  public function maybe_install_or_upgrade_db() {
    // Run a lightweight existence + schema check; only dbDelta if needed.
    global $wpdb;

    $orders  = $this->table_orders();
    $links   = $this->table_links();
    $access  = $this->table_sheet_music_access();
    $payouts = $this->table_payout_ledger();
    $credits = $this->table_lesson_credits();
    $autopay = $this->table_autopay_profiles();
    $webhooks = $this->table_webhook_events();
    $subs = $this->table_sheet_music_subscriptions();
    $promo_redemptions = $this->table_promo_redemptions();
    $profile_requests = $this->table_profile_card_requests();
    $tax_states = $this->table_tax_state_status();
    $tax_sales  = $this->table_tax_sales_ledger();
    $tax_alerts = $this->table_tax_alerts();

    $needs_upgrade = false;

    if (
      (string) get_option('mrm_tax_schema_version', '') !==
      (string) self::TAX_SCHEMA_VERSION
    ) {
      $needs_upgrade = true;
    }

    // 1) Table existence check
    foreach (array($orders, $links, $access, $payouts, $credits, $autopay, $webhooks, $subs, $promo_redemptions, $profile_requests, $tax_states, $tax_sales, $tax_alerts) as $t) {
      $found = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $t));
      if ($found !== $t) {
        $needs_upgrade = true;
        break;
      }
    }

    // 2) Access-table schema check (important after plugin updates)
    if (!$needs_upgrade) {
      $required_access_columns = array(
        'email_hash',
        'email_plain',
        'sku',
        'start_at',
        'expires_at',
        'month_key',
        'granted_at',
        'revoked_at',
        'source',
        'source_id',
      );

      $existing_cols = array();
      $cols = $wpdb->get_results("SHOW COLUMNS FROM {$access}");
      if (is_array($cols)) {
        foreach ($cols as $c) {
          if (!empty($c->Field)) {
            $existing_cols[] = (string)$c->Field;
          }
        }
      }

      foreach ($required_access_columns as $col) {
        if (!in_array($col, $existing_cols, true)) {
          $needs_upgrade = true;
          break;
        }
      }
    }

    if (!$needs_upgrade) {
      $required_autopay_columns = array(
        'plan_kind',
        'authorized_lesson_count',
        'charged_lesson_count',
        'detached_at',
      );

      $existing_autopay_cols = array();
      $cols = $wpdb->get_results("SHOW COLUMNS FROM {$autopay}");
      if (is_array($cols)) {
        foreach ($cols as $c) {
          if (!empty($c->Field)) {
            $existing_autopay_cols[] = (string)$c->Field;
          }
        }
      }

      foreach ($required_autopay_columns as $col) {
        if (!in_array($col, $existing_autopay_cols, true)) {
          $needs_upgrade = true;
          break;
        }
      }
    }

    if (!$needs_upgrade) {
      $required_subscription_columns = array(
        'tax_attention_status',
        'tax_attention_reason',
        'tax_attention_since',
        'tax_attention_notified_at',
        'collection_paused_for_tax',
      );

      $existing_subscription_columns = array();
      $subscription_columns = $wpdb->get_results("SHOW COLUMNS FROM {$subs}");

      if (is_array($subscription_columns)) {
        foreach ($subscription_columns as $column) {
          if (!empty($column->Field)) {
            $existing_subscription_columns[] = (string)$column->Field;
          }
        }
      }

      foreach ($required_subscription_columns as $required_column) {
        if (!in_array($required_column, $existing_subscription_columns, true)) {
          $needs_upgrade = true;
          break;
        }
      }
    }

    // 4) Promo redemption schema check
    if (!$needs_upgrade) {
      $promo_cols = $wpdb->get_results("SHOW COLUMNS FROM {$promo_redemptions}");
      $promo_col_names = array();

      if (is_array($promo_cols)) {
        foreach ($promo_cols as $col) {
          if (!empty($col->Field)) {
            $promo_col_names[] = (string)$col->Field;
          }
        }
      }

      foreach (array('customer_email') as $required_col) {
        if (!in_array($required_col, $promo_col_names, true)) {
          $needs_upgrade = true;
          break;
        }
      }
    }

    if ($needs_upgrade) {
      $this->install_or_upgrade_db();
    }

    $this->mrm_tax_normalize_legacy_profile_requests();

    $this->mrm_tax_seed_state_rows();

    // ✅ One-time migration: move old master SKU rows to all-sheet-music
    $table = $this->table_sheet_music_access();
    $found = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
    if ($found === $table) {
      $wpdb->query(
        "UPDATE {$table}
         SET sku = 'all-sheet-music'
         WHERE sku = 'piece-all-sheet-music-access-complete-package'"
      );
    }

    /*
     * Per-piece access now comes only from the visible database ledger.
     * Remove the old option-based email lists once so stale testing data
     * cannot grant ownership or public downloads invisibly.
     */
    if (get_option(self::OPT_LEGACY_ACCESS_LISTS_REMOVED, '') !== 'yes') {
      delete_option(self::OPT_ACCESS_LISTS);
      update_option(self::OPT_LEGACY_ACCESS_LISTS_REMOVED, 'yes', false);
    }

    $this->mrm_ensure_payout_ledger_status_column_width();
    $this->mrm_ensure_subscription_portal_tokens();

    $unsubscribe_route_version = '1.1';
    $saved_unsubscribe_route_version = get_option(
      'mrm_pay_hub_unsubscribe_route_version',
      ''
    );

    if ($saved_unsubscribe_route_version !== $unsubscribe_route_version) {
      $this->register_marketing_unsubscribe_endpoint();
      flush_rewrite_rules(false);

      update_option(
        'mrm_pay_hub_unsubscribe_route_version',
        $unsubscribe_route_version,
        false
      );
    }
  }

