    // Promo codes may be reusable per email, so the old unique index must be removed.
    // dbDelta() does not reliably remove old indexes, so do it explicitly.
    $promo_unique_exists = $wpdb->get_var($wpdb->prepare(
      "SELECT COUNT(1)
       FROM information_schema.statistics
       WHERE table_schema = DATABASE()
         AND table_name = %s
         AND index_name = 'promo_email_unique'",
      $promo_redemptions
    ));

    if ((int)$promo_unique_exists > 0) {
      $wpdb->query("ALTER TABLE {$promo_redemptions} DROP INDEX promo_email_unique");
    }

    $promo_lookup_exists = $wpdb->get_var($wpdb->prepare(
      "SELECT COUNT(1)
       FROM information_schema.statistics
       WHERE table_schema = DATABASE()
         AND table_name = %s
         AND index_name = 'promo_email_lookup'",
      $promo_redemptions
    ));

    if ((int)$promo_lookup_exists <= 0) {
      $wpdb->query("ALTER TABLE {$promo_redemptions} ADD KEY promo_email_lookup (promo_code, email_hash)");
    }

    $autopay_columns = $wpdb->get_results("SHOW COLUMNS FROM {$autopay}", ARRAY_A);
    $autopay_column_names = array();

    if (is_array($autopay_columns)) {
      foreach ($autopay_columns as $col) {
        if (!empty($col['Field'])) {
          $autopay_column_names[] = (string)$col['Field'];
        }
      }
    }

    if (!in_array('promo_code', $autopay_column_names, true)) {
      $wpdb->query("ALTER TABLE {$autopay} ADD promo_code VARCHAR(80) DEFAULT NULL AFTER charged_lesson_count");
    }

    if (!in_array('promo_started_at', $autopay_column_names, true)) {
      $wpdb->query("ALTER TABLE {$autopay} ADD promo_started_at DATETIME DEFAULT NULL AFTER promo_code");
    }
    $this->mrm_tax_run_schema_migrations();
    $this->mrm_tax_seed_state_rows();
  }

  private function mrm_tax_require_innodb_table(
    $table,
    &$errors
  ) {
    global $wpdb;

    $table = str_replace('`', '', (string)$table);

    if ($table === '') {
      $errors[] = 'An empty table name was supplied for the InnoDB migration.';
      return false;
    }

    $wpdb->last_error = '';
    $engine = $wpdb->get_var($wpdb->prepare("SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s LIMIT 1", $table));

    if ($wpdb->last_error !== '') {
      $errors[] = 'Unable to inspect the storage engine for ' . $table . ': ' . $wpdb->last_error;
      return false;
    }

    if ($engine === null) {
      $errors[] = 'The required table ' . $table . ' does not exist.';
      return false;
    }

    if (strtoupper((string)$engine) === 'INNODB') return true;

    $wpdb->last_error = '';
    $converted = $wpdb->query("ALTER TABLE `{$table}` ENGINE=InnoDB");

    if ($converted === false || $wpdb->last_error !== '') {
      $errors[] = 'Unable to convert ' . $table . ' to InnoDB: ' . ($wpdb->last_error ?: 'Unknown database error.');
      return false;
    }

    $wpdb->last_error = '';
    $verified_engine = $wpdb->get_var($wpdb->prepare("SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s LIMIT 1", $table));

    if ($wpdb->last_error !== '' || strtoupper((string)$verified_engine) !== 'INNODB') {
      $errors[] = 'The InnoDB conversion could not be verified for ' . $table . '.';
      return false;
    }

    return true;
  }

  private function mrm_tax_required_tables_innodb_readiness() {
    global $wpdb;
    $tables = array($this->table_tax_state_status(), $this->table_tax_sales_ledger(), $this->table_tax_alerts(), $this->table_sheet_music_subscriptions());
    $placeholders = implode(',', array_fill(0, count($tables), '%s'));
    $wpdb->last_error = '';
    $rows = $wpdb->get_results($wpdb->prepare("SELECT TABLE_NAME, ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ({$placeholders})", $tables), ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('tax_table_engine_query_failed', 'The required database storage engines could not be inspected: ' . $wpdb->last_error);
    $engines = array();
    foreach ((array)$rows as $row) $engines[(string)($row['TABLE_NAME'] ?? '')] = strtoupper((string)($row['ENGINE'] ?? ''));
    foreach ($tables as $table) {
      if (!isset($engines[$table]) || $engines[$table] !== 'INNODB') return new WP_Error('tax_table_not_innodb', 'The required table ' . $table . ' is not using InnoDB.');
    }
    return true;
  }

  private function mrm_tax_add_column_if_missing($table, $column, $definition, &$errors) {
    global $wpdb;
    $exists = $wpdb->get_var($wpdb->prepare("SHOW COLUMNS FROM {$table} LIKE %s", $column));
    if ($exists) return true;
    $wpdb->last_error = '';
    $result = $wpdb->query("ALTER TABLE {$table} ADD COLUMN {$column} {$definition}");
    if ($result === false || $wpdb->last_error !== '') {
      $errors[] = 'Unable to add ' . $table . '.' . $column . ': ' . $wpdb->last_error;
      return false;
    }
    $verified = $wpdb->get_var($wpdb->prepare("SHOW COLUMNS FROM {$table} LIKE %s", $column));
    if (!$verified) {
      $errors[] = 'Column verification failed for ' . $table . '.' . $column . '.';
      return false;
    }
    return true;
  }

  private function mrm_tax_add_index_if_missing($table, $index_name, $definition, &$errors) {
    global $wpdb;
    $table = str_replace('`', '', (string) $table);
    $index_name = sanitize_key($index_name);
    $definition = trim((string) $definition);
    if ($table === '' || $index_name === '' || $definition === '') {
      $errors[] = 'An invalid tax index migration was supplied.';
      return false;
    }
    $wpdb->last_error = '';
    $existing = $wpdb->get_var($wpdb->prepare(
      "SELECT INDEX_NAME FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = %s AND index_name = %s LIMIT 1",
      $table,
      $index_name
    ));
    if ($wpdb->last_error !== '') {
      $errors[] = 'Unable to inspect index ' . $index_name . ' on ' . $table . ': ' . $wpdb->last_error;
      return false;
    }
    if ((string) $existing === $index_name) return true;
    $wpdb->last_error = '';
    $result = $wpdb->query("ALTER TABLE `{$table}` ADD KEY `{$index_name}` {$definition}");
    if ($result === false || $wpdb->last_error !== '') {
      $errors[] = 'Unable to add index ' . $index_name . ' to ' . $table . ': ' . ($wpdb->last_error ?: 'Unknown database error.');
      return false;
    }
    $verified = $wpdb->get_var($wpdb->prepare(
      "SELECT INDEX_NAME FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = %s AND index_name = %s LIMIT 1",
      $table,
      $index_name
    ));
    if ((string) $verified !== $index_name) {
      $errors[] = 'Index verification failed for ' . $table . '.' . $index_name . '.';
      return false;
    }
    return true;
  }

  private function mrm_tax_run_schema_migrations() {
    global $wpdb;
    if (get_option('mrm_tax_schema_version') === self::TAX_SCHEMA_VERSION) return true;
    $state_table = $this->table_tax_state_status();
    $sales_table = $this->table_tax_sales_ledger();
    $alerts_table = $this->table_tax_alerts();
    $subscriptions_table = $this->table_sheet_music_subscriptions();
    $errors = array();
    $wpdb->last_error = '';
    $modified = $wpdb->query("ALTER TABLE {$state_table} MODIFY threshold_operator VARCHAR(32) NOT NULL DEFAULT 'amount'");
    if ($modified === false || $wpdb->last_error !== '') $errors[] = 'Unable to update threshold_operator: ' . $wpdb->last_error;
    $this->mrm_tax_add_column_if_missing($state_table, 'written_determination_reviewed_at', 'DATE NULL', $errors);
    $this->mrm_tax_add_column_if_missing($state_table, 'written_determination_reference', 'TEXT NULL', $errors);
    $this->mrm_tax_add_column_if_missing($state_table, 'rule_professionally_reviewed_at', 'DATE NULL', $errors);
    $this->mrm_tax_add_column_if_missing($state_table, 'rule_professional_reference', 'TEXT NULL', $errors);
    $this->mrm_tax_add_column_if_missing($sales_table, 'stripe_tax_line_item_id', 'VARCHAR(191) NULL', $errors);
    $this->mrm_tax_add_column_if_missing($sales_table, 'tax_reversals_json', 'LONGTEXT NULL', $errors);
    $this->mrm_tax_add_column_if_missing($sales_table, 'calculation_line_items_json', 'LONGTEXT NULL', $errors);
    $this->mrm_tax_add_column_if_missing($sales_table, 'last_association_sync_at', 'DATETIME NULL', $errors);
    $this->mrm_tax_add_column_if_missing($sales_table, 'association_error', 'TEXT NULL', $errors);
    $this->mrm_tax_add_column_if_missing($subscriptions_table, 'tax_held_invoices_json', 'LONGTEXT NULL', $errors);
    $this->mrm_tax_add_column_if_missing($subscriptions_table, 'tax_held_invoices_verified_at', 'DATETIME NULL', $errors);
    $this->mrm_tax_add_column_if_missing($alerts_table, 'alert_revision', 'BIGINT UNSIGNED NOT NULL DEFAULT 1', $errors);
    $wpdb->last_error = '';
    $alert_revision_backfill = $wpdb->query(
      "UPDATE {$alerts_table}
       SET alert_revision = 1
       WHERE alert_revision IS NULL
          OR alert_revision < 1"
    );
    if ($alert_revision_backfill === false || $wpdb->last_error !== '') {
      $errors[] = 'Unable to backfill tax-alert revisions: ' . $wpdb->last_error;
    }
    $this->mrm_tax_add_column_if_missing($alerts_table, 'email_status', "VARCHAR(24) NOT NULL DEFAULT 'not_sent'", $errors);
    $this->mrm_tax_add_column_if_missing($alerts_table, 'email_claim_token', 'VARCHAR(64) NULL', $errors);
    $this->mrm_tax_add_column_if_missing($alerts_table, 'email_claimed_at', 'DATETIME NULL', $errors);
    $this->mrm_tax_add_column_if_missing($alerts_table, 'email_last_attempt_at', 'DATETIME NULL', $errors);
    $this->mrm_tax_add_column_if_missing($alerts_table, 'email_last_error', 'TEXT NULL', $errors);
    $this->mrm_tax_add_index_if_missing($alerts_table, 'email_status', '(email_status)', $errors);
    $wpdb->last_error = '';
    $email_status_backfill = $wpdb->query(
      "UPDATE {$alerts_table}
       SET email_status = CASE WHEN emailed_at IS NOT NULL THEN 'sent' ELSE 'not_sent' END
       WHERE email_status = 'not_sent'"
    );
    if ($email_status_backfill === false || $wpdb->last_error !== '') {
      $errors[] = 'Unable to backfill tax-alert email states: ' . $wpdb->last_error;
    }
    $workflow_columns = array(
      'authority_registration_submitted_at' => 'DATETIME NULL',
      'authority_registration_application_reference' => 'VARCHAR(191) NULL',
      'physical_activity_started_at' => 'DATETIME NULL',
      'stripe_collection_started_at' => 'DATETIME NULL',
      'pending_tax_tracking_started_at' => 'DATETIME NULL',
      'pending_tax_tracking_ended_at' => 'DATETIME NULL',
      'foreign_registration_status' => "VARCHAR(32) NOT NULL DEFAULT 'not_started'",
      'foreign_registration_grace_days' => 'SMALLINT UNSIGNED NULL',
      'foreign_registration_internal_due_date' => 'DATE NULL',
      'foreign_registration_outside_due_date' => 'DATE NULL',
      'registered_agent_status' => "VARCHAR(32) NOT NULL DEFAULT 'not_started'",
      'registered_agent_reference' => 'TEXT NULL',
      'foreign_registration_submitted_at' => 'DATETIME NULL',
      'foreign_registration_accepted_at' => 'DATETIME NULL',
      'foreign_registration_reference' => 'TEXT NULL',
      'pending_tax_reserve_rate_bps' => 'SMALLINT UNSIGNED NULL',
      'pending_tax_reconciled_at' => 'DATETIME NULL',
      'workflow_audit_json' => 'LONGTEXT NULL',
    );
    foreach ($workflow_columns as $column => $definition) {
      $this->mrm_tax_add_column_if_missing($state_table, $column, $definition, $errors);
    }
    $this->mrm_tax_add_column_if_missing($state_table, 'filing_status', "VARCHAR(32) NOT NULL DEFAULT 'not_configured'", $errors);
    $this->mrm_tax_add_column_if_missing($state_table, 'filing_frequency', 'VARCHAR(32) NULL', $errors);
    $this->mrm_tax_add_column_if_missing($state_table, 'next_return_due_date', 'DATE NULL', $errors);
    $this->mrm_tax_add_column_if_missing($state_table, 'last_return_filed_at', 'DATE NULL', $errors);
    $this->mrm_tax_add_column_if_missing($state_table, 'last_return_confirmation', 'TEXT NULL', $errors);
    $this->mrm_tax_add_column_if_missing($state_table, 'rule_management_mode', "VARCHAR(20) NOT NULL DEFAULT 'catalog'", $errors);
    $this->mrm_tax_add_column_if_missing($sales_table, 'retail_sales_cents', 'BIGINT NOT NULL DEFAULT 0', $errors);
    $wpdb->last_error = '';
    $backfilled = $wpdb->query("UPDATE {$sales_table} SET retail_sales_cents = gross_sales_cents WHERE retail_sales_cents = 0 AND gross_sales_cents > 0");
    if ($backfilled === false || $wpdb->last_error !== '') $errors[] = 'Unable to backfill retail sales: ' . $wpdb->last_error;
    $operator_column = $wpdb->get_row($wpdb->prepare("SHOW COLUMNS FROM {$state_table} LIKE %s", 'threshold_operator'), ARRAY_A);
    if (!is_array($operator_column) || strtolower((string)($operator_column['Type'] ?? '')) !== 'varchar(32)') $errors[] = 'threshold_operator was not verified as VARCHAR(32).';
    $wpdb->last_error = '';
    $catalog_verification_reset = $wpdb->query("UPDATE {$state_table} SET threshold_rule_verified = 0, rule_professionally_reviewed_at = NULL, rule_professional_reference = NULL WHERE rule_management_mode = 'catalog'");
    if ($catalog_verification_reset === false || $wpdb->last_error !== '') $errors[] = 'Unable to reset automatically verified catalog rules: ' . $wpdb->last_error;
    $this->mrm_tax_add_index_if_missing($state_table, 'authority_registration_status', '(authority_registration_status)', $errors);
    $this->mrm_tax_add_index_if_missing($state_table, 'foreign_registration_status', '(foreign_registration_status)', $errors);
    $this->mrm_tax_add_index_if_missing($state_table, 'foreign_registration_outside_due_date', '(foreign_registration_outside_due_date)', $errors);
    $this->mrm_tax_add_index_if_missing($sales_table, 'pending_state_period_category', '(customer_state, occurred_at, threshold_category)', $errors);
    $this->mrm_tax_require_innodb_table($state_table, $errors);
    $this->mrm_tax_require_innodb_table($sales_table, $errors);
    $this->mrm_tax_require_innodb_table($alerts_table, $errors);
    $this->mrm_tax_require_innodb_table($subscriptions_table, $errors);
    if (!empty($errors)) {
      update_option('mrm_tax_schema_migration_error', implode("\n", $errors), false);
      error_log('MRM tax schema migration failed: ' . implode(' | ', $errors));
      return false;
    }
    delete_option('mrm_tax_schema_migration_error');
    update_option('mrm_tax_schema_version', self::TAX_SCHEMA_VERSION, false);
    return true;
  }

  private function mrm_tax_get_state_row($state) {
    global $wpdb;
    $state = $this->mrm_normalize_state_code($state);
    if ($state === '') return new WP_Error('invalid_tax_state', 'The state code is missing or invalid.');
    $wpdb->last_error = '';
    $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table_tax_state_status()} WHERE state_code = %s LIMIT 1", $state), ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('tax_state_lookup_failed', $wpdb->last_error);
    if (!is_array($row)) return new WP_Error('tax_state_missing', $state . ' is missing from the state tax registry.');
    return $row;
  }

  private function mrm_tax_authority_registration_statuses() { return array('not_started','application_submitted','additional_information_requested','approved','active','denied','not_required_written_determination'); }
  private function mrm_tax_foreign_registration_statuses() { return array('not_started','registered_agent_pending','preparing','submitted','correction_required','active','not_required_written_determination','overdue'); }
  private function mrm_tax_registered_agent_statuses() { return array('not_started','researching','engagement_pending','engaged','active','not_required'); }
  private function mrm_tax_filing_statuses() { return array('not_configured','provider_managed','manual_managed','filing_attention_required'); }

  private function mrm_tax_parse_admin_date($value, $label) {
    $value = trim(sanitize_text_field((string) $value));
    if ($value === '') return '';
    $date = DateTimeImmutable::createFromFormat('!Y-m-d', $value, wp_timezone());
    $errors = DateTimeImmutable::getLastErrors();
    if (!$date || (is_array($errors) && (!empty($errors['warning_count']) || !empty($errors['error_count']))) || $date->format('Y-m-d') !== $value) return new WP_Error('invalid_tax_date', $label . ' must use YYYY-MM-DD.');
    return $date->format('Y-m-d');
  }

  private function mrm_tax_parse_admin_datetime($value, $label) {
    $value = trim(sanitize_text_field((string) $value));
    if ($value === '') return '';
    foreach (array('Y-m-d\TH:i','Y-m-d H:i:s') as $format) {
      $date = DateTimeImmutable::createFromFormat('!' . $format, $value, wp_timezone());
      $errors = DateTimeImmutable::getLastErrors();
      if ($date && (!is_array($errors) || (empty($errors['warning_count']) && empty($errors['error_count'])))) return $date->format('Y-m-d H:i:s');
    }
    return new WP_Error('invalid_tax_datetime', $label . ' contains an invalid date or time.');
  }

  private function mrm_tax_parse_admin_nonnegative_integer($value, $label, $maximum) {
    $value=trim(sanitize_text_field(wp_unslash((string)$value)));
    if($value==='') return null;
    if(!preg_match('/^\d+$/',$value)) return new WP_Error('invalid_nonnegative_integer',$label.' must be a whole number of zero or greater.');
    $number=(int)$value;
    if($number>(int)$maximum) return new WP_Error('integer_above_maximum',$label.' cannot be greater than '.number_format_i18n($maximum).'.');
    return $number;
  }

  private function mrm_tax_wp_local_mysql_to_utc_mysql($value) {
    $value = trim((string) $value); if ($value === '') return '';
    try { return (new DateTimeImmutable($value, wp_timezone()))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'); } catch (Throwable $error) { return ''; }
  }

  private function mrm_tax_append_workflow_audit($existing_json, $event) {
    $audit = json_decode((string) $existing_json, true); if (!is_array($audit)) $audit = array();
    $event = is_array($event) ? $event : array();
    if (empty($event['recorded_at'])) $event['recorded_at'] = current_time('mysql');
    if (!array_key_exists('administrator_id', $event)) $event['administrator_id'] = get_current_user_id();
    $audit[] = $event; return wp_json_encode($audit);
  }

  private function mrm_tax_profile_approval_eligibility(
    $state,
    $allow_stripe_basis = true
  ) {
    $row = $this->mrm_tax_get_state_row($state);
    if (is_wp_error($row)) return array('allowed'=>false,'state'=>$this->mrm_normalize_state_code($state),'approval_basis'=>'none','message'=>$row->get_error_message());
    $state = $this->mrm_normalize_state_code($row['state_code'] ?? '');
    if (sanitize_key($row['general_sales_tax_status'] ?? '') === 'no_general_state_sales_tax') return array('allowed'=>true,'state'=>$state,'row'=>$row,'approval_basis'=>'no_general_state_sales_tax','message'=>$state . ' does not impose a general state sales tax.');
    if ($this->mrm_tax_row_has_written_clearance($row)) return array('allowed'=>true,'state'=>$state,'row'=>$row,'approval_basis'=>'written_determination','message'=>'A valid written determination is recorded.');
    $stripe_active = sanitize_key($row['stripe_registration_status'] ?? '') === 'active' && !empty($row['collection_active']);
    if ($this->mrm_tax_is_live_stripe_key() && empty($row['stripe_livemode'])) $stripe_active = false;
    if ($allow_stripe_basis && $stripe_active) {
      return array(
        'allowed' => true,
        'state' => $state,
        'row' => $row,
        'approval_basis' => 'stripe_collection_active',
        'message' => 'Stripe Tax collection is active.',
      );
    }
    $status = sanitize_key($row['authority_registration_status'] ?? '');
    $submitted = sanitize_text_field($row['authority_registration_submitted_at'] ?? '');
    $reference = sanitize_text_field($row['authority_registration_application_reference'] ?? '');
    $valid_date = false;
    if ($submitted !== '') try { $valid_date = new DateTimeImmutable($submitted, wp_timezone()) <= new DateTimeImmutable('now', wp_timezone()); } catch (Throwable $error) { $valid_date = false; }
    if (in_array($status,array('application_submitted','approved','active'),true) && $valid_date && $reference !== '') return array('allowed'=>true,'state'=>$state,'row'=>$row,'approval_basis'=>'permit_application_submitted','authority_registration_submitted_at'=>$submitted,'authority_registration_application_reference'=>$reference,'message'=>'The state permit application has been documented.');
    return array('allowed'=>false,'state'=>$state,'row'=>$row,'approval_basis'=>'none','message'=>'Approval requires active Stripe collection, a no-general-sales-tax state, a valid written determination, or a documented permit application submission date and reference.');
  }

  private function mrm_tax_state_pending_registration_window_is_valid($row) {
    if (!is_array($row)) return false;
    if (sanitize_key($row['general_sales_tax_status'] ?? '') === 'no_general_state_sales_tax' || $this->mrm_tax_row_has_written_clearance($row)) return true;
    if (!in_array(sanitize_key($row['authority_registration_status'] ?? ''),array('application_submitted','approved','active'),true)) return false;
    if (empty($row['authority_registration_submitted_at']) || empty($row['authority_registration_application_reference']) || empty($row['physical_activity_started_at'])) return false;
    try { if (new DateTimeImmutable($row['authority_registration_submitted_at'], wp_timezone()) > new DateTimeImmutable('now', wp_timezone())) return false; } catch (Throwable $error) { return false; }
    if (in_array(sanitize_key($row['foreign_registration_status'] ?? ''),array('overdue','correction_required'),true)) return false;
    $outside_due = sanitize_text_field($row['foreign_registration_outside_due_date'] ?? '');
    if ($outside_due !== '') try { if (new DateTimeImmutable('now', wp_timezone()) > new DateTimeImmutable($outside_due . ' 23:59:59', wp_timezone())) return false; } catch (Throwable $error) { return false; }
    return true;
  }

  private function mrm_tax_normalize_legacy_profile_requests() {
    global $wpdb;
    $migration_option = 'mrm_tax_profile_request_status_migration_v1';
    if (get_option($migration_option) === 'complete') return true;
    $table = $this->table_profile_card_requests();
    $wpdb->last_error = '';
    $requests = $wpdb->get_results("SELECT id, request_type, status, submission_payload, review_notes FROM {$table} WHERE status = 'tax_registration_required' AND request_type IN ('instructor_profile','presenter_profile') ORDER BY id ASC", ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('legacy_profile_request_lookup_failed', $wpdb->last_error);
    foreach ((array) $requests as $request) {
      $request_id = absint($request['id'] ?? 0); if ($request_id <= 0) continue;
      $payload = $this->mrm_profile_card_decode_json($request['submission_payload'] ?? '');
      $notes = $this->mrm_profile_card_decode_json($request['review_notes'] ?? '');
      $notes['legacy_tax_registration_status'] = array('original_status'=>'tax_registration_required','normalized_status'=>'pending_review','normalized_at'=>current_time('mysql'),'normalized_by_user_id'=>0,'state'=>$this->mrm_normalize_state_code($payload['state'] ?? ''),'original_tax_gate'=>$notes['tax_registration_gate'] ?? null);
      $wpdb->last_error = '';
      $updated = $wpdb->update($table,array('status'=>'pending_review','review_notes'=>$this->mrm_profile_card_encode_json($notes),'updated_at'=>current_time('mysql')),array('id'=>$request_id));
      if ($updated === false || $wpdb->last_error !== '') return new WP_Error('legacy_profile_request_update_failed',$wpdb->last_error ?: 'A legacy profile request could not be normalized.');
      $verified = $wpdb->get_row($wpdb->prepare("SELECT status, review_notes FROM {$table} WHERE id = %d LIMIT 1",$request_id),ARRAY_A);
      if (!is_array($verified) || sanitize_key($verified['status'] ?? '') !== 'pending_review') return new WP_Error('legacy_profile_request_verification_failed','Legacy request #' . $request_id . ' could not be verified.');
    }
    update_option($migration_option, 'complete', false);
    return true;
  }


  /* =========================================================
   * Ledger helpers (WP timezone safe)
   * ======================================================= */

  private function mrm_wp_tz() {
    if (function_exists('wp_timezone')) return wp_timezone();
    $tz = get_option('timezone_string');
    if ($tz) return new DateTimeZone($tz);
    $offset = (float) get_option('gmt_offset', 0);
    $hours = (int) $offset;
    $mins = (int) round(abs($offset - $hours) * 60);
    $sign = ($offset < 0) ? '-' : '+';
    return new DateTimeZone(sprintf('%s%02d:%02d', $sign, abs($hours), $mins));
  }

  private function mrm_lesson_normalize_timezone($timezone, $fallback = 'America/Phoenix') {
    $candidates = array(trim((string)$timezone), trim((string)$fallback), 'UTC');
    foreach ($candidates as $candidate) {
      if ($candidate === '') continue;
      try {
        new DateTimeZone($candidate);
        return $candidate;
      } catch (Exception $e) {
        continue;
      }
    }
    return 'UTC';
  }

  private function mrm_lesson_utc_timestamp($value) {
    $value = trim((string)$value);
    if ($value === '') return 0;
    try {
      if (preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/', $value)) {
        $datetime = DateTimeImmutable::createFromFormat('!Y-m-d H:i:s', $value, new DateTimeZone('UTC'));
        return $datetime instanceof DateTimeImmutable ? $datetime->getTimestamp() : 0;
      }
      return (new DateTimeImmutable($value, new DateTimeZone('UTC')))->getTimestamp();
    } catch (Exception $e) {
      return 0;
    }
  }

  private function mrm_lesson_time_label($utc_value, $timezone, $fallback = 'America/Phoenix', $format = 'F j, Y \a\t g:i A T') {
    $timestamp = $this->mrm_lesson_utc_timestamp($utc_value);
    if ($timestamp <= 0) return '';
    $timezone = $this->mrm_lesson_normalize_timezone($timezone, $fallback);
    try {
      return (new DateTimeImmutable('@' . $timestamp))->setTimezone(new DateTimeZone($timezone))->format($format);
    } catch (Exception $e) {
      return gmdate($format, $timestamp);
    }
  }

  private function mrm_month_key_from_ts($ts) {
    $ts = (int)$ts;
    if (function_exists('wp_date')) return wp_date('Y-m', $ts, $this->mrm_wp_tz());
    $dt = new DateTime('@' . $ts);
    $dt->setTimezone($this->mrm_wp_tz());
    return $dt->format('Y-m');
  }

  private function mrm_mysql_from_ts($ts) {
    $dt = new DateTime('@' . (int)$ts);
    $dt->setTimezone($this->mrm_wp_tz());
    return $dt->format('Y-m-d H:i:s');
  }

  private function mrm_now_mysql() {
    return current_time('mysql');
  }

  public function mrm_master_all_sheet_music_sku() {
    // ✅ No override. Master SKU is fixed.
    return 'all-sheet-music';
  }

  private function master_sheet_music_sku() {
    return $this->mrm_master_all_sheet_music_sku();
  }

  public function mrm_is_all_sheet_music_active_for_month($email, $month_key) {
    $email = sanitize_email((string)$email);
    if (!$email || !is_email($email)) return false;

    global $wpdb;
    $table = $this->table_sheet_music_access();
    $found = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
    if ($found !== $table) return false;

    $email_hash = $this->email_hash($email);
    $master_sku = $this->mrm_master_all_sheet_music_sku();
    $now = $this->mrm_now_mysql();

    $id = $wpdb->get_var($wpdb->prepare(
      "SELECT id FROM {$table}
       WHERE email_hash=%s AND sku=%s AND month_key=%s AND revoked_at IS NULL
         AND (
           (expires_at IS NOT NULL AND expires_at > %s)
           OR
           (expires_at IS NULL AND DATE_ADD(granted_at, INTERVAL 31 DAY) > %s)
         )
       ORDER BY id DESC LIMIT 1",
      $email_hash, $master_sku, $month_key, $now, $now
    ));
    return !empty($id);
  }

  public function mrm_grant_all_sheet_music_ledger($email, $start_ts, $source = null, $source_id = null) {
    $email = sanitize_email((string)$email);
    if (!$email || !is_email($email)) return false;

    $start_ts = (int)$start_ts;
    if ($start_ts <= 0) $start_ts = time();

    $month_key = $this->mrm_month_key_from_ts($start_ts);
    if ($this->mrm_is_all_sheet_music_active_for_month($email, $month_key)) {
      return true;
    }

    global $wpdb;
    $table = $this->table_sheet_music_access();
    $found = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
    if ($found !== $table) return false;

    $email_hash = $this->email_hash($email);
    $master_sku = $this->mrm_master_all_sheet_music_sku();

    $start_mysql = $this->mrm_mysql_from_ts($start_ts);
    $now = $this->mrm_now_mysql();

    $ok = $wpdb->insert($table, array(
      'email_hash'  => $email_hash,
      'email_plain' => $email,
      'sku'         => $master_sku,
      'start_at'    => $start_mysql,
      'expires_at'  => null,
      'month_key'   => $month_key,
      'granted_at'  => $now,
      'revoked_at'  => null,
      'source'      => $source,
      'source_id'   => $source_id,
    ), array('%s','%s','%s','%s','%s','%s','%s','%s','%s','%s'));

    return (bool)$ok;
  }

  public function mrm_prune_expired_all_sheet_music() {
    global $wpdb;
    $table = $this->table_sheet_music_access();
    $found = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
    if ($found !== $table) return;

    $master_sku = $this->mrm_master_all_sheet_music_sku();
    $now = $this->mrm_now_mysql();

    $wpdb->query($wpdb->prepare(
      "UPDATE {$table}
       SET revoked_at=%s
       WHERE sku=%s AND revoked_at IS NULL
         AND (
           (expires_at IS NOT NULL AND expires_at <= %s)
           OR
           (expires_at IS NULL AND DATE_ADD(granted_at, INTERVAL 31 DAY) <= %s)
         )",
      $now, $master_sku, $now, $now
    ));
  }

  /* =========================================================
   * Settings / Products
   * ======================================================= */

  private function mrm_get_promo_codes() {
  $codes = get_option(self::OPT_PROMO_CODES, array());
  return is_array($codes) ? $codes : array();
}

private function mrm_save_promo_codes($codes) {
  update_option(self::OPT_PROMO_CODES, is_array($codes) ? $codes : array(), false);
}

private function mrm_normalize_promo_code($code) {
  $code = strtoupper(trim((string)$code));
  $code = preg_replace('/[^A-Z0-9\-_]/', '', $code);
  return substr($code, 0, 80);
}

private function mrm_normalize_promo_target($target) {
  $target = strtolower(trim((string)$target));
  $target = preg_replace('/[^a-z0-9:_,-]/', '', $target);
  return substr($target, 0, 190);
}

private function mrm_promo_target_from_legacy($promo) {
  $promo = is_array($promo) ? $promo : array();
  $target = $this->mrm_normalize_promo_target($promo['promo_target'] ?? '');
  if ($target !== '') return $target;

  $scopes = array();
  if (!empty($promo['scopes']) && is_array($promo['scopes'])) {
    foreach ($promo['scopes'] as $scope) {
      $scope = sanitize_key((string)$scope);
      if (in_array($scope, array('lesson', 'sheet_music', 'masterclass'), true)) $scopes[] = $scope;
    }
  }
  if (empty($scopes)) {
    $legacy_scope = strtolower(trim((string)($promo['scope'] ?? 'all')));
    if ($legacy_scope === 'all') {
      $scopes = array('lesson', 'sheet_music', 'masterclass');
    } else {
      foreach (explode(',', $legacy_scope) as $scope) {
        $scope = sanitize_key($scope);
        if (in_array($scope, array('lesson', 'sheet_music', 'masterclass'), true)) $scopes[] = $scope;
      }
    }
  }
  $scopes = array_values(array_unique($scopes));
  if (count($scopes) === 3) return 'all';
  if (count($scopes) === 1) return $scopes[0] . ':all';
  if (!empty($scopes)) return 'legacy:' . implode(',', $scopes);
  return 'all';
}

private function mrm_promo_scope_values_for_target($target) {
  $target = $this->mrm_normalize_promo_target($target);
  if ($target === 'all') return array('lesson', 'sheet_music', 'masterclass');
  foreach (array('lesson', 'sheet_music', 'masterclass') as $scope) {
    if (strpos($target, $scope . ':') === 0) return array($scope);
  }
  if (strpos($target, 'legacy:') === 0) {
    $scopes = array();
    foreach (explode(',', substr($target, 7)) as $scope) {
      $scope = sanitize_key($scope);
      if (in_array($scope, array('lesson', 'sheet_music', 'masterclass'), true)) $scopes[] = $scope;
    }
    return array_values(array_unique($scopes));
  }
  return array();
}

private function mrm_promo_piece_display_label($piece_stem, $product_label = '') {
  $piece_stem = $this->sanitize_sku($piece_stem);
  $label = sanitize_text_field((string)$product_label);
  if ($label !== '') {
    $cleaned = preg_replace(
      '/\s*(?:-|–|—|:)?\s*(?:fundamental packet|fundamentals?|trombone\s*\/\s*euphonium|trombone-euphonium|tuba|complete package|complete-package|full piece|full-piece|bundle)\s*$/iu',
      '',
      $label
    );
    if (is_string($cleaned) && trim($cleaned) !== '') $label = trim($cleaned);
  }
  if ($label === '') $label = ucwords(str_replace(array('-', '_'), ' ', $piece_stem));
  return $label;
}

private function mrm_get_promo_target_option_groups() {
  $groups = array(
    'General' => array('all' => 'All Products'),
    'Lessons' => array(
      'lesson:all' => 'All Lessons',
      'lesson:length:30' => 'All 30-Minute Lessons',
      'lesson:length:60' => 'All 60-Minute Lessons',
      'lesson:mode:online' => 'All Online Lessons',
      'lesson:mode:inperson' => 'All In-Person Lessons',
      'lesson:category:30_online' => '30-Minute Online Lessons',
      'lesson:category:30_inperson' => '30-Minute In-Person Lessons',
      'lesson:category:60_online' => '60-Minute Online Lessons',
      'lesson:category:60_inperson' => '60-Minute In-Person Lessons',
    ),
    'Sheet Music' => array('sheet_music:all' => 'All Sheet Music'),
    'Masterclasses' => array('masterclass:all' => 'All Masterclasses'),
  );
  $piece_rows = array();
  $standalone = array();
  $category_labels = array('fundamentals'=>'Fundamental Packet','trombone-euphonium'=>'Trombone/Euphonium','tuba'=>'Tuba','complete-package'=>'Complete Package');
  foreach ($this->all_products() as $stored_sku => $product) {
    if (!is_array($product) || empty($product['active']) || sanitize_key((string)($product['product_type'] ?? '')) !== 'sheet_music') continue;
    $sku = $this->sanitize_sku($product['sku'] ?? $stored_sku);
    if ($sku === '') continue;
    $label = sanitize_text_field((string)($product['label'] ?? $sku));
    $category = sanitize_key((string)($product['category'] ?? ''));
    if ($category === '') $category = $this->mrm_infer_sheet_music_category_from_text($sku . ' ' . $label);
    $piece_stem = $this->mrm_piece_stem_from_offer_slug($sku, $category);
    if ($piece_stem === '' || !isset($category_labels[$category])) {
      $standalone['sheet_music:sku:' . $sku] = $label;
      continue;
    }
    if (!isset($piece_rows[$piece_stem])) $piece_rows[$piece_stem] = array('label'=>$this->mrm_promo_piece_display_label($piece_stem, $label),'offers'=>array());
    $piece_rows[$piece_stem]['offers'][$sku] = array('label'=>$label,'category'=>$category);
  }
  ksort($piece_rows, SORT_NATURAL | SORT_FLAG_CASE);
  $options = array();
  foreach ($piece_rows as $piece_stem => $piece_data) {
    $piece_label = sanitize_text_field((string)($piece_data['label'] ?? ''));
    if ($piece_label === '') $piece_label = ucwords(str_replace(array('-', '_'), ' ', $piece_stem));
    $options['sheet_music:piece:' . $piece_stem] = $piece_label . ' — All Offerings';
    foreach ($piece_data['offers'] as $sku => $offer) {
      $category = sanitize_key((string)($offer['category'] ?? ''));
      $offer_label = $category_labels[$category] ?? sanitize_text_field((string)($offer['label'] ?? $sku));
      $options['sheet_music:sku:' . $sku] = $piece_label . ' — ' . $offer_label;
    }
  }
  asort($standalone, SORT_NATURAL | SORT_FLAG_CASE);
  foreach ($standalone as $target => $label) $options[$target] = $label;
  $groups['Sheet Music'] = array('sheet_music:all' => 'All Sheet Music') + $options;
  return $groups;
}

private function mrm_promo_target_is_known($target) {
  $target = $this->mrm_normalize_promo_target($target);
  if (strpos($target, 'legacy:') === 0) return !empty($this->mrm_promo_scope_values_for_target($target));
  foreach ($this->mrm_get_promo_target_option_groups() as $options) if (isset($options[$target])) return true;
  return false;
}

private function mrm_promo_target_allows_purchase($promo, $product_type, $context = array()) {
  $promo = is_array($promo) ? $promo : array();
  $context = is_array($context) ? $context : array();
  $product_type = sanitize_key((string)$product_type);
  $target = $this->mrm_promo_target_from_legacy($promo);
  if ($target === 'all') return in_array($product_type, array('lesson','sheet_music','masterclass'), true);
  if (strpos($target, 'legacy:') === 0) return in_array($product_type, $this->mrm_promo_scope_values_for_target($target), true);
  $sku = $this->sanitize_sku($context['sku'] ?? '');
  $category = sanitize_key((string)($context['product_category'] ?? ''));
  if ($sku !== '' && $category === '') {
    $product = $this->get_product($sku);
    if (is_array($product)) $category = sanitize_key((string)($product['category'] ?? ''));
  }
  if ($product_type === 'lesson') {
    if ($target === 'lesson:all') return true;
    if ($target === 'lesson:length:30') return strpos($category, '30_') === 0;
    if ($target === 'lesson:length:60') return strpos($category, '60_') === 0;
    if ($target === 'lesson:mode:online') return substr($category, -7) === '_online';
    if ($target === 'lesson:mode:inperson') return substr($category, -9) === '_inperson';
    if (strpos($target, 'lesson:category:') === 0) {
      $wanted = sanitize_key(substr($target, strlen('lesson:category:')));
      return $wanted !== '' && hash_equals($wanted, $category);
    }
    return false;
  }
  if ($product_type === 'sheet_music') {
    if ($target === 'sheet_music:all') return true;
    if (strpos($target, 'sheet_music:sku:') === 0) {
      $wanted = $this->sanitize_sku(substr($target, strlen('sheet_music:sku:')));
      return $wanted !== '' && $sku !== '' && hash_equals($wanted, $sku);
    }
    if (strpos($target, 'sheet_music:piece:') === 0) {
      $wanted = $this->sanitize_sku(substr($target, strlen('sheet_music:piece:')));
      $piece = $this->mrm_piece_stem_from_offer_slug($sku, $category);
      return $wanted !== '' && $piece !== '' && hash_equals($wanted, $piece);
    }
    return false;
  }
  if ($product_type === 'masterclass') {
    if ($target === 'masterclass:all') return true;
    if (strpos($target, 'masterclass:id:') === 0) {
      $wanted = sanitize_key(substr($target, strlen('masterclass:id:')));
      $current = sanitize_key((string)($context['masterclass_id'] ?? ''));
      return $wanted !== '' && $current !== '' && hash_equals($wanted, $current);
    }
  }
  return false;
}

private function mrm_get_active_promo_code($code) {
  $code = $this->mrm_normalize_promo_code($code);
  if ($code === '') return null;

  $codes = $this->mrm_get_promo_codes();
  if (empty($codes[$code]) || !is_array($codes[$code])) {
    return null;
  }

  $promo = $codes[$code];

  if (empty($promo['active'])) {
    return null;
  }

  $expires = trim((string)($promo['expires_at'] ?? ''));
  if ($expires !== '') {
    $expires_ts = strtotime($expires . ' 23:59:59');
    if ($expires_ts && $expires_ts < current_time('timestamp')) {
      return null;
    }
  }

  $promo['code'] = $code;
  return $promo;
}

private function mrm_scope_allows_promo_for_product($promo, $product_type) {
  $promo = is_array($promo) ? $promo : array();
  $product_type = sanitize_key((string)$product_type);
  $scopes = array();

  if (isset($promo['scopes']) && is_array($promo['scopes'])) {
    $scopes = array_values(array_filter(array_map('sanitize_key', $promo['scopes'])));
  }

  if (empty($scopes)) {
    $legacy_scope = sanitize_key((string)($promo['scope'] ?? 'all'));
    if ($legacy_scope === 'all') {
      $scopes = array('lesson', 'sheet_music', 'masterclass');
    } elseif (in_array($legacy_scope, array('lesson', 'sheet_music', 'masterclass'), true)) {
      $scopes = array($legacy_scope);
    }
  }

  $scopes = array_values(array_intersect($scopes, array('lesson', 'sheet_music', 'masterclass')));
  return !empty($scopes) && in_array($product_type, $scopes, true);
}

private function mrm_customer_has_used_promo($code, $email_hash, $promo = array()) {
  global $wpdb;

  $code = $this->mrm_normalize_promo_code($code);
  $email_hash = (string)$email_hash;
  $promo = is_array($promo) ? $promo : array();

  if ($code === '' || $email_hash === '') {
    return false;
  }

  /*
   * Reusable-per-email promos are allowed to be redeemed repeatedly by the
   * same email address. Each successful use is still recorded as a separate
   * redemption row.
   */
  if (!empty($promo['reusable_per_email'])) {
    return false;
  }

  $table = $this->table_promo_redemptions();

  $found_table = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
  if ($found_table !== $table) {
    $this->install_or_upgrade_db();
  }

  /* Age alone must never make a code reusable. */
  $this->mrm_reconcile_stale_pending_promo_redemptions($code, $email_hash);

  $found = $wpdb->get_var($wpdb->prepare(
    "SELECT id FROM {$table}
     WHERE promo_code = %s
       AND email_hash = %s
       AND status = 'paid'
     LIMIT 1",
    $code,
    $email_hash
  ));

  return !empty($found);
}


private function mrm_promo_date_in_window($promo, $context = array()) {
  $promo = is_array($promo) ? $promo : array();
  $context = is_array($context) ? $context : array();

  $now_ts = !empty($context['now_ts']) ? (int)$context['now_ts'] : current_time('timestamp');

  $starts_at = trim((string)($promo['starts_at'] ?? ''));

  /*
   * expires_at is the canonical saved field. ends_at is supported as a
   * backwards-compatible alias in case older saved promo data used that name.
   */
  $ends_at = trim((string)($promo['expires_at'] ?? ''));
  if ($ends_at === '') {
    $ends_at = trim((string)($promo['ends_at'] ?? ''));
  }

  if ($starts_at !== '') {
    $start_ts = strtotime($starts_at . ' 00:00:00');
    if ($start_ts && $now_ts < $start_ts) {
      return false;
    }
  }

  if ($ends_at !== '') {
    $end_ts = strtotime($ends_at . ' 23:59:59');
    if ($end_ts && $now_ts > $end_ts) {
      return false;
    }
  }

  return true;
}



private function mrm_promo_rule_allows_context($promo, $context = array()) {
  $promo = is_array($promo) ? $promo : array();
  $context = is_array($context) ? $context : array();
  $rule_mode = (string)($promo['rule_mode'] ?? 'all');
  $occurrence_number = isset($context['occurrence_number']) ? max(1, absint($context['occurrence_number'])) : 1;
  $occurrence_count = isset($promo['occurrence_count']) ? max(0, absint($promo['occurrence_count'])) : 0;
  if (!$this->mrm_promo_date_in_window($promo, $context)) return array('ok'=>false,'message'=>'This promotional code is not active for the current date.',);
  if ($rule_mode === 'first_n' && $occurrence_count > 0 && $occurrence_number > $occurrence_count) return array('ok'=>false,'message'=>'This promotional code has already reached its occurrence limit.',);
  if ($rule_mode === 'after_n' && $occurrence_count > 0 && $occurrence_number <= $occurrence_count) return array('ok'=>false,'message'=>'This promotional code starts after occurrence ' . $occurrence_count . '.',);
  if ($rule_mode === 'first_n_months') { $months = $occurrence_count > 0 ? $occurrence_count : 1; $started_at = trim((string)($context['promo_started_at'] ?? '')); if ($started_at !== '') { $start_ts = strtotime($started_at); $now_ts = !empty($context['now_ts']) ? (int)$context['now_ts'] : current_time('timestamp'); if ($start_ts) { $end_ts = strtotime('+' . $months . ' months', $start_ts); if ($end_ts && $now_ts >= $end_ts) return array('ok'=>false,'message'=>'This promotional code is outside its month-based discount window.',); } } }
  return array('ok'=>true,'message'=>'',);
}

private function mrm_promo_eligible_occurrences_for_context($promo, $context = array()) {
  $promo = is_array($promo) ? $promo : array();
  $context = is_array($context) ? $context : array();

  $lesson_count = isset($context['lesson_count']) ? max(1, absint($context['lesson_count'])) : 1;
  $occurrence_number = isset($context['occurrence_number']) ? max(1, absint($context['occurrence_number'])) : 1;
  $rule_mode = (string)($promo['rule_mode'] ?? 'all');
  $occurrence_count = isset($promo['occurrence_count']) ? max(0, absint($promo['occurrence_count'])) : 0;
  if ($rule_mode === 'first_n' && $occurrence_count > 0) {
    $eligible_remaining = max(0, $occurrence_count - ($occurrence_number - 1));
    return min($lesson_count, $eligible_remaining);
  }
  if ($rule_mode === 'after_n' && $occurrence_count > 0) {
    $eligible = 0;
    for ($i = 0; $i < $lesson_count; $i++) { if ($occurrence_number + $i > $occurrence_count) $eligible++; }
    return min($lesson_count, $eligible);
  }
  return $lesson_count;
}

private function mrm_calculate_promo_discount_cents($promo, $base_amount_cents, $product_type, $context = array()) {
  $promo = is_array($promo) ? $promo : array();
  $context = is_array($context) ? $context : array();

  $base_amount_cents = max(0, (int)$base_amount_cents);

  if ($base_amount_cents <= 0) {
    return array(
      'ok' => false,
      'message' => 'Invalid purchase amount.',
      'discount_cents' => 0,
    );
  }

  if (!$this->mrm_promo_target_allows_purchase($promo, $product_type, $context)) {
    return array(
      'ok' => false,
      'message' => 'This promotional code does not apply to this purchase.',
      'discount_cents' => 0,
    );
  }

  $rule_check = $this->mrm_promo_rule_allows_context($promo, $context);
  if (empty($rule_check['ok'])) {
    return array(
      'ok' => false,
      'message' => (string)($rule_check['message'] ?? 'This promotional code does not apply to this occurrence.'),
      'discount_cents' => 0,
    );
  }

  $discount_type = (string)($promo['discount_type'] ?? 'percent');
  $lesson_count = isset($context['lesson_count']) ? max(1, absint($context['lesson_count'])) : 1;
  $eligible_occurrences = $this->mrm_promo_eligible_occurrences_for_context($promo, $context);

  if ($eligible_occurrences <= 0) {
    return array(
      'ok' => false,
      'message' => 'This promotional code does not apply to this occurrence.',
      'discount_cents' => 0,
    );
  }

  $eligible_amount_cents = $base_amount_cents;

  if ($product_type === 'lesson') {
    $per_lesson_cents = (int)floor($base_amount_cents / $lesson_count);

    $eligible_amount_cents = min($base_amount_cents, $per_lesson_cents * $eligible_occurrences);
  }

  $discount_cents = 0;

  if ($discount_type === 'percent') {
    $percent = max(0, min(100, (int)($promo['percent_off'] ?? 0)));
    $discount_cents = (int)floor($eligible_amount_cents * ($percent / 100));
  } else {
    $amount_off_cents = max(0, (int)($promo['amount_off_cents'] ?? 0));

    if ($product_type === 'lesson' && $lesson_count > 1) {
      $discount_cents = min($amount_off_cents * $eligible_occurrences, $eligible_amount_cents);
    } else {
      $discount_cents = min($amount_off_cents, $eligible_amount_cents);
    }
  }

  $discount_cents = min($discount_cents, $eligible_amount_cents);

  /*
   * Keep the complete checkout at or above Stripe's minimum charge while
   * allowing the primary item to be fully discounted when a paid,
   * non-discountable add-on remains on the order.
   */
  $non_discountable_amount_cents = max(0, (int)($context['non_discountable_amount_cents'] ?? 0));
  $minimum_charge_cents = max(0, (int)($context['minimum_charge_cents'] ?? 50));
  $max_safe_discount = max(
    0,
    $base_amount_cents + $non_discountable_amount_cents - $minimum_charge_cents
  );
  $discount_cents = min($discount_cents, $eligible_amount_cents, $max_safe_discount);

  return array(
    'ok' => true,
    'message' => '',
    'discount_cents' => $discount_cents,
    'eligible_amount_cents' => $eligible_amount_cents,
    'eligible_occurrences' => $eligible_occurrences,
  );
}


private function mrm_validate_promo_for_purchase($code, $email, $product_type, $base_amount_cents, $context = array()) {
  $code = $this->mrm_normalize_promo_code($code);

  if ($code === '') {
    return array(
      'ok' => false,
      'message' => 'Please enter a promotional code.',
      'discount_cents' => 0,
    );
  }

  $email = sanitize_email((string)$email);
  if (!$email || !is_email($email)) {
    return array(
      'ok' => false,
      'message' => 'Please enter a valid email before applying a promotional code.',
      'discount_cents' => 0,
    );
  }

  $promo = $this->mrm_get_active_promo_code($code);
  if (!$promo) {
    return array(
      'ok' => false,
      'message' => 'This promotional code is invalid or expired.',
      'discount_cents' => 0,
    );
  }

  $email_hash = $this->email_hash($email);

  if ($this->mrm_customer_has_used_promo($code, $email_hash, $promo)) {
    return array(
      'ok' => false,
      'code' => 'promo_code_already_used',
      'message' => 'This email has already used this promotional code.',
      'discount_cents' => 0,
    );
  }

  $calc = $this->mrm_calculate_promo_discount_cents($promo, $base_amount_cents, $product_type, $context);

  if (empty($calc['ok'])) {
    return $calc;
  }

  return array(
    'ok' => true,
    'message' => 'Promotional code applied.',
    'promo' => $promo,
    'code' => $code,
    'discount_cents' => (int)$calc['discount_cents'],
    'eligible_amount_cents' => (int)($calc['eligible_amount_cents'] ?? $base_amount_cents),
    'eligible_occurrences' => (int)($calc['eligible_occurrences'] ?? 1),
  );
}

public function resolve_promo_discount($promo_code, $amount_cents, $context = array()) {
  $promo_code = $this->mrm_normalize_promo_code($promo_code);
  $amount_cents = max(0, absint($amount_cents));
  $context = is_array($context) ? $context : array();
  $email = sanitize_email((string)($context['email'] ?? ''));
  $product_type = sanitize_key((string)($context['product_type'] ?? 'lesson'));

  if ($promo_code === '' || $amount_cents <= 0) {
    return array('ok'=>false,'discount_cents'=>0,'message'=>'No promotional code was provided.');
  }

  $result = $this->mrm_validate_promo_for_purchase($promo_code, $email, $product_type, $amount_cents, $context);

  if (empty($result['ok'])) {
    return $result;
  }

  $discount_cents = max(0, min($amount_cents, (int)($result['discount_cents'] ?? 0)));

  if ($discount_cents <= 0) {
    return array('ok'=>false,'discount_cents'=>0,'message'=>'This promotional code does not apply to this purchase.');
  }

  return array_merge($result, array(
    'ok' => true,
    'promo_code' => $promo_code,
    'discount_cents' => $discount_cents,
    'discount_label' => '$' . number_format($discount_cents / 100, 2) . ' off',
    'original_amount_cents' => $amount_cents,
    'final_amount_cents' => max(0, $amount_cents - $discount_cents),
  ));
}

private function mrm_promo_redemption_lock_name($code, $email_hash) {
  $code = $this->mrm_normalize_promo_code($code);
  $email_hash = preg_replace('/[^a-f0-9]/i', '', (string)$email_hash);
  if ($code === '' || $email_hash === '') return '';
  return 'mrm_promo_' . substr(hash('sha256', $code . '|' . strtolower($email_hash)), 0, 48);
}

private function mrm_acquire_promo_redemption_lock($code, $email_hash) {
  global $wpdb;
  $lock_name = $this->mrm_promo_redemption_lock_name($code, $email_hash);
  if ($lock_name === '') return '';
  $acquired = $wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s, %d)', $lock_name, 10));
  return (int)$acquired === 1 ? $lock_name : '';
}

private function mrm_release_promo_redemption_lock($lock_name) {
  global $wpdb;
  $lock_name = sanitize_text_field((string)$lock_name);
  if ($lock_name !== '') $wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)', $lock_name));
}

private function mrm_update_pending_promo_redemption_status($redemption_id, $status) {
  global $wpdb;
  $redemption_id = absint($redemption_id);
  $status = sanitize_key((string)$status);
  if ($redemption_id <= 0 || !in_array($status, array('paid', 'expired'), true)) return false;
  return $wpdb->update(
    $this->table_promo_redemptions(),
    array('status'=>$status, 'updated_at'=>current_time('mysql')),
    array('id'=>$redemption_id, 'status'=>'pending'),
    array('%s','%s'), array('%d','%s')
  ) !== false;
}

private function mrm_reconcile_stale_pending_promo_redemptions_locked($code, $email_hash) {
  global $wpdb;
  $code = $this->mrm_normalize_promo_code($code);
  $email_hash = sanitize_text_field((string)$email_hash);
  if ($code === '' || $email_hash === '') return false;
  $table = $this->table_promo_redemptions();
  $cutoff = wp_date('Y-m-d H:i:s', time() - HOUR_IN_SECONDS, wp_timezone());
  $rows = $wpdb->get_results($wpdb->prepare(
    "SELECT id, order_id, stripe_payment_intent_id FROM {$table} WHERE promo_code = %s AND email_hash = %s AND status = 'pending' AND created_at < %s ORDER BY id ASC",
    $code, $email_hash, $cutoff
  ), ARRAY_A);
  if (!is_array($rows)) return false;
  foreach ($rows as $row) {
    $redemption_id = absint($row['id'] ?? 0);
    $order_id = absint($row['order_id'] ?? 0);
    $payment_reference = sanitize_text_field((string)($row['stripe_payment_intent_id'] ?? ''));
    if ($redemption_id <= 0) continue;
    $order = $order_id > 0 ? $this->get_order($order_id) : null;
    $external_reservation_token = '';
    $payment_intent_id = strpos($payment_reference, 'pi_') === 0 ? $payment_reference : '';
    if ($payment_intent_id === '' && strpos($payment_reference, 'mrm_pending_') === 0) {
      $external_reservation_token = $payment_reference;
      $payment_intent_id = $this->mrm_get_external_promo_payment_reference($external_reservation_token);
      /* Never expire an unresolved external reservation merely because it is old. */
      if ($payment_intent_id === '') continue;
    }
    if ($payment_intent_id === '' && is_array($order)) {
      $order_pi = sanitize_text_field((string)($order['stripe_payment_intent_id'] ?? ''));
      if (strpos($order_pi, 'pi_') === 0) $payment_intent_id = $order_pi;
    }
    if ($payment_intent_id === '') {
      $this->mrm_update_pending_promo_redemption_status($redemption_id, 'expired');
      continue;
    }
    $payment_intent = $this->stripe_retrieve_payment_intent($payment_intent_id);
    if (is_wp_error($payment_intent)) continue;
    $stripe_status = sanitize_key((string)($payment_intent['status'] ?? ''));
    if ($stripe_status === 'succeeded') {
      if ($external_reservation_token !== '') $this->mark_external_promo_redemption_paid($payment_intent_id, $external_reservation_token);
      elseif ($order_id > 0) $this->mrm_mark_promo_redemption_paid($order_id, $payment_intent_id);
      else $this->mrm_mark_promo_redemption_paid_by_payment_intent($payment_intent_id);
      continue;
    }
    if ($stripe_status === 'canceled') {
      if ($order_id > 0) $this->update_order_status_from_pi($payment_intent_id, 'canceled', 'canceled', array('mrm_checkout_invalidated_reason'=>'stale_checkout_reconciliation','mrm_checkout_invalidated_at'=>current_time('mysql')));
      $this->mrm_update_pending_promo_redemption_status($redemption_id, 'expired');
      if ($external_reservation_token !== '') $this->mrm_delete_external_promo_payment_reference($external_reservation_token);
      continue;
    }
    if (in_array($stripe_status, array('processing','requires_capture'), true)) continue;
    if (in_array($stripe_status, array('requires_payment_method','requires_confirmation','requires_action'), true)) {
      $canceled = $this->stripe_api_request('POST', '/v1/payment_intents/' . rawurlencode($payment_intent_id) . '/cancel', array('cancellation_reason'=>'abandoned'));
      if (is_wp_error($canceled) || sanitize_key((string)($canceled['status'] ?? '')) !== 'canceled') continue;
      if ($order_id > 0) $this->update_order_status_from_pi($payment_intent_id, 'canceled', 'canceled', array('mrm_checkout_invalidated_reason'=>'stale_checkout_reconciliation','mrm_checkout_invalidated_at'=>current_time('mysql')));
      $this->mrm_update_pending_promo_redemption_status($redemption_id, 'expired');
      if ($external_reservation_token !== '') $this->mrm_delete_external_promo_payment_reference($external_reservation_token);
    }
  }
  return true;
}

private function mrm_reconcile_stale_pending_promo_redemptions($code, $email_hash) {
  $lock_name = $this->mrm_acquire_promo_redemption_lock($code, $email_hash);
  if ($lock_name === '') return false;
  try {
    return $this->mrm_reconcile_stale_pending_promo_redemptions_locked($code, $email_hash);
  } finally {
    $this->mrm_release_promo_redemption_lock($lock_name);
  }
}

private function mrm_release_pending_promo_redemption($order_id = 0, $payment_intent_id = '') {
  global $wpdb;
  $order_id = absint($order_id);
  $payment_intent_id = sanitize_text_field((string)$payment_intent_id);
  if ($order_id > 0) return $wpdb->delete($this->table_promo_redemptions(), array('order_id'=>$order_id,'status'=>'pending'), array('%d','%s')) !== false;
  if ($payment_intent_id !== '') return $wpdb->delete($this->table_promo_redemptions(), array('stripe_payment_intent_id'=>$payment_intent_id,'status'=>'pending'), array('%s','%s')) !== false;
  return false;
}

private function mrm_reserve_promo_redemption($code, $email_hash, $order_id, $payment_intent_id = '', $customer_email = '', $promo = array()) {
  global $wpdb;
  $code = $this->mrm_normalize_promo_code($code);
  $email_hash = (string)$email_hash;
  $order_id = absint($order_id);
  $payment_intent_id = sanitize_text_field((string)$payment_intent_id);
  $customer_email = sanitize_email((string)$customer_email);
  $promo = is_array($promo) ? $promo : array();
  if ($code === '' || $email_hash === '' || ($order_id <= 0 && $payment_intent_id === '')) return false;
  $table = $this->table_promo_redemptions();
  $found_table = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
  if ($found_table !== $table) $this->install_or_upgrade_db();
  $lock_name = $this->mrm_acquire_promo_redemption_lock($code, $email_hash);
  if ($lock_name === '') return false;
  try {
    $this->mrm_reconcile_stale_pending_promo_redemptions_locked($code, $email_hash);
    $existing_reference = $order_id > 0
      ? $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE order_id = %d AND promo_code = %s LIMIT 1", $order_id, $code))
      : $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE stripe_payment_intent_id = %s AND promo_code = %s LIMIT 1", $payment_intent_id, $code));
    if (!empty($existing_reference)) return true;
    if (empty($promo['reusable_per_email'])) {
      $active = $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE promo_code = %s AND email_hash = %s AND status IN ('pending', 'paid') LIMIT 1", $code, $email_hash));
      if (!empty($active)) return false;
    }
    $ip = isset($_SERVER['REMOTE_ADDR']) ? sanitize_text_field((string)$_SERVER['REMOTE_ADDR']) : '';
    $ua = isset($_SERVER['HTTP_USER_AGENT']) ? sanitize_text_field((string)$_SERVER['HTTP_USER_AGENT']) : '';
    $now = current_time('mysql');
    $row = array('promo_code'=>$code,'email_hash'=>$email_hash,'customer_email'=>$customer_email !== '' ? $customer_email : null,'stripe_payment_intent_id'=>$payment_intent_id,'status'=>'pending','ip_hash'=>$ip !== '' ? hash('sha256',$ip) : null,'user_agent_hash'=>$ua !== '' ? hash('sha256',$ua) : null,'created_at'=>$now,'updated_at'=>$now);
    $formats = array('%s','%s','%s','%s','%s','%s','%s','%s','%s');
    if ($order_id > 0) { $row['order_id'] = $order_id; $formats[] = '%d'; }
    return !empty($wpdb->insert($table, $row, $formats));
  } finally {
    $this->mrm_release_promo_redemption_lock($lock_name);
  }
}

private function mrm_external_promo_payment_reference_key($reservation_token) {
  $reservation_token = sanitize_text_field((string)$reservation_token);
  if ($reservation_token === '' || strpos($reservation_token, 'mrm_pending_') !== 0) return '';
  return 'mrm_ext_promo_pi_' . substr(hash('sha256', $reservation_token), 0, 40);
}

private function mrm_get_external_promo_payment_reference($reservation_token) {
  $key = $this->mrm_external_promo_payment_reference_key($reservation_token);
  if ($key === '') return '';
  $stored = get_transient($key);
  if (!is_array($stored)) return '';
  $stored_token = sanitize_text_field((string)($stored['reservation_token'] ?? ''));
  $payment_intent_id = sanitize_text_field((string)($stored['payment_intent_id'] ?? ''));
  if ($stored_token === '' || !hash_equals($stored_token, (string)$reservation_token) || strpos($payment_intent_id, 'pi_') !== 0) return '';
  return $payment_intent_id;
}

private function mrm_delete_external_promo_payment_reference($reservation_token) {
  $key = $this->mrm_external_promo_payment_reference_key($reservation_token);
  return $key === '' ? false : delete_transient($key);
}

public function record_external_promo_payment_reference($reservation_token, $payment_intent_id) {
  $reservation_token = sanitize_text_field((string)$reservation_token);
  $payment_intent_id = sanitize_text_field((string)$payment_intent_id);
  $key = $this->mrm_external_promo_payment_reference_key($reservation_token);
  if ($key === '' || strpos($payment_intent_id, 'pi_') !== 0) return new WP_Error('external_promo_payment_reference_invalid', 'The external promotional-code payment reference is invalid.');
  set_transient($key, array('reservation_token'=>$reservation_token, 'payment_intent_id'=>$payment_intent_id, 'recorded_at'=>current_time('mysql')), 7 * DAY_IN_SECONDS);
  $stored_payment_intent_id = $this->mrm_get_external_promo_payment_reference($reservation_token);
  if ($stored_payment_intent_id === '' || !hash_equals($payment_intent_id, $stored_payment_intent_id)) return new WP_Error('external_promo_payment_reference_not_saved', 'The external promotional-code payment reference could not be preserved.');
  return true;
}

private function mrm_external_promo_reservation_token($source, $reference) {
  $source = sanitize_key((string)$source);
  $reference = sanitize_text_field((string)$reference);
  if ($source === '' || $reference === '') return '';
  return 'mrm_pending_' . substr($source, 0, 30) . '_' . hash('sha256', $source . '|' . $reference);
}

public function reserve_external_promo_redemption($promo_code, $email, $source, $reference) {
  $promo_code = $this->mrm_normalize_promo_code($promo_code);
  $email = sanitize_email((string)$email);
  if ($promo_code === '' || !is_email($email)) return new WP_Error('external_promo_reservation_invalid', 'The promotional-code reservation data is invalid.');
  $promo = $this->mrm_get_active_promo_code($promo_code);
  if (!$promo) return new WP_Error('invalid_promo_code', 'This promotional code is invalid or expired.');
  $token = $this->mrm_external_promo_reservation_token($source, $reference);
  if ($token === '') return new WP_Error('external_promo_reference_invalid', 'The promotional-code reservation reference is invalid.');
  if (!$this->mrm_reserve_promo_redemption($promo_code, $this->email_hash($email), 0, $token, $email, $promo)) return new WP_Error('promo_code_already_used', 'This email has already used or reserved this promotional code.');
  return array('ok'=>true,'reservation_token'=>$token);
}

public function attach_external_promo_redemption($reservation_token, $payment_intent_id) {
  global $wpdb;
  $reservation_token = sanitize_text_field((string)$reservation_token);
  $payment_intent_id = sanitize_text_field((string)$payment_intent_id);
  if ($reservation_token === '' || $payment_intent_id === '') return new WP_Error('external_promo_attachment_invalid', 'The promotional-code attachment data is invalid.');
  $table = $this->table_promo_redemptions();
  $updated = $wpdb->update($table, array('stripe_payment_intent_id'=>$payment_intent_id,'updated_at'=>current_time('mysql')), array('stripe_payment_intent_id'=>$reservation_token,'status'=>'pending'), array('%s','%s'), array('%s','%s'));
  if ($updated === false) return new WP_Error('external_promo_attachment_failed', 'The promotional-code reservation could not be attached to the payment.');
  if ((int)$updated === 0) {
    $existing = $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE stripe_payment_intent_id = %s AND status IN ('pending', 'paid') LIMIT 1", $payment_intent_id));
    if (empty($existing)) return new WP_Error('external_promo_reservation_missing', 'The promotional-code reservation could not be found.');
  }
  $this->mrm_delete_external_promo_payment_reference($reservation_token);
  return true;
}

public function release_external_promo_redemption($reservation_token) {
  $reservation_token = sanitize_text_field((string)$reservation_token);
  $released = $this->mrm_release_pending_promo_redemption(0, $reservation_token);
  if ($released) $this->mrm_delete_external_promo_payment_reference($reservation_token);
  return $released;
}

private function mrm_mark_promo_redemption_paid_by_payment_intent($payment_intent_id) {
  global $wpdb;
  $payment_intent_id = sanitize_text_field((string)$payment_intent_id);
  if ($payment_intent_id === '') return false;
  $table = $this->table_promo_redemptions();
  $updated = $wpdb->update($table, array('status'=>'paid','updated_at'=>current_time('mysql')), array('stripe_payment_intent_id'=>$payment_intent_id,'status'=>'pending'), array('%s','%s'), array('%s','%s'));
  if ($updated === false) return false;
  if ((int)$updated > 0) return true;
  return !empty($wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE stripe_payment_intent_id = %s AND status = 'paid' LIMIT 1", $payment_intent_id)));
}

public function mark_external_promo_redemption_paid($payment_intent_id, $reservation_token = '') {
  $payment_intent_id = sanitize_text_field((string)$payment_intent_id);
  $reservation_token = sanitize_text_field((string)$reservation_token);
  if ($payment_intent_id === '') return false;
  if ($reservation_token !== '') {
    $attached = $this->attach_external_promo_redemption($reservation_token, $payment_intent_id);
    if (is_wp_error($attached) && $attached->get_error_code() !== 'external_promo_reservation_missing') return $attached;
  }
  $marked_paid = $this->mrm_mark_promo_redemption_paid_by_payment_intent($payment_intent_id);
  if ($marked_paid === true && $reservation_token !== '') $this->mrm_delete_external_promo_payment_reference($reservation_token);
  return $marked_paid;
}

private function mrm_attach_payment_intent_to_promo_redemption($order_id, $payment_intent_id) {
  global $wpdb;

  $order_id = absint($order_id);
  $payment_intent_id = sanitize_text_field((string)$payment_intent_id);

  if ($order_id <= 0 || $payment_intent_id === '') {
    return false;
  }

  $table = $this->table_promo_redemptions();

  $found_table = $wpdb->get_var($wpdb->prepare(
    "SHOW TABLES LIKE %s",
    $table
  ));

  if ($found_table !== $table) {
    $this->install_or_upgrade_db();
  }

  $updated = $wpdb->update(
    $table,
    array(
      'stripe_payment_intent_id' => $payment_intent_id,
      'updated_at' => current_time('mysql'),
    ),
    array(
      'order_id' => $order_id,
    ),
    array(
      '%s',
      '%s',
    ),
    array(
      '%d',
    )
  );

  return ($updated !== false);
}

private function mrm_mark_promo_redemption_paid($order_id, $payment_intent_id) {
  global $wpdb;

  $order_id = (int)$order_id;
  if ($order_id <= 0 || $payment_intent_id === '') return;

  $wpdb->update(
    $this->table_promo_redemptions(),
    array(
      'status' => 'paid',
      'stripe_payment_intent_id' => sanitize_text_field((string)$payment_intent_id),
      'updated_at' => current_time('mysql'),
    ),
    array('order_id' => $order_id),
    array('%s','%s','%s'),
    array('%d')
  );
}

private function mrm_get_redemptions_for_promo_code($code, $limit = 25) {
    global $wpdb;

    $code = $this->mrm_normalize_promo_code($code);
    if ($code === '') return array();

    $table = $this->table_promo_redemptions();

    $found_table = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
    if ($found_table !== $table) {
      return array();
    }

    $limit = max(1, min(100, absint($limit)));

    $rows = $wpdb->get_results($wpdb->prepare(
      "SELECT id, promo_code, email_hash, customer_email, status, created_at, updated_at
       FROM {$table}
       WHERE promo_code = %s
         AND status = 'paid'
       ORDER BY updated_at DESC
       LIMIT %d",
      $code,
      $limit
    ), ARRAY_A);

    if (!is_array($rows)) {
      return array();
    }

    foreach ($rows as &$row) {
      if (empty($row['customer_email']) && !empty($row['email_hash'])) {
        $decoded = $this->decode_email_hash((string)$row['email_hash']);
        if ($decoded) {
          $row['customer_email'] = $decoded;
        }
      }
    }
    unset($row);

    return $rows;
  }

private function mrm_delete_promo_redemption_rows($ids) {
    global $wpdb;

    if (!current_user_can('manage_options')) {
      return 0;
    }

    $ids = array_map('absint', (array)$ids);
    $ids = array_values(array_filter($ids));

    if (empty($ids)) {
      return 0;
    }

    $table = $this->table_promo_redemptions();

    $found_table = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
    if ($found_table !== $table) {
      return 0;
    }

    $placeholders = implode(',', array_fill(0, count($ids), '%d'));

    $sql = "DELETE FROM {$table} WHERE id IN ({$placeholders})";

    $deleted = $wpdb->query($wpdb->prepare($sql, $ids));

    return is_numeric($deleted) ? (int)$deleted : 0;
  }

private function get_settings() {
    $opts = get_option(self::OPT_SETTINGS, array());
    $opts = is_array($opts) ? $opts : array();

    $settings = wp_parse_args($opts, array(
      'one_time_sheet_music_composer_pct' => 0,
      'in_person_travel_amount_cents' => 500,

      'instructor_payout_30_online_year1_cents' => 0,
      'instructor_payout_30_online_year2_cents' => 0,
      'instructor_payout_30_online_year3_cents' => 0,

      'instructor_payout_30_inperson_year1_cents' => 0,
      'instructor_payout_30_inperson_year2_cents' => 0,
      'instructor_payout_30_inperson_year3_cents' => 0,

      'instructor_payout_60_online_year1_cents' => 0,
      'instructor_payout_60_online_year2_cents' => 0,
      'instructor_payout_60_online_year3_cents' => 0,

      'instructor_payout_60_inperson_year1_cents' => 0,
      'instructor_payout_60_inperson_year2_cents' => 0,
      'instructor_payout_60_inperson_year3_cents' => 0,

      'payout_anchor_date' => '',
      'composer_connected_account_id' => '',
      'test_composer_connected_account_id' => '',
      'background_check_docusign_url' => 'https://www.docusign.com/',
      'background_check_standard_docusign_url' => 'https://www.docusign.com/',
      'background_check_california_docusign_url' => 'https://www.docusign.com/',
