  private function mrm_quote_debug_enabled() {
    return (defined('MRM_LAUNCH_DEBUG') && MRM_LAUNCH_DEBUG && current_user_can('manage_options'));
  }

private function mrm_quote_debug_log($event, $data = array()) {
  if (!$this->mrm_quote_debug_enabled()) {
    return;
  }

  if (!defined('WP_CONTENT_DIR')) {
    return;
  }

  $file = trailingslashit(WP_CONTENT_DIR) . 'mrm-quote-debug.log';

  $safe_data = $this->mrm_quote_debug_sanitize($data);

  $entry = array(
    'time' => current_time('mysql'),
    'event' => (string)$event,
    'data' => $safe_data,
  );

  $line = wp_json_encode($entry, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

  if (!is_string($line) || $line === '') {
    $line = json_encode(array(
      'time' => current_time('mysql'),
      'event' => (string)$event,
      'data' => 'json_encode_failed',
    ));
  }

  /**
   * LOCK_EX prevents two simultaneous quote requests from garbling one line.
   */
  @file_put_contents($file, $line . PHP_EOL, FILE_APPEND | LOCK_EX);
}

private function mrm_quote_debug_sanitize($value) {
  if (is_array($value)) {
    $out = array();

    foreach ($value as $key => $child) {
      $key_string = strtolower((string)$key);

      /**
       * Avoid logging secrets or payment-sensitive values.
       */
      if (
        strpos($key_string, 'secret') !== false ||
        strpos($key_string, 'token') !== false ||
        strpos($key_string, 'client_secret') !== false ||
        strpos($key_string, 'webhook') !== false ||
        strpos($key_string, 'password') !== false ||
        strpos($key_string, 'card') !== false
      ) {
        $out[$key] = '[redacted]';
        continue;
      }

      $out[$key] = $this->mrm_quote_debug_sanitize($child);
    }

    return $out;
  }

  if (is_object($value)) {
    return $this->mrm_quote_debug_sanitize((array)$value);
  }

  if (is_string($value)) {
    if (strlen($value) > 500) {
      return substr($value, 0, 500) . '...[truncated]';
    }

    return $value;
  }

  return $value;
}

private function mrm_quote_debug_product_summary($product) {
  if (!is_array($product)) {
    return null;
  }

  return array(
    'label' => (string)($product['label'] ?? ''),
    'active_raw' => $product['active'] ?? null,
    'active_bool' => !empty($product['active']),
    'amount_cents' => isset($product['amount_cents']) ? (int)$product['amount_cents'] : null,
    'currency' => (string)($product['currency'] ?? ''),
    'product_type' => (string)($product['product_type'] ?? ''),
    'category' => (string)($product['category'] ?? ''),
    'has_stripe_price_id' => !empty($product['stripe_price_id']),
    'keys_present' => array_keys($product),
  );
}

private function mrm_quote_debug_nearby_product_keys($needle, $limit = 25) {
  $needle = $this->sanitize_sku($needle);
  $all = $this->all_products();

  if (!is_array($all) || empty($all)) {
    return array();
  }

  $matches = array();

  foreach ($all as $sku => $product) {
    $clean_sku = $this->sanitize_sku($sku);
    $label = is_array($product) ? (string)($product['label'] ?? '') : '';
    $label_slug = $this->slugify($label);

    if (
      $needle === '' ||
      strpos($clean_sku, $needle) !== false ||
      strpos($needle, $clean_sku) !== false ||
      ($label_slug !== '' && strpos($label_slug, $needle) !== false)
    ) {
      $matches[] = array(
        'sku_key' => $clean_sku,
        'label' => $label,
        'active' => is_array($product) ? !empty($product['active']) : false,
        'amount_cents' => is_array($product) && isset($product['amount_cents']) ? (int)$product['amount_cents'] : null,
        'currency' => is_array($product) ? (string)($product['currency'] ?? '') : '',
        'product_type' => is_array($product) ? (string)($product['product_type'] ?? '') : '',
        'category' => is_array($product) ? (string)($product['category'] ?? '') : '',
      );

      if (count($matches) >= (int)$limit) {
        break;
      }
    }
  }

  return $matches;
}

private function all_products() {
    $p = get_option(self::OPT_PRODUCTS, array());
    return is_array($p) ? $p : array();
  }

  private function save_products($products) {
    update_option(self::OPT_PRODUCTS, $this->mrm_strip_legacy_sheet_music_composer_pct_from_products($products));
  }

  private function mrm_strip_legacy_sheet_music_composer_pct_from_products($products) {
    if (!is_array($products)) return array();

    foreach ($products as $sku => $product) {
      if (!is_array($product)) continue;

      $type = (string)($product['product_type'] ?? '');
      if ($type === 'sheet_music' && array_key_exists('composer_pct', $product)) {
        unset($product['composer_pct']);
      }

      $products[$sku] = $product;
    }

    return $products;
  }

  private function mrm_sanitize_percent_setting($value, $default = 0) {
    if ($value === null || $value === '') return (int)$default;
    $pct = (int)$value;
    if ($pct < 0) $pct = 0;
    if ($pct > 100) $pct = 100;
    return $pct;
  }

  private function mrm_money_to_cents($value, $default = 0) {
    if ($value === null || $value === '') return (int)$default;

    $value = is_string($value) ? wp_unslash($value) : $value;
    $value = str_replace(array('$', ',', ' '), '', (string)$value);

    if ($value === '' || !is_numeric($value)) {
      return (int)$default;
    }

    return max(0, (int) round(((float)$value) * 100));
  }

  private function mrm_format_cents_for_admin_input($cents) {
    return number_format(((int)$cents) / 100, 2, '.', '');
  }

  private function mrm_get_one_time_sheet_music_composer_pct() {
    $settings = $this->get_settings();
    return $this->mrm_sanitize_percent_setting($settings['one_time_sheet_music_composer_pct'] ?? 0, 0);
  }

  private function mrm_get_in_person_travel_cents() {
    $settings = $this->get_settings();
    return max(0, (int)($settings['in_person_travel_amount_cents'] ?? 500));
  }

  private function mrm_get_instructor_payout_chart_rows() {
    return array(
      '30_online' => array(
        'label' => '30-Minute Online Lesson',
        'lesson_length' => 30,
        'is_online' => 1,
      ),
      '30_inperson' => array(
        'label' => '30-Minute In-Person Lesson',
        'lesson_length' => 30,
        'is_online' => 0,
      ),
      '60_online' => array(
        'label' => '60-Minute Online Lesson',
        'lesson_length' => 60,
        'is_online' => 1,
      ),
      '60_inperson' => array(
        'label' => '60-Minute In-Person Lesson',
        'lesson_length' => 60,
        'is_online' => 0,
      ),
    );
  }

  private function mrm_get_instructor_payout_chart_columns() {
    return array(
      1 => 'Year 1',
      2 => 'Year 2',
      3 => 'Year 3+',
    );
  }

  private function mrm_get_instructor_payout_chart_setting_key($lesson_length, $is_online, $year_bucket) {
    $lesson_length = (int)$lesson_length;
    $is_online = !empty($is_online);
    $year_bucket = max(1, min(3, (int)$year_bucket));

    if (!in_array($lesson_length, array(30, 60), true)) {
      return '';
    }

    $mode = $is_online ? 'online' : 'inperson';
    return 'instructor_payout_' . $lesson_length . '_' . $mode . '_year' . $year_bucket . '_cents';
  }

  private function mrm_get_instructor_payout_chart_admin_matrix() {
    $settings = $this->get_settings();
    $rows = $this->mrm_get_instructor_payout_chart_rows();
    $matrix = array();

    foreach ($rows as $row_key => $row) {
      $matrix[$row_key] = array();

      foreach (array_keys($this->mrm_get_instructor_payout_chart_columns()) as $year_bucket) {
        $setting_key = $this->mrm_get_instructor_payout_chart_setting_key(
          (int)$row['lesson_length'],
          (int)$row['is_online'],
          (int)$year_bucket
        );

        $matrix[$row_key][$year_bucket] = $this->mrm_format_cents_for_admin_input(
          (int)($settings[$setting_key] ?? 0)
        );
      }
    }

    return $matrix;
  }

  private function mrm_get_instructor_employment_year_bucket($hire_date, $as_of_ts = null) {
    $hire_date = trim((string)$hire_date);
    if ($hire_date === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $hire_date)) {
      return 1;
    }

    try {
      $tz = $this->mrm_wp_tz();

      if ($as_of_ts !== null && (int)$as_of_ts > 0) {
        $now = new DateTime('@' . (int)$as_of_ts);
        $now->setTimezone($tz);
      } else {
        $now = new DateTime('now', $tz);
      }

      $start = new DateTime($hire_date . ' 00:00:00', $tz);

      if ($now < $start) {
        return 1;
      }

      $full_years = (int)$start->diff($now)->y;
      $bucket = $full_years + 1;

      if ($bucket < 1) $bucket = 1;
      if ($bucket > 3) $bucket = 3;

      return $bucket;
    } catch (Exception $e) {
      return 1;
    }
  }

  private function mrm_get_instructor_year_bucket_label($year_bucket) {
    $year_bucket = (int)$year_bucket;
    return ($year_bucket >= 3) ? '3+' : (string)max(1, $year_bucket);
  }

  private function mrm_get_instructor_payout_chart_base_cents($lesson_length, $is_online, $hire_date, $as_of_ts = null) {
    $settings = $this->get_settings();
    $year_bucket = $this->mrm_get_instructor_employment_year_bucket($hire_date, $as_of_ts);

    $setting_key = $this->mrm_get_instructor_payout_chart_setting_key($lesson_length, $is_online, $year_bucket);
    if ($setting_key === '') {
      return 0;
    }

    return max(0, (int)($settings[$setting_key] ?? 0));
  }

  private function mrm_get_instructor_payout_cents_for_instructor($lesson_length, $is_online, $hire_date, $as_of_ts = null) {
    $base = $this->mrm_get_instructor_payout_chart_base_cents($lesson_length, $is_online, $hire_date, $as_of_ts);

    if (!empty($is_online)) {
      return $base;
    }

    return $base + $this->mrm_get_in_person_travel_cents();
  }

  private function mrm_sheet_music_blocked_emails() {
    $emails = get_option(self::OPT_SHEET_MUSIC_BLOCKED_EMAILS, array());

    if (!is_array($emails)) {
      $emails = array();
    }

    $clean = array();

    foreach ($emails as $email) {
      $email = strtolower(trim(sanitize_email((string)$email)));

      if ($email && is_email($email)) {
        $clean[] = $email;
      }
    }

    return array_values(array_unique($clean));
  }

  private function mrm_save_sheet_music_blocked_emails($emails) {
    $emails = is_array($emails) ? $emails : array();
    $clean = array();

    foreach ($emails as $email) {
      $email = strtolower(trim(sanitize_email((string)$email)));

      if ($email && is_email($email)) {
        $clean[] = $email;
      }
    }

    update_option(self::OPT_SHEET_MUSIC_BLOCKED_EMAILS, array_values(array_unique($clean)));
  }

  private function mrm_sheet_music_email_is_blocked($email) {
    $email = strtolower(trim(sanitize_email((string)$email)));

    if (!$email || !is_email($email)) {
      return false;
    }

    return in_array($email, $this->mrm_sheet_music_blocked_emails(), true);
  }

  private function mrm_block_sheet_music_email($email) {
    $email = strtolower(trim(sanitize_email((string)$email)));

    if (!$email || !is_email($email)) {
      return false;
    }

    $blocked = $this->mrm_sheet_music_blocked_emails();
    $blocked[] = $email;

    $this->mrm_save_sheet_music_blocked_emails($blocked);

    return true;
  }

  private function mrm_unblock_sheet_music_email($email) {
    $email = strtolower(trim(sanitize_email((string)$email)));

    if (!$email || !is_email($email)) {
      return false;
    }

    $blocked = array_values(array_filter(
      $this->mrm_sheet_music_blocked_emails(),
      function($blocked_email) use ($email) {
        return $blocked_email !== $email;
      }
    ));

    $this->mrm_save_sheet_music_blocked_emails($blocked);

    return true;
  }

  private function mrm_sheet_music_contact_url() {
    return home_url('/contact/');
  }

  private function mrm_sheet_music_access_source_label($source, $sku = '') {
    $source = strtolower(trim((string)$source));
    $sku = strtolower(trim((string)$sku));

    if ($sku === 'all-sheet-music') {
      return 'Subscription / All Sheet Music';
    }

    if ($source === 'manual_admin' || $source === 'manual') {
      return 'Manual Grant';
    }

    if ($source === 'stripe_pi') {
      return 'Purchase';
    }

    if ($source === 'subscription' || strpos($source, 'subscription') !== false) {
      return 'Subscription';
    }

    if ($source !== '') {
      return ucwords(str_replace(array('_', '-'), ' ', $source));
    }

    return 'Access Row';
  }

  private function normalize_email_list_textarea($raw) {
    $raw = (string)$raw;
    $parts = preg_split('/[\s,;]+/', $raw);
    $out = array();
    foreach ($parts as $p) {
      $em = sanitize_email(trim($p));
      if ($em && is_email($em)) $out[] = strtolower($em);
    }
    $out = array_values(array_unique($out));
    return $out;
  }

  private function sanitize_product_slug($slug) {
    // Lowercase, hyphen/underscore only (your requirement)
    $slug = strtolower(trim((string)$slug));
    $slug = preg_replace('/[^a-z0-9\-_]+/', '', $slug);
    return $slug;
  }

  private function get_product($sku) {
    $sku = $this->sanitize_sku($sku);
    $all = $this->all_products();
    return isset($all[$sku]) && is_array($all[$sku]) ? $all[$sku] : null;
  }

private function mrm_is_active_product_sku($sku) {
  $sku = $this->sanitize_sku($sku);
  if ($sku === '') {
    return false;
  }

  $product = $this->get_product($sku);
  return is_array($product) && !empty($product['active']);
}

private function mrm_add_unique_sku_candidate(&$candidates, $sku) {
  $sku = $this->sanitize_sku($sku);
  if ($sku !== '' && !in_array($sku, $candidates, true)) {
    $candidates[] = $sku;
  }
}

private function mrm_infer_sheet_music_category_from_text($text) {
  $text = strtolower((string)$text);
  if (strpos($text, 'trombone-euphonium') !== false || strpos($text, 'trombone_euphonium') !== false) return 'trombone-euphonium';
  if (strpos($text, 'trombone') !== false && strpos($text, 'euphonium') !== false) return 'trombone-euphonium';
  if (preg_match('/(^|[-_\s])tuba($|[-_\s])/', $text)) return 'tuba';
  if (strpos($text, 'fundamental') !== false) return 'fundamentals';
  if (strpos($text, 'complete-package') !== false || strpos($text, 'complete_package') !== false || strpos($text, 'complete package') !== false || strpos($text, 'full-piece') !== false || strpos($text, 'full piece') !== false || strpos($text, 'bundle') !== false || strpos($text, 'all-parts') !== false || strpos($text, 'all parts') !== false) return 'complete-package';
  return '';
}

private function mrm_piece_stem_from_offer_slug($raw_sku, $category = '') {
  $stem = $this->sanitize_sku($raw_sku);
  if ($stem === '') return '';
  $stem = preg_replace('/^piece-/', '', $stem);
  $patterns = array('/-trombone-euphonium.*$/','/-trombone.*euphonium.*$/','/-tuba.*$/','/-fundamentals?.*$/','/-complete-package.*$/','/-complete.*$/','/-full-piece.*$/','/-all-parts.*$/','/-bundle.*$/',);
  foreach ($patterns as $pattern) {
    $cleaned = preg_replace($pattern, '', $stem);
    if (is_string($cleaned) && $cleaned !== $stem && $cleaned !== '') { $stem = $cleaned; break; }
  }
  return trim($stem, '-_');
}

private function mrm_resolve_active_product_sku($incoming_sku, $context = array()) {
  $original_incoming_sku = $incoming_sku;
  $incoming_sku = $this->sanitize_sku($incoming_sku);

  $this->mrm_quote_debug_log('resolver_start', array(
    'original_incoming_sku' => $original_incoming_sku,
    'sanitized_incoming_sku' => $incoming_sku,
    'context' => $context,
  ));

  if ($incoming_sku === '') {
    $this->mrm_quote_debug_log('resolver_empty_incoming_sku', array(
      'original_incoming_sku' => $original_incoming_sku,
    ));
    return '';
  }

  if ($this->mrm_is_active_product_sku($incoming_sku)) {
    $this->mrm_quote_debug_log('resolver_exact_active_match', array(
      'resolved_sku' => $incoming_sku,
      'product' => $this->mrm_quote_debug_product_summary($this->get_product($incoming_sku)),
    ));
    return $incoming_sku;
  }

  $context = is_array($context) ? $context : array();

  $candidates = array();
  $this->mrm_add_unique_sku_candidate($candidates, $incoming_sku);

  if (strpos($incoming_sku, 'piece-') !== 0) {
    $this->mrm_add_unique_sku_candidate($candidates, 'piece-' . $incoming_sku);
  }

  $piece_slug_from_context = !empty($context['piece_slug']) ? $this->slugify((string)$context['piece_slug']) : '';

  $context_text = $incoming_sku . ' '
    . (string)($context['display_title'] ?? '') . ' '
    . (string)($context['subtitle'] ?? '') . ' '
    . (string)($context['type'] ?? '');

  $category = $this->mrm_infer_sheet_music_category_from_text($context_text);

  if ($category !== '') {
    $stem = $this->mrm_piece_stem_from_offer_slug($incoming_sku, $category);

    if ($stem !== '') {
      $this->mrm_add_unique_sku_candidate($candidates, 'piece-' . $stem . '-' . $category);
    }

    if ($piece_slug_from_context !== '') {
      $this->mrm_add_unique_sku_candidate($candidates, 'piece-' . $piece_slug_from_context . '-' . $category);
    }
  }

  $this->mrm_quote_debug_log('resolver_candidates_built', array(
    'incoming_sku' => $incoming_sku,
    'piece_slug_from_context' => $piece_slug_from_context,
    'context_text' => $context_text,
    'inferred_category' => $category,
    'candidates' => $candidates,
  ));

  foreach ($candidates as $candidate) {
    $candidate_product = $this->get_product($candidate);

    $this->mrm_quote_debug_log('resolver_testing_candidate', array(
      'candidate' => $candidate,
      'exists' => is_array($candidate_product),
      'product' => $this->mrm_quote_debug_product_summary($candidate_product),
    ));

    if ($this->mrm_is_active_product_sku($candidate)) {
      $this->mrm_quote_debug_log('resolver_candidate_active_match', array(
        'resolved_sku' => $candidate,
      ));
      return $candidate;
    }

    for ($i = 2; $i <= 999; $i++) {
      $suffixed = $candidate . '-' . $i;
      $suffixed_product = $this->get_product($suffixed);

      if ($i <= 5 && is_array($suffixed_product)) {
        $this->mrm_quote_debug_log('resolver_testing_suffixed_candidate', array(
          'candidate' => $suffixed,
          'exists' => true,
          'product' => $this->mrm_quote_debug_product_summary($suffixed_product),
        ));
      }

      if ($this->mrm_is_active_product_sku($suffixed)) {
        $this->mrm_quote_debug_log('resolver_suffixed_active_match', array(
          'resolved_sku' => $suffixed,
        ));
        return $suffixed;
      }
    }
  }

  $all = $this->all_products();

  $this->mrm_quote_debug_log('resolver_scanning_all_products', array(
    'product_count' => is_array($all) ? count($all) : 0,
    'incoming_sku' => $incoming_sku,
    'piece_slug_from_context' => $piece_slug_from_context,
    'inferred_category' => $category,
  ));

  foreach ($all as $sku => $product) {
    if (!is_array($product) || empty($product['active'])) {
      continue;
    }

    if ((string)($product['product_type'] ?? '') !== 'sheet_music') {
      continue;
    }

    $product_category = (string)($product['category'] ?? '');

    if ($category !== '' && $product_category !== $category) {
      continue;
    }

    $sku_clean = $this->sanitize_sku($sku);
    $label_slug = $this->slugify((string)($product['label'] ?? ''));

    if ($category !== '' && $piece_slug_from_context !== '') {
      if (
        strpos($sku_clean, 'piece-' . $piece_slug_from_context . '-' . $category) === 0 ||
        (
          strpos($label_slug, $piece_slug_from_context) !== false &&
          strpos($sku_clean, '-' . $category) !== false
        )
      ) {
        $this->mrm_quote_debug_log('resolver_scan_piece_slug_match', array(
          'resolved_sku' => $sku_clean,
          'product' => $this->mrm_quote_debug_product_summary($product),
        ));
        return $sku_clean;
      }
    }

    $stem = $this->mrm_piece_stem_from_offer_slug($incoming_sku, $category);

    if ($category !== '' && $stem !== '') {
      if (
        strpos($sku_clean, 'piece-' . $stem . '-' . $category) === 0 ||
        (
          strpos($label_slug, $stem) !== false &&
          strpos($sku_clean, '-' . $category) !== false
        )
      ) {
        $this->mrm_quote_debug_log('resolver_scan_stem_match', array(
          'resolved_sku' => $sku_clean,
          'stem' => $stem,
          'product' => $this->mrm_quote_debug_product_summary($product),
        ));
        return $sku_clean;
      }
    }
  }

  $this->mrm_quote_debug_log('resolver_no_match', array(
    'incoming_sku' => $incoming_sku,
    'piece_slug_from_context' => $piece_slug_from_context,
    'inferred_category' => $category,
    'nearby_products' => $this->mrm_quote_debug_nearby_product_keys($incoming_sku),
  ));

  return '';
}



  private function get_email_lists() {
    $m = get_option(self::OPT_EMAIL_LISTS, array());
    return is_array($m) ? $m : array();
  }

  private function save_email_lists($lists) {
    update_option(self::OPT_EMAIL_LISTS, is_array($lists) ? $lists : array());
  }

  private function mrm_normalize_state_code($state) {
    $state = strtoupper((string)$state);
    $state = preg_replace('/[^A-Z]/', '', $state);
    return substr($state, 0, 2);
  }


  private function mrm_get_instructor_performance_location_id($instructor_id) {
    global $wpdb;
    $instructor_id = absint($instructor_id);
    if ($instructor_id <= 0) return '';
    $table = $wpdb->prefix . 'mrm_instructors';
    return sanitize_text_field($wpdb->get_var($wpdb->prepare("SELECT stripe_tax_location_id FROM {$table} WHERE id = %d", $instructor_id)));
  }

  private function mrm_normalize_tax_address($address = array()) {
    return array(
      'country' => strtoupper(trim((string)($address['country'] ?? 'US'))),
      'state' => $this->mrm_normalize_state_code($address['state'] ?? ''),
      'postal_code' => trim((string)($address['postal_code'] ?? '')),
      'line1' => trim((string)($address['line1'] ?? '')),
      'line2' => trim((string)($address['line2'] ?? '')),
      'city' => sanitize_text_field((string)($address['city'] ?? '')),
    );
  }

  private function mrm_get_tax_product_profiles(
  $product_type,
  $addon_selected = false,
  $product_cfg = array(),
  $context = array()
) {
  $product_type = sanitize_key($product_type);
  $context = is_array($context) ? $context : array();
  $sku = sanitize_key($context['sku'] ?? $product_cfg['sku'] ?? '');
  $profiles = array();

  if ($product_type === 'sheet_music') {
    $profiles[] = array('key'=>'sheet_music_base','label'=>'Sheet music download','taxable'=>true,'tax_code'=>'txcd_10503000','amount_source'=>'base','threshold_category'=>'digital_document_download');
    if (!empty($context['fundamentals_addon_selected'])) $profiles[] = array('key'=>'sheet_music_fundamentals_packet_addon','label'=>'Fundamental Packet download','taxable'=>true,'tax_code'=>'txcd_10503000','amount_source'=>'fundamentals_addon','threshold_category'=>'digital_document_download');
    if ($addon_selected) {
      $subscription_code = $this->mrm_expected_subscription_tax_code();
      if ($subscription_code === '') return new WP_Error('invalid_subscription_tax_model','The sheet-music subscription rights model has not been approved for tax purposes.');
      $profiles[] = array('key'=>'sheet_music_access','label'=>'Sheet music access subscription','taxable'=>true,'tax_code'=>$subscription_code,'amount_source'=>'addon','threshold_category'=>'digital_document_subscription');
    }
    return $profiles;
  }

  if ($product_type === 'lesson') {
    $lesson_mode = sanitize_key($context['lesson_mode'] ?? $context['lesson_type'] ?? '');
    $online = !empty($context['online']) || $lesson_mode === 'online' || strpos($sku, '_online') !== false;
    $profile = array('key'=>$online ? 'private_lesson_online' : 'private_lesson_in_person','label'=>$online ? 'Live online private lesson' : 'In-person private lesson','taxable'=>true,'tax_code'=>$online ? 'txcd_20060045' : 'txcd_20060044','amount_source'=>'base','threshold_category'=>$online ? 'service_live_virtual' : 'service_in_person');
    if (!$online && !empty($context['stripe_tax_performance_location_id'])) $profile['performance_location'] = sanitize_text_field($context['stripe_tax_performance_location_id']);
    $profiles[] = $profile;
    if ($addon_selected) {
      $subscription_code = $this->mrm_expected_subscription_tax_code();
      if ($subscription_code === '') return new WP_Error('invalid_subscription_tax_model','The sheet-music subscription rights model has not been approved for tax purposes.');
      $profiles[] = array('key'=>'sheet_music_access','label'=>'Sheet music access subscription','taxable'=>true,'tax_code'=>$subscription_code,'amount_source'=>'addon','threshold_category'=>'digital_document_subscription');
    }
    return $profiles;
  }

  if ($product_type === 'masterclass') return array(array('key'=>'masterclass_live_virtual','label'=>'Live online masterclass','taxable'=>true,'tax_code'=>'txcd_20060045','amount_source'=>'base','threshold_category'=>'service_live_virtual'));
  return new WP_Error('unclassified_tax_product','This checkout has no approved Stripe Tax product classification.');
}

  private function mrm_build_tax_policy($address, $product_type, $addon_selected = false, $product_cfg = array(), $context = array()) {
    $address = $this->mrm_normalize_tax_address($address);
    $context = is_array($context) ? $context : array();
    $allow_incomplete_address = !empty($context['allow_incomplete_address']);
    $missing_address_fields = array();
    $required_fields = array('line1'=>'street address','city'=>'city','state'=>'state','postal_code'=>'ZIP code','country'=>'country');
    foreach ($required_fields as $field=>$label) if (trim((string)($address[$field] ?? '')) === '') $missing_address_fields[] = $label;
    if (!empty($missing_address_fields) && !$allow_incomplete_address) return array('ok'=>false,'code'=>'billing_address_required','message'=>'Please enter your complete billing address before checkout: '.implode(', ',$missing_address_fields).'.','address'=>$address,'missing_address_fields'=>$missing_address_fields,'profiles'=>array(),'should_collect_tax'=>false,'allow_subscription_automatic_tax'=>false);
    if (($address['country'] ?? 'US') !== 'US') return array('ok'=>false,'code'=>'unsupported_tax_country','message'=>'This checkout currently supports United States billing addresses only.','address'=>$address,'profiles'=>array(),'should_collect_tax'=>false,'allow_subscription_automatic_tax'=>false);
    $profiles = $this->mrm_get_tax_product_profiles($product_type,$addon_selected,$product_cfg,$context);
    if (is_wp_error($profiles)) return array('ok'=>false,'code'=>$profiles->get_error_code(),'message'=>$profiles->get_error_message(),'address'=>$address,'profiles'=>array(),'should_collect_tax'=>false,'allow_subscription_automatic_tax'=>false);
    $preview_incomplete = $allow_incomplete_address && !empty($missing_address_fields);
    return array('ok'=>true,'address'=>$address,'missing_address_fields'=>$missing_address_fields,'jurisdiction'=>array('country'=>(string)$address['country'],'state'=>(string)$address['state'],'exists'=>!$preview_incomplete,'stripe_controls_rollout'=>true),'profiles'=>$profiles,'policy_reason'=>$preview_incomplete?'billing_address_preview_incomplete':'stripe_tax_calculation_ready','policy_message'=>$preview_incomplete?'Sales tax is calculated after the complete billing address is entered.':'Sales tax is calculated from the billing address provided.','should_collect_tax'=>!$preview_incomplete,'allow_subscription_automatic_tax'=>!$preview_incomplete);
  }

  private function mrm_build_taxable_items_from_policy($policy, $base_amount_cents, $addon_amount_cents, $fundamentals_addon_amount_cents = 0) {
    $items = array();
    foreach ((array)($policy['profiles'] ?? array()) as $profile) {
      if (empty($profile['taxable'])) continue;
      $amount_source = (string)($profile['amount_source'] ?? 'base');
      if ($amount_source === 'addon') $amount_cents = (int)$addon_amount_cents;
      elseif ($amount_source === 'fundamentals_addon') $amount_cents = (int)$fundamentals_addon_amount_cents;
      else $amount_cents = (int)$base_amount_cents;
      if ($amount_cents <= 0) continue;
      $tax_code = sanitize_text_field($profile['tax_code'] ?? '');
      if ($tax_code === '') return new WP_Error('missing_tax_code','A taxable checkout item is missing its Stripe tax code.');
      $item = array('amount_cents'=>$amount_cents,'reference'=>sanitize_key($profile['key'] ?? 'item'),'tax_code'=>$tax_code,'threshold_category'=>sanitize_key($profile['threshold_category'] ?? 'other'));
      if (!empty($profile['performance_location'])) $item['performance_location'] = sanitize_text_field($profile['performance_location']);
      $items[] = $item;
    }
    if (empty($items)) return new WP_Error('missing_taxable_items','The checkout did not produce a valid taxable line item.');
    return $items;
  }

  private function mrm_build_tax_display_message($policy, $tax_result = array(), $tax_cents = 0) {
    if (empty($policy['should_collect_tax'])) {
      return (string)($policy['policy_message'] ?? 'Sales tax is calculated after billing state and ZIP are entered.');
    }

    $reason = (string)($tax_result['taxability_reason'] ?? '');

    if ((int)$tax_cents > 0) {
      return 'Sales tax calculated based on the billing address provided.';
    }

    if ($reason === 'not_collecting') {
      return 'We are not currently collecting tax in this jurisdiction.';
    }

    if (in_array($reason, array('not_subject_to_tax', 'product_exempt', 'zero_rated'), true)) {
      return 'No sales tax applies to this purchase for the billing address provided.';
    }

    if ($reason === 'missing_location_inputs') {
      return 'Sales tax is calculated after billing state and ZIP are entered.';
    }

    return 'No sales tax was applied for the billing address provided.';
  }

  private function mrm_should_enable_subscription_automatic_tax_from_meta($meta = array()) {
    $country = strtoupper(trim((string)($meta['mrm_tax_country'] ?? 'US')));
    $state = $this->mrm_normalize_state_code($meta['mrm_tax_state'] ?? '');

    return ($country === 'US' && $state !== '');
  }

  private function normalize_email_lines($raw) {
    $raw = (string)$raw;
    $lines = preg_split("/\r\n|\n|\r/", $raw);
    $out = array();
    foreach ($lines as $line) {
      $e = sanitize_email(trim($line));
      if ($e && is_email($e)) $out[strtolower($e)] = true;
    }
    return array_keys($out);
  }

  private function get_all_sheet_music_sku() {
    return $this->mrm_master_all_sheet_music_sku();
  }

  /**
   * Ensure that lesson default products are present AND valid.
   * If a default SKU already exists but has an invalid amount/shape, repair it.
   */
  private function ensure_default_products() {
    $all = $this->all_products();
    $changed = false;

    $defaults = array(
      'lesson_60_online' => array(
        'sku' => 'lesson_60_online',
        'label' => '60 Minute Online Lesson',
        'amount_cents' => 6200,
        'currency' => 'usd',
        'product_type' => 'lesson',
        'category' => '60_online',
        'active' => 1,
      ),
      'lesson_60_inperson' => array(
        'sku' => 'lesson_60_inperson',
        'label' => '60 Minute In-Person Lesson',
        'amount_cents' => 6700,
        'currency' => 'usd',
        'product_type' => 'lesson',
        'category' => '60_inperson',
        'active' => 1,
      ),
      'lesson_30_online' => array(
        'sku' => 'lesson_30_online',
        'label' => '30 Minute Online Lesson',
        'amount_cents' => 3800,
        'currency' => 'usd',
        'product_type' => 'lesson',
        'category' => '30_online',
        'active' => 1,
      ),
      'lesson_30_inperson' => array(
        'sku' => 'lesson_30_inperson',
        'label' => '30 Minute In-Person Lesson',
        'amount_cents' => 4300,
        'currency' => 'usd',
        'product_type' => 'lesson',
        'category' => '30_inperson',
        'active' => 1,
      ),
    );

    foreach ($defaults as $sku => $cfg) {
      if (!isset($all[$sku]) || !is_array($all[$sku])) {
        // Missing => add
        $all[$sku] = $cfg;
        $changed = true;
        continue;
      }

      // Exists => validate and repair only if needed
      $current = $all[$sku];

      $cur_amount = isset($current['amount_cents']) ? (int)$current['amount_cents'] : 0;
      $cur_currency = isset($current['currency']) ? (string)$current['currency'] : '';
      $cur_type = isset($current['product_type']) ? (string)$current['product_type'] : '';
      $cur_label = isset($current['label']) ? (string)$current['label'] : '';
      $cur_active = isset($current['active']) ? (int)$current['active'] : 0;

      $needs_repair =
        ($cur_amount <= 0) ||
        (!$cur_currency) ||
        (!$cur_type) ||
        (!$cur_label) ||
        ($cur_active !== 1); // keep lesson defaults active unless you explicitly disable them

      if ($needs_repair) {
        // Preserve any extra fields the admin may have added, but repair core shape.
        $all[$sku] = array_merge($current, $cfg);
        $changed = true;

      }
    }

    if ($changed) $this->save_products($all);
  }

  /* =========================================================
   * Helpers: hash/slug/sku
   * ======================================================= */

  private function email_hash($email) {
    $email = strtolower(trim((string)$email));
    $hash = hash('sha256', $email);
    if ($email && is_email($email)) {
      $this->remember_email_map($email, $hash);
    }
    return $hash;
  }

  private function remember_email_map($email, $hash) {
    $map = get_option('mrm_pay_hub_email_map', array());
    if (!is_array($map)) $map = array();
    if (!isset($map[$hash]) || $map[$hash] !== $email) {
      $map[$hash] = $email;
      update_option('mrm_pay_hub_email_map', $map);
    }
  }

  private function sanitize_sku($sku) {
    $sku = strtolower(trim((string)$sku));
    $sku = preg_replace('/[^a-z0-9\-_]/', '', $sku);
    return $sku;
  }

  private function mrm_parse_piece_sku_labels($sku) {
    $sku = $this->sanitize_sku((string)$sku);

    $out = array(
      'is_piece' => false,
      'piece_slug' => '',
      'piece_title' => '',
      'category_slug' => '',
      'category_label' => '',
      'display_label' => '',
    );

    if (!preg_match('/^piece-(.+)-(fundamentals|trombone-euphonium|tuba|complete-package)$/', $sku, $m)) {
      return $out;
    }

    $piece_slug = (string)$m[1];
    $category_slug = (string)$m[2];

    $category_map = array(
      'fundamentals' => 'Fundamentals',
      'trombone-euphonium' => 'Trombone/Euphonium',
      'tuba' => 'Tuba',
      'complete-package' => 'Complete Package',
    );

    $piece_title = ucwords(str_replace('-', ' ', $piece_slug));
    $category_label = $category_map[$category_slug] ?? ucwords(str_replace('-', ' ', $category_slug));

    $out['is_piece'] = true;
    $out['piece_slug'] = $piece_slug;
    $out['piece_title'] = $piece_title;
    $out['category_slug'] = $category_slug;
    $out['category_label'] = $category_label;
    $out['display_label'] = $piece_title . ' — ' . $category_label;

    return $out;
  }

  private function mrm_sheet_music_manual_access_label($sku, $product = array()) {
    $sku = $this->sanitize_sku((string)$sku);

    if ($sku === 'all-sheet-music') {
      return 'All Sheet Music Access';
    }

    if ($sku === 'all-piece-products-instructors') {
      return 'Instructor-Wide Piece Access';
    }

    $parsed = $this->mrm_parse_piece_sku_labels($sku);

    if (!empty($parsed['is_piece']) && !empty($parsed['display_label'])) {
      return (string)$parsed['display_label'];
    }

    $product = is_array($product) ? $product : array();

    $label = trim((string)($product['label'] ?? ''));
    if ($label === '') {
      $label = trim((string)($product['title'] ?? ''));
    }
    if ($label === '') {
      $label = trim((string)($product['name'] ?? ''));
    }
    if ($label === '') {
      $label = $sku;
    }

    return $label;
  }

  private function mrm_sheet_music_manual_access_sort_key($sku, $label) {
    $sku = $this->sanitize_sku((string)$sku);
    $parsed = $this->mrm_parse_piece_sku_labels($sku);

    $category_order = array(
      'fundamentals' => '1',
      'trombone-euphonium' => '2',
      'tuba' => '3',
      'complete-package' => '4',
    );

    if (!empty($parsed['is_piece'])) {
      $piece_title = strtolower((string)($parsed['piece_title'] ?? ''));
      $category_slug = (string)($parsed['category_slug'] ?? '');
      $order = $category_order[$category_slug] ?? '9';

      return $piece_title . '|' . $order . '|' . strtolower((string)$label);
    }

    return strtolower((string)$label);
  }


  private function mrm_get_piece_page_url_from_sku($sku) {
    $labels = $this->mrm_parse_piece_sku_labels($sku);
    $piece_slug = sanitize_title((string)($labels['piece_slug'] ?? ''));

    if ($piece_slug === '') {
      return '';
    }

    return home_url('/' . $piece_slug . '/');
  }

  private function mrm_email_has_direct_sheet_music_product_access($email, $sku) {
    $email = sanitize_email((string)$email);
    $sku = $this->sanitize_sku((string)$sku);

    if (!$email || !is_email($email) || !$sku) {
      return false;
    }

    /* The visible mrm_sheet_music_access ledger is the only per-piece authority. */
    return $this->has_sheet_music_access($this->email_hash($email), $sku);
  }

  private function mrm_email_already_has_piece_or_package_access($email, $sku) {
    $email = sanitize_email((string)$email);
    $sku = $this->sanitize_sku((string)$sku);
    if (!$email || !is_email($email) || !$sku) return false;
    if ($this->mrm_email_has_direct_sheet_music_product_access($email, $sku)) return true;
    $target = $this->get_product($sku);
    if (!is_array($target)) return false;
    $category = sanitize_key((string)($target['category'] ?? ''));
    if ($category === 'complete-package') return false;
    $stem = $this->mrm_piece_stem_from_offer_slug($sku, $category);
    if ($stem === '') return false;
    foreach ($this->all_products() as $candidate_sku => $candidate) {
      if (!is_array($candidate) || empty($candidate['active']) || sanitize_key((string)($candidate['product_type'] ?? '')) !== 'sheet_music' || sanitize_key((string)($candidate['category'] ?? '')) !== 'complete-package') continue;
      $candidate_sku = $this->sanitize_sku($candidate_sku);
      if ($candidate_sku && $this->mrm_piece_stem_from_offer_slug($candidate_sku, 'complete-package') === $stem && $this->mrm_email_has_direct_sheet_music_product_access($email, $candidate_sku)) return true;
    }
    return false;
  }

  private function mrm_get_authoritative_fundamentals_ownership_match($email, $packet_sku) {
    $result = array(
      'owned' => false,
      'ownership_source' => '',
      'ownership_sku' => '',
    );

    $email = strtolower(sanitize_email((string)$email));
    $packet_sku = $this->sanitize_sku((string)$packet_sku);

    if (!$email || !is_email($email) || !$packet_sku) {
      return $result;
    }

    $email_hash = $this->email_hash($email);

    /*
     * Direct database entitlement for the exact packet.
     */
    if ($this->has_sheet_music_access($email_hash, $packet_sku)) {
      return array(
        'owned' => true,
        'ownership_source' => 'fundamental_packet_ledger',
        'ownership_sku' => $packet_sku,
      );
    }

    $packet_product = $this->get_product($packet_sku);
    if (!is_array($packet_product)) {
      return $result;
    }

    $packet_stem = $this->mrm_piece_stem_from_offer_slug($packet_sku, 'fundamentals');
    if ($packet_stem === '') {
      return $result;
    }

    /* A matching Complete Package entitlement also proves packet ownership. */
    foreach ($this->all_products() as $candidate_sku => $candidate_product) {
      if (!is_array($candidate_product) || empty($candidate_product['active'])) {
        continue;
      }
      if (sanitize_key((string)($candidate_product['product_type'] ?? '')) !== 'sheet_music') {
        continue;
      }
      if (sanitize_key((string)($candidate_product['category'] ?? '')) !== 'complete-package') {
        continue;
      }

      $candidate_sku = $this->sanitize_sku($candidate_sku);
      if (!$candidate_sku) {
        continue;
      }
      $candidate_stem = $this->mrm_piece_stem_from_offer_slug($candidate_sku, 'complete-package');
      if ($candidate_stem !== $packet_stem) {
        continue;
      }
      if ($this->has_sheet_music_access($email_hash, $candidate_sku)) {
        return array(
          'owned' => true,
          'ownership_source' => 'complete_package_ledger',
          'ownership_sku' => $candidate_sku,
        );
      }

    }

    return $result;
  }

  private function mrm_get_fundamentals_addon_offer($base_sku) {
    $empty = array('available'=>false,'selected'=>false,'sku'=>'','label'=>'','regular_amount_cents'=>0,'offer_amount_cents'=>0,'savings_cents'=>0);
    $base_sku = $this->sanitize_sku($base_sku);
    $base = $this->get_product($base_sku);
    if (!$base_sku || !is_array($base) || empty($base['active']) || sanitize_key($base['product_type'] ?? '') !== 'sheet_music') return $empty;
    $category = sanitize_key($base['category'] ?? '');
    if (!in_array($category, array('tuba','trombone-euphonium'), true) || empty($base['fundamentals_addon_enabled'])) return $empty;
    $addon_sku = $this->sanitize_sku($base['fundamentals_addon_sku'] ?? '');
    $addon = $this->get_product($addon_sku);
    if (!$addon_sku || $addon_sku === $base_sku || !is_array($addon) || empty($addon['active']) || sanitize_key($addon['product_type'] ?? '') !== 'sheet_music' || sanitize_key($addon['category'] ?? '') !== 'fundamentals') return $empty;
    if (strtolower((string)($base['currency'] ?? 'usd')) !== strtolower((string)($addon['currency'] ?? 'usd'))) return $empty;
    if ($this->mrm_piece_stem_from_offer_slug($base_sku,$category) === '' || $this->mrm_piece_stem_from_offer_slug($base_sku,$category) !== $this->mrm_piece_stem_from_offer_slug($addon_sku,'fundamentals')) return $empty;
    $regular=max(0,(int)($addon['amount_cents']??0)); $offer=max(0,(int)($base['fundamentals_addon_amount_cents']??500));
    if ($regular<=0 || $offer<=0 || $offer>$regular) return $empty;
    return array('available'=>true,'selected'=>false,'sku'=>$addon_sku,'label'=>sanitize_text_field((string)($addon['label']??'Fundamental Packet')),'regular_amount_cents'=>$regular,'offer_amount_cents'=>$offer,'savings_cents'=>$regular-$offer);
  }

  private function mrm_resolve_fundamentals_addon_selection($base_sku, $requested, $email='') {
    $offer=$this->mrm_get_fundamentals_addon_offer($base_sku);
    if (!$requested) return $offer;
    if (empty($offer['available'])) return new WP_Error('fundamentals_addon_not_available','The Fundamental Packet add-on is not available for this product.');
    $email=sanitize_email($email);
    if ($email && is_email($email)) {
      $ownership = $this->mrm_get_authoritative_fundamentals_ownership_match($email, (string)$offer['sku']);
      if (is_wp_error($ownership)) {
        return $ownership;
      }
      if (!empty($ownership['owned'])) {
        return new WP_Error(
          'fundamentals_addon_already_owned',
          'This email already has access to the Fundamental Packet, so it has not been added to the order.',
          array(
            'ownership_source' => sanitize_key((string)($ownership['ownership_source'] ?? '')),
            'ownership_sku' => $this->sanitize_sku((string)($ownership['ownership_sku'] ?? '')),
          )
        );
      }
    }
    $offer['selected']=true; return $offer;
  }

  private function slugify($text) {
    $text = (string)$text;
    $text = remove_accents($text);
    $text = strtolower($text);
    $text = preg_replace('/[^\p{L}\p{N}]+/u', '-', $text);
    $text = preg_replace('/-+/', '-', $text);
    $text = trim($text, '-');
    return $text ?: 'untitled';
  }

  /**
   * Sheet music SKU generator: piece-<title>-<type>.  The type can be
   * fundamentals, trombone-euphonium, tuba or complete-package.  If the base
   * SKU already exists, a numeric suffix is added to make it unique.
   */
  private function generate_sheet_music_sku($title, $type, $current_sku = '') {
    $type = strtolower(trim((string)$type));
    $allowed = array('fundamentals','trombone-euphonium','tuba','complete-package');
    if (!in_array($type, $allowed, true)) $type = 'fundamentals';

    $base_title = $this->slugify($title);
    $base = 'piece-' . $base_title . '-' . $type;

    $sku = $base;
    $all = $this->all_products();
    $current_sku = $this->sanitize_sku($current_sku);
    if ($current_sku && isset($all[$current_sku])) {
      unset($all[$current_sku]);
    }
    $i = 2;
    while (isset($all[$sku])) {
      $sku = $base . '-' . $i;
      $i++;
      if ($i > 999) break;
    }
    return $sku;
  }

  /* =========================================================
   * Stripe HTTP (no composer dependency)
   * ======================================================= */

  private function mrm_stripe_tax_headers() {
    /*
     * Stable Stripe Tax endpoints must receive only the stable
     * API version. Do not append the PaymentIntent Tax beta token
     * to Tax Settings, registrations, calculations, or Tax
     * Transactions.
     */
    return array(
      'Stripe-Version' =>
        self::STRIPE_TAX_API_VERSION,
    );
  }


  private function mrm_stripe_tax_location_headers() {
    return array(
      'Stripe-Version' =>
        self::STRIPE_TAX_LOCATION_API_VERSION,
    );
  }


  private function mrm_stripe_tax_calculation_headers(
    $has_performance_location = false
  ) {
    /*
     * Performance locations are now documented in the stable
     * Tax Calculation API.
     */
    return $this->mrm_stripe_tax_headers();
  }


  private function stripe_api_request($method, $path, $params = array(), $extra_headers = array()) {
    $key = $this->secret_key();
    if (!$key) return new WP_Error('stripe_not_configured', 'Stripe secret key is not configured.');

    $url = 'https://api.stripe.com' . $path;

    $headers = array(
      'Authorization' => 'Bearer ' . $key,
      'Content-Type'  => 'application/x-www-form-urlencoded',
      'Stripe-Version' => self::STRIPE_CORE_API_VERSION,
    );

    if (!empty($extra_headers) && is_array($extra_headers)) {
      $headers = array_merge($headers, $extra_headers);
    }

    $args = array(
      'method'  => strtoupper($method),
      'timeout' => 30,
      'headers' => $headers,
    );

    if ($args['method'] === 'GET') {
      if (!empty($params)) $url = add_query_arg($params, $url);
    } else {
      $args['body'] = http_build_query($params, '', '&');
    }

    $res = wp_remote_request($url, $args);
    if (is_wp_error($res)) return $res;

    $code = (int) wp_remote_retrieve_response_code($res);
    $body = (string) wp_remote_retrieve_body($res);
    $json = json_decode($body, true);

    if ($code < 200 || $code >= 300 || !is_array($json)) {
      $msg = is_array($json) && isset($json['error']['message']) ? $json['error']['message'] : 'Stripe request failed.';
      return new WP_Error('stripe_error', $msg, array('http_code'=>$code,'body'=>$body));
    }

    return $json;
  }


  private function mrm_tax_cents_for_addon($address) {
    $addr = is_array($address) ? $address : array();
    $state = strtoupper(sanitize_text_field((string)($addr['state'] ?? '')));
    $zip = sanitize_text_field((string)($addr['postal_code'] ?? ''));
    $country = strtoupper(sanitize_text_field((string)($addr['country'] ?? 'US')));

    if (!$state || !$zip) return 0;

    $payload = array(
      'currency' => 'usd',
      'customer_details[address][state]' => $state,
      'customer_details[address][postal_code]' => $zip,
      'customer_details[address][country]' => $country,
      'line_items[0][amount]' => 500,
      'line_items[0][quantity]' => 1,
      'line_items[0][reference]' => 'sheet_music_addon'
    );

    $calc = $this->stripe_api_request('POST', '/v1/tax/calculations', $payload);
    if (is_wp_error($calc)) return 0;

    $tax = isset($calc['tax_amount_exclusive']) ? (int)$calc['tax_amount_exclusive'] : 0;
    return max(0, $tax);
  }

  /**
   * Calculate tax for a set of line items using Stripe Tax (custom flow).
   * Each line item: ['amount_cents'=>int, 'reference'=>string, 'tax_code'=>string]
   * Returns array: ['ok'=>bool,'tax_cents'=>int,'amount_total_cents'=>int,'calculation_id'=>string,'line_items'=>array]
   */
private function mrm_tax_summarize_calculation_line(
  $line,
  $fallback_address = array()
) {
  if (!is_array($line)) {
    return new WP_Error('tax_calculation_line_invalid','Stripe returned an invalid tax calculation line.');
  }

  $fallback_address = $this->mrm_normalize_tax_address(is_array($fallback_address) ? $fallback_address : array());
  $line_amount = max(0, (int)($line['amount'] ?? 0));
  $state = '';
  $country = '';
  $sourcing = '';
  $state_reason = '';
  $first_reason = '';
  $taxable_sales_cents = 0;

  foreach ((array)($line['tax_breakdown'] ?? array()) as $breakdown) {
    $reason = sanitize_key($breakdown['taxability_reason'] ?? '');
    if ($first_reason === '' && $reason !== '') $first_reason = $reason;
    $taxable_sales_cents = max($taxable_sales_cents, max(0, (int)($breakdown['taxable_amount'] ?? 0)));
    $jurisdiction = is_array($breakdown['jurisdiction'] ?? null) ? $breakdown['jurisdiction'] : array();
    $jurisdiction_state = $this->mrm_normalize_state_code($jurisdiction['state'] ?? '');
    $jurisdiction_country = strtoupper(sanitize_text_field($jurisdiction['country'] ?? ''));
    $jurisdiction_sourcing = sanitize_key($breakdown['sourcing'] ?? '');
    if ($jurisdiction_state !== '') {
      if ($state !== '' && $state !== $jurisdiction_state) return new WP_Error('tax_calculation_line_state_conflict','Stripe returned conflicting state jurisdictions for one tax line.');
      $state = $jurisdiction_state;
      if ($jurisdiction_country !== '') $country = $jurisdiction_country;
      if ($jurisdiction_sourcing !== '') $sourcing = $jurisdiction_sourcing;
      if ($reason !== '') $state_reason = $reason;
    }
  }

  $performance_location = sanitize_text_field($line['performance_location'] ?? '');
  if ($performance_location !== '' && $state === '') return new WP_Error('performance_tax_state_missing','Stripe did not return a state jurisdiction for a performance-location tax line.');
  if ($state === '') $state = $this->mrm_normalize_state_code($fallback_address['state'] ?? '');
  if ($country === '') $country = strtoupper(sanitize_text_field($fallback_address['country'] ?? 'US'));
  $taxability_reason = $state_reason !== '' ? $state_reason : $first_reason;
  if ($taxable_sales_cents <= 0 && !in_array($taxability_reason, array('customer_exempt','not_subject_to_tax','product_exempt'), true)) $taxable_sales_cents = $line_amount;
  $taxable_sales_cents = min($line_amount, max(0, $taxable_sales_cents));

  return array('jurisdiction_state'=>$state,'jurisdiction_country'=>$country,'sourcing'=>$sourcing,'taxability_reason'=>$taxability_reason,'taxable_sales_cents'=>$taxable_sales_cents,'performance_location'=>$performance_location);
}

private function mrm_tax_encode_line_items_metadata($line_items) {
  $compact_lines = array();

  foreach ((array)$line_items as $line) {
    if (!is_array($line)) continue;

    $reference = sanitize_key((string)($line['reference'] ?? ''));
    if ($reference === '') continue;

    /*
     * Compact Stripe metadata schema:
     * r = reference; a = pre-tax item amount; t = tax amount;
     * q = taxability reason; x = taxable sales amount;
     * s = jurisdiction state; o = sourcing; c = Stripe tax code.
     */
    $compact_lines[] = array(
      'r' => $reference,
      'a' => max(0, (int)($line['amount_cents'] ?? 0)),
      't' => max(0, (int)($line['tax_cents'] ?? 0)),
      'q' => sanitize_key((string)($line['taxability_reason'] ?? '')),
      'x' => max(0, (int)($line['taxable_sales_cents'] ?? 0)),
      's' => $this->mrm_normalize_state_code($line['jurisdiction_state'] ?? ''),
      'o' => sanitize_key((string)($line['sourcing'] ?? '')),
      'c' => sanitize_text_field((string)($line['tax_code'] ?? '')),
    );
  }

  if (empty($compact_lines)) return new WP_Error('stripe_tax_lines_metadata_empty', 'The Stripe Tax line summary could not be created.');

  $json = wp_json_encode($compact_lines);
  if (!is_string($json) || $json === '') return new WP_Error('stripe_tax_lines_metadata_encode_failed', 'The Stripe Tax line summary could not be encoded.');

  /* Keep a safety margin beneath Stripe's metadata-value capacity. */
  if (strlen($json) > 450) return new WP_Error('stripe_tax_lines_metadata_too_large', 'The compact Stripe Tax line summary exceeds the safe metadata limit.');

  return $json;
}

private function mrm_tax_decode_line_items_metadata($json) {
  if (is_array($json)) {
    $decoded = $json;
  } else {
    $json = trim((string)$json);
    if ($json === '') return array();
    $decoded = json_decode($json, true);
  }

  if (!is_array($decoded)) return array();

  $normalized_lines = array();
  foreach ($decoded as $line) {
    if (!is_array($line)) continue;

    /* New compact format. */
    if (array_key_exists('r', $line)) {
      $reference = sanitize_key((string)($line['r'] ?? ''));
      if ($reference === '') continue;
      $normalized_lines[] = array(
        'reference' => $reference,
        'amount_cents' => max(0, (int)($line['a'] ?? 0)),
        'tax_cents' => max(0, (int)($line['t'] ?? 0)),
        'taxability_reason' => sanitize_key((string)($line['q'] ?? '')),
        'taxable_sales_cents' => max(0, (int)($line['x'] ?? 0)),
        'jurisdiction_state' => $this->mrm_normalize_state_code($line['s'] ?? ''),
        'sourcing' => sanitize_key((string)($line['o'] ?? '')),
        'tax_code' => sanitize_text_field((string)($line['c'] ?? '')),
      );
      continue;
    }

    /* Old full-length format, retained for existing Payment Intents and orders. */
    $reference = sanitize_key((string)($line['reference'] ?? ''));
    if ($reference === '') continue;
    $normalized_lines[] = array(
      'reference' => $reference,
      'amount_cents' => max(0, (int)($line['amount_cents'] ?? 0)),
      'tax_cents' => max(0, (int)($line['tax_cents'] ?? 0)),
      'taxability_reason' => sanitize_key((string)($line['taxability_reason'] ?? '')),
      'taxable_sales_cents' => max(0, (int)($line['taxable_sales_cents'] ?? 0)),
      'jurisdiction_state' => $this->mrm_normalize_state_code($line['jurisdiction_state'] ?? ''),
      'sourcing' => sanitize_key((string)($line['sourcing'] ?? '')),
      'tax_code' => sanitize_text_field((string)($line['tax_code'] ?? '')),
    );
  }

  return $normalized_lines;
}

private function mrm_tax_calculate_for_items($address, $line_items, $currency = 'usd', $customer_id = '') {
  $customer_id = sanitize_text_field((string)$customer_id);
  $address = $this->mrm_normalize_tax_address($address);
  if ($customer_id === '') foreach (array('country','line1','city','state','postal_code') as $required) if (trim((string)($address[$required] ?? '')) === '') return new WP_Error('tax_address_incomplete','Please enter your complete billing address.');
  if (empty($line_items) || !is_array($line_items)) return new WP_Error('tax_line_items_missing','Sales tax could not be calculated because no line items were provided.');
  $items=array(); $subtotal=0; $has_performance_location=false;
  foreach ($line_items as $line_item) {
    $amount=absint($line_item['amount_cents'] ?? 0); $tax_code=sanitize_text_field($line_item['tax_code'] ?? '');
    if ($amount <= 0) continue;
    if ($tax_code === '') return new WP_Error('tax_code_missing','A checkout item is missing its Stripe tax code.');
    $reference=sanitize_key($line_item['reference'] ?? ''); if ($reference === '') $reference='item_'.count($items);
    $stripe_item=array('amount'=>$amount,'reference'=>$reference,'tax_code'=>$tax_code,'tax_behavior'=>'exclusive');
    if (!empty($line_item['performance_location'])) { $stripe_item['performance_location']=sanitize_text_field($line_item['performance_location']); $has_performance_location=true; }
    $subtotal += $amount; $items[]=$stripe_item;
  }
  if (empty($items)) return new WP_Error('tax_items_empty','Sales tax could not be calculated for this checkout.');
  $payload=array('currency'=>strtolower($currency),'line_items'=>$items,'expand[0]'=>'line_items','expand[1]'=>'line_items.data.tax_breakdown');
  if ($customer_id !== '') $payload['customer']=$customer_id; else { $stripe_address=array('country'=>$address['country'],'line1'=>$address['line1'],'city'=>$address['city'],'state'=>$address['state'],'postal_code'=>$address['postal_code']); if ($address['line2'] !== '') $stripe_address['line2']=$address['line2']; $payload['customer_details']=array('address_source'=>'billing','address'=>$stripe_address); }
  $calculation=$this->stripe_api_request('POST','/v1/tax/calculations',$payload,$this->mrm_stripe_tax_calculation_headers($has_performance_location));
  if (is_wp_error($calculation)) { $this->stripe_debug_log('stripe tax calculation failed', array('message'=>$calculation->get_error_message())); return new WP_Error('stripe_tax_calculation_failed','Sales tax could not be calculated. Please verify your billing address and try again.'); }
  $calculation_id=sanitize_text_field($calculation['id'] ?? ''); if ($calculation_id === '') return new WP_Error('stripe_tax_calculation_missing','Stripe did not return a valid tax calculation.');
  $amount_total_cents=(int)($calculation['amount_total'] ?? 0); if ($amount_total_cents <= 0) return new WP_Error('stripe_tax_total_invalid','Stripe returned an invalid payment total.');
  $tax_cents=max(0,(int)($calculation['tax_amount_exclusive'] ?? 0));
  $customer_details=is_array($calculation['customer_details'] ?? null) ? $calculation['customer_details'] : array();
  $fallback_address=is_array($customer_details['address'] ?? null) ? $customer_details['address'] : $address;
  $out_items=array(); $overall_reason='';
  foreach ((array)($calculation['line_items']['data'] ?? array()) as $line) {
    $summary=$this->mrm_tax_summarize_calculation_line($line,$fallback_address); if (is_wp_error($summary)) return $summary;
    if ($overall_reason === '' && !empty($summary['taxability_reason'])) $overall_reason=$summary['taxability_reason'];
    $out_items[]=array('reference'=>sanitize_key($line['reference'] ?? ''),'amount_cents'=>(int)($line['amount'] ?? 0),'tax_cents'=>(int)($line['amount_tax'] ?? 0),'taxability_reason'=>sanitize_key($summary['taxability_reason'] ?? ''),'taxable_sales_cents'=>max(0,(int)($summary['taxable_sales_cents'] ?? 0)),'jurisdiction_state'=>$this->mrm_normalize_state_code($summary['jurisdiction_state'] ?? ''),'sourcing'=>sanitize_key($summary['sourcing'] ?? ''),'tax_code'=>sanitize_text_field($line['tax_code'] ?? ''));
  }
  if (empty($out_items)) return new WP_Error('stripe_tax_lines_missing','Stripe returned no expanded tax calculation lines.');
  $metadata_lines_json = $this->mrm_tax_encode_line_items_metadata($out_items);
  if (is_wp_error($metadata_lines_json)) return $metadata_lines_json;
  return array('ok'=>true,'subtotal_cents'=>$subtotal,'tax_cents'=>$tax_cents,'amount_total_cents'=>$amount_total_cents,'calculation_id'=>$calculation_id,'line_items'=>$out_items,'metadata_line_items_json'=>$metadata_lines_json,'taxability_reason'=>$overall_reason,'customer_details'=>$customer_details);
}

  private function
  mrm_prepare_payment_intent_metadata_for_stripe(
    $metadata
  ) {
    $metadata =
      is_array($metadata)
        ? $metadata
        : array();

    /*
     * These fields remain in the local WordPress order but do
     * not need separate Stripe Payment Intent metadata slots.
     */

    /*
     * mrm_tax_cents is authoritative.
     *
     * mrm_addon_tax_cents remains only as a local compatibility
     * value for older WordPress order readers.
     */
    unset(
      $metadata[
        'mrm_addon_tax_cents'
      ]
    );

    $product_type =
      sanitize_key(
        (string)(
          $metadata[
            'mrm_product_type'
          ] ?? ''
        )
      );

    $order_id =
      absint(
        $metadata[
          'mrm_order_id'
        ] ?? 0
      );

    /*
     * Local lesson and sheet-music checkouts have a complete
     * metadata_json record stored in WordPress.
     *
     * Remove display-only, compatibility, and duplicated fields
     * from the Stripe-specific copy. The local order retains
     * every one of these values.
     *
     * External taxed Payment Intents without mrm_order_id are
     * excluded from this reduction because they may rely on
     * their Payment Intent metadata as the primary record.
     */
    $is_local_order_checkout = (
      $order_id > 0 &&
      in_array(
        $product_type,
        array(
          'lesson',
          'sheet_music',
        ),
        true
      )
    );

    if ($is_local_order_checkout) {
      $local_only_keys =
        array(
          'mrm_tax_policy_message',
          'mrm_tax_rollout_mode',
          'mrm_tax_calculation_requested',
          'mrm_tax_policy_reason',
        );

      if (array_key_exists('mrm_tax_state', $metadata)) {
        $local_only_keys[] = 'mrm_customer_state';
      }

      if (array_key_exists('mrm_tax_country', $metadata)) {
        $local_only_keys[] = 'mrm_customer_country';
      }

      foreach ($local_only_keys as $local_only_key) {
        unset($metadata[$local_only_key]);
      }
    }

    /*
     * These keys can be added after Payment Intent creation.
     *
     * mrm_tax_transaction_id:
     * Added after payment succeeds and the stable Stripe Tax
     * Transaction is committed.
     *
     * Subscriber acknowledgement keys:
     * These can be added during final preconfirmation when a
     * subscription becomes active after the Payment Intent was
     * originally created.
     */
    $future_metadata_keys = array('mrm_tax_transaction_id');

    $source_flow = sanitize_key((string)($metadata['mrm_terms_source_flow'] ?? ''));

    if ($product_type === 'sheet_music' && $source_flow === 'piece_product_purchase') {
      $future_metadata_keys[] = 'mrm_sub_purchase_ack';
      $future_metadata_keys[] = 'mrm_sub_purchase_id';
      $future_metadata_keys[] = 'mrm_sub_purchase_ack_at';
    }

    /*
     * Reserve only keys that are not already present.
     *
     * When the subscriber acknowledgement was recorded during
     * initial Payment Intent creation, those three keys already
     * count toward the current metadata total and do not need
     * to be reserved again.
     */
    $reserved_key_count = 0;
    foreach ($future_metadata_keys as $future_key) {
      if (!array_key_exists($future_key, $metadata)) $reserved_key_count++;
    }

    $maximum_initial_key_count = 50 - $reserved_key_count;

    /*
     * Sanitize keys exactly once before sending them to Stripe.
     * Also detect a collision where two original keys sanitize
     * into the same final key.
     */
    $prepared_metadata = array();
    foreach ($metadata as $key => $value) {
      $prepared_key = preg_replace('/[^a-zA-Z0-9_\-]/', '_', (string)$key);
      $prepared_key = (string)$prepared_key;

      if ($prepared_key === '') {
        return new WP_Error('payment_intent_metadata_key_invalid', 'The payment metadata contains an empty Stripe metadata key.');
      }

      if (strlen($prepared_key) > 40) {
        return new WP_Error(
          'payment_intent_metadata_key_too_long',
          'The payment metadata key "' . sanitize_text_field($prepared_key) . '" exceeds the Stripe metadata key-length limit.'
        );
      }

      if (array_key_exists($prepared_key, $prepared_metadata)) {
        return new WP_Error(
          'payment_intent_metadata_key_collision',
          'Two payment metadata keys resolve to the same Stripe metadata key: "' . sanitize_text_field($prepared_key) . '".'
        );
      }

      $prepared_metadata[$prepared_key] = (string)$value;
    }

    $current_key_count = count($prepared_metadata);
    if ($current_key_count > $maximum_initial_key_count) {
      return new WP_Error(
        'payment_intent_metadata_capacity_exceeded',
        sprintf(
          'The payment metadata requires %1$d keys, but checkout must use no more than %2$d keys so later payment and tax metadata can be recorded.',
          $current_key_count,
          $maximum_initial_key_count
        ),
        array(
          'current_key_count' => $current_key_count,
          'maximum_initial_key_count' => $maximum_initial_key_count,
          'reserved_key_count' => $reserved_key_count,
          'reserved_keys' => array_values($future_metadata_keys),
        )
      );
    }

    return $prepared_metadata;
  }

  private function stripe_create_payment_intent($amount_cents, $currency, $metadata, $description = '', $extra_params = array(), $payment_method_types = array('card'), $tax_calculation_id = '', $idempotency_key = '') {
    /*
     * Add the calculation ID before validating metadata
     * capacity so the final key count includes it.
     */
    $tax_calculation_id = sanitize_text_field((string)$tax_calculation_id);
    if ($tax_calculation_id !== '') {
      $metadata = is_array($metadata) ? $metadata : array();
      $metadata['mrm_tax_calculation_id'] = $tax_calculation_id;
    }

    $metadata = $this->mrm_prepare_payment_intent_metadata_for_stripe($metadata);
    if (is_wp_error($metadata)) return $metadata;

    $params = array(
      'amount' => (int)$amount_cents,
      'currency' => $currency ?: 'usd',
    );

    if ($description) {
      $params['description'] = $description;
    }

    $idx = 0;
    foreach ((array)$payment_method_types as $pm_type) {
      $pm_type = sanitize_text_field((string)$pm_type);
      if ($pm_type === '') continue;
      $params["payment_method_types[{$idx}]"] = $pm_type;
      $idx++;
    }

    if ($idx <= 0) {
      $params['payment_method_types[0]'] = 'card';
    }

    // Allow additional Stripe params (customer, setup_future_usage, etc.)
    if (is_array($extra_params)) {
      foreach ($extra_params as $k => $v) {
        if ($v === null || $v === '') continue;
        $params[(string)$k] = (string)$v;
      }
    }

    foreach ($metadata as $key => $value) {
      /*
       * Keys were already sanitized and capacity-checked by
       * mrm_prepare_payment_intent_metadata_for_stripe().
       */
      $params["metadata[{$key}]"] = (string)$value;
    }

    $extra_headers = array();
    $idempotency_key = sanitize_text_field((string)$idempotency_key);
    if ($idempotency_key !== '') $extra_headers['Idempotency-Key'] = $idempotency_key;
    return $this->stripe_api_request('POST', '/v1/payment_intents', $params, $extra_headers);
  }

  private function stripe_retrieve_payment_intent($pi_id) {
    return $this->stripe_api_request('GET', '/v1/payment_intents/' . rawurlencode((string)$pi_id));
  }

  private function mrm_cancel_pending_piece_checkout($order, $payment_intent, $reason) {
    if (!is_array($order) || empty($order['id']) || !is_array($payment_intent)) {
      return new WP_Error('piece_checkout_cancel_failed', 'The obsolete payment session could not be invalidated safely.');
    }
    $payment_intent_id = sanitize_text_field((string)($payment_intent['id'] ?? ''));
    $status = sanitize_key((string)($payment_intent['status'] ?? ''));
    if ($payment_intent_id === '') {
      return new WP_Error('piece_checkout_cancel_failed', 'The obsolete payment session does not contain a valid Payment Intent ID.');
    }
    if ($status === 'succeeded') {
      return new WP_Error('checkout_request_already_completed', 'This checkout request has already been paid.');
    }
    $status_metadata = array(
      'mrm_checkout_invalidated_reason' => sanitize_key((string)$reason),
      'mrm_checkout_invalidated_at' => current_time('mysql'),
    );
    if ($status === 'canceled') {
      $this->update_order_status_from_pi(
        $payment_intent_id,
        'canceled',
        'canceled',
        $status_metadata
      );

      $promo_released =
        $this
          ->mrm_release_pending_promo_redemption(
            absint($order['id']),
            $payment_intent_id
          );

      if (!$promo_released) {
        return new WP_Error(
          'piece_checkout_promo_release_failed',
          'The obsolete payment session was canceled, but its promotional-code reservation could not be released.'
        );
      }

      return true;
    }
    $canceled = $this->stripe_api_request(
      'POST',
      '/v1/payment_intents/' . rawurlencode($payment_intent_id) . '/cancel',
      array('cancellation_reason' => 'abandoned')
    );
    if (is_wp_error($canceled)) {
      $this->stripe_debug_log('Obsolete sheet-music Payment Intent cancellation failed.', array(
        'order_id' => absint($order['id']),
        'payment_intent_id' => $payment_intent_id,
        'reason' => sanitize_key((string)$reason),
        'message' => $canceled->get_error_message(),
      ));
      return new WP_Error(
        'piece_checkout_cancel_failed',
        'Existing access was detected, but the old payment session could not be invalidated safely. No payment has been submitted. Please close checkout and try again.',
        array('payment_intent_id' => $payment_intent_id)
      );
    }
    $this->update_order_status_from_pi(
      $payment_intent_id,
      'canceled',
      sanitize_key(
        (string)(
          $canceled['status'] ??
          'canceled'
        )
      ),
      $status_metadata
    );

    $promo_released =
      $this
        ->mrm_release_pending_promo_redemption(
          absint($order['id']),
          $payment_intent_id
        );

    if (!$promo_released) {
      return new WP_Error(
        'piece_checkout_promo_release_failed',
        'The obsolete payment session was canceled, but its promotional-code reservation could not be released.'
      );
    }

    return true;
  }

  private function stripe_retrieve_charge($charge_id) {
    $charge_id = sanitize_text_field((string)$charge_id);

    if ($charge_id === '') {
      return new WP_Error('stripe_missing_charge_id', 'Missing Stripe charge id.');
    }

    return $this->stripe_api_request('GET', '/v1/charges/' . rawurlencode($charge_id));
  }


  private function stripe_retrieve_refund($refund_id) {
    $refund_id = sanitize_text_field($refund_id);
    if ($refund_id === '') return new WP_Error('missing_refund_id', 'Missing Stripe Refund ID.');
    return $this->stripe_api_request('GET', '/v1/refunds/' . rawurlencode($refund_id));
  }

  private function mrm_stripe_list_all_refunds_for_charge($charge_id) {
    $charge_id = sanitize_text_field($charge_id);
    if ($charge_id === '') return new WP_Error('missing_refund_charge_id', 'The Charge ID required for refund reconciliation is missing.');
    $refunds = array(); $starting_after = ''; $guard = 0;
    do {
      if (++$guard > 1000) return new WP_Error('refund_pagination_limit', 'Stripe refund pagination exceeded the safety limit.');
      $params = array('charge'=>$charge_id,'limit'=>100);
      if ($starting_after !== '') $params['starting_after'] = $starting_after;
      $response = $this->stripe_api_request('GET', '/v1/refunds', $params);
      if (is_wp_error($response)) return $response;
      if (!isset($response['data']) || !is_array($response['data'])) return new WP_Error('refund_list_invalid', 'Stripe returned an invalid refund list.');
      $page = $response['data'];
      foreach ($page as $refund) { $refund_id = sanitize_text_field($refund['id'] ?? ''); if ($refund_id === '') return new WP_Error('refund_list_id_missing', 'Stripe returned a Refund without an ID.'); $refunds[$refund_id] = $refund; }
      if (!empty($response['has_more'])) { if (empty($page)) return new WP_Error('refund_pagination_empty', 'Stripe reported additional refunds but returned an empty page.'); $last = end($page); $next = sanitize_text_field($last['id'] ?? ''); if ($next === '' || $next === $starting_after) return new WP_Error('refund_pagination_stalled', 'Stripe refund pagination could not advance.'); $starting_after = $next; } else { $starting_after = ''; }
    } while ($starting_after !== '');
    return array_values($refunds);
  }


  private function stripe_create_setup_intent($customer_id, $metadata = array()) {
    $params = array(
      'customer' => (string)$customer_id,
      'usage' => 'off_session',
      'automatic_payment_methods[enabled]' => 'true',
    );
    foreach ((array)$metadata as $k => $v) {
      if ($k === '' || $v === null) continue;
      $params["metadata[{$k}]"] = (string)$v;
    }
    return $this->stripe_api_request('POST', '/v1/setup_intents', $params);
  }

