    $params = array(
      'amount' => (int)$amount_cents,
      'currency' => strtolower((string)$currency),
      'customer' => (string)$customer_id,
      'payment_method' => (string)$payment_method_id,
      'off_session' => 'true',
      'confirm' => 'true',
      'payment_method_types[0]' => 'card',
    );
