  private function mrm_resume_sheet_music_subscription($email, $payment_method_id = '', $order_id = 0) {
    $email = sanitize_email((string)$email);
    if (!$email || !is_email($email)) {
      return new WP_Error('mrm_invalid_email', 'Missing valid email for subscription resume.');
    }

    $candidate = $this->mrm_get_resumable_sheet_music_subscription_by_email($email);
    if (empty($candidate['subscription_id'])) {
      return new WP_Error('mrm_no_resumable_subscription', 'No resumable subscription found.');
    }

    $params = array(
      'cancel_at_period_end' => 'false',
      'automatic_tax[enabled]' => 'true',
    );

    if ($payment_method_id !== '') {
      $params['default_payment_method'] = (string)$payment_method_id;
    }

    $updated = $this->stripe_update_subscription($candidate['subscription_id'], $params);
    if (is_wp_error($updated)) {
      return $updated;
    }

    $local_sync = $this->mrm_sync_local_sheet_music_subscription_from_stripe($updated, $email);
    if (is_wp_error($local_sync)) {
      $containment = $this->mrm_contain_subscription_after_local_sync_failure($updated, $local_sync->get_error_message(), false);
      if (is_wp_error($containment)) {
        $this->mrm_tax_create_alert('', 'subscription_global_tax_pause_failed', 'subscription', 0, array('message'=>'Resumed subscription '.sanitize_text_field($updated['id'] ?? '').' failed local synchronization and could not be re-paused: '.$containment->get_error_message(), 'subscription_id'=>sanitize_text_field($updated['id'] ?? '')), sanitize_key($updated['id'] ?? ''));
      }
      return $local_sync;
    }

    return $updated;
  }

  private function stripe_find_customer_by_email($email) {
    $email = sanitize_email((string)$email);
    if (!$email || !is_email($email)) {
      return new WP_Error('invalid_email', 'Invalid email.');
    }

    $results = $this->stripe_api_request('GET', '/v1/customers', array(
      'email' => $email,
      'limit' => 1,
    ));

    if (is_wp_error($results)) {
      return $results;
    }

    if (empty($results['data']) || !is_array($results['data'])) {
      return new WP_Error('customer_not_found', 'Stripe customer not found.');
    }

    return (array)$results['data'][0];
  }

  private function stripe_find_all_customers_by_email($email) {
    $email = strtolower(sanitize_email((string)$email));
    if (!$email || !is_email($email)) {
      return new WP_Error('invalid_email', 'Invalid email.');
    }

    $customers = array();
    $starting_after = '';
    $pagination_guard = 0;

    do {
      $pagination_guard++;
      if ($pagination_guard > 100) {
        return new WP_Error(
          'stripe_customer_search_pagination_limit',
          'Stripe customer search exceeded the pagination safety limit.'
        );
      }

      $params = array('email' => $email, 'limit' => 100);
      if ($starting_after !== '') $params['starting_after'] = $starting_after;

      $response = $this->stripe_api_request('GET', '/v1/customers', $params);
      if (is_wp_error($response)) return $response;
      if (!array_key_exists('data', $response) || !is_array($response['data'])) {
        return new WP_Error(
          'stripe_customer_search_invalid_response',
          'Stripe returned an invalid customer-search response.'
        );
      }

      $page = $response['data'];
      foreach ($page as $customer) {
        if (!is_array($customer)) continue;
        $customer_id = sanitize_text_field((string)($customer['id'] ?? ''));
        if ($customer_id === '') continue;
        /* Key by Customer ID so the same record cannot be processed twice. */
        $customers[$customer_id] = $customer;
      }

      if (empty($response['has_more'])) break;
      if (empty($page)) {
        return new WP_Error(
          'stripe_customer_search_pagination_empty',
          'Stripe reported more matching customers but returned an empty page.'
        );
      }

      $last_customer = end($page);
      $next_starting_after = sanitize_text_field((string)($last_customer['id'] ?? ''));
      if ($next_starting_after === '' || $next_starting_after === $starting_after) {
        return new WP_Error(
          'stripe_customer_search_pagination_stalled',
          'Stripe customer-search pagination could not advance.'
        );
      }
      $starting_after = $next_starting_after;
    } while (true);

    return array_values($customers);
  }

  private function stripe_list_customer_subscriptions($customer_id) {
    $customer_id = trim((string)$customer_id);
    if ($customer_id === '') {
      return new WP_Error('missing_customer_id', 'Missing Stripe customer ID.');
    }

    $subscriptions = $this->stripe_api_request('GET', '/v1/subscriptions', array(
      'customer' => $customer_id,
      'status'   => 'all',
      'limit'    => 20,
    ));

    if (is_wp_error($subscriptions)) {
      return $subscriptions;
    }

    return $subscriptions;
  }

  private function
  mrm_get_sheet_music_subscription_access_status_by_email(
    $email,
    $fail_closed = false
  ) {
    $email = strtolower(sanitize_email((string)$email));
    $empty_result = array(
      'has_access' => false,
      'status' => '',
      'subscription_id' => '',
      'reason' => '',
      'cancel_at_period_end' => false,
      'current_period_end' => 0,
    );

    if (!$email || !is_email($email)) {
      $empty_result['reason'] = 'invalid_email';
      return $empty_result;
    }
    if ($this->mrm_sheet_music_email_is_blocked($email)) {
      $empty_result['reason'] = 'blocked_email';
      return $empty_result;
    }

    $customers = $this->stripe_find_all_customers_by_email($email);
    if (is_wp_error($customers)) {
      if ($fail_closed) {
        return new WP_Error(
          'sheet_music_subscription_lookup_failed',
          'We could not verify existing sheet-music subscription access. No payment has been submitted. Please try again in a moment.',
          array('lookup_stage' => 'customers', 'stripe_error_code' => sanitize_key((string)$customers->get_error_code()))
        );
      }
      $empty_result['reason'] = 'customer_lookup_failed';
      return $empty_result;
    }
    if (empty($customers)) {
      $empty_result['reason'] = 'no_customer';
      return $empty_result;
    }

    $now_ts = time();
    $best_access = null;
    $best_priority = 0;
    $best_period_end = 0;
    $best_created = 0;
    $latest_managed_subscription = null;
    $latest_managed_created = 0;
    $lookup_failed = false;

    foreach ($customers as $customer) {
      $customer_id = sanitize_text_field((string)($customer['id'] ?? ''));
      if ($customer_id === '') continue;
      $subscription_rows = $this->mrm_stripe_list_managed_subscriptions_for_customer($customer_id);
      if (is_wp_error($subscription_rows)) {
        if ($fail_closed) {
          return new WP_Error(
            'sheet_music_subscription_lookup_failed',
            'We could not verify existing sheet-music subscription access. No payment has been submitted. Please try again in a moment.',
            array(
              'lookup_stage' => 'subscriptions',
              'stripe_customer_id' => $customer_id,
              'stripe_error_code' => sanitize_key((string)$subscription_rows->get_error_code()),
            )
          );
        }
        $lookup_failed = true;
        continue;
      }

      foreach ($subscription_rows as $subscription) {
        if (!is_array($subscription)) continue;
        $status = sanitize_key((string)($subscription['status'] ?? ''));
        $subscription_id = sanitize_text_field((string)($subscription['id'] ?? ''));
        if ($subscription_id === '') continue;
        $cancel_at_period_end = !empty($subscription['cancel_at_period_end']);
        $period_bounds = $this->mrm_stripe_subscription_period_bounds($subscription);
        $current_period_end = max(0, (int)($period_bounds['end'] ?? 0));
        $created = max(0, (int)($subscription['created'] ?? 0));

        if ($latest_managed_subscription === null || $created > $latest_managed_created) {
          $latest_managed_subscription = $subscription;
          $latest_managed_created = $created;
        }

        $priority = 0;
        $reason = '';
        if (in_array($status, array('active', 'trialing'), true) && !$cancel_at_period_end) {
          $priority = 4;
          $reason = 'stripe_active';
        } elseif (in_array($status, array('active', 'trialing'), true) && $cancel_at_period_end && $current_period_end > $now_ts) {
          $priority = 3;
          $reason = 'paid_through_canceled';
        } elseif ($status === 'canceled' && $current_period_end > $now_ts) {
          $priority = 2;
          $reason = 'paid_through_canceled';
        }
        if ($priority <= 0) continue;

        $is_better_candidate = $best_access === null || $priority > $best_priority
          || ($priority === $best_priority && $current_period_end > $best_period_end)
          || ($priority === $best_priority && $current_period_end === $best_period_end && $created > $best_created);
        if (!$is_better_candidate) continue;

        $best_priority = $priority;
        $best_period_end = $current_period_end;
        $best_created = $created;
        $best_access = array(
          'has_access' => true,
          'status' => $status,
          'subscription_id' => $subscription_id,
          'reason' => $reason,
          'cancel_at_period_end' => $cancel_at_period_end,
          'current_period_end' => $current_period_end,
        );
      }
    }

    /* Select only after every customer and managed subscription is examined. */
    if (is_array($best_access)) return $best_access;
    if ($lookup_failed) {
      $empty_result['reason'] = 'subscription_lookup_failed';
      return $empty_result;
    }
    if (is_array($latest_managed_subscription)) {
      $latest_period_bounds = $this->mrm_stripe_subscription_period_bounds($latest_managed_subscription);
      return array(
        'has_access' => false,
        'status' => sanitize_key((string)($latest_managed_subscription['status'] ?? '')),
        'subscription_id' => sanitize_text_field((string)($latest_managed_subscription['id'] ?? '')),
        'reason' => 'stripe_not_active',
        'cancel_at_period_end' => !empty($latest_managed_subscription['cancel_at_period_end']),
        'current_period_end' => max(0, (int)($latest_period_bounds['end'] ?? 0)),
      );
    }
    $empty_result['reason'] = 'no_managed_subscriptions';
    return $empty_result;
  }

  private function mrm_validate_sheet_music_subscription_purchase_acknowledgement($email, $context = array()) {
    $email = strtolower(sanitize_email((string)$email));
    $context = is_array($context) ? $context : array();

    if (!$email || !is_email($email)) {
      return new WP_Error('sheet_music_subscription_purchase_email_invalid', 'A valid email is required before sheet-music subscription access can be checked.');
    }

    $subscription_status = $this->mrm_get_sheet_music_subscription_access_status_by_email($email, true);
    if (is_wp_error($subscription_status)) return $subscription_status;

    $has_active_subscription = is_array($subscription_status) && !empty($subscription_status['has_access']);
    $acknowledged = !empty($context['subscription_purchase_acknowledged']);

    if ($has_active_subscription && !$acknowledged) {
      return new WP_Error(
        'sheet_music_subscription_purchase_ack_required',
        'We notice you currently have an active subscription to access all the pieces in our catalog. Are you sure you want to make this purchase?',
        array(
          'active_subscription' => true,
          'subscription_status' => sanitize_key((string)($subscription_status['status'] ?? '')),
          'subscription_id' => sanitize_text_field((string)($subscription_status['subscription_id'] ?? '')),
          'subscription_reason' => sanitize_key((string)($subscription_status['reason'] ?? '')),
        )
      );
    }

    return array(
      'active_subscription' => $has_active_subscription,
      'acknowledged' => $has_active_subscription && $acknowledged,
      'subscription_status' => sanitize_key((string)($subscription_status['status'] ?? '')),
      'subscription_id' => sanitize_text_field((string)($subscription_status['subscription_id'] ?? '')),
      'subscription_reason' => sanitize_key((string)($subscription_status['reason'] ?? '')),
    );
  }

  private function mrm_persist_sheet_music_subscription_purchase_acknowledgement($order, $payment_intent, $subscription_purchase_check) {
    global $wpdb;

    $subscription_purchase_check = is_array($subscription_purchase_check) ? $subscription_purchase_check : array();
    if (empty($subscription_purchase_check['active_subscription']) || empty($subscription_purchase_check['acknowledged'])) return true;

    if (!is_array($order) || empty($order['id']) || !is_array($payment_intent)) {
      return new WP_Error('sheet_music_subscription_ack_persist_failed', 'The subscription purchase acknowledgement could not be attached to the payment order.');
    }

    $order_id = absint($order['id']);
    $payment_intent_id = sanitize_text_field((string)($payment_intent['id'] ?? ''));
    $subscription_id = sanitize_text_field((string)($subscription_purchase_check['subscription_id'] ?? ''));
    if ($order_id <= 0 || $payment_intent_id === '' || strpos($payment_intent_id, 'pi_') !== 0 || $subscription_id === '') {
      return new WP_Error('sheet_music_subscription_ack_persist_failed', 'The subscription purchase acknowledgement is missing its order, payment, or subscription reference.');
    }

    $order_metadata = $this->mrm_get_order_meta_array($order);
    $payment_metadata = isset($payment_intent['metadata']) && is_array($payment_intent['metadata']) ? $payment_intent['metadata'] : array();
    $acknowledged_at = sanitize_text_field((string)($order_metadata['mrm_sub_purchase_ack_at'] ?? $payment_metadata['mrm_sub_purchase_ack_at'] ?? ''));
    if ($acknowledged_at === '') $acknowledged_at = gmdate('Y-m-d\TH:i:s\Z');

    $order_needs_update = strtolower((string)($order_metadata['mrm_sub_purchase_ack'] ?? 'no')) !== 'yes'
      || !hash_equals(sanitize_text_field((string)($order_metadata['mrm_sub_purchase_id'] ?? '')), $subscription_id)
      || sanitize_text_field((string)($order_metadata['mrm_sub_purchase_ack_at'] ?? '')) === '';
    if ($order_needs_update) {
      $order_metadata['mrm_sub_purchase_ack'] = 'yes';
      $order_metadata['mrm_sub_purchase_id'] = $subscription_id;
      $order_metadata['mrm_sub_purchase_ack_at'] = $acknowledged_at;
      $encoded_metadata = wp_json_encode($order_metadata);
      if (!is_string($encoded_metadata) || $encoded_metadata === '') {
        return new WP_Error('sheet_music_subscription_ack_persist_failed', 'The subscription purchase acknowledgement could not be encoded for the order.');
      }
      $updated = $wpdb->update($this->table_orders(), array('metadata_json'=>$encoded_metadata, 'updated_at'=>current_time('mysql')), array('id'=>$order_id), array('%s','%s'), array('%d'));
      if ($updated === false) {
        return new WP_Error('sheet_music_subscription_ack_persist_failed', 'The subscription purchase acknowledgement could not be saved to the order.', array('order_id'=>$order_id, 'database_error'=>(string)$wpdb->last_error));
      }
    }

    $payment_needs_update = strtolower((string)($payment_metadata['mrm_sub_purchase_ack'] ?? 'no')) !== 'yes'
      || !hash_equals(sanitize_text_field((string)($payment_metadata['mrm_sub_purchase_id'] ?? '')), $subscription_id)
      || sanitize_text_field((string)($payment_metadata['mrm_sub_purchase_ack_at'] ?? '')) === '';
    if ($payment_needs_update) {
      $updated_payment_intent = $this->stripe_api_request('POST', '/v1/payment_intents/' . rawurlencode($payment_intent_id), array(
        'metadata[mrm_sub_purchase_ack]' => 'yes',
        'metadata[mrm_sub_purchase_id]' => $subscription_id,
        'metadata[mrm_sub_purchase_ack_at]' => $acknowledged_at,
      ));
      if (is_wp_error($updated_payment_intent)) {
        return new WP_Error('sheet_music_subscription_ack_persist_failed', 'The subscription purchase acknowledgement could not be saved to the secure payment record. No payment has been submitted.', array(
          'order_id'=>$order_id, 'payment_intent_id'=>$payment_intent_id,
          'stripe_error_code'=>sanitize_key((string)$updated_payment_intent->get_error_code()),
        ));
      }
    }
    return true;
  }

  private function stripe_create_billing_portal_session($customer_id, $return_url) {
    return $this->stripe_api_request('POST', '/v1/billing_portal/sessions', array(
      'customer' => (string)$customer_id,
      'return_url' => (string)$return_url,
    ));
  }

  private function mrm_extract_card_snapshot_from_payment_method($pm) {
    if (!is_array($pm)) {
      return array(
        'brand' => '',
        'last4' => '',
        'exp_month' => 0,
        'exp_year' => 0,
      );
    }

    $card = isset($pm['card']) && is_array($pm['card']) ? $pm['card'] : array();

    return array(
      'brand' => (string)($card['brand'] ?? ''),
      'last4' => (string)($card['last4'] ?? ''),
      'exp_month' => (int)($card['exp_month'] ?? 0),
      'exp_year' => (int)($card['exp_year'] ?? 0),
    );
  }

  private function mrm_store_autopay_payment_method_snapshot($autopay_profile_id, $payment_method_id, $pm = null, $attention_status = null, $attention_reason = null, $notified_now = false) {
    global $wpdb;

    $autopay_profile_id = (int)$autopay_profile_id;
    if ($autopay_profile_id <= 0) return false;

    if (!is_array($pm)) {
      $pm = $this->stripe_retrieve_payment_method($payment_method_id);
      if (is_wp_error($pm)) {
        return false;
      }
    }

    $snap = $this->mrm_extract_card_snapshot_from_payment_method($pm);

    $data = array(
      'payment_method_id' => (string)$payment_method_id,
      'pm_brand' => $snap['brand'],
      'pm_last4' => $snap['last4'],
      'pm_exp_month' => (int)$snap['exp_month'],
      'pm_exp_year' => (int)$snap['exp_year'],
      'pm_last_checked_at' => current_time('mysql'),
      'updated_at' => current_time('mysql'),
    );

    $formats = array('%s','%s','%s','%d','%d','%s','%s');

    if ($attention_status !== null) {
      $data['pm_attention_status'] = (string)$attention_status;
      $formats[] = '%s';
    }

    if ($attention_reason !== null) {
      $data['pm_attention_reason'] = (string)$attention_reason;
      $formats[] = '%s';
    }

    if ($notified_now) {
      $data['pm_attention_notified_at'] = current_time('mysql');
      $formats[] = '%s';
    }

    return (false !== $wpdb->update(
      $this->table_autopay_profiles(),
      $data,
      array('id' => $autopay_profile_id),
      $formats,
      array('%d')
    ));
  }

  private function mrm_payment_method_needs_attention_for_lesson($exp_month, $exp_year, $lesson_start_mysql) {
    $exp_month = (int)$exp_month;
    $exp_year = (int)$exp_year;
    $lesson_start_mysql = (string)$lesson_start_mysql;

    if ($exp_month <= 0 || $exp_year <= 0 || $lesson_start_mysql === '') {
      return array(
        'needs_attention' => true,
        'reason_code' => 'missing_expiration',
        'reason_text' => 'We could not confirm the expiration date of the saved payment method.',
      );
    }

    $lesson_ts = $this->mrm_lesson_utc_timestamp($lesson_start_mysql);
    if (!$lesson_ts) {
      return array(
        'needs_attention' => true,
        'reason_code' => 'lesson_time_invalid',
        'reason_text' => 'We could not confirm the lesson start time for payment-readiness review.',
      );
    }

    $lesson_year = (int)gmdate('Y', $lesson_ts);
    $lesson_month = (int)gmdate('n', $lesson_ts);

    $expires_before_lesson_month =
      ($exp_year < $lesson_year) ||
      ($exp_year === $lesson_year && $exp_month < $lesson_month);

    if ($expires_before_lesson_month) {
      return array(
        'needs_attention' => true,
        'reason_code' => 'expired_before_lesson',
        'reason_text' => sprintf('The saved card expires %02d/%04d, which is before the lesson month.', $exp_month, $exp_year),
      );
    }

    if (self::MRM_PM_SAME_MONTH_REQUIRES_UPDATE && $exp_year === $lesson_year && $exp_month === $lesson_month) {
      return array(
        'needs_attention' => true,
        'reason_code' => 'expires_same_month',
        'reason_text' => sprintf('The saved card expires %02d/%04d, which is the same month as the scheduled lesson.', $exp_month, $exp_year),
      );
    }

    return array(
      'needs_attention' => false,
      'reason_code' => '',
      'reason_text' => '',
    );
  }

  private function mrm_pm_notice_option_key($lesson_id) {
    return 'mrm_pm_attention_notice_lesson_' . (int)$lesson_id;
  }

  private function mrm_pm_notice_already_sent_for_signature($lesson_id, $signature) {
    $existing = (string)get_option($this->mrm_pm_notice_option_key($lesson_id), '');
    return ($existing !== '' && hash_equals($existing, (string)$signature));
  }

  private function mrm_mark_pm_notice_sent_for_signature($lesson_id, $signature) {
    update_option($this->mrm_pm_notice_option_key($lesson_id), (string)$signature, false);
  }

  private function mrm_clear_pm_notice_signature($lesson_id) {
    delete_option($this->mrm_pm_notice_option_key($lesson_id));
  }

  private function mrm_get_wp_admin_notification_email() {
    return sanitize_email((string)get_option('admin_email', ''));
  }

  private function mrm_format_lesson_mode_label($is_online) {
    return ((int)$is_online === 1) ? 'Online' : 'In Person';
  }

  private function mrm_send_upcoming_payment_method_attention_emails($lesson_row, $profile, $snapshot, $reason_text) {
    $lesson_id = (int)($lesson_row['id'] ?? 0);
    if ($lesson_id <= 0) return false;
    $student_email = sanitize_email((string)($lesson_row['student_email'] ?? ''));
    $student_name = trim((string)($lesson_row['student_name'] ?? $lesson_row['client_name'] ?? ''));
    $student_phone = trim((string)($lesson_row['student_phone'] ?? $lesson_row['client_phone'] ?? ''));
    $lesson_start = (string)($lesson_row['start_time'] ?? '');
    $lesson_length = (int)($lesson_row['lesson_length'] ?? 0);
    $mode_label = $this->mrm_format_lesson_mode_label((int)($lesson_row['is_online'] ?? 0));
    $instructor = $this->mrm_get_instructor_contact_from_id((int)($lesson_row['instructor_id'] ?? 0));
    $instructor_name = (string)($instructor['name'] ?? '');
    $instructor_email = sanitize_email((string)($instructor['email'] ?? ''));
    $instructor_phone = (string)($instructor['phone'] ?? '');
    $admin_email = $this->mrm_get_wp_admin_notification_email();

    $student_timezone = $this->mrm_lesson_normalize_timezone($lesson_row['parent_timezone'] ?? '', 'America/Phoenix');
    $instructor_timezone = $this->mrm_lesson_normalize_timezone($lesson_row['instructor_timezone'] ?? $instructor['timezone'] ?? '', 'America/Phoenix');
    $admin_timezone = $this->mrm_wp_tz()->getName();
    $student_when_line = $this->mrm_lesson_time_label($lesson_start, $student_timezone) ?: 'the scheduled lesson time';
    $instructor_when_line = $this->mrm_lesson_time_label($lesson_start, $instructor_timezone) ?: 'the scheduled lesson time';
    $admin_when_line = $this->mrm_lesson_time_label($lesson_start, $admin_timezone) ?: 'the scheduled lesson time';

    $brand = trim((string)($snapshot['brand'] ?? ''));
    $last4 = trim((string)($snapshot['last4'] ?? ''));
    $card_line = ($brand !== '' || $last4 !== '') ? trim($brand . ' ending in ' . $last4) : 'Saved payment method on file';
    $exp_month = (int)($snapshot['exp_month'] ?? 0); $exp_year = (int)($snapshot['exp_year'] ?? 0);
    if ($exp_month > 0 && $exp_year > 0) $card_line .= sprintf(' (expires %02d/%04d)', $exp_month, $exp_year);
    $lesson_line = trim(($lesson_length > 0 ? $lesson_length . '-minute ' : '') . $mode_label . ' lesson');
    $profile_id = (int)($lesson_row['autopay_profile_id'] ?? $profile['id'] ?? 0);
    $update_url = $this->mrm_autopay_update_payment_url($lesson_id, $profile_id);
    $headers = array('Content-Type: text/html; charset=UTF-8','From: LowBrass Lessons <no-reply@lowbrass-lessons.com>');

    $student_details = '<div><strong>Lesson:</strong> '.esc_html($lesson_line).'</div><div><strong>Renewing at:</strong> '.esc_html($student_when_line).'</div><div><strong>Saved payment method:</strong> '.esc_html($card_line).'</div><div><strong>Reason:</strong> '.esc_html($reason_text).'</div>';
    $student_sent = $student_email && is_email($student_email) ? wp_mail($student_email, 'Your Payment Method Requires Attention', $this->mrm_email_wrap_html('Update your payment information', '<p>Your payment information is in need of an update. Please update it for the auto-pay lesson renewing at <strong>'.esc_html($student_when_line).'</strong>.</p>', $student_details, array(array('url'=>$update_url,'label'=>'Update Payment Information','variant'=>'primary')), '', $this->mrm_email_contact_support_html('If you have any questions please fill out our contact form.')), $headers) : false;

    $instructor_details = '<div><strong>Student:</strong> '.esc_html($student_name).'</div><div><strong>Lesson:</strong> '.esc_html($lesson_line).'</div><div><strong>Scheduled time:</strong> '.esc_html($instructor_when_line).'</div><div><strong>Client email:</strong> '.esc_html($student_email).'</div><div><strong>Client phone number:</strong> '.esc_html($student_phone).'</div>';
    $instructor_sent = $instructor_email && is_email($instructor_email) ? wp_mail($instructor_email, 'Payment method needs attention for '.$student_name, $this->mrm_email_wrap_html('Please withhold this lesson '.$instructor_when_line.' until payment method has been updated', '<p>The upcoming AutoPay lesson requires an updated payment method before it can be processed.</p>', $instructor_details, '', ''), $headers) : false;

    $admin_details = '<div><strong>Student:</strong> '.esc_html($student_name).'</div><div><strong>Student email:</strong> '.esc_html($student_email).'</div><div><strong>Student phone:</strong> '.esc_html($student_phone).'</div><div><strong>Instructor:</strong> '.esc_html($instructor_name).'</div><div><strong>Instructor email:</strong> '.esc_html($instructor_email).'</div><div><strong>Instructor phone:</strong> '.esc_html($instructor_phone).'</div><div><strong>Lesson:</strong> '.esc_html($lesson_line).'</div><div><strong>Lesson day and time:</strong> '.esc_html($admin_when_line).'</div><div><strong>Payment update portal:</strong> <a href="'.esc_url($update_url).'">'.esc_html($update_url).'</a></div><div><strong>Issue:</strong> '.esc_html($reason_text).'</div>';
    $admin_sent = $admin_email && is_email($admin_email) ? wp_mail($admin_email, 'Payment information update required for '.$student_name, $this->mrm_email_wrap_html('Payment method update needed', '<p>Payment information must be updated before the upcoming lesson.</p>', $admin_details, '', ''), $headers) : false;
    return $student_sent || $instructor_sent || $admin_sent;
  }

  private function mrm_signed_lesson_action_url($action, $lesson_id, $profile_id = 0) {
    $lesson_id = absint($lesson_id); $profile_id = absint($profile_id); $expires = time() + (7 * DAY_IN_SECONDS);
    $payload = $action . '|' . $lesson_id . '|' . $profile_id . '|' . $expires;
    $sig = hash_hmac('sha256', $payload, wp_salt('auth'));
    return add_query_arg(array('action'=>$action,'lesson_id'=>$lesson_id,'profile_id'=>$profile_id,'expires'=>$expires,'sig'=>$sig), admin_url('admin-post.php'));
  }
  private function mrm_verify_signed_lesson_action($action, $lesson_id, $profile_id, $expires, $sig) {
    $lesson_id=absint($lesson_id); $profile_id=absint($profile_id); $expires=absint($expires); $sig=(string)$sig;
    if ($lesson_id <= 0 || $expires < time() || $sig === '') return false;
    return hash_equals(hash_hmac('sha256', $action . '|' . $lesson_id . '|' . $profile_id . '|' . $expires, wp_salt('auth')), $sig);
  }
  private function mrm_autopay_update_payment_url($lesson_id, $profile_id) { return $this->mrm_signed_lesson_action_url('mrm_autopay_update_payment', $lesson_id, $profile_id); }
  public function handle_autopay_update_payment() {
    $lesson_id=absint($_GET['lesson_id'] ?? 0); $profile_id=absint($_GET['profile_id'] ?? 0); $expires=absint($_GET['expires'] ?? 0); $sig=sanitize_text_field((string)($_GET['sig'] ?? ''));
    if (!$this->mrm_verify_signed_lesson_action('mrm_autopay_update_payment',$lesson_id,$profile_id,$expires,$sig)) wp_die('This payment update link is invalid or expired.', 'Payment Update', array('response'=>403));
    $profile=$this->mrm_get_autopay_profile($profile_id); if (!$profile || empty($profile['customer_id'])) wp_die('Unable to find the AutoPay customer profile.', 'Payment Update', array('response'=>404));
    $portal=$this->stripe_create_billing_portal_session((string)$profile['customer_id'], home_url('/contact/'));
    if (is_wp_error($portal) || empty($portal['url'])) wp_die('Unable to open the Stripe payment update page right now.', 'Payment Update', array('response'=>500));
    wp_redirect((string)$portal['url']); exit;
  }

  private function mrm_ensure_customer_payment_method_ready($customer_id, $payment_method_id) {
    $customer_id = sanitize_text_field((string)$customer_id);
    $payment_method_id = sanitize_text_field((string)$payment_method_id);

    if (!$customer_id || !$payment_method_id) {
      return new WP_Error('mrm_autopay_missing_customer_or_pm', 'Missing Stripe customer or payment method for autopay.');
    }

    $pm = $this->stripe_retrieve_payment_method($payment_method_id);
    if (is_wp_error($pm)) {
      return $pm;
    }

    $attached_customer = isset($pm['customer']) ? (string)$pm['customer'] : '';
    if ($attached_customer !== '' && $attached_customer !== $customer_id) {
      return new WP_Error(
        'mrm_autopay_pm_customer_mismatch',
        'Saved payment method is attached to a different Stripe customer.'
      );
    }

    if ($attached_customer === '') {
      $attach = $this->stripe_attach_payment_method_to_customer($payment_method_id, $customer_id);
      if (is_wp_error($attach)) {
        return $attach;
      }
    }

    $set = $this->stripe_set_default_payment_method($customer_id, $payment_method_id);
    if (is_wp_error($set)) {
      return $set;
    }

    return array(
      'customer_id' => $customer_id,
      'payment_method_id' => $payment_method_id,
    );
  }

  private function stripe_detach_payment_method($payment_method_id) {
    $payment_method_id = sanitize_text_field((string)$payment_method_id);
    if (!$payment_method_id) return new WP_Error('stripe_invalid_args', 'Missing payment method id.');
    return $this->stripe_api_request('POST', '/v1/payment_methods/' . rawurlencode($payment_method_id) . '/detach', array());
  }

  private function stripe_create_refund($payment_intent_id, $amount_cents = null, $reason = 'requested_by_customer') {
    $payment_intent_id = sanitize_text_field($payment_intent_id);
    if ($payment_intent_id === '') return new WP_Error('stripe_invalid_args', 'Missing PaymentIntent ID.');
    $payment_intent = $this->stripe_api_request('GET', '/v1/payment_intents/' . rawurlencode($payment_intent_id), array('expand'=>array('latest_charge')));
    if (is_wp_error($payment_intent)) return $payment_intent;
    $latest_charge = $payment_intent['latest_charge'] ?? null;
    if (is_string($latest_charge)) { $latest_charge = $this->stripe_retrieve_charge($latest_charge); if (is_wp_error($latest_charge)) return $latest_charge; }
    $invoice_id = '';
    if (is_array($latest_charge)) $invoice_id = is_array($latest_charge['invoice'] ?? null) ? sanitize_text_field($latest_charge['invoice']['id'] ?? '') : sanitize_text_field($latest_charge['invoice'] ?? '');
    if ($invoice_id !== '') {
      $available = max(0, absint($latest_charge['amount'] ?? 0) - absint($latest_charge['amount_refunded'] ?? 0));
      $invoice_refund_amount = $amount_cents !== null ? min($available, absint($amount_cents)) : $available;
      if ($invoice_refund_amount <= 0) return new WP_Error('invoice_refund_amount_invalid', 'No refundable invoice amount remains.');
      return $this->mrm_create_subscription_invoice_refund($invoice_id, $invoice_refund_amount);
    }
    $params = array('payment_intent'=>$payment_intent_id,'reason'=>$reason);
    if ($amount_cents !== null && (int)$amount_cents > 0) $params['amount'] = (int)$amount_cents;
    return $this->stripe_api_request('POST', '/v1/refunds', $params);
  }

  private function stripe_find_or_create_customer($email) {
    $email = sanitize_email((string)$email);
    if (!$email || !is_email($email)) return new WP_Error('bad_email', 'Valid email required for customer.');

    // Try to find existing customer by email
    $list = $this->stripe_api_request('GET', '/v1/customers', array(
      'email' => $email,
      'limit' => 1,
    ));
    if (is_wp_error($list)) return $list;

    if (isset($list['data'][0]['id'])) {
      return (string)$list['data'][0]['id'];
    }

    // Create new customer
    $created = $this->stripe_api_request('POST', '/v1/customers', array(
      'email' => $email,
    ));
    if (is_wp_error($created)) return $created;

    return isset($created['id']) ? (string)$created['id'] : new WP_Error('stripe_error', 'Unable to create customer.');
  }

  private function stripe_update_customer_address($customer_id, $email, $address = array(), $name = '') {
    $customer_id = trim((string)$customer_id);
    $email = sanitize_email((string)$email);

    if ($customer_id === '') {
      return new WP_Error('missing_customer_id', 'Missing Stripe customer id.');
    }

    $line1 = trim((string)($address['line1'] ?? ''));
    $line2 = trim((string)($address['line2'] ?? ''));
    $city = trim((string)($address['city'] ?? ''));
    $state = trim((string)($address['state'] ?? ''));
    $postal = trim((string)($address['postal_code'] ?? ''));
    $country = strtoupper(trim((string)($address['country'] ?? 'US')));

    $params = array(
      'email' => $email,
    );

    if ($name !== '') {
      $params['name'] = (string)$name;
    }

    if ($line1 !== '') {
      $params['address[line1]'] = $line1;
    }
    if ($line2 !== '') {
      $params['address[line2]'] = $line2;
    }
    if ($city !== '') {
      $params['address[city]'] = $city;
    }
    if ($state !== '') {
      $params['address[state]'] = $state;
    }
    if ($postal !== '') {
      $params['address[postal_code]'] = $postal;
    }
    if ($country !== '') {
      $params['address[country]'] = $country;
    }

    $params['tax[validate_location]'] = 'immediately';

    $this->stripe_debug_log('updating stripe customer tax location', array(
      'customer_id' => $customer_id,
      'email' => $email,
      'state' => $state,
      'postal_code' => $postal,
      'country' => $country,
      'line1_present' => $line1 ? 'yes' : 'no',
    ));

    return $this->stripe_api_request('POST', '/v1/customers/' . rawurlencode($customer_id), $params);
  }

  private function stripe_construct_webhook_event($payload, $signature_header, $secret) {
    if (!$payload || !$signature_header || !$secret) {
      return new WP_Error('stripe_webhook_invalid', 'Missing webhook payload, signature, or secret.');
    }

    $parts = explode(',', (string)$signature_header);
    $timestamp = '';
    $signatures = array();

    foreach ($parts as $part) {
      $kv = explode('=', trim($part), 2);
      if (count($kv) !== 2) continue;
      if ($kv[0] === 't') $timestamp = $kv[1];
      if ($kv[0] === 'v1') $signatures[] = $kv[1];
    }

    if ($timestamp === '' || empty($signatures)) {
      return new WP_Error('stripe_webhook_invalid', 'Invalid Stripe-Signature header.');
    }

    $signed_payload = $timestamp . '.' . $payload;
    $expected = hash_hmac('sha256', $signed_payload, $secret);

    $valid = false;
    foreach ($signatures as $sig) {
      if (hash_equals($expected, $sig)) {
        $valid = true;
        break;
      }
    }

    if (!$valid) {
      return new WP_Error('stripe_webhook_invalid', 'Webhook signature verification failed.');
    }

    $json = json_decode($payload, true);
    if (!is_array($json)) {
      return new WP_Error('stripe_webhook_invalid', 'Invalid webhook JSON.');
    }

    return $json;
  }

  private function mrm_webhook_event_already_processed($event_id) {
    global $wpdb;
    return (bool)$wpdb->get_var($wpdb->prepare(
      "SELECT id FROM {$this->table_webhook_events()} WHERE stripe_event_id=%s LIMIT 1",
      (string)$event_id
    ));
  }

  private function mrm_mark_webhook_event_processed($event_id, $event_type, $object_id = '') {
    global $wpdb;
    $now = current_time('mysql');

    $wpdb->insert($this->table_webhook_events(), array(
      'stripe_event_id' => (string)$event_id,
      'event_type' => (string)$event_type,
      'object_id' => (string)$object_id,
      'processed_at' => $now,
      'created_at' => $now,
    ), array('%s','%s','%s','%s','%s'));
  }

  private function
  mrm_finalize_succeeded_payment_intent_promo_redemption(
    $payment_intent
  ) {
    if (!is_array($payment_intent)) {
      return new WP_Error(
        'promo_payment_intent_invalid',
        'The successful PaymentIntent could not be read while finalizing its promotional code.'
      );
    }

    $payment_intent_id = sanitize_text_field(
      (string)($payment_intent['id'] ?? '')
    );

    if ($payment_intent_id === '') {
      return new WP_Error(
        'promo_payment_intent_id_missing',
        'The successful PaymentIntent did not contain an ID while finalizing its promotional code.'
      );
    }

    $metadata =
      isset($payment_intent['metadata']) &&
      is_array($payment_intent['metadata'])
        ? $payment_intent['metadata']
        : array();

    $promo_code =
      $this->mrm_normalize_promo_code(
        $metadata['mrm_promo_code'] ??
        $metadata['promo_code'] ??
        ''
      );

    $promo_discount_cents = max(
      0,
      (int)(
        $metadata['mrm_promo_discount_cents'] ??
        $metadata['promo_discount_cents'] ??
        0
      )
    );

    $reservation_token = sanitize_text_field(
      (string)(
        $metadata[
          'mrm_promo_reservation_token'
        ] ?? ''
      )
    );

    /* PaymentIntents without a discounted promo do not require a redemption transition. */
    if ($promo_code === '' || $promo_discount_cents <= 0) {
      return true;
    }

    if ($reservation_token !== '') {
      $external_result =
        $this->mark_external_promo_redemption_paid(
          $payment_intent_id,
          $reservation_token
        );

      if (is_wp_error($external_result)) {
        return $external_result;
      }

      if ($external_result !== true) {
        return new WP_Error(
          'external_promo_redemption_not_finalized',
          'The successful payment promotional-code reservation could not be marked paid.'
        );
      }

      return true;
    }

    if ($this->mrm_mark_promo_redemption_paid_by_payment_intent($payment_intent_id)) {
      return true;
    }

    $order = $this->get_order_by_pi($payment_intent_id);

    if (is_array($order) && !empty($order['id'])) {
      $this->mrm_mark_promo_redemption_paid(
        (int)$order['id'],
        $payment_intent_id
      );

      if ($this->mrm_mark_promo_redemption_paid_by_payment_intent($payment_intent_id)) {
        return true;
      }

      return new WP_Error(
        'internal_promo_redemption_not_finalized',
        'The successful payment promotional-code reservation could not be marked paid.'
      );
    }

    /* Older external intents might predate the central reservation table. */
    return true;
  }

  private function mrm_handle_payment_intent_succeeded_webhook(
  $pi
) {
  $this->stripe_debug_log(
    'payment_intent.succeeded handler entered',
    array(
      'pi_id' => (string)($pi['id'] ?? ''),
      'customer_id' => (string)($pi['customer'] ?? ''),
      'payment_method_id' => (string)($pi['payment_method'] ?? ''),
    )
  );

  if (!is_array($pi)) {
    return new WP_Error('payment_intent_succeeded_object_invalid', 'The payment_intent.succeeded event did not contain a valid PaymentIntent.');
  }

  $pi_id = sanitize_text_field($pi['id'] ?? '');

  if ($pi_id === '') {
    return new WP_Error(
      'payment_intent_succeeded_id_missing',
      'The payment_intent.succeeded event did not contain a PaymentIntent ID.'
    );
  }

  /* Permanently consume the promo before downstream processing can fail. */
  $promo_redemption_result =
    $this
      ->mrm_finalize_succeeded_payment_intent_promo_redemption(
        $pi
      );

  if (is_wp_error($promo_redemption_result)) {
    $this->stripe_debug_log(
      'Payment succeeded but promotional-code finalization failed.',
      array(
        'payment_intent_id' => $pi_id,
        'code' => $promo_redemption_result->get_error_code(),
        'message' => $promo_redemption_result->get_error_message(),
      )
    );

    return $promo_redemption_result;
  }

  $tax_sync_result =
    $this->mrm_tax_sync_payment_intent_ledger(
      $pi,
      0
    );

  if (is_wp_error($tax_sync_result)) {
    $this->stripe_debug_log(
      'Payment succeeded but required tax-ledger synchronization failed.',
      array(
        'payment_intent_id' => $pi_id,
        'message' => $tax_sync_result->get_error_message(),
      )
    );

    return $tax_sync_result;
  }

  $latest_charge = '';

  if (!empty($pi['latest_charge'])) {
    $latest_charge = is_array($pi['latest_charge'])
      ? sanitize_text_field($pi['latest_charge']['id'] ?? '')
      : sanitize_text_field($pi['latest_charge']);
  }

  do_action(
    'mrm_masterclass_payment_intent_succeeded',
    $pi
  );

  $order = $this->get_order_by_pi($pi_id);

  if (!$order) {
    return true;
  }

  $metadata = isset($pi['metadata']) && is_array($pi['metadata']) ? $pi['metadata'] : array();
  $metadata['mrm_latest_charge_id'] = $latest_charge;

  $this->update_order_status_from_pi($pi_id, 'paid', (string)($pi['status'] ?? 'succeeded'), $metadata);

  $this->mrm_subscription_debug_log(
    'order updated after payment success',
    array(
      'order_id' => (int)($order['id'] ?? 0),
      'payment_intent_id' => $pi_id,
      'status' => 'paid',
    )
  );

  $order = $this->get_order_by_pi($pi_id);

  if ($order) {
    if (sanitize_key((string)($order['product_type'] ?? '')) === 'sheet_music') {
      $grant_result = $this->mrm_grant_sheet_music_purchase_entitlements($pi, 'stripe_pi_webhook');
      if (is_wp_error($grant_result)) return $grant_result;
    }
    $this->mrm_maybe_send_purchase_receipt_email($pi, $order);
    $payout_result = $this->mrm_maybe_create_payout_ledger_for_order($order);
    if (is_wp_error($payout_result)) {
      $this->stripe_debug_log('Payment succeeded but payout-ledger persistence failed.', array(
        'order_id'=>(int)($order['id'] ?? 0), 'payment_intent_id'=>$pi_id,
        'message'=>$payout_result->get_error_message(), 'code'=>$payout_result->get_error_code(),
      ));
      return $payout_result;
    }
    if (in_array(sanitize_key((string)($order['product_type'] ?? '')), array('sheet_music', 'lesson'), true) && $payout_result !== true) {
      return new WP_Error('payout_ledger_not_created', 'The required payout ledger was not created for the paid order.');
    }

    $promo_code_from_meta = '';

    if (!empty($metadata['mrm_promo_code'])) {
      $promo_code_from_meta = $this->mrm_normalize_promo_code($metadata['mrm_promo_code']);
    }

    if ($promo_code_from_meta !== '') {
      $this->mrm_mark_promo_redemption_paid((int)$order['id'], $pi_id);
    }

    $meta = isset($pi['metadata']) && is_array($pi['metadata']) ? $pi['metadata'] : array();
    $addon_yes = (isset($meta['mrm_sheet_music_addon']) && strtolower((string)$meta['mrm_sheet_music_addon']) === 'yes');
    $product_type = (string)($order['product_type'] ?? '');

    if ($addon_yes && $product_type === 'lesson' && !empty($order['id'])) {
      $this->mrm_attempt_sheet_music_subscription_activation((int)$order['id'], $pi, 'payment_intent_succeeded_webhook');
    }

    $lesson_id = 0;

    if (!empty($metadata['mrm_lesson_id'])) {
      $lesson_id = (int)$metadata['mrm_lesson_id'];
    }

    if ($lesson_id <= 0 && !empty($order['metadata_json'])) {
      $decoded = json_decode((string)$order['metadata_json'], true);

      if (is_array($decoded) && !empty($decoded['mrm_lesson_id'])) {
        $lesson_id = (int)$decoded['mrm_lesson_id'];
      }
    }

    if ($lesson_id > 0 && (string)($order['sku'] ?? '') === 'autopay_lesson_charge') {
      $this->mrm_finalize_autopay_lesson_success($lesson_id, $order, $pi_id, true);
    }
  }

  return true;
}

  private function
  mrm_handle_payment_intent_failed_webhook(
    $pi,
    $local_status = 'failed'
  ) {
    if (!is_array($pi)) {
      return new WP_Error(
        'payment_intent_failure_object_invalid',
        'The PaymentIntent failure event did not contain a valid PaymentIntent.'
      );
    }

    $pi_id = sanitize_text_field((string)($pi['id'] ?? ''));
    if ($pi_id === '') {
      return new WP_Error(
        'payment_intent_failure_id_missing',
        'The PaymentIntent failure event did not contain an ID.'
      );
    }

    $local_status = sanitize_key((string)$local_status);
    $stripe_status = sanitize_key((string)($pi['status'] ?? ''));
    $is_canceled = ($local_status === 'canceled' || $stripe_status === 'canceled');

    if ($is_canceled) {
      $promo_released = $this->mrm_release_pending_promo_redemption(0, $pi_id);
      if (!$promo_released) {
        return new WP_Error(
          'canceled_payment_promo_release_failed',
          'The canceled PaymentIntent promotional-code reservation could not be released.'
        );
      }
    }

    $order = $this->get_order_by_pi($pi_id);
    if (!$order) {
      return true;
    }

    $metadata = isset($pi['metadata']) && is_array($pi['metadata']) ? $pi['metadata'] : array();
    if (!empty($pi['latest_charge'])) {
      $metadata['mrm_latest_charge_id'] = is_array($pi['latest_charge'])
        ? sanitize_text_field((string)($pi['latest_charge']['id'] ?? ''))
        : sanitize_text_field((string)$pi['latest_charge']);
    }

    $this->update_order_status_from_pi($pi_id, $local_status, $stripe_status, $metadata);
    $lesson_id = !empty($metadata['mrm_lesson_id']) ? (int)$metadata['mrm_lesson_id'] : 0;
    if ($lesson_id <= 0 && !empty($order['metadata_json'])) {
      $decoded = json_decode((string)$order['metadata_json'], true);
      if (is_array($decoded) && !empty($decoded['mrm_lesson_id'])) {
        $lesson_id = (int)$decoded['mrm_lesson_id'];
      }
    }

    if ($lesson_id > 0 && (string)($order['sku'] ?? '') === 'autopay_lesson_charge') {
      $message = 'Autopay webhook failure: ' . ($stripe_status !== '' ? $stripe_status : $local_status);
      $this->mrm_finalize_autopay_lesson_failure($lesson_id, $message);
    }

    return true;
  }

  private function mrm_void_standard_payouts_for_refunded_order($order_id, $pi_id = '', $reason = 'payment_refunded') {
    global $wpdb;

    $order_id = absint($order_id);
    $pi_id = sanitize_text_field((string)$pi_id);
    $reason = sanitize_key((string)$reason);

    if ($order_id <= 0 && $pi_id === '') {
      return array('voided' => 0, 'reversed' => 0, 'reversal_failed' => 0, 'recovery_needed' => 0);
    }

    $table = $this->table_payout_ledger();
    $where = array();
    $args = array();

    if ($order_id > 0) {
      $where[] = 'order_id = %d';
      $args[] = $order_id;
    }

    if ($pi_id !== '') {
      $where[] = 'stripe_payment_intent_id = %s';
      $args[] = $pi_id;
    }

    if (empty($where)) {
      return array('voided' => 0, 'reversed' => 0, 'reversal_failed' => 0, 'recovery_needed' => 0);
    }

    $sql = "SELECT *
            FROM {$table}
            WHERE (" . implode(' OR ', $where) . ")
              AND payee_type <> 'platform'
            ORDER BY id ASC";

    $rows = $wpdb->get_results($wpdb->prepare($sql, $args), ARRAY_A);

    $summary = array('voided' => 0, 'reversed' => 0, 'reversal_failed' => 0, 'recovery_needed' => 0);

    foreach ((array)$rows as $row) {
      $ledger_id = absint($row['id'] ?? 0);
      if ($ledger_id <= 0) {
        continue;
      }

      $status = sanitize_key((string)($row['status'] ?? ''));
      $transfer_id = sanitize_text_field((string)($row['transfer_id'] ?? ''));
      $payout_id = sanitize_text_field((string)($row['payout_id'] ?? ''));
      $amount = absint($row['net_cents'] ?? 0);

      if (in_array($status, array('pending', 'error', 'blocked'), true)) {
        $wpdb->update($table, array(
          'status' => 'refunded_void',
          'notes' => 'Payout voided because associated payment was refunded. Reason: ' . $reason,
          'updated_at' => current_time('mysql'),
        ), array('id' => $ledger_id), array('%s', '%s', '%s'), array('%d'));

        $summary['voided']++;
        continue;
      }

      if ($status === 'transferred' && $transfer_id !== '' && $payout_id === '') {
        $reversal = $this->stripe_reverse_transfer($transfer_id, $amount > 0 ? $amount : null, array(
          'mrm_order_id' => (string)$order_id,
          'mrm_payout_ledger_id' => (string)$ledger_id,
          'mrm_refund_void_reason' => $reason,
        ));

        if (is_wp_error($reversal)) {
          $wpdb->update($table, array(
            'status' => 'refund_reversal_failed',
            'notes' => 'Payment was refunded after transfer. Transfer reversal failed: ' . $reversal->get_error_message(),
            'updated_at' => current_time('mysql'),
          ), array('id' => $ledger_id), array('%s', '%s', '%s'), array('%d'));

          $summary['reversal_failed']++;
        } else {
          $wpdb->update($table, array(
            'status' => 'refunded_reversed',
            'notes' => 'Payout transfer reversed because associated payment was refunded. Stripe reversal: ' . sanitize_text_field((string)($reversal['id'] ?? '')),
            'updated_at' => current_time('mysql'),
          ), array('id' => $ledger_id), array('%s', '%s', '%s'), array('%d'));

          $summary['reversed']++;
        }

        continue;
      }

      if ($status === 'paid_out' || $payout_id !== '') {
        $wpdb->update($table, array(
          'status' => 'refund_after_payout_needs_recovery',
          'notes' => 'Payment was refunded after contractor payout was already completed. Manual recovery/adjustment is required.',
          'updated_at' => current_time('mysql'),
        ), array('id' => $ledger_id), array('%s', '%s', '%s'), array('%d'));

        $summary['recovery_needed']++;
        continue;
      }
    }

    if ($order_id > 0) {
      $wpdb->update($table, array(
        'status' => 'retained_refunded',
        'notes' => 'Platform retained row marked refunded because associated payment was refunded. Reason: ' . $reason,
        'updated_at' => current_time('mysql'),
      ), array(
        'order_id' => $order_id,
        'payee_type' => 'platform',
        'status' => 'retained',
      ), array('%s', '%s', '%s'), array('%d', '%s', '%s'));
    }

    if (method_exists($this, 'stripe_debug_log')) {
      $this->stripe_debug_log('standard payout rows voided for refunded order', array(
        'order_id' => $order_id,
        'pi_id' => $pi_id,
        'reason' => $reason,
        'summary' => $summary,
      ));
    }

    return $summary;
  }

  private function mrm_void_subscription_composer_payout_for_refunded_invoice($invoice_id, $subscription_id = '', $reason = 'subscription_invoice_refunded') {
    global $wpdb;

    $invoice_id = sanitize_text_field((string)$invoice_id);
    $subscription_id = sanitize_text_field((string)$subscription_id);
    $reason = sanitize_key((string)$reason);

    $summary = array(
      'voided' => 0,
      'reversed' => 0,
      'reversal_failed' => 0,
      'recovery_needed' => 0,
    );

    if ($invoice_id === '' && $subscription_id === '') {
      return $summary;
    }

    $table = $this->table_payout_ledger();

    $where = array();
    $args = array();

    if ($invoice_id !== '') {
      $where[] = 'payee_ref = %s';
      $args[] = 'stripe_subscription_invoice:' . $invoice_id;
    }

    /*
     * Subscription ID fallback:
     * The current composer rows are invoice-based. This fallback catches any future
     * rows you may create with subscription ID in the payee_ref or notes field.
     */
    if ($subscription_id !== '') {
      $where[] = 'payee_ref = %s';
      $args[] = 'stripe_subscription:' . $subscription_id;
      $where[] = 'notes LIKE %s';
      $args[] = '%' . $wpdb->esc_like($subscription_id) . '%';
    }

    if (empty($where)) {
      return $summary;
    }

    $sql = "SELECT *
            FROM {$table}
            WHERE payee_type = %s
              AND (" . implode(' OR ', $where) . ")
            ORDER BY id ASC";

    array_unshift($args, 'composer');

    $rows = $wpdb->get_results($wpdb->prepare($sql, $args), ARRAY_A);

    foreach ((array)$rows as $row) {
      $ledger_id = absint($row['id'] ?? 0);

      if ($ledger_id <= 0) {
        continue;
      }

      $status = sanitize_key((string)($row['status'] ?? ''));
      $transfer_id = sanitize_text_field((string)($row['transfer_id'] ?? ''));
      $payout_id = sanitize_text_field((string)($row['payout_id'] ?? ''));
      $amount = absint($row['net_cents'] ?? 0);

      if (in_array($status, array('pending', 'error', 'blocked'), true)) {
        $wpdb->update(
          $table,
          array(
            'status' => 'refunded_void',
            'notes' => 'Composer subscription payout voided because subscription invoice was refunded. Invoice: ' . $invoice_id . '. Reason: ' . $reason,
            'updated_at' => current_time('mysql'),
          ),
          array('id' => $ledger_id),
          array('%s', '%s', '%s'),
          array('%d')
        );

        $summary['voided']++;
        continue;
      }

      if ($status === 'transferred' && $transfer_id !== '' && $payout_id === '') {
        $reversal = $this->stripe_reverse_transfer(
          $transfer_id,
          $amount > 0 ? $amount : null,
          array(
            'mrm_payout_ledger_id' => (string)$ledger_id,
            'mrm_subscription_invoice_id' => $invoice_id,
            'mrm_subscription_id' => $subscription_id,
            'mrm_refund_void_reason' => $reason,
          )
        );

        if (is_wp_error($reversal)) {
          $wpdb->update(
            $table,
            array(
              'status' => 'refund_reversal_failed',
              'notes' => 'Subscription invoice was refunded after transfer. Transfer reversal failed: ' . $reversal->get_error_message(),
              'updated_at' => current_time('mysql'),
            ),
            array('id' => $ledger_id),
            array('%s', '%s', '%s'),
            array('%d')
          );

          $summary['reversal_failed']++;
        } else {
          $wpdb->update(
            $table,
            array(
              'status' => 'refunded_reversed',
              'notes' => 'Composer subscription transfer reversed because invoice was refunded. Stripe reversal: ' . sanitize_text_field((string)($reversal['id'] ?? '')),
              'updated_at' => current_time('mysql'),
            ),
            array('id' => $ledger_id),
            array('%s', '%s', '%s'),
            array('%d')
          );

          $summary['reversed']++;
        }

        continue;
      }

      if ($status === 'paid_out' || $payout_id !== '') {
        $wpdb->update(
          $table,
          array(
            'status' => 'refund_after_payout_needs_recovery',
            'notes' => 'Subscription invoice was refunded after composer payout was already completed. Manual recovery/adjustment is required. Invoice: ' . $invoice_id,
            'updated_at' => current_time('mysql'),
          ),
          array('id' => $ledger_id),
          array('%s', '%s', '%s'),
          array('%d')
        );

        $summary['recovery_needed']++;
        continue;
      }
    }

    if (method_exists($this, 'stripe_debug_log')) {
      $this->stripe_debug_log('subscription composer payout rows voided for refunded invoice', array(
        'invoice_id' => $invoice_id,
        'subscription_id' => $subscription_id,
        'reason' => $reason,
        'summary' => $summary,
      ));
    }

    return $summary;
  }

  private function mrm_void_subscription_composer_payout_from_refunded_charge($charge, $reason = 'stripe_charge_refunded_webhook') {
    if (!is_array($charge)) {
      return array(
        'voided' => 0,
        'reversed' => 0,
        'reversal_failed' => 0,
        'recovery_needed' => 0,
      );
    }

    $invoice_id = '';

    if (isset($charge['invoice'])) {
      if (is_array($charge['invoice'])) {
        $invoice_id = sanitize_text_field((string)($charge['invoice']['id'] ?? ''));
      } else {
        $invoice_id = sanitize_text_field((string)$charge['invoice']);
      }
    }

    $subscription_id = '';

    if (isset($charge['metadata']) && is_array($charge['metadata'])) {
      $subscription_id = sanitize_text_field((string)($charge['metadata']['subscription'] ?? $charge['metadata']['subscription_id'] ?? ''));
    }

    /*
     * If Stripe provided an expanded invoice object, try to read the subscription.
     */
    if ($subscription_id === '' && isset($charge['invoice']) && is_array($charge['invoice'])) {
      $subscription_id = $this->mrm_stripe_invoice_subscription_id($charge['invoice']);
    }

    /*
     * If we only have an invoice ID, try retrieving the invoice to find subscription ID.
     */
    if ($invoice_id !== '' && $subscription_id === '') {
      $invoice = $this->stripe_api_request('GET', '/v1/invoices/' . rawurlencode($invoice_id));

      if (!is_wp_error($invoice) && is_array($invoice)) {
        $subscription_id = $this->mrm_stripe_invoice_subscription_id($invoice);
      }
    }

    if ($invoice_id === '' && $subscription_id === '') {
      return array(
        'voided' => 0,
        'reversed' => 0,
        'reversal_failed' => 0,
        'recovery_needed' => 0,
      );
    }

    return $this->mrm_void_subscription_composer_payout_for_refunded_invoice(
      $invoice_id,
      $subscription_id,
      $reason
    );
  }

  private function mrm_tax_required_webhook_result(
  $error_code,
  $messages
) {
  $messages = array_values(
    array_unique(
      array_filter(
        array_map(
          'sanitize_text_field',
          (array)$messages
        )
      )
    )
  );

  if (empty($messages)) {
    return true;
  }

  return new WP_Error(
    sanitize_key($error_code),
    implode(' | ', $messages)
  );
}

private function mrm_charge_refund_effects_state_key($charge_id) { return 'mrm_charge_refund_effects_'.substr(hash('sha256',sanitize_text_field($charge_id)),0,40); }
private function mrm_charge_refund_effects_lock_key($charge_id) { return 'mrm_charge_refund_effects_lock_'.substr(hash('sha256',sanitize_text_field($charge_id)),0,40); }
private function mrm_get_charge_refund_effects_state($charge_id) { $state=get_option($this->mrm_charge_refund_effects_state_key($charge_id),array()); return is_array($state)?$state:array(); }
private function mrm_claim_charge_refund_effects_lock($charge_id) { $lock_key=$this->mrm_charge_refund_effects_lock_key($charge_id); if(add_option($lock_key,time(),'',false)) return true; $locked_at=absint(get_option($lock_key,0)); if($locked_at>0 && $locked_at < time()-300){ delete_option($lock_key); if(add_option($lock_key,time(),'',false)) return true; } return new WP_Error('charge_refund_effects_locked','Cumulative Charge refund effects are already being processed.'); }
private function mrm_release_charge_refund_effects_lock($charge_id) { delete_option($this->mrm_charge_refund_effects_lock_key($charge_id)); }
private function mrm_store_charge_refund_effects_state($charge_id,$summary,$full_effects_applied,$transition_refund_id='') { $charge_id=sanitize_text_field($charge_id); $summary=is_array($summary)?$summary:array(); if($charge_id==='') return new WP_Error('charge_refund_state_id_missing','The Charge ID required for cumulative refund state is missing.'); $value=array('charge_id'=>$charge_id,'charge_amount_cents'=>absint($summary['charge_amount_cents'] ?? 0),'succeeded_refund_cents'=>absint($summary['succeeded_refund_cents'] ?? 0),'is_full_refund'=>!empty($summary['is_full_refund'])?1:0,'full_effects_applied'=>$full_effects_applied?1:0,'full_transition_refund_id'=>sanitize_text_field($transition_refund_id),'updated_at'=>current_time('mysql')); update_option($this->mrm_charge_refund_effects_state_key($charge_id),$value,false); $stored=$this->mrm_get_charge_refund_effects_state($charge_id); foreach(array('charge_id','charge_amount_cents','succeeded_refund_cents','is_full_refund','full_effects_applied','full_transition_refund_id') as $key){ if(!array_key_exists($key,$stored) || (string)$stored[$key] !== (string)$value[$key]) return new WP_Error('charge_refund_state_save_failed','The cumulative Charge refund-effects state could not be verified.'); } return true; }

private function mrm_refund_effects_state_key($refund_id) { return 'mrm_refund_effects_'.substr(hash('sha256',sanitize_text_field($refund_id)),0,40); }
private function mrm_refund_effects_lock_key($refund_id) { return 'mrm_refund_effects_lock_'.substr(hash('sha256',sanitize_text_field($refund_id)),0,40); }
private function mrm_refund_effects_status_applied($refund_id, $status) { $state=get_option($this->mrm_refund_effects_state_key($refund_id),array()); return is_array($state) && sanitize_key($state['last_status'] ?? '')===sanitize_key($status); }
private function mrm_claim_refund_effects_lock($refund_id) { $lock_key=$this->mrm_refund_effects_lock_key($refund_id); if(add_option($lock_key,time(),'',false)) return true; $locked_at=absint(get_option($lock_key,0)); if($locked_at>0 && $locked_at < time()-300){ delete_option($lock_key); if(add_option($lock_key,time(),'',false)) return true; } return new WP_Error('refund_effects_locked','Refund business effects are already being processed.'); }
private function mrm_release_refund_effects_lock($refund_id) { delete_option($this->mrm_refund_effects_lock_key($refund_id)); }
private function mrm_store_refund_effects_state($refund_id, $status, $summary) { $summary=is_array($summary)?$summary:array(); return update_option($this->mrm_refund_effects_state_key($refund_id),array('refund_id'=>sanitize_text_field($refund_id),'last_status'=>sanitize_key($status),'charge_id'=>sanitize_text_field($summary['charge_id'] ?? ''),'charge_amount_cents'=>absint($summary['charge_amount_cents'] ?? 0),'succeeded_refund_cents'=>absint($summary['succeeded_refund_cents'] ?? 0),'is_full_refund'=>!empty($summary['is_full_refund'])?1:0,'applied_at'=>current_time('mysql')),false); }
private function mrm_refund_charge_summary($charge) { if(!is_array($charge)) return new WP_Error('refund_charge_invalid','The Stripe Charge object was invalid.'); $charge_id=sanitize_text_field($charge['id'] ?? ''); $charge_amount=absint($charge['amount'] ?? 0); if($charge_id==='' || $charge_amount<=0) return new WP_Error('refund_charge_reference_invalid','The Stripe Charge amount or ID was invalid.'); $refunds=$this->mrm_stripe_list_all_refunds_for_charge($charge_id); if(is_wp_error($refunds)) return $refunds; $succeeded_total=0; $succeeded_ids=array(); foreach((array)$refunds as $refund){ if(sanitize_key($refund['status'] ?? '')!=='succeeded') continue; $succeeded_total+=absint($refund['amount'] ?? 0); $refund_id=sanitize_text_field($refund['id'] ?? ''); if($refund_id!=='') $succeeded_ids[]=$refund_id; } $succeeded_total=min($charge_amount,max(0,$succeeded_total)); return array('charge_id'=>$charge_id,'charge_amount_cents'=>$charge_amount,'succeeded_refund_cents'=>$succeeded_total,'remaining_cents'=>max(0,$charge_amount-$succeeded_total),'is_full_refund'=>$succeeded_total>=$charge_amount,'is_partial_refund'=>($succeeded_total>0 && $succeeded_total<$charge_amount),'succeeded_refund_ids'=>array_values(array_unique($succeeded_ids))); }

private function mrm_apply_successful_refund_business_effects($refund, $charge) {
  global $wpdb;
  if(!is_array($refund)) return new WP_Error('successful_refund_invalid','The successful Refund object was invalid.');
  $refund_id=sanitize_text_field($refund['id'] ?? ''); if($refund_id==='') return new WP_Error('successful_refund_id_missing','The successful Refund ID is missing.');
  $refund_lock=$this->mrm_claim_refund_effects_lock($refund_id); if(is_wp_error($refund_lock)) return $refund_lock;
  $charge_id=sanitize_text_field(is_array($charge)?($charge['id'] ?? ''):''); $charge_locked=false;
  try {
    if($charge_id==='') return new WP_Error('successful_refund_charge_missing','The successful Refund has no usable Charge ID.');
    $charge_lock=$this->mrm_claim_charge_refund_effects_lock($charge_id); if(is_wp_error($charge_lock)) return $charge_lock; $charge_locked=true;
    $summary=$this->mrm_refund_charge_summary($charge); if(is_wp_error($summary)) return $summary;
    $refund_already_applied=$this->mrm_refund_effects_status_applied($refund_id,'succeeded');
    $charge_state=$this->mrm_get_charge_refund_effects_state($charge_id);
    $full_effects_already_applied=!empty($charge_state['full_effects_applied']);
    $apply_full_transition=!empty($summary['is_full_refund']) && !$full_effects_already_applied;
    $pi_id=$this->mrm_stripe_expandable_id($refund['payment_intent'] ?? ''); $order=array(); $order_id=0;
    if($pi_id!==''){ $order=$this->get_order_by_pi($pi_id); if(is_array($order) && !empty($order['id'])){ $order_id=absint($order['id']); $addon_refund_id=sanitize_text_field($this->mrm_get_order_meta_value($order,'mrm_subscription_addon_refund_id','')); if($addon_refund_id!=='' && hash_equals($addon_refund_id,$refund_id)){ $this->mrm_set_order_meta_flag($order_id,'mrm_subscription_addon_refund_status','succeeded'); $this->mrm_set_order_meta_flag($order_id,'mrm_sheet_music_subscription_status','activation_failed_addon_refund_succeeded'); } } }
    if($apply_full_transition){
      if($order_id>0){ $this->update_order_status_from_pi($pi_id,'refunded','refunded',array('mrm_refunded_at'=>current_time('mysql'),'mrm_refund_id'=>$refund_id,'mrm_refund_status'=>'succeeded','mrm_cumulative_refund_cents'=>(string)$summary['succeeded_refund_cents'])); $this->mrm_void_standard_payouts_for_refunded_order($order_id,$pi_id,'stripe_cumulative_full_refund'); $product_type=sanitize_key($order['product_type'] ?? ''); if($product_type==='sheet_music'){ $revoke_result=$this->mrm_revoke_sheet_music_entitlements_for_payment_intent($pi_id); if(is_wp_error($revoke_result)) return $revoke_result; } $resolved=$this->mrm_tax_resolve_alerts_by_reference('payment_intent_id',$pi_id,array('partial_refund_business_review_required')); if(is_wp_error($resolved)) return $resolved; }
      $this->mrm_void_subscription_composer_payout_from_refunded_charge($charge,'stripe_cumulative_full_refund'); do_action('mrm_payments_hub_refund_succeeded',$refund,$charge,$summary);
    } elseif(empty($summary['is_full_refund']) && !$refund_already_applied) {
      if($order_id>0){ $this->update_order_status_from_pi($pi_id,'partially_refunded','partially_refunded',array('mrm_refund_id'=>$refund_id,'mrm_refund_status'=>'succeeded','mrm_cumulative_refund_cents'=>(string)$summary['succeeded_refund_cents'],'mrm_charge_amount_cents'=>(string)$summary['charge_amount_cents'])); $alert_result=$this->mrm_tax_create_alert('', 'partial_refund_business_review_required','refund',0,array('message'=>'A partial refund succeeded. Access remains active and the full payout was not voided. Review the proportional payout, accounting, and customer records.','refund_id'=>$refund_id,'payment_intent_id'=>$pi_id,'charge_id'=>$summary['charge_id'],'succeeded_refund_cents'=>$summary['succeeded_refund_cents'],'charge_amount_cents'=>$summary['charge_amount_cents']),sanitize_key($refund_id)); if(is_wp_error($alert_result)) return $alert_result; }
      do_action('mrm_payments_hub_refund_partially_succeeded',$refund,$charge,$summary);
    }
    $charge_state_result=$this->mrm_store_charge_refund_effects_state($charge_id,$summary,!empty($summary['is_full_refund']),$apply_full_transition?$refund_id:sanitize_text_field($charge_state['full_transition_refund_id'] ?? '')); if(is_wp_error($charge_state_result)) return $charge_state_result;
    $saved=$this->mrm_store_refund_effects_state($refund_id,'succeeded',$summary); if($saved===false){ $stored=get_option($this->mrm_refund_effects_state_key($refund_id),array()); if(!is_array($stored) || sanitize_key($stored['last_status'] ?? '')!=='succeeded') return new WP_Error('refund_effects_state_save_failed','The successful Refund effects state could not be saved.'); }
    return true;
  } finally { if($charge_locked) $this->mrm_release_charge_refund_effects_lock($charge_id); $this->mrm_release_refund_effects_lock($refund_id); }
}



private function mrm_apply_failed_refund_recovery($refund, $charge) {
  global $wpdb;
  if(!is_array($refund)) return new WP_Error('failed_refund_invalid','The failed Refund object was invalid.');
  $refund_id=sanitize_text_field($refund['id'] ?? ''); $refund_status=sanitize_key($refund['status'] ?? ''); if($refund_id==='') return new WP_Error('failed_refund_id_missing','The failed Refund ID is missing.');
  if($this->mrm_refund_effects_status_applied($refund_id,$refund_status)) return true;
  $refund_lock=$this->mrm_claim_refund_effects_lock($refund_id); if(is_wp_error($refund_lock)) return $refund_lock;
  $charge_id=sanitize_text_field(is_array($charge)?($charge['id'] ?? ''):''); $charge_locked=false;
  try {
    if($this->mrm_refund_effects_status_applied($refund_id,$refund_status)) return true;
    if($charge_id==='') return new WP_Error('failed_refund_charge_missing','The failed Refund has no usable Charge ID.');
    $charge_lock=$this->mrm_claim_charge_refund_effects_lock($charge_id); if(is_wp_error($charge_lock)) return $charge_lock; $charge_locked=true;
    $summary=$this->mrm_refund_charge_summary($charge); if(is_wp_error($summary)) return $summary;
    $charge_state=$this->mrm_get_charge_refund_effects_state($charge_id); $pi_id=$this->mrm_stripe_expandable_id($refund['payment_intent'] ?? '');
    if($pi_id!==''){ $order=$this->get_order_by_pi($pi_id); if(is_array($order) && !empty($order['id'])){ $order_id=absint($order['id']); $addon_refund_id=sanitize_text_field($this->mrm_get_order_meta_value($order,'mrm_subscription_addon_refund_id','')); if($addon_refund_id!=='' && hash_equals($addon_refund_id,$refund_id)){ $this->mrm_set_order_meta_flag($order_id,'mrm_subscription_addon_refund_status',$refund_status); $this->mrm_set_order_meta_flag($order_id,'mrm_sheet_music_subscription_status','activation_failed_addon_refund_failed'); } if(!empty($summary['is_full_refund'])){ $new_order_status='refunded'; $new_stripe_status='refunded'; } elseif(!empty($summary['is_partial_refund'])){ $new_order_status='partially_refunded'; $new_stripe_status='partially_refunded'; } else { $new_order_status='paid'; $new_stripe_status='succeeded'; } $this->update_order_status_from_pi($pi_id,$new_order_status,$new_stripe_status,array('mrm_refund_id'=>$refund_id,'mrm_refund_status'=>$refund_status,'mrm_refund_failed_at'=>current_time('mysql'),'mrm_cumulative_refund_cents'=>(string)$summary['succeeded_refund_cents'])); $wpdb->update($this->table_sheet_music_access(),array('revoked_at'=>!empty($summary['is_full_refund'])?current_time('mysql'):null),array('source_id'=>$pi_id)); } }
    do_action('mrm_payments_hub_refund_failed',$refund,$charge,$summary);
    $alert_result=$this->mrm_tax_create_alert('', 'refund_failure_recovery_required','refund',0,array('message'=>'Refund '.$refund_id.' entered status '.$refund_status.'. The tax ledger was restored, but order, access, payout, registration, and accounting records require review.','refund_id'=>$refund_id,'payment_intent_id'=>$pi_id,'charge_id'=>$charge_id,'refund_status'=>$refund_status,'failure_reason'=>sanitize_text_field($refund['failure_reason'] ?? ''),'remaining_successful_refund_cents'=>$summary['succeeded_refund_cents'],'charge_amount_cents'=>$summary['charge_amount_cents']),sanitize_key($refund_id)); if(is_wp_error($alert_result)) return $alert_result;
    $charge_state_result=$this->mrm_store_charge_refund_effects_state($charge_id,$summary,!empty($summary['is_full_refund']) ? !empty($charge_state['full_effects_applied']) : false,!empty($summary['is_full_refund']) ? sanitize_text_field($charge_state['full_transition_refund_id'] ?? '') : ''); if(is_wp_error($charge_state_result)) return $charge_state_result;
    $saved=$this->mrm_store_refund_effects_state($refund_id,$refund_status,$summary); if($saved===false){ $stored=get_option($this->mrm_refund_effects_state_key($refund_id),array()); if(!is_array($stored) || sanitize_key($stored['last_status'] ?? '')!==$refund_status) return new WP_Error('refund_effects_state_save_failed','The failed Refund effects state could not be saved.'); }
    return true;
  } finally { if($charge_locked) $this->mrm_release_charge_refund_effects_lock($charge_id); $this->mrm_release_refund_effects_lock($refund_id); }
}



private function mrm_tax_schedule_refund_lifecycle_retry($refund_id, $attempt, $message) {
  $refund_id = sanitize_text_field($refund_id); $attempt = absint($attempt);
  if ($refund_id === '' || $attempt > 6) return new WP_Error('refund_lifecycle_retry_invalid','The refund-lifecycle retry parameters were invalid.');
  return $this->mrm_tax_schedule_checked_retry('mrm_pay_hub_retry_refund_lifecycle', array($refund_id, $attempt), '', 'refund_lifecycle_reconciliation_failed', 'refund', array('refund_id'=>$refund_id,'attempt'=>$attempt), sanitize_key($refund_id), $message);
}

private function mrm_tax_refund_lifecycle_failure($refund_id, $attempt, $message, $details = array()) {
  $refund_id = sanitize_text_field($refund_id); $attempt = absint($attempt); $message = sanitize_textarea_field($message); $details = is_array($details) ? $details : array();
  $details['message']=$message; $details['refund_id']=$refund_id; $details['attempt']=$attempt;
  $alert_result = $this->mrm_tax_create_alert('', 'refund_lifecycle_reconciliation_failed', 'refund', 0, $details, sanitize_key($refund_id !== '' ? $refund_id : hash('sha256',$message)));
  if (is_wp_error($alert_result)) return $alert_result;
  if ($refund_id !== '' && $attempt < 6) { $schedule_result=$this->mrm_tax_schedule_refund_lifecycle_retry($refund_id,$attempt+1,$message); if (is_wp_error($schedule_result)) return $schedule_result; }
  return new WP_Error('refund_lifecycle_reconciliation_failed', $message);
}

public function mrm_tax_retry_refund_lifecycle($refund_id, $attempt = 1) {
  $refund_id = sanitize_text_field($refund_id); $attempt = absint($attempt); if ($refund_id === '') return;
  $result = $this->mrm_handle_refund_lifecycle_webhook(array('id'=>$refund_id), $attempt);
  if (is_wp_error($result)) $this->stripe_debug_log('Refund lifecycle reconciliation retry failed.', array('refund_id'=>$refund_id,'attempt'=>$attempt,'message'=>$result->get_error_message()));
}

private function mrm_handle_refund_lifecycle_webhook($refund, $attempt = 0) {
  if (!is_array($refund)) return new WP_Error('refund_object_invalid','The Stripe refund event did not contain a valid Refund.');
  $attempt=absint($attempt); $refund_id=sanitize_text_field($refund['id'] ?? ''); if ($refund_id === '') return new WP_Error('refund_id_missing','The Stripe refund event did not contain a Refund ID.');
  $current=$this->stripe_retrieve_refund($refund_id); if (is_wp_error($current)) return $this->mrm_tax_refund_lifecycle_failure($refund_id,$attempt,'Refund '.$refund_id.' could not be retrieved from Stripe: '.$current->get_error_message());
  $status=sanitize_key($current['status'] ?? ''); $payment_intent_id=$this->mrm_stripe_expandable_id($current['payment_intent'] ?? ''); $charge_id=$this->mrm_stripe_expandable_id($current['charge'] ?? ''); $charge=array(); $invoice_id='';
  if ($charge_id !== '') { $charge_result=$this->stripe_retrieve_charge($charge_id); if (is_wp_error($charge_result)) return $this->mrm_tax_refund_lifecycle_failure($refund_id,$attempt,'The Charge for refund '.$refund_id.' could not be retrieved: '.$charge_result->get_error_message(),array('payment_intent_id'=>$payment_intent_id,'charge_id'=>$charge_id,'refund_status'=>$status)); $charge=$charge_result; $invoice_id=$this->mrm_stripe_expandable_id($charge['invoice'] ?? ''); }
  if (in_array($status,array('pending','requires_action'),true)) return $this->mrm_tax_refund_lifecycle_failure($refund_id,$attempt,'Refund '.$refund_id.' has not reached a final status. Current status: '.$status.'.',array('payment_intent_id'=>$payment_intent_id,'charge_id'=>$charge_id,'invoice_id'=>$invoice_id,'refund_status'=>$status));
  if (!in_array($status,array('succeeded','failed','canceled'),true)) return $this->mrm_tax_refund_lifecycle_failure($refund_id,$attempt,'Refund '.$refund_id.' has an unsupported status: '.($status!==''?$status:'unknown').'.',array('payment_intent_id'=>$payment_intent_id,'charge_id'=>$charge_id,'invoice_id'=>$invoice_id,'refund_status'=>$status));
  if ($invoice_id !== '') $tax_result=$this->mrm_tax_sync_subscription_invoice_refunds($invoice_id,$attempt); else { if ($payment_intent_id === '') return $this->mrm_tax_refund_lifecycle_failure($refund_id,$attempt,'Refund '.$refund_id.' has no PaymentIntent or Invoice reference.',array('charge_id'=>$charge_id,'refund_status'=>$status)); $tax_result=$this->mrm_tax_sync_refund_reversal($payment_intent_id,$refund_id,$attempt); }
  if (is_wp_error($tax_result)) return $tax_result;
  $resolved=$this->mrm_tax_resolve_alerts_by_reference('refund_id',$refund_id,array('refund_lifecycle_reconciliation_failed')); if (is_wp_error($resolved)) return $resolved;
  if ($status === 'succeeded') return $this->mrm_apply_successful_refund_business_effects($current,$charge);
  $recovery_result=$this->mrm_apply_failed_refund_recovery($current,$charge); if (is_wp_error($recovery_result)) return $recovery_result; return true;
}

private function mrm_handle_charge_refunded_webhook($charge) {
  if (!is_array($charge)) return new WP_Error('charge_refunded_object_invalid', 'The charge.refunded event did not contain a valid Charge.');
  $charge_id=sanitize_text_field($charge['id'] ?? ''); if ($charge_id === '') return new WP_Error('charge_refunded_id_missing', 'The charge.refunded event did not contain a Charge ID.');
  $refunds=$this->mrm_stripe_list_all_refunds_for_charge($charge_id); if (is_wp_error($refunds)) return $refunds; $errors=array();
  foreach ($refunds as $refund) { $result=$this->mrm_handle_refund_lifecycle_webhook($refund,0); if (is_wp_error($result)) $errors[]=$result->get_error_message(); }
  return $this->mrm_tax_required_webhook_result('charge_refund_reconciliation_failed', $errors);
}

private function mrm_handle_refund_created_webhook($refund) { return $this->mrm_handle_refund_lifecycle_webhook($refund, 0); }
private function mrm_handle_refund_updated_webhook($refund) { return $this->mrm_handle_refund_lifecycle_webhook($refund, 0); }
private function mrm_handle_refund_failed_webhook($refund) { return $this->mrm_handle_refund_lifecycle_webhook($refund, 0); }


  private function mrm_subscription_tax_location_problem($subscription = array(), $invoice = array()) {
    $subscription = is_array($subscription) ? $subscription : array();
    $invoice = is_array($invoice) ? $invoice : array();
    $subscription_reason = sanitize_key($subscription['automatic_tax']['disabled_reason'] ?? '');
    $invoice_status = sanitize_key($invoice['automatic_tax']['status'] ?? '');
    $invoice_reason = sanitize_key($invoice['automatic_tax']['disabled_reason'] ?? '');
    $finalization_error_code = sanitize_key($invoice['last_finalization_error']['code'] ?? '');
    if ($subscription_reason === 'requires_location_inputs') return 'requires_location_inputs';
    if ($invoice_status === 'requires_location_inputs') return 'requires_location_inputs';
    if ($invoice_reason === 'finalization_requires_location_inputs') return 'requires_location_inputs';
    if ($finalization_error_code === 'customer_tax_location_invalid') return 'customer_tax_location_invalid';
    return '';
  }

  private function mrm_send_subscription_tax_attention_emails($local_subscription, $reason) {
    global $wpdb;
    $local_subscription = is_array($local_subscription) ? $local_subscription : array();
    $subscription_id = sanitize_text_field($local_subscription['stripe_subscription_id'] ?? '');
    $email = sanitize_email($local_subscription['email_plain'] ?? '');
    if ($subscription_id === '') return false;
    if (!empty($local_subscription['tax_attention_notified_at'])) return true;
    $manage_url = $this->mrm_subscription_manage_url($local_subscription['portal_token'] ?? '');
    $details = '<div><strong>Subscription:</strong> ' . esc_html($subscription_id) . '</div>' . '<div><strong>Issue:</strong> ' . esc_html($reason) . '</div>';
    $customer_sent = false;
    if ($email && is_email($email)) {
      $customer_body = $this->mrm_email_wrap_html('Billing address update required', '<p>Stripe could not confirm a valid tax location for your sheet-music subscription. Future automatic billing has been paused until your billing address is corrected.</p>', $details, $manage_url, 'Update Billing Information', '<p style="margin-top:16px;">Your current paid access remains available according to your existing subscription period.</p>');
      $customer_sent = wp_mail($email, 'Billing address update required for your sheet music subscription', $customer_body, array('Content-Type: text/html; charset=UTF-8', 'From: Low Brass Lessons <no-reply@lowbrass-lessons.com>'));
    }
    $admin_email = sanitize_email(get_option('admin_email'));
    if ($admin_email && is_email($admin_email)) {
      $admin_body = $this->mrm_email_wrap_html('Subscription tax location requires attention', '<p>A sheet-music subscription has been paused because Stripe could not confirm the customer’s tax location.</p>', $details);
      wp_mail($admin_email, 'Subscription tax location requires attention', $admin_body, array('Content-Type: text/html; charset=UTF-8', 'From: Low Brass Lessons <no-reply@lowbrass-lessons.com>'));
    }
    $wpdb->update($this->table_sheet_music_subscriptions(), array('tax_attention_notified_at' => current_time('mysql'), 'updated_at' => current_time('mysql')), array('stripe_subscription_id' => $subscription_id));
    return $customer_sent;
  }

  private function mrm_stripe_safe_metadata_value($value, $maximum_length = 450) {
    $value = sanitize_text_field((string)$value);
    $maximum_length = max(1, min(500, absint($maximum_length)));
    if (function_exists('mb_substr')) return mb_substr($value, 0, $maximum_length, 'UTF-8');
    return substr($value, 0, $maximum_length);
  }

  private function mrm_is_managed_sheet_music_subscription($subscription) {
    if (!is_array($subscription)) return false;
    $configured_price_id = sanitize_text_field($this->subscription_price_id());
    foreach ((array)($subscription['items']['data'] ?? array()) as $item) {
      $price_id = sanitize_text_field($item['price']['id'] ?? '');
      if ($configured_price_id !== '' && $price_id === $configured_price_id) return true;
    }
    $source = sanitize_key($subscription['metadata']['mrm_source'] ?? '');
    return ($source === 'sheet_music_addon_initial_checkout');
  }

  private function mrm_stripe_list_all_managed_sheet_music_subscriptions() {
    $managed = array(); $starting_after = ''; $pagination_guard = 0;
    do {
      $pagination_guard++;
      if ($pagination_guard > 1000) return new WP_Error('subscription_inventory_pagination_limit', 'Stripe subscription pagination exceeded the safety limit.');
      $params = array('status' => 'all', 'limit' => 100);
      if ($starting_after !== '') $params['starting_after'] = $starting_after;
      $response = $this->stripe_api_request('GET', '/v1/subscriptions', $params);
      if (is_wp_error($response)) return new WP_Error('subscription_inventory_api_failed', 'The Stripe subscription inventory could not be retrieved: ' . $response->get_error_message());
      if (!array_key_exists('data', $response) || !is_array($response['data'])) return new WP_Error('subscription_inventory_response_invalid', 'Stripe returned an invalid subscription inventory response.');
      $page = $response['data'];
      foreach ($page as $subscription) {
        if (!$this->mrm_is_managed_sheet_music_subscription($subscription)) continue;
        $status = sanitize_key($subscription['status'] ?? '');
        if (!in_array($status, array('trialing','active','past_due','unpaid'), true)) continue;
        $subscription_id = sanitize_text_field($subscription['id'] ?? '');
        if ($subscription_id === '') return new WP_Error('subscription_inventory_id_missing', 'Stripe returned a managed subscription without an ID.');
        $managed[$subscription_id] = $subscription;
      }
      if (!empty($response['has_more'])) {
        if (empty($page)) return new WP_Error('subscription_inventory_pagination_empty', 'Stripe reported more subscriptions but returned an empty page.');
        $last = end($page); $next_starting_after = sanitize_text_field($last['id'] ?? '');
        if ($next_starting_after === '' || $next_starting_after === $starting_after) return new WP_Error('subscription_inventory_pagination_stalled', 'Stripe subscription pagination could not advance.');
        $starting_after = $next_starting_after;
      } else $starting_after = '';
    } while ($starting_after !== '');
    return array_values($managed);
  }

  private function mrm_tax_current_subscription_inventory_context($force_refresh = false) {
    $key=trim((string)$this->secret_key()); if($key==='') return new WP_Error('stripe_inventory_key_missing','The Stripe API key is missing.');
    $mode=$this->mrm_tax_is_live_stripe_key()?'live':'test'; $credential_fingerprint=hash_hmac('sha256',$key,wp_salt('auth')); $price_id=sanitize_text_field($this->subscription_price_id());
    if($price_id==='') return new WP_Error('stripe_inventory_price_missing','The configured sheet-music subscription Price ID is missing.');
    $expected_tax_code=$this->mrm_expected_subscription_tax_code(); if($expected_tax_code==='') return new WP_Error('stripe_inventory_tax_model_missing','The sheet-music subscription tax model is invalid.');
    $cache_material=implode('|',array($credential_fingerprint,$mode,$price_id,self::STRIPE_CORE_API_VERSION,self::TAX_SUBSCRIPTION_CONFIG_PROFILE_VERSION,$expected_tax_code)); $cache_key='mrm_stripe_inventory_context_'.substr(hash('sha256',$cache_material),0,32);
    if(!$force_refresh){ $cached=get_transient($cache_key); if(is_array($cached) && !empty($cached['account_id']) && !empty($cached['configuration_fingerprint'])) return $cached; }
    $account=$this->stripe_api_request('GET','/v1/account'); if(is_wp_error($account)) return new WP_Error('stripe_inventory_account_failed','The active Stripe account could not be identified: '.$account->get_error_message());
    $account_id=sanitize_text_field($account['id'] ?? ''); if($account_id==='') return new WP_Error('stripe_inventory_account_id_missing','Stripe did not return an account ID.');
    $configuration=$this->mrm_verify_sheet_music_subscription_tax_configuration($price_id); if(is_wp_error($configuration)) return new WP_Error('subscription_tax_configuration_invalid',$configuration->get_error_message());
    $profile=is_array($configuration['profile'] ?? null)?$configuration['profile']:array(); $configuration_fingerprint=sanitize_text_field($configuration['configuration_fingerprint'] ?? '');
    if(empty($profile) || $configuration_fingerprint==='') return new WP_Error('subscription_tax_configuration_profile_missing','The Stripe subscription tax-configuration profile could not be created.');
    $context=array('account_id'=>$account_id,'mode'=>$mode,'credential_fingerprint'=>$credential_fingerprint,'price_id'=>$price_id,'product_id'=>sanitize_text_field($profile['product_id'] ?? ''),'expected_tax_code'=>sanitize_text_field($profile['expected_tax_code'] ?? ''),'actual_tax_code'=>sanitize_text_field($profile['actual_tax_code'] ?? ''),'configuration_fingerprint'=>$configuration_fingerprint,'subscription_configuration'=>$profile,'configuration_profile_version'=>self::TAX_SUBSCRIPTION_CONFIG_PROFILE_VERSION,'api_version'=>self::STRIPE_CORE_API_VERSION);
    set_transient($cache_key,$context,2 * MINUTE_IN_SECONDS); return $context;
  }

  private function mrm_tax_subscription_inventory_snapshot_readiness($maximum_age_minutes = self::TAX_SUBSCRIPTION_INVENTORY_MAX_AGE_MINUTES) {
    $current=$this->mrm_tax_current_subscription_inventory_context(true); if(is_wp_error($current)) return $current;
    $snapshot=get_option(self::OPT_TAX_SUBSCRIPTION_INVENTORY_SNAPSHOT,array()); if(!is_array($snapshot)) return new WP_Error('subscription_inventory_snapshot_missing','The Stripe subscription inventory snapshot is missing.');
    $required_matches=array('account_id','mode','credential_fingerprint','price_id','product_id','expected_tax_code','actual_tax_code','configuration_fingerprint','configuration_profile_version','api_version');
    foreach($required_matches as $key){ if(!array_key_exists($key,$snapshot) || !array_key_exists($key,$current) || !hash_equals((string)$current[$key],(string)$snapshot[$key])) return new WP_Error('subscription_inventory_snapshot_mismatch','The Stripe subscription inventory snapshot does not match the active account, mode, key, Price, Product, tax code, recurring configuration, or API version.'); }
    $synced_at=sanitize_text_field($snapshot['synced_at'] ?? ''); if($synced_at==='') return new WP_Error('subscription_inventory_snapshot_time_missing','The Stripe subscription inventory snapshot has no synchronization time.');
    try { $synced=new DateTimeImmutable($synced_at,wp_timezone()); $cutoff=new DateTimeImmutable('-'.absint($maximum_age_minutes).' minutes',wp_timezone()); if($synced<$cutoff) return new WP_Error('subscription_inventory_snapshot_stale','The Stripe subscription inventory snapshot is stale.'); }
    catch(Throwable $error){ return new WP_Error('subscription_inventory_snapshot_time_invalid','The Stripe subscription inventory synchronization time is invalid.'); }
    return true;
  }

  private function mrm_stripe_list_subscription_invoices_by_status($subscription_id, $status) {
    $subscription_id = sanitize_text_field($subscription_id); $status = sanitize_key($status);
    if ($subscription_id === '') return new WP_Error('subscription_invoice_list_id_missing','The Stripe subscription ID is missing.');
    if (!in_array($status, array('draft','open'), true)) return new WP_Error('subscription_invoice_list_status_invalid','The requested invoice status is invalid.');
    $invoices=array(); $starting_after=''; $pagination_guard=0;
    do { $pagination_guard++; if ($pagination_guard > 1000) return new WP_Error('subscription_invoice_pagination_limit','Stripe invoice pagination exceeded the safety limit.');
      $params=array('subscription'=>$subscription_id,'status'=>$status,'limit'=>100); if($starting_after!=='') $params['starting_after']=$starting_after;
      $response=$this->stripe_api_request('GET','/v1/invoices',$params); if(is_wp_error($response)) return new WP_Error('subscription_invoice_list_failed','Stripe invoices for subscription '.$subscription_id.' could not be retrieved: '.$response->get_error_message());
      if(!array_key_exists('data',$response)||!is_array($response['data'])) return new WP_Error('subscription_invoice_list_invalid','Stripe returned an invalid invoice-list response.');
      $page=$response['data']; foreach($page as $invoice){ $invoice_id=sanitize_text_field($invoice['id'] ?? ''); if($invoice_id==='') return new WP_Error('subscription_invoice_id_missing','Stripe returned an invoice without an ID.'); $invoices[$invoice_id]=$invoice; }
      if(!empty($response['has_more'])){ if(empty($page)) return new WP_Error('subscription_invoice_pagination_empty','Stripe reported more invoices but returned an empty page.'); $last=end($page); $next_starting_after=sanitize_text_field($last['id'] ?? ''); if($next_starting_after===''||$next_starting_after===$starting_after) return new WP_Error('subscription_invoice_pagination_stalled','Stripe invoice pagination could not advance.'); $starting_after=$next_starting_after; } else $starting_after='';
    } while($starting_after !== ''); return array_values($invoices);
  }

  private function mrm_tax_verify_subscription_payment_pause($subscription_id) {
    $subscription_id=sanitize_text_field($subscription_id); if($subscription_id==='') return new WP_Error('subscription_pause_verification_id_missing','The Stripe subscription ID is missing.');
    $subscription=$this->stripe_retrieve_subscription($subscription_id); if(is_wp_error($subscription)) return new WP_Error('subscription_pause_verification_failed','Subscription '.$subscription_id.' could not be retrieved after it was paused: '.$subscription->get_error_message());
    if(sanitize_key($subscription['pause_collection']['behavior'] ?? '') !== 'keep_as_draft') return new WP_Error('subscription_pause_not_active','Subscription '.$subscription_id.' is not confirmed paused with keep_as_draft.'); return $subscription;
  }

  private function mrm_tax_contain_existing_subscription_invoices($subscription_id, $hold_status, $reason) {
    $subscription_id=sanitize_text_field($subscription_id); $hold_status=sanitize_key($hold_status); $reason=sanitize_text_field($reason); if($subscription_id==='') return new WP_Error('subscription_invoice_hold_id_missing','The Stripe subscription ID is missing.');
    $actions=array(); $errors=array();
    $draft_invoices=$this->mrm_stripe_list_subscription_invoices_by_status($subscription_id,'draft'); if(is_wp_error($draft_invoices)){ $errors[]=$draft_invoices->get_error_message(); $draft_invoices=array(); }
    foreach((array)$draft_invoices as $invoice){ $invoice_id=sanitize_text_field($invoice['id'] ?? ''); if($invoice_id===''){ $errors[]='Stripe returned a draft invoice without an ID.'; continue; } $updated=$this->stripe_api_request('POST','/v1/invoices/'.rawurlencode($invoice_id),array('auto_advance'=>'false')); if(is_wp_error($updated)){ $errors[]='Draft invoice '.$invoice_id.' could not be frozen: '.$updated->get_error_message(); continue; } if(sanitize_key($updated['status'] ?? '')!=='draft' || !array_key_exists('auto_advance',$updated) || !empty($updated['auto_advance'])){ $errors[]='Draft invoice '.$invoice_id.' was not verified as draft with automatic advancement disabled.'; continue; } $actions[]=array('invoice_id'=>$invoice_id,'original_status'=>'draft','action'=>'auto_advance_disabled','result_status'=>'draft','verified_at'=>current_time('mysql')); }
    $open_invoices=$this->mrm_stripe_list_subscription_invoices_by_status($subscription_id,'open');
    if(is_wp_error($open_invoices)){ $errors[]=$open_invoices->get_error_message(); $open_invoices=array(); }
    foreach((array)$open_invoices as $invoice){
      $invoice_id=sanitize_text_field($invoice['id'] ?? '');
      if($invoice_id===''){ $errors[]='Stripe returned an open invoice without an ID.'; continue; }
      $updated=$invoice;
      if(!array_key_exists('auto_advance',$invoice) || !empty($invoice['auto_advance'])){
        $updated=$this->stripe_api_request('POST','/v1/invoices/'.rawurlencode($invoice_id),array('auto_advance'=>'false'));
      }
      if(is_wp_error($updated)){ $errors[]='Open invoice '.$invoice_id.' could not have automatic collection disabled: '.$updated->get_error_message(); continue; }
      if(sanitize_key($updated['status'] ?? '')!=='open' || !array_key_exists('auto_advance',$updated) || !empty($updated['auto_advance'])){ $errors[]='Open invoice '.$invoice_id.' was not verified as open with automatic collection disabled.'; continue; }
      $actions[]=array('invoice_id'=>$invoice_id,'original_status'=>'open','action'=>'auto_advance_disabled','result_status'=>'open','verified_at'=>current_time('mysql'));
    }
    if(!empty($errors)){ $message=implode(' | ',array_values(array_unique($errors))); $this->mrm_tax_create_alert('','subscription_invoice_hold_failed','subscription',0,array('message'=>$message,'subscription_id'=>$subscription_id,'hold_status'=>$hold_status,'hold_reason'=>$reason,'completed_actions'=>$actions),sanitize_key($subscription_id)); return new WP_Error('subscription_invoice_hold_failed',$message); }
    $this->mrm_tax_resolve_alerts_by_reference('subscription_id',$subscription_id,array('subscription_invoice_hold_failed')); return $actions;
  }

  private function mrm_contain_subscription_after_local_sync_failure($subscription, $reason, $allow_cancel = false) {
    if(!is_array($subscription)) return new WP_Error('invalid_subscription','Invalid Stripe subscription.'); $subscription_id=sanitize_text_field($subscription['id'] ?? ''); if($subscription_id==='') return new WP_Error('missing_subscription_id','Missing Stripe subscription ID.'); $reason=sanitize_text_field($reason);
    $paused=$this->stripe_update_subscription($subscription_id,array('pause_collection[behavior]'=>'keep_as_draft','metadata[mrm_tax_attention_status]'=>'local_sync_failed','metadata[mrm_tax_attention_reason]'=>$this->mrm_stripe_safe_metadata_value($reason))); $pause_error=is_wp_error($paused)?$paused:null;
    $invoice_result=$this->mrm_tax_contain_existing_subscription_invoices($subscription_id,'local_sync_failed',$reason); if(!is_wp_error($paused)){ $verification=$this->mrm_tax_verify_subscription_payment_pause($subscription_id); if(is_wp_error($verification)) $pause_error=$verification; }
    if(!$pause_error && !is_wp_error($invoice_result)) return true;
    if($allow_cancel && $pause_error){ $canceled=$this->stripe_api_request('DELETE','/v1/subscriptions/'.rawurlencode($subscription_id)); if(!is_wp_error($canceled)&&!is_wp_error($invoice_result)) return true; $cancel_message=is_wp_error($canceled)?$canceled->get_error_message():'The subscription was canceled, but existing invoices were not fully contained.'; return new WP_Error('subscription_sync_containment_failed','The subscription could not be safely contained. '.($pause_error?'Pause error: '.$pause_error->get_error_message().' ':'').'Cancel result: '.$cancel_message.(is_wp_error($invoice_result)?' Invoice error: '.$invoice_result->get_error_message():'')); }
    return new WP_Error('subscription_sync_containment_failed',($pause_error?$pause_error->get_error_message():'').($pause_error&&is_wp_error($invoice_result)?' | ':'').(is_wp_error($invoice_result)?$invoice_result->get_error_message():''));
  }

  private function mrm_apply_subscription_payment_hold($subscription, $hold_status, $reason, $pause_failure_alert_type) {
    global $wpdb; if(!is_array($subscription)) return new WP_Error('invalid_subscription','Invalid Stripe subscription.'); $subscription_id=sanitize_text_field($subscription['id'] ?? ''); if($subscription_id==='') return new WP_Error('missing_subscription_id','Missing Stripe subscription ID.');
    $hold_status=sanitize_key($hold_status); $reason=sanitize_text_field($reason); if(!in_array($hold_status,array('global_compliance_hold','requires_location_inputs','not_collecting_review_required','local_sync_failed'),true)) return new WP_Error('subscription_hold_status_invalid','The subscription hold status is invalid.'); $pause_failure_alert_type=sanitize_key($pause_failure_alert_type);
    $updated=$this->stripe_update_subscription($subscription_id,array('pause_collection[behavior]'=>'keep_as_draft','metadata[mrm_tax_attention_status]'=>$hold_status,'metadata[mrm_tax_attention_reason]'=>$this->mrm_stripe_safe_metadata_value($reason)));
    if(is_wp_error($updated)){ $this->mrm_tax_create_alert('',$pause_failure_alert_type,'subscription',0,array('message'=>'Subscription '.$subscription_id.' could not be placed on the required tax hold: '.$updated->get_error_message(),'subscription_id'=>$subscription_id,'hold_status'=>$hold_status,'hold_reason'=>$reason),sanitize_key($subscription_id)); return $updated; }
    $verified_subscription=$this->mrm_tax_verify_subscription_payment_pause($subscription_id); if(is_wp_error($verified_subscription)) return $verified_subscription;
    $invoice_actions=$this->mrm_tax_contain_existing_subscription_invoices($subscription_id,$hold_status,$reason); if(is_wp_error($invoice_actions)) return $invoice_actions;
    $local_sync=$this->mrm_sync_local_sheet_music_subscription_from_stripe($verified_subscription,sanitize_email($subscription['metadata']['mrm_customer_email'] ?? '')); if(is_wp_error($local_sync)) return $local_sync;
    $local=$this->mrm_get_sheet_music_subscription_by_stripe_id($subscription_id); if(!is_array($local)) return new WP_Error('subscription_hold_local_missing','The paused Stripe subscription could not be found in the local registry.'); $attention_since=!empty($local['tax_attention_since'])?$local['tax_attention_since']:current_time('mysql'); $now=current_time('mysql'); $wpdb->last_error='';
