    $held=$this->mrm_apply_subscription_payment_hold($subscription,$target_status,$target_reason,'subscription_global_tax_pause_failed'); if(is_wp_error($held)) return $held; return true;
  }

  private function mrm_tax_enforce_single_subscription_hold($subscription) {
    if (!is_array($subscription)) return new WP_Error('invalid_subscription', 'Invalid Stripe subscription.');
    if (!$this->mrm_is_managed_sheet_music_subscription($subscription)) return true;
    $readiness=$this->mrm_tax_core_live_checkout_readiness(); if(is_wp_error($readiness)) return $this->mrm_pause_subscription_for_global_tax_hold($subscription,$readiness);
    $subscription_id=sanitize_text_field($subscription['id'] ?? ''); if($subscription_id==='') return new WP_Error('missing_subscription_id','Missing Stripe subscription ID.');
    $local_sync=$this->mrm_sync_local_sheet_music_subscription_from_stripe($subscription, sanitize_email($subscription['metadata']['mrm_customer_email'] ?? ''));
    if(is_wp_error($local_sync)){ $containment=$this->mrm_contain_subscription_after_local_sync_failure($subscription,$local_sync->get_error_message(),false); if(is_wp_error($containment)) $this->mrm_tax_create_alert('','subscription_global_tax_pause_failed','subscription',0,array('message'=>'Subscription '.$subscription_id.' could not be contained after local synchronization failed: '.$containment->get_error_message(),'subscription_id'=>$subscription_id),sanitize_key($subscription_id)); return $local_sync; }
    $local=$this->mrm_get_sheet_music_subscription_by_stripe_id($subscription_id); $local_hold_status = sanitize_key($local['tax_attention_status'] ?? ''); if(!empty($local['collection_paused_for_tax']) && in_array($local_hold_status,array('global_compliance_hold','not_collecting_review_required'),true)){ $resumed=$this->mrm_resume_subscription_after_tax_location_fix($subscription); if(is_wp_error($resumed)){ $this->mrm_tax_create_alert('','subscription_global_tax_resume_failed','subscription',0,array('message'=>'Subscription '.$subscription_id.' could not resume after the global tax-compliance hold was cleared: '.$resumed->get_error_message(),'subscription_id'=>$subscription_id),sanitize_key($subscription_id)); return new WP_Error('subscription_global_tax_resume_failed',$resumed->get_error_message()); } $this->mrm_tax_resolve_alerts_by_reference('subscription_id',$subscription_id,array('subscription_global_tax_resume_failed')); }
    return true;
  }

  private function mrm_tax_enforce_global_subscription_holds() {
    $context=$this->mrm_tax_current_subscription_inventory_context(true);
    $inventory=$this->mrm_stripe_list_all_managed_sheet_music_subscriptions();
    if(is_wp_error($inventory)){ $message=$inventory->get_error_message(); update_option(self::OPT_TAX_SUBSCRIPTION_HOLD_ERROR,$message,false); $this->mrm_tax_create_alert('','subscription_inventory_reconciliation_failed','stripe',0,array('message'=>$message),sanitize_key(gmdate('Y-m-d-H'))); return $inventory; }
    if(is_wp_error($context)){ $configuration_message=$context->get_error_message(); $containment_failures=array(); foreach($inventory as $subscription){ $subscription_id=sanitize_text_field($subscription['id'] ?? ''); $this->mrm_tax_create_alert('','subscription_tax_configuration_invalid','subscription',0,array('message'=>$configuration_message,'subscription_id'=>$subscription_id),sanitize_key($subscription_id!==''?$subscription_id:gmdate('Y-m-d-H'))); $held=$this->mrm_pause_subscription_for_global_tax_hold($subscription,$context); if(is_wp_error($held)) $containment_failures[]=($subscription_id!==''?$subscription_id.': ':'').$held->get_error_message(); } $message=$configuration_message; if(!empty($containment_failures)) $message.=' | Hold failures: '.implode(' | ',array_values(array_unique($containment_failures))); update_option(self::OPT_TAX_SUBSCRIPTION_HOLD_ERROR,$message,false); return new WP_Error('subscription_tax_configuration_invalid',$message); }
    $blocking_failures=array(); $resume_failures=array();
    foreach($inventory as $subscription){ $subscription_id=sanitize_text_field($subscription['id'] ?? ''); $automatic_tax_enabled=!empty($subscription['automatic_tax']['enabled']); $uses_configured_price=false; foreach((array)($subscription['items']['data'] ?? array()) as $item){ $item_price_id=sanitize_text_field($item['price']['id'] ?? ''); if($item_price_id===$context['price_id']){ $uses_configured_price=true; break; } }
      if(!$automatic_tax_enabled || !$uses_configured_price){ $reasons=array(); if(!$automatic_tax_enabled) $reasons[]='Stripe automatic tax is disabled on the subscription.'; if(!$uses_configured_price) $reasons[]='The subscription does not use the configured Price ID '.$context['price_id'].'.'; $configuration_error=new WP_Error('subscription_tax_configuration_invalid',implode(' ',$reasons)); $this->mrm_tax_create_alert('','subscription_tax_configuration_invalid','subscription',0,array('message'=>$configuration_error->get_error_message(),'subscription_id'=>$subscription_id),sanitize_key($subscription_id)); $held=$this->mrm_pause_subscription_for_global_tax_hold($subscription,$configuration_error); $blocking_failures[]=$subscription_id.': '.$configuration_error->get_error_message().(is_wp_error($held)?' Hold failure: '.$held->get_error_message():''); continue; }
      $this->mrm_tax_resolve_alerts_by_reference('subscription_id',$subscription_id,array('subscription_tax_configuration_invalid'));
      $result=$this->mrm_tax_enforce_single_subscription_hold($subscription); if(!is_wp_error($result)) continue; if($result->get_error_code()==='subscription_global_tax_resume_failed'){ $resume_failures[]=$subscription_id.': '.$result->get_error_message(); continue; } $blocking_failures[]=($subscription_id!==''?$subscription_id.': ':'').$result->get_error_message(); }
    if(!empty($blocking_failures)){ $message=implode(' | ',array_values(array_unique($blocking_failures))); update_option(self::OPT_TAX_SUBSCRIPTION_HOLD_ERROR,$message,false); return new WP_Error('subscription_tax_hold_enforcement_failed',$message); }
    $snapshot=array_merge($context,array('synced_at'=>current_time('mysql'),'managed_subscription_count'=>count($inventory))); update_option(self::OPT_TAX_SUBSCRIPTION_INVENTORY_SNAPSHOT,$snapshot,false); $stored=get_option(self::OPT_TAX_SUBSCRIPTION_INVENTORY_SNAPSHOT,array()); if(!is_array($stored)) return new WP_Error('subscription_inventory_snapshot_save_failed','The Stripe subscription inventory snapshot could not be saved.');
    foreach(array('account_id','mode','credential_fingerprint','price_id','product_id','expected_tax_code','actual_tax_code','configuration_fingerprint','configuration_profile_version','api_version','synced_at') as $key){ if(!isset($stored[$key])||!isset($snapshot[$key])||!hash_equals((string)$snapshot[$key],(string)$stored[$key])) return new WP_Error('subscription_inventory_snapshot_verification_failed','The Stripe subscription inventory snapshot could not be verified after saving.'); }
    delete_option(self::OPT_TAX_LAST_SUCCESSFUL_SUBSCRIPTION_INVENTORY_SYNC); delete_option(self::OPT_TAX_SUBSCRIPTION_HOLD_ERROR); $this->mrm_tax_resolve_alert_type('subscription_inventory_reconciliation_failed'); if(!empty($resume_failures)) error_log('MRM subscription resume review required: '.implode(' | ',array_values(array_unique($resume_failures)))); return true;
  }

  public function cron_tax_enforce_subscription_holds() {
    $result = $this->mrm_tax_enforce_global_subscription_holds();
    if (is_wp_error($result)) error_log('MRM subscription inventory and tax-hold enforcement failed: ' . $result->get_error_message());
  }


  private function mrm_stripe_expandable_id($value) {
    if (is_array($value)) return sanitize_text_field($value['id'] ?? '');
    return sanitize_text_field((string)$value);
  }

  private function mrm_stripe_invoice_charge_id($invoice) {
  if (!is_array($invoice)) return new WP_Error('invoice_object_invalid','The Stripe Invoice object was invalid.');
  $charge_id=$this->mrm_stripe_expandable_id($invoice['charge'] ?? ''); if ($charge_id !== '') return $charge_id;
  $payment_intent_id=$this->mrm_stripe_expandable_id($invoice['payment_intent'] ?? '');
  if ($payment_intent_id === '' && !empty($invoice['payments']['data'])) { foreach ((array)$invoice['payments']['data'] as $invoice_payment) { $payment=is_array($invoice_payment['payment'] ?? null) ? $invoice_payment['payment'] : array(); $candidate=$this->mrm_stripe_expandable_id($payment['payment_intent'] ?? ''); if ($candidate !== '') { $payment_intent_id=$candidate; break; } } }
  if ($payment_intent_id === '') return new WP_Error('invoice_charge_reference_missing','The Stripe Invoice does not expose a Charge or PaymentIntent reference.');
  $payment_intent=$this->stripe_retrieve_payment_intent($payment_intent_id); if (is_wp_error($payment_intent)) return $payment_intent;
  $charge_id=$this->mrm_stripe_expandable_id($payment_intent['latest_charge'] ?? ''); if ($charge_id === '') return new WP_Error('invoice_latest_charge_missing','The Invoice PaymentIntent has no latest Charge.');
  return $charge_id;
}

  private function mrm_stripe_invoice_subscription_id($invoice) {
    if (!is_array($invoice)) return '';
    $legacy_id = $this->mrm_stripe_expandable_id($invoice['subscription'] ?? '');
    if ($legacy_id !== '') return $legacy_id;
    $parent = is_array($invoice['parent'] ?? null) ? $invoice['parent'] : array();
    if (sanitize_key($parent['type'] ?? '') !== 'subscription_details') return '';
    $details = is_array($parent['subscription_details'] ?? null) ? $parent['subscription_details'] : array();
    return $this->mrm_stripe_expandable_id($details['subscription'] ?? '');
  }

  private function mrm_stripe_invoice_line_price_id($line) {
    if (!is_array($line)) return '';
    $legacy_price = $this->mrm_stripe_expandable_id($line['price'] ?? '');
    if ($legacy_price !== '') return $legacy_price;
    $pricing = is_array($line['pricing'] ?? null) ? $line['pricing'] : array();
    if (sanitize_key($pricing['type'] ?? '') !== 'price_details') return '';
    $price_details = is_array($pricing['price_details'] ?? null) ? $pricing['price_details'] : array();
    return $this->mrm_stripe_expandable_id($price_details['price'] ?? '');
  }

  private function mrm_stripe_invoice_primary_price_id($invoice) {
    if (!is_array($invoice)) return '';
    foreach ((array)($invoice['lines']['data'] ?? array()) as $line) {
      $price_id = $this->mrm_stripe_invoice_line_price_id($line);
      if ($price_id !== '') return $price_id;
    }
    return '';
  }

  private function mrm_stripe_subscription_period_bounds($subscription) {
    if (!is_array($subscription)) return array('start'=>0,'end'=>0);
    $starts = array(); $ends = array();
    if (!empty($subscription['current_period_start'])) $starts[] = (int)$subscription['current_period_start'];
    if (!empty($subscription['current_period_end'])) $ends[] = (int)$subscription['current_period_end'];
    foreach ((array)($subscription['items']['data'] ?? array()) as $item) {
      if (!empty($item['current_period_start'])) $starts[] = (int)$item['current_period_start'];
      if (!empty($item['current_period_end'])) $ends[] = (int)$item['current_period_end'];
    }
    $starts = array_values(array_filter($starts, static function($value){ return $value > 0; }));
    $ends = array_values(array_filter($ends, static function($value){ return $value > 0; }));
    return array('start'=>!empty($starts)?min($starts):0,'end'=>!empty($ends)?max($ends):0);
  }

  private function mrm_handle_invoice_upcoming_webhook($invoice) {
    $subscription_id = $this->mrm_stripe_invoice_subscription_id($invoice); if ($subscription_id === '') return true;
    $subscription = $this->stripe_retrieve_subscription($subscription_id);
    if (is_wp_error($subscription)) { $this->mrm_tax_create_alert('', 'subscription_global_tax_pause_failed', 'subscription', 0, array('message'=>'The upcoming invoice for subscription '.$subscription_id.' could not be checked against the global tax-readiness gate: '.$subscription->get_error_message(),'subscription_id'=>$subscription_id,'invoice_id'=>sanitize_text_field($invoice['id'] ?? '')), sanitize_key($subscription_id)); return $subscription; }
    if (!$this->mrm_is_managed_sheet_music_subscription($subscription)) return true;
    return $this->mrm_tax_enforce_single_subscription_hold($subscription);
  }

  private function mrm_handle_invoice_finalization_failed_webhook($invoice) {
    $subscription_id = $this->mrm_stripe_invoice_subscription_id($invoice); if ($subscription_id === '') return true;
    $subscription = $this->stripe_retrieve_subscription($subscription_id); if (is_wp_error($subscription)) return $subscription;
    if (!$this->mrm_is_managed_sheet_music_subscription($subscription)) return true;
    if ($this->mrm_subscription_tax_location_problem($subscription, $invoice) !== '') return $this->mrm_pause_subscription_for_tax_location($subscription, $invoice);
    return true;
  }

  private function mrm_stripe_list_managed_subscriptions_for_customer($customer_id) {
    $customer_id=sanitize_text_field($customer_id); if($customer_id==='') return new WP_Error('customer_subscription_list_id_missing','The Stripe customer ID is missing.'); $managed=array(); $starting_after=''; $pagination_guard=0;
    do { $pagination_guard++; if($pagination_guard>1000) return new WP_Error('customer_subscription_pagination_limit','Customer subscription pagination exceeded the safety limit.'); $params=array('customer'=>$customer_id,'status'=>'all','limit'=>100); if($starting_after!=='') $params['starting_after']=$starting_after; $response=$this->stripe_api_request('GET','/v1/subscriptions',$params); if(is_wp_error($response)) return new WP_Error('customer_subscription_list_failed','Subscriptions for customer '.$customer_id.' could not be retrieved: '.$response->get_error_message()); if(!array_key_exists('data',$response)||!is_array($response['data'])) return new WP_Error('customer_subscription_list_invalid','Stripe returned an invalid customer subscription response.'); $page=$response['data']; foreach($page as $subscription){ if(!$this->mrm_is_managed_sheet_music_subscription($subscription)) continue; $subscription_id=sanitize_text_field($subscription['id'] ?? ''); if($subscription_id==='') return new WP_Error('customer_subscription_id_missing','Stripe returned a managed subscription without an ID.'); $managed[$subscription_id]=$subscription; } if(!empty($response['has_more'])){ if(empty($page)) return new WP_Error('customer_subscription_pagination_empty','Stripe reported more customer subscriptions but returned an empty page.'); $last=end($page); $next_starting_after=sanitize_text_field($last['id'] ?? ''); if($next_starting_after===''||$next_starting_after===$starting_after) return new WP_Error('customer_subscription_pagination_stalled','Customer subscription pagination could not advance.'); $starting_after=$next_starting_after; } else $starting_after=''; } while($starting_after!==''); return array_values($managed);
  }

  private function mrm_handle_customer_updated_webhook($customer) {
    $customer_id=sanitize_text_field($customer['id'] ?? ''); if($customer_id==='') return new WP_Error('customer_updated_id_missing','The customer.updated event has no customer ID.'); $expanded_customer=$this->stripe_retrieve_customer_with_tax($customer_id);
    if(is_wp_error($expanded_customer)){ $this->mrm_tax_create_alert('','customer_subscription_reconciliation_failed','customer',0,array('message'=>'Customer '.$customer_id.' could not be retrieved after customer.updated: '.$expanded_customer->get_error_message(),'customer_id'=>$customer_id),sanitize_key($customer_id)); return $expanded_customer; }
    $automatic_tax_status=sanitize_key($expanded_customer['tax']['automatic_tax'] ?? ''); if(!in_array($automatic_tax_status,array('supported','not_collecting'),true)) return true; $subscriptions=$this->mrm_stripe_list_managed_subscriptions_for_customer($customer_id);
    if(is_wp_error($subscriptions)){ $this->mrm_tax_create_alert('','customer_subscription_reconciliation_failed','customer',0,array('message'=>$subscriptions->get_error_message(),'customer_id'=>$customer_id),sanitize_key($customer_id)); return $subscriptions; }
    $errors=array(); foreach($subscriptions as $subscription){ $subscription_id=sanitize_text_field($subscription['id'] ?? ''); $local=$this->mrm_get_sheet_music_subscription_by_stripe_id($subscription_id); $stripe_pause_behavior=sanitize_key($subscription['pause_collection']['behavior'] ?? ''); $stripe_attention_status=sanitize_key($subscription['metadata']['mrm_tax_attention_status'] ?? ''); $has_hold=(!empty($local['collection_paused_for_tax'])||$stripe_pause_behavior==='keep_as_draft'||in_array($stripe_attention_status,array('global_compliance_hold','requires_location_inputs','not_collecting_review_required','local_sync_failed'),true)); if(!$has_hold) continue; $result=$this->mrm_resume_subscription_after_tax_location_fix($subscription); if(is_wp_error($result)) $errors[]=$subscription_id.': '.$result->get_error_message(); }
    if(!empty($errors)){ $message=implode(' | ',array_values(array_unique($errors))); $this->mrm_tax_create_alert('','customer_subscription_reconciliation_failed','customer',0,array('message'=>$message,'customer_id'=>$customer_id),sanitize_key($customer_id)); return new WP_Error('customer_subscription_reconciliation_failed',$message); }
    $this->mrm_tax_resolve_alerts_by_reference('customer_id',$customer_id,array('customer_subscription_reconciliation_failed')); return true;
  }

  private function mrm_handle_customer_subscription_created_webhook($subscription) {
    if (!$this->mrm_is_managed_sheet_music_subscription($subscription)) return true;
    $email = sanitize_email($subscription['metadata']['mrm_customer_email'] ?? ''); $subscription_id = sanitize_text_field($subscription['id'] ?? '');
    $this->stripe_debug_log('customer.subscription.created handler entered', array('subscription_id'=>$subscription_id,'status'=>sanitize_key($subscription['status'] ?? ''),'email'=>$email));
    $local_sync=$this->mrm_sync_local_sheet_music_subscription_from_stripe($subscription,$email);
    if(is_wp_error($local_sync)){ $containment=$this->mrm_contain_subscription_after_local_sync_failure($subscription,$local_sync->get_error_message(),false); if(is_wp_error($containment)) $this->mrm_tax_create_alert('','subscription_global_tax_pause_failed','subscription',0,array('message'=>'New subscription '.$subscription_id.' failed local synchronization and could not be paused: '.$containment->get_error_message(),'subscription_id'=>$subscription_id),sanitize_key($subscription_id)); return $local_sync; }
    $hold_result=$this->mrm_tax_enforce_single_subscription_hold($subscription); if(is_wp_error($hold_result)) return $hold_result;
    $local=$this->mrm_get_sheet_music_subscription_by_stripe_id($subscription_id); if(is_array($local)) $this->stripe_debug_log('customer.subscription.created webhook synchronization completed', array('subscription_id'=>$subscription_id,'email'=>sanitize_email($local['email_plain'] ?? ''),'status'=>sanitize_key($local['stripe_status'] ?? '')));
    return true;
  }

  private function mrm_handle_customer_subscription_updated_webhook($subscription) {
    if (!$this->mrm_is_managed_sheet_music_subscription($subscription)) return true;
    $email=sanitize_email($subscription['metadata']['mrm_customer_email'] ?? ''); $subscription_id=sanitize_text_field($subscription['id'] ?? '');
    $local_sync=$this->mrm_sync_local_sheet_music_subscription_from_stripe($subscription,$email);
    if(is_wp_error($local_sync)){ $containment=$this->mrm_contain_subscription_after_local_sync_failure($subscription,$local_sync->get_error_message(),false); if(is_wp_error($containment)) $this->mrm_tax_create_alert('','subscription_global_tax_pause_failed','subscription',0,array('message'=>'Updated subscription '.$subscription_id.' failed local synchronization and could not be paused: '.$containment->get_error_message(),'subscription_id'=>$subscription_id),sanitize_key($subscription_id)); return $local_sync; }
    $tax_problem=$this->mrm_subscription_tax_location_problem($subscription); if($tax_problem !== '') return $this->mrm_pause_subscription_for_tax_location($subscription);
    $global_hold_result=$this->mrm_tax_enforce_single_subscription_hold($subscription); if(is_wp_error($global_hold_result)) return $global_hold_result;
    $resume_result=$this->mrm_resume_subscription_after_tax_location_fix($subscription); if(is_wp_error($resume_result)) return $resume_result;
    return true;
  }

  private function mrm_handle_customer_subscription_deleted_webhook($subscription) {
    $email = sanitize_email((string)($subscription['metadata']['mrm_customer_email'] ?? ''));
    $subscription_id = (string)($subscription['id'] ?? '');

    $this->stripe_debug_log('customer.subscription.deleted handler entered', array(
      'subscription_id' => $subscription_id,
      'status' => (string)($subscription['status'] ?? ''),
      'email' => $email,
    ));
    $this->mrm_subscription_debug_log('customer.subscription.deleted webhook entered', array(
      'subscription_id' => $subscription_id,
      'status' => (string)($subscription['status'] ?? ''),
      'email' => $email,
    ));

    $this->mrm_sync_local_sheet_music_subscription_from_stripe($subscription, $email);

    $order = $this->get_order_by_meta_value('mrm_sheet_music_subscription_id', $subscription_id);
    if (is_array($order) && !empty($order)) {
      $order_id = (int)($order['id'] ?? 0);
      if ($order_id > 0) {
        $this->mrm_set_order_meta_flag($order_id, 'mrm_sheet_music_subscription_status', 'retry_reopened_after_unhealthy_subscription');
        $this->mrm_set_order_meta_flag($order_id, 'mrm_sheet_music_subscription_error', 'Stripe reported the subscription as deleted/canceled; reopening activation.');
        $this->mrm_set_order_meta_flag($order_id, 'mrm_sheet_music_subscription_id', '');
        $this->mrm_set_order_meta_flag($order_id, 'mrm_sheet_music_subscription_created_at', '');
        $this->mrm_subscription_debug_log('deleted webhook reopened order for retry', array(
          'order_id' => $order_id,
          'subscription_id' => $subscription_id,
        ));
      }
    }

    $local = $this->mrm_get_sheet_music_subscription_by_stripe_id($subscription_id);
    if (!empty($local['email_plain'])) {
      $sent = $this->mrm_send_sheet_music_subscription_cancelled_email($local, $subscription);

      $this->stripe_debug_log('subscription cancellation email result', array(
        'subscription_id' => $subscription_id,
        'email' => (string)($local['email_plain'] ?? ''),
        'sent' => ($sent ? 'yes' : 'no'),
      ));
    }
  }

  private function mrm_tax_schedule_subscription_invoice_lifecycle_retry($invoice_id, $attempt, $message) {
    $invoice_id=sanitize_text_field($invoice_id); $attempt=absint($attempt); $message=sanitize_textarea_field($message);
    if($invoice_id==='' || $attempt>6) return new WP_Error('subscription_invoice_lifecycle_retry_invalid','The subscription Invoice lifecycle retry parameters were invalid.');
    return $this->mrm_tax_schedule_checked_retry('mrm_pay_hub_retry_subscription_invoice_lifecycle',array($invoice_id,$attempt),'','subscription_invoice_lifecycle_reconciliation_failed','invoice',array('invoice_id'=>$invoice_id,'attempt'=>$attempt),sanitize_key($invoice_id),$message);
  }

  private function mrm_tax_subscription_invoice_lifecycle_failure($invoice_id, $attempt, $message, $details = array()) {
    $invoice_id=sanitize_text_field($invoice_id); $attempt=absint($attempt); $message=sanitize_textarea_field($message); $details=is_array($details)?$details:array();
    $details['message']=$message; $details['invoice_id']=$invoice_id; $details['attempt']=$attempt;
    $alert_result=$this->mrm_tax_create_alert('','subscription_invoice_lifecycle_reconciliation_failed','invoice',0,$details,sanitize_key($invoice_id!=='' ? $invoice_id : hash('sha256',$message)));
    if(is_wp_error($alert_result)) return $alert_result;
    if($invoice_id!=='' && $attempt<6){ $schedule_result=$this->mrm_tax_schedule_subscription_invoice_lifecycle_retry($invoice_id,$attempt+1,$message); if(is_wp_error($schedule_result)) return $schedule_result; }
    return new WP_Error('subscription_invoice_lifecycle_reconciliation_failed',$message);
  }

  public function mrm_tax_retry_subscription_invoice_lifecycle($invoice_id, $attempt = 1) {
    $invoice_id=sanitize_text_field($invoice_id); $attempt=absint($attempt); if($invoice_id==='') return;
    $invoice=$this->stripe_api_request('GET','/v1/invoices/'.rawurlencode($invoice_id));
    if(is_wp_error($invoice)){ $this->mrm_tax_subscription_invoice_lifecycle_failure($invoice_id,$attempt,'The subscription Invoice could not be retrieved during lifecycle reconciliation: '.$invoice->get_error_message()); return; }
    $result=$this->mrm_tax_sync_managed_subscription_invoice_lifecycle($invoice,$attempt);
    if(is_wp_error($result)) $this->stripe_debug_log('Subscription Invoice lifecycle retry failed.',array('invoice_id'=>$invoice_id,'attempt'=>$attempt,'message'=>$result->get_error_message()));
  }

  private function mrm_tax_sync_managed_subscription_invoice_lifecycle($invoice, $attempt = 0, $subscription = null) {
    if (!is_array($invoice)) return new WP_Error('subscription_invoice_object_invalid','The Stripe Invoice object was invalid.');
    $attempt=absint($attempt); $invoice_id=sanitize_text_field($invoice['id'] ?? '');
    if ($invoice_id==='') return new WP_Error('subscription_invoice_id_missing','The Stripe Invoice ID is missing.');
    $subscription_id=$this->mrm_stripe_invoice_subscription_id($invoice);
    if ($subscription_id==='') return true;
    if (!is_array($subscription)) { $subscription=$this->stripe_retrieve_subscription($subscription_id); if (is_wp_error($subscription)) return $this->mrm_tax_subscription_invoice_lifecycle_failure($invoice_id,$attempt,'Subscription '.$subscription_id.' could not be retrieved for Invoice '.$invoice_id.': '.$subscription->get_error_message(),array('subscription_id'=>$subscription_id)); }
    if (!$this->mrm_is_managed_sheet_music_subscription($subscription)) return true;
    $configured_price_id=sanitize_text_field($this->subscription_price_id()); $invoice_price_id=sanitize_text_field($this->mrm_stripe_invoice_primary_price_id($invoice));
    if($configured_price_id==='' || $invoice_price_id==='' || $invoice_price_id!==$configured_price_id) return $this->mrm_tax_subscription_invoice_lifecycle_failure($invoice_id,$attempt,'Subscription Invoice '.$invoice_id.' does not use the configured Stripe Price.',array('subscription_id'=>$subscription_id,'configured_price_id'=>$configured_price_id,'invoice_price_id'=>$invoice_price_id));
    $configuration=$this->mrm_verify_sheet_music_subscription_tax_configuration($configured_price_id);
    if(is_wp_error($configuration)) return $this->mrm_tax_subscription_invoice_lifecycle_failure($invoice_id,$attempt,'The Stripe subscription Price or Product tax configuration is invalid: '.$configuration->get_error_message(),array('subscription_id'=>$subscription_id,'configured_price_id'=>$configured_price_id));
    if(empty($subscription['automatic_tax']['enabled'])) return $this->mrm_tax_subscription_invoice_lifecycle_failure($invoice_id,$attempt,'Stripe automatic tax is disabled on subscription '.$subscription_id.'.',array('subscription_id'=>$subscription_id));
    $tax_problem=$this->mrm_subscription_tax_location_problem($subscription,$invoice);
    if($tax_problem!==''){ $pause_result=$this->mrm_pause_subscription_for_tax_location($subscription,$invoice); if(is_wp_error($pause_result)) return $this->mrm_tax_subscription_invoice_lifecycle_failure($invoice_id,$attempt,'The subscription tax-location hold failed: '.$pause_result->get_error_message(),array('subscription_id'=>$subscription_id,'tax_problem'=>$tax_problem)); }
    $ledger_result=$this->mrm_tax_record_subscription_invoice($invoice);
    if(is_wp_error($ledger_result)) return $this->mrm_tax_subscription_invoice_lifecycle_failure($invoice_id,$attempt,'The subscription Invoice tax ledger could not be synchronized: '.$ledger_result->get_error_message(),array('subscription_id'=>$subscription_id,'ledger_error_code'=>$ledger_result->get_error_code()));
    $adjustment_result=$this->mrm_tax_sync_subscription_invoice_refunds($invoice_id,$attempt); if(is_wp_error($adjustment_result)) return $adjustment_result;
    $resolved=$this->mrm_tax_resolve_alerts_by_reference('invoice_id',$invoice_id,array('subscription_invoice_tax_failed','subscription_invoice_ledger_failed','subscription_invoice_lifecycle_reconciliation_failed')); if(is_wp_error($resolved)) return $resolved;
    return true;
  }

  private function mrm_handle_invoice_finalized_webhook($invoice) { return $this->mrm_tax_sync_managed_subscription_invoice_lifecycle($invoice,0); }
  private function mrm_handle_invoice_voided_webhook($invoice) { return $this->mrm_tax_sync_managed_subscription_invoice_lifecycle($invoice,0); }
  private function mrm_handle_invoice_marked_uncollectible_webhook($invoice) { return $this->mrm_tax_sync_managed_subscription_invoice_lifecycle($invoice,0); }

  private function mrm_handle_invoice_paid_webhook($invoice) {
    if(!is_array($invoice)) return new WP_Error('invoice_paid_object_invalid','The invoice.paid event did not contain a valid invoice.');
    $invoice_id=sanitize_text_field($invoice['id'] ?? ''); $subscription_id=$this->mrm_stripe_invoice_subscription_id($invoice); $amount_paid=(int)($invoice['amount_paid'] ?? 0);
    $this->stripe_debug_log('invoice.paid handler entered',array('invoice_id'=>$invoice_id,'subscription_id'=>$subscription_id,'amount_paid'=>$amount_paid));
    if($subscription_id==='' || $amount_paid<=0) return true;
    $subscription=$this->stripe_retrieve_subscription($subscription_id);
    if(is_wp_error($subscription)){ $error=new WP_Error('invoice_paid_subscription_retrieve_failed','Subscription '.$subscription_id.' could not be retrieved for paid invoice '.$invoice_id.': '.$subscription->get_error_message()); $this->mrm_tax_create_alert('','subscription_invoice_processing_failed','invoice',0,array('message'=>$error->get_error_message(),'invoice_id'=>$invoice_id,'subscription_id'=>$subscription_id),sanitize_key($invoice_id)); return $error; }
    if(!$this->mrm_is_managed_sheet_music_subscription($subscription)) return true;
    $configured_price_id=sanitize_text_field($this->subscription_price_id()); $invoice_price_id=sanitize_text_field($this->mrm_stripe_invoice_primary_price_id($invoice));
    if($configured_price_id==='' || $invoice_price_id==='' || $invoice_price_id!==$configured_price_id){ $error=new WP_Error('invoice_paid_price_mismatch','Paid subscription invoice '.$invoice_id.' uses Price ID '.($invoice_price_id!==''?$invoice_price_id:'missing').', but the site requires '.($configured_price_id!==''?$configured_price_id:'a configured Price ID').'.'); $this->mrm_tax_create_alert('','subscription_invoice_processing_failed','invoice',0,array('message'=>$error->get_error_message(),'invoice_id'=>$invoice_id,'subscription_id'=>$subscription_id),sanitize_key($invoice_id)); return $error; }
    $configuration=$this->mrm_verify_sheet_music_subscription_tax_configuration($configured_price_id); if(is_wp_error($configuration)){ $error=new WP_Error('invoice_paid_tax_configuration_invalid',$configuration->get_error_message()); $this->mrm_tax_create_alert('','subscription_tax_configuration_invalid','invoice',0,array('message'=>$error->get_error_message(),'invoice_id'=>$invoice_id,'subscription_id'=>$subscription_id),sanitize_key($invoice_id)); return $error; }
    if(empty($subscription['automatic_tax']['enabled'])){ $error=new WP_Error('invoice_paid_automatic_tax_disabled','Stripe automatic tax is disabled on subscription '.$subscription_id.'.'); $this->mrm_tax_create_alert('','subscription_tax_configuration_invalid','invoice',0,array('message'=>$error->get_error_message(),'invoice_id'=>$invoice_id,'subscription_id'=>$subscription_id),sanitize_key($invoice_id)); return $error; }
    $lifecycle_result=$this->mrm_tax_sync_managed_subscription_invoice_lifecycle($invoice,0,$subscription);
    if (is_wp_error($lifecycle_result)) return $lifecycle_result;
    $local_sync=$this->mrm_sync_local_sheet_music_subscription_from_stripe($subscription,sanitize_email($subscription['metadata']['mrm_customer_email'] ?? '')); if(is_wp_error($local_sync)) return $local_sync;
    $local=$this->mrm_get_sheet_music_subscription_by_stripe_id($subscription_id); if(!is_array($local)){ $error=new WP_Error('invoice_paid_local_subscription_missing','Paid subscription invoice '.$invoice_id.' was recorded, but subscription '.$subscription_id.' is missing from the local subscription registry.'); $this->mrm_tax_create_alert('','subscription_invoice_processing_failed','invoice',0,array('message'=>$error->get_error_message(),'invoice_id'=>$invoice_id,'subscription_id'=>$subscription_id),sanitize_key($invoice_id)); return $error; }
    if(!empty($local['email_plain'])){ $invoice_created_ts=!empty($invoice['created'])?(int)$invoice['created']:time(); $this->mrm_grant_all_sheet_music_ledger((string)$local['email_plain'],$invoice_created_ts,'stripe_subscription_invoice',$invoice_id); $this->mrm_create_composer_payout_for_subscription_invoice($invoice,$local); $sent=$this->mrm_send_sheet_music_subscription_charge_email($local,$invoice); $this->stripe_debug_log('subscription recurring charge email result',array('invoice_id'=>$invoice_id,'subscription_id'=>$subscription_id,'email'=>(string)($local['email_plain'] ?? ''),'sent'=>$sent?'yes':'no')); }
    $this->mrm_tax_resolve_alerts_by_reference('invoice_id',$invoice_id,array('subscription_invoice_processing_failed','subscription_invoice_ledger_failed','subscription_tax_configuration_invalid'));
    return true;
  }

  private function mrm_handle_invoice_payment_failed_webhook($invoice) {
    $subscription_id = $this->mrm_stripe_invoice_subscription_id($invoice);
    if ($subscription_id === '') return;

    $sub = $this->stripe_retrieve_subscription($subscription_id);
    if (is_wp_error($sub)) return;

    $email = sanitize_email((string)($sub['metadata']['mrm_customer_email'] ?? ''));
    $this->mrm_sync_local_sheet_music_subscription_from_stripe($sub, $email);
  }

  private function mrm_tax_find_association($payment_intent_id) {
    return new WP_Error('tax_association_unsupported', 'Stripe Tax Associations are not used by the stable Tax Transaction flow.');
  }

  private function mrm_tax_retrieve_transaction($transaction_id) {
    $transaction_id = sanitize_text_field($transaction_id);
    if ($transaction_id === '') return new WP_Error('missing_tax_transaction', 'Missing Tax Transaction ID.');
    return $this->stripe_api_request('GET', '/v1/tax/transactions/' . rawurlencode($transaction_id), array(), $this->mrm_stripe_tax_headers());
  }

  private function mrm_tax_get_transaction_line_items($transaction_id) {
    $transaction_id = sanitize_text_field($transaction_id);
    if ($transaction_id === '') return new WP_Error('missing_tax_transaction', 'Missing Tax Transaction ID.');
    return $this->stripe_api_request('GET', '/v1/tax/transactions/' . rawurlencode($transaction_id) . '/line_items', array('limit'=>100), $this->mrm_stripe_tax_headers());
  }


  private function mrm_tax_existing_transaction_id_for_payment_intent($payment_intent_id, $metadata = array()) {
    global $wpdb;
    $payment_intent_id = sanitize_text_field($payment_intent_id);
    $metadata = is_array($metadata) ? $metadata : array();
    $metadata_transaction_id = sanitize_text_field($metadata['mrm_tax_transaction_id'] ?? '');
    if ($metadata_transaction_id !== '') return $metadata_transaction_id;
    if ($payment_intent_id === '') return '';
    $wpdb->last_error = '';
    $transaction_id = $wpdb->get_var($wpdb->prepare("SELECT tax_transaction_id FROM {$this->table_tax_sales_ledger()} WHERE payment_intent_id = %s AND COALESCE(tax_transaction_id, '') <> '' ORDER BY id ASC LIMIT 1", $payment_intent_id));
    if ($wpdb->last_error !== '') return new WP_Error('tax_transaction_lookup_failed', $wpdb->last_error);
    return sanitize_text_field($transaction_id);
  }

  private function mrm_tax_payment_intent_reversal_ids($payment_intent_id) {
    global $wpdb;
    $payment_intent_id = sanitize_text_field($payment_intent_id);
    if ($payment_intent_id === '') return array();
    $wpdb->last_error = '';
    $values = $wpdb->get_col($wpdb->prepare("SELECT tax_reversals_json FROM {$this->table_tax_sales_ledger()} WHERE payment_intent_id = %s", $payment_intent_id));
    if ($wpdb->last_error !== '') return new WP_Error('tax_reversal_lookup_failed', $wpdb->last_error);
    $ids = array();
    foreach ((array)$values as $value) { $decoded = json_decode((string)$value, true); if (!is_array($decoded)) continue; foreach ($decoded as $transaction_id) { $transaction_id = sanitize_text_field($transaction_id); if ($transaction_id !== '') $ids[$transaction_id] = true; } }
    return array_keys($ids);
  }

  private function mrm_tax_add_reversal_to_payment_intent_ledger($payment_intent_id, $transaction_id) {
    global $wpdb;
    $payment_intent_id = sanitize_text_field($payment_intent_id); $transaction_id = sanitize_text_field($transaction_id);
    if ($payment_intent_id === '' || $transaction_id === '') return new WP_Error('tax_reversal_reference_missing', 'The tax-reversal ledger references were incomplete.');
    $wpdb->last_error = '';
    $rows = $wpdb->get_results($wpdb->prepare("SELECT id, tax_reversals_json FROM {$this->table_tax_sales_ledger()} WHERE payment_intent_id = %s", $payment_intent_id), ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('tax_reversal_rows_lookup_failed', $wpdb->last_error);
    if (empty($rows)) return new WP_Error('tax_reversal_sale_ledger_missing', 'The original payment tax ledger must exist before a reversal can be recorded.');
    foreach ($rows as $row) { $ids = json_decode((string)($row['tax_reversals_json'] ?? '[]'), true); if (!is_array($ids)) $ids = array(); $ids[] = $transaction_id; $ids = array_values(array_unique(array_filter(array_map('sanitize_text_field', $ids)))); $wpdb->last_error = ''; $updated = $wpdb->update($this->table_tax_sales_ledger(), array('tax_reversals_json'=>wp_json_encode($ids),'updated_at'=>current_time('mysql')), array('id'=>absint($row['id']))); if ($updated === false || $wpdb->last_error !== '') return new WP_Error('tax_reversal_ledger_update_failed', $wpdb->last_error ?: 'The tax reversal could not be stored.'); }
    return true;
  }

  private function mrm_tax_commit_payment_intent_transaction($payment_intent) {
    if (!is_array($payment_intent)) return new WP_Error('tax_payment_intent_invalid', 'The PaymentIntent was invalid.');
    $payment_intent_id = sanitize_text_field($payment_intent['id'] ?? '');
    if ($payment_intent_id === '') return new WP_Error('tax_payment_intent_id_missing', 'The PaymentIntent ID is missing.');
    if (sanitize_key($payment_intent['status'] ?? '') !== 'succeeded') return new WP_Error('tax_payment_not_succeeded', 'The tax transaction cannot be committed until the PaymentIntent succeeds.');
    $metadata = is_array($payment_intent['metadata'] ?? null) ? $payment_intent['metadata'] : array();
    $calculation_id = sanitize_text_field($metadata['mrm_tax_calculation_id'] ?? '');
    if ($calculation_id === '') return new WP_Error('tax_calculation_id_missing', 'The succeeded PaymentIntent does not contain its Stripe Tax Calculation ID.');
    $transaction_id = $this->mrm_tax_existing_transaction_id_for_payment_intent($payment_intent_id, $metadata); if (is_wp_error($transaction_id)) return $transaction_id;
    if ($transaction_id === '') {
      $posted_at = time(); $charge_id = $this->mrm_stripe_expandable_id($payment_intent['latest_charge'] ?? '');
