    $metadata = is_array($payment_intent['metadata'] ?? null) ? $payment_intent['metadata'] : array();
    $metadata_state = $this->mrm_normalize_state_code($metadata['mrm_tax_state'] ?? ($metadata['mrm_customer_state'] ?? ''));
    $metadata_country = strtoupper(sanitize_text_field((string)($metadata['mrm_tax_country'] ?? ($metadata['mrm_customer_country'] ?? 'US'))));
    if ($metadata_country === '') $metadata_country = 'US';
    $customer_state_from_meta = $metadata_state;
    $committed = $this->mrm_tax_commit_payment_intent_transaction($payment_intent);
    if (is_wp_error($committed)) return $this->mrm_tax_retry_or_alert_payment_intent($pi_id, $attempt, $customer_state_from_meta, 'The stable Stripe Tax Transaction could not be committed: ' . $committed->get_error_message());
    $payment_intent = is_array($committed['payment_intent'] ?? null) ? $committed['payment_intent'] : $payment_intent;
    $metadata = is_array($payment_intent['metadata'] ?? null) ? $payment_intent['metadata'] : $metadata;
    $parsed = is_array($committed['parsed'] ?? null) ? $committed['parsed'] : array();
    $transaction = is_array($committed['transaction'] ?? null) ? $committed['transaction'] : array();
    $original_lines = is_array($committed['line_items'] ?? null) ? $committed['line_items'] : array();
    if (empty($parsed['original_transaction_id'])) return $this->mrm_tax_retry_or_alert_payment_intent($pi_id, $attempt, $customer_state_from_meta, 'No committed original Stripe Tax Transaction was found.');
    if (sanitize_key($transaction['type'] ?? '') !== 'transaction') return $this->mrm_tax_retry_or_alert_payment_intent($pi_id, $attempt, $customer_state_from_meta, 'The committed original Stripe Tax object is not a sale transaction.');
    $transaction_posted_at = absint($transaction['posted_at'] ?? 0); if ($transaction_posted_at <= 0) return $this->mrm_tax_retry_or_alert_payment_intent($pi_id, $attempt, $customer_state_from_meta, 'The committed Stripe Tax Transaction has no valid posted_at timestamp.');
    $transaction_occurred_at = $this->mrm_tax_utc_mysql_from_timestamp($transaction_posted_at); $metadata['mrm_tax_transaction_posted_at']=$transaction_posted_at; $metadata['mrm_payment_intent_created_at']=absint($payment_intent['created'] ?? 0);
    $reversal_transaction_ids = array_values(array_unique(array_filter(array_map('sanitize_text_field', (array)($parsed['reversal_transaction_ids'] ?? array())))));
    $refunds_by_original_line = $this->mrm_tax_net_reversals_by_original_line($parsed['original_transaction_id'], $original_lines, $reversal_transaction_ids); if (is_wp_error($refunds_by_original_line)) return $this->mrm_tax_retry_or_alert_payment_intent($pi_id, $attempt, $customer_state_from_meta, 'The Stripe Tax refund-reversal chain could not be reconciled: ' . $refunds_by_original_line->get_error_message());
    $transaction_address = is_array($transaction['customer_details']['address'] ?? null) ? $transaction['customer_details']['address'] : array();
    $transaction_state = $this->mrm_normalize_state_code($transaction_address['state'] ?? '');
    $fallback_state = $transaction_state !== '' ? $transaction_state : $metadata_state;
    $transaction_country = strtoupper(sanitize_text_field((string)($transaction_address['country'] ?? '')));
    $fallback_country = $transaction_country !== '' ? $transaction_country : $metadata_country;
    $calculation_lines = $this->mrm_tax_decode_line_items_metadata($metadata['mrm_tax_lines_json'] ?? '');
    $calculation_by_reference=array(); foreach($calculation_lines as $calculation_line){ if(!is_array($calculation_line)) continue; $calculation_reference=sanitize_key($calculation_line['reference'] ?? ''); if($calculation_reference==='') continue; if(isset($calculation_by_reference[$calculation_reference])) return $this->mrm_tax_retry_or_alert_payment_intent($pi_id,$attempt,$fallback_state,'The saved Stripe Tax calculation contains duplicate line references.'); $calculation_by_reference[$calculation_reference]=$calculation_line; }
    $ledger_write_errors=array(); $states_written=array(); $transaction_states_counted=array(); $index=0;
    foreach ((array)($original_lines['data'] ?? array()) as $line) {
      $line_id=sanitize_text_field($line['id'] ?? ''); $reference=sanitize_key($line['reference'] ?? 'item_'.$index); $calculation_line=$calculation_by_reference[$reference] ?? array(); if(empty($calculation_line)){ $ledger_write_errors[]='No saved Stripe Tax calculation line matches reference '.$reference.'.'; $index++; continue; }
      $line_amount=abs((int)($line['amount'] ?? 0)); $line_tax=abs((int)($line['amount_tax'] ?? 0));
      if(absint($calculation_line['amount_cents'] ?? -1) !== $line_amount || absint($calculation_line['tax_cents'] ?? -1) !== $line_tax){ $ledger_write_errors[]='The saved calculation amounts do not match committed Tax Transaction line '.$reference.'.'; $index++; continue; }
      $line_state=$this->mrm_normalize_state_code($calculation_line['jurisdiction_state'] ?? ''); $line_country=$fallback_country; $line_sourcing=sanitize_key($calculation_line['sourcing'] ?? ''); $is_performance_line=$line_sourcing==='performance' || strpos($reference,'private_lesson_in_person')!==false;
      if($is_performance_line && $line_state===''){ $ledger_write_errors[]='The in-person lesson line has no Stripe performance-jurisdiction state.'; $index++; continue; }
      if($line_state==='') $line_state=$fallback_state; if($line_state===''){ $ledger_write_errors[]='Tax Transaction line '.$reference.' has no usable state jurisdiction.'; $index++; continue; }
      $taxability_reason=sanitize_key($calculation_line['taxability_reason'] ?? $metadata['mrm_taxability_reason'] ?? '');
      $taxable_sales=min($line_amount,max(0,(int)($calculation_line['taxable_sales_cents'] ?? (in_array($taxability_reason,array('not_subject_to_tax','product_exempt','customer_exempt'),true)?0:$line_amount))));
      $refund=$refunds_by_original_line[$line_id] ?? array('sales'=>0,'tax'=>0,'transactions'=>array()); $refund['sales']=min($line_amount,max(0,(int)$refund['sales'])); $refund['tax']=min($line_tax,max(0,(int)$refund['tax']));
      $transaction_count=0; if(empty($transaction_states_counted[$line_state])){ $transaction_count=1; $transaction_states_counted[$line_state]=true; }
      $row_metadata=$metadata; $row_metadata['mrm_tax_line_reference']=$reference; $row_metadata['mrm_tax_line_jurisdiction_state']=$line_state; $row_metadata['mrm_tax_line_jurisdiction_country']=$line_country; $row_metadata['mrm_tax_line_sourcing']=$line_sourcing;
      $ledger_write_result=$this->mrm_tax_upsert_ledger_row(array('external_id'=>'payment_intent:'.$pi_id.':'.($line_id!==''?$line_id:$reference),'source_type'=>'payment_intent','payment_intent_id'=>$pi_id,'customer_state'=>$line_state,'customer_country'=>$line_country,'product_type'=>$this->mrm_tax_product_from_reference($reference,$metadata),'threshold_category'=>$this->mrm_tax_category_from_reference($reference,$metadata),'gross_sales_cents'=>$line_amount,'retail_sales_cents'=>$line_amount,'taxable_sales_cents'=>$taxable_sales,'tax_cents'=>$line_tax,'refunded_sales_cents'=>$refund['sales'],'refunded_tax_cents'=>$refund['tax'],'transaction_count'=>$transaction_count,'currency'=>$payment_intent['currency'] ?? 'usd','tax_code'=>sanitize_text_field($line['tax_code'] ?? ''),'taxability_reason'=>$taxability_reason,'tax_calculation_id'=>$parsed['calculation_id'],'tax_association_id'=>$parsed['association_id'],'tax_transaction_id'=>$parsed['original_transaction_id'],'stripe_tax_line_item_id'=>$line_id,'tax_reversals'=>array_values(array_unique($refund['transactions'])),'calculation_line_items'=>$calculation_lines,'tax_transaction_status'=>'committed','occurred_at'=>$transaction_occurred_at,'metadata'=>$row_metadata));
      if(is_wp_error($ledger_write_result)) $ledger_write_errors[]=$ledger_write_result->get_error_message(); else $states_written[$line_state]=true; $index++;
    }
    if(!empty($ledger_write_errors)) return $this->mrm_tax_retry_or_alert_payment_intent($pi_id,$attempt,$fallback_state,'One or more tax-ledger rows failed: '.implode(' | ',array_values(array_unique($ledger_write_errors))));
    if(!empty($states_written)){ $threshold_result=$this->mrm_tax_recompute_all_thresholds(); if(is_wp_error($threshold_result)){ $alert_state=sanitize_key(array_key_first($states_written)); $this->mrm_tax_create_alert($alert_state,'threshold_recompute_failed','payment_intent',0,array('message'=>$threshold_result->get_error_message(),'payment_intent_id'=>$pi_id),sanitize_key($pi_id)); return $threshold_result; } }
    $resolved=$this->mrm_tax_resolve_alerts_by_reference('payment_intent_id',$pi_id,array('tax_ledger_sync_failed')); if(is_wp_error($resolved)) return $resolved; return true;
  }

  public function mrm_tax_retry_association($payment_intent_id, $attempt) { $payment_intent = $this->stripe_retrieve_payment_intent($payment_intent_id); if (is_wp_error($payment_intent)) return $payment_intent; return $this->mrm_tax_sync_payment_intent_ledger($payment_intent, absint($attempt)); }
  private function mrm_tax_resync_payment_intent_id($payment_intent_id) { $payment_intent_id = sanitize_text_field($payment_intent_id); if ($payment_intent_id === '') return; $payment_intent = $this->stripe_retrieve_payment_intent($payment_intent_id); if (!is_wp_error($payment_intent)) return $this->mrm_tax_sync_payment_intent_ledger($payment_intent, 0); return $payment_intent; }
  public function sync_external_payment_intent_tax_ledger($payment_intent_id) { $payment_intent = $this->stripe_retrieve_payment_intent($payment_intent_id); if (is_wp_error($payment_intent)) return $payment_intent; return $this->mrm_tax_sync_payment_intent_ledger($payment_intent, 0); }
  private function mrm_verify_sheet_music_subscription_tax_configuration($price_id) {
    $price_id=sanitize_text_field($price_id); $expected_tax_code=$this->mrm_expected_subscription_tax_code();
    if($expected_tax_code==='') return new WP_Error('subscription_tax_model_invalid','The sheet-music subscription tax model is invalid.');
    if($price_id==='') return new WP_Error('subscription_price_id_missing','The configured Stripe subscription Price ID is missing.');
    $price=$this->stripe_retrieve_price($price_id); if(is_wp_error($price)) return $price;
    if(empty($price['active'])) return new WP_Error('subscription_price_inactive','The configured Stripe Price is inactive.');
    if(sanitize_key($price['type'] ?? '')!=='recurring') return new WP_Error('subscription_price_not_recurring','The configured Stripe Price is not recurring.');
    $interval=sanitize_key($price['recurring']['interval'] ?? ''); $interval_count=max(1,absint($price['recurring']['interval_count'] ?? 1));
    if($interval!=='month' || $interval_count!==1) return new WP_Error('subscription_interval_invalid','The configured Stripe Price must recur once every month.');
    $currency=strtolower(sanitize_text_field($price['currency'] ?? '')); if($currency!=='usd') return new WP_Error('subscription_currency_invalid','The configured Stripe Price is not USD.');
    $price_tax_behavior=sanitize_key($price['tax_behavior'] ?? ''); $effective_tax_behavior=$price_tax_behavior;
    if($effective_tax_behavior==='' || $effective_tax_behavior==='unspecified') { $tax_settings=$this->stripe_api_request('GET','/v1/tax/settings',array(),$this->mrm_stripe_tax_headers()); if(is_wp_error($tax_settings)) return new WP_Error('subscription_tax_settings_unavailable','The Stripe Price does not specify tax behavior and the Stripe Tax default could not be retrieved: '.$tax_settings->get_error_message()); $default_tax_behavior=sanitize_key($tax_settings['defaults']['tax_behavior'] ?? ''); if($default_tax_behavior==='exclusive' || ($default_tax_behavior==='inferred_by_currency' && $currency==='usd')) $effective_tax_behavior='exclusive'; }
    if($effective_tax_behavior!=='exclusive') return new WP_Error('subscription_tax_behavior_invalid','The subscription must use tax-exclusive pricing. Set the Price to exclusive or set the Stripe Tax default behavior to exclusive.');
    $product_id=is_array($price['product'] ?? null)?sanitize_text_field($price['product']['id'] ?? ''):sanitize_text_field($price['product'] ?? '');
    if($product_id==='') return new WP_Error('subscription_product_id_missing','The configured Stripe Price has no Product ID.');
    $product=$this->stripe_retrieve_product($product_id); if(is_wp_error($product)) return $product;
    if(empty($product['active'])) return new WP_Error('subscription_product_inactive','The configured Stripe Product is inactive.');
    $actual_tax_code=is_array($product['tax_code'] ?? null)?sanitize_text_field($product['tax_code']['id'] ?? ''):sanitize_text_field($product['tax_code'] ?? '');
    if($actual_tax_code!==$expected_tax_code) return new WP_Error('subscription_tax_code_mismatch','The Stripe Product tax code is '.($actual_tax_code!==''?$actual_tax_code:'missing').', but the site requires '.$expected_tax_code.'.');
    $profile=array('profile_version'=>self::TAX_SUBSCRIPTION_CONFIG_PROFILE_VERSION,'price_id'=>$price_id,'product_id'=>$product_id,'price_active'=>!empty($price['active'])?1:0,'product_active'=>!empty($product['active'])?1:0,'price_type'=>sanitize_key($price['type'] ?? ''),'currency'=>$currency,'price_tax_behavior'=>$price_tax_behavior,'effective_tax_behavior'=>$effective_tax_behavior,'recurring_interval'=>$interval,'recurring_interval_count'=>$interval_count,'expected_tax_code'=>$expected_tax_code,'actual_tax_code'=>$actual_tax_code);
    $configuration_fingerprint=hash('sha256',wp_json_encode($profile));
    return array('price'=>$price,'product'=>$product,'tax_code'=>$expected_tax_code,'profile'=>$profile,'configuration_fingerprint'=>$configuration_fingerprint);
  }

  private function mrm_tax_invoice_taxable_sales_cents($invoice) {
    $taxable_sales_cents = 0; $non_taxable_reasons = array('not_subject_to_tax','product_exempt','customer_exempt'); $lines = (array)($invoice['lines']['data'] ?? array());
    foreach ($lines as $line) { $line_amount = isset($line['amount_excluding_tax']) ? (int)$line['amount_excluding_tax'] : (int)($line['amount'] ?? 0); if ($line_amount <= 0) continue; $reasons = array(); foreach ((array)($line['taxes'] ?? array()) as $tax) { $reason = sanitize_key($tax['taxability_reason'] ?? ''); if ($reason !== '') $reasons[] = $reason; } foreach ((array)($line['tax_amounts'] ?? array()) as $tax) { $reason = sanitize_key($tax['taxability_reason'] ?? ''); if ($reason !== '') $reasons[] = $reason; } $explicitly_non_taxable = false; foreach (array_values(array_unique($reasons)) as $reason) { if (in_array($reason, $non_taxable_reasons, true)) { $explicitly_non_taxable = true; break; } } if (!$explicitly_non_taxable) $taxable_sales_cents += $line_amount; }
    if (empty($lines)) { $invoice_total = isset($invoice['total_excluding_tax']) ? (int)$invoice['total_excluding_tax'] : 0; $overall_reason = ''; foreach ((array)($invoice['total_taxes'] ?? array()) as $tax) { $reason = sanitize_key($tax['taxability_reason'] ?? ''); if ($reason !== '') { $overall_reason = $reason; break; } } if (!in_array($overall_reason, $non_taxable_reasons, true)) $taxable_sales_cents = $invoice_total; }
    return max(0, $taxable_sales_cents);
  }

  private function mrm_tax_record_subscription_invoice(
    $invoice
  ) {
    if (!is_array($invoice)) {
      return new WP_Error(
        'invalid_invoice',
        'Invalid Stripe invoice.'
      );
    }

    $invoice_id = sanitize_text_field(
      $invoice['id'] ?? ''
    );

    if ($invoice_id === '') {
      return new WP_Error(
        'missing_invoice_id',
        'Missing Stripe invoice ID.'
      );
    }

    $finalized_at = absint($invoice['status_transitions']['finalized_at'] ?? 0);
    if ($finalized_at <= 0) {
      return new WP_Error('subscription_invoice_finalized_at_missing','The Stripe subscription Invoice has no finalization timestamp.');
    }

    $subscription_id =
      $this->mrm_stripe_invoice_subscription_id(
        $invoice
      );

    $status = sanitize_key(
      $invoice['automatic_tax']['status']
        ?? ''
    );

    $address = is_array(
      $invoice['customer_address'] ?? null
    )
      ? $invoice['customer_address']
      : array();

    $state =
      $this->mrm_normalize_state_code(
        $address['state'] ?? ''
      );

    /*
     * Never write an incomplete Stripe Tax result into the
     * authoritative sales ledger.
     */
    if ($status !== 'complete') {
      $status_label =
        $status !== ''
          ? $status
          : 'unknown';

      $message =
        'Stripe automatic tax was not completed for invoice '
        . $invoice_id
        . '. Current status: '
        . $status_label
        . '.';

      $alert_result =
        $this->mrm_tax_create_alert(
          $state,
          'subscription_invoice_tax_failed',
          'invoice',
          0,
          array(
            'message' =>
              $message,

            'invoice_id' =>
              $invoice_id,

            'subscription_id' =>
              $subscription_id,

            'automatic_tax_status' =>
              $status_label,
          ),
          sanitize_key($invoice_id)
        );

      if (is_wp_error($alert_result)) {
        return $alert_result;
      }

      return new WP_Error(
        'subscription_invoice_tax_incomplete',
        $message
      );
    }

    /*
     * A complete tax result must also contain the state needed
     * for the state-by-state sales ledger.
     */
    if ($state === '') {
      return new WP_Error(
        'subscription_invoice_state_missing',
        'The finalized subscription Invoice has no customer state.'
      );
    }

    $tax_cents = 0;
    $reason = '';

    foreach (
      (array)(
        $invoice['total_taxes'] ?? array()
      )
      as $tax
    ) {
      $tax_cents +=
        (int)($tax['amount'] ?? 0);

      if (
        $reason === ''
        && !empty(
          $tax['taxability_reason']
        )
      ) {
        $reason = sanitize_key(
          $tax['taxability_reason']
        );
      }
    }

    $pretax = isset(
      $invoice['total_excluding_tax']
    )
      ? (int)$invoice[
          'total_excluding_tax'
        ]
      : max(
          0,
          (int)($invoice['total'] ?? 0)
            - $tax_cents
        );

    $taxable =
      $this
        ->mrm_tax_invoice_taxable_sales_cents(
          $invoice
        );

    $invoice_metadata = is_array($invoice['metadata'] ?? null) ? $invoice['metadata'] : array();
    $invoice_metadata['mrm_invoice_status'] = sanitize_key($invoice['status'] ?? '');
    $invoice_metadata['mrm_invoice_finalized_at'] = $finalized_at;
    $invoice_metadata['mrm_subscription_id'] = $subscription_id;

    $row_id =
      $this->mrm_tax_upsert_ledger_row(
        array(
          'external_id' =>
            'invoice:'
            . $invoice_id
            . ':sheet_music_subscription',

          'source_type' =>
            'subscription_invoice',

          'invoice_id' =>
            $invoice_id,

          'customer_state' =>
            $state,

          'customer_country' =>
            strtoupper(
              sanitize_text_field(
                $address['country']
                  ?? 'US'
              )
            ),

          'product_type' =>
            'sheet_music',

          'threshold_category' =>
            'digital_document_subscription',

          'gross_sales_cents' =>
            $pretax,

          'retail_sales_cents' =>
            $pretax,

          'taxable_sales_cents' =>
            $taxable,

          'tax_cents' =>
            $tax_cents,

          'transaction_count' =>
            1,

          'currency' =>
            sanitize_key(
              $invoice['currency']
                ?? 'usd'
            ),

          'tax_code' =>
            $this
              ->mrm_expected_subscription_tax_code(),

          'taxability_reason' =>
            $reason !== ''
              ? $reason
              : 'not_available',

          /*
           * Only complete invoices reach this point.
           */
          'tax_transaction_status' =>
            'complete',

          'occurred_at' =>
            $this
              ->mrm_tax_utc_mysql_from_timestamp(
                $finalized_at
              ),

          'metadata' =>
            $invoice_metadata,
        )
      );

    if (is_wp_error($row_id)) {
      return $row_id;
    }

    $threshold_result =
      $this
        ->mrm_tax_recompute_all_thresholds();

    if (is_wp_error($threshold_result)) {
      return $threshold_result;
    }

    $resolved =
      $this
        ->mrm_tax_resolve_alerts_by_reference(
          'invoice_id',
          $invoice_id,
          array(
            'subscription_invoice_tax_failed',
            'subscription_invoice_ledger_failed',
          )
        );

    if (is_wp_error($resolved)) {
      return $resolved;
    }

    return $row_id;
  }

  private function mrm_create_subscription_invoice_refund(
    $invoice_id,
    $amount_cents
  ) {
    $invoice_id =
      sanitize_text_field(
        $invoice_id
      );

    $amount_cents =
      absint(
        $amount_cents
      );

    if (
      $invoice_id === ''
      || $amount_cents <= 0
    ) {
      return new WP_Error(
        'invalid_invoice_refund',
        'Missing invoice or refund amount.'
      );
    }

    return $this->stripe_api_request(
      'POST',
      '/v1/credit_notes',
      array(
        /*
         * Total value credited by the
         * Credit Note.
         */
        'amount' =>
          $amount_cents,

        /*
         * Portion returned to the original
         * payment method.
         */
        'refund_amount' =>
          $amount_cents,

        'invoice' =>
          $invoice_id,

        'reason' =>
          'order_change',

        'memo' =>
          'Low Brass Lessons subscription refund',

        'metadata' => array(
          'source' =>
            'low_brass_lessons',

          'refund_type' =>
            'sheet_music_subscription',
        ),
      )
    );
  }

  private function mrm_tax_schedule_subscription_invoice_refund_retry(
  $invoice_id,
  $attempt,
  $message
) {
  $invoice_id = sanitize_text_field($invoice_id);
  $attempt = absint($attempt);

  if ($invoice_id === '' || $attempt > 6) {
    return new WP_Error('subscription_refund_retry_invalid', 'The subscription refund retry parameters were invalid.');
  }

  return $this->mrm_tax_schedule_checked_retry(
    'mrm_pay_hub_retry_subscription_invoice_refunds',
    array($invoice_id, $attempt),
    '',
    'subscription_credit_note_sync_failed',
    'invoice',
    array('invoice_id' => $invoice_id, 'attempt' => $attempt),
    sanitize_key($invoice_id),
    $message
  );
}

  private function mrm_tax_subscription_invoice_refund_failure(
  $invoice_id,
  $attempt,
  $message
) {
  global $wpdb;

  $invoice_id = sanitize_text_field($invoice_id);
  $attempt = absint($attempt);
  $message = sanitize_textarea_field($message);

  $state = $this->mrm_normalize_state_code(
    $wpdb->get_var(
      $wpdb->prepare(
        "SELECT customer_state
           FROM {$this->table_tax_sales_ledger()}
           WHERE external_id = %s
           LIMIT 1",
        'invoice:' . $invoice_id . ':sheet_music_subscription'
      )
    )
  );

  $alert_result = $this->mrm_tax_create_alert(
    $state,
    'subscription_credit_note_sync_failed',
    'invoice',
    0,
    array('message' => $message, 'invoice_id' => $invoice_id, 'attempts' => $attempt),
    sanitize_key($invoice_id)
  );

  if (is_wp_error($alert_result)) { return $alert_result; }

  if ($attempt < 6) {
    $schedule_result = $this->mrm_tax_schedule_subscription_invoice_refund_retry($invoice_id, $attempt + 1, $message);
    if (is_wp_error($schedule_result)) { return $schedule_result; }
  }

  return new WP_Error('subscription_credit_note_sync_failed', $message);
}

  public function mrm_tax_retry_subscription_invoice_refunds($invoice_id, $attempt) {
    $result = $this->mrm_tax_sync_subscription_invoice_refunds($invoice_id, $attempt);
    if (is_wp_error($result)) $this->stripe_debug_log('Subscription Credit Note reconciliation retry failed.', array('invoice_id'=>sanitize_text_field($invoice_id),'attempt'=>absint($attempt),'message'=>$result->get_error_message()));
  }

  private function mrm_tax_list_all_credit_notes_for_invoice($invoice_id) {
    $invoice_id = sanitize_text_field($invoice_id); $notes = array(); $starting_after = ''; $guard = 0;
    do { if (++$guard > 1000) return new WP_Error('credit_note_pagination_limit', 'Stripe Credit Note pagination exceeded the safety limit.'); $params = array('invoice'=>$invoice_id,'limit'=>100); if ($starting_after !== '') $params['starting_after'] = $starting_after; $response = $this->stripe_api_request('GET', '/v1/credit_notes', $params); if (is_wp_error($response)) return $response; $page = is_array($response['data'] ?? null) ? $response['data'] : array(); foreach ($page as $note) { $note_id = sanitize_text_field($note['id'] ?? ''); if ($note_id !== '') $notes[$note_id] = $note; } if (!empty($response['has_more'])) { if (empty($page)) return new WP_Error('credit_note_pagination_empty', 'Stripe reported more Credit Notes but returned an empty page.'); $last=end($page); $next=sanitize_text_field($last['id'] ?? ''); if ($next === '' || $next === $starting_after) return new WP_Error('credit_note_pagination_stalled', 'Stripe Credit Note pagination could not advance.'); $starting_after = $next; } else { $starting_after = ''; } } while ($starting_after !== '');
    return array_values($notes);
  }

  private function mrm_tax_sync_subscription_invoice_refunds($invoice_id, $attempt = 0) {
    global $wpdb;
    $invoice_id=sanitize_text_field($invoice_id); $attempt=absint($attempt);
    if ($invoice_id==='') return new WP_Error('missing_subscription_invoice','The subscription Invoice ID is missing.');
    $invoice=$this->stripe_api_request('GET','/v1/invoices/'.rawurlencode($invoice_id));
    if (is_wp_error($invoice)) return $this->mrm_tax_subscription_invoice_refund_failure($invoice_id,$attempt,'The subscription Invoice could not be retrieved: '.$invoice->get_error_message());
    $invoice_status=sanitize_key($invoice['status'] ?? ''); $external_id='invoice:'.$invoice_id.':sheet_music_subscription';
    $wpdb->last_error=''; $ledger_row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table_tax_sales_ledger()} WHERE external_id = %s LIMIT 1",$external_id),ARRAY_A);
    if ($wpdb->last_error!=='' || !is_array($ledger_row)) return $this->mrm_tax_subscription_invoice_refund_failure($invoice_id,$attempt,$wpdb->last_error!=='' ? 'The local subscription Invoice ledger could not be loaded: '.$wpdb->last_error : 'The local subscription Invoice tax-ledger row does not exist yet.');
    $ledger_metadata=json_decode((string)($ledger_row['metadata_json'] ?? ''),true); if(!is_array($ledger_metadata)) $ledger_metadata=array();
    $manual_direct_refunds=is_array($ledger_metadata['manual_direct_refunds'] ?? null) ? $ledger_metadata['manual_direct_refunds'] : array();
    $original_sales=max(0,(int)($ledger_row['gross_sales_cents'] ?? 0)); $original_tax=max(0,(int)($ledger_row['tax_cents'] ?? 0));
    $credit_notes=$this->mrm_tax_list_all_credit_notes_for_invoice($invoice_id); if(is_wp_error($credit_notes)) return $this->mrm_tax_subscription_invoice_refund_failure($invoice_id,$attempt,'Stripe Credit Notes could not be retrieved: '.$credit_notes->get_error_message());
    $refunded_sales_cents=0; $refunded_tax_cents=0; $reversal_ids=array(); $credit_note_refund_ids=array(); $resolved_manual_refund_ids=array();
    if (in_array($invoice_status,array('void','uncollectible'),true)) { $refunded_sales_cents=$original_sales; $refunded_tax_cents=$original_tax; $reversal_ids[]='invoice_status:'.$invoice_status; }
    else {
      foreach($credit_notes as $credit_note){ if(sanitize_key($credit_note['status'] ?? '')!=='issued') continue; $credit_note_id=sanitize_text_field($credit_note['id'] ?? ''); if($credit_note_id!=='') $reversal_ids[]=$credit_note_id; $refunded_sales_cents+=absint($credit_note['total_excluding_tax'] ?? 0); foreach((array)($credit_note['total_taxes'] ?? array()) as $tax) $refunded_tax_cents+=absint($tax['amount'] ?? 0); foreach((array)($credit_note['refunds'] ?? array()) as $linked_refund){ $linked_refund_id=is_array($linked_refund['refund'] ?? null) ? sanitize_text_field($linked_refund['refund']['id'] ?? '') : sanitize_text_field($linked_refund['refund'] ?? ''); if($linked_refund_id!=='') $credit_note_refund_ids[]=$linked_refund_id; } }
      $charge_id=''; $charge_result=$this->mrm_stripe_invoice_charge_id($invoice); if(!is_wp_error($charge_result)) $charge_id=sanitize_text_field($charge_result); elseif($invoice_status==='paid' || absint($invoice['amount_paid'] ?? 0)>0) return $this->mrm_tax_subscription_invoice_refund_failure($invoice_id,$attempt,'A paid subscription Invoice has no retrievable Charge: '.$charge_result->get_error_message());
      $refunds=array(); if($charge_id!==''){ $refunds=$this->mrm_stripe_list_all_refunds_for_charge($charge_id); if(is_wp_error($refunds)) return $this->mrm_tax_subscription_invoice_refund_failure($invoice_id,$attempt,'Direct Stripe refunds could not be retrieved: '.$refunds->get_error_message()); }
      foreach((array)$refunds as $refund){ $refund_id=sanitize_text_field($refund['id'] ?? ''); if($refund_id==='') continue; $refund_status=sanitize_key($refund['status'] ?? '');
        if(in_array($refund_status,array('pending','requires_action'),true)) return $this->mrm_tax_refund_lifecycle_failure($refund_id,$attempt,'Subscription refund '.$refund_id.' has not reached a final status. Current status: '.$refund_status.'.',array('invoice_id'=>$invoice_id,'charge_id'=>$charge_id,'refund_status'=>$refund_status));
        if(in_array($refund_status,array('failed','canceled'),true)) continue;
        if($refund_status!=='succeeded') return $this->mrm_tax_refund_lifecycle_failure($refund_id,$attempt,'Subscription refund '.$refund_id.' has an unsupported status: '.($refund_status!==''?$refund_status:'unknown').'.',array('invoice_id'=>$invoice_id,'charge_id'=>$charge_id));
        if(in_array($refund_id,$credit_note_refund_ids,true)) continue;
        $manual=is_array($manual_direct_refunds[$refund_id] ?? null) ? $manual_direct_refunds[$refund_id] : array(); $manual_sales=isset($manual['sales_cents'])?(int)$manual['sales_cents']:-1; $manual_tax=isset($manual['tax_cents'])?(int)$manual['tax_cents']:-1; $refund_amount=absint($refund['amount'] ?? 0);
        if($manual_sales<0 || $manual_tax<0 || ($manual_sales+$manual_tax)!==$refund_amount){ $message='Subscription Invoice refund '.$refund_id.' was created directly without an exact issued Credit Note relationship. Enter the authoritative refunded pretax and tax amounts before the local ledger can be reconciled.'; $alert_result=$this->mrm_tax_create_alert('', 'subscription_direct_refund_review_required','refund',0,array('message'=>$message,'refund_id'=>$refund_id,'invoice_id'=>$invoice_id,'charge_id'=>$charge_id,'refund_amount_cents'=>$refund_amount,'refund_status'=>$refund_status),sanitize_key($refund_id)); if(is_wp_error($alert_result)) return $alert_result; return new WP_Error('subscription_direct_refund_review_required',$message); }
        $refunded_sales_cents+=$manual_sales; $refunded_tax_cents+=$manual_tax; $reversal_ids[]=$refund_id; $resolved_manual_refund_ids[]=$refund_id;
      }
    }
    if($refunded_sales_cents>$original_sales || $refunded_tax_cents>$original_tax) return $this->mrm_tax_subscription_invoice_refund_failure($invoice_id,$attempt,'The combined subscription adjustments exceed the original Invoice ledger amounts.');
    $ledger_metadata['mrm_invoice_status']=$invoice_status; $ledger_metadata['mrm_invoice_adjustments_synced_at']=current_time('mysql');
    $wpdb->last_error=''; $updated=$wpdb->update($this->table_tax_sales_ledger(),array('refunded_sales_cents'=>max(0,$refunded_sales_cents),'refunded_tax_cents'=>max(0,$refunded_tax_cents),'tax_reversals_json'=>wp_json_encode(array_values(array_unique(array_filter($reversal_ids)))),'metadata_json'=>wp_json_encode($ledger_metadata),'updated_at'=>current_time('mysql')),array('external_id'=>$external_id));
    if($updated===false || $wpdb->last_error!=='') return $this->mrm_tax_subscription_invoice_refund_failure($invoice_id,$attempt,'The local subscription adjustment ledger could not be updated: '.($wpdb->last_error ?: 'Unknown database error.'));
    $threshold_result=$this->mrm_tax_recompute_all_thresholds(); if(is_wp_error($threshold_result)) return $this->mrm_tax_subscription_invoice_refund_failure($invoice_id,$attempt,'The Invoice ledger was updated, but state threshold recomputation failed: '.$threshold_result->get_error_message());
    $resolved=$this->mrm_tax_resolve_alerts_by_reference('invoice_id',$invoice_id,array('subscription_credit_note_sync_failed')); if(is_wp_error($resolved)) return $resolved;
    foreach(array_values(array_unique($resolved_manual_refund_ids)) as $resolved_refund_id){ $resolved=$this->mrm_tax_resolve_alerts_by_reference('refund_id',$resolved_refund_id,array('subscription_direct_refund_review_required','refund_lifecycle_reconciliation_failed')); if(is_wp_error($resolved)) return $resolved; }
    return true;
  }




  private function stripe_retrieve_price($price_id) { $price_id = sanitize_text_field($price_id); if ($price_id === '') return new WP_Error('missing_price_id', 'Missing Stripe Price ID.'); return $this->stripe_api_request('GET', '/v1/prices/' . rawurlencode($price_id)); }
  private function stripe_retrieve_product($product_id) { $product_id = sanitize_text_field($product_id); if ($product_id === '') return new WP_Error('missing_product_id', 'Missing Stripe Product ID.'); return $this->stripe_api_request('GET', '/v1/products/' . rawurlencode($product_id)); }
  private function mrm_expected_subscription_tax_code() { $access_model = sanitize_key(get_option('mrm_sheet_music_subscription_tax_model', 'downloadable_conditional')); if ($access_model === 'view_only_conditional') return 'txcd_10503005'; if ($access_model === 'downloadable_conditional') return 'txcd_10503002'; return ''; }


  /* =========================================================
   * Orders ledger helpers
   * ======================================================= */

  private function mrm_fail_order_before_payment_intent($order_id, $message) {
    global $wpdb; $order_id = absint($order_id); if ($order_id <= 0) return;
    $wpdb->update($this->table_orders(), array('status'=>'failed','stripe_status'=>'customer_tax_location_invalid','updated_at'=>current_time('mysql')), array('id'=>$order_id));
    $wpdb->delete($this->table_promo_redemptions(), array('order_id'=>$order_id,'status'=>'pending'));
    $this->stripe_debug_log('Order stopped before PaymentIntent creation.', array('order_id'=>$order_id,'message'=>sanitize_text_field($message)));
  }

  private function mrm_sanitize_checkout_request_id($request_id) {
    $request_id = sanitize_text_field((string)$request_id);
    if ($request_id === '' || strlen($request_id) < 16 || strlen($request_id) > 100 || !preg_match('/^[A-Za-z0-9_-]+$/', $request_id)) return '';
    return $request_id;
  }

  private function mrm_checkout_lock_name($request_id) {
    $request_id = $this->mrm_sanitize_checkout_request_id($request_id);
    return $request_id === '' ? '' : 'mrm_checkout_' . substr(hash('sha256', $request_id), 0, 48);
  }

  private function mrm_acquire_checkout_lock($request_id) {
    global $wpdb;
    $lock_name = $this->mrm_checkout_lock_name($request_id);
    if ($lock_name === '') return new WP_Error('checkout_request_id_invalid', 'The checkout request ID is invalid.');
    $acquired = $wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s, %d)', $lock_name, 30));
    if ((int)$acquired !== 1) return new WP_Error('checkout_request_in_progress', 'This checkout request is already being processed. Please wait a moment and try again.');
    return $lock_name;
  }

  private function mrm_release_checkout_lock($lock_name) {
    global $wpdb;
    $lock_name = sanitize_text_field((string)$lock_name);
    if ($lock_name !== '') $wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)', $lock_name));
  }

  private function mrm_checkout_order_matches_customer($order, $email_hash, $sku) {
    return is_array($order) && hash_equals((string)($order['email_hash'] ?? ''), (string)$email_hash) && $this->sanitize_sku((string)($order['sku'] ?? '')) === $this->sanitize_sku((string)$sku);
  }

  private function mrm_build_piece_checkout_state_fingerprint(
    $checkout_request_id,
    $email_hash,
    $sku,
    $data,
    $context,
    $terms_version,
    $source_flow
  ) {
    $checkout_request_id = $this->mrm_sanitize_checkout_request_id($checkout_request_id);
    $email_hash = sanitize_text_field((string)$email_hash);
    $sku = $this->sanitize_sku((string)$sku);
    $data = is_array($data) ? $data : array();
    $context = is_array($context) ? $context : array();
    $address = $this->mrm_normalize_tax_address(
      isset($data['address']) && is_array($data['address']) ? $data['address'] : array()
    );

    $state = array(
      'checkout_request_id' => $checkout_request_id,
      'email_hash' => $email_hash,
      'sku' => $sku,
      'promo_code' => $this->mrm_normalize_promo_code($data['promo_code'] ?? ''),
      'fundamentals_addon' => isset($data['fundamentals_addon']) && strtolower((string)$data['fundamentals_addon']) === 'yes' ? 'yes' : 'no',
      'sheet_music_addon' => isset($data['sheet_music_addon']) && strtolower((string)$data['sheet_music_addon']) === 'yes' ? 'yes' : 'no',
      'save_card' => !empty($data['save_card']) ? 'yes' : 'no',
      'amount_override_cents' => max(0, (int)($data['amount_override_cents'] ?? 0)),
      'terms_accepted' => !empty($context['terms_accepted']) ? 'yes' : 'no',
      'terms_version' => sanitize_text_field((string)$terms_version),
      'source_flow' => sanitize_key((string)$source_flow),
      'piece_slug' => sanitize_title((string)($context['piece_slug'] ?? '')),
      'address' => array(
        'line1' => (string)($address['line1'] ?? ''),
        'line2' => (string)($address['line2'] ?? ''),
        'city' => (string)($address['city'] ?? ''),
        'state' => (string)($address['state'] ?? ''),
        'postal_code' => (string)($address['postal_code'] ?? ''),
        'country' => (string)($address['country'] ?? 'US'),
      ),
    );

    return hash('sha256', wp_json_encode($state));
  }

  private function mrm_validate_existing_piece_checkout_state($order, $email_hash, $sku, $incoming_state_fingerprint) {
    if (!$this->mrm_checkout_order_matches_customer($order, $email_hash, $sku)) {
      return new WP_Error('checkout_request_mismatch', 'This checkout request does not match the current customer or product.');
    }
    if (sanitize_key((string)($order['product_type'] ?? '')) !== 'sheet_music') {
      return new WP_Error('checkout_request_product_mismatch', 'This checkout request does not belong to a sheet-music purchase.');
    }

    /* Prevent reuse after pricing, tax registrations, or customer details may have changed. */
    $created_timestamp = strtotime((string)($order['created_at'] ?? ''));
    if ($created_timestamp && (current_time('timestamp') - $created_timestamp) > 1800) {
      return new WP_Error('checkout_request_expired', 'This checkout session has expired. Please close checkout and begin again.');
    }

    $metadata = $this->mrm_get_order_meta_array($order);
    $stored_state_fingerprint = sanitize_text_field((string)($metadata['mrm_checkout_state_fingerprint'] ?? ''));
    $incoming_state_fingerprint = sanitize_text_field((string)$incoming_state_fingerprint);
    if ($stored_state_fingerprint === '' || $incoming_state_fingerprint === '' || !hash_equals($stored_state_fingerprint, $incoming_state_fingerprint)) {
      return new WP_Error('checkout_request_parameters_changed', 'The checkout details changed during payment creation. Please close checkout and begin again.');
    }
    return true;
  }

  private function mrm_validate_reused_fundamentals_ownership(
    $order
  ) {
    if (!is_array($order)) {
      return new WP_Error(
        'checkout_order_invalid',
        'The existing checkout order could not be read.'
      );
    }

    /*
     * This validation applies only to sheet-music checkouts.
     */
    if (
      sanitize_key(
        (string)(
          $order['product_type'] ?? ''
        )
      ) !== 'sheet_music'
    ) {
      return true;
    }

    $metadata =
      $this->mrm_get_order_meta_array(
        $order
      );

    $fundamentals_selected = (
      strtolower(
        (string)(
          $metadata[
            'mrm_fundamentals_addon'
          ] ?? 'no'
        )
      ) === 'yes'
    );

    /*
     * A Full Piece-only checkout has no packet ownership to
     * recheck.
     */
    if (!$fundamentals_selected) {
      return true;
    }

    $packet_sku =
      $this->sanitize_sku(
        (string)(
          $metadata[
            'mrm_fundamentals_addon_sku'
          ] ?? ''
        )
      );

    $packet_amount_cents =
      max(
        0,
        (int)(
          $metadata[
            'mrm_fundamentals_addon_amount_cents'
          ] ?? 0
        )
      );

    $customer_email =
      sanitize_email(
        (string)(
          $metadata[
            'mrm_customer_email'
          ] ??
          $order[
            'customer_email'
          ] ??
          ''
        )
      );

    /*
     * A stored combined checkout must contain a valid packet
     * SKU, selling amount, and customer email before it can be
     * safely reused.
     */
    if (
      $packet_sku === '' ||
      $packet_amount_cents <= 0 ||
      $customer_email === '' ||
      !is_email($customer_email)
    ) {
      return new WP_Error(
        'checkout_snapshot_incomplete',
        'The stored Fundamental Packet checkout information is incomplete. Please close checkout and begin again.'
      );
    }

    $ownership =
      $this
        ->mrm_get_authoritative_fundamentals_ownership_match(
          $customer_email,
          $packet_sku
        );

    if (is_wp_error($ownership)) {
      return $ownership;
    }

    if (empty($ownership['owned'])) {
      return true;
    }

    /*
     * Return the same error code already handled by the
     * product-page checkout frontend.
     */
    return new WP_Error(
      'fundamentals_addon_already_owned',

      'This email already has access to the Fundamental Packet, so it has not been added to the order.',

      array(
        'ownership_source' =>
          sanitize_key(
            (string)(
              $ownership[
                'ownership_source'
              ] ?? ''
            )
          ),

        'ownership_sku' =>
          $this->sanitize_sku(
            (string)(
              $ownership[
                'ownership_sku'
              ] ?? ''
            )
          ),
      )
    );
  }

  private function mrm_checkout_wp_error_response(
    $error,
    $default_status = 409
  ) {
    if (!is_wp_error($error)) {
      return new WP_REST_Response(
        array(
          'ok' =>
            false,

          'code' =>
            'checkout_unknown_error',

          'message' =>
            'Checkout could not be completed.',
        ),
        500
      );
    }

    $error_code =
      sanitize_key(
        (string)(
          $error->get_error_code()
        )
      );

    $error_data =
      $error->get_error_data();

    $error_data =
      is_array($error_data)
        ? $error_data
        : array();

    $status =
      max(
        400,
        (int)$default_status
      );

    /*
     * Existing ownership is a checkout-state conflict rather
     * than a server failure.
     */
    if (
      $error_code ===
      'fundamentals_addon_already_owned'
    ) {
      $status = 409;
    }

    if (in_array($error_code, array(
      'sheet_music_subscription_lookup_failed',
      'piece_checkout_cancel_failed',
    ), true)) {
      $status = 503;
    }

    return new WP_REST_Response(
      array(
        'ok' =>
          false,

        'code' =>
          $error_code !== ''
            ? $error_code
            : 'checkout_error',

        'message' =>
          $error->get_error_message(),

        'ownership_source' =>
          sanitize_key(
            (string)(
              $error_data[
                'ownership_source'
              ] ?? ''
            )
          ),

        'ownership_sku' =>
          $this->sanitize_sku(
            (string)(
              $error_data[
                'ownership_sku'
              ] ?? ''
            )
          ),

        'active_subscription' => !empty($error_data['active_subscription']),
        'subscription_status' => sanitize_key((string)($error_data['subscription_status'] ?? '')),
      ),
      $status
    );
  }

  private function mrm_resume_unattached_piece_checkout_order($order, $checkout_request_id) {
    if (!is_array($order) || empty($order['id'])) return new WP_Error('checkout_order_invalid', 'The existing checkout order could not be read.');
    $order_id = absint($order['id']);
    $checkout_request_id = $this->mrm_sanitize_checkout_request_id($checkout_request_id);
    if ($order_id <= 0 || $checkout_request_id === '') return new WP_Error('checkout_resume_invalid', 'The previous checkout could not be resumed.');
    if (!empty($order['stripe_payment_intent_id'])) return $this->mrm_build_reused_checkout_response($order);
    if (sanitize_key((string)($order['product_type'] ?? '')) !== 'sheet_music') {
      return new WP_Error('checkout_resume_product_invalid', 'Only sheet-music checkout requests can be resumed through this payment flow.');
    }

    $metadata = $this->mrm_get_order_meta_array($order);
    $stored_request_id = $this->mrm_sanitize_checkout_request_id($metadata['mrm_checkout_request_id'] ?? '');
    if ($stored_request_id === '' || !hash_equals($stored_request_id, $checkout_request_id)) {
      return new WP_Error('checkout_resume_request_mismatch', 'The stored checkout request does not match the current request.');
    }

    $ownership_validation =
      $this
        ->mrm_validate_reused_fundamentals_ownership(
          $order
        );

    if (is_wp_error($ownership_validation)) {
      return $ownership_validation;
    }

    $amount_cents = max(0, (int)($order['amount_cents'] ?? 0));
    $currency = strtolower(sanitize_text_field((string)($order['currency'] ?? 'usd')));
    $tax_calculation_id = sanitize_text_field((string)($metadata['mrm_tax_calculation_id'] ?? ''));
    if ($amount_cents <= 0 || $tax_calculation_id === '') {
      return new WP_Error('checkout_snapshot_incomplete', 'The stored checkout calculation is incomplete. Please close checkout and begin again.');
    }

    $metadata['mrm_order_id'] = (string)$order_id;
    $customer_email = sanitize_email((string)($metadata['mrm_customer_email'] ?? $order['customer_email'] ?? ''));
    $email_hash = sanitize_text_field((string)($order['email_hash'] ?? ''));
    $promo_code = $this->mrm_normalize_promo_code($metadata['mrm_promo_code'] ?? '');
    $promo_discount_cents = max(0, (int)($metadata['mrm_promo_discount_cents'] ?? 0));
    if ($promo_code !== '' && $promo_discount_cents > 0) {
      $promo = $this->mrm_get_active_promo_code($promo_code);
      $reserved = $this->mrm_reserve_promo_redemption($promo_code, $email_hash, $order_id, '', $customer_email, is_array($promo) ? $promo : array());
      if (!$reserved) return new WP_Error('promo_code_reservation_failed', 'The promotional code could not be reserved for the resumed checkout.');
    }

    $stripe_idempotency_key = 'mrm-pi-' . hash('sha256', $checkout_request_id);
    $payment_intent = $this->stripe_create_payment_intent(
      $amount_cents, $currency, $metadata, 'Low Brass Lessons - Sheet Music Charge', array(), array('card'), $tax_calculation_id, $stripe_idempotency_key
    );
    if (is_wp_error($payment_intent)) {
      if ($promo_code !== '' && $promo_discount_cents > 0) {
        $this->mrm_release_pending_promo_redemption($order_id);
      }
      return $payment_intent;
    }
    $payment_intent_id = sanitize_text_field((string)($payment_intent['id'] ?? ''));
    if ($payment_intent_id === '') {
      if ($promo_code !== '' && $promo_discount_cents > 0) {
        $this->mrm_release_pending_promo_redemption($order_id);
      }
      return new WP_Error('checkout_payment_intent_missing', 'Stripe did not return a Payment Intent ID.');
    }

    $this->attach_payment_intent_to_order($order_id, $payment_intent_id, sanitize_key((string)($payment_intent['status'] ?? '')));
    if ($promo_code !== '' && $promo_discount_cents > 0) $this->mrm_attach_payment_intent_to_promo_redemption($order_id, $payment_intent_id);
    $fresh_order = $this->get_order($order_id);
    if (!is_array($fresh_order)) return new WP_Error('checkout_order_reload_failed', 'The resumed checkout order could not be reloaded.');
    return $this->mrm_build_reused_checkout_response($fresh_order);
  }

  private function mrm_build_reused_checkout_response($order) {
    if (!is_array($order) || empty($order['id'])) return new WP_Error('checkout_order_invalid', 'The existing checkout order could not be read.');
    $payment_intent_id = sanitize_text_field((string)($order['stripe_payment_intent_id'] ?? ''));
    if ($payment_intent_id === '') return new WP_Error('checkout_payment_intent_missing', 'The existing checkout does not yet have a Payment Intent.');
    $pi = $this->stripe_retrieve_payment_intent($payment_intent_id);
    if (is_wp_error($pi)) return $pi;
    $status = sanitize_key((string)($pi['status'] ?? ''));
    if ($status === 'succeeded') return new WP_Error('checkout_request_already_completed', 'This checkout request has already been paid.');
    if ($status === 'canceled') return new WP_Error('checkout_payment_intent_unusable', 'The previous checkout attempt can no longer be used. Please close checkout and begin again.');
    $ownership_validation =
      $this
        ->mrm_validate_reused_fundamentals_ownership(
          $order
        );

    if (is_wp_error($ownership_validation)) {
      return $ownership_validation;
    }
    $client_secret = sanitize_text_field((string)($pi['client_secret'] ?? ''));
    if ($client_secret === '') return new WP_Error('checkout_client_secret_missing', 'Stripe did not return a usable client secret.');
    $metadata = json_decode((string)($order['metadata_json'] ?? ''), true);
    $metadata = is_array($metadata) ? $metadata : array();
    if (is_array($pi['metadata'] ?? null)) $metadata = array_replace($metadata, $pi['metadata']);
    $sku = $this->sanitize_sku((string)($order['sku'] ?? ($metadata['mrm_sku'] ?? '')));
    $product = $this->get_product($sku);
    $methods = array_values(array_filter(array_map('sanitize_key', (array)($pi['payment_method_types'] ?? array('card')))));
    if (!$methods) $methods = array('card');
    $key = $this->publishable_key();
    if ($key === '') return new WP_Error('stripe_publishable_key_missing', 'Stripe publishable key is not configured.');
    $amount = (int)($pi['amount'] ?? ($order['amount_cents'] ?? 0));
    return new WP_REST_Response(array(
      'ok'=>true, 'reused_checkout_request'=>true, 'publishableKey'=>$key, 'client_secret'=>$client_secret,
      'payment_intent_id'=>$payment_intent_id, 'allowed_payment_methods'=>$methods, 'order_id'=>(int)$order['id'],
      'customer_id'=>is_array($pi['customer'] ?? null) ? sanitize_text_field((string)($pi['customer']['id'] ?? '')) : sanitize_text_field((string)($pi['customer'] ?? '')),
      'sku'=>$sku, 'label'=>sanitize_text_field((string)(is_array($product) ? ($product['label'] ?? $sku) : $sku)),
      'amount_cents'=>$amount, 'total_cents'=>$amount,
      'original_base_amount_cents'=>(int)($metadata['mrm_original_base_amount_cents'] ?? 0), 'base_amount_cents'=>(int)($metadata['mrm_base_amount_cents'] ?? 0),
      'addon_amount_cents'=>(int)($metadata['mrm_addon_amount_cents'] ?? 0), 'fundamentals_addon_selected'=>strtolower((string)($metadata['mrm_fundamentals_addon'] ?? 'no')) === 'yes',
      'fundamentals_addon_sku'=>$this->sanitize_sku((string)($metadata['mrm_fundamentals_addon_sku'] ?? '')), 'fundamentals_addon_label'=>sanitize_text_field((string)($metadata['mrm_fundamentals_addon_label'] ?? '')),
      'fundamentals_addon_amount_cents'=>(int)($metadata['mrm_fundamentals_addon_amount_cents'] ?? 0), 'promo_code'=>sanitize_text_field((string)($metadata['mrm_promo_code'] ?? '')),
      'promo_discount_cents'=>(int)($metadata['mrm_promo_discount_cents'] ?? 0), 'tax_cents'=>(int)($metadata['mrm_tax_cents'] ?? 0),
      'tax_message'=>sanitize_text_field((string)($metadata['mrm_tax_policy_message'] ?? '')), 'tax_calculation_id'=>sanitize_text_field((string)($metadata['mrm_tax_calculation_id'] ?? '')),
      'currency'=>strtolower(sanitize_text_field((string)($order['currency'] ?? ($pi['currency'] ?? 'usd')))),
      'product_type'=>sanitize_key((string)($order['product_type'] ?? ($metadata['mrm_product_type'] ?? ''))), 'category'=>sanitize_key((string)(is_array($product) ? ($product['category'] ?? '') : '')),
    ), 200);
  }

  private function create_order($email_hash, $sku, $product_type, $amount_cents, $currency, $metadata) {
    global $wpdb;

    $now = current_time('mysql');
    $environment_mode = 'live';

    $metadata = is_array($metadata) ? $metadata : array();
    $customer_email = sanitize_email((string)($metadata['mrm_customer_email'] ?? ''));

    $wpdb->insert($this->table_orders(), array(
      'email_hash' => $email_hash,
      'customer_email' => $customer_email ?: null,
      'sku' => $sku,
      'product_type' => $product_type,
      'amount_cents' => (int)$amount_cents,
      'currency' => $currency ?: 'usd',
      'environment_mode' => $environment_mode,
      'status' => 'created',
      'metadata_json' => wp_json_encode($metadata),
      'created_at' => $now,
      'updated_at' => $now,
    ), array('%s','%s','%s','%s','%d','%s','%s','%s','%s','%s','%s'));

    return (int)$wpdb->insert_id;
  }

  private function attach_payment_intent_to_order($order_id, $payment_intent_id, $stripe_status = null, $local_status = 'processing') {
    global $wpdb;

    $data = array(
      'stripe_payment_intent_id' => $payment_intent_id,
      'stripe_status' => $stripe_status,
      'updated_at' => current_time('mysql'),
    );
    $fmt = array('%s','%s','%s');

    if ($local_status !== null && $local_status !== '') {
      $data['status'] = (string)$local_status;
      $fmt[] = '%s';
    }

    $wpdb->update(
      $this->table_orders(),
      $data,
      array('id' => (int)$order_id),
      $fmt,
      array('%d')
    );
  }

  private function update_order_amount_and_metadata($order_id, $amount_cents, $metadata_array) {
    global $wpdb;
    $wpdb->update(
      $this->table_orders(),
      array(
        'amount_cents' => (int)$amount_cents,
        'metadata_json' => wp_json_encode(is_array($metadata_array) ? $metadata_array : array()),
        'updated_at' => current_time('mysql'),
      ),
      array('id' => (int)$order_id),
      array('%d','%s','%s'),
      array('%d')
    );
  }

  private function get_order($order_id) {
    global $wpdb;
    return $wpdb->get_row($wpdb->prepare(
      "SELECT * FROM {$this->table_orders()} WHERE id=%d LIMIT 1",
      (int)$order_id
    ), ARRAY_A);
  }

  private function get_order_by_pi($payment_intent_id) {
    global $wpdb;
    return $wpdb->get_row($wpdb->prepare(
      "SELECT * FROM {$this->table_orders()} WHERE stripe_payment_intent_id=%s LIMIT 1",
      $payment_intent_id
    ), ARRAY_A);
  }

  private function get_order_by_meta_value($meta_key, $meta_value) {
    global $wpdb;

    $meta_key = sanitize_key((string)$meta_key);
    $meta_value = sanitize_text_field((string)$meta_value);

    if ($meta_key === '' || $meta_value === '') {
      return null;
    }

    $orders = $this->table_orders();

    return $wpdb->get_row(
      $wpdb->prepare(
        "SELECT *
         FROM {$orders}
         WHERE metadata_json LIKE %s
         ORDER BY id DESC
         LIMIT 1",
        '%' . $wpdb->esc_like('"' . $meta_key . '":"' . $meta_value . '"') . '%'
      ),
      ARRAY_A
    );
  }

  private function update_order_status_from_pi($payment_intent_id, $status, $stripe_status = null, $metadata = null) {
    global $wpdb;
    $data = array(
      'status' => $status,
      'stripe_payment_intent_id' => (string)$payment_intent_id,
      'stripe_status' => $stripe_status,
      'updated_at' => current_time('mysql'),
    );
    $fmt = array('%s','%s','%s','%s');

    if ($metadata !== null) {
      // Merge with any existing metadata_json so we can store local flags (like receipt sent)
      $existing_json = $wpdb->get_var($wpdb->prepare(
        "SELECT metadata_json FROM {$this->table_orders()} WHERE stripe_payment_intent_id=%s LIMIT 1",
        $payment_intent_id
      ));
      $existing = array();
      if ($existing_json) {
        $decoded = json_decode((string)$existing_json, true);
        if (is_array($decoded)) $existing = $decoded;
      }

      $incoming = is_array($metadata) ? $metadata : array();
      $merged = array_merge($existing, $incoming);

      $data['metadata_json'] = wp_json_encode($merged);
      $fmt[] = '%s';
    }

    $wpdb->update($this->table_orders(), $data, array('stripe_payment_intent_id' => $payment_intent_id), $fmt, array('%s'));
  }

  private function link_order($order_id, $source, $source_object_id) {
    global $wpdb;
    $wpdb->insert($this->table_links(), array(
      'order_id' => (int)$order_id,
      'source' => sanitize_text_field((string)$source),
      'source_object_id' => sanitize_text_field((string)$source_object_id),
      'created_at' => current_time('mysql'),
    ), array('%d','%s','%s','%s'));
  }


  private function mrm_create_or_update_credits_for_order($order_id, $instructor_id, $email_hash, $currency, $base_cents, $lesson_count) {
    global $wpdb;
    $table = $this->table_lesson_credits();
    $now = current_time('mysql');

    $lesson_count = max(1, (int)$lesson_count);
    $unit = (int) floor(((int)$base_cents) / $lesson_count);

    $exists = $wpdb->get_var($wpdb->prepare(
      "SELECT id FROM {$table} WHERE order_id=%d AND instructor_id=%d LIMIT 1",
      (int)$order_id,
      (int)$instructor_id
    ));

    if ($exists) return (int)$exists;

    $wpdb->insert($table, array(
      'order_id' => (int)$order_id,
      'instructor_id' => (int)$instructor_id,
      'email_hash' => (string)$email_hash,
      'currency' => strtolower((string)$currency),
      'unit_base_cents' => (int)$unit,
      'total_credits' => (int)$lesson_count,
      'remaining_credits' => (int)$lesson_count,
      'created_at' => $now,
      'updated_at' => $now,
    ), array('%d','%d','%s','%s','%d','%d','%d','%s','%s'));

    return (int)$wpdb->insert_id;
  }

