  public function rest_stripe_webhook(WP_REST_Request $req) {
    $payload = $req->get_body();
    $this->stripe_debug_log('stripe webhook entrypoint reached');
    $signature = isset($_SERVER['HTTP_STRIPE_SIGNATURE']) ? (string)$_SERVER['HTTP_STRIPE_SIGNATURE'] : '';
    $secret = $this->webhook_secret();

    if (!$secret) {
      return new WP_REST_Response(array('ok' => false, 'message' => 'Webhook secret is not configured.'), 500);
    }

    $event = $this->stripe_construct_webhook_event($payload, $signature, $secret);
    if (is_wp_error($event)) {
      return new WP_REST_Response(array('ok' => false, 'message' => $event->get_error_message()), 400);
    }

    $event_id = (string)($event['id'] ?? '');
    $event_type = (string)($event['type'] ?? '');

    $this->stripe_debug_log('webhook received', array(
      'event_id' => (string)($event['id'] ?? ''),
      'event_type' => $event_type,
    ));
    $object = isset($event['data']['object']) && is_array($event['data']['object']) ? $event['data']['object'] : array();
    $object_id = (string)($object['id'] ?? '');

    if ($event_id === '' || $event_type === '') {
      return new WP_REST_Response(array('ok' => false, 'message' => 'Invalid webhook event.'), 400);
    }

    if ($this->mrm_webhook_event_already_processed($event_id)) {
      return new WP_REST_Response(array('ok' => true, 'duplicate' => true), 200);
    }

    $required_processing_result = true;

    switch ($event_type) {
      case 'payment_intent.succeeded':
        $required_processing_result =
          $this
            ->mrm_handle_payment_intent_succeeded_webhook(
              $object
            );
        break;

      case 'payment_intent.payment_failed':
        $required_processing_result =
          $this->mrm_handle_payment_intent_failed_webhook($object, 'failed');
        break;

      case 'payment_intent.canceled':
        $required_processing_result =
          $this->mrm_handle_payment_intent_failed_webhook($object, 'canceled');
        break;

      case 'charge.refunded':
        $required_processing_result =
          $this
            ->mrm_handle_charge_refunded_webhook(
              $object
            );
        break;

      case 'refund.created':
        $required_processing_result =
          $this
            ->mrm_handle_refund_created_webhook(
              $object
            );
        break;

      case 'refund.updated':
        $required_processing_result =
          $this
            ->mrm_handle_refund_updated_webhook(
              $object
            );
        break;

      case 'refund.failed':
        $required_processing_result =
          $this
            ->mrm_handle_refund_failed_webhook(
              $object
            );
        break;

      case 'credit_note.created':
      case 'credit_note.updated':
      case 'credit_note.voided':
        $invoice_id = $this->mrm_stripe_expandable_id($object['invoice'] ?? '');
        if ($invoice_id === '') {
          $required_processing_result = new WP_Error('credit_note_invoice_missing', 'The Credit Note webhook does not contain an Invoice ID.');
        } else {
          $required_processing_result = $this->mrm_tax_sync_subscription_invoice_refunds($invoice_id, 0);
        }
        break;

      case 'customer.subscription.created':
        $required_processing_result = $this->mrm_handle_customer_subscription_created_webhook($object);
        break;

      case 'customer.subscription.updated':
        $required_processing_result = $this->mrm_handle_customer_subscription_updated_webhook($object);
        break;

      case 'customer.updated':
        $required_processing_result = $this->mrm_handle_customer_updated_webhook($object);
        break;

      case 'customer.subscription.deleted':
        $this->mrm_handle_customer_subscription_deleted_webhook($object);
        break;

      case 'invoice.upcoming':
        $required_processing_result = $this->mrm_handle_invoice_upcoming_webhook($object);
        break;

      case 'invoice.finalization_failed':
        $required_processing_result = $this->mrm_handle_invoice_finalization_failed_webhook($object);
        break;

      case 'invoice.finalized':
        $required_processing_result = $this->mrm_handle_invoice_finalized_webhook($object);
        break;

      case 'invoice.voided':
        $required_processing_result = $this->mrm_handle_invoice_voided_webhook($object);
        break;

      case 'invoice.marked_uncollectible':
        $required_processing_result = $this->mrm_handle_invoice_marked_uncollectible_webhook($object);
        break;

      case 'invoice.paid':
        $required_processing_result =
          $this
            ->mrm_handle_invoice_paid_webhook(
              $object
            );
        break;

      case 'invoice.payment_failed':
        $this->mrm_handle_invoice_payment_failed_webhook($object);
        break;

      default:
        // Acknowledge unhandled events so Stripe does not keep retrying forever.
        break;
    }

    if (is_wp_error($required_processing_result)) {
      $this->stripe_debug_log('Required Stripe webhook processing failed.', array('event_id'=>$event_id,'event_type'=>$event_type,'object_id'=>$object_id,'message'=>$required_processing_result->get_error_message()));
      return new WP_REST_Response(array('ok'=>false,'message'=>'Required local reconciliation failed.'), 500);
    }

    $this->mrm_mark_webhook_event_processed($event_id, $event_type, $object_id);

    $this->stripe_debug_log('webhook processed successfully', array(
      'event_id' => (string)($event['id'] ?? ''),
      'event_type' => $event_type,
    ));

    return new WP_REST_Response(array('ok' => true), 200);
  }

  public function rest_subscription_portal(WP_REST_Request $req) {
    $token = sanitize_text_field((string)$req->get_param('token'));
    if ($token === '') {
      wp_die('Missing subscription token.', 'Subscription Portal', array('response' => 400));
    }

    $sub = $this->mrm_get_sheet_music_subscription_by_portal_token($token);
    if (empty($sub['id']) || empty($sub['stripe_customer_id'])) {
      wp_die('Invalid subscription token.', 'Subscription Portal', array('response' => 404));
    }

    /*
     * Refresh from Stripe before opening the portal, so an old email link cannot
     * open management for a subscription that has already cancelled or expired.
     */
    if (!empty($sub['stripe_subscription_id'])) {
      $stripe_sub = $this->stripe_retrieve_subscription((string)$sub['stripe_subscription_id']);

      if (!is_wp_error($stripe_sub) && is_array($stripe_sub)) {
        $this->mrm_sync_local_sheet_music_subscription_from_stripe(
          $stripe_sub,
          (string)($sub['email_plain'] ?? '')
        );

        $sub = $this->mrm_get_sheet_music_subscription_by_portal_token($token);
      }
    }

    if (!$this->mrm_sheet_music_subscription_is_manageable($sub)) {
      wp_die(
        'This subscription is no longer active or has already been scheduled for cancellation. If you need help, please contact Low Brass Lessons.',
        'Subscription Not Active',
        array('response' => 403)
      );
    }

    $portal = $this->stripe_create_billing_portal_session(
      (string)$sub['stripe_customer_id'],
      home_url('/contact/')
    );

    if (is_wp_error($portal) || empty($portal['url'])) {
      wp_die('Unable to open subscription portal right now.', 'Subscription Portal', array('response' => 500));
    }

    wp_redirect((string)$portal['url']);
    exit;
  }



  public function rest_validate_promo(WP_REST_Request $req) {
    $data = (array)$req->get_json_params();

    $code = $this->mrm_normalize_promo_code($data['promo_code'] ?? '');
    $email = sanitize_email((string)($data['email'] ?? ''));
    $sku = $this->sanitize_sku($data['sku'] ?? '');
    $context = isset($data['context']) && is_array($data['context']) ? $data['context'] : array();

    if ($sku === '') {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Missing SKU.',
      ), 400);
    }

    $resolved_sku = $this->mrm_resolve_active_product_sku($sku, $context);
    if ($resolved_sku !== '') {
      $sku = $resolved_sku;
    }

    $product = $this->get_product($sku);
    if (!$product || empty($product['active'])) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Unknown or inactive product.',
      ), 404);
    }

    $context['sku'] = $sku;
    $context['product_type'] = sanitize_key((string)($product['product_type'] ?? 'unknown'));
    $context['product_category'] = sanitize_key((string)($product['category'] ?? ''));

    $fundamentals_requested = isset($data['fundamentals_addon']) && strtolower((string)$data['fundamentals_addon']) === 'yes';
    $fundamentals_addon = $this->mrm_resolve_fundamentals_addon_selection($sku, $fundamentals_requested, $email);
    if (is_wp_error($fundamentals_addon)) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => $fundamentals_addon->get_error_code(),
        'message' => $fundamentals_addon->get_error_message(),
      ), $fundamentals_addon->get_error_code() === 'fundamentals_addon_already_owned' ? 409 : 400);
    }
    $fundamentals_addon_amount_cents = !empty($fundamentals_addon['selected']) ? max(0, (int)($fundamentals_addon['offer_amount_cents'] ?? 0)) : 0;
    $context['fundamentals_addon_selected'] = !empty($fundamentals_addon['selected']);
    $context['fundamentals_addon_amount_cents'] = $fundamentals_addon_amount_cents;
    $context['non_discountable_amount_cents'] = $fundamentals_addon_amount_cents;

    $base_amount_cents = (int)($product['amount_cents'] ?? 0);

    $lesson_count = isset($context['lesson_count']) ? max(1, absint($context['lesson_count'])) : 1;
    $prepay = isset($context['prepay']) ? strtolower((string)$context['prepay']) : 'no';

    if ((string)($product['product_type'] ?? '') === 'lesson' && $prepay === 'yes' && $lesson_count > 1) {
      $base_amount_cents = $base_amount_cents * $lesson_count;
    }

    $result = $this->mrm_validate_promo_for_purchase(
      $code,
      $email,
      (string)($product['product_type'] ?? 'unknown'),
      $base_amount_cents,
      $context
    );

    if (empty($result['ok'])) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => (string)($result['message'] ?? 'Invalid promotional code.'),
      ), 400);
    }

    $promo = isset($result['promo']) && is_array($result['promo']) ? $result['promo'] : array();

    $discount_type = (string)($promo['discount_type'] ?? 'percent');
    $percent_off = max(0, min(100, (int)($promo['percent_off'] ?? 0)));
    $amount_off_cents = max(0, (int)($promo['amount_off_cents'] ?? 0));
    $discount_cents = max(0, (int)($result['discount_cents'] ?? 0));

    if ($discount_type === 'amount') {
      $promo_success_message = 'Code applied: $' . number_format($discount_cents / 100, 2) . ' off.';
    } else {
      $promo_success_message = 'Code applied: ' . $percent_off . '% promotional discount applied.';
    }

    return new WP_REST_Response(array(
      'ok' => true,
      'message' => 'Promotional code applied.',
      'promo_code' => $code,
      'discount_cents' => $discount_cents,
      'discount_display' => '$' . number_format($discount_cents / 100, 2),
      'discount_type' => $discount_type,
      'percent_off' => $percent_off,
      'amount_off_cents' => $amount_off_cents,
      'promo_success_message' => $promo_success_message,
    ), 200);
  }

  public function rest_quote(WP_REST_Request $req) {
  $request_id = 'quote_' . gmdate('Ymd_His') . '_' . wp_generate_password(8, false, false);

  try {
    $raw_params = $req->get_params();

    $sku = $this->sanitize_sku($req->get_param('sku'));
    $browser_session_id = $this->mrm_sanitize_piece_browser_session_id($req->get_param('browser_session_id'));

    $context = array(
      'piece_slug' => sanitize_text_field((string)$req->get_param('piece_slug')),
      'type' => sanitize_text_field((string)$req->get_param('type')),
      'display_title' => sanitize_text_field((string)$req->get_param('display_title')),
      'subtitle' => sanitize_text_field((string)$req->get_param('subtitle')),
    );

    $this->mrm_quote_debug_log('quote_start', array(
      'request_id' => $request_id,
      'raw_params' => $raw_params,
      'sanitized_sku' => $sku,
      'context' => $context,
      'request_uri' => isset($_SERVER['REQUEST_URI']) ? sanitize_text_field((string)$_SERVER['REQUEST_URI']) : '',
      'referer' => isset($_SERVER['HTTP_REFERER']) ? esc_url_raw((string)$_SERVER['HTTP_REFERER']) : '',
    ));

    if (!$sku) {
      $this->mrm_quote_debug_log('quote_fail_missing_sku', array(
        'request_id' => $request_id,
      ));

      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Some payment details were missing. Please refresh and try again.',
      ), 400);
    }

    $resolved_sku = $this->mrm_resolve_active_product_sku($sku, $context);

    $this->mrm_quote_debug_log('quote_after_resolver', array(
      'request_id' => $request_id,
      'incoming_sku' => $sku,
      'resolved_sku' => $resolved_sku,
    ));

    if ($resolved_sku !== '') {
      $sku = $resolved_sku;
    }

    $p = $this->get_product($sku);

    $this->mrm_quote_debug_log('quote_product_lookup', array(
      'request_id' => $request_id,
      'lookup_sku' => $sku,
      'product_exists' => is_array($p),
      'product' => $this->mrm_quote_debug_product_summary($p),
      'nearby_products' => is_array($p) ? array() : $this->mrm_quote_debug_nearby_product_keys($sku),
    ));

    if (!$p) {
      $this->mrm_quote_debug_log('quote_fail_unknown_sku', array(
        'request_id' => $request_id,
        'lookup_sku' => $sku,
        'original_requested_sku' => $this->sanitize_sku($req->get_param('sku')),
      ));

      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This purchase option is not available. Please refresh and try again.',
        'requested_sku' => $this->sanitize_sku($req->get_param('sku')),
        'lookup_sku' => $sku,
      ), 404);
    }

    if (empty($p['active'])) {
      $this->mrm_quote_debug_log('quote_fail_inactive_sku', array(
        'request_id' => $request_id,
        'lookup_sku' => $sku,
        'product' => $this->mrm_quote_debug_product_summary($p),
      ));

      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This purchase option is not currently available.',
        'lookup_sku' => $sku,
      ), 404);
    }

    $amount_cents = isset($p['amount_cents']) ? (int)$p['amount_cents'] : 0;
    $currency = strtolower((string)($p['currency'] ?? 'usd'));
    $price_id = isset($p['stripe_price_id']) ? trim((string)$p['stripe_price_id']) : '';
    $product_type = (string)($p['product_type'] ?? '');
    $product_category = (string)($p['category'] ?? '');
    $subscription_status_token_data = array('token' => '', 'expires_at' => 0);
    if (sanitize_key($product_type) === 'sheet_music') {
      if ($browser_session_id === '') {
        return new WP_REST_Response(array(
          'ok' => false,
          'code' => 'piece_browser_session_required',
          'message' => 'The sheet-music checkout session could not be initialized. Please refresh the page and try again.',
        ), 400);
      }
      $subscription_status_token_data = $this->mrm_issue_piece_subscription_status_token($sku, $browser_session_id);
      if (is_wp_error($subscription_status_token_data)) {
        return new WP_REST_Response(array(
          'ok' => false,
          'code' => $subscription_status_token_data->get_error_code(),
          'message' => $subscription_status_token_data->get_error_message(),
        ), 500);
      }
    }

    $this->mrm_quote_debug_log('quote_product_config', array(
      'request_id' => $request_id,
      'sku' => $sku,
      'amount_cents' => $amount_cents,
      'currency' => $currency,
      'price_id_present' => $price_id !== '',
      'product_type' => $product_type,
      'product_category' => $product_category,
    ));

    $is_inperson_lesson =
      ($product_type === 'lesson') &&
      (
        strpos($product_category, 'inperson') !== false ||
        strpos($sku, 'inperson') !== false
      );

    $travel_amount_cents = $is_inperson_lesson ? $this->mrm_get_in_person_travel_cents() : 0;

    if ($travel_amount_cents > $amount_cents) {
      $travel_amount_cents = $amount_cents;
    }

    $base_amount_cents = max(0, $amount_cents - $travel_amount_cents);

    if ($amount_cents <= 0) {
      $this->mrm_quote_debug_log('quote_fail_pricing_not_configured', array(
        'request_id' => $request_id,
        'sku' => $sku,
        'amount_cents' => $amount_cents,
        'product' => $this->mrm_quote_debug_product_summary($p),
      ));

      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Pricing is temporarily unavailable for this purchase option.',
        'lookup_sku' => $sku,
        'amount_cents' => $amount_cents,
      ), 500);
    }

    if (!$currency) {
      $this->mrm_quote_debug_log('quote_fail_currency_not_configured', array(
        'request_id' => $request_id,
        'sku' => $sku,
        'currency' => $currency,
        'product' => $this->mrm_quote_debug_product_summary($p),
      ));

      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Payment settings are temporarily unavailable for this purchase option.',
        'lookup_sku' => $sku,
      ), 500);
    }

    $preview_address = array(
      'country' => strtoupper((string)($req->get_param('country') ?? 'US')),
      'state' => (string)($req->get_param('state') ?? ''),
      'postal_code' => (string)($req->get_param('postal_code') ?? ''),
      'line1' => (string)($req->get_param('line1') ?? ''),
    );

    $this->mrm_quote_debug_log('quote_before_tax_preview', array(
      'request_id' => $request_id,
      'sku' => $sku,
      'preview_address' => $preview_address,
    ));

    $preview_policy = $this->mrm_build_tax_policy(
      $preview_address,
      (string)($p['product_type'] ?? 'unknown'),
      false,
      $p,
      array(
        'allow_incomplete_address' => true,
        'source_flow' => 'quote_preview',
        'sku' => $sku,
      )
    );

    if ($preview_policy instanceof WP_REST_Response) {
      $this->mrm_quote_debug_log('quote_preview_policy_unexpected_response_object', array(
        'request_id' => $request_id,
        'sku' => $sku,
        'status' => $preview_policy->get_status(),
        'data' => $preview_policy->get_data(),
      ));

      $preview_policy = array(
        'ok' => true,
        'policy_reason' => 'quote_preview_policy_response_object_converted',
        'policy_message' => 'Sales tax is calculated after billing state and ZIP are entered.',
        'should_collect_tax' => false,
        'jurisdiction' => array(
          'country' => (string)($preview_address['country'] ?? 'US'),
          'state' => (string)($preview_address['state'] ?? ''),
        ),
      );
    }

    if (!is_array($preview_policy)) {
      $this->mrm_quote_debug_log('quote_preview_policy_unexpected_type', array(
        'request_id' => $request_id,
        'sku' => $sku,
        'preview_policy_type' => gettype($preview_policy),
      ));

      $preview_policy = array(
        'ok' => true,
        'policy_reason' => 'quote_preview_policy_unexpected_type',
        'policy_message' => 'Sales tax is calculated after billing state and ZIP are entered.',
        'should_collect_tax' => false,
        'jurisdiction' => array(
          'country' => (string)($preview_address['country'] ?? 'US'),
          'state' => (string)($preview_address['state'] ?? ''),
        ),
      );
    }

    $fundamentals_addon_offer =
      $this->mrm_get_fundamentals_addon_offer(
        $sku
      );

    $response = array(
      'ok' => true,

      'sku' =>
        $sku,

      'label' =>
        (string)($p['label'] ?? $sku),

      'amount_cents' =>
        $amount_cents,

      'base_amount_cents' =>
        $base_amount_cents,

      'travel_amount_cents' =>
        $travel_amount_cents,

      'currency' =>
        $currency,

      'subscription_status_token' =>
        sanitize_text_field((string)($subscription_status_token_data['token'] ?? '')),

      'subscription_status_token_expires_at' =>
        max(0, (int)($subscription_status_token_data['expires_at'] ?? 0)),

      /*
       * The frontend reads this information to decide whether the
       * Full Piece banner and checkout checkbox should be shown.
       */
      'optional_addons' => array(
        'fundamentals_packet' =>
          $fundamentals_addon_offer,
      ),

      'tax_pending' =>
        true,

      'tax_message' =>
        (string)(
          $preview_policy['policy_message'] ??
          'Sales tax is calculated after billing state and ZIP are entered.'
        ),

      'tax_policy_preview' => array(
        'policy_reason' =>
          (string)(
            $preview_policy['policy_reason'] ??
            ''
          ),

        'should_collect_tax' =>
          !empty(
            $preview_policy[
              'should_collect_tax'
            ]
          ),

        'state' =>
          (string)(
            $preview_policy[
              'jurisdiction'
            ]['state'] ?? ''
          ),

        'country' =>
          (string)(
            $preview_policy[
              'jurisdiction'
            ]['country'] ?? 'US'
          ),
      ),

      'price_id' =>
        $price_id
          ? $price_id
          : null,
    );

    $this->mrm_quote_debug_log(
      'quote_success',
      array(
        'request_id' =>
          $request_id,

        'response_summary' => array(
          'sku' =>
            $response['sku'],

          'amount_cents' =>
            $response['amount_cents'],

          'currency' =>
            $response['currency'],

          'label' =>
            $response['label'],

          'fundamentals_addon_available' =>
            !empty(
              $fundamentals_addon_offer[
                'available'
              ]
            ),

          'fundamentals_addon_sku' =>
            (string)(
              $fundamentals_addon_offer[
                'sku'
              ] ?? ''
            ),

          'fundamentals_addon_amount_cents' =>
            (int)(
              $fundamentals_addon_offer[
                'offer_amount_cents'
              ] ?? 0
            ),
        ),
      )
    );

    return new WP_REST_Response($response, 200);

  } catch (Throwable $e) {
    $this->mrm_quote_debug_log('quote_exception', array(
      'request_id' => $request_id,
      'message' => $e->getMessage(),
      'file' => $e->getFile(),
      'line' => $e->getLine(),
      'trace' => $e->getTraceAsString(),
    ));

    return new WP_REST_Response(array(
      'ok' => false,
      'message' => 'We could not prepare this payment. Please refresh and try again.',
    ), 500);
  }
}


  private function resolve_sheet_music_sku($piece_slug, $type) {
    $piece_slug = $this->slugify((string)$piece_slug);

    $type = strtolower(trim((string)$type));
    $allowed = array('fundamentals','trombone-euphonium','tuba','complete-package');
    if (!in_array($type, $allowed, true)) return null;

    $base = 'piece-' . $piece_slug . '-' . $type;

    $all = $this->all_products();

    // Exact match first
    if (isset($all[$base]) && is_array($all[$base]) && !empty($all[$base]['active'])) {
      return $base;
    }

    // Fall back to any numeric-suffix SKU the hub may have generated
    for ($i = 2; $i <= 999; $i++) {
      $candidate = $base . '-' . $i;
      if (isset($all[$candidate]) && is_array($all[$candidate]) && !empty($all[$candidate]['active'])) {
        return $candidate;
      }
    }

    return null;
  }

  public function rest_resolve(WP_REST_Request $req) {
    $piece_slug = (string)$req->get_param('piece_slug');
    $type = (string)$req->get_param('type');

    if (!$piece_slug) return new WP_REST_Response(array('ok'=>false,'message'=>'Missing piece_slug.'), 400);
    if (!$type) return new WP_REST_Response(array('ok'=>false,'message'=>'Missing type.'), 400);

    $sku = $this->resolve_sheet_music_sku($piece_slug, $type);
    if (!$sku) return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This offer is temporarily unavailable. Please contact Low Brass Lessons for assistance.',
      ), 404);

    $p = $this->get_product($sku);
    $fundamentals_addon_offer = $this->mrm_get_fundamentals_addon_offer($sku);
    return new WP_REST_Response(array(
      'ok' => true,
      'sku' => $sku,
      'label' => (string)($p['label'] ?? $sku),
      'amount_cents' => (int)($p['amount_cents'] ?? 0),
      'currency' => (string)($p['currency'] ?? 'usd'),
      'product_type' => (string)($p['product_type'] ?? 'unknown'),
      'optional_addons' => array('fundamentals_packet'=>$fundamentals_addon_offer),
    ), 200);
  }

  public function rest_tax_preview(WP_REST_Request $req) {
    $data = (array) $req->get_json_params();
    $exemption_check = $this->mrm_tax_reject_unsupported_exemption_claim($data);
    if (is_wp_error($exemption_check)) return new WP_REST_Response(array('ok'=>false,'code'=>$exemption_check->get_error_code(),'message'=>$exemption_check->get_error_message()), 400);

    $readiness = $this->mrm_tax_live_checkout_readiness();
    $readiness_response = $this->mrm_tax_customer_readiness_response($readiness);
    if ($readiness_response) return $readiness_response;

    $sku = $this->sanitize_sku($data['sku'] ?? '');
    $email = sanitize_email((string)($data['email'] ?? ''));
    $context = isset($data['context']) && is_array($data['context']) ? $data['context'] : array();

    if (!$sku) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This offer is temporarily unavailable. Please contact Low Brass Lessons for assistance.',
      ), 400);
    }

    $resolved_sku = $this->mrm_resolve_active_product_sku($sku, $context);
    if ($resolved_sku !== '') {
      $sku = $resolved_sku;
    }

    $p = $this->get_product($sku);
    if (!$p || empty($p['active'])) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This offer is temporarily unavailable. Please contact Low Brass Lessons for assistance.',
      ), 404);
    }

    $product_type = (string)($p['product_type'] ?? 'unknown');
    $context['sku'] = $sku;
    $context['product_type'] = sanitize_key($product_type);
    $context['product_category'] = sanitize_key((string)($p['category'] ?? ''));
    $sheet_music_addon_requested = isset($data['sheet_music_addon']) && strtolower((string)$data['sheet_music_addon']) === 'yes';

    /* The monthly sheet-music subscription add-on belongs only to lesson checkout. */
    if ($sheet_music_addon_requested && $product_type !== 'lesson') {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => 'sheet_music_subscription_addon_not_supported',
        'message' => 'The monthly sheet-music subscription add-on is available only with a lesson purchase.',
      ), 400);
    }

    /* Reject blocked sheet-music emails during preview once a valid email is present. */
    if (
      $email && is_email($email) &&
      ($product_type === 'sheet_music' || $sheet_music_addon_requested) &&
      $this->mrm_sheet_music_email_is_blocked($email)
    ) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => 'sheet_music_email_blocked',
        'message' => 'This email is currently restricted from purchasing or accessing sheet music.',
      ), 403);
    }

    $amount = (int)($p['amount_cents'] ?? 0);
    $currency = (string)($p['currency'] ?? 'usd');
    $base_amount = (int)$amount;

    if ($base_amount <= 0) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Invalid product price.',
      ), 400);
    }

    $lesson_count = isset($context['lesson_count']) ? absint($context['lesson_count']) : 0;
    $prepay_flag = isset($context['prepay']) ? strtolower((string)$context['prepay']) : 'no';
    $override = isset($data['amount_override_cents']) ? absint($data['amount_override_cents']) : 0;

    if ($prepay_flag === 'yes' && $lesson_count > 1) {
      $expected = $base_amount * $lesson_count;

      if ($override > 0 && $override !== $expected) {
        return new WP_REST_Response(array(
          'ok' => false,
          'message' => 'Prepay total mismatch. Please refresh and try again.',
        ), 400);
      }

      $amount = $override > 0 ? $override : $expected;
    } elseif ($override > 0) {
      $max = $base_amount * 50;

      if ($override >= $base_amount && $override <= $max) {
        $amount = $override;
      } else {
        return new WP_REST_Response(array(
          'ok' => false,
          'message' => 'Invalid override amount.',
        ), 400);
      }
    }

    $addon_selected = $sheet_music_addon_requested;
    $fundamentals_requested = isset($data['fundamentals_addon']) && strtolower((string)$data['fundamentals_addon']) === 'yes';
    /*
     * Tax preview calculates the selected order without mutating the
     * customer's selection based on ownership. Ownership is enforced when
     * the Payment Intent is created immediately before charging.
     */
    $fundamentals_addon = $this->mrm_resolve_fundamentals_addon_selection($sku, $fundamentals_requested, '');
    if (is_wp_error($fundamentals_addon)) return new WP_REST_Response(array('ok'=>false,'code'=>$fundamentals_addon->get_error_code(),'message'=>$fundamentals_addon->get_error_message()), $fundamentals_addon->get_error_code()==='fundamentals_addon_already_owned'?409:400);
    $fundamentals_selected = !empty($fundamentals_addon['selected']);
    $fundamentals_addon_amount_cents = $fundamentals_selected ? max(0,(int)($fundamentals_addon['offer_amount_cents']??0)) : 0;

    $address = (isset($data['address']) && is_array($data['address'])) ? $data['address'] : array();
    $address = $this->mrm_normalize_tax_address($address);

    $base_amount_cents = (int)$amount;
    $original_base_amount_cents = $base_amount_cents;
    $addon_amount_cents = $addon_selected ? 500 : 0;

    $context['fundamentals_addon_selected'] = $fundamentals_selected;
    $context['fundamentals_addon_amount_cents'] = $fundamentals_addon_amount_cents;
    $context['non_discountable_amount_cents'] = $addon_amount_cents + $fundamentals_addon_amount_cents;

    $promo_code = $this->mrm_normalize_promo_code($data['promo_code'] ?? '');
    $promo_discount_cents = 0;
    $promo_validation = null;

    if ($promo_code !== '') {
      if (!$email || !is_email($email)) {
        return new WP_REST_Response(array(
          'ok' => false,
          'code' => 'email_required_for_promo_tax_preview',
          'message' => 'Please enter a valid email address before previewing tax with this promotional code.',
        ), 400);
      }

      $promo_validation = $this->mrm_validate_promo_for_purchase(
        $promo_code,
        $email,
        $product_type,
        $base_amount_cents,
        $context
      );

      if (empty($promo_validation['ok'])) {
        return new WP_REST_Response(array(
          'ok' => false,
          'code' => !empty($promo_validation['code']) ? sanitize_key((string)$promo_validation['code']) : 'invalid_promo_code',
          'message' => (string)($promo_validation['message'] ?? 'Invalid promotional code.'),
        ), 400);
      }

      $promo_discount_cents = max(0, (int)($promo_validation['discount_cents'] ?? 0));
      $base_amount_cents = max(0, $base_amount_cents - $promo_discount_cents);
    }

    $lesson_mode = sanitize_key($context['lesson_mode'] ?? '');
    if ($product_type === 'lesson' && $lesson_mode !== 'online') {
      $performance_location_id = $this->mrm_get_instructor_performance_location_id(absint($context['instructor_id'] ?? 0));
      if ($performance_location_id === '') return new WP_REST_Response(array('ok'=>false,'code'=>'performance_location_required','message'=>'This in-person lesson location is not yet configured for tax calculation.'), 409);
      $context['stripe_tax_performance_location_id'] = $performance_location_id;
    }

    $tax_policy = $this->mrm_build_tax_policy($address, $product_type, $addon_selected, $p, $context);

    if ($tax_policy instanceof WP_REST_Response) {
      return $tax_policy;
    }

    if (is_array($tax_policy) && empty($tax_policy['ok']) && !empty($tax_policy['code'])) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => (string)($tax_policy['code'] ?? 'tax_policy_failed'),
        'message' => (string)($tax_policy['message'] ?? 'Billing address is required before checkout.'),
        'missing_address_fields' => (array)($tax_policy['missing_address_fields'] ?? array()),
      ), 400);
    }

    if (!is_array($tax_policy)) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => 'tax_policy_invalid_response',
        'message' => 'Unable to validate tax policy for this checkout.',
      ), 500);
    }

    $taxable_items = $this->mrm_build_taxable_items_from_policy($tax_policy, $base_amount_cents, $addon_amount_cents, $fundamentals_addon_amount_cents);
    if (is_wp_error($taxable_items)) return new WP_REST_Response(array('ok'=>false,'code'=>$taxable_items->get_error_code(),'message'=>$taxable_items->get_error_message()), 500);
    $tax_result = $this->mrm_tax_calculate_for_items($address, $taxable_items, $currency);
    if (is_wp_error($tax_result)) return new WP_REST_Response(array('ok'=>false,'code'=>$tax_result->get_error_code(),'message'=>$tax_result->get_error_message()), 503);
    $tax_cents = (int)$tax_result['tax_cents'];
    $tax_calc_id = sanitize_text_field($tax_result['calculation_id']);
    $tax_message = $this->mrm_build_tax_display_message($tax_policy, $tax_result, $tax_cents);
    $final_amount_cents = (int)$tax_result['amount_total_cents'];

    return new WP_REST_Response(array(
      'ok' => true,
      'sku' => $sku,
      'label' => (string)($p['label'] ?? $sku),
      'amount_cents' => $final_amount_cents,
      'total_cents' => $final_amount_cents,
      'original_base_amount_cents' => $original_base_amount_cents,
      'base_amount_cents' => $base_amount_cents,
      'addon_amount_cents' => $addon_amount_cents,
      'fundamentals_addon_selected' => $fundamentals_selected,
      'fundamentals_addon_sku' => $fundamentals_selected ? (string)$fundamentals_addon['sku'] : '',
      'fundamentals_addon_label' => $fundamentals_selected ? (string)$fundamentals_addon['label'] : '',
      'fundamentals_addon_amount_cents' => $fundamentals_addon_amount_cents,
      'fundamentals_addon_regular_amount_cents' => (int)($fundamentals_addon['regular_amount_cents'] ?? 0),
      'optional_addons' => array('fundamentals_packet'=>$fundamentals_addon),
      'promo_code' => $promo_code,
      'promo_discount_cents' => $promo_discount_cents,
      'tax_cents' => $tax_cents,
      'tax_message' => (string)$tax_message,
      'tax_calculation_id' => $tax_calc_id,
      'tax_calculated' => true,
      'tax_ready' => true,
      'currency' => $currency,
      'product_type' => $product_type,
      'tax_policy' => array(
        'policy_reason' => (string)($tax_policy['policy_reason'] ?? ''),
        'should_collect_tax' => !empty($tax_policy['should_collect_tax']),
        'state' => (string)($tax_policy['jurisdiction']['state'] ?? ''),
        'country' => (string)($tax_policy['jurisdiction']['country'] ?? 'US'),
        'stripe_controls_rollout' => true,
      ),
    ), 200);
  }

  public function rest_sheet_music_purchase_subscription_status(WP_REST_Request $req) {
    $data = (array)$req->get_json_params();
    $email = strtolower(sanitize_email((string)($data['email'] ?? '')));
    $sku = $this->sanitize_sku((string)($data['sku'] ?? ''));
    $checkout_status_token = sanitize_text_field((string)($data['checkout_status_token'] ?? ''));
    $browser_session_id = $this->mrm_sanitize_piece_browser_session_id($data['browser_session_id'] ?? '');

    if (!$email || !is_email($email) || !$sku) {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'sheet_music_subscription_status_request_invalid', 'message'=>'A valid sheet-music product and email are required.'), 400);
    }

    $product = $this->get_product($sku);
    if (!is_array($product) || empty($product['active']) || sanitize_key((string)($product['product_type'] ?? '')) !== 'sheet_music') {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'sheet_music_subscription_status_product_invalid', 'message'=>'The selected sheet-music product is unavailable.'), 404);
    }

    $token_validation = $this->mrm_validate_piece_subscription_status_token($checkout_status_token, $sku, $browser_session_id);
    if (is_wp_error($token_validation)) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => $token_validation->get_error_code(),
        'message' => $token_validation->get_error_message(),
      ), 403);
    }

    $rate_limit_result = $this->mrm_check_piece_subscription_status_rate_limit($email, $sku);
    if (is_wp_error($rate_limit_result)) {
      $rate_data = $rate_limit_result->get_error_data();
      $rate_data = is_array($rate_data) ? $rate_data : array();
      $retry_after = max(1, (int)($rate_data['retry_after'] ?? 600));
      $response = new WP_REST_Response(array(
        'ok' => false,
        'code' => $rate_limit_result->get_error_code(),
        'message' => $rate_limit_result->get_error_message(),
        'retry_after' => $retry_after,
      ), 429);
      $response->header('Retry-After', (string)$retry_after);
      return $response;
    }

    if ($this->mrm_sheet_music_email_is_blocked($email)) {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'sheet_music_email_blocked', 'message'=>'This email is currently restricted from purchasing or accessing sheet music.'), 403);
    }

    $subscription_status = $this->mrm_get_sheet_music_subscription_access_status_by_email($email, true);
    if (is_wp_error($subscription_status)) return $this->mrm_checkout_wp_error_response($subscription_status, 503);
    $notice_required = is_array($subscription_status) && !empty($subscription_status['has_access']);

    return new WP_REST_Response(array(
      'ok' => true,
      'notice_required' => $notice_required,
      'active_subscription' => $notice_required,
      'subscription_status' => sanitize_key((string)($subscription_status['status'] ?? '')),
      'message' => $notice_required ? 'We notice you currently have an active subscription to access all the pieces in our catalog. Are you sure you want to make this purchase?' : '',
    ), 200);
  }

  public function rest_preconfirm_piece_payment(WP_REST_Request $req) {
    $data = (array)$req->get_json_params();
    $payment_intent_id = sanitize_text_field((string)($data['payment_intent_id'] ?? ''));
    $checkout_request_id = $this->mrm_sanitize_checkout_request_id($data['checkout_request_id'] ?? '');
    $email = strtolower(sanitize_email((string)($data['email'] ?? '')));
    $sku = $this->sanitize_sku((string)($data['sku'] ?? ''));
    $context = isset($data['context']) && is_array($data['context']) ? $data['context'] : array();
    $terms_version = sanitize_text_field((string)($context['terms_version'] ?? ''));
    $terms_accepted = !empty($context['terms_accepted']);
    $source_flow = sanitize_key((string)($context['source_flow'] ?? 'piece_product_purchase'));

    if ($payment_intent_id === '' || strpos($payment_intent_id, 'pi_') !== 0 || $checkout_request_id === '' || $email === '' || !is_email($email) || $sku === '') {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'piece_preconfirm_request_invalid', 'message'=>'The payment session is incomplete. Please close checkout and begin again.'), 400);
    }
    if (!$terms_accepted || $source_flow !== 'piece_product_purchase') {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'piece_preconfirm_terms_invalid', 'message'=>'Please review and accept the Terms of Service before payment.'), 409);
    }

    $order = $this->get_order_by_pi($payment_intent_id);
    if (!is_array($order) || empty($order['id'])) {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'piece_preconfirm_order_missing', 'message'=>'The payment order could not be found. Please close checkout and begin again.'), 404);
    }
    if (sanitize_key((string)($order['product_type'] ?? '')) !== 'sheet_music') {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'piece_preconfirm_product_invalid', 'message'=>'This payment session is not a sheet-music purchase.'), 409);
    }

    $email_hash = $this->email_hash($email);
    $incoming_state_fingerprint = $this->mrm_build_piece_checkout_state_fingerprint(
      $checkout_request_id, $email_hash, $sku, $data, $context, $terms_version, $source_flow
    );
    $state_validation = $this->mrm_validate_existing_piece_checkout_state($order, $email_hash, $sku, $incoming_state_fingerprint);
    if (is_wp_error($state_validation)) {
      return $this->mrm_checkout_wp_error_response($state_validation, 409);
    }

    $payment_intent = $this->stripe_retrieve_payment_intent($payment_intent_id);
    if (is_wp_error($payment_intent)) {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'piece_preconfirm_stripe_failed', 'message'=>'We could not revalidate the secure payment session. No payment has been submitted. Please try again.'), 503);
    }
    $payment_status = sanitize_key((string)($payment_intent['status'] ?? ''));
    if ($payment_status === 'succeeded') {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'checkout_request_already_completed', 'message'=>'This checkout request has already been paid.'), 409);
    }
    if ($payment_status === 'canceled') {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'checkout_payment_intent_unusable', 'message'=>'This payment session is no longer usable. Please close checkout and begin again.'), 409);
    }
    if (!in_array($payment_status, array('requires_payment_method', 'requires_confirmation', 'requires_action'), true)) {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'piece_preconfirm_status_invalid', 'message'=>'The payment session is not currently ready for confirmation.'), 409);
    }

    /* Recheck blocking immediately before Stripe is allowed to confirm payment. */
    if ($this->mrm_sheet_music_email_is_blocked($email)) {
      $cancel_result = $this->mrm_cancel_pending_piece_checkout(
        $order,
        $payment_intent,
        'sheet_music_email_blocked'
      );
      if (is_wp_error($cancel_result)) {
        return $this->mrm_checkout_wp_error_response($cancel_result, 503);
      }
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => 'sheet_music_email_blocked',
        'message' => 'This email is currently restricted from purchasing or accessing sheet music. The payment session has been canceled.',
      ), 403);
    }

    $subscription_purchase_check = $this->mrm_validate_sheet_music_subscription_purchase_acknowledgement($email, $context);
    if (is_wp_error($subscription_purchase_check)) {
      /* Keep the Payment Intent usable while the frontend collects acknowledgement. */
      return $this->mrm_checkout_wp_error_response($subscription_purchase_check, 409);
    }

    $order_metadata = $this->mrm_get_order_meta_array($order);
    $payment_metadata = isset($payment_intent['metadata']) && is_array($payment_intent['metadata']) ? $payment_intent['metadata'] : array();
    $stored_request_id = $this->mrm_sanitize_checkout_request_id($order_metadata['mrm_checkout_request_id'] ?? '');
    $payment_request_id = $this->mrm_sanitize_checkout_request_id($payment_metadata['mrm_checkout_request_id'] ?? '');
    $payment_sku = $this->sanitize_sku((string)($payment_metadata['mrm_sku'] ?? ''));
    $payment_order_id = absint($payment_metadata['mrm_order_id'] ?? 0);
    $order_total = max(0, (int)($order_metadata['mrm_total_cents'] ?? $order['amount_cents'] ?? 0));
    $payment_total = max(0, (int)($payment_intent['amount'] ?? 0));
    if ($stored_request_id === '' || $payment_request_id === '' || !hash_equals($stored_request_id, $checkout_request_id) || !hash_equals($payment_request_id, $checkout_request_id) || $payment_sku !== $sku || $payment_order_id !== absint($order['id']) || $order_total <= 0 || $payment_total !== $order_total) {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'piece_preconfirm_snapshot_mismatch', 'message'=>'The payment amount or product details changed. Please close checkout and begin again.'), 409);
    }

    $acknowledgement_result = $this->mrm_persist_sheet_music_subscription_purchase_acknowledgement($order, $payment_intent, $subscription_purchase_check);
    if (is_wp_error($acknowledgement_result)) return $this->mrm_checkout_wp_error_response($acknowledgement_result, 503);

    /* Reload only after the complete order/Payment Intent relationship is valid. */
    if (!empty($subscription_purchase_check['active_subscription']) && !empty($subscription_purchase_check['acknowledged'])) {
      $fresh_order = $this->get_order(absint($order['id']));
      if (is_array($fresh_order)) {
        $order = $fresh_order;
        $order_metadata = $this->mrm_get_order_meta_array($order);
      }
    }

    if ($this->mrm_email_already_has_piece_or_package_access($email, $sku)) {
      $cancel_result = $this->mrm_cancel_pending_piece_checkout($order, $payment_intent, 'base_piece_already_owned');
      if (is_wp_error($cancel_result)) return $this->mrm_checkout_wp_error_response($cancel_result, 503);
      return new WP_REST_Response(array('ok'=>false, 'code'=>'already_purchased_piece_product', 'message'=>'This email already has access to this piece product. The obsolete payment session has been canceled.'), 409);
    }

    $ownership_validation = $this->mrm_validate_reused_fundamentals_ownership($order);
    if (is_wp_error($ownership_validation)) {
      if ($ownership_validation->get_error_code() === 'fundamentals_addon_already_owned') {
        $cancel_result = $this->mrm_cancel_pending_piece_checkout($order, $payment_intent, 'fundamentals_addon_already_owned');
        if (is_wp_error($cancel_result)) return $this->mrm_checkout_wp_error_response($cancel_result, 503);
      }
      return $this->mrm_checkout_wp_error_response($ownership_validation, 409);
    }

    return new WP_REST_Response(array(
      'ok'=>true,
      'payment_intent_id'=>$payment_intent_id,
      'order_id'=>absint($order['id']),
      'amount_cents'=>$payment_total,
      'fundamentals_addon_selected'=>strtolower((string)($order_metadata['mrm_fundamentals_addon'] ?? 'no')) === 'yes',
      'active_subscription'=>!empty($subscription_purchase_check['active_subscription']),
      'subscription_purchase_acknowledged'=>!empty($subscription_purchase_check['acknowledged']),
    ), 200);
  }

  public function rest_abandon_payment_intent(WP_REST_Request $req) {
    $data = (array)$req->get_json_params();
    $payment_intent_id = sanitize_text_field((string)($data['payment_intent_id'] ?? ''));
    $order_id = absint($data['order_id'] ?? 0);
    $email = sanitize_email((string)($data['email'] ?? ''));
    $checkout_request_id = $this->mrm_sanitize_checkout_request_id($data['checkout_request_id'] ?? '');
    $reason = sanitize_key((string)($data['reason'] ?? 'customer_abandoned'));
    if ($reason === '') $reason = 'customer_abandoned';
    if ($payment_intent_id === '' || strpos($payment_intent_id, 'pi_') !== 0 || $order_id <= 0 || $email === '' || !is_email($email)) {
      return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_invalid','message'=>'The payment session could not be identified safely.'), 400);
    }
    $order = $this->get_order_by_pi($payment_intent_id);
    if (!is_array($order) || empty($order['id']) || absint($order['id']) !== $order_id) {
      return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_order_mismatch','message'=>'The payment session did not match the requested order.'), 409);
    }
    $submitted_email_hash = $this->email_hash($email);
    $stored_email_hash = sanitize_text_field((string)($order['email_hash'] ?? ''));
    if ($submitted_email_hash === '' || $stored_email_hash === '' || !hash_equals($stored_email_hash, $submitted_email_hash)) {
      return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_email_mismatch','message'=>'The payment session could not be verified for this email.'), 403);
    }
    $product_type = sanitize_key((string)($order['product_type'] ?? ''));
    if (!in_array($product_type, array('lesson','sheet_music'), true)) {
      return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_product_invalid','message'=>'This payment session cannot be abandoned through this checkout flow.'), 409);
    }
    $order_metadata = $this->mrm_get_order_meta_array($order);
    if ($product_type === 'sheet_music') {
      $stored_request_id = $this->mrm_sanitize_checkout_request_id($order_metadata['mrm_checkout_request_id'] ?? '');
      if ($checkout_request_id === '' || $stored_request_id === '' || !hash_equals($stored_request_id, $checkout_request_id)) {
        return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_request_mismatch','message'=>'The sheet-music checkout request could not be verified.'), 409);
      }
    }
    $payment_intent = $this->stripe_retrieve_payment_intent($payment_intent_id);
    if (is_wp_error($payment_intent)) {
      return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_status_unavailable','message'=>'The payment status could not be confirmed, so the payment session was preserved.'), 503);
    }
    $stripe_status = sanitize_key((string)($payment_intent['status'] ?? ''));
    if (in_array($stripe_status, array('succeeded','processing','requires_capture'), true)) {
      return new WP_REST_Response(array('ok'=>false,'code'=>$stripe_status === 'succeeded' ? 'checkout_already_paid' : 'checkout_payment_status_uncertain','message'=>$stripe_status === 'succeeded' ? 'This payment has already completed and cannot be abandoned.' : 'This payment is currently being processed and cannot be abandoned safely.'), 409);
    }
    if ($stripe_status !== 'canceled') {
      if (!in_array($stripe_status, array('requires_payment_method','requires_confirmation','requires_action'), true)) {
        return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_status_invalid','message'=>'The payment session is not currently in a safely cancelable state.'), 409);
      }
      $canceled = $this->stripe_api_request('POST', '/v1/payment_intents/' . rawurlencode($payment_intent_id) . '/cancel', array('cancellation_reason'=>'abandoned'));
      if (is_wp_error($canceled)) {
        return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_cancel_failed','message'=>'The payment session could not be canceled safely, so it was preserved.'), 503);
      }
      if (sanitize_key((string)($canceled['status'] ?? '')) !== 'canceled') {
        return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_not_confirmed','message'=>'Stripe did not confirm that the payment session was canceled.'), 503);
      }
    }
    $this->update_order_status_from_pi($payment_intent_id, 'canceled', 'canceled', array('mrm_checkout_invalidated_reason'=>$reason,'mrm_checkout_invalidated_at'=>current_time('mysql')));
    if (!$this->mrm_release_pending_promo_redemption($order_id, $payment_intent_id)) {
      return new WP_REST_Response(array('ok'=>false,'code'=>'checkout_abandonment_promo_release_failed','message'=>'The payment was canceled, but its promotional-code reservation could not be released.'), 503);
    }
    return new WP_REST_Response(array('ok'=>true,'payment_intent_id'=>$payment_intent_id,'order_id'=>$order_id,'status'=>'canceled'), 200);
  }

  public function rest_create_payment_intent(WP_REST_Request $req) {
    $data = (array) $req->get_json_params();
    $exemption_check = $this->mrm_tax_reject_unsupported_exemption_claim($data);
    if (is_wp_error($exemption_check)) return new WP_REST_Response(array('ok'=>false,'code'=>$exemption_check->get_error_code(),'message'=>$exemption_check->get_error_message()), 400);

    $readiness = $this->mrm_tax_live_checkout_readiness();
    $readiness_response = $this->mrm_tax_customer_readiness_response($readiness);
    if ($readiness_response) return $readiness_response;

    $sku = $this->sanitize_sku($data['sku'] ?? '');
    $email = sanitize_email((string)($data['email'] ?? ''));
    $context = isset($data['context']) && is_array($data['context']) ? $data['context'] : array();
    $terms_accepted = ! empty( $context['terms_accepted'] );
    $terms_version  = sanitize_text_field( (string) ( $context['terms_version'] ?? '' ) );
    $source_flow    = sanitize_text_field( (string) ( $context['source_flow'] ?? '' ) );

    if (!$sku) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This offer is temporarily unavailable. Please contact Low Brass Lessons for assistance.',
      ), 400);
    }

    if (!$email || !is_email($email)) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Please enter a valid email address.',
      ), 400);
    }

    $resolved_sku = $this->mrm_resolve_active_product_sku($sku, $context);
    if ($resolved_sku !== '') {
      $sku = $resolved_sku;
    }

    $p = $this->get_product($sku);
    if (!$p || empty($p['active'])) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This offer is temporarily unavailable. Please contact Low Brass Lessons for assistance.',
      ), 404);
    }

    $product_type = (string)($p['product_type'] ?? 'unknown');
    $context['sku'] = $sku;
    $context['product_type'] = sanitize_key($product_type);
    $context['product_category'] = sanitize_key((string)($p['category'] ?? ''));
    $sheet_music_addon_requested = isset($data['sheet_music_addon']) && strtolower((string)$data['sheet_music_addon']) === 'yes';

    if ($sheet_music_addon_requested && $product_type !== 'lesson') {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => 'sheet_music_subscription_addon_not_supported',
        'message' => 'The monthly sheet-music subscription add-on is available only with a lesson purchase.',
      ), 400);
    }

    /* Block sheet-music purchases before fingerprinting, reuse, tax, or order creation. */
    if (
      ($product_type === 'sheet_music' || $sheet_music_addon_requested) &&
      $this->mrm_sheet_music_email_is_blocked($email)
    ) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => 'sheet_music_email_blocked',
        'message' => 'This email is currently restricted from purchasing or accessing sheet music.',
      ), 403);
    }

    if (in_array($product_type, array('lesson', 'sheet_music'), true) && !$terms_accepted) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Please agree to the Terms of Service before checkout.',
        'code' => 'terms_required',
      ), 400);
    }

    if ($terms_version === '') {
      $terms_version = '2026-04-25';
    }

    if ($source_flow === '') {
      $source_flow = ($product_type === 'sheet_music') ? 'piece_product_purchase' : 'lesson_booking';
    }

    $subscription_purchase_check = array(
      'active_subscription' => false,
      'acknowledged' => false,
      'subscription_status' => '',
      'subscription_id' => '',
      'subscription_reason' => '',
    );
    if ($product_type === 'sheet_music') {
      $subscription_purchase_check = $this->mrm_validate_sheet_music_subscription_purchase_acknowledgement($email, $context);
      if (is_wp_error($subscription_purchase_check)) return $this->mrm_checkout_wp_error_response($subscription_purchase_check, 409);
    }

    $checkout_request_id = $this->mrm_sanitize_checkout_request_id($data['checkout_request_id'] ?? '');
    if ($source_flow === 'piece_product_purchase' && $checkout_request_id === '') {
      return new WP_REST_Response(array('ok'=>false, 'code'=>'checkout_request_id_required', 'message'=>'Checkout could not be initialized securely. Please close the payment window and try again.'), 400);
    }


    $request_email_hash = $this->email_hash($email);
    $incoming_checkout_state_fingerprint = $checkout_request_id !== ''
      ? $this->mrm_build_piece_checkout_state_fingerprint(
          $checkout_request_id,
          $request_email_hash,
          $sku,
          $data,
          $context,
          $terms_version,
          $source_flow
        )
      : '';

    if ($product_type === 'sheet_music') {
      if ($this->mrm_email_already_has_piece_or_package_access($email, $sku)) {
        return new WP_REST_Response(array(
          'ok' => false,
          'code' => 'already_purchased_piece_product',
          'message' => 'This email already has access to this piece product. You do not need to purchase it again.',
          'already_owned' => true,
        ), 409);
      }
    }

    $checkout_lock_name = '';
    if ($checkout_request_id !== '') {
      $existing_checkout_order = $this->get_order_by_meta_value('mrm_checkout_request_id', $checkout_request_id);

      /* A completed attachment can be reused only after validating the complete client state. */
      if (is_array($existing_checkout_order) && !empty($existing_checkout_order['stripe_payment_intent_id'])) {
        $state_validation = $this->mrm_validate_existing_piece_checkout_state($existing_checkout_order, $request_email_hash, $sku, $incoming_checkout_state_fingerprint);
        if (is_wp_error($state_validation)) return new WP_REST_Response(array('ok'=>false, 'code'=>$state_validation->get_error_code(), 'message'=>$state_validation->get_error_message()), 409);
        $reused_response = $this->mrm_build_reused_checkout_response($existing_checkout_order);
        if (is_wp_error($reused_response)) {
          return $this
            ->mrm_checkout_wp_error_response(
              $reused_response,
              409
            );
        }
        return $reused_response;
      }

      $checkout_lock_result = $this->mrm_acquire_checkout_lock($checkout_request_id);
      if (is_wp_error($checkout_lock_result)) return new WP_REST_Response(array('ok'=>false, 'code'=>$checkout_lock_result->get_error_code(), 'message'=>$checkout_lock_result->get_error_message()), 409);
      $checkout_lock_name = $checkout_lock_result;
      register_shutdown_function(function() use ($checkout_lock_name) { $this->mrm_release_checkout_lock($checkout_lock_name); });

      /* Recheck after locking because an identical request may have just completed. */
      $existing_checkout_order = $this->get_order_by_meta_value('mrm_checkout_request_id', $checkout_request_id);
      if (is_array($existing_checkout_order)) {
        $state_validation = $this->mrm_validate_existing_piece_checkout_state($existing_checkout_order, $request_email_hash, $sku, $incoming_checkout_state_fingerprint);
        if (is_wp_error($state_validation)) return new WP_REST_Response(array('ok'=>false, 'code'=>$state_validation->get_error_code(), 'message'=>$state_validation->get_error_message()), 409);
        if (!empty($existing_checkout_order['stripe_payment_intent_id'])) {
          $reused_response = $this->mrm_build_reused_checkout_response($existing_checkout_order);
          if (is_wp_error($reused_response)) {
            return $this
              ->mrm_checkout_wp_error_response(
                $reused_response,
                409
              );
          }
          return $reused_response;
        }

        /* Resume the stored calculation when the prior response ended before local PI attachment. */
        $resume_response = $this->mrm_resume_unattached_piece_checkout_order($existing_checkout_order, $checkout_request_id);
        if (is_wp_error($resume_response)) {
          return $this
            ->mrm_checkout_wp_error_response(
              $resume_response,
              500
            );
        }
        return $resume_response;
      }
    }

    $amount = (int)($p['amount_cents'] ?? 0);
    $currency = (string)($p['currency'] ?? 'usd');

    $base_amount = (int)$amount;

    // Diagnostics for misconfigured products
    if ($base_amount <= 0) {
      return new WP_REST_Response(array(
        'ok'=>false,
        'message'=>'Invalid product price.',
      ), 400);
    }

    // Read scheduler intent
    $lesson_count = isset($context['lesson_count']) ? absint($context['lesson_count']) : 0;
    $prepay_flag  = isset($context['prepay']) ? strtolower((string)$context['prepay']) : 'no';

    // Optional: scheduler may request a one-time override (e.g., prepay multiple lessons).
    $override = isset($data['amount_override_cents']) ? absint($data['amount_override_cents']) : 0;

    // If prepay is enabled and count > 1, enforce exact math: override MUST equal base * count.
    // (This prevents “prepay but only paid for one”.)
    if ($prepay_flag === 'yes' && $lesson_count > 1) {
      $expected = $base_amount * $lesson_count;

      if ($override > 0 && $override !== $expected) {
        return new WP_REST_Response(array(
          'ok'=>false,
          'message'=>'Prepay total mismatch. Please refresh and try again.',
            'sku'=>$sku,
            'base_amount_cents'=>$base_amount,
            'lesson_count'=>$lesson_count,
            'expected_amount_cents'=>$expected,
            'amount_override_cents'=>$override
        ), 400);
      }

      // If frontend didn’t send override for some reason, compute it server-side
      if ($override <= 0) {
        $override = $expected;
      }

      $amount = $override;
    } else {
      // Non-prepay: accept override with reasonable bounds (existing behavior)
      if ($override > 0) {
        $max = $base_amount * 50; // generous cap
        if ($override >= $base_amount && $override <= $max) {
          $amount = $override;
        } else {
          return new WP_REST_Response(array(
            'ok'=>false,
            'message'=>'Invalid override amount.',
          ), 400);
        }
      }
    }

    $addon_selected = $sheet_music_addon_requested;
    $fundamentals_requested = isset($data['fundamentals_addon']) && strtolower((string)$data['fundamentals_addon']) === 'yes';
    $fundamentals_addon = $this->mrm_resolve_fundamentals_addon_selection($sku, $fundamentals_requested, $email);
    if (is_wp_error($fundamentals_addon)) {
      return $this->mrm_checkout_wp_error_response($fundamentals_addon, 400);
    }
    $fundamentals_selected = !empty($fundamentals_addon['selected']);
    $fundamentals_addon_amount_cents = $fundamentals_selected ? max(0,(int)($fundamentals_addon['offer_amount_cents']??0)) : 0;

    $address = (isset($data['address']) && is_array($data['address'])) ? $data['address'] : array();
    $address = $this->mrm_normalize_tax_address($address);

    $base_amount_cents = (int)$amount;
    $original_base_amount_cents = $base_amount_cents;
    $addon_amount_cents = $addon_selected ? 500 : 0;

    $context['fundamentals_addon_selected'] = $fundamentals_selected;
    $context['fundamentals_addon_amount_cents'] = $fundamentals_addon_amount_cents;
    $context['non_discountable_amount_cents'] = $addon_amount_cents + $fundamentals_addon_amount_cents;

    $promo_code = $this->mrm_normalize_promo_code($data['promo_code'] ?? '');
    $promo_discount_cents = 0;
    $promo_validation = null;

    if ($promo_code !== '') {
      $promo_validation = $this->mrm_validate_promo_for_purchase(
        $promo_code,
        $email,
        $product_type,
        $base_amount_cents,
        $context
      );

      if (empty($promo_validation['ok'])) {
        $promo_error_code = !empty($promo_validation['code'])
          ? sanitize_key((string)$promo_validation['code'])
          : 'invalid_promo_code';

        return new WP_REST_Response(array(
          'ok' => false,
          'code' => $promo_error_code,
          'message' => (string)($promo_validation['message'] ?? 'Invalid promotional code.'),
        ), 400);
      }

      $promo_discount_cents = max(0, (int)($promo_validation['discount_cents'] ?? 0));
      $base_amount_cents = max(0, $base_amount_cents - $promo_discount_cents);
    }

    $lesson_mode = sanitize_key($context['lesson_mode'] ?? '');
    if ($product_type === 'lesson' && $lesson_mode !== 'online') {
      $performance_location_id = $this->mrm_get_instructor_performance_location_id(absint($context['instructor_id'] ?? 0));
      if ($performance_location_id === '') return new WP_REST_Response(array('ok'=>false,'code'=>'performance_location_required','message'=>'This in-person lesson location is not yet configured for tax calculation.'), 409);
      $context['stripe_tax_performance_location_id'] = $performance_location_id;
    }

    $tax_policy = $this->mrm_build_tax_policy($address, $product_type, $addon_selected, $p, $context);

    if (is_array($tax_policy) && empty($tax_policy['ok']) && !empty($tax_policy['code'])) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => (string)($tax_policy['code'] ?? 'tax_policy_failed'),
        'message' => (string)($tax_policy['message'] ?? 'Billing address is required before checkout.'),
        'missing_address_fields' => (array)($tax_policy['missing_address_fields'] ?? array()),
      ), 400);
    }

    if ($tax_policy instanceof WP_REST_Response) {
      return $tax_policy;
    }

    if (!is_array($tax_policy)) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => 'tax_policy_invalid_response',
        'message' => 'Unable to validate tax policy for this checkout.',
      ), 500);
    }

    $taxable_items = $this->mrm_build_taxable_items_from_policy($tax_policy, $base_amount_cents, $addon_amount_cents, $fundamentals_addon_amount_cents);
    if (is_wp_error($taxable_items)) return new WP_REST_Response(array('ok'=>false,'code'=>$taxable_items->get_error_code(),'message'=>$taxable_items->get_error_message()), 500);
    $tax_result = $this->mrm_tax_calculate_for_items($address, $taxable_items, $currency);
    if (is_wp_error($tax_result)) return new WP_REST_Response(array('ok'=>false,'code'=>$tax_result->get_error_code(),'message'=>$tax_result->get_error_message()), 503);
    $tax_cents = (int)$tax_result['tax_cents'];
    $tax_calc_id = sanitize_text_field($tax_result['calculation_id']);
    $tax_message = $this->mrm_build_tax_display_message($tax_policy, $tax_result, $tax_cents);

    if ($tax_cents <= 0 && !empty($taxable_items)) {
      $this->stripe_debug_log('create_payment_intent tax result was zero', array(
        'sku' => $sku,
        'product_type' => $product_type,
        'tax_calculation_id' => $tax_calc_id,
        'taxability_reason' => (string)($tax_result['taxability_reason'] ?? ''),
        'policy_reason' => (string)($tax_policy['policy_reason'] ?? ''),
        'policy_message' => $tax_message,
        'address' => $address,
        'taxable_items' => $taxable_items,
      ));
    }

    $final_amount_cents = (int)$tax_result['amount_total_cents'];

    // Final safety: NEVER create PI with amount=0
    if ($final_amount_cents <= 0) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Invalid product price.'), 400);
    }

    $email_hash = $this->email_hash($email);

    // Build labels
    $metadata = $this->build_metadata($sku, $product_type, $email_hash, $context, $p);
    if ($checkout_request_id !== '') $metadata['mrm_checkout_request_id'] = $checkout_request_id;
    if ($incoming_checkout_state_fingerprint !== '') {
      $metadata['mrm_checkout_state_fingerprint'] = $incoming_checkout_state_fingerprint;
    }
    $metadata['mrm_customer_email'] = $email;
    if ( $terms_version !== '' ) {
      $metadata['mrm_terms_version'] = $terms_version;
    }
    if ( $terms_accepted ) {
      $metadata['mrm_terms_accepted'] = 'yes';
    }
    if ( $source_flow !== '' ) {
      $metadata['mrm_terms_source_flow'] = $source_flow;
    }
    if (!empty($subscription_purchase_check['active_subscription']) && !empty($subscription_purchase_check['acknowledged'])) {
      $metadata['mrm_sub_purchase_ack'] = 'yes';
      $metadata['mrm_sub_purchase_id'] = sanitize_text_field((string)($subscription_purchase_check['subscription_id'] ?? ''));
      $metadata['mrm_sub_purchase_ack_at'] = gmdate('Y-m-d\TH:i:s\Z');
    }
    $metadata['mrm_sheet_music_addon'] = $addon_selected ? 'yes' : 'no';
    $metadata['mrm_original_base_amount_cents'] = (string)$original_base_amount_cents;
    $metadata['mrm_base_amount_cents'] = (string)$base_amount_cents;
    $metadata['mrm_addon_amount_cents'] = (string)$addon_amount_cents;
    $metadata['mrm_fundamentals_addon'] = $fundamentals_selected ? 'yes' : 'no';
    $metadata['mrm_fundamentals_addon_sku'] = $fundamentals_selected ? (string)$fundamentals_addon['sku'] : '';
    $metadata['mrm_fundamentals_addon_label'] = $fundamentals_selected ? (string)$fundamentals_addon['label'] : '';
    $metadata['mrm_fundamentals_addon_amount_cents'] = (string)$fundamentals_addon_amount_cents;
    if ($promo_code !== '') {
      $metadata['mrm_promo_code'] = $promo_code;
      $metadata['mrm_promo_discount_cents'] = (string)$promo_discount_cents;
    }
    // Total tax for this order (covers sheet music base + subscription add-on, depending on product).
    $metadata['mrm_subtotal_cents'] = (string)$tax_result['subtotal_cents'];
    $metadata['mrm_tax_cents'] = (string)$tax_cents;
    $metadata['mrm_total_cents'] = (string)$final_amount_cents;
    $metadata['mrm_tax_calculation_id'] = $tax_calc_id;
    /*
     * Local WordPress order compatibility value.
     *
     * mrm_prepare_payment_intent_metadata_for_stripe() removes
     * this duplicate key from the Stripe Payment Intent while
     * preserving it in metadata_json for older local readers.
     */
    $metadata['mrm_addon_tax_cents'] = (string)$tax_cents;

    $metadata['mrm_tax_country'] = (string)($address['country'] ?? 'US');
    $metadata['mrm_tax_state'] = (string)($address['state'] ?? '');
    $metadata['mrm_tax_postal_code'] = (string)($address['postal_code'] ?? '');
    $metadata['mrm_tax_line1'] = (string)($address['line1'] ?? '');
    $metadata['mrm_tax_line2'] = (string)($address['line2'] ?? '');
    $metadata['mrm_tax_city'] = (string)($address['city'] ?? '');
    $metadata['mrm_tax_rollout_mode'] = 'stripe_only';
    $metadata['mrm_tax_calculation_requested'] = !empty($tax_policy['should_collect_tax']) ? 'yes' : 'no';
    $metadata['mrm_tax_policy_reason'] = (string)($tax_policy['policy_reason'] ?? '');
    $metadata['mrm_tax_policy_message'] = (string)$tax_message;
    $metadata['mrm_taxability_reason'] = sanitize_key($tax_result['taxability_reason'] ?? '');
    $metadata['mrm_customer_state'] = (string)$address['state'];
    $metadata['mrm_customer_country'] = (string)$address['country'];
    $metadata['mrm_tax_lines_json'] = (string)($tax_result['metadata_line_items_json'] ?? '[]');

    $checkout_fingerprint = hash('sha256', wp_json_encode(array(
      'checkout_request_id'=>$checkout_request_id, 'email_hash'=>$email_hash, 'sku'=>$sku, 'product_type'=>$product_type,
      'currency'=>strtolower($currency), 'original_base_amount_cents'=>$original_base_amount_cents, 'base_amount_cents'=>$base_amount_cents,
      'subscription_addon_cents'=>$addon_amount_cents, 'fundamentals_addon_sku'=>$fundamentals_selected ? (string)$fundamentals_addon['sku'] : '',
      'fundamentals_addon_cents'=>$fundamentals_addon_amount_cents, 'promo_code'=>$promo_code, 'promo_discount_cents'=>$promo_discount_cents,
      'tax_cents'=>$tax_cents, 'final_amount_cents'=>$final_amount_cents, 'terms_version'=>$terms_version, 'address'=>$address,
    )));
    $metadata['mrm_checkout_fingerprint'] = $checkout_fingerprint;

    // Early duplicate guard:
    // If this is a lesson checkout with the $5 sheet music add-on selected,
    // block checkout before creating the order / PaymentIntent when the email
    // already has an active Stripe-synced sheet music subscription.
    $resumable_subscription_for_checkout = array();
    if ($addon_selected && $product_type === 'lesson') {
      $existing_subscription = $this->mrm_get_active_sheet_music_subscription_by_email($email);

      if (!empty($existing_subscription['id'])) {
        $this->stripe_debug_log('create_payment_intent blocked: duplicate sheet music subscription', array(
          'email' => $email,
          'sku' => $sku,
          'product_type' => $product_type,
          'existing_subscription_id' => (string)($existing_subscription['stripe_subscription_id'] ?? ''),
          'existing_status' => (string)($existing_subscription['stripe_status'] ?? ''),
        ));

        return new WP_REST_Response(array(
          'ok' => false,
          'code' => 'already_enrolled_sheet_music_subscription',
          'message' => $this->mrm_sheet_music_duplicate_subscription_message(),
          'already_enrolled' => true,
        ), 409);
      }

      $resumable_subscription_for_checkout = $this->mrm_get_resumable_sheet_music_subscription_by_email($email);

      if (!empty($resumable_subscription_for_checkout['subscription_id'])) {
        $metadata['mrm_sheet_music_subscription_mode'] = 'resume';
        $metadata['mrm_prior_subscription_id'] = (string)$resumable_subscription_for_checkout['subscription_id'];
      }
    }

    // Create or reuse one internal order for this checkout request.
    $existing_checkout_order = $checkout_request_id !== '' ? $this->get_order_by_meta_value('mrm_checkout_request_id', $checkout_request_id) : null;
    if (is_array($existing_checkout_order)) {
      if (!$this->mrm_checkout_order_matches_customer($existing_checkout_order, $email_hash, $sku)) return new WP_REST_Response(array('ok'=>false, 'code'=>'checkout_request_mismatch', 'message'=>'This checkout request does not match the current customer or product.'), 409);
      $existing_metadata = json_decode((string)($existing_checkout_order['metadata_json'] ?? ''), true);
      $existing_metadata = is_array($existing_metadata) ? $existing_metadata : array();
      $existing_fingerprint = sanitize_text_field((string)($existing_metadata['mrm_checkout_fingerprint'] ?? ''));
      if ($existing_fingerprint !== '' && !hash_equals($existing_fingerprint, $checkout_fingerprint)) return new WP_REST_Response(array('ok'=>false, 'code'=>'checkout_request_parameters_changed', 'message'=>'The checkout details changed during payment creation. Please close checkout and begin again.'), 409);
      $order_id = (int)$existing_checkout_order['id'];
      $this->update_order_amount_and_metadata($order_id, $final_amount_cents, $metadata);
    } else {
      $order_id = $this->create_order($email_hash, $sku, $product_type, $final_amount_cents, $currency, $metadata);
    }
    if ($order_id <= 0) return new WP_REST_Response(array('ok'=>false, 'code'=>'checkout_order_creation_failed', 'message'=>'The local checkout order could not be created.'), 500);
    $metadata['mrm_order_id'] = (string)$order_id;
    $description = ($product_type === 'lesson')
      ? 'Low Brass Lessons - Lesson Charge'
      : 'Low Brass Lessons - Sheet Music Charge';

    $save_card = !empty($data['save_card']);
    if ($source_flow === 'piece_product_purchase') {
      /* Piece checkout is card-only; retries must preserve the original Stripe parameters. */
      $save_card = false;
    }
    $requires_customer_for_subscription = ($addon_selected && $product_type === 'lesson');
    $requires_customer_for_piece_purchase = false;

    $extra = array();
    $customer_id = '';

    // Default safe method set
    $payment_method_types = array('card');

    // Keep card-only so the Payment Element can show:
    // - card entry
    // - Apple Pay (when available)
    // - Google Pay (when available)
    // We intentionally do NOT include us_bank_account here.
    if (!$save_card && !$requires_customer_for_subscription && !$requires_customer_for_piece_purchase) {
      $payment_method_types = array('card');
    }

    /*
     * Do not ask Stripe to send its own customer receipt email.
     *
     * Low Brass Lessons sends the canonical branded receipt through
     * mrm_maybe_send_purchase_receipt_email(), with the subject:
     * "Purchase Confirmation - [Item]".
     *
     * Leaving receipt_email enabled can cause customers to receive a second
     * Stripe-generated confirmation/receipt email in addition to the branded
     * Purchase Confirmation email.
     */

    if ($save_card || $requires_customer_for_subscription || $requires_customer_for_piece_purchase) {
      $this->stripe_debug_log('create_payment_intent resolving stripe customer', array(
        'email' => $email,
        'save_card' => ($save_card ? 'yes' : 'no'),
        'requires_customer_for_subscription' => ($requires_customer_for_subscription ? 'yes' : 'no'),
        'requires_customer_for_piece_purchase' => ($requires_customer_for_piece_purchase ? 'yes' : 'no'),
        'addon_selected' => ($addon_selected ? 'yes' : 'no'),
        'product_type' => $product_type,
      ));
      $customer_id = $this->stripe_find_or_create_customer($email);
      if (is_wp_error($customer_id)) {
        return new WP_REST_Response(array('ok'=>false,'message'=>$customer_id->get_error_message()), 500);
      }

      $customer_update = $this->stripe_update_customer_address(
        $customer_id,
        $email,
        $address,
        (string)($context['student_name'] ?? '')
      );

      $requires_valid_customer_tax_location = $save_card || $requires_customer_for_subscription || (sanitize_key($context['autopay'] ?? '') === 'yes');
      if (is_wp_error($customer_update)) {
        $this->stripe_debug_log('create_payment_intent Stripe customer address validation failed', array('email'=>$email,'customer_id'=>(string)$customer_id,'message'=>$customer_update->get_error_message(),'recurring_flow'=>$requires_valid_customer_tax_location ? 'yes' : 'no'));
        if ($requires_valid_customer_tax_location) {
          $this->mrm_fail_order_before_payment_intent($order_id, $customer_update->get_error_message());
          return new WP_REST_Response(array('ok'=>false,'code'=>'customer_tax_location_invalid','message'=>'Your billing address could not be validated for recurring billing. Please check the address and try again.'), 400);
        }
      }

      // Attach PI to a real Stripe customer so future off-session billing can work.
      $extra['customer'] = $customer_id;
      $extra['setup_future_usage'] = 'off_session';

      $metadata['mrm_save_card'] = 'yes';
      $metadata['mrm_customer_id'] = (string)$customer_id;
      $this->stripe_debug_log('create_payment_intent stripe customer resolved', array(
        'email' => $email,
        'customer_id' => (string)$customer_id,
      ));
    }

    $publishable_key = $this->publishable_key();
    if ($publishable_key === '') {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Stripe publishable key is not configured.',
      ), 500);
    }

    if ($promo_code !== '' && $promo_discount_cents > 0) {
      $reserved = $this->mrm_reserve_promo_redemption(
        $promo_code,
        $email_hash,
        $order_id,
        '',
        $email,
        is_array($promo_validation) && !empty($promo_validation['promo']) ? $promo_validation['promo'] : array()
      );
      if (!$reserved) {
        return new WP_REST_Response(array(
          'ok' => false,
          'code' => 'promo_code_already_used',
          'message' => 'This email has already used or reserved this promotional code.',
        ), 409);
      }
    }

    $stripe_idempotency_key = $checkout_request_id !== '' ? 'mrm-pi-' . hash('sha256', $checkout_request_id) : '';
    $pi = $this->stripe_create_payment_intent($final_amount_cents, $currency, $metadata, $description, $extra, $payment_method_types, $tax_calc_id, $stripe_idempotency_key);
    if (is_wp_error($pi)) {
      if ($promo_code !== '' && $promo_discount_cents > 0) {
        $this->mrm_release_pending_promo_redemption($order_id);
      }
      $data = $pi->get_error_data();
      return new WP_REST_Response(array('ok'=>false,'message'=>$pi->get_error_message()), 500);
    }

    $this->attach_payment_intent_to_order($order_id, (string)$pi['id'], (string)($pi['status'] ?? ''));
    if ($promo_code !== '' && $promo_discount_cents > 0) {
      $this->mrm_attach_payment_intent_to_promo_redemption($order_id, (string)$pi['id']);
    }

    return new WP_REST_Response(array(
      'ok' => true,
      'publishableKey' => $publishable_key,
      'client_secret' => (string)($pi['client_secret'] ?? ''),
      'payment_intent_id' => (string)$pi['id'],
      'allowed_payment_methods' => array_values($payment_method_types),
      'order_id' => (int)$order_id,
      'customer_id' => $customer_id ? (string)$customer_id : '',
      'sku' => $sku,
      'label' => (string)($p['label'] ?? $sku),
      'amount_cents' => $final_amount_cents,
      'total_cents' => $final_amount_cents,
      'original_base_amount_cents' => $original_base_amount_cents,
      'base_amount_cents' => $base_amount_cents,
      'addon_amount_cents' => $addon_amount_cents,
      'fundamentals_addon_selected' => $fundamentals_selected,
      'fundamentals_addon_sku' => $fundamentals_selected ? (string)$fundamentals_addon['sku'] : '',
      'fundamentals_addon_label' => $fundamentals_selected ? (string)$fundamentals_addon['label'] : '',
      'fundamentals_addon_amount_cents' => $fundamentals_addon_amount_cents,
      'fundamentals_addon_regular_amount_cents' => (int)($fundamentals_addon['regular_amount_cents'] ?? 0),
      'promo_code' => $promo_code,
      'promo_discount_cents' => $promo_discount_cents,
      'promo_discount_type' => is_array($promo_validation) && !empty($promo_validation['promo']['discount_type'])
        ? (string)$promo_validation['promo']['discount_type']
        : '',
      'promo_percent_off' => is_array($promo_validation) && isset($promo_validation['promo']['percent_off'])
        ? (int)$promo_validation['promo']['percent_off']
        : 0,
      'promo_amount_off_cents' => is_array($promo_validation) && isset($promo_validation['promo']['amount_off_cents'])
        ? (int)$promo_validation['promo']['amount_off_cents']
        : 0,
      'tax_cents' => $tax_cents,
      'tax_message' => (string)$tax_message,
      'tax_policy' => array(
        'policy_reason' => (string)($tax_policy['policy_reason'] ?? ''),
        'should_collect_tax' => !empty($tax_policy['should_collect_tax']),
        'state' => (string)($tax_policy['jurisdiction']['state'] ?? ''),
        'country' => (string)($tax_policy['jurisdiction']['country'] ?? 'US'),
        'registered' => null,
        'collect_enabled' => null,
        'stripe_controls_rollout' => true,
      ),
      'tax_calculation_id' => $tax_calc_id,
      'currency' => $currency,
      'product_type' => $product_type,
      'category' => (string)($p['category'] ?? ''),
      'sheet_music_resuming_subscription' => (
        !empty($resumable_subscription_for_checkout['subscription_id'])
          ? array(
            'is_resuming' => true,
            'subscription_id' => (string)$resumable_subscription_for_checkout['subscription_id'],
            'current_period_end' => !empty($resumable_subscription_for_checkout['current_period_end']) ? (int)$resumable_subscription_for_checkout['current_period_end'] : 0,
            'current_period_end_display' => (
              !empty($resumable_subscription_for_checkout['current_period_end'])
                ? wp_date(get_option('date_format'), (int)$resumable_subscription_for_checkout['current_period_end'])
                : ''
            ),
          )
          : array('is_resuming' => false)
      ),
      // Public response intentionally excludes raw Stripe/order metadata.
    ), 200);
  }


  public function rest_create_setup_intent(WP_REST_Request $req) {
    global $wpdb;

    $data = (array)$req->get_json_params();
    $email = sanitize_email((string)($data['email'] ?? ''));
    $context = isset($data['context']) && is_array($data['context']) ? $data['context'] : array();

    $instructor_id = isset($context['instructor_id']) ? absint($context['instructor_id']) : 0;
    $lesson_length = isset($context['lesson_length']) ? absint($context['lesson_length']) : 60;
    $lesson_mode = sanitize_text_field((string)($context['lesson_mode'] ?? 'online'));

    $repeat_frequency = sanitize_text_field((string)($context['repeat_frequency'] ?? 'none'));
    $repeat_duration = sanitize_text_field((string)($context['repeat_duration'] ?? 'indefinitely'));
    $authorized_lesson_count = isset($context['authorized_lesson_count']) ? absint($context['authorized_lesson_count']) : 0;

    $promo_code = $this->mrm_normalize_promo_code($data['promo_code'] ?? ($context['promo_code'] ?? ''));
    $promo_started_at = $promo_code !== '' ? current_time('mysql') : null;

    $plan_kind = ($repeat_duration === 'indefinitely') ? 'indefinite' : 'bounded';
    if ($plan_kind === 'bounded' && $authorized_lesson_count <= 0) {
      $authorized_lesson_count = 1;
    }

    if (!$email || !is_email($email)) return new WP_REST_Response(array('ok'=>false,'message'=>'Valid email required.'), 400);
    if ($instructor_id <= 0) return new WP_REST_Response(array('ok'=>false,'message'=>'Valid instructor_id required.'), 400);

    $sku = 'lesson_' . ($lesson_length === 60 ? '60' : '30') . '_' . ($lesson_mode === 'online' ? 'online' : 'inperson');
    $p = $this->get_product($sku);
    if (!$p || empty($p['active'])) return new WP_REST_Response(array('ok'=>false,'message'=>'Unknown or inactive lesson SKU.'), 404);

    $base_amount = (int)($p['amount_cents'] ?? 0);
    $currency = strtolower((string)($p['currency'] ?? 'usd'));
    if ($base_amount <= 0) return new WP_REST_Response(array('ok'=>false,'message'=>'Invalid lesson price.'), 400);

    $customer_id = $this->stripe_find_or_create_customer($email);
    if (is_wp_error($customer_id)) return new WP_REST_Response(array('ok'=>false,'message'=>$customer_id->get_error_message()), 500);

    $email_hash = $this->email_hash($email);
    $now = current_time('mysql');

    /*
     * This legacy setup-intent route creates a new autopay profile before a setup
     * intent exists. The active frontend autopay flow uses
     * rest_create_autopay_enrollment(), which performs idempotency checks from the
     * successful first-payment PaymentIntent.
     *
     * Do not reference $payment_intent_id or $payment_method_id here; those values
     * are not available in this legacy setup-intent route.
     */

    $wpdb->insert($this->table_autopay_profiles(), array(
  'instructor_id' => (int)$instructor_id,
  'email_hash' => (string)$email_hash,
  'customer_id' => (string)$customer_id,
  'payment_method_id' => '',
  'currency' => $currency,
  'unit_base_cents' => (int)$base_amount,
  'plan_kind' => $plan_kind,
  'authorized_lesson_count' => (int)$authorized_lesson_count,
  'charged_lesson_count' => 0,
  'promo_code' => $promo_code !== '' ? $promo_code : null,
  'promo_started_at' => $promo_started_at,
  'active' => 1,
  'detached_at' => null,
  'created_at' => $now,
  'updated_at' => $now,
), array(
  '%d',
  '%s',
  '%s',
  '%s',
  '%s',
  '%d',
  '%s',
  '%d',
  '%d',
  '%s',
  '%s',
  '%d',
  '%s',
  '%s',
  '%s',
));

    $autopay_profile_id = (int)$wpdb->insert_id;
    if ($autopay_profile_id <= 0) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Unable to create autopay profile.'), 500);
    }

    // This route is not your active frontend path, but this cleanup removes stale overlapping
    // logic that was guaranteed to fail if it ever got used again.

    $si = $this->stripe_create_setup_intent($customer_id, array(
      'mrm_autopay_profile_id' => (string)$autopay_profile_id,
      'mrm_instructor_id' => (string)$instructor_id,
      'mrm_customer_email' => (string)$email,
    ));

    if (is_wp_error($si)) {
      return new WP_REST_Response(array('ok'=>false,'message'=>$si->get_error_message()), 500);
    }

    $publishable_key = $this->publishable_key();
    if ($publishable_key === '') {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Stripe publishable key is not configured.',
      ), 500);
    }

    return new WP_REST_Response(array(
      'ok' => true,
      'publishableKey' => $publishable_key,
      'client_secret' => (string)($si['client_secret'] ?? ''),
      'setup_intent_id' => (string)($si['id'] ?? ''),
      'autopay_profile_id' => $autopay_profile_id,
      'currency' => $currency,
      'unit_base_cents' => $base_amount,
      'plan_kind' => $plan_kind,
      'authorized_lesson_count' => (int)$authorized_lesson_count,
    ), 200);
  }

  public function rest_finalize_autopay(WP_REST_Request $req) {
    global $wpdb;

    $data = (array)$req->get_json_params();
    $autopay_profile_id = isset($data['autopay_profile_id']) ? absint($data['autopay_profile_id']) : 0;
    $setup_intent_id = sanitize_text_field((string)($data['setup_intent_id'] ?? ''));

    if ($autopay_profile_id <= 0 || $setup_intent_id === '') {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Missing autopay_profile_id or setup_intent_id.'), 400);
    }

    $profile = $this->mrm_get_autopay_profile($autopay_profile_id);
    if (!$profile) return new WP_REST_Response(array('ok'=>false,'message'=>'Autopay profile not found.'), 404);

    $si = $this->stripe_retrieve_setup_intent($setup_intent_id);
    if (is_wp_error($si)) return new WP_REST_Response(array('ok'=>false,'message'=>$si->get_error_message()), 500);

    $status = (string)($si['status'] ?? '');
    $customer_id = (string)($si['customer'] ?? '');
    $payment_method_id = (string)($si['payment_method'] ?? '');

    if ($status !== 'succeeded' || $payment_method_id === '') {
      return new WP_REST_Response(array('ok'=>false,'message'=>'SetupIntent not ready.'), 400);
    }

    if ($customer_id !== '' && $customer_id !== (string)$profile['customer_id']) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'SetupIntent customer mismatch.'), 400);
    }

    $pm_ready = $this->mrm_ensure_customer_payment_method_ready((string)$profile['customer_id'], $payment_method_id);
    if (is_wp_error($pm_ready)) {
      return new WP_REST_Response(array('ok'=>false,'message'=>$pm_ready->get_error_message()), 400);
    }

    $wpdb->update($this->table_autopay_profiles(), array(
      'payment_method_id' => $payment_method_id,
      'active' => 1,
      'updated_at' => current_time('mysql'),
    ), array('id' => $autopay_profile_id), array('%s','%d','%s'), array('%d'));

    $pm_live = $this->stripe_retrieve_payment_method($payment_method_id);
    if (!is_wp_error($pm_live)) {
      $this->mrm_store_autopay_payment_method_snapshot(
        $autopay_profile_id,
        $payment_method_id,
        $pm_live,
        'ok',
        '',
        false
      );
    }

    return new WP_REST_Response(array(
      'ok' => true,
      'autopay_profile_id' => $autopay_profile_id,
      'payment_method_id' => $payment_method_id,
    ), 200);
  }

  public function rest_create_autopay_enrollment(WP_REST_Request $req) {
    global $wpdb;

    $data = (array)$req->get_json_params();
    $payment_intent_id = sanitize_text_field((string)($data['payment_intent_id'] ?? ''));
    $email = sanitize_email((string)($data['email'] ?? ''));
    $context = isset($data['context']) && is_array($data['context']) ? $data['context'] : array();

    $instructor_id = isset($context['instructor_id']) ? absint($context['instructor_id']) : 0;
    $lesson_length = isset($context['lesson_length']) ? absint($context['lesson_length']) : 60;
    $lesson_mode = sanitize_text_field((string)($context['lesson_mode'] ?? 'online'));
    $repeat_frequency = sanitize_text_field((string)($context['repeat_frequency'] ?? 'none'));
    $repeat_duration = sanitize_text_field((string)($context['repeat_duration'] ?? 'indefinitely'));
    $authorized_lesson_count = isset($context['authorized_lesson_count']) ? absint($context['authorized_lesson_count']) : 0;

    $promo_code = $this->mrm_normalize_promo_code($data['promo_code'] ?? ($context['promo_code'] ?? ''));
    $promo_started_at = $promo_code !== '' ? current_time('mysql') : null;

    if ($payment_intent_id === '') {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Missing payment_intent_id.'), 400);
    }
    if (!$email || !is_email($email)) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Valid email required.'), 400);
    }
    if ($instructor_id <= 0) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Valid instructor_id required.'), 400);
    }

    $pi = $this->stripe_retrieve_payment_intent($payment_intent_id);
    if (is_wp_error($pi)) {
      return new WP_REST_Response(array('ok'=>false,'message'=>$pi->get_error_message()), 500);
    }

if ($promo_code === '' && !empty($pi['metadata']['mrm_promo_code'])) {
  $promo_code = $this->mrm_normalize_promo_code($pi['metadata']['mrm_promo_code']);
  $promo_started_at = $promo_code !== '' ? current_time('mysql') : null;
}

    $status = (string)($pi['status'] ?? '');
    $customer_id = (string)($pi['customer'] ?? '');
    $payment_method_id = (string)($pi['payment_method'] ?? '');

    if ($status !== 'succeeded') {
      return new WP_REST_Response(array('ok'=>false,'message'=>'PaymentIntent not succeeded.'), 400);
    }
    if ($customer_id === '' || $payment_method_id === '') {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Saved card details were not attached to the successful payment.'), 400);
    }

    $pm_ready = $this->mrm_ensure_customer_payment_method_ready($customer_id, $payment_method_id);
    if (is_wp_error($pm_ready)) {
      return new WP_REST_Response(array('ok'=>false,'message'=>$pm_ready->get_error_message()), 400);
    }

    $sku = 'lesson_' . ($lesson_length === 60 ? '60' : '30') . '_' . ($lesson_mode === 'online' ? 'online' : 'inperson');
    $p = $this->get_product($sku);
    if (!$p || empty($p['active'])) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Unknown or inactive lesson SKU.'), 404);
    }

    $base_amount = (int)($p['amount_cents'] ?? 0);
    $currency = strtolower((string)($p['currency'] ?? 'usd'));
    if ($base_amount <= 0) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Invalid lesson price.'), 400);
    }

    $plan_kind = ($repeat_duration === 'indefinitely') ? 'indefinite' : 'bounded';
    if ($plan_kind === 'bounded' && $authorized_lesson_count <= 0) {
      $authorized_lesson_count = 1;
    }

    $email_hash = $this->email_hash($email);
    $now = current_time('mysql');

    /*
     * Idempotency guard: do not create multiple autopay profiles for the same
     * successful first-payment order if the frontend retries or refreshes.
     */
    $existing_order_for_autopay = $this->get_order_by_pi($payment_intent_id);
    if ($existing_order_for_autopay && !empty($existing_order_for_autopay['metadata_json'])) {
      $existing_meta = json_decode((string)$existing_order_for_autopay['metadata_json'], true);
      if (is_array($existing_meta) && !empty($existing_meta['mrm_autopay_profile_id'])) {
        $existing_profile_id = absint($existing_meta['mrm_autopay_profile_id']);
        if ($existing_profile_id > 0) {
          return new WP_REST_Response(array(
            'ok' => true,
            'autopay_profile_id' => $existing_profile_id,
            'customer_id' => $customer_id,
            'payment_method_id' => $payment_method_id,
            'plan_kind' => ($repeat_duration === 'indefinitely') ? 'indefinite' : 'bounded',
            'authorized_lesson_count' => (int)$authorized_lesson_count,
            'already_created' => true,
          ), 200);
        }
      }
    }

    $pm_live = $this->stripe_retrieve_payment_method($payment_method_id);
    $pm_snap = !is_wp_error($pm_live) ? $this->mrm_extract_card_snapshot_from_payment_method($pm_live) : array(
      'brand' => '',
      'last4' => '',
      'exp_month' => 0,
      'exp_year' => 0,
    );

    $wpdb->insert($this->table_autopay_profiles(), array(
      'instructor_id' => (int)$instructor_id,
      'email_hash' => (string)$email_hash,
      'customer_id' => (string)$customer_id,
      'payment_method_id' => (string)$payment_method_id,
      'currency' => $currency,
      'unit_base_cents' => (int)$base_amount,
      'plan_kind' => $plan_kind,
      'authorized_lesson_count' => (int)$authorized_lesson_count,
      'charged_lesson_count' => 0,
      'promo_code' => $promo_code !== '' ? $promo_code : null,
      'promo_started_at' => $promo_started_at,
      'pm_brand' => (string)$pm_snap['brand'],
      'pm_last4' => (string)$pm_snap['last4'],
      'pm_exp_month' => (int)$pm_snap['exp_month'],
      'pm_exp_year' => (int)$pm_snap['exp_year'],
      'pm_last_checked_at' => $now,
      'pm_attention_status' => 'ok',
      'pm_attention_reason' => '',
      'pm_attention_notified_at' => null,
      'active' => 1,
      'detached_at' => null,
      'created_at' => $now,
      'updated_at' => $now,
    ), array(
  '%d',
  '%s',
  '%s',
  '%s',
  '%s',
  '%d',
  '%s',
  '%d',
  '%d',
  '%s',
  '%s',
  '%s',
  '%s',
  '%d',
  '%d',
  '%s',
  '%s',
  '%s',
  '%s',
  '%d',
  '%s',
  '%s',
  '%s',
));

    $autopay_profile_id = (int)$wpdb->insert_id;
    if ($autopay_profile_id <= 0) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Unable to create autopay profile.'), 500);
    }

    $validated_profile = $this->mrm_validate_autopay_profile_for_charge(
      $this->mrm_get_autopay_profile($autopay_profile_id)
    );

    if ( is_wp_error($validated_profile) ) {
      return new WP_Error(
        'mrm_autopay_profile_incomplete',
        $validated_profile->get_error_message(),
        array('status' => 500)
      );
    }

    $order = $this->get_order_by_pi($payment_intent_id);
    if ($order) {
      $meta = array();
      if (!empty($order['metadata_json'])) {
        $decoded = json_decode((string)$order['metadata_json'], true);
        if (is_array($decoded)) $meta = $decoded;
      }

      $meta['mrm_autopay_enrollment'] = 'yes';
      $meta['mrm_autopay_profile_id'] = (string)$autopay_profile_id;
      $meta['mrm_plan_kind'] = $plan_kind;
      $meta['mrm_authorized_lesson_count'] = (string)$authorized_lesson_count;
      $meta['mrm_first_lesson_prepaid'] = 'yes';

      $this->update_order_status_from_pi($payment_intent_id, (string)($order['status'] ?? 'paid'), 'succeeded', $meta);
    }


    return new WP_REST_Response(array(
      'ok' => true,
      'autopay_profile_id' => $autopay_profile_id,
      'customer_id' => $customer_id,
      'payment_method_id' => $payment_method_id,
      'plan_kind' => $plan_kind,
      'authorized_lesson_count' => (int)$authorized_lesson_count,
    ), 200);
  }


  public function rest_update_tax(WP_REST_Request $req) {
    $data = (array) $req->get_json_params();
    $exemption_check = $this->mrm_tax_reject_unsupported_exemption_claim($data);
    if (is_wp_error($exemption_check)) return new WP_REST_Response(array('ok'=>false,'code'=>$exemption_check->get_error_code(),'message'=>$exemption_check->get_error_message()), 400);

    $order_id = isset($data['order_id']) ? absint($data['order_id']) : 0;
    $address = (isset($data['address']) && is_array($data['address'])) ? $data['address'] : array();

    $address = $this->mrm_normalize_tax_address($address);

    if ($order_id <= 0) return new WP_REST_Response(array('ok'=>false,'message'=>'Missing order_id.'), 400);

    $order = $this->get_order($order_id);
    if (!$order) return new WP_REST_Response(array('ok'=>false,'message'=>'Order not found.'), 404);

    $pi_id = (string)($order['stripe_payment_intent_id'] ?? '');
    if (!$pi_id) return new WP_REST_Response(array('ok'=>false,'message'=>'PaymentIntent not attached yet.'), 409);

    // Only allow updating tax for unpaid orders
    $status = (string)($order['status'] ?? '');
    // NOTE: your orders start as 'created' in create_order(). Allow both 'created' and 'pending' here.
    if ($status && !in_array($status, array('created','pending'), true)) {
      return new WP_REST_Response(array('ok'=>false,'message'=>'Order is not pending.'), 409);
    }

    $meta = array();
    if (!empty($order['metadata_json'])) {
      $decoded = json_decode((string)$order['metadata_json'], true);
      if (is_array($decoded)) $meta = $decoded;
    }

    $product_type = (string)($order['product_type'] ?? ($meta['mrm_product_type'] ?? ''));
    $base_amount_cents = isset($meta['mrm_base_amount_cents']) ? (int)$meta['mrm_base_amount_cents'] : (int)($order['amount_cents'] ?? 0);
    $addon_amount_cents = isset($meta['mrm_addon_amount_cents']) ? (int)$meta['mrm_addon_amount_cents'] : 0;
    $fundamentals_addon_amount_cents = max(0, (int)($meta['mrm_fundamentals_addon_amount_cents'] ?? 0));
    $fundamentals_selected = (
      strtolower((string)($meta['mrm_fundamentals_addon'] ?? 'no')) === 'yes' &&
      $fundamentals_addon_amount_cents > 0
    );

    $currency = strtolower((string)($order['currency'] ?? 'usd'));

    $addon_selected = ($addon_amount_cents > 0);
    $tax_context = is_array($meta) ? $meta : array();
    $raw_lesson_mode = strtolower(trim((string)($meta['lesson_mode'] ?? $meta['mrm_lesson_mode'] ?? '')));
    $is_online = strpos($raw_lesson_mode, 'online') !== false || strpos($raw_lesson_mode, 'virtual') !== false;
    $tax_context['lesson_mode'] = $is_online ? 'online' : 'inperson';
    $tax_context['online'] = $is_online;
    $tax_context['instructor_id'] = absint($meta['instructor_id'] ?? $meta['mrm_instructor_id'] ?? 0);
    $tax_context['sku'] = sanitize_key($order['sku'] ?? $meta['mrm_sku'] ?? '');
    $tax_context['fundamentals_addon_selected'] = $fundamentals_selected;
    if ($product_type === 'lesson' && !$is_online) {
      $performance_location_id = $this->mrm_get_instructor_performance_location_id($tax_context['instructor_id']);
      if ($performance_location_id === '') {
        return new WP_REST_Response(array('ok'=>false,'code'=>'performance_location_required','message'=>'The instructor performance location is not configured.'), 409);
      }
      $tax_context['stripe_tax_performance_location_id'] = $performance_location_id;
    }
    $tax_policy = $this->mrm_build_tax_policy($address, $product_type, $addon_selected, array(), $tax_context);

    if ($tax_policy instanceof WP_REST_Response) {
      return $tax_policy;
    }

    if (is_array($tax_policy) && empty($tax_policy['ok']) && !empty($tax_policy['code'])) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => (string)($tax_policy['code'] ?? 'tax_policy_failed'),
        'message' => (string)($tax_policy['message'] ?? 'Billing address is required before checkout.'),
        'missing_address_fields' => (array)($tax_policy['missing_address_fields'] ?? array()),
      ), 400);
    }

    if (!is_array($tax_policy)) {
      return new WP_REST_Response(array(
        'ok' => false,
        'code' => 'tax_policy_invalid_response',
        'message' => 'Unable to validate tax policy for this checkout.',
      ), 500);
    }

    $taxable_items = $this->mrm_build_taxable_items_from_policy(
      $tax_policy,
      $base_amount_cents,
      $addon_amount_cents,
      $fundamentals_addon_amount_cents
    );
    if (is_wp_error($taxable_items)) return new WP_REST_Response(array('ok'=>false,'code'=>$taxable_items->get_error_code(),'message'=>$taxable_items->get_error_message()), 500);
    $tax_result = $this->mrm_tax_calculate_for_items($address, $taxable_items, $currency);
    if (is_wp_error($tax_result)) return new WP_REST_Response(array('ok'=>false,'code'=>$tax_result->get_error_code(),'message'=>$tax_result->get_error_message()), 503);
    $tax_cents = (int)$tax_result['tax_cents'];
    $tax_calc_id = sanitize_text_field($tax_result['calculation_id']);
    $tax_message = $this->mrm_build_tax_display_message($tax_policy, $tax_result, $tax_cents);

    $new_total_cents = (int)$tax_result['amount_total_cents'];
    $first_profile = $tax_policy['profiles'][0] ?? array();

    // Update Stripe PaymentIntent amount (before confirmation)
    $update_params = array(
      'amount' => (int)$tax_result['amount_total_cents'],
      'metadata[mrm_subtotal_cents]' => (string)$tax_result['subtotal_cents'],
      'metadata[mrm_tax_cents]' => (string)$tax_result['tax_cents'],
      'metadata[mrm_total_cents]' => (string)$tax_result['amount_total_cents'],
      'metadata[mrm_tax_calculation_id]' => sanitize_text_field($tax_result['calculation_id']),
      'metadata[mrm_taxability_reason]' => sanitize_key($tax_result['taxability_reason'] ?? ''),
      'metadata[mrm_tax_lines_json]' => (string)($tax_result['metadata_line_items_json'] ?? '[]'),
      'metadata[mrm_lesson_mode]' => $is_online ? 'Online' : 'In Person',
      'metadata[mrm_instructor_id]' => (string)$tax_context['instructor_id'],
      'metadata[mrm_product_type]' => sanitize_key($product_type),
      'metadata[mrm_tax_state]' => (string)($address['state'] ?? ''),
      'metadata[mrm_tax_country]' => (string)($address['country'] ?? 'US'),
      'metadata[mrm_customer_state]' => '',
      'metadata[mrm_customer_country]' => '',
      'metadata[mrm_tax_policy_message]' => '',
      'metadata[mrm_tax_rollout_mode]' => '',
      'metadata[mrm_tax_calculation_requested]' => '',
      'metadata[mrm_tax_policy_reason]' => '',
    );
    $pi = $this->stripe_api_request('POST', '/v1/payment_intents/' . rawurlencode($pi_id), $update_params);
    if (is_wp_error($pi)) {
      return new WP_REST_Response(array('ok'=>false,'message'=>$pi->get_error_message()), 500);
    }

    // Persist into order metadata so receipts and ledger remain consistent
    $meta['mrm_subtotal_cents'] = (string)$tax_result['subtotal_cents'];
    $meta['mrm_tax_cents'] = (string)$tax_cents;
    $meta['mrm_total_cents'] = (string)$new_total_cents;
    $meta['mrm_tax_calculation_id'] = (string)$tax_calc_id;
    $meta['mrm_addon_tax_cents'] = (string)$tax_cents; // back-compat
    $meta['mrm_tax_country'] = (string)($address['country'] ?? 'US');
    $meta['mrm_tax_state'] = (string)($address['state'] ?? '');
    $meta['mrm_tax_postal_code'] = (string)($address['postal_code'] ?? '');
    $meta['mrm_tax_line1'] = (string)($address['line1'] ?? '');
    $meta['mrm_tax_line2'] = (string)($address['line2'] ?? '');
    $meta['mrm_tax_city'] = (string)($address['city'] ?? '');
    $meta['mrm_tax_rollout_mode'] = 'stripe_only';
    $meta['mrm_tax_calculation_requested'] = !empty($tax_policy['should_collect_tax']) ? 'yes' : 'no';
    $meta['mrm_tax_policy_reason'] = (string)($tax_policy['policy_reason'] ?? '');
    $meta['mrm_tax_policy_message'] = (string)$tax_message;
    $meta['mrm_taxability_reason'] = (string)($tax_result['taxability_reason'] ?? '');
    $meta['mrm_tax_lines_json'] = (string)($tax_result['metadata_line_items_json'] ?? '[]');
    $meta['mrm_lesson_mode'] = $is_online ? 'Online' : 'In Person';
    $meta['mrm_instructor_id'] = (string)$tax_context['instructor_id'];
    $meta['mrm_tax_code'] = sanitize_text_field($first_profile['tax_code'] ?? '');
    $meta['mrm_threshold_category'] = sanitize_key($first_profile['threshold_category'] ?? 'other');
    $meta['mrm_product_type'] = sanitize_key($product_type);
    $meta['mrm_customer_state'] = (string)($address['state'] ?? '');
    $meta['mrm_customer_country'] = (string)($address['country'] ?? 'US');

    $this->update_order_amount_and_metadata($order_id, $new_total_cents, $meta);

    return new WP_REST_Response(array(
      'ok' => true,
      'order_id' => (int)$order_id,
      'payment_intent_id' => $pi_id,
      'original_base_amount_cents' => (int)($meta['mrm_original_base_amount_cents'] ?? $base_amount_cents),
      'promo_discount_cents' => (int)($meta['mrm_promo_discount_cents'] ?? 0),
      'amount_cents' => (int)$new_total_cents,
      'base_amount_cents' => (int)$base_amount_cents,
      'addon_amount_cents' => (int)$addon_amount_cents,
      'tax_cents' => (int)$tax_cents,
      'tax_message' => (string)$tax_message,
      'tax_policy' => array(
        'policy_reason' => (string)($tax_policy['policy_reason'] ?? ''),
        'should_collect_tax' => !empty($tax_policy['should_collect_tax']),
        'state' => (string)($tax_policy['jurisdiction']['state'] ?? ''),
        'country' => (string)($tax_policy['jurisdiction']['country'] ?? 'US'),
        'registered' => null,
        'collect_enabled' => null,
        'stripe_controls_rollout' => true,
      ),
      'tax_calculation_id' => $tax_calc_id,
      'total_cents' => (int)$new_total_cents,
      'currency' => $currency,
    ), 200);
  }

  private function mrm_maybe_create_sheet_music_subscription_from_initial_payment_intent($pi, $order = array()) {
    if (!is_array($pi)) return;

    $pi_id = (string)($pi['id'] ?? '');
    if ($pi_id === '') return;

    if (!is_array($order) || empty($order)) {
      $order = $this->get_order_by_pi($pi_id);
    }

    if (!is_array($order) || empty($order)) {
      return;
    }

    $order_id = (int)($order['id'] ?? 0);
    if ($order_id <= 0) return;

    $this->mrm_attempt_sheet_music_subscription_activation($order_id, $pi, 'initial_payment_intent_helper');
  }

  private function mrm_retry_sheet_music_subscription_creation_for_order($order_id) {
    $order_id = (int)$order_id;
    if ($order_id <= 0) return false;

    $order = $this->get_order($order_id);
    if (!is_array($order) || empty($order)) {
      return false;
    }

    $pi_id = (string)($order['stripe_payment_intent_id'] ?? ($order['payment_intent_id'] ?? ''));
    if ($pi_id === '') {
      $this->mrm_set_order_meta_flag($order_id, 'mrm_sheet_music_subscription_status', 'missing_payment_intent');
      $this->mrm_set_order_meta_flag($order_id, 'mrm_sheet_music_subscription_error', 'Missing payment_intent_id on order.');
      return false;
    }

    $pi = $this->stripe_retrieve_payment_intent($pi_id);
    if (is_wp_error($pi)) {
      $this->mrm_set_order_meta_flag($order_id, 'mrm_sheet_music_subscription_status', 'payment_intent_retrieve_failed');
      $this->mrm_set_order_meta_flag($order_id, 'mrm_sheet_music_subscription_error', $pi->get_error_message());
      return false;
    }

    $this->stripe_debug_log('subscription retry helper invoked', array(
      'order_id' => $order_id,
      'pi_id' => $pi_id,
      'pi_status' => (string)($pi['status'] ?? ''),
      'customer_id' => (string)($pi['customer'] ?? ''),
      'payment_method_id' => (string)($pi['payment_method'] ?? ''),
    ));

    $result = $this->mrm_attempt_sheet_music_subscription_activation($order_id, $pi, 'retry_helper');

    $this->mrm_subscription_debug_log('retry helper completed', array(
      'order_id' => $order_id,
      'result' => ($result ? 'true' : 'false'),
      'pi_id' => $pi_id,
    ));

    return $result;
  }


  public function rest_verify_payment_intent(WP_REST_Request $req) {
    $data = (array) $req->get_json_params();
    $pi_id = sanitize_text_field((string)($data['payment_intent_id'] ?? ''));

    if (!$pi_id) return new WP_REST_Response(array('ok'=>false,'message'=>'Missing payment_intent_id.'), 400);

    $pi = $this->stripe_retrieve_payment_intent($pi_id);
    if (is_wp_error($pi)) return new WP_REST_Response(array('ok'=>false,'message'=>$pi->get_error_message()), 500);

    $status = (string)($pi['status'] ?? '');
    $terminal_statuses = array('succeeded');
    $fail_statuses = array('requires_payment_method', 'canceled');

    $ok = in_array($status, $terminal_statuses, true);

    if ($ok) {
      $tax_sync_result = $this->mrm_tax_sync_payment_intent_ledger($pi, 0);
      if (is_wp_error($tax_sync_result)) {
        return new WP_REST_Response(array('ok'=>false,'status'=>$status,'tax_reconciliation_pending'=>true,'message'=>'Payment was received, but the required sales-tax record is still being reconciled. Access and order finalization will complete automatically after reconciliation succeeds.'), 503);
      }
    }

    $piece_auto_grant_attempted = false;
    $piece_auto_grant_success = false;
    $piece_auto_grant_skus = array();

    // If this PaymentIntent was created with a customer + setup_future_usage,
    // Stripe should attach the payment method to the customer.
    // We log proof and force-set default PM for off-session charges.
    if ($ok) {
      $customer_id = isset($pi['customer']) ? (string)$pi['customer'] : '';
      $pm_id = isset($pi['payment_method']) ? (string)$pi['payment_method'] : '';
      $sfu = isset($pi['setup_future_usage']) ? (string)$pi['setup_future_usage'] : '';

      if ($customer_id && $pm_id) {

        $pm_ready = $this->mrm_ensure_customer_payment_method_ready($customer_id, $pm_id);
        if (is_wp_error($pm_ready)) {
        } else {
        }
      } else {
        // If user expected autopay but no customer/pm is present, log it loudly
      }
    }

    $meta = isset($pi['metadata']) && is_array($pi['metadata']) ? $pi['metadata'] : array();
    $addon_yes = (isset($meta['mrm_sheet_music_addon']) && strtolower((string)$meta['mrm_sheet_music_addon']) === 'yes');

    $start_ts = 0;
    if (isset($pi['charges']['data'][0]['created'])) {
      $start_ts = (int)$pi['charges']['data'][0]['created'];
    } elseif (isset($pi['created'])) {
      $start_ts = (int)$pi['created'];
    } else {
      $start_ts = time();
    }

    // Scheduler lesson addon path (existing behavior)
    if ($ok && $addon_yes) {
      $email = sanitize_email((string)($meta['mrm_customer_email'] ?? ''));
      if ($email && is_email($email)) {
        $this->mrm_grant_all_sheet_music_ledger($email, $start_ts, 'stripe_pi_addon', $pi_id);
      }
    }

    // Piece-product path: trusted metadata grants all purchased products.
    if ($ok && sanitize_key((string)($meta['mrm_product_type'] ?? '')) === 'sheet_music') {
      $pi_sku=$this->sanitize_sku($meta['mrm_sku']??'');
      if ($pi_sku && $pi_sku !== $this->master_sheet_music_sku()) {
        $piece_auto_grant_attempted=true;
        $grant_result=$this->mrm_grant_sheet_music_purchase_entitlements($pi,'stripe_pi_verify');
        if (!is_wp_error($grant_result)) { $piece_auto_grant_success=true; $piece_auto_grant_skus=array_values((array)($grant_result['skus']??array())); }
      }
    }

    // Update local order status if it exists
    $latest_charge = '';
    if (!empty($pi['latest_charge'])) {
      $latest_charge = (string)$pi['latest_charge'];
    }

    $order = $this->get_order_by_pi($pi_id);
    if ($order) {
      $new_status = $ok ? 'paid' : (in_array($status, $fail_statuses, true) ? 'failed' : 'created');
      $metadata = $pi['metadata'] ?? null;
      if (is_array($metadata)) {
        $metadata['mrm_latest_charge_id'] = $latest_charge;
      } else {
        $metadata = array('mrm_latest_charge_id' => $latest_charge);
      }
      $this->update_order_status_from_pi($pi_id, $new_status, $status, $metadata);
    }

    // Do not send the purchase receipt from the verify endpoint.
    // The Stripe payment_intent.succeeded webhook is the sole sender
    // for lesson purchase confirmation emails.
    if ($ok && $order) {
      $order = $this->get_order_by_pi($pi_id);

      /*
       * Payout-ledger creation is intentionally handled only by payment_intent.succeeded.
       * The webhook returns persistence errors so Stripe can retry; browser verification
       * must not independently create or silently ignore payout records.
       */

      $meta = isset($pi['metadata']) && is_array($pi['metadata']) ? $pi['metadata'] : array();
      $addon_yes = (isset($meta['mrm_sheet_music_addon']) && strtolower((string)$meta['mrm_sheet_music_addon']) === 'yes');
      $product_type = (string)($order['product_type'] ?? '');

      $this->mrm_subscription_debug_log('verify endpoint loaded order before activation', array(
        'order_id' => (int)($order['id'] ?? 0),
        'order_status' => (string)($order['status'] ?? ''),
        'order_payment_intent_id' => (string)($order['stripe_payment_intent_id'] ?? ($order['payment_intent_id'] ?? '')),
        'passed_pi_id' => (string)($pi['id'] ?? ''),
      ));

      if ($addon_yes && $product_type === 'lesson' && !empty($order['id'])) {
        $order_id = (int)($order['id'] ?? 0);
        $order_meta = $this->mrm_get_order_meta_array($order);

        $existing_subscription_id = (string)($order_meta['mrm_sheet_music_subscription_id'] ?? '');
        $existing_created_at = (string)($order_meta['mrm_sheet_music_subscription_created_at'] ?? '');
        $email = sanitize_email((string)($order_meta['mrm_customer_email'] ?? ($pi['metadata']['mrm_customer_email'] ?? '')));

        $existing_active = array();
        if ($email && is_email($email)) {
          $existing_active = $this->mrm_get_active_sheet_music_subscription_by_email($email);
        }

        $this->mrm_subscription_debug_log('verify endpoint guarded activation check', array(
          'order_id' => $order_id,
          'payment_intent_id' => (string)($pi['id'] ?? ''),
          'existing_subscription_id' => $existing_subscription_id,
          'existing_created_at' => $existing_created_at,
          'existing_active_found' => (!empty($existing_active['id']) ? 'yes' : 'no'),
          'context' => 'verify_endpoint',
        ));

        if ($existing_subscription_id === '' && empty($existing_active['id'])) {
          $this->mrm_subscription_debug_log('verify endpoint invoking guarded fallback activation', array(
            'order_id' => $order_id,
            'payment_intent_id' => (string)($pi['id'] ?? ''),
            'context' => 'verify_endpoint',
          ));

          $this->mrm_attempt_sheet_music_subscription_activation($order_id, $pi, 'verify_endpoint_fallback');
        } else {
          $this->mrm_subscription_debug_log('verify endpoint skipped fallback activation because subscription already exists or is already active', array(
            'order_id' => $order_id,
            'payment_intent_id' => (string)($pi['id'] ?? ''),
            'existing_subscription_id' => $existing_subscription_id,
            'existing_active_subscription_id' => (string)($existing_active['stripe_subscription_id'] ?? ''),
            'context' => 'verify_endpoint',
          ));
        }
      }
    }

    return new WP_REST_Response(array(
      'ok' => $ok,
      'status' => $status,
      'amount_cents' => (int)($pi['amount'] ?? 0),
      'currency' => (string)($pi['currency'] ?? 'usd'),
      'metadata' => (array)($pi['metadata'] ?? array()),
      'piece_auto_grant_attempted' => (bool)$piece_auto_grant_attempted,
      'piece_auto_grant_success' => (bool)$piece_auto_grant_success,
      'piece_auto_grant_skus' => $piece_auto_grant_skus,
    ), 200);
  }

  private function mrm_wrap_transactional_email_html($title, $intro_html, $details_html, $button_url = '', $button_text = '', $options = array()) {
    return $this->mrm_email_wrap_html($title, $intro_html, $details_html, $button_url, $button_text);
  }

  public function rest_grant_sheet_music_access(WP_REST_Request $req) {
    $data = (array) $req->get_json_params();

    // Accept sku or product_slug (canonical is product_slug)
    $incoming_slug = isset($data['product_slug']) ? $data['product_slug'] : ($data['sku'] ?? '');
    $sku   = $this->sanitize_sku($incoming_slug);

    $context = isset($data['context']) && is_array($data['context']) ? $data['context'] : array();

    $resolved_sku = $this->mrm_resolve_active_product_sku($sku, $context);
    if ($resolved_sku !== '') {
      $sku = $resolved_sku;
    }

    $email = sanitize_email((string)($data['email'] ?? ''));
    $pi_id = sanitize_text_field((string)($data['payment_intent_id'] ?? ''));

    $is_admin_manual_grant = current_user_can('manage_options');

    /*
     * Public access grants must always be backed by a succeeded Stripe PaymentIntent.
     * Admin/manual grants are still allowed for logged-in administrators only.
     */
    if (!$pi_id && !$is_admin_manual_grant) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'We could not confirm payment for this purchase. Please contact Low Brass Lessons for assistance.',
      ), 403);
    }

    if ($pi_id) {
      $pi = $this->stripe_retrieve_payment_intent($pi_id);
      if (is_wp_error($pi)) {
        return new WP_REST_Response(array(
          'ok' => false,
          'message' => 'We could not confirm payment for this purchase. Please contact Low Brass Lessons for assistance.',
        ), 500);
      }

      $status = (string)($pi['status'] ?? '');
      if ($status !== 'succeeded') {
        return new WP_REST_Response(array(
          'ok' => false,
          'message' => 'Payment has not been completed yet.',
        ), 400);
      }

      $tax_sync_result = $this->mrm_tax_sync_payment_intent_ledger($pi, 0);
      if (is_wp_error($tax_sync_result)) {
        return new WP_REST_Response(array('ok'=>false,'tax_reconciliation_pending'=>true,'message'=>'Payment was received, but access cannot be granted until the required sales-tax record is reconciled.'), 503);
      }

      $meta = isset($pi['metadata']) && is_array($pi['metadata']) ? $pi['metadata'] : array();
      if (sanitize_key((string)($meta['mrm_product_type'] ?? '')) === 'sheet_music') {
        $grant_result=$this->mrm_grant_sheet_music_purchase_entitlements($pi,'stripe_pi_rest');
        if (is_wp_error($grant_result)) return new WP_REST_Response(array('ok'=>false,'code'=>$grant_result->get_error_code(),'message'=>$grant_result->get_error_message()),$grant_result->get_error_code()==='sheet_music_email_blocked'?403:500);
        return new WP_REST_Response(array('ok'=>true,'granted'=>true,'email_hash'=>$grant_result['email_hash'],'sku'=>$grant_result['base_sku'],'skus'=>$grant_result['skus'],'payment_intent_id'=>$grant_result['payment_intent_id']),200);
      }


      $pi_sku = $this->sanitize_sku((string)($meta['mrm_sku'] ?? ''));
      $pi_email = sanitize_email((string)($meta['mrm_customer_email'] ?? ''));

      if ($pi_sku) {
        $sku = $pi_sku;
      }

      if ($pi_email && is_email($pi_email)) {
        $email = $pi_email;
      }
    }

    if (!$sku) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This offer is temporarily unavailable. Please contact Low Brass Lessons for assistance.',
      ), 400);
    }

    if (!$email || !is_email($email)) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Please enter a valid email address.',
      ), 400);
    }

    if ($this->mrm_sheet_music_email_is_blocked($email)) {
      return new WP_REST_Response(array(
        'ok' => false,
        'blocked' => true,
        'redirect_url' => $this->mrm_sheet_music_contact_url(),
        'message' => 'This email is currently restricted from accessing sheet music. Please contact Low Brass Lessons support.',
      ), 403);
    }

    $p = $this->get_product($sku);
    if (!$p || empty($p['active'])) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This offer is temporarily unavailable. Please contact Low Brass Lessons for assistance.',
      ), 404);
    }

    $product_type = (string)($p['product_type'] ?? 'unknown');
    if ($product_type !== 'sheet_music') {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'This purchase could not be completed for the selected item.',
      ), 400);
    }

    // DB guard (updates can skip activation hook)
    $this->maybe_install_or_upgrade_db();

    // Verify access table exists
    global $wpdb;
    $access_table = $this->table_sheet_music_access();
    $found = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $access_table));
    if ($found !== $access_table) {
      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Server is updating. Please try again in a moment.',
      ), 500);
    }

    $email_hash = $this->email_hash($email);

    $ok = $this->grant_sheet_music_access($email_hash, $email, $sku, $pi_id ? 'stripe_pi' : 'manual', $pi_id);
    if (!$ok) {
      $last = $wpdb->last_error ? $wpdb->last_error : 'unknown_db_error';

      return new WP_REST_Response(array(
        'ok' => false,
        'message' => 'Failed to grant access.',
      ), 500);
    }

    // ✅ Access source of truth: DB ledger row only.
    // Do NOT also mirror into the per-product "Approved Emails (OTP Access)" product UI.


    return new WP_REST_Response(array(
      'ok' => true,
      'email_hash' => $email_hash,
      'sku' => $sku,
    ), 200);
  }


  public function rest_has_access(WP_REST_Request $req) {
    $data = (array) $req->get_json_params();
    $sku   = $this->sanitize_sku($data['sku'] ?? '');
    $email = sanitize_email((string)($data['email'] ?? ''));

    // Privacy-safe: do not leak whether access exists unless caller already has context.
    // We still return ok with has_access boolean (needed for internal systems / admin tools).
    if (!$sku) {
      return new WP_REST_Response(array('ok' => false, 'message' => 'Some payment details were missing. Please refresh and try again.'), 400);
    }
    if (!$email || !is_email($email)) {
      return new WP_REST_Response(array('ok' => false, 'message' => 'Valid email required.'), 400);
    }

    if ($this->mrm_sheet_music_email_is_blocked($email)) {
      return new WP_REST_Response(array(
        'ok' => true,
        'sku' => $sku,
        'has_access' => false,
        'blocked' => true,
        'redirect_url' => $this->mrm_sheet_music_contact_url(),
        'message' => 'This email is currently restricted from accessing sheet music. Please contact Low Brass Lessons support.',
      ), 200);
    }

    $email_hash = $this->email_hash($email);

    global $wpdb;
    $table = $wpdb->prefix . 'mrm_sheet_music_access';

    // If table doesn't exist, fail closed.
    $exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
    if ($exists !== $table) {
      return new WP_REST_Response(array('ok' => true, 'sku' => $sku, 'has_access' => false), 200);
    }

    $id = $wpdb->get_var($wpdb->prepare(
      "SELECT id FROM {$table} WHERE email_hash=%s AND sku=%s AND revoked_at IS NULL LIMIT 1",
      (string)$email_hash,
      (string)$sku
    ));

    return new WP_REST_Response(array(
      'ok' => true,
      'sku' => $sku,
      'has_access' => !empty($id),
    ), 200);
  }

  private function mrm_grant_sheet_music_purchase_entitlements($pi, $source = 'stripe_pi') {
    if (!is_array($pi) || strpos((string)($pi['id']??''),'pi_') !== 0) return new WP_Error('invalid_payment_intent','The Stripe Payment Intent could not be read.');
    if (sanitize_key($pi['status']??'') !== 'succeeded') return new WP_Error('payment_not_succeeded','The payment has not completed successfully.');
    $meta=is_array($pi['metadata']??null)?$pi['metadata']:array();
    if (sanitize_key($meta['mrm_product_type']??'') !== 'sheet_music') return new WP_Error('not_sheet_music_purchase','This payment is not a sheet-music purchase.');
    $email=sanitize_email($meta['mrm_customer_email']??'');
    if (!$email || !is_email($email)) return new WP_Error('invalid_customer_email','The payment does not contain a valid customer email.');
    if ($this->mrm_sheet_music_email_is_blocked($email)) return new WP_Error('sheet_music_email_blocked','This email is currently restricted from accessing sheet music.');
    $base_sku=$this->sanitize_sku($meta['mrm_sku']??''); $base=$this->get_product($base_sku);
    if (!$base_sku || !is_array($base) || sanitize_key($base['product_type']??'')!=='sheet_music' || $base_sku===$this->master_sheet_music_sku()) return new WP_Error('invalid_base_entitlement','The purchased sheet-music product could not be resolved.');
    $skus=array($base_sku);
    if (strtolower((string)($meta['mrm_fundamentals_addon']??'no'))==='yes') {
      $addon_sku=$this->sanitize_sku($meta['mrm_fundamentals_addon_sku']??''); $addon=$this->get_product($addon_sku);
      if (!$addon_sku || !is_array($addon) || sanitize_key($addon['product_type']??'')!=='sheet_music' || sanitize_key($addon['category']??'')!=='fundamentals') return new WP_Error('invalid_fundamentals_entitlement','The purchased Fundamental Packet could not be resolved.');
      $category=sanitize_key($base['category']??'');
      if ($this->mrm_piece_stem_from_offer_slug($base_sku,$category)==='' || $this->mrm_piece_stem_from_offer_slug($base_sku,$category)!==$this->mrm_piece_stem_from_offer_slug($addon_sku,'fundamentals')) return new WP_Error('fundamentals_entitlement_piece_mismatch','The purchased Fundamental Packet does not match the Full Piece.');
      $skus[]=$addon_sku;
    }
    $created=(int)($pi['charges']['data'][0]['created']??($pi['created']??time())); $hash=$this->email_hash($email); $granted=array();
    foreach(array_unique($skus) as $sku) {
      if (!$this->grant_sheet_music_access($hash,$email,$sku,sanitize_text_field($source),(string)$pi['id'],$created)) return new WP_Error('sheet_music_entitlement_grant_failed','One or more purchased sheet-music entitlements could not be granted.');
      $granted[]=$sku;
    }
    return array('ok'=>true,'email_hash'=>$hash,'email'=>$email,'base_sku'=>$base_sku,'skus'=>$granted,'payment_intent_id'=>(string)$pi['id']);
  }

  private function grant_sheet_music_access($email_hash, $email_plain, $sku, $source = null, $source_id = null, $start_ts = null) {
    global $wpdb;
    $table = $this->table_sheet_music_access();

    // Default to "now", but allow caller to pass Stripe charge/create timestamp.
    $now_mysql = current_time('mysql');
    $start_at_mysql = $now_mysql;

    if ($start_ts !== null && is_numeric($start_ts) && (int)$start_ts > 0) {
      $start_at_mysql = gmdate('Y-m-d H:i:s', (int)$start_ts);
    }

    // If already granted (active row exists), treat as idempotent success.
    $existing = $wpdb->get_var($wpdb->prepare(
      "SELECT id FROM {$table} WHERE email_hash = %s AND sku = %s AND revoked_at IS NULL LIMIT 1",
      $email_hash, $sku
    ));

    if ($existing) {
      return true;
    }

    $ins = $wpdb->insert($table, array(
      'email_hash'  => $email_hash,
      'email_plain' => $email_plain,
      'sku'         => $sku,
      'start_at'    => $start_at_mysql,
      'expires_at'  => null,              // piece purchases never expire
      'month_key'   => null,
      'granted_at'  => $now_mysql,
      'revoked_at'  => null,
      'source'      => $source,
      'source_id'   => $source_id,
    ), array('%s','%s','%s','%s','%s','%s','%s','%s','%s','%s'));

    if ($ins) {
      return true;
    }

    return false;
  }

  public function grant_all_sheet_music_db_row($email, $source = null, $source_id = null) {
    $email = sanitize_email((string)$email);
    if (!$email || !is_email($email)) return false;

    $this->maybe_install_or_upgrade_db();
    return $this->mrm_grant_all_sheet_music_ledger($email, time(), $source, $source_id);
  }

  public function has_sheet_music_access($email_hash, $sku) {
    global $wpdb;
    $table = $this->table_sheet_music_access();
    $id = $wpdb->get_var($wpdb->prepare(
      "SELECT id FROM {$table} WHERE email_hash = %s AND sku = %s AND revoked_at IS NULL LIMIT 1",
      $email_hash, $sku
    ));
    return !empty($id);
  }

  public function email_has_access_for_slug($email, $product_slug) {
    $email = sanitize_email((string)$email);
    if (!$email || !is_email($email)) return false;

    $product_slug = $this->sanitize_product_slug($product_slug);
    if (!$product_slug) return false;

    if ($this->mrm_sheet_music_email_is_blocked($email)) return false;

    /* Active Stripe subscriptions remain authoritative for all-sheet-music access. */
    $subscription_status = $this->mrm_get_sheet_music_subscription_access_status_by_email($email);
    if (!empty($subscription_status['has_access'])) return true;
    if ($product_slug === 'all-sheet-music') return false;

    /* Per-piece access comes only from the visible access table. */
    return $this->has_sheet_music_access($this->email_hash($email), $product_slug);
  }

  private function mrm_revoke_sheet_music_entitlements_for_payment_intent($pi_id) {
    global $wpdb;
    $pi_id = sanitize_text_field($pi_id);
    if (!$pi_id || strpos($pi_id, 'pi_') !== 0) {
      return new WP_Error('invalid_refund_payment_intent', 'The refunded Payment Intent ID is invalid.');
    }

    $table = $this->table_sheet_music_access();
    $wpdb->last_error = '';
    $updated = $wpdb->query($wpdb->prepare(
      "UPDATE {$table} SET revoked_at = %s WHERE source_id = %s AND revoked_at IS NULL",
      current_time('mysql'), $pi_id
    ));
    if ($updated === false) {
      return new WP_Error('refund_entitlement_revoke_failed', $wpdb->last_error);
    }
    return true;
  }

  public function cleanup_access() {
    $this->mrm_prune_expired_all_sheet_music();
  }

  /* =========================================================
   * Marketing Email Lists
