  private function mrm_marketing_school_outreach_key($state, $type) {
    $states = $this->mrm_marketing_state_options();
    $types = $this->mrm_marketing_school_outreach_types();

    $state = sanitize_key((string)$state);
    $type = sanitize_key((string)$type);

    if (!isset($states[$state]) || !isset($types[$type])) {
      return '';
    }

    return 'school_outreach_' . $state . '_' . $type;
  }

  private function mrm_marketing_state_instructor_key($state) {
    $states = $this->mrm_marketing_state_options();
    $state = sanitize_key((string)$state);

    if (!isset($states[$state])) {
      return '';
    }

    return 'state_instructors_' . $state;
  }

  private function mrm_marketing_parse_state_instructor_key($list_key) {
    $list_key = sanitize_key((string)$list_key);
    $prefix = 'state_instructors_';

    if (strpos($list_key, $prefix) !== 0) {
      return array();
    }

    $state = substr($list_key, strlen($prefix));
    $states = $this->mrm_marketing_state_options();

    if (!isset($states[$state])) {
      return array();
    }

    return array(
      'state' => $state,
      'state_code' => strtoupper($state),
      'state_label' => (string)$states[$state],
      'label' => 'Instructors in ' . (string)$states[$state],
    );
  }

  private function mrm_marketing_state_college_professor_key($state) {
    $states = $this->mrm_marketing_state_options();
    $state = sanitize_key((string)$state);

    if (!isset($states[$state])) {
      return '';
    }

    return 'college_professors_' . $state;
  }

  private function mrm_marketing_parse_state_college_professor_key($list_key) {
    $list_key = sanitize_key((string)$list_key);
    $prefix = 'college_professors_';

    if (strpos($list_key, $prefix) !== 0) {
      return array();
    }

    $state = substr($list_key, strlen($prefix));
    $states = $this->mrm_marketing_state_options();

    if (!isset($states[$state])) {
      return array();
    }

    return array(
      'state' => $state,
      'state_code' => strtoupper($state),
      'state_label' => (string)$states[$state],
      'label' => 'College Professors in ' . (string)$states[$state],
    );
  }

  private function mrm_marketing_is_instructor_list($list_key) {
    $list_key = sanitize_key((string)$list_key);

    if ($list_key === 'all_current_instructors') {
      return true;
    }

    return !empty(
      $this->mrm_marketing_parse_state_instructor_key($list_key)
    );
  }

  private function mrm_marketing_selected_list_mode($list_keys) {
    $has_instructor = false;
    $has_marketing = false;

    foreach ((array)$list_keys as $list_key) {
      if ($this->mrm_marketing_is_instructor_list($list_key)) {
        $has_instructor = true;
      } else {
        $has_marketing = true;
      }
    }

    if ($has_instructor && $has_marketing) {
      return 'mixed';
    }

    if ($has_instructor) {
      return 'instructor';
    }

    return 'marketing';
  }

  private function mrm_marketing_parse_school_outreach_key($list_key) {
    $list_key = sanitize_key((string)$list_key);

    if (strpos($list_key, 'school_outreach_') !== 0) {
      return array();
    }

    $states = $this->mrm_marketing_state_options();
    $types = $this->mrm_marketing_school_outreach_types();

    foreach ($states as $state_key => $state_label) {
      $prefix = 'school_outreach_' . $state_key . '_';

      if (strpos($list_key, $prefix) !== 0) {
        continue;
      }

      $type = substr($list_key, strlen($prefix));

      if (!isset($types[$type])) {
        return array();
      }

      return array(
        'state' => $state_key,
        'state_label' => $state_label,
        'type' => $type,
        'type_label' => (string)$types[$type]['label'],
      );
    }

    return array();
  }

