  private function mrm_marketing_manual_lists() {
    $lists = $this->get_email_lists();
    $defs = $this->mrm_marketing_default_lists();

    foreach ($defs as $key => $def) {
      if (($def['type'] ?? '') === 'manual' && !isset($lists[$key])) {
        $lists[$key] = array();
      }
    }

    foreach ($this->mrm_marketing_state_options() as $state_key => $state_label) {
      foreach ($this->mrm_marketing_school_outreach_types() as $type_key => $type_def) {
        $list_key = $this->mrm_marketing_school_outreach_key($state_key, $type_key);

        if ($list_key !== '' && !isset($lists[$list_key])) {
          $lists[$list_key] = array();
        }
      }
    }

    foreach ($this->mrm_marketing_state_options() as $state_key => $state_label) {
      $list_key = $this->mrm_marketing_state_college_professor_key(
        $state_key
      );

      if ($list_key !== '' && !isset($lists[$list_key])) {
        $lists[$list_key] = array();
      }
    }

    foreach ($lists as $key => $emails) {
      $normalized = array();

      foreach ((array)$emails as $email) {
        $email = strtolower(sanitize_email((string)$email));

        if ($email && is_email($email)) {
          $normalized[$email] = true;
        }
      }

      $lists[$key] = array_keys($normalized);
      sort($lists[$key]);
    }

    return $lists;
  }

  private function mrm_marketing_unsubscribed_emails() {
    $emails = get_option('mrm_pay_hub_marketing_unsubscribed', array());
    $out = array();
    foreach ((array)$emails as $email) {
      $email = strtolower(sanitize_email((string)$email));
      if ($email && is_email($email)) $out[$email] = true;
    }
    return $out;
  }

  private function mrm_marketing_save_unsubscribed_emails($emails) {
    $out = array();
    foreach ((array)$emails as $email) {
      $email = strtolower(sanitize_email((string)$email));
      if ($email && is_email($email)) $out[$email] = true;
    }
    $final = array_keys($out);
    sort($final);
    update_option('mrm_pay_hub_marketing_unsubscribed', $final, false);
  }

  private function mrm_marketing_add_unsubscribe($email) {
    $email = strtolower(sanitize_email((string)$email));
    if (!$email || !is_email($email)) return false;

    $unsubscribed = $this->mrm_marketing_unsubscribed_emails();
    $unsubscribed[$email] = true;
    $this->mrm_marketing_save_unsubscribed_emails(array_keys($unsubscribed));

    $lists = $this->mrm_marketing_manual_lists();
    foreach ($lists as $key => $emails) {
      $lists[$key] = array_values(array_diff((array)$emails, array($email)));
    }
    $this->save_email_lists($lists);
    return true;
  }

  private function mrm_marketing_normalize_emails_from_text($raw) {
    $parts = preg_split('/[\s,;]+/', (string)$raw);
    $out = array();
    foreach ((array)$parts as $part) {
      $email = strtolower(sanitize_email(trim((string)$part)));
      if ($email && is_email($email)) $out[$email] = true;
    }
    $emails = array_keys($out);
    sort($emails);
    return $emails;
  }

  private function mrm_marketing_table_exists($table) {
    global $wpdb;
    $table = (string)$table;
    return $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
  }

  private function mrm_marketing_extract_customer_email_from_order_row($row) {
    $meta = array();
    if (!empty($row['metadata_json'])) {
      $decoded = json_decode((string)$row['metadata_json'], true);
      if (is_array($decoded)) $meta = $decoded;
    }
    $email = strtolower(sanitize_email((string)($meta['mrm_customer_email'] ?? '')));
    return ($email && is_email($email)) ? $email : '';
  }

  private function mrm_marketing_paid_order_emails_by_type($product_type) {
    global $wpdb;
    $orders = $this->table_orders();
    if (!$this->mrm_marketing_table_exists($orders)) return array();

    $rows = $wpdb->get_results(
      $wpdb->prepare(
        "SELECT metadata_json FROM {$orders}
         WHERE product_type = %s
           AND status IN ('paid','completed','succeeded')
         ORDER BY created_at DESC
         LIMIT 5000",
        sanitize_text_field((string)$product_type)
      ),
      ARRAY_A
    );

    $out = array();
    foreach ((array)$rows as $row) {
      $email = $this->mrm_marketing_extract_customer_email_from_order_row($row);
      if ($email) $out[$email] = true;
    }
    $emails = array_keys($out);
    sort($emails);
    return $emails;
  }

  private function mrm_marketing_sheet_music_subscriber_emails() {
    global $wpdb;
    $subs = $this->table_sheet_music_subscriptions();
    if (!$this->mrm_marketing_table_exists($subs)) return array();

    $rows = $wpdb->get_col(
      "SELECT DISTINCT email_plain FROM {$subs}
       WHERE email_plain IS NOT NULL
         AND email_plain <> ''
         AND stripe_status IN ('active','trialing','past_due')
       ORDER BY email_plain ASC
       LIMIT 5000"
    );

    $out = array();
    foreach ((array)$rows as $email) {
      $email = strtolower(sanitize_email((string)$email));
      if ($email && is_email($email)) $out[$email] = true;
    }
    $emails = array_keys($out);
    sort($emails);
    return $emails;
  }

  private function mrm_marketing_lesson_student_emails($mode = 'active') {
    global $wpdb;
    $lessons = $this->table_lessons();
    if (!$this->mrm_marketing_table_exists($lessons)) return array();

    $now = current_time('mysql');
    $one_month_ago = date('Y-m-d H:i:s', strtotime('-1 month', current_time('timestamp')));

    $active_rows = $wpdb->get_col(
      $wpdb->prepare(
        "SELECT DISTINCT student_email FROM {$lessons}
         WHERE student_email IS NOT NULL
           AND student_email <> ''
           AND start_time >= %s
           AND status NOT IN ('cancelled','refunded','failed')
         ORDER BY student_email ASC
         LIMIT 5000",
        $now
      )
    );

    $active = array();
    foreach ((array)$active_rows as $email) {
      $email = strtolower(sanitize_email((string)$email));
      if ($email && is_email($email)) $active[$email] = true;
    }

    if ($mode === 'active') {
      $emails = array_keys($active);
      sort($emails);
      return $emails;
    }

    if ($mode === 'past') {
      $past_rows = $wpdb->get_results(
        $wpdb->prepare(
          "SELECT student_email, MAX(start_time) AS last_lesson_at
           FROM {$lessons}
           WHERE student_email IS NOT NULL
             AND student_email <> ''
             AND start_time < %s
             AND status NOT IN ('cancelled','refunded','failed')
           GROUP BY student_email
           HAVING last_lesson_at <= %s
           ORDER BY student_email ASC
           LIMIT 5000",
          $now,
          $one_month_ago
        ),
        ARRAY_A
      );

      $past = array();
      foreach ((array)$past_rows as $row) {
        $email = strtolower(sanitize_email((string)($row['student_email'] ?? '')));
        if ($email && is_email($email) && !isset($active[$email])) {
          $past[$email] = true;
        }
      }

      $emails = array_keys($past);
      sort($emails);
      return $emails;
    }

    return array();
  }

  private function mrm_marketing_instructor_emails($state = '') {
    global $wpdb;

    $table = $wpdb->prefix . 'mrm_instructors';

    $table_exists = $wpdb->get_var(
      $wpdb->prepare(
        'SHOW TABLES LIKE %s',
        $table
      )
    );

    if ($table_exists !== $table) {
      return array();
    }

    $state = strtoupper(
      substr(
        sanitize_text_field((string)$state),
        0,
        2
      )
    );

    if ($state !== '') {
      $rows = $wpdb->get_col(
        $wpdb->prepare(
          "SELECT DISTINCT email
           FROM {$table}
           WHERE email IS NOT NULL
             AND email <> ''
             AND UPPER(state) = %s
           ORDER BY email ASC",
          $state
        )
      );
    } else {
      $rows = $wpdb->get_col(
        "SELECT DISTINCT email
         FROM {$table}
         WHERE email IS NOT NULL
           AND email <> ''
         ORDER BY email ASC"
      );
    }

    $emails = array();

    foreach ((array)$rows as $email) {
      $email = strtolower(
        sanitize_email((string)$email)
      );

      if ($email !== '' && is_email($email)) {
        $emails[$email] = true;
      }
    }

    $emails = array_keys($emails);
    sort($emails);

    return $emails;
  }

  private function mrm_marketing_all_college_professor_emails() {
    $lists = $this->mrm_marketing_manual_lists();
    $emails = array();

    foreach ($this->mrm_marketing_state_options() as $state_key => $state_label) {
      $list_key = $this->mrm_marketing_state_college_professor_key(
        $state_key
      );

      if ($list_key === '' || empty($lists[$list_key])) {
        continue;
      }

      foreach ((array)$lists[$list_key] as $email) {
        $email = strtolower(
          sanitize_email((string)$email)
        );

        if ($email !== '' && is_email($email)) {
          $emails[$email] = true;
        }
      }
    }

    $emails = array_keys($emails);
    sort($emails);

    return $emails;
  }


  private function mrm_marketing_all_school_outreach_emails($type) {
    $types = $this->mrm_marketing_school_outreach_types();
    $states = $this->mrm_marketing_state_options();
    $lists = $this->mrm_marketing_manual_lists();

    $type = sanitize_key((string)$type);

    if (!isset($types[$type])) {
      return array();
    }

    $emails = array();

    foreach ($states as $state_key => $state_label) {
      $list_key = $this->mrm_marketing_school_outreach_key($state_key, $type);

      if ($list_key === '' || empty($lists[$list_key])) {
        continue;
      }

      foreach ((array)$lists[$list_key] as $email) {
        $email = strtolower(sanitize_email((string)$email));

        if ($email !== '' && is_email($email)) {
          $emails[$email] = true;
        }
      }
    }

    $emails = array_keys($emails);
    sort($emails);

    return $emails;
  }

  private function mrm_marketing_get_list_recipients($list_key, $apply_suppression = true) {
    $defs = $this->mrm_marketing_default_lists();
    $list_key = sanitize_key((string)$list_key);

    $school_list = $this->mrm_marketing_parse_school_outreach_key(
      $list_key
    );

    $state_instructor_list = $this->mrm_marketing_parse_state_instructor_key(
      $list_key
    );

    $state_college_professor_list =
      $this->mrm_marketing_parse_state_college_professor_key(
        $list_key
      );

    if (
      !isset($defs[$list_key]) &&
      empty($school_list) &&
      empty($state_instructor_list) &&
      empty($state_college_professor_list)
    ) {
      return array();
    }

    switch ($list_key) {
      case 'all_sheet_music_purchasers':
        $emails = $this->mrm_marketing_paid_order_emails_by_type('sheet_music');
        break;
      case 'sheet_music_subscribers':
        $emails = $this->mrm_marketing_sheet_music_subscriber_emails();
        break;
      case 'active_lesson_students':
        $emails = $this->mrm_marketing_lesson_student_emails('active');
        break;
      case 'past_lesson_students':
        $emails = $this->mrm_marketing_lesson_student_emails('past');
        break;
      case 'all_current_instructors':
        $emails = $this->mrm_marketing_instructor_emails();
        break;
      case 'all_college_professors':
        $emails = $this->mrm_marketing_all_college_professor_emails();
        break;
      case 'all_middle_school_band_directors':
        $emails = $this->mrm_marketing_all_school_outreach_emails('middle_school_band_directors');
        break;
      case 'all_middle_school_administrators':
        $emails = $this->mrm_marketing_all_school_outreach_emails('middle_school_administrators');
        break;
      case 'all_high_school_band_directors':
        $emails = $this->mrm_marketing_all_school_outreach_emails('high_school_band_directors');
        break;
      case 'all_high_school_administrators':
        $emails = $this->mrm_marketing_all_school_outreach_emails('high_school_administrators');
        break;
      default:
        if (!empty($state_instructor_list)) {
          $emails = $this->mrm_marketing_instructor_emails(
            $state_instructor_list['state_code']
          );
        } else {
          /*
           * State college-professor lists and school outreach lists
           * are both manually stored.
           */
          $manual = $this->mrm_marketing_manual_lists();
          $emails = isset($manual[$list_key])
            ? (array)$manual[$list_key]
            : array();
        }
        break;
    }

    $out = array();
    foreach ((array)$emails as $email) {
      $email = strtolower(sanitize_email((string)$email));
      if ($email && is_email($email)) $out[$email] = true;
    }

    if ($apply_suppression) {
      $unsubscribed = $this->mrm_marketing_unsubscribed_emails();
      foreach (array_keys($unsubscribed) as $email) unset($out[$email]);
    }

    $final = array_keys($out);
    sort($final);
    return $final;
  }

  private function mrm_marketing_get_combined_recipients(
    $list_keys,
    $apply_suppression = true
  ) {
    $out = array();

    foreach ((array)$list_keys as $list_key) {
      foreach (
        $this->mrm_marketing_get_list_recipients(
          $list_key,
          $apply_suppression
        ) as $email
      ) {
        $out[$email] = true;
      }
    }

    $final = array_keys($out);
    sort($final);

    return $final;
  }

  private function mrm_marketing_token_for_email($email) {
    $email = strtolower(sanitize_email((string)$email));
    if (!$email || !is_email($email)) return '';
    $secret = defined('AUTH_SALT') ? AUTH_SALT : wp_salt('auth');
    $payload = $email . '|' . hash_hmac('sha256', $email, $secret);
    return rtrim(strtr(base64_encode($payload), '+/', '-_'), '=');
  }

  private function mrm_marketing_email_from_token($token) {
    $token = preg_replace('/[^A-Za-z0-9\-_]/', '', (string)$token);
    if ($token === '') return '';
    $padded = strtr($token, '-_', '+/');
    $padded .= str_repeat('=', (4 - strlen($padded) % 4) % 4);
    $decoded = base64_decode($padded, true);
    if (!$decoded || strpos($decoded, '|') === false) return '';

    list($email, $sig) = explode('|', $decoded, 2);
    $email = strtolower(sanitize_email((string)$email));
    if (!$email || !is_email($email)) return '';

    $secret = defined('AUTH_SALT') ? AUTH_SALT : wp_salt('auth');
    $expected = hash_hmac('sha256', $email, $secret);
    return hash_equals($expected, (string)$sig) ? $email : '';
  }

  public function register_marketing_unsubscribe_endpoint() {
    add_rewrite_rule(
      '^marketing-unsubscribe/?$',
      'index.php?mrm_marketing_unsubscribe=1',
      'top'
    );
  }

  public function register_marketing_unsubscribe_query_vars($vars) {
    $vars[] = 'mrm_marketing_unsubscribe';
    return $vars;
  }

  public function intercept_public_marketing_unsubscribe($wp) {
    $request_path = isset($wp->request)
      ? trim((string)$wp->request, '/')
      : '';

    if ($request_path !== 'marketing-unsubscribe') {
      return;
    }

    $wp->query_vars['mrm_marketing_unsubscribe'] = '1';

    if (strtoupper((string)($_SERVER['REQUEST_METHOD'] ?? 'GET')) === 'POST') {
      $this->handle_marketing_unsubscribe_do();
      exit;
    }

    $this->handle_marketing_unsubscribe_confirm();
    exit;
  }

  public function handle_public_marketing_unsubscribe() {
    $is_endpoint = (string)get_query_var('mrm_marketing_unsubscribe') === '1';

    if (!$is_endpoint) {
      $request_uri = isset($_SERVER['REQUEST_URI'])
        ? wp_unslash($_SERVER['REQUEST_URI'])
        : '';

      $request_path = trim(
        (string)wp_parse_url($request_uri, PHP_URL_PATH),
        '/'
      );

      $home_path = trim(
        (string)wp_parse_url(home_url('/'), PHP_URL_PATH),
        '/'
      );

      if ($home_path !== '' && strpos($request_path, $home_path . '/') === 0) {
        $request_path = substr($request_path, strlen($home_path) + 1);
      }

      $is_endpoint = $request_path === 'marketing-unsubscribe';
    }

    if (!$is_endpoint) {
      return;
    }

    global $wp_query;

    if ($wp_query) {
      $wp_query->is_404 = false;
      $wp_query->is_page = true;
    }

    status_header(200);
    nocache_headers();

    if (strtoupper((string)($_SERVER['REQUEST_METHOD'] ?? 'GET')) === 'POST') {
      $this->handle_marketing_unsubscribe_do();
      exit;
    }

    $this->handle_marketing_unsubscribe_confirm();
    exit;
  }

  private function mrm_marketing_unsubscribe_url($email) {
    $token = $this->mrm_marketing_token_for_email($email);

    if ($token === '') {
      return '';
    }

    return add_query_arg(
      array('token' => $token),
      home_url('/marketing-unsubscribe/')
    );
  }

  // BEGIN PAYMENT HUB MARKETING UNSUBSCRIBE FIX
  public function handle_marketing_unsubscribe_confirm() {
    $token = isset($_GET['token']) ? sanitize_text_field(wp_unslash($_GET['token'])) : '';
    $email = $this->mrm_marketing_email_from_token($token);

    if (!$email) {
      $this->mrm_marketing_render_unsubscribe_page(
        'Invalid unsubscribe link',
        'This unsubscribe link is invalid or expired. Please contact Low Brass Lessons if you still need help unsubscribing.',
        ''
      );
      exit;
    }

    $unsubscribe_action_url = home_url('/marketing-unsubscribe/');

    $form = '<form method="post" action="' . esc_url($unsubscribe_action_url) . '" style="margin-top:20px;">'
      . '<input type="hidden" name="token" value="' . esc_attr($token) . '">'
      . wp_nonce_field(
          'mrm_marketing_unsubscribe_do_' . $email,
          'mrm_marketing_unsubscribe_nonce',
          true,
          false
        )
      . '<button type="submit" style="appearance:none;background:#111;color:#fff;border:0;border-radius:999px;padding:13px 22px;cursor:pointer;font-weight:800;">Remove me from marketing emails</button>'
      . '</form>';

    $this->mrm_marketing_render_unsubscribe_page(
      'Confirm unsubscribe',
      'You are unsubscribing ' . esc_html($email) . ' from Low Brass Lessons marketing emails.',
      $form
    );
    exit;
  }

  public function handle_marketing_unsubscribe_do() {
    $token = isset($_POST['token'])
      ? sanitize_text_field(wp_unslash($_POST['token']))
      : '';

    $email = $this->mrm_marketing_email_from_token($token);

    if (!$email) {
      $this->mrm_marketing_render_unsubscribe_page(
        'Invalid unsubscribe request',
        'This unsubscribe request could not be verified. Please contact Low Brass Lessons if you still need help unsubscribing.',
        ''
      );
      exit;
    }

    $nonce = isset($_POST['mrm_marketing_unsubscribe_nonce'])
      ? sanitize_text_field(wp_unslash($_POST['mrm_marketing_unsubscribe_nonce']))
      : '';

    if (
      !$nonce ||
      !wp_verify_nonce(
        $nonce,
        'mrm_marketing_unsubscribe_do_' . $email
      )
    ) {
      $this->mrm_marketing_render_unsubscribe_page(
        'Unsubscribe request expired',
        'Please reopen the unsubscribe link from your email and try again.',
        ''
      );
      exit;
    }

    $this->mrm_marketing_add_unsubscribe($email);

    $this->mrm_marketing_render_unsubscribe_page(
      'You are unsubscribed',
      esc_html($email) . ' has been removed from Low Brass Lessons marketing emails.',
      '<p style="margin-top:18px;color:#555;">You may still receive transactional emails related to purchases, lessons, masterclasses, access links, receipts, reminders, safety, or legal/account records.</p>'
    );
    exit;
  }

