  private function mrm_marketing_allowed_html($html) {
    $html = (string)$html;
    if (current_user_can('manage_options')) return $html;
    $allowed = wp_kses_allowed_html('post');
    foreach ($allowed as $tag => $attrs) {
      $allowed[$tag]['style'] = true;
      $allowed[$tag]['class'] = true;
      $allowed[$tag]['id'] = true;
    }
    $allowed['table'] = array('style'=>true,'class'=>true,'id'=>true,'width'=>true,'cellpadding'=>true,'cellspacing'=>true,'border'=>true,'role'=>true);
    $allowed['tbody'] = array('style'=>true,'class'=>true,'id'=>true);
    $allowed['thead'] = array('style'=>true,'class'=>true,'id'=>true);
    $allowed['tr'] = array('style'=>true,'class'=>true,'id'=>true);
    $allowed['td'] = array('style'=>true,'class'=>true,'id'=>true,'align'=>true,'valign'=>true,'width'=>true);
    $allowed['th'] = array('style'=>true,'class'=>true,'id'=>true,'align'=>true,'valign'=>true,'width'=>true);
    $allowed['img'] = array('src'=>true,'alt'=>true,'style'=>true,'class'=>true,'id'=>true,'width'=>true,'height'=>true,'border'=>true);
    return wp_kses($html, $allowed);
  }

  private function mrm_marketing_email_footer_html($unsubscribe_url, $mailing_address = '') {
    $site = esc_html(get_bloginfo('name') ? get_bloginfo('name') : 'Low Brass Lessons');
    $address_html = trim((string)$mailing_address) !== ''
      ? '<div style="margin-top:8px;">' . nl2br(esc_html((string)$mailing_address)) . '</div>'
      : '';

    if (!$unsubscribe_url) return '';

    return '<div class="mrm-marketing-email-footer" style="margin-top:28px;padding-top:16px;border-top:1px solid #e5e5e5;font-size:12px;line-height:1.6;color:#777;text-align:center;font-family:Arial,Helvetica,sans-serif;">'
      . '<div>You are receiving this marketing email from ' . $site . '.</div>'
      . $address_html
      . '<div style="margin-top:10px;"><a href="' . esc_url($unsubscribe_url) . '" style="color:#555;text-decoration:underline;">Remove me from marketing emails</a></div>'
      . '</div>';
  }

  private function mrm_marketing_build_email_html($body_html, $unsubscribe_url, $mailing_address = '') {
    $body_html = (string)$body_html;
    $footer_html = $this->mrm_marketing_email_footer_html($unsubscribe_url, $mailing_address);

    if (stripos($body_html, '</body>') !== false) {
      return preg_replace('/<\/body>/i', $footer_html . '</body>', $body_html, 1);
    }

    if (stripos($body_html, '<html') !== false) {
      return $body_html . $footer_html;
    }

    return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;">'
      . $body_html
      . $footer_html
      . '</body></html>';
  }

  private function mrm_instructor_correspondence_build_email_html($body_html) {
    $body_html = (string)$body_html;

    /*
     * A complete HTML document is sent exactly as entered.
     */
    if (stripos($body_html, '<html') !== false) {
      return $body_html;
    }

    /*
     * An HTML fragment receives only the minimum document wrapper.
     * No marketing footer or additional visible content is inserted.
     */
    return '<!doctype html>'
      . '<html>'
      . '<head>'
      . '<meta charset="utf-8">'
      . '<meta name="viewport" content="width=device-width,initial-scale=1">'
      . '</head>'
      . '<body style="margin:0;padding:0;">'
      . $body_html
      . '</body>'
      . '</html>';
  }

  private function mrm_marketing_sent_log() {
    $log = get_option('mrm_pay_hub_marketing_sent_log', array());
    return is_array($log) ? $log : array();
  }

  private function mrm_marketing_save_sent_log($log) {
    $clean = array();

    foreach ((array)$log as $item) {
      if (!is_array($item)) continue;

      $item_id = sanitize_key((string)($item['id'] ?? ''));

      if ($item_id === '') {
        $item_id = 'legacy_' . substr(
          hash(
            'sha256',
            wp_json_encode(array(
              $item['sent_at'] ?? '',
              $item['subject'] ?? '',
              $item['list_keys'] ?? array(),
              $item['recipient_count'] ?? 0,
              $item['sent_count'] ?? 0,
              $item['failed_count'] ?? 0,
            ))
          ),
          0,
          20
        );
      }

      $clean[] = array(
        'id' => $item_id,
        'sent_at' => sanitize_text_field((string)($item['sent_at'] ?? '')),
        'subject' => sanitize_text_field((string)($item['subject'] ?? '')),
        'list_keys' => array_values(array_map('sanitize_key', (array)($item['list_keys'] ?? array()))),
        'list_labels' => array_values(array_map('sanitize_text_field', (array)($item['list_labels'] ?? array()))),
        'recipient_count' => absint($item['recipient_count'] ?? 0),
        'sent_count' => absint($item['sent_count'] ?? 0),
        'failed_count' => absint($item['failed_count'] ?? 0),
        'send_mode' => in_array(
          (string)($item['send_mode'] ?? 'marketing'),
          array('marketing', 'instructor'),
          true
        )
          ? (string)($item['send_mode'] ?? 'marketing')
          : 'marketing',
      );
    }

    $clean = array_slice($clean, 0, 250);
    update_option('mrm_pay_hub_marketing_sent_log', $clean, false);
  }

  private function mrm_marketing_add_sent_log_item(
    $subject,
    $list_keys,
    $recipient_count,
    $sent_count,
    $failed_count,
    $send_mode = 'marketing'
  ) {
    $defs = $this->mrm_marketing_default_lists();
    $labels = array();

    foreach ((array)$list_keys as $key) {
      $key = sanitize_key((string)$key);

      if (isset($defs[$key])) {
        $labels[] = (string)($defs[$key]['label'] ?? $key);
        continue;
      }

      $school_list = $this->mrm_marketing_parse_school_outreach_key($key);

      if (!empty($school_list)) {
        $labels[] = (string)$school_list['state_label']
          . ' — '
          . (string)$school_list['type_label'];
      }

      $state_instructor_list = $this->mrm_marketing_parse_state_instructor_key(
        $key
      );

      if (!empty($state_instructor_list)) {
        $labels[] = 'Instructors — '
          . (string)$state_instructor_list['state_label'];
      }

      $state_college_professor_list =
        $this->mrm_marketing_parse_state_college_professor_key(
          $key
        );

      if (!empty($state_college_professor_list)) {
        $labels[] = 'College Professors — '
          . (string)$state_college_professor_list[
            'state_label'
          ];
      }
    }

    $log = $this->mrm_marketing_sent_log();
    $log_id = 'send_' . wp_generate_uuid4();

    $send_mode = $send_mode === 'instructor'
      ? 'instructor'
      : 'marketing';

    array_unshift($log, array(
      'id' => sanitize_key($log_id),
      'sent_at' => current_time('mysql'),
      'subject' => sanitize_text_field((string)$subject),
      'list_keys' => array_values(
        array_map('sanitize_key', (array)$list_keys)
      ),
      'list_labels' => $labels,
      'recipient_count' => absint($recipient_count),
      'sent_count' => absint($sent_count),
      'failed_count' => absint($failed_count),
      'send_mode' => $send_mode,
    ));

    $this->mrm_marketing_save_sent_log($log);
  }

  private function mrm_marketing_upload_attachments_from_request() {
    if (empty($_FILES['mrm_marketing_attachments']) || empty($_FILES['mrm_marketing_attachments']['name'])) {
      return array('paths' => array(), 'errors' => array());
    }

    if (!function_exists('wp_handle_upload')) {
      require_once ABSPATH . 'wp-admin/includes/file.php';
    }

    $files = $_FILES['mrm_marketing_attachments'];
    $paths = array();
    $errors = array();

    $allowed_mimes = array(
      'pdf'  => 'application/pdf',
      'doc'  => 'application/msword',
      'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'jpg'  => 'image/jpeg',
      'jpeg' => 'image/jpeg',
      'png'  => 'image/png',
    );

    $max_files = 5;
    $max_bytes_per_file = 10 * 1024 * 1024;
    $count = is_array($files['name']) ? count($files['name']) : 0;
    if ($count > $max_files) {
      $errors[] = 'You can attach up to ' . $max_files . ' files per marketing email.';
      $count = $max_files;
    }

    for ($i = 0; $i < $count; $i++) {
      if (empty($files['name'][$i])) continue;
      if (!empty($files['error'][$i])) {
        $errors[] = 'Upload error for ' . sanitize_file_name((string)$files['name'][$i]) . '.';
        continue;
      }
      if ((int)$files['size'][$i] > $max_bytes_per_file) {
        $errors[] = sanitize_file_name((string)$files['name'][$i]) . ' is larger than 10MB.';
        continue;
      }

      $single_file = array(
        'name'     => sanitize_file_name((string)$files['name'][$i]),
        'type'     => (string)$files['type'][$i],
        'tmp_name' => (string)$files['tmp_name'][$i],
        'error'    => (int)$files['error'][$i],
        'size'     => (int)$files['size'][$i],
      );

      $upload = wp_handle_upload($single_file, array('test_form' => false, 'mimes' => $allowed_mimes));
      if (!empty($upload['error'])) {
        $errors[] = $single_file['name'] . ': ' . $upload['error'];
        continue;
      }
      if (!empty($upload['file']) && file_exists($upload['file'])) $paths[] = $upload['file'];
    }

    return array('paths' => $paths, 'errors' => $errors);
  }

  private function mrm_marketing_delete_temp_attachments($paths) {
    foreach ((array)$paths as $path) {
      $path = (string)$path;
      if ($path && file_exists($path)) @unlink($path);
    }
  }

  private function mrm_marketing_manual_list_example_html($def) {
    $example = isset($def['example']) ? trim((string)$def['example']) : '';
    if ($example === '') return '';
    return '<p style="margin:6px 0 10px 0;"><small><em>Example format:</em><br><code>' .
      esc_html($example) .
      '</code><br>Separate emails with new lines, commas, semicolons, or spaces.</small></p>';
  }

  public function handle_marketing_email_save_lists() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission to save marketing email lists.');
    }

    check_admin_referer(
      'mrm_marketing_email_save_lists',
      'mrm_marketing_email_lists_nonce'
    );

    $defs = $this->mrm_marketing_default_lists();
    $lists = $this->mrm_marketing_manual_lists();

    /*
     * Save normal manual lists, currently General Interest.
     */
    foreach ($defs as $key => $def) {
      if (($def['type'] ?? '') !== 'manual') {
        continue;
      }

      $field_name = 'mrm_marketing_list_' . $key;

      $raw = isset($_POST[$field_name])
        ? wp_unslash($_POST[$field_name])
        : '';

      $lists[$key] = $this->mrm_marketing_normalize_emails_from_text($raw);
    }

    /*
     * Save the four lists for the state currently shown in the admin page.
     */
    $states = $this->mrm_marketing_state_options();
    $types = $this->mrm_marketing_school_outreach_types();

    $selected_state = isset($_POST['mrm_marketing_state'])
      ? sanitize_key(
          wp_unslash($_POST['mrm_marketing_state'])
        )
      : '';

    if (isset($states[$selected_state])) {
      foreach ($types as $type_key => $type_def) {
        $list_key = $this->mrm_marketing_school_outreach_key(
          $selected_state,
          $type_key
        );

        if ($list_key === '') {
          continue;
        }

        $field_name = 'mrm_marketing_school_list_' . $type_key;

        $raw = isset($_POST[$field_name])
          ? wp_unslash($_POST[$field_name])
          : '';

        $lists[$list_key] = $this->mrm_marketing_normalize_emails_from_text($raw);
      }
    }

    /*
     * Save the college-professor list for the selected state.
     */
    if (isset($states[$selected_state])) {
      $professor_list_key =
        $this->mrm_marketing_state_college_professor_key(
          $selected_state
        );

      if ($professor_list_key !== '') {
        $raw_professor_emails = isset(
          $_POST['mrm_marketing_college_professor_emails']
        )
          ? wp_unslash(
              $_POST['mrm_marketing_college_professor_emails']
            )
          : '';

        $lists[$professor_list_key] =
          $this->mrm_marketing_normalize_emails_from_text(
            $raw_professor_emails
          );
      }
    }

    /*
     * Remove only obsolete non-school manual keys.
     * Preserve all valid generated school outreach keys.
     */
    foreach (array_keys($lists) as $key) {
      if (
        isset($defs[$key]) &&
        (($defs[$key]['type'] ?? '') === 'manual')
      ) {
        continue;
      }

      if (
        !empty(
          $this->mrm_marketing_parse_school_outreach_key($key)
        )
      ) {
        continue;
      }

      if (
        !empty(
          $this->mrm_marketing_parse_state_college_professor_key(
            $key
          )
        )
      ) {
        continue;
      }

      unset($lists[$key]);
    }

    $mailing_address = isset($_POST['mrm_marketing_mailing_address'])
      ? wp_kses_post(wp_unslash($_POST['mrm_marketing_mailing_address']))
      : '';

    update_option(
      'mrm_pay_hub_marketing_mailing_address',
      $mailing_address,
      false
    );

    $this->save_email_lists($lists);

    $redirect_args = array(
      'page' => 'mrm-pay-hub-marketing-email-lists',
      'mrm_marketing_saved' => '1',
    );

    if (isset($states[$selected_state])) {
      $redirect_args['mrm_state'] = $selected_state;
    }

    wp_safe_redirect(
      add_query_arg(
        $redirect_args,
        admin_url('admin.php')
      )
    );
    exit;
  }


  public function handle_marketing_delete_sent_log_item() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission to remove marketing email history.');
    }

    check_admin_referer(
      'mrm_marketing_delete_sent_log_item',
      'mrm_marketing_delete_sent_log_nonce'
    );

    $item_id = isset($_POST['mrm_marketing_sent_log_id'])
      ? sanitize_key(wp_unslash($_POST['mrm_marketing_sent_log_id']))
      : '';

    if ($item_id === '') {
      wp_safe_redirect(
        add_query_arg(
          array(
            'page' => 'mrm-pay-hub-marketing-email-lists',
            'mrm_marketing_log_deleted' => '0',
          ),
          admin_url('admin.php')
        )
      );
      exit;
    }

    $log = $this->mrm_marketing_sent_log();
    $new_log = array();
    $deleted = false;

    foreach ((array)$log as $item) {
      $current_id = sanitize_key((string)($item['id'] ?? ''));

      if (!$deleted && $current_id === $item_id) {
        $deleted = true;
        continue;
      }

      $new_log[] = $item;
    }

    if ($deleted) {
      $this->mrm_marketing_save_sent_log($new_log);
    }

    wp_safe_redirect(
      add_query_arg(
        array(
          'page' => 'mrm-pay-hub-marketing-email-lists',
          'mrm_marketing_log_deleted' => $deleted ? '1' : '0',
        ),
        admin_url('admin.php')
      )
    );
    exit;
  }

  public function handle_marketing_email_send() {
  if (!current_user_can('manage_options')) wp_die('You do not have permission to send marketing emails.');
  check_admin_referer('mrm_marketing_email_send', 'mrm_marketing_email_send_nonce');

  $subject = sanitize_text_field((string)($_POST['mrm_marketing_subject'] ?? ''));
  $raw_body = isset($_POST['mrm_marketing_html']) ? wp_unslash($_POST['mrm_marketing_html']) : '';
  $body_html = $this->mrm_marketing_allowed_html($raw_body);
  $selected_lists = isset($_POST['mrm_marketing_lists']) && is_array($_POST['mrm_marketing_lists']) ? array_map('sanitize_key', (array)$_POST['mrm_marketing_lists']) : array();
  $defs = $this->mrm_marketing_default_lists();
  $allowed_lists = array();

  foreach ($selected_lists as $list_key) {
    $school_list =
      $this->mrm_marketing_parse_school_outreach_key(
        $list_key
      );

    $state_instructor_list =
      $this->mrm_marketing_parse_state_instructor_key(
        $list_key
      );

    $state_college_professor_list =
      $this->mrm_marketing_parse_state_college_professor_key(
        $list_key
      );

    if (
      !isset($defs[$list_key]) &&
      empty($school_list) &&
      empty($state_instructor_list) &&
      empty($state_college_professor_list)
    ) {
      continue;
    }

    $allowed_lists[$list_key] = true;
  }

  $selected_lists = array_keys($allowed_lists);

  $send_mode = $this->mrm_marketing_selected_list_mode(
    $selected_lists
  );

  if ($send_mode === 'mixed') {
    wp_safe_redirect(
      add_query_arg(
        array(
          'page' => 'mrm-pay-hub-marketing-email-lists',
          'mrm_marketing_error' => rawurlencode(
            'Instructor correspondence lists cannot be combined with marketing or school outreach lists. Send instructor correspondence separately.'
          ),
        ),
        admin_url('admin.php')
      )
    );
    exit;
  }

  if ($subject === '' || trim(wp_strip_all_tags($body_html)) === '' || empty($selected_lists)) {
    wp_safe_redirect(add_query_arg(array(
      'page' => 'mrm-pay-hub-marketing-email-lists',
      'mrm_marketing_error' => rawurlencode('Subject, HTML body, and at least one list are required.'),
    ), admin_url('admin.php')));
    exit;
  }

  $apply_unsubscribe_suppression = $send_mode !== 'instructor';

  $recipients = $this->mrm_marketing_get_combined_recipients(
    $selected_lists,
    $apply_unsubscribe_suppression
  );
  if (empty($recipients)) {
    $no_recipients_message = $send_mode === 'instructor'
      ? 'No recipients found after deduplication.'
      : 'No recipients found after deduplication and unsubscribe suppression.';

    wp_safe_redirect(add_query_arg(array(
      'page' => 'mrm-pay-hub-marketing-email-lists',
      'mrm_marketing_error' => rawurlencode($no_recipients_message),
    ), admin_url('admin.php')));
    exit;
  }

  $attachment_result = $this->mrm_marketing_upload_attachments_from_request();
  $attachments = isset($attachment_result['paths']) ? (array)$attachment_result['paths'] : array();
  $attachment_errors = isset($attachment_result['errors']) ? (array)$attachment_result['errors'] : array();

  if (!empty($attachment_errors)) {
    $this->mrm_marketing_delete_temp_attachments($attachments);

    wp_safe_redirect(add_query_arg(array(
      'page' => 'mrm-pay-hub-marketing-email-lists',
      'mrm_marketing_error' => rawurlencode('Attachment problem: ' . implode(' ', $attachment_errors)),
    ), admin_url('admin.php')));
    exit;
  }

  $mailing_address = (string)get_option('mrm_pay_hub_marketing_mailing_address', '');
  $from_name = 'Low Brass Lessons';
  $from_email = 'no-reply@lowbrass-lessons.com';
  $headers = array(
    'Content-Type: text/html; charset=UTF-8',
    'From: ' . $from_name . ' <' . $from_email . '>',
    'Reply-To: ' . $from_name . ' <' . $from_email . '>',
  );

  $headers = array_values(
    array_filter(
      $headers,
      static function($header) {
        $header = strtolower(trim((string)$header));

        return strpos($header, 'cc:') !== 0
          && strpos($header, 'bcc:') !== 0
          && strpos($header, 'to:') !== 0;
      }
    )
  );

  $sent = 0;
  $failed = 0;

  /*
   * Privacy requirement:
   * Send one separate wp_mail() call per recipient.
   * Never pass the full recipient array to wp_mail() and never place
   * recipient lists in To, Cc, or Bcc headers.
   */
  foreach ($recipients as $email) {
    if ($send_mode === 'instructor') {
      /*
       * Instructor correspondence:
       * no marketing sentence, address, or unsubscribe link.
       */
      $final_html = $this->mrm_instructor_correspondence_build_email_html(
        $body_html
      );
    } else {
      /*
       * All customer, student, general-interest, purchaser,
       * subscriber, and school-outreach sends remain marketing sends.
       */
      $unsubscribe_url = $this->mrm_marketing_unsubscribe_url($email);

      $final_html = $this->mrm_marketing_build_email_html(
        $body_html,
        $unsubscribe_url,
        $mailing_address
      );
    }

    $ok = wp_mail(
      $email,
      $subject,
      $final_html,
      $headers,
      $attachments
    );

    if ($ok) {
      $sent++;
    } else {
      $failed++;
    }
  }

  $this->mrm_marketing_delete_temp_attachments($attachments);

  $this->mrm_marketing_add_sent_log_item(
    $subject,
    $selected_lists,
    count($recipients),
    $sent,
    $failed,
    $send_mode
  );

  wp_safe_redirect(add_query_arg(array(
    'page' => 'mrm-pay-hub-marketing-email-lists',
    'mrm_marketing_sent' => (string)$sent,
    'mrm_marketing_failed' => (string)$failed,
  ), admin_url('admin.php')));
  exit;
}

private function mrm_marketing_verify_recaptcha($response_token) {
  $response_token = trim(sanitize_text_field((string)$response_token));

  if ($response_token === '') {
    return false;
  }

  $scheduler_settings = get_option('mrm_scheduler_settings', array());
  $secret_key = is_array($scheduler_settings) && isset($scheduler_settings['contact_form_recaptcha_secret_key'])
    ? trim((string)$scheduler_settings['contact_form_recaptcha_secret_key'])
    : '';

  if ($secret_key === '') {
    return false;
  }

  $remote_ip = '';

  if (!empty($_SERVER['REMOTE_ADDR'])) {
    $remote_ip = sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR']));
  }

  $verification = wp_remote_post(
    'https://www.google.com/recaptcha/api/siteverify',
    array(
      'timeout' => 15,
      'body' => array(
        'secret' => $secret_key,
        'response' => $response_token,
        'remoteip' => $remote_ip,
      ),
    )
  );

  if (is_wp_error($verification)) {
    return false;
  }

  $status_code = wp_remote_retrieve_response_code($verification);

  if ($status_code !== 200) {
    return false;
  }

  $result = json_decode(wp_remote_retrieve_body($verification), true);

  if (!is_array($result)) {
    return false;
  }

  return !empty($result['success']);
}

private function mrm_marketing_signup_redirect_back($status) {
  $status = sanitize_key((string)$status);

  $fallback = home_url('/');
  $referer = wp_get_referer();

  $url = $referer ? $referer : $fallback;

  $url = remove_query_arg(array('mrm_marketing_signup_status'), $url);
  $url = add_query_arg('mrm_marketing_signup_status', $status, $url);

  wp_safe_redirect($url . '#mrm-general-interest-form-section');
  exit;
}

public function handle_marketing_general_interest_signup() {
  $nonce = isset($_POST['mrm_marketing_signup_nonce'])
    ? sanitize_text_field(wp_unslash($_POST['mrm_marketing_signup_nonce']))
    : '';

  if (!$nonce || !wp_verify_nonce($nonce, 'mrm_marketing_general_interest_signup')) {
    $this->mrm_marketing_signup_redirect_back('error');
  }

  $honeypot = isset($_POST['mrm_marketing_website'])
    ? trim(sanitize_text_field(wp_unslash($_POST['mrm_marketing_website'])))
    : '';

  if ($honeypot !== '') {
    $this->mrm_marketing_signup_redirect_back('error');
  }

  $loaded_at_ms = isset($_POST['mrm_marketing_loaded_at'])
    ? absint(wp_unslash($_POST['mrm_marketing_loaded_at']))
    : 0;

  $now_ms = (int) round(microtime(true) * 1000);
  $elapsed_ms = $loaded_at_ms > 0 ? ($now_ms - $loaded_at_ms) : 0;

  if ($loaded_at_ms <= 0 || $elapsed_ms < 2500 || $elapsed_ms > 7200000) {
    $this->mrm_marketing_signup_redirect_back('error');
  }

  $email = isset($_POST['mrm_marketing_email'])
    ? strtolower(sanitize_email(wp_unslash($_POST['mrm_marketing_email'])))
    : '';

  $consent = isset($_POST['mrm_marketing_consent'])
    ? sanitize_text_field(wp_unslash($_POST['mrm_marketing_consent']))
    : '';

  if (!$email || !is_email($email) || $consent !== '1') {
    $this->mrm_marketing_signup_redirect_back('error');
  }

  $recaptcha_response = isset($_POST['g-recaptcha-response'])
    ? sanitize_text_field(wp_unslash($_POST['g-recaptcha-response']))
    : '';

  if (!$this->mrm_marketing_verify_recaptcha($recaptcha_response)) {
    $this->mrm_marketing_signup_redirect_back('recaptcha');
  }

  $unsubscribed = $this->mrm_marketing_unsubscribed_emails();

  if (isset($unsubscribed[$email])) {
    $this->mrm_marketing_signup_redirect_back('unsubscribed');
  }

  $lists = $this->mrm_marketing_manual_lists();

  if (!isset($lists['general_interest']) || !is_array($lists['general_interest'])) {
    $lists['general_interest'] = array();
  }

  $already_exists = in_array($email, $lists['general_interest'], true);

  if (!$already_exists) {
    $lists['general_interest'][] = $email;
    $lists['general_interest'] = array_values(array_unique($lists['general_interest']));
    sort($lists['general_interest']);
    $this->save_email_lists($lists);
    $this->mrm_marketing_signup_redirect_back('joined');
  }

  $this->mrm_marketing_signup_redirect_back('already');
}

public function handle_marketing_resubscribe() {
  if (!current_user_can('manage_options')) {
    wp_die('You do not have permission to update marketing unsubscribes.');
  }

  check_admin_referer('mrm_marketing_resubscribe', 'mrm_marketing_resubscribe_nonce');

  $raw = isset($_POST['mrm_marketing_resubscribe_emails']) ? wp_unslash($_POST['mrm_marketing_resubscribe_emails']) : '';
  $emails_to_restore = $this->mrm_marketing_normalize_emails_from_text($raw);

  if (empty($emails_to_restore)) {
    wp_safe_redirect(add_query_arg(array(
      'page' => 'mrm-pay-hub-marketing-email-lists',
      'mrm_marketing_error' => rawurlencode('No valid emails were entered for re-subscribe.'),
    ), admin_url('admin.php')));
    exit;
  }

  $unsubscribed = $this->mrm_marketing_unsubscribed_emails();

  foreach ($emails_to_restore as $email) {
    unset($unsubscribed[$email]);
  }

  $this->mrm_marketing_save_unsubscribed_emails(array_keys($unsubscribed));

  wp_safe_redirect(add_query_arg(array(
    'page' => 'mrm-pay-hub-marketing-email-lists',
    'mrm_marketing_saved' => '1',
    'mrm_marketing_resubscribed' => (string)count($emails_to_restore),
  ), admin_url('admin.php')));
  exit;
}




