  private function mrm_profile_card_existing_instructor_by_email($email) {
    global $wpdb;

    $email = sanitize_email((string)$email);
    if (!is_email($email)) {
      return null;
    }

    $table = $wpdb->prefix . 'mrm_instructors';
    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
      return null;
    }

    $row = $wpdb->get_row(
      $wpdb->prepare("SELECT * FROM {$table} WHERE email = %s LIMIT 1", $email),
      ARRAY_A
    );

    return is_array($row) ? $row : null;
  }

  private function mrm_profile_card_existing_presenter_by_email($email) {
    global $wpdb;

    $email = sanitize_email((string)$email);
    if (!is_email($email)) {
      return null;
    }

    $table = $wpdb->prefix . 'mrm_masterclass_presenters';
    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
      return null;
    }

    $row = $wpdb->get_row(
      $wpdb->prepare("SELECT * FROM {$table} WHERE email = %s LIMIT 1", $email),
      ARRAY_A
    );

    return is_array($row) ? $row : null;
  }

  private function mrm_profile_card_private_upload_dir() {
    $uploads = wp_upload_dir();
    $base = trailingslashit($uploads['basedir']) . 'mrm-private/profile-card';

    if (!file_exists($base)) {
      wp_mkdir_p($base);
    }

    $index_file = trailingslashit($base) . 'index.html';
    if (!file_exists($index_file)) {
      file_put_contents($index_file, '');
    }

    $htaccess = trailingslashit($base) . '.htaccess';
    if (!file_exists($htaccess)) {
      file_put_contents($htaccess, "Deny from all\n");
    }

    return $base;
  }

  private function mrm_profile_card_handle_profile_image_upload($field_name) {
    $field_name = sanitize_key((string)$field_name);

    if (
      $field_name === '' ||
      empty($_FILES[$field_name]) ||
      empty($_FILES[$field_name]['name']) ||
      !empty($_FILES[$field_name]['error'])
    ) {
      return '';
    }

    if (!current_user_can('upload_files')) {
      /*
       * Public nopriv submissions will usually not have upload_files.
       * Allow this controlled public form upload through wp_handle_upload().
       */
    }

    require_once ABSPATH . 'wp-admin/includes/file.php';

    $overrides = array(
      'test_form' => false,
      'mimes' => array(
        'jpg|jpeg|jpe' => 'image/jpeg',
        'png'          => 'image/png',
        'gif'          => 'image/gif',
        'webp'         => 'image/webp',
      ),
    );

    $upload = wp_handle_upload($_FILES[$field_name], $overrides);

    if (!is_array($upload) || !empty($upload['error']) || empty($upload['url'])) {
      return '';
    }

    return esc_url_raw((string)$upload['url']);
  }

  private function mrm_profile_card_handle_private_fingerprint_upload($field_name) {
    $field_name = sanitize_key((string)$field_name);

    if (
      $field_name === '' ||
      empty($_FILES[$field_name]) ||
      empty($_FILES[$field_name]['name']) ||
      !empty($_FILES[$field_name]['error'])
    ) {
      return array();
    }

    $file = $_FILES[$field_name];

    $allowed_mimes = array(
      'image/jpeg',
      'image/png',
      'image/webp',
      'application/pdf',
    );

    $tmp_name = (string)($file['tmp_name'] ?? '');
    $mime = $tmp_name && function_exists('mime_content_type') ? mime_content_type($tmp_name) : '';

    if ($mime !== '' && !in_array($mime, $allowed_mimes, true)) {
      return array();
    }

    $private_dir = $this->mrm_profile_card_private_upload_dir();
    $original_name = sanitize_file_name((string)($file['name'] ?? 'fingerprint-card'));
    $ext = pathinfo($original_name, PATHINFO_EXTENSION);
    $safe_name = 'fingerprint-' . gmdate('Ymd-His') . '-' . wp_generate_password(10, false, false);

    if ($ext !== '') {
      $safe_name .= '.' . strtolower($ext);
    }

    $destination = trailingslashit($private_dir) . $safe_name;

    if (!move_uploaded_file($tmp_name, $destination)) {
      return array();
    }

    return array(
      'name' => $original_name,
      'display_name' => $original_name,
      'stored_name' => basename($destination),
      'file' => $destination,
      'uploaded_at' => current_time('mysql'),
    );
  }

  private function mrm_profile_card_availability_guide_image_urls() {
    $settings = $this->get_settings();

    $urls = array();

    foreach (array('availability_guide_image_url_1', 'availability_guide_image_url_2', 'availability_guide_image_url_3') as $key) {
      $url = esc_url_raw((string)($settings[$key] ?? ''));
      if ($url !== '') {
        $urls[] = $url;
      }
    }

    return $urls;
  }

  private function mrm_profile_card_render_instructor_pay_chart_html() {
    $settings = $this->get_settings();

    /*
     * Public instructor profile-card acknowledgement chart.
     *
     * In-person lessons should visually show the online payout plus the
     * $5 travel add-on, so instructors can clearly see the full amount.
     */
    $travel_cents = 500;

    $amount_cents = function($key, $default = 0) use ($settings) {
      return max(0, (int)($settings[$key] ?? $default));
    };

    $money = function($cents) {
      return '$' . number_format(max(0, (int)$cents) / 100, 2);
    };

    $p30_y1 = $amount_cents('instructor_payout_30_online_year1_cents');
    $p30_y2 = $amount_cents('instructor_payout_30_online_year2_cents');
    $p30_y3 = $amount_cents('instructor_payout_30_online_year3_cents');

    $p60_y1 = $amount_cents('instructor_payout_60_online_year1_cents');
    $p60_y2 = $amount_cents('instructor_payout_60_online_year2_cents');
    $p60_y3 = $amount_cents('instructor_payout_60_online_year3_cents');

    return implode('', array(
      '<div class="mrm-profile-public-pay-box">',
        '<h3>Instructor Payout Acknowledgement</h3>',
        '<p>Please review the current instructor payout chart before submitting your profile card.</p>',
        '<table>',
          '<thead>',
            '<tr>',
              '<th>Lesson Type</th>',
              '<th>Year 1</th>',
              '<th>Year 2</th>',
              '<th>Year 3+</th>',
            '</tr>',
          '</thead>',
          '<tbody>',
            '<tr>',
              '<td>30-minute online</td>',
              '<td>' . esc_html($money($p30_y1)) . '</td>',
              '<td>' . esc_html($money($p30_y2)) . '</td>',
              '<td>' . esc_html($money($p30_y3)) . '</td>',
            '</tr>',
            '<tr>',
              '<td>30-minute in-person</td>',
              '<td>' . esc_html($money($p30_y1 + $travel_cents)) . '</td>',
              '<td>' . esc_html($money($p30_y2 + $travel_cents)) . '</td>',
              '<td>' . esc_html($money($p30_y3 + $travel_cents)) . '</td>',
            '</tr>',
            '<tr>',
              '<td>60-minute online</td>',
              '<td>' . esc_html($money($p60_y1)) . '</td>',
              '<td>' . esc_html($money($p60_y2)) . '</td>',
              '<td>' . esc_html($money($p60_y3)) . '</td>',
            '</tr>',
            '<tr>',
              '<td>60-minute in-person</td>',
              '<td>' . esc_html($money($p60_y1 + $travel_cents)) . '</td>',
              '<td>' . esc_html($money($p60_y2 + $travel_cents)) . '</td>',
              '<td>' . esc_html($money($p60_y3 + $travel_cents)) . '</td>',
            '</tr>',
          '</tbody>',
        '</table>',
        '<p class="mrm-field-help">In-person lessons have an added $5.00 to account for travel costs.</p>',
      '</div>',
    ));
  }

  private function mrm_profile_card_presenter_approval_where_sql($table_alias = '') {
    global $wpdb;

    $presenters_table = $wpdb->prefix . 'mrm_masterclass_presenters';
    $columns = $this->mrm_profile_card_table_columns($presenters_table);

    $prefix = $table_alias !== '' ? sanitize_key($table_alias) . '.' : '';

    $clauses = array();

    if (in_array('status', $columns, true)) {
      $clauses[] = $prefix . "status IN ('approved','active','published')";
    }

    if (in_array('profile_status', $columns, true)) {
      $clauses[] = $prefix . "profile_status IN ('approved','active','published')";
    }

    if (in_array('is_approved', $columns, true)) {
      $clauses[] = $prefix . "is_approved = 1";
    }

    if (in_array('approved', $columns, true)) {
      $clauses[] = $prefix . "approved = 1";
    }

    /*
     * If the presenter table has no approval/status column, do not block.
     * Some builds only insert approved presenters into this table.
     */
    if (empty($clauses)) {
      return '1=1';
    }

    return '(' . implode(' OR ', $clauses) . ')';
  }

  private function mrm_profile_card_presenter_is_approved($presenter_id) {
    global $wpdb;

    $presenter_id = absint($presenter_id);

    if ($presenter_id <= 0) {
      return false;
    }

    $table = $wpdb->prefix . 'mrm_masterclass_presenters';

    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
      return false;
    }

    $where = $this->mrm_profile_card_presenter_approval_where_sql('');

    $row = $wpdb->get_row(
      $wpdb->prepare(
        "SELECT *
         FROM {$table}
         WHERE id = %d
           AND {$where}
         LIMIT 1",
        $presenter_id
      ),
      ARRAY_A
    );

    return is_array($row) && !empty($row['id']);
  }

  private function mrm_profile_card_table_columns($table) {
    global $wpdb;

    $columns = $wpdb->get_col("DESC {$table}", 0);

    return is_array($columns) ? $columns : array();
  }

  private function mrm_profile_card_filter_data_for_table($table, $data) {
    $data = is_array($data) ? $data : array();
    $columns = $this->mrm_profile_card_table_columns($table);

    if (empty($columns)) {
      return $data;
    }

    return array_intersect_key($data, array_flip($columns));
  }

  private function mrm_profile_card_decode_metadata_from_row($row) {
    $row = is_array($row) ? $row : array();

    foreach (array('profile_metadata_json', 'metadata_json') as $key) {
      if (!empty($row[$key])) {
        $decoded = json_decode((string)$row[$key], true);
        if (is_array($decoded)) {
          return $decoded;
        }
      }
    }

    return array();
  }

  private function mrm_profile_card_existing_profile_submission_payload($request_type, $existing_target_id) {
    global $wpdb;

    $request_type = sanitize_key((string)$request_type);
    $existing_target_id = absint($existing_target_id);

    if ($existing_target_id <= 0) {
      return array();
    }

    if ($request_type === 'instructor_profile') {
      $table = $wpdb->prefix . 'mrm_instructors';
    } elseif ($request_type === 'presenter_profile') {
      $table = $wpdb->prefix . 'mrm_masterclass_presenters';
    } else {
      return array();
    }

    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
      return array();
    }

    $row = $wpdb->get_row(
      $wpdb->prepare("SELECT * FROM {$table} WHERE id = %d LIMIT 1", $existing_target_id),
      ARRAY_A
    );

    if (!is_array($row) || empty($row['id'])) {
      return array();
    }

    $metadata = $this->mrm_profile_card_decode_metadata_from_row($row);

    $name = trim((string)($row['name'] ?? ''));
    $first_name = '';
    $last_name = '';

    if ($name !== '') {
      $parts = preg_split('/\s+/', $name);
      $first_name = (string)array_shift($parts);
      $last_name = trim(implode(' ', $parts));
    }

    $payload = array(
      'first_name' => $first_name,
      'last_name' => $last_name,
      'name' => $name,
      'email' => sanitize_email((string)($row['email'] ?? '')),
      'city' => sanitize_text_field((string)($row['city'] ?? '')),
      'state' => strtoupper(substr(sanitize_text_field((string)($row['state'] ?? '')), 0, 2)),
      'address' => sanitize_text_field((string)($row['address'] ?? '')),
      'zip_code' => sanitize_text_field((string)($row['zip_code'] ?? '')),
      'profile_image_url' => esc_url_raw((string)($row['profile_image_url'] ?? '')),
      'short_description' => wp_kses_post((string)($row['short_description'] ?? '')),
      'long_description' => wp_kses_post((string)($row['long_description'] ?? $row['bio'] ?? '')),
      'website_url' => esc_url_raw((string)($metadata['website_url'] ?? '')),
      'instagram_url' => esc_url_raw((string)($metadata['instagram_url'] ?? '')),
      'facebook_url' => esc_url_raw((string)($metadata['facebook_url'] ?? '')),
      'youtube_url' => esc_url_raw((string)($metadata['youtube_url'] ?? '')),
      'linkedin_url' => esc_url_raw((string)($metadata['linkedin_url'] ?? '')),
    );

    if ($request_type === 'instructor_profile') {
      $payload['instructor_title'] = sanitize_text_field((string)(
        $row['instructor_title']
        ?? $metadata['instructor_title']
        ?? ''
      ));

      $payload['offers_in_person'] = !empty($row['offers_in_person']) ? 1 : 0;
      $payload['offers_online'] = !empty($row['offers_online']) ? 1 : 0;

      $instruments = array();

      if (!empty($row['instruments'])) {
        $decoded_instruments = json_decode((string)$row['instruments'], true);
        if (is_array($decoded_instruments)) {
          $instruments = $decoded_instruments;
        }
      }

      $payload['instruments'] = array_values(array_filter(array_map('sanitize_text_field', (array)$instruments)));
    }

    if ($request_type === 'presenter_profile') {
      $payload['presenter_title'] = sanitize_text_field((string)(
        $row['presenter_title']
        ?? $metadata['presenter_title']
        ?? ''
      ));
    }

    return array_filter($payload, function($value) {
      return $value !== '' && $value !== array() && $value !== null;
    });
  }

  private function mrm_profile_card_instructor_approved_archive_payload($instructor_id, $instructor_row = array()) {
    global $wpdb;

    $instructor_id = absint($instructor_id);
    $instructor_row = is_array($instructor_row) ? $instructor_row : array();

    if ($instructor_id <= 0) {
      return array();
    }

    $metadata = $this->mrm_profile_card_decode_metadata_from_row($instructor_row);

    if (!empty($metadata['approved_profile_card_payload']) && is_array($metadata['approved_profile_card_payload'])) {
      return $this->mrm_profile_card_complete_submission_payload(
        'instructor_profile',
        $metadata['approved_profile_card_payload']
      );
    }

    $requests_table = $this->table_profile_card_requests();

    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $requests_table)) !== $requests_table) {
      return $this->mrm_profile_card_existing_profile_submission_payload('instructor_profile', $instructor_id);
    }

    $request = $wpdb->get_row(
      $wpdb->prepare(
        "SELECT submission_payload
         FROM {$requests_table}
         WHERE status = 'approved'
           AND created_target_type = 'instructor'
           AND created_target_id = %d
         ORDER BY reviewed_at DESC, id DESC
         LIMIT 1",
        $instructor_id
      ),
      ARRAY_A
    );

    if (is_array($request) && !empty($request['submission_payload'])) {
      $payload = $this->mrm_profile_card_decode_json($request['submission_payload']);
      return $this->mrm_profile_card_complete_submission_payload('instructor_profile', $payload);
    }

    return $this->mrm_profile_card_existing_profile_submission_payload('instructor_profile', $instructor_id);
  }

  private function mrm_profile_card_instructor_approved_archive_uploads($instructor_id, $instructor_row = array()) {
    global $wpdb;

    $instructor_id = absint($instructor_id);
    $instructor_row = is_array($instructor_row) ? $instructor_row : array();

    if ($instructor_id <= 0) {
      return array();
    }

    $metadata = $this->mrm_profile_card_decode_metadata_from_row($instructor_row);

    $metadata_uploads = array();

    if (!empty($metadata['approved_profile_card_uploaded_files']) && is_array($metadata['approved_profile_card_uploaded_files'])) {
      $metadata_uploads = $metadata['approved_profile_card_uploaded_files'];
    }

    if (!empty($metadata['approved_profile_card_payload']) && is_array($metadata['approved_profile_card_payload'])) {
      $metadata_uploads = $this->mrm_profile_card_merge_uploads_with_payload(
        $metadata_uploads,
        $metadata['approved_profile_card_payload']
      );
    }

    $metadata_uploads = array_map(
      array($this, 'mrm_profile_card_normalize_private_upload_file'),
      $metadata_uploads
    );

    if (!empty($metadata_uploads)) {
      return $metadata_uploads;
    }

    $requests_table = $this->table_profile_card_requests();

    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $requests_table)) !== $requests_table) {
      return array();
    }

    $request = $wpdb->get_row(
      $wpdb->prepare(
        "SELECT uploaded_files, submission_payload
         FROM {$requests_table}
         WHERE status = 'approved'
           AND created_target_type = 'instructor'
           AND created_target_id = %d
         ORDER BY reviewed_at DESC, id DESC
         LIMIT 1",
        $instructor_id
      ),
      ARRAY_A
    );

    if (is_array($request)) {
      $uploads = $this->mrm_profile_card_decode_json($request['uploaded_files'] ?? '');
      $payload = $this->mrm_profile_card_decode_json($request['submission_payload'] ?? '');

      return array_map(
        array($this, 'mrm_profile_card_normalize_private_upload_file'),
        $this->mrm_profile_card_merge_uploads_with_payload($uploads, $payload)
      );
    }

    return array();
  }

  private function mrm_profile_card_add_profile_metadata_to_record($table, &$data, $payload, $request_type = '', $uploaded_files = array()) {
    $data = is_array($data) ? $data : array();
    $payload = is_array($payload) ? $payload : array();
    $uploaded_files = is_array($uploaded_files) ? $uploaded_files : array();

    $metadata = array(
      'instructor_title' => sanitize_text_field((string)($payload['instructor_title'] ?? '')),
      'presenter_title' => sanitize_text_field((string)($payload['presenter_title'] ?? '')),
      'website_url' => esc_url_raw((string)($payload['website_url'] ?? '')),
      'instagram_url' => esc_url_raw((string)($payload['instagram_url'] ?? '')),
      'facebook_url' => esc_url_raw((string)($payload['facebook_url'] ?? '')),
      'youtube_url' => esc_url_raw((string)($payload['youtube_url'] ?? '')),
      'linkedin_url' => esc_url_raw((string)($payload['linkedin_url'] ?? '')),
      'fingerprint_clearance_status' => sanitize_key((string)($payload['fingerprint_clearance_status'] ?? '')),
      'background_check_docusign_ack' => !empty($payload['background_check_docusign_ack']) ? 1 : 0,
      'docusign_completed' => !empty($payload['docusign_completed']) ? 1 : 0,
      'stripe_onboarding_completed' => !empty($payload['stripe_onboarding_completed']) ? 1 : 0,
      'calendar_availability_completed' => !empty($payload['calendar_availability_completed']) ? 1 : 0,
    );

    $request_type = sanitize_key((string)$request_type);

    if ($request_type !== '') {
      $metadata['approved_profile_card_payload'] = $this->mrm_profile_card_complete_submission_payload($request_type, $payload);
      if (!empty($uploaded_files)) {
        $metadata['approved_profile_card_uploaded_files'] = array_values($uploaded_files);
      }
      $metadata['approved_profile_card_saved_at'] = current_time('mysql');
    }

    $metadata = array_filter($metadata, function($value) {
      return $value !== '' && $value !== null && $value !== array();
    });

    $columns = $this->mrm_profile_card_table_columns($table);

    if (in_array('profile_metadata_json', $columns, true)) {
      $data['profile_metadata_json'] = wp_json_encode($metadata);
    } elseif (in_array('metadata_json', $columns, true)) {
      $data['metadata_json'] = wp_json_encode($metadata);
    } elseif (in_array('notes', $columns, true) && !empty($metadata)) {
      $data['notes'] = trim((string)($data['notes'] ?? '') . "\n\nProfile Card Metadata:\n" . wp_json_encode($metadata, JSON_PRETTY_PRINT));
    }

    /*
     * Important: strip fields that do not exist in the target table so approving
     * a request cannot fail with “Unknown column” errors.
     */
    $data = $this->mrm_profile_card_filter_data_for_table($table, $data);
  }

