  private function mrm_profile_card_review_field_label($key, $request_type = '') {
    $labels = $this->mrm_profile_card_review_field_labels($request_type);
    $key = (string)$key;
    $request_type = sanitize_key((string)$request_type);

    if ($request_type === 'presenter_event') {
      $event_labels = array(
        'event_title' => 'Masterclass Event Title',
        'short_description' => 'Short Listing Description',
        'long_description' => 'Full Masterclass Description',
        'session_details' => 'Session Details',
        'preparation_notes' => 'Preparation Notes',
        'masterclass_piece_title' => 'Selected Piece',
        'masterclass_piece_sku' => 'Selected Piece SKU',
        'masterclass_piece_url' => 'Selected Piece URL',
        'start_time' => 'Proposed Start Time',
        'end_time' => 'Proposed End Time',
        'timezone' => 'Timezone',
        'pay_ack' => 'Payout Acknowledgement',
      );

      if (isset($event_labels[$key])) {
        return $event_labels[$key];
      }
    }

    return isset($labels[$key]) ? $labels[$key] : ucwords(str_replace('_', ' ', $key));
  }

  private function mrm_profile_card_review_field_order($request_type, $payload) {
    $request_type = sanitize_key((string)$request_type);
    $payload = is_array($payload) ? $payload : array();

    if ($request_type === 'presenter_event') {
      $preferred = array(
        'event_title',
        'masterclass_piece_title',
        'masterclass_piece_sku',
        'masterclass_piece_url',
        'short_description',
        'long_description',
        'session_details',
        'preparation_notes',
        'start_time',
        'end_time',
        'timezone',
        'pay_ack',
      );
    } elseif ($request_type === 'presenter_profile') {
      $preferred = array(
        'first_name',
        'last_name',
        'name',
        'email',
        'city',
        'state',
        'address',
        'zip_code',
        'presenter_title',
        'short_description',
        'long_description',
        'profile_image_url',
        'website_url',
        'instagram_url',
        'facebook_url',
        'youtube_url',
        'linkedin_url',
      );
    } else {
      $preferred = array(
        'first_name',
        'last_name',
        'name',
        'email',
        'city',
        'state',
        'address',
        'zip_code',
        'offers_online',
        'offers_in_person',
        'instruments',
        'instructor_title',
        'short_description',
        'long_description',
        'profile_image_url',
        'fingerprint_clearance_status',
        'fingerprint_card_name',
        'calendar_availability_completed',
        'pay_ack',
        'website_url',
        'instagram_url',
        'facebook_url',
        'youtube_url',
        'linkedin_url',
      );
    }

    $hidden = array(
      'profile_social_links_json',
      'fingerprint_card_file',
      'fingerprint_card_uploaded_at',
      'docusign_completed',
      'stripe_onboarding_completed',
      'background_check_docusign_ack',
      'event_short_description',
      'event_full_description',
      'selected_piece_title',
      'selected_piece_sku',
      'selected_piece_url',
    );

    $ordered = array();
    $seen = array();

    foreach (array_merge($preferred, array_keys($payload)) as $key) {
      $key = (string)$key;

      if ($key === '' || isset($seen[$key]) || in_array($key, $hidden, true)) {
        continue;
      }

      $seen[$key] = true;
      $ordered[] = $key;
    }

    return $ordered;
  }

  private function mrm_profile_card_review_value_html($key, $value) {
    if (is_array($value)) {
      return empty($value) ? '<span style="color:#777;">—</span>' : '<pre style="white-space:pre-wrap;margin:0;">' . esc_html(wp_json_encode($value, JSON_PRETTY_PRINT)) . '</pre>';
    }

    $value = (string)$value;
    if ($value === '') {
      return '<span style="color:#777;">—</span>';
    }
    if (in_array($value, array('1', '0'), true)) {
      return $value === '1' ? 'Yes' : 'No';
    }
    if (filter_var($value, FILTER_VALIDATE_URL)) {
      return '<a href="' . esc_url($value) . '" target="_blank" rel="noopener noreferrer">' . esc_html($value) . '</a>';
    }

    return wp_kses_post(nl2br(esc_html($value)));
  }

  private function mrm_profile_card_sanitize_field_comments_from_post($raw_comments) {
    $raw_comments = is_array($raw_comments) ? $raw_comments : array();
    $comments = array();

    foreach ($raw_comments as $key => $comment) {
      $key = sanitize_key((string)$key);
      $comment = sanitize_textarea_field(wp_unslash($comment));
      if ($key === '' || trim($comment) === '') {
        continue;
      }
      $comments[$key] = $comment;
    }

    return $comments;
  }

  private function mrm_profile_card_field_comments_list_html($field_comments, $request_type = '') {
    $field_comments = is_array($field_comments) ? $field_comments : array();
    if (empty($field_comments)) {
      return '';
    }
    $html = '<ul style="margin:8px 0 0 18px;padding:0;">';
    foreach ($field_comments as $key => $comment) {
      $html .= '<li style="margin-bottom:8px;"><strong>' . esc_html($this->mrm_profile_card_review_field_label($key, $request_type)) . ':</strong> ' . nl2br(esc_html((string)$comment)) . '</li>';
    }
    return $html . '</ul>';
  }

  private function mrm_profile_card_send_changes_requested_email($request, $form_url, $note = '', $field_comments = array()) {
    $request = is_array($request) ? $request : array();
    $request_type = sanitize_key((string)($request['request_type'] ?? ''));
    $intro_html = '<p>Hello,</p><p>Low Brass Lessons has reviewed your submitted profile card or event request and requested changes before approval.</p>';
    $details_html = '<div><strong>Requested changes:</strong></div>';
    $details_html .= '<div>' . ($note !== '' ? nl2br(esc_html($note)) : 'Please review and update the requested form details.') . '</div>';
    $comment_list = $this->mrm_profile_card_field_comments_list_html($field_comments, $request_type);
    if ($comment_list !== '') {
      $details_html .= '<div style="margin-top:16px;"><strong>Field-specific comments:</strong>' . $comment_list . '</div>';
    }
    $details_html .= '<div style="margin-top:16px;">Please use this private link to update and resubmit your request: <a href="' . esc_url($form_url) . '">' . esc_html($form_url) . '</a></div>';
    $changes_body = $this->mrm_email_wrap_html('Profile Card Changes Requested', $intro_html, $details_html, '', '');

    return wp_mail((string)($request['recipient_email'] ?? ''), 'Low Brass Lessons requested changes', $changes_body, array('Content-Type: text/html; charset=UTF-8'));
  }

  private function mrm_profile_card_render_review_payload_table($request, $payload, $field_comments = array(), $commentable = true) {
    $request = is_array($request) ? $request : array();
    $payload = is_array($payload) ? $payload : array();
    $field_comments = is_array($field_comments) ? $field_comments : array();
    $request_type = sanitize_key((string)($request['request_type'] ?? ''));
    $admin_payload = is_array($request['admin_payload_decoded'] ?? null) ? $request['admin_payload_decoded'] : array();

    $payload = $this->mrm_profile_card_complete_submission_payload($request_type, $payload, $admin_payload);

    $display_only_keys = array(
      'masterclass_piece_title',
      'masterclass_piece_sku',
      'masterclass_piece_url',
      'start_time',
      'end_time',
      'timezone',
    );

    echo '<table class="widefat striped mrm-profile-review-table" style="width:100%;table-layout:fixed;">';
    echo '<thead>';
    echo '<tr>';
    echo '<th style="width:220px;">Field</th>';
    echo '<th>Value</th>';

    if ($commentable) {
      echo '<th style="width:360px;">Admin Comment for Request Changes</th>';
    }

    echo '</tr>';
    echo '</thead>';
    echo '<tbody>';

    foreach ($this->mrm_profile_card_review_field_order($request_type, $payload) as $key) {
      $value = array_key_exists($key, $payload) ? $payload[$key] : '';
      $comment_value = (string)($field_comments[$key] ?? '');
      $is_display_only = in_array((string)$key, $display_only_keys, true);

      echo '<tr>';
      echo '<th style="vertical-align:top;">' . esc_html($this->mrm_profile_card_review_field_label($key, $request_type)) . '<br><code>' . esc_html($key) . '</code></th>';
      echo '<td style="vertical-align:top;white-space:normal;word-break:break-word;">' . $this->mrm_profile_card_review_value_html($key, $value) . '</td>';

      if ($commentable) {
        echo '<td style="vertical-align:top;">';

        if ($is_display_only) {
          echo '<span class="description">Display-only request detail. To change this, create a new request with the corrected setup details.</span>';
        } else {
          echo '<textarea name="field_comments[' . esc_attr($key) . ']" rows="3" class="large-text" placeholder="Optional comment for this field.">' . esc_textarea($comment_value) . '</textarea>';
        }

        echo '</td>';
      }

      echo '</tr>';
    }

    echo '</tbody>';
    echo '</table>';
  }

  private function mrm_profile_card_piece_options() {
    $products = $this->all_products();
    $pieces = array();

    foreach ((array)$products as $sku => $product) {
      if (!is_array($product)) {
        continue;
      }

      if ((string)($product['product_type'] ?? '') !== 'sheet_music') {
        continue;
      }

      $sku = sanitize_text_field((string)$sku);

      if ($sku === '' || $sku === $this->mrm_master_all_sheet_music_sku() || $sku === 'all-sheet-music') {
        continue;
      }

      $parsed = $this->mrm_parse_piece_sku_labels($sku);

      if (empty($parsed['is_piece']) || empty($parsed['piece_slug'])) {
        continue;
      }

      $piece_slug = sanitize_title((string)$parsed['piece_slug']);
      $piece_title = sanitize_text_field((string)($parsed['piece_title'] ?? ''));

      if ($piece_slug === '' || $piece_title === '') {
        continue;
      }

      $category = sanitize_key((string)($parsed['category'] ?? ''));
      $url = $this->mrm_get_piece_page_url_from_sku($sku);

      if (!isset($pieces[$piece_slug])) {
        $pieces[$piece_slug] = array(
          'sku' => $sku,
          'title' => $piece_title,
          'url' => $url,
          'category' => $category,
        );
      }

      if ($category === 'complete-package') {
        $pieces[$piece_slug]['sku'] = $sku;
        $pieces[$piece_slug]['url'] = $url;
        $pieces[$piece_slug]['category'] = $category;
      }
    }

    uasort($pieces, function($a, $b) {
      return strcasecmp((string)($a['title'] ?? ''), (string)($b['title'] ?? ''));
    });

    return array_values($pieces);
  }

  private function mrm_profile_card_piece_select_html($selected_sku = '') {
    $selected_sku = sanitize_text_field((string)$selected_sku);
    $pieces = $this->mrm_profile_card_piece_options();

    $html = '<select id="masterclass_piece_sku" name="masterclass_piece_sku">';
    $html .= '<option value="">Select the piece being discussed</option>';

    foreach ($pieces as $piece) {
      $sku = sanitize_text_field((string)($piece['sku'] ?? ''));
      $title = sanitize_text_field((string)($piece['title'] ?? ''));

      if ($sku === '' || $title === '') {
        continue;
      }

      $html .= '<option value="' . esc_attr($sku) . '"' . selected($selected_sku, $sku, false) . '>';
      $html .= esc_html($title);
      $html .= '</option>';
    }

    $html .= '</select>';

    if (empty($pieces)) {
      $html .= '<p class="description" style="color:#b32d2e;">No sheet music piece products were found in the Payment Hub product collection.</p>';
    } else {
      $html .= '<p class="description">Choose the piece that will be discussed in this masterclass. This will be used in the masterclass registration/reminder emails so students can access the correct piece.</p>';
    }

    return $html;
  }

  private function mrm_profile_card_piece_from_sku($sku) {
    $sku = sanitize_text_field((string)$sku);

    if ($sku === '') {
      return array(
        'sku' => '',
        'title' => '',
        'url' => '',
      );
    }

    foreach ($this->mrm_profile_card_piece_options() as $piece) {
      if ((string)($piece['sku'] ?? '') === $sku) {
        return array(
          'sku' => sanitize_text_field((string)($piece['sku'] ?? '')),
          'title' => sanitize_text_field((string)($piece['title'] ?? '')),
          'url' => esc_url_raw((string)($piece['url'] ?? '')),
        );
      }
    }

    return array(
      'sku' => '',
      'title' => '',
      'url' => '',
    );
  }

  private function mrm_profile_card_invite_email_parts($request_type, $label = '', $days_label = '', $admin_note = '', $selected_piece = array()) {
    $request_type = sanitize_key((string)$request_type);
    $label = trim((string)$label);
