  public function render_instructor_profiles_page() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission to view this page.');
    }

    global $wpdb;
    $this->maybe_install_or_upgrade_db();
    $instructors_table = $wpdb->prefix . 'mrm_instructors';

    echo '<div class="wrap"><h1>Instructor Profiles</h1>';
    echo '<p class="description">Review existing instructor profile cards, leave field-specific comments, and request profile card updates from current instructors.</p>';

    $instructor_search = sanitize_text_field(wp_unslash($_GET['s'] ?? ''));

    echo '<form method="get" style="margin:16px 0;padding:14px;background:#fff;border:1px solid #dcdcde;border-radius:12px;display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;">';
    echo '<input type="hidden" name="page" value="mrm-pay-hub-instructor-profiles">';
    echo '<p style="margin:0;min-width:280px;flex:1;">';
    echo '<label for="mrm_instructor_profile_search"><strong>Search instructors</strong></label><br>';
    echo '<input type="search" id="mrm_instructor_profile_search" name="s" value="' . esc_attr($instructor_search) . '" class="regular-text" placeholder="Search by name, email, state, or title">';
    echo '</p>';
    echo '<p style="margin:0;">';
    echo '<button type="submit" class="button button-primary">Search</button> ';
    echo '<a class="button" href="' . esc_url(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles')) . '">Clear</a>';
    echo '</p>';
    echo '</form>';

    if (isset($_GET['update_sent'])) {
      echo '<div class="notice notice-success"><p>Instructor profile update request sent.</p></div>';
    }
    if (isset($_GET['manual_updated'])) {
      echo '<div class="notice notice-success"><p>Instructor profile card fields were manually updated.</p></div>';
    }
    if (isset($_GET['error'])) {
      echo '<div class="notice notice-error"><p>' . esc_html(sanitize_text_field(wp_unslash($_GET['error']))) . '</p></div>';
    }
    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $instructors_table)) !== $instructors_table) {
      echo '<div class="notice notice-error"><p>The instructors table could not be found.</p></div></div>';
      return;
    }

    if ($instructor_search !== '') {
      $like = '%' . $wpdb->esc_like($instructor_search) . '%';

      $instructors = $wpdb->get_results(
        $wpdb->prepare(
          "SELECT *
           FROM {$instructors_table}
           WHERE name LIKE %s
              OR email LIKE %s
              OR state LIKE %s
           ORDER BY name ASC, email ASC
           LIMIT 300",
          $like,
          $like,
          $like
        ),
        ARRAY_A
      );
    } else {
      $instructors = $wpdb->get_results(
        "SELECT *
         FROM {$instructors_table}
         ORDER BY name ASC, email ASC
         LIMIT 300",
        ARRAY_A
      );
    }

    if (empty($instructors)) {
      if ($instructor_search !== '') {
        echo '<p>No instructors matched your search.</p></div>';
      } else {
        echo '<p>No instructors were found.</p></div>';
      }
      return;
    }

    echo '<div style="display:grid;gap:18px;margin-top:18px;">';
    foreach ($instructors as $instructor) {
      $instructor_id = absint($instructor['id'] ?? 0);
      $payload = $this->mrm_profile_card_existing_profile_submission_payload('instructor_profile', $instructor_id);
      $archive_payload = $this->mrm_profile_card_instructor_approved_archive_payload($instructor_id, $instructor);
      $archive_uploads = $this->mrm_profile_card_instructor_approved_archive_uploads($instructor_id, $instructor);
      echo '<div style="background:#fff;border:1px solid #dcdcde;border-radius:14px;padding:18px;">';
      echo '<div style="display:flex;justify-content:space-between;gap:18px;align-items:flex-start;flex-wrap:wrap;">';
      echo '<div><h2 style="margin:0 0 8px 0;">' . esc_html((string)($instructor['name'] ?? 'Instructor #' . $instructor_id)) . '</h2><p style="margin:0;"><code>' . esc_html((string)($instructor['email'] ?? '')) . '</code></p></div>';
      echo '<div style="min-width:240px;"><p style="margin:0;"><strong>ID:</strong> ' . esc_html((string)$instructor_id) . '</p><p style="margin:4px 0 0;"><strong>State:</strong> ' . esc_html((string)($instructor['state'] ?? '—')) . '</p><p style="margin:4px 0 0;"><strong>Title:</strong> ' . esc_html((string)($payload['instructor_title'] ?? '—')) . '</p></div>';
      echo '</div><details style="margin-top:14px;"><summary class="button">Review / Request Profile Changes</summary>';
      echo '<form method="post" action="' . esc_url(admin_url('admin-post.php')) . '" style="margin-top:14px;padding:16px;border:1px solid #dcdcde;background:#fbfbfb;border-radius:12px;">';
      wp_nonce_field('mrm_profile_card_request_existing_instructor_update', 'mrm_profile_card_existing_instructor_nonce');
      echo '<input type="hidden" name="action" value="mrm_profile_card_request_existing_instructor_update"><input type="hidden" name="instructor_id" value="' . esc_attr($instructor_id) . '">';
      echo '<p><label><strong>Instructor Google Calendar Link</strong></label><br><input type="url" name="instructor_calendar_url" class="large-text" required placeholder="https://calendar.google.com/..."></p>';
      echo '<p><label><strong>Overall change request note</strong></label><br><textarea name="change_request_note" rows="4" class="large-text" placeholder="Write the general reason you are requesting updates. Field-specific comments below will also be included."></textarea></p>';
      echo '<p><label><strong>Link expiration</strong></label><br><input type="number" name="token_days" min="1" max="60" value="14" class="small-text"> days</p>';
      echo '<h3>Current Instructor Profile Content</h3><p class="description">Leave comments beside any field that should be changed. These comments will appear beside the matching field when the instructor opens the update form.</p>';
      $this->mrm_profile_card_render_review_payload_table(array('request_type' => 'instructor_profile'), $payload, array(), true);
      echo '<p style="margin-top:18px;"><button type="submit" class="button button-primary">Request Profile Card Changes</button></p>';
      echo '</form></details>';

      echo '<details style="margin-top:14px;">';
      echo '<summary class="button">View Saved Approved Profile Card Form</summary>';
      echo '<div style="margin-top:14px;padding:16px;border:1px solid #dcdcde;background:#fbfbfb;border-radius:12px;">';
      echo '<h3>Saved Approved Profile Card Form</h3>';
      echo '<p class="description">This is the saved approved profile-card snapshot. It is preserved for future reference even after manual edits are made.</p>';
      $this->mrm_profile_card_render_review_payload_table(array('request_type' => 'instructor_profile'), $archive_payload, array(), false);
      $this->mrm_profile_card_render_uploaded_file_previews($archive_uploads, $archive_payload);
      echo '</div>';
      echo '</details>';

      echo '<details style="margin-top:14px;">';
      echo '<summary class="button button-primary">Manually Edit Profile Card Fields</summary>';
      $this->mrm_profile_card_render_manual_instructor_edit_form($instructor_id, $payload);
      echo '</details>';

      echo '</div>';
    }
    echo '</div></div>';
  }



  private function mrm_tax_seed_state_rows() {
    global $wpdb;
    $table = $this->table_tax_state_status();
    $now = current_time('mysql');
    $states = array('AL'=>'Alabama','AK'=>'Alaska','AZ'=>'Arizona','AR'=>'Arkansas','CA'=>'California','CO'=>'Colorado','CT'=>'Connecticut','DE'=>'Delaware','FL'=>'Florida','GA'=>'Georgia','HI'=>'Hawaii','ID'=>'Idaho','IL'=>'Illinois','IN'=>'Indiana','IA'=>'Iowa','KS'=>'Kansas','KY'=>'Kentucky','LA'=>'Louisiana','ME'=>'Maine','MD'=>'Maryland','MA'=>'Massachusetts','MI'=>'Michigan','MN'=>'Minnesota','MS'=>'Mississippi','MO'=>'Missouri','MT'=>'Montana','NE'=>'Nebraska','NV'=>'Nevada','NH'=>'New Hampshire','NJ'=>'New Jersey','NM'=>'New Mexico','NY'=>'New York','NC'=>'North Carolina','ND'=>'North Dakota','OH'=>'Ohio','OK'=>'Oklahoma','OR'=>'Oregon','PA'=>'Pennsylvania','RI'=>'Rhode Island','SC'=>'South Carolina','SD'=>'South Dakota','TN'=>'Tennessee','TX'=>'Texas','UT'=>'Utah','VT'=>'Vermont','VA'=>'Virginia','WA'=>'Washington','WV'=>'West Virginia','WI'=>'Wisconsin','WY'=>'Wyoming','DC'=>'District of Columbia');
    foreach ($states as $code => $name) {
      $existing = $wpdb->get_var($wpdb->prepare("SELECT state_code FROM {$table} WHERE state_code = %s", $code));
      if ($existing) continue;
      $general_status = 'statewide';
      if (in_array($code, array('DE','MT','NH','OR'), true)) $general_status = 'no_general_state_sales_tax';
      if ($code === 'AK') $general_status = 'local_sales_tax_only';
      $wpdb->insert($table, array('state_code'=>$code,'state_name'=>$name,'general_sales_tax_status'=>$general_status,'threshold_rule_verified'=>0,'rules_version'=>self::TAX_RULES_VERSION,'authority_registration_status'=>'not_started','stripe_registration_status'=>'none','collection_active'=>0,'created_at'=>$now,'updated_at'=>$now));
    }
    $az = $wpdb->get_row("SELECT physical_nexus_flag, first_flagged_at FROM {$table} WHERE state_code = 'AZ'", ARRAY_A);
    if ($az && empty($az['physical_nexus_flag'])) {
      $wpdb->update($table, array('physical_nexus_flag'=>1,'physical_nexus_reason'=>'Low Brass Lessons home-state business presence.','first_flagged_at'=>$now,'updated_at'=>$now), array('state_code'=>'AZ'));
    }
    $this->mrm_tax_seed_initial_rules();
  }



  private function
  mrm_tax_alert_email_claim_is_expired(
    $claimed_at,
    $minutes = 15
  ) {
    $minutes = max(1, min(1440, absint($minutes)));
    $claimed_at = sanitize_text_field((string) $claimed_at);
    if ($claimed_at === '') return true;
    try {
      $claim_time = new DateTimeImmutable($claimed_at, wp_timezone());
      $expires_at = $claim_time->modify('+' . $minutes . ' minutes');
      $now = new DateTimeImmutable('now', wp_timezone());
      return $expires_at <= $now;
    } catch (Throwable $error) {
      /* A malformed timestamp cannot be trusted as an active claim. */
      return true;
    }
  }

  private function
  mrm_tax_transition_stale_alert_email_claim_to_uncertain($alert) {
    global $wpdb;
    if (!is_array($alert)) return new WP_Error('tax_alert_email_claim_row_invalid', 'The email claim record is invalid.');
    $alert_id = absint($alert['id'] ?? 0);
    $email_status = sanitize_key($alert['email_status'] ?? '');
    $claim_token = sanitize_text_field($alert['email_claim_token'] ?? '');
    $claimed_at = sanitize_text_field($alert['email_claimed_at'] ?? '');
    if ($alert_id <= 0) return new WP_Error('tax_alert_email_claim_id_invalid', 'The email claim alert ID is invalid.');
    if ($email_status !== 'sending') return false;
    if (!$this->mrm_tax_alert_email_claim_is_expired($claimed_at, 15)) return false;
    $table = $this->table_tax_alerts();
    $now = current_time('mysql');
    $message = 'A previous sending claim expired before its final state was confirmed. Automatic resend was suppressed to prevent a duplicate.';
    $wpdb->last_error = '';
    if ($claim_token !== '') {
      $changed = $wpdb->query($wpdb->prepare("UPDATE {$table} SET email_status = 'uncertain', email_claim_token = NULL, email_last_error = %s, updated_at = %s, alert_revision = alert_revision + 1 WHERE id = %d AND alert_status = 'open' AND email_status = 'sending' AND email_claim_token = %s", $message, $now, $alert_id, $claim_token));
    } else {
      $changed = $wpdb->query($wpdb->prepare("UPDATE {$table} SET email_status = 'uncertain', email_claim_token = NULL, email_last_error = %s, updated_at = %s, alert_revision = alert_revision + 1 WHERE id = %d AND alert_status = 'open' AND email_status = 'sending' AND (email_claim_token IS NULL OR email_claim_token = '')", $message, $now, $alert_id));
    }
    if ($changed === false || $wpdb->last_error !== '') return new WP_Error('tax_alert_email_stale_claim_update_failed', $wpdb->last_error ?: 'The expired email claim could not be marked uncertain.');
    if ((int) $changed === 0) return false;
    $wpdb->last_error = '';
    $verified = $wpdb->get_var($wpdb->prepare("SELECT email_status FROM {$table} WHERE id = %d LIMIT 1", $alert_id));
    if ($wpdb->last_error !== '' || sanitize_key($verified) !== 'uncertain') return new WP_Error('tax_alert_email_stale_claim_unverified', $wpdb->last_error ?: 'The expired email claim transition could not be verified.');
    return true;
  }

  private function
  mrm_tax_cleanup_stale_alert_email_claims($limit = 100) {
    global $wpdb;
    $limit = max(1, min(500, absint($limit)));
    $cutoff = (new DateTimeImmutable('now', wp_timezone()))->modify('-15 minutes')->format('Y-m-d H:i:s');
    $table = $this->table_tax_alerts();
    $wpdb->last_error = '';
    $rows = $wpdb->get_results($wpdb->prepare("SELECT id, email_status, email_claim_token, email_claimed_at FROM {$table} WHERE alert_status = 'open' AND email_status = 'sending' AND (email_claimed_at IS NULL OR email_claimed_at <= %s) ORDER BY email_claimed_at ASC, id ASC LIMIT %d", $cutoff, $limit), ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('tax_alert_stale_claim_query_failed', $wpdb->last_error);
    $transitioned = 0; $errors = array();
    foreach ((array) $rows as $row) {
      $result = $this->mrm_tax_transition_stale_alert_email_claim_to_uncertain($row);
      if (is_wp_error($result)) {
        $errors[] = array('alert_id'=>absint($row['id'] ?? 0), 'code'=>$result->get_error_code(), 'message'=>$result->get_error_message());
        continue;
      }
      if ($result === true) $transitioned++;
    }
    return array('transitioned'=>$transitioned, 'errors'=>$errors);
  }

  private function
  mrm_tax_append_alert_email_recovery_history($details_json, $event) {
    $details = json_decode((string) $details_json, true);
    if (!is_array($details)) $details = array();
    $history = isset($details['email_recovery_history']) && is_array($details['email_recovery_history']) ? $details['email_recovery_history'] : array();
    $event = is_array($event) ? $event : array();
    if (empty($event['recorded_at'])) $event['recorded_at'] = current_time('mysql');
    if (!array_key_exists('administrator_id', $event)) $event['administrator_id'] = get_current_user_id();
    $history[] = $event;
    $details['email_recovery_history'] = $history;
    $details['email_recovery_last_resolution'] = $event;
    return wp_json_encode($details);
  }

  private function
  mrm_tax_merge_alert_details_preserving_recovery($new_details, $existing_details_json) {
    $new_details = is_array($new_details) ? $new_details : array();
    $existing_details = json_decode((string) $existing_details_json, true);
    if (!is_array($existing_details)) return $new_details;
    foreach (array('email_recovery_history', 'email_recovery_last_resolution') as $key) {
      if (array_key_exists($key, $existing_details)) $new_details[$key] = $existing_details[$key];
    }
    return $new_details;
  }

  private function mrm_tax_attempt_alert_email($alert_id) {
    global $wpdb; $alert_id=absint($alert_id);
    if($alert_id<=0)return new WP_Error('tax_alert_email_id_invalid','The tax-alert email ID is invalid.');
    $table=$this->table_tax_alerts(); $wpdb->last_error='';
    $alert=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d LIMIT 1",$alert_id),ARRAY_A);
    if($wpdb->last_error!=='')return new WP_Error('tax_alert_email_lookup_failed',$wpdb->last_error);
    if(!is_array($alert))return new WP_Error('tax_alert_email_missing','The tax alert no longer exists.');
    $alert_status=sanitize_key($alert['alert_status']??'');
    if($alert_status!=='open')return new WP_Error('tax_alert_email_already_resolved','The tax alert has already been resolved. No email was sent.');
    $status=sanitize_key($alert['email_status']??''); if($status==='')$status=!empty($alert['emailed_at'])?'sent':'not_sent';
    if(in_array($status,array('sent','waived'),true))return $alert_id;
    if($status==='uncertain')return new WP_Error('tax_alert_email_uncertain','The email delivery state is uncertain and requires administrator review.');
    if ($status === 'sending') {
      $transition = $this->mrm_tax_transition_stale_alert_email_claim_to_uncertain($alert);
      if (is_wp_error($transition)) return $transition;
      if ($transition === true) return new WP_Error('tax_alert_email_uncertain', 'The previous email attempt expired with an uncertain delivery state and requires administrator review.');
      return new WP_Error('tax_alert_email_in_progress', 'Another process is currently sending this alert email.');
    }
    if(!in_array($status,array('not_sent','failed'),true))return new WP_Error('tax_alert_email_status_invalid','The tax alert has an unsupported email status.');
    $recipient=sanitize_email(get_option('admin_email'));
    if ($recipient === '' || !is_email($recipient)) {
      $now = current_time('mysql');
      $error_message = 'The WordPress administrator email address is missing or invalid.';
      $wpdb->last_error = '';
      $failed = $wpdb->query($wpdb->prepare("UPDATE {$table} SET email_status = 'failed', email_claim_token = NULL, email_claimed_at = NULL, email_last_attempt_at = %s, email_last_error = %s, updated_at = %s WHERE id = %d AND alert_status = 'open' AND email_status IN ('not_sent', 'failed')", $now, $error_message, $now, $alert_id));
      if ($failed === false || $wpdb->last_error !== '') return new WP_Error('tax_alert_email_recipient_failure_save_failed', $wpdb->last_error ?: 'The invalid-recipient email state could not be saved.');
      if ((int) $failed !== 1) return new WP_Error('tax_alert_email_recipient_state_changed', 'The alert email state changed before the invalid recipient could be recorded.');
      $wpdb->last_error = '';
      $verified = $wpdb->get_row($wpdb->prepare("SELECT email_status, email_last_error FROM {$table} WHERE id = %d LIMIT 1", $alert_id), ARRAY_A);
      if ($wpdb->last_error !== '' || !is_array($verified) || sanitize_key($verified['email_status'] ?? '') !== 'failed' || sanitize_text_field($verified['email_last_error'] ?? '') !== $error_message) return new WP_Error('tax_alert_email_recipient_failure_unverified', $wpdb->last_error ?: 'The invalid-recipient email state could not be verified.');
      return new WP_Error('tax_alert_email_recipient_invalid', $error_message);
    }
    $token=wp_generate_uuid4();$now=current_time('mysql');$wpdb->last_error='';
    $claimed=$wpdb->query($wpdb->prepare("UPDATE {$table} SET email_status='sending',email_claim_token=%s,email_claimed_at=%s,email_last_attempt_at=%s,email_last_error=NULL,updated_at=%s WHERE id=%d AND alert_status='open' AND email_status IN ('not_sent','failed')",$token,$now,$now,$now,$alert_id));
    if($claimed===false||$wpdb->last_error!=='')return new WP_Error('tax_alert_email_claim_failed',$wpdb->last_error?:'The tax-alert email could not be claimed.');
    if((int)$claimed!==1)return new WP_Error('tax_alert_email_claim_unavailable','Another process claimed the alert email first.');
    $wpdb->last_error='';$verified=$wpdb->get_row($wpdb->prepare("SELECT email_status,email_claim_token FROM {$table} WHERE id=%d LIMIT 1",$alert_id),ARRAY_A);
    if($wpdb->last_error!==''||!is_array($verified)||sanitize_key($verified['email_status']??'')!=='sending'||!hash_equals($token,(string)($verified['email_claim_token']??'')))return new WP_Error('tax_alert_email_claim_unverified','The tax-alert email claim could not be verified.');
    $details=json_decode((string)($alert['details_json']??''),true);if(!is_array($details))$details=array();$type=sanitize_key($alert['alert_type']??'');$state=$this->mrm_normalize_state_code($alert['state_code']??'');$message=sanitize_textarea_field($details['message']??'A sales-tax issue requires attention.');
    $subject=sprintf('Sales Tax Alert: %s%s',str_replace('_',' ',ucwords($type,'_')),$state!==''?' — '.$state:'');
    $sent=wp_mail($recipient,$subject,$message."\n\nAlert type: ".$type."\nState: ".($state!==''?$state:'Not specified'));
    if (!$sent) {
      $wpdb->last_error='';
      $failed=$wpdb->query($wpdb->prepare("UPDATE {$table} SET email_status='failed',email_claim_token=NULL,email_last_error=%s,updated_at=%s WHERE id=%d AND email_status='sending' AND email_claim_token=%s",'wp_mail() returned false.',$now,$alert_id,$token));
      if($failed===false||$wpdb->last_error!==''||(int)$failed!==1){
        $wpdb->last_error = '';
        $uncertain = $wpdb->query($wpdb->prepare("UPDATE {$table} SET email_status = 'uncertain', email_claim_token = NULL, email_last_error = %s, updated_at = %s WHERE id = %d AND email_status = 'sending' AND email_claim_token = %s", 'wp_mail() returned false, but the failed state could not be verified. Automatic resend was suppressed.', $now, $alert_id, $token));
        if ($uncertain === false || $wpdb->last_error !== '') error_log('MRM could not preserve the uncertain email state for alert #' . $alert_id . ': ' . ($wpdb->last_error ?: 'The claim state changed before the fallback update.'));
        return new WP_Error('tax_alert_email_failure_state_unverified',$wpdb->last_error?:'The failed email state could not be verified.');
      }
      return new WP_Error('tax_alert_email_send_failed','WordPress mail did not accept the tax-alert email.');
    }
    $wpdb->last_error='';$sent_saved=$wpdb->query($wpdb->prepare("UPDATE {$table} SET email_status='sent',email_claim_token=NULL,emailed_at=%s,email_last_error=NULL,updated_at=%s WHERE id=%d AND email_status='sending' AND email_claim_token=%s",$now,$now,$alert_id,$token));
    if($sent_saved===false||$wpdb->last_error!==''||(int)$sent_saved!==1){
      $wpdb->last_error = '';
      $uncertain = $wpdb->query($wpdb->prepare("UPDATE {$table} SET email_status = 'uncertain', email_claim_token = NULL, email_last_error = %s, updated_at = %s WHERE id = %d AND email_status = 'sending' AND email_claim_token = %s", 'WordPress mail accepted the message, but the sent state could not be persisted. Automatic resend was suppressed.', $now, $alert_id, $token));
      if ($uncertain === false || $wpdb->last_error !== '') error_log('MRM could not preserve the post-send uncertain state for alert #' . $alert_id . ': ' . ($wpdb->last_error ?: 'The claim state changed before the fallback update.'));
      return new WP_Error('tax_alert_email_sent_state_unverified', 'WordPress mail accepted the email, but its sent state could not be verified. Automatic resend was suppressed.');
    }
    $wpdb->last_error='';$verified=$wpdb->get_row($wpdb->prepare("SELECT email_status,emailed_at FROM {$table} WHERE id=%d LIMIT 1",$alert_id),ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('tax_alert_email_sent_state_read_failed', $wpdb->last_error);
    if (!is_array($verified) || sanitize_key($verified['email_status'] ?? '') !== 'sent' || empty($verified['emailed_at'])) return new WP_Error('tax_alert_email_sent_state_unverified', 'The tax-alert email sent state could not be verified without risking an overwrite of a newer state.');
    return $alert_id;
  }

  private function mrm_tax_create_alert(
    $state, $alert_type, $source_type = '', $source_id = 0,
    $details = array(), $deduplication_key = ''
  ) {
    global $wpdb;
    $state = $this->mrm_normalize_state_code($state);
    $alert_type = substr(sanitize_key($alert_type), 0, 64);
    $source_type = substr(sanitize_key($source_type), 0, 64);
    $source_id = absint($source_id);
    $details = is_array($details) ? $details : array();
    if ($alert_type === '') return new WP_Error('tax_alert_type_missing', 'The tax alert type was missing.');
    $deduplication_key = sanitize_key((string) $deduplication_key);
    if ($deduplication_key === '') {
      $deduplication_key = substr(sha1(wp_json_encode(array(
        'state'=>$state, 'alert_type'=>$alert_type, 'source_type'=>$source_type,
        'source_id'=>$source_id, 'details'=>$details,
      ))), 0, 40);
    }
    $alert_key = substr('mrm_tax_' . $alert_type . '_' . $deduplication_key, 0, 191);
    $table = $this->table_tax_alerts();
    $alert_id = 0;
    /* Two attempts allow one reload after a concurrent administrator action or alert refresh. */
    for ($attempt = 0; $attempt < 2; $attempt++) {
      $wpdb->last_error = '';
      $existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE alert_key = %s LIMIT 1", $alert_key), ARRAY_A);
      if ($wpdb->last_error !== '') return new WP_Error('tax_alert_lookup_failed', $wpdb->last_error);
      if (!is_array($existing)) {
        $now = current_time('mysql');
        $inserted = $wpdb->insert($table, array(
          'alert_key'=>$alert_key, 'alert_revision'=>1, 'state_code'=>$state,
          'alert_type'=>$alert_type, 'alert_status'=>'open', 'source_type'=>$source_type,
          'source_id'=>$source_id, 'details_json'=>wp_json_encode($details),
          'email_status'=>'not_sent', 'created_at'=>$now, 'updated_at'=>$now,
        ));
        if ($inserted !== false && $wpdb->last_error === '' && absint($wpdb->insert_id) > 0) {
          $alert_id = absint($wpdb->insert_id); break;
        }
        /* A concurrent request may have inserted the same unique alert key. */
        $wpdb->last_error = '';
        $concurrent_row = $wpdb->get_row($wpdb->prepare("SELECT id FROM {$table} WHERE alert_key = %s LIMIT 1", $alert_key), ARRAY_A);
        if (is_array($concurrent_row) && $attempt === 0) continue;
        return new WP_Error('tax_alert_save_failed', $wpdb->last_error ?: 'The tax alert could not be created.');
      }
      $alert_id = absint($existing['id'] ?? 0);
      if ($alert_id <= 0) return new WP_Error('tax_alert_id_invalid', 'The existing tax alert has an invalid ID.');
      $expected_revision = max(1, absint($existing['alert_revision'] ?? 1));
      $expected_status = sanitize_key($existing['alert_status'] ?? '');
      if ($expected_status === '') $expected_status = 'open';
      $merged_details = $this->mrm_tax_merge_alert_details_preserving_recovery($details, $existing['details_json'] ?? '');
      $details_json = wp_json_encode($merged_details);
      $now = current_time('mysql');
      $reopening = $expected_status !== 'open';
      $wpdb->last_error = '';
      if ($reopening) {
        $updated = $wpdb->query($wpdb->prepare(
          "UPDATE {$table} SET state_code = %s, alert_type = %s, alert_status = 'open', source_type = %s, source_id = %d, details_json = %s, email_status = 'not_sent', email_claim_token = NULL, email_claimed_at = NULL, email_last_attempt_at = NULL, email_last_error = NULL, emailed_at = NULL, resolved_at = NULL, updated_at = %s, alert_revision = alert_revision + 1 WHERE id = %d AND alert_status = %s AND alert_revision = %d",
          $state, $alert_type, $source_type, $source_id, $details_json, $now,
          $alert_id, $expected_status, $expected_revision
        ));
      } else {
        $updated = $wpdb->query($wpdb->prepare(
          "UPDATE {$table} SET state_code = %s, alert_type = %s, source_type = %s, source_id = %d, details_json = %s, resolved_at = NULL, updated_at = %s, alert_revision = alert_revision + 1 WHERE id = %d AND alert_status = 'open' AND alert_revision = %d",
          $state, $alert_type, $source_type, $source_id, $details_json, $now,
          $alert_id, $expected_revision
        ));
      }
      if ($updated === false || $wpdb->last_error !== '') return new WP_Error('tax_alert_save_failed', $wpdb->last_error ?: 'The tax alert could not be updated.');
      if ((int) $updated === 1) break;
      $wpdb->last_error = '';
      $latest = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d LIMIT 1", $alert_id), ARRAY_A);
      if ($wpdb->last_error !== '' || !is_array($latest)) return new WP_Error('tax_alert_concurrency_reload_failed', $wpdb->last_error ?: 'The concurrently modified tax alert could not be reloaded.');
      $latest_status = sanitize_key($latest['alert_status'] ?? '');
      /* A newer lifecycle decision wins over a stale refresh. */
      if ($latest_status !== $expected_status) return $alert_id;
      if ($attempt === 0) continue;
      return new WP_Error('tax_alert_concurrent_update_failed', 'The tax alert changed repeatedly while it was being refreshed.');
    }
    if ($alert_id <= 0) return new WP_Error('tax_alert_save_failed', 'The tax alert could not be stored.');
    /* Email handling cannot fail the surrounding payment operation. */
    $email_result = $this->mrm_tax_attempt_alert_email($alert_id);
    if (is_wp_error($email_result)) error_log('MRM tax-alert email pending for alert #' . $alert_id . ': ' . $email_result->get_error_message());
    return $alert_id;
  }

  private function mrm_tax_retry_failed_alert_emails($limit=25) {
    global $wpdb;$limit=max(1,min(100,absint($limit)));
    $cleanup_result=$this->mrm_tax_cleanup_stale_alert_email_claims($limit);
    if(is_wp_error($cleanup_result))return $cleanup_result;
    $errors=!empty($cleanup_result['errors'])&&is_array($cleanup_result['errors'])?$cleanup_result['errors']:array();
    $stale_claims_transitioned=absint($cleanup_result['transitioned']??0);
    $wpdb->last_error='';$rows=$wpdb->get_results($wpdb->prepare("SELECT id FROM {$this->table_tax_alerts()} WHERE alert_status='open' AND email_status IN ('not_sent','failed') ORDER BY COALESCE(email_last_attempt_at,created_at) ASC,id ASC LIMIT %d",$limit),ARRAY_A);
    if($wpdb->last_error!=='')return new WP_Error('tax_alert_email_retry_query_failed',$wpdb->last_error);$attempted=0;foreach((array)$rows as $row){$id=absint($row['id']??0);if($id<=0)continue;$attempted++;$result=$this->mrm_tax_attempt_alert_email($id);if(is_wp_error($result))$errors[]=array('alert_id'=>$id,'code'=>$result->get_error_code(),'message'=>$result->get_error_message());}
    return array('attempted'=>$attempted,'stale_claims_transitioned'=>$stale_claims_transitioned,'errors'=>$errors);
  }

  private function mrm_tax_resolve_review_alert($alert_type, $refund_id, $resolution) {
    global $wpdb;
    $alert_type = sanitize_key($alert_type);
    $refund_id = sanitize_text_field($refund_id);
    $resolution = is_array($resolution) ? $resolution : array();
    if ($alert_type === '' || $refund_id === '') return new WP_Error('tax_review_resolution_invalid', 'The refund review resolution reference was invalid.');
    $table = $this->table_tax_alerts();
    $like = '%"refund_id":"' . $wpdb->esc_like($refund_id) . '"%';
    $wpdb->last_error = '';
    $rows = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} WHERE alert_status = 'open' AND alert_type = %s AND details_json LIKE %s", $alert_type, $like), ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('tax_review_alert_lookup_failed', $wpdb->last_error);
    if (empty($rows)) return new WP_Error('tax_review_alert_missing', 'No matching open refund review alert was found.');
    foreach ($rows as $initial_row) {
      $alert_id = absint($initial_row['id'] ?? 0);
      if ($alert_id <= 0) return new WP_Error('tax_review_alert_id_invalid', 'A matching refund-review alert had an invalid ID.');
      $resolved = false;
      for ($attempt = 0; $attempt < 2; $attempt++) {
        if ($attempt === 0) $row = $initial_row;
        else {
          $wpdb->last_error = '';
          $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d LIMIT 1", $alert_id), ARRAY_A);
          if ($wpdb->last_error !== '' || !is_array($row)) return new WP_Error('tax_review_alert_reload_failed', $wpdb->last_error ?: 'The refund-review alert could not be reloaded.');
        }
        if (sanitize_key($row['alert_status'] ?? '') !== 'open') { $resolved = true; break; }
        $expected_revision = max(1, absint($row['alert_revision'] ?? 1));
        $details = json_decode((string) ($row['details_json'] ?? ''), true);
        if (!is_array($details)) $details = array();
        /* Starting with the latest row retains existing email recovery history. */
        $details['resolution'] = $resolution;
        $now = current_time('mysql');
        $wpdb->last_error = '';
        $updated = $wpdb->query($wpdb->prepare(
          "UPDATE {$table} SET details_json = %s, alert_status = 'resolved', resolved_at = %s, updated_at = %s, alert_revision = alert_revision + 1 WHERE id = %d AND alert_status = 'open' AND alert_revision = %d",
          wp_json_encode($details), $now, $now, $alert_id, $expected_revision
        ));
        if ($updated === false || $wpdb->last_error !== '') return new WP_Error('tax_review_alert_resolution_failed', $wpdb->last_error ?: 'The refund-review alert could not be resolved.');
        if ((int) $updated === 1) { $resolved = true; break; }
        /* A concurrent update occurred; reload and merge the latest details once. */
      }
      if (!$resolved) return new WP_Error('tax_review_alert_concurrent_resolution_failed', 'The refund-review alert changed repeatedly while it was being resolved.');
    }
    return true;
  }

  private function mrm_tax_resolve_alerts_by_reference($detail_key, $reference, $alert_types = array()) {
    global $wpdb; $allowed = array('payment_intent_id','refund_id','invoice_id','subscription_id','customer_id'); $detail_key = sanitize_key($detail_key); $reference = sanitize_text_field($reference); if (!in_array($detail_key,$allowed,true) || $reference === '') return false;
    $alert_types = array_values(array_filter(array_map('sanitize_key', (array)$alert_types))); $like = '%"' . $wpdb->esc_like($detail_key) . '":"' . $wpdb->esc_like($reference) . '"%'; $now=current_time('mysql');
    $sql="UPDATE {$this->table_tax_alerts()} SET alert_status = 'resolved', resolved_at = %s, updated_at = %s, alert_revision = alert_revision + 1 WHERE alert_status = 'open' AND details_json LIKE %s"; $args=array($now,$now,$like);
    if (!empty($alert_types)) { $sql .= ' AND alert_type IN (' . implode(',', array_fill(0, count($alert_types), '%s')) . ')'; $args = array_merge($args, $alert_types); }
    $wpdb->last_error=''; $result=$wpdb->query($wpdb->prepare($sql,$args)); if ($result===false || $wpdb->last_error!=='') return new WP_Error('tax_alert_resolution_failed', $wpdb->last_error ?: 'The tax alert could not be resolved.'); return true;
  }

  private function mrm_tax_resolve_alert_type($alert_type) { global $wpdb; $alert_type=sanitize_key($alert_type); if($alert_type==='') return false; $now=current_time('mysql'); $wpdb->last_error=''; $result=$wpdb->query($wpdb->prepare("UPDATE {$this->table_tax_alerts()} SET alert_status = 'resolved', resolved_at = %s, updated_at = %s, alert_revision = alert_revision + 1 WHERE alert_status = 'open' AND alert_type = %s", $now, $now, $alert_type)); if($result===false || $wpdb->last_error!=='') return new WP_Error('tax_alert_type_resolution_failed', $wpdb->last_error ?: 'The tax alerts could not be resolved.'); return true; }

  private function mrm_tax_email_attention_alerts($limit=100) {
    global $wpdb;$limit=max(1,min(200,absint($limit)));
    $cleanup_result=$this->mrm_tax_cleanup_stale_alert_email_claims($limit);
    if(is_wp_error($cleanup_result))return $cleanup_result;
    if(!empty($cleanup_result['errors']))foreach($cleanup_result['errors'] as $cleanup_error)error_log('MRM stale tax-alert email claim cleanup failed for alert #'.absint($cleanup_error['alert_id']??0).': '.sanitize_textarea_field($cleanup_error['message']??'Unknown stale-claim cleanup error.'));
    $types=array('stripe_activation_notification_pending','stripe_activation_postprocessing_failed');$ph=implode(',',array_fill(0,count($types),'%s'));
    $sql="SELECT * FROM {$this->table_tax_alerts()} WHERE alert_status='open' AND (email_status IN ('not_sent','failed','sending','uncertain') OR alert_type IN ({$ph})) ORDER BY updated_at DESC,id DESC LIMIT %d";$wpdb->last_error='';$rows=$wpdb->get_results($wpdb->prepare($sql,array_merge($types,array($limit))),ARRAY_A);
    if($wpdb->last_error!=='')return new WP_Error('tax_alert_email_attention_query_failed',$wpdb->last_error);return is_array($rows)?$rows:array();
  }

  private function mrm_tax_critical_open_alerts($limit = 50) { global $wpdb; $limit=max(1,min(200,absint($limit))); $types = array(
      'stripe_registration_sync_failed',
      'tax_ledger_sync_failed',
      'refund_tax_reversal_unresolved',
      'refund_lifecycle_reconciliation_failed',
      'refund_failure_recovery_required',
      'partial_refund_business_review_required',
      'subscription_direct_refund_review_required',
      'subscription_invoice_ledger_failed',
      'subscription_invoice_tax_failed',
      'subscription_credit_note_sync_failed',
      'subscription_global_tax_pause_failed',
      'subscription_tax_pause_failed',
      'subscription_local_sync_failed',
      'subscription_inventory_reconciliation_failed',
      'subscription_invoice_hold_failed',
      'customer_subscription_reconciliation_failed',
      'subscription_tax_configuration_invalid',
      'subscription_invoice_processing_failed',
      'subscription_invoice_lifecycle_reconciliation_failed',
    ); $ph=implode(',',array_fill(0,count($types),'%s')); $sql="SELECT * FROM {$this->table_tax_alerts()} WHERE alert_status = 'open' AND alert_type IN ({$ph}) ORDER BY created_at ASC, id ASC LIMIT %d"; $wpdb->last_error=''; $rows=$wpdb->get_results($wpdb->prepare($sql,array_merge($types,array($limit))), ARRAY_A); if($wpdb->last_error!=='') return new WP_Error('tax_alert_query_failed',$wpdb->last_error); return is_array($rows)?$rows:array(); }

  private function mrm_tax_utc_mysql_from_timestamp(
    $timestamp = 0
  ) {
    $timestamp = (int)$timestamp;

    if ($timestamp <= 0) {
      $timestamp = time();
    }

    return gmdate(
      'Y-m-d H:i:s',
      $timestamp
    );
  }

  private function mrm_tax_window_bounds(
    $measurement_window
  ) {
    $measurement_window =
      sanitize_key($measurement_window);

    /*
     * Reporting periods are calculated in the configured
     * business timezone and then converted to UTC before
     * being compared with the UTC tax ledger.
     */
    $business_timezone = wp_timezone();
    $utc_timezone = new DateTimeZone('UTC');

    $now = new DateTimeImmutable(
      'now',
      $business_timezone
    );

    $format_window = static function(
      DateTimeImmutable $start,
      DateTimeImmutable $end
    ) use ($utc_timezone) {
      return array(
        $start
          ->setTimezone($utc_timezone)
          ->format('Y-m-d H:i:s'),

        $end
          ->setTimezone($utc_timezone)
          ->format('Y-m-d H:i:s'),
      );
    };

    $year = (int)$now->format('Y');
    $month = (int)$now->format('n');

    $current_year_start = $now
      ->setDate($year, 1, 1)
      ->setTime(0, 0, 0);

    $previous_year_start =
      $current_year_start->modify('-1 year');

    $previous_year_end =
      $current_year_start->modify('-1 second');

    switch ($measurement_window) {
      case 'previous_calendar_year':
        return array($format_window($previous_year_start, $previous_year_end));

      case 'current_or_previous_calendar_year':
        return array(
          $format_window($current_year_start, $now),
          $format_window($previous_year_start, $previous_year_end)
        );

      case 'rolling_12_months':
        return array($format_window($now->modify('-12 months')->setTime(0, 0, 0), $now));

      case 'previous_four_completed_calendar_quarters':
        $current_quarter_start_month = ((int)floor(($month - 1) / 3) * 3) + 1;
        $current_quarter_start = $now->setDate($year, $current_quarter_start_month, 1)->setTime(0, 0, 0);
        return array($format_window($current_quarter_start->modify('-12 months'), $current_quarter_start->modify('-1 second')));

      case 'connecticut_september_30_lookback':
        $ending_year = $month >= 10 ? $year : $year - 1;
        $start = $now->setDate($ending_year - 1, 10, 1)->setTime(0, 0, 0);
        $end = $now->setDate($ending_year, 9, 30)->setTime(23, 59, 59);
        return array($format_window($start, $end));

      case 'new_york_previous_four_sales_tax_quarters':
        $quarter_starts = array(
          $now->setDate($year - 1, 12, 1)->setTime(0, 0, 0),
          $now->setDate($year, 3, 1)->setTime(0, 0, 0),
          $now->setDate($year, 6, 1)->setTime(0, 0, 0),
          $now->setDate($year, 9, 1)->setTime(0, 0, 0),
          $now->setDate($year, 12, 1)->setTime(0, 0, 0),
        );
        $current_sales_tax_quarter_start = $quarter_starts[0];
        foreach ($quarter_starts as $candidate) {
          if ($candidate <= $now && $candidate > $current_sales_tax_quarter_start) {
            $current_sales_tax_quarter_start = $candidate;
          }
        }
        return array($format_window($current_sales_tax_quarter_start->modify('-12 months'), $current_sales_tax_quarter_start->modify('-1 second')));

      case 'not_applicable':
        return array($format_window($current_year_start, $now));
    }

    return array();
  }

  private function mrm_tax_get_compliance_settings() {
    return wp_parse_args(get_option(self::OPT_TAX_COMPLIANCE_SETTINGS, array()), array('national_monitoring_mode'=>'','professional_reviewed_at'=>'','professional_reference'=>'','filing_provider'=>'','filing_provider_status'=>'inactive','filing_provider_effective_date'=>'','filing_provider_reference'=>''));
  }

  private function mrm_tax_review_is_current($date, $maximum_age_days = 90) {
    $date = sanitize_text_field($date);
    if ($date === '') return false;
    try { $reviewed = new DateTimeImmutable($date . ' 23:59:59', wp_timezone()); $cutoff = new DateTimeImmutable('-' . absint($maximum_age_days) . ' days', wp_timezone()); return $reviewed >= $cutoff; } catch (Throwable $error) { return false; }
  }

  private function mrm_tax_stripe_sync_is_fresh($row, $maximum_age_minutes = self::TAX_STRIPE_SYNC_MAX_AGE_MINUTES) { $row = is_array($row) ? $row : array(); $last_sync = sanitize_text_field($row['last_stripe_sync_at'] ?? ''); if ($last_sync === '') return false; try { $synced = new DateTimeImmutable($last_sync, wp_timezone()); $cutoff = new DateTimeImmutable('-' . absint($maximum_age_minutes) . ' minutes', wp_timezone()); return $synced >= $cutoff; } catch (Throwable $error) { return false; } }
  private function mrm_tax_global_registration_sync_is_fresh($maximum_age_minutes = self::TAX_STRIPE_SYNC_MAX_AGE_MINUTES) { $last_sync = sanitize_text_field(get_option(self::OPT_TAX_LAST_SUCCESSFUL_REGISTRATION_SYNC, '')); if ($last_sync === '') return false; try { $synced = new DateTimeImmutable($last_sync, wp_timezone()); $cutoff = new DateTimeImmutable('-' . absint($maximum_age_minutes) . ' minutes', wp_timezone()); return $synced >= $cutoff; } catch (Throwable $error) { return false; } }

  private function mrm_tax_row_rule_review_is_current($row) { $row = is_array($row) ? $row : array(); return (!empty($row['threshold_rule_verified']) && $this->mrm_tax_review_is_current($row['rule_professionally_reviewed_at'] ?? '', self::TAX_RULE_REVIEW_MAX_AGE_DAYS) && trim((string)($row['rule_professional_reference'] ?? '')) !== ''); }
  private function mrm_tax_rule_status_label($row) { $row = is_array($row) ? $row : array(); if ($this->mrm_tax_row_rule_review_is_current($row)) return 'Professionally verified'; if (sanitize_key($row['rule_management_mode'] ?? 'catalog') === 'catalog') return 'Catalog monitoring rule'; return 'Professional verification required'; }

  private function mrm_tax_stripe_settings_readiness($force_refresh = false) {
    if (!$this->mrm_tax_is_live_stripe_key()) return true; $key='mrm_tax_stripe_settings_readiness_v1'; if(!$force_refresh){ $cached=get_transient($key); if(is_array($cached)&&!empty($cached['ready'])) return $cached; }
    $settings=$this->stripe_api_request('GET','/v1/tax/settings',array(),$this->mrm_stripe_tax_headers()); if(is_wp_error($settings)) return new WP_Error('stripe_tax_settings_unavailable','Stripe Tax Settings could not be retrieved: '.$settings->get_error_message()); $status=sanitize_key($settings['status'] ?? ''); if($status!=='active') return new WP_Error('stripe_tax_settings_inactive','Stripe Tax Settings are not active. Current status: '.($status!==''?$status:'unknown').'.');
    $addr=is_array($settings['head_office']['address'] ?? null)?$settings['head_office']['address']:array(); $country=strtoupper(sanitize_text_field($addr['country'] ?? '')); $state=$this->mrm_normalize_state_code($addr['state'] ?? ''); if($country!=='US'||$state!=='AZ') return new WP_Error('stripe_tax_head_office_invalid','Stripe Tax must identify the Low Brass Lessons head office as an Arizona, United States location.');
    $result=array('ready'=>true,'status'=>$status,'country'=>$country,'state'=>$state,'checked_at'=>current_time('mysql')); set_transient($key,$result,self::TAX_STRIPE_SETTINGS_CACHE_MINUTES*MINUTE_IN_SECONDS); return $result;
  }

  private function mrm_tax_threshold_recompute_is_fresh() { $last=sanitize_text_field(get_option('mrm_tax_last_threshold_recompute_at','')); if($last==='') return false; try { $dt=new DateTimeImmutable($last, wp_timezone()); $cutoff=new DateTimeImmutable('-'.absint(self::TAX_THRESHOLD_RECOMPUTE_MAX_AGE_HOURS).' hours', wp_timezone()); return $dt >= $cutoff; } catch (Throwable $error) { return false; } }

  private function mrm_tax_ledger_reconciliation_rows($limit = 50) {
    global $wpdb; $limit=max(1,min(200,absint($limit))); $cutoff =
      $this->mrm_tax_utc_mysql_from_timestamp(
        time()
          - (
            self::TAX_LEDGER_RECONCILIATION_GRACE_MINUTES
            * MINUTE_IN_SECONDS
          )
      );
    $sql=$wpdb->prepare("SELECT id, external_id, source_type, payment_intent_id, invoice_id, customer_state, tax_transaction_status, tax_transaction_id, refunded_tax_cents, tax_reversals_json, association_error, occurred_at, updated_at FROM {$this->table_tax_sales_ledger()} WHERE occurred_at <= %s AND (((source_type = 'payment_intent') AND (COALESCE(tax_transaction_status, '') <> 'committed' OR COALESCE(tax_transaction_id, '') = '' OR COALESCE(association_error, '') <> '')) OR ((source_type = 'subscription_invoice') AND (COALESCE(invoice_id, '') = '' OR COALESCE(tax_transaction_status, '') <> 'complete' OR COALESCE(association_error, '') <> '')) OR (refunded_tax_cents > 0 AND TRIM(COALESCE(tax_reversals_json, '')) IN ('', '[]'))) ORDER BY occurred_at ASC, id ASC LIMIT %d", $cutoff, $limit);
    $wpdb->last_error=''; $rows=$wpdb->get_results($sql, ARRAY_A); if($wpdb->last_error!=='') return new WP_Error('tax_ledger_reconciliation_query_failed',$wpdb->last_error); return is_array($rows)?$rows:array();
  }

  private function mrm_tax_row_has_written_clearance($row) {
    return sanitize_key($row['authority_registration_status'] ?? '') === 'not_required_written_determination' && trim((string)($row['written_determination_reviewed_at'] ?? '')) !== '' && trim((string)($row['written_determination_reference'] ?? '')) !== '';
  }


  private function mrm_tax_reject_unsupported_exemption_claim($payload) {
    $payload = is_array($payload) ? $payload : array();
    $claim_keys = array('tax_exempt','tax_exemption','exemption_certificate','exemption_certificate_id','tax_exempt_customer');
    foreach ($claim_keys as $key) {
      if (!array_key_exists($key, $payload)) continue;
      $value = $payload[$key];
      if (is_array($value) ? !empty($value) : trim((string)$value) !== '') return new WP_Error('online_tax_exemption_not_supported', 'Tax-exempt purchasing is not available through the public checkout. Please contact Low Brass Lessons before purchasing.', array('status'=>400));
    }
    return true;
  }

  private function mrm_tax_live_checkout_readiness() {
    if(!$this->mrm_tax_is_live_stripe_key()) return true; $core_readiness=$this->mrm_tax_core_live_checkout_readiness(); if(is_wp_error($core_readiness)) return $core_readiness; $inventory_readiness=$this->mrm_tax_subscription_inventory_snapshot_readiness();
    if(is_wp_error($inventory_readiness)){ $inventory_result=$this->mrm_tax_enforce_global_subscription_holds(); if(is_wp_error($inventory_result)) return new WP_Error('subscription_inventory_not_ready','The live Stripe subscription inventory could not be reconciled: '.$inventory_result->get_error_message()); $inventory_readiness=$this->mrm_tax_subscription_inventory_snapshot_readiness(); if(is_wp_error($inventory_readiness)) return new WP_Error('subscription_inventory_still_invalid','The Stripe subscription inventory reconciliation did not produce a current snapshot for the active account, mode, key, and price: '.$inventory_readiness->get_error_message()); }
    $subscription_hold_error=trim((string)get_option(self::OPT_TAX_SUBSCRIPTION_HOLD_ERROR,'')); if($subscription_hold_error!=='') return new WP_Error('subscription_tax_hold_enforcement_failed','One or more existing subscriptions could not be protected by the tax-compliance hold system: '.$subscription_hold_error); return true;
  }

  private function mrm_tax_core_live_checkout_readiness() {
    global $wpdb;
    if (!$this->mrm_tax_is_live_stripe_key()) return true;
    $schema_error = trim((string)get_option('mrm_tax_schema_migration_error', ''));
    if ($schema_error !== '') return new WP_Error('tax_schema_migration_failed', 'The tax database schema migration has unresolved errors: ' . $schema_error);
    $engine_readiness = $this->mrm_tax_required_tables_innodb_readiness(); if (is_wp_error($engine_readiness)) return $engine_readiness;
    $stripe_settings = $this->mrm_tax_stripe_settings_readiness(); if (is_wp_error($stripe_settings)) return $stripe_settings;
    $state_table = $this->table_tax_state_status();
    $arizona = $wpdb->get_row("SELECT * FROM {$state_table} WHERE state_code = 'AZ' LIMIT 1", ARRAY_A);
    if (!$this->mrm_tax_global_registration_sync_is_fresh() || !$arizona || !$this->mrm_tax_stripe_sync_is_fresh($arizona)) { $sync = $this->mrm_tax_sync_stripe_registrations(); if (is_wp_error($sync)) return new WP_Error('stripe_registration_sync_failed', 'The live Stripe Tax registration status could not be refreshed: ' . $sync->get_error_message()); $arizona = $wpdb->get_row("SELECT * FROM {$state_table} WHERE state_code = 'AZ' LIMIT 1", ARRAY_A); }
    if (!$arizona) return new WP_Error('arizona_tax_registry_missing', 'Arizona is missing from the Stripe registration monitor.');
    if (sanitize_key($arizona['stripe_registration_status'] ?? '') !== 'active' || empty($arizona['stripe_livemode']) || empty($arizona['collection_active'])) return new WP_Error('arizona_stripe_registration_inactive', 'The Arizona live Stripe Tax registration is not active.');
    $reconciliation = $this->mrm_tax_ledger_reconciliation_rows(1); if (is_wp_error($reconciliation)) return $reconciliation; if (!empty($reconciliation)) return new WP_Error('tax_ledger_reconciliation_required', 'One or more completed payments or refunds still require tax-ledger reconciliation.');
    $critical_alerts = $this->mrm_tax_critical_open_alerts(1); if (is_wp_error($critical_alerts)) return $critical_alerts; if (!empty($critical_alerts)) { $first = $critical_alerts[0]; return new WP_Error('tax_critical_alert_open', 'A critical tax alert is open: ' . sanitize_text_field($first['alert_type'] ?? 'unknown')); }
    return true;
  }


  private function mrm_tax_administrative_compliance_issues() {
    global $wpdb;$issues=array();$add=static function(&$issues,$code,$state,$message,$alertable=true){$issues[]=compact('code','state','message','alertable');};$schema=trim((string)get_option('mrm_tax_schema_migration_error',''));if($schema!=='')$add($issues,'tax_schema_migration_failed','AZ','The tax database schema has an unresolved migration error: '.$schema);$threshold=trim((string)get_option('mrm_tax_threshold_recompute_error',''));if($threshold!=='')$add($issues,'tax_threshold_recompute_failed','AZ','State threshold monitoring has an unresolved error: '.$threshold);elseif(!$this->mrm_tax_threshold_recompute_is_fresh())$add($issues,'tax_threshold_recompute_stale','AZ','State payment totals have not been recomputed within the last '.self::TAX_THRESHOLD_RECOMPUTE_MAX_AGE_HOURS.' hours.');if($this->mrm_tax_is_live_stripe_key()){ $ready=$this->mrm_tax_stripe_settings_readiness();if(is_wp_error($ready))$add($issues,$ready->get_error_code(),'AZ',$ready->get_error_message());if(!$this->mrm_tax_global_registration_sync_is_fresh())$add($issues,'stripe_registration_sync_stale','AZ','The Stripe Tax registration snapshot is missing or older than two hours.');}
    $rows=$wpdb->get_results("SELECT * FROM {$this->table_tax_state_status()} WHERE collection_active=0 AND general_sales_tax_status<>'no_general_state_sales_tax' AND (physical_nexus_flag=1 OR estimated_threshold_status='threshold_reached' OR estimated_threshold_percent>=75) ORDER BY estimated_threshold_percent DESC,state_code ASC",ARRAY_A);if($wpdb->last_error!=='')$add($issues,'state_monitor_query_failed','AZ','State monitoring results could not be loaded: '.$wpdb->last_error);else foreach((array)$rows as $row){$state=$this->mrm_normalize_state_code($row['state_code']??'');if($state==='')continue;if($this->mrm_tax_state_pending_registration_window_is_valid($row)){$add($issues,'registration_pending_controlled_window',$state,$state.' has a documented permit application and remains inside its controlled registration window.',false);continue;}if(!empty($row['physical_nexus_flag'])||sanitize_key($row['estimated_threshold_status']??'')==='threshold_reached')$add($issues,'stripe_registration_action_required',$state,$state.' has a detected physical-presence or reached-threshold signal, but Stripe Tax collection is not active. Review this state in Stripe Tax.');else $add($issues,'stripe_threshold_monitoring',$state,$state.' is at '.number_format((float)($row['estimated_threshold_percent']??0),1).'% of the local catalog threshold. Review Stripe Tax → Needs attention.');}
    $recon=$this->mrm_tax_ledger_reconciliation_rows(50);if(is_wp_error($recon))$add($issues,'tax_ledger_reconciliation_query_failed','AZ','Tax-ledger reconciliation could not be evaluated: '.$recon->get_error_message());elseif(!empty($recon))$add($issues,'tax_ledger_reconciliation_required','AZ',count($recon).' Stripe Tax transaction(s) require reconciliation.');$alerts=$this->mrm_tax_critical_open_alerts(50);if(is_wp_error($alerts))$add($issues,'tax_alert_query_failed','AZ','Open tax alerts could not be evaluated: '.$alerts->get_error_message());elseif(!empty($alerts))$add($issues,'critical_tax_alerts_open','AZ',count($alerts).' critical Stripe Tax or refund alert(s) remain unresolved.');return $issues;
  }

  private function mrm_tax_customer_readiness_response($readiness) {
    if (!is_wp_error($readiness)) return null;
    $this->stripe_debug_log('Live checkout blocked by tax readiness gate.', array('code'=>$readiness->get_error_code(),'message'=>$readiness->get_error_message()));
    return new WP_REST_Response(array('ok'=>false,'code'=>'tax_configuration_not_ready','message'=>'Payments are temporarily unavailable while our tax configuration is being updated. Please try again later or contact Low Brass Lessons.'), 503);
  }

