  private function mrm_tax_catalog_rule_for_state($state, $as_of_date = '') {
    $state = $this->mrm_normalize_state_code($state); if ($state === '') return null;
    $versions = $this->mrm_tax_national_rule_catalog()[$state] ?? array(); if (empty($versions)) return null;
    $as_of_date = sanitize_text_field($as_of_date); if ($as_of_date === '') $as_of_date = wp_date('Y-m-d');
    usort($versions, static function($left,$right){ return strcmp((string)($left['effective_date'] ?? ''),(string)($right['effective_date'] ?? '')); });
    $selected = null; foreach ($versions as $version) { $effective = (string)($version['effective_date'] ?? ''); if ($effective !== '' && $effective <= $as_of_date) $selected = $version; }
    return $selected;
  }

  private function mrm_tax_sync_rule_catalog($state_filter = '') {
    global $wpdb; $table = $this->table_tax_state_status(); $state_filter = $this->mrm_normalize_state_code($state_filter); $catalog = $this->mrm_tax_national_rule_catalog(); $states = $state_filter !== '' ? array($state_filter) : array_keys($catalog); $now = current_time('mysql');
    foreach ($states as $state) {
      $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE state_code = %s LIMIT 1", $state), ARRAY_A); if (!is_array($row)) continue;
      if (sanitize_key($row['rule_management_mode'] ?? 'catalog') === 'manual') continue;
      $rule = $this->mrm_tax_catalog_rule_for_state($state); if (!is_array($rule)) continue;
      $channels = $rule['channels'] === 'all' ? array('direct','marketplace') : array('direct');
      $applicable = !empty($rule['economic_nexus_applicable']);
      $general_status = $rule['tax_system'] === 'no_general_sales_tax' ? 'no_general_state_sales_tax' : ($rule['tax_system'] === 'local_only' ? 'local_sales_tax_only' : 'statewide');
      $source_url = $state === 'IL' ? 'https://tax.illinois.gov/research/publications/bulletins/fy-2026-12.html' : 'https://www.salestaxinstitute.com/resources/economic-nexus-state-guide';
      $basis_description = !$applicable ? 'Not applicable' : ucfirst($rule['sales_basis']) . ' sales; ' . ($rule['channels'] === 'all' ? 'marketplace included' : 'marketplace excluded for individual sellers');
      $rules_json = array('catalog_managed'=>true,'catalog_as_of'=>'2026-07-14','verification_status'=>'catalog_monitoring_only','source_chart_as_of'=>'2026-05-04','economic_nexus_applicable'=>$applicable,'tax_system'=>$rule['tax_system'],'sales_basis'=>$rule['sales_basis'],'included_channels'=>$channels,'included_categories'=>array('all'),'subtract_refunds'=>false,'amount_comparison'=>$rule['amount_comparison'],'count_comparison'=>$rule['count_comparison'],'conservative_scope'=>'The engine may overcount product or service categories when a state threshold is limited to particular sale types. It must not be used to override physical nexus or a documented registration obligation.','source_note'=>$rule['note'],'secondary_source_url'=>'https://www.streamlinedsalestax.org/state-tables');
      $updated = $wpdb->update($table, array('general_sales_tax_status'=>$general_status,'rule_management_mode'=>'catalog','threshold_amount_cents'=>$rule['threshold_amount_cents'],'threshold_transaction_count'=>$rule['threshold_transaction_count'],'threshold_operator'=>$rule['threshold_operator'],'measurement_window'=>$rule['measurement_window'],'included_sales_basis'=>$basis_description,'rules_json'=>wp_json_encode($rules_json),'rule_source_url'=>$source_url,'rule_effective_date'=>$rule['effective_date'],'rules_version'=>self::TAX_RULES_VERSION,'updated_at'=>$now), array('state_code'=>$state));
      if ($updated === false) return new WP_Error('tax_rule_catalog_sync_failed', $state . ': ' . ($wpdb->last_error ?: 'The catalog rule could not be saved.'));
    }
    return true;
  }

  private function mrm_tax_seed_initial_rules() {
    return $this->mrm_tax_sync_rule_catalog();
  }

  private function mrm_tax_is_live_stripe_key() {
    $key = trim((string)$this->secret_key());
    return strpos($key, 'sk_live_') === 0 || strpos($key, 'rk_live_') === 0;
  }

  private function mrm_tax_acquire_registration_sync_lock() {
    $token=wp_generate_uuid4(); $now=time(); $lock=array('token'=>$token,'started_at'=>$now);
    if(add_option(self::OPT_TAX_REGISTRATION_SYNC_LOCK,$lock,'',false)) return $token;
    $existing=get_option(self::OPT_TAX_REGISTRATION_SYNC_LOCK,array()); $started_at=absint(is_array($existing)?($existing['started_at']??0):0);
    if($started_at>0 && ($now-$started_at)>600){ delete_option(self::OPT_TAX_REGISTRATION_SYNC_LOCK); if(add_option(self::OPT_TAX_REGISTRATION_SYNC_LOCK,$lock,'',false)) return $token; }
    return new WP_Error('stripe_registration_sync_locked','A Stripe registration synchronization is already running.');
  }

  private function mrm_tax_collection_activation_deduplication_key($state, $collection_started_at) {
    $state = $this->mrm_normalize_state_code($state);
    $collection_started_at = sanitize_text_field((string) $collection_started_at);
    return sanitize_key($state . '_' . str_replace(array('-', ':', ' '), '', $collection_started_at));
  }

  private function
  mrm_tax_collection_activation_source_context(
    $row,
    $collection_started_at
  ) {
    global $wpdb;

    $result = array(
      'source' => '',
      'recorded' => false,
    );

    if (!is_array($row)) {
      return $result;
    }

    $state = $this->mrm_normalize_state_code(
      $row['state_code'] ?? ''
    );

    $collection_started_at = sanitize_text_field(
      (string) $collection_started_at
    );

    if ($state === '' || $collection_started_at === '') {
      return $result;
    }

    $allowed_sources = array(
      'first_post_patch_verified_sync',
      'inactive_to_active_transition',
    );

    /* First look for the canonical source event. */
    $audit = json_decode(
      (string) ($row['workflow_audit_json'] ?? ''),
      true
    );

    if (is_array($audit)) {
      foreach ($audit as $event) {
        if (!is_array($event)) {
          continue;
        }

        $event_name = sanitize_key($event['event'] ?? '');
        $event_started_at = sanitize_text_field(
          $event['collection_started_at'] ?? ''
        );

        if ($event_started_at !== $collection_started_at) {
          continue;
        }

        if ($event_name === 'stripe_collection_start_source_recorded') {
          $source = sanitize_key($event['source'] ?? '');
          if (in_array($source, $allowed_sources, true)) {
            return array('source' => $source, 'recorded' => true);
          }
        }

        /* Preserve compatibility with an earlier successful implementation. */
        if ($event_name === 'first_post_patch_verified_sync') {
          return array(
            'source' => 'first_post_patch_verified_sync',
            'recorded' => true,
          );
        }
      }
    }

    /* Recover the source from an activation alert created before this repair. */
    $deduplication_key =
      $this->mrm_tax_collection_activation_deduplication_key(
        $state,
        $collection_started_at
      );
    $alert_key = substr(
      'mrm_tax_stripe_collection_activated_' . $deduplication_key,
      0,
      191
    );
    $wpdb->last_error = '';
    $details_json = $wpdb->get_var(
      $wpdb->prepare(
        "SELECT details_json FROM {$this->table_tax_alerts()} WHERE alert_key = %s LIMIT 1",
        $alert_key
      )
    );

    if ($wpdb->last_error === '' && is_string($details_json) && $details_json !== '') {
      $details = json_decode($details_json, true);
      if (is_array($details)) {
        $source = sanitize_key($details['activation_detection_source'] ?? '');
        if (in_array($source, $allowed_sources, true)) {
          return array('source' => $source, 'recorded' => false);
        }

        $message = sanitize_textarea_field($details['message'] ?? '');
        if (strpos($message, 'first verified locally after the state-workflow update') !== false) {
          return array(
            'source' => 'first_post_patch_verified_sync',
            'recorded' => false,
          );
        }
      }
    }

    return $result;
  }

  private function
  mrm_tax_collection_activation_postprocessing_complete(
    $row
  ) {
    global $wpdb;

    if (!is_array($row)) return false;

    $state = $this->mrm_normalize_state_code($row['state_code'] ?? '');
    $collection_started_at = sanitize_text_field($row['stripe_collection_started_at'] ?? '');
    if ($state === '' || $collection_started_at === '') return false;

    $audit = json_decode((string) ($row['workflow_audit_json'] ?? ''), true);
    if (!is_array($audit)) return false;

    $completion_marker_found = false;
    foreach ($audit as $event) {
      if (!is_array($event)) continue;
      if (sanitize_key($event['event'] ?? '') !== 'stripe_collection_activation_processed') continue;
      if (sanitize_text_field($event['collection_started_at'] ?? '') === $collection_started_at) {
        $completion_marker_found = true;
        break;
      }
    }
    if (!$completion_marker_found) return false;

    $deduplication_key = $this->mrm_tax_collection_activation_deduplication_key($state, $collection_started_at);
    $alert_key = substr('mrm_tax_stripe_collection_activated_' . $deduplication_key, 0, 191);
    $wpdb->last_error = '';
    $alert = $wpdb->get_row(
      $wpdb->prepare(
        "SELECT id, email_status, emailed_at FROM {$this->table_tax_alerts()} WHERE alert_key = %s LIMIT 1",
        $alert_key
      ),
      ARRAY_A
    );
    $email_status = sanitize_key($alert['email_status'] ?? '');
    $email_complete = ($email_status === 'sent' && !empty($alert['emailed_at'])) || $email_status === 'waived';
    if ($wpdb->last_error !== '' || !is_array($alert) || !$email_complete) return false;
    return true;
  }

  private function mrm_tax_release_registration_sync_lock($token) {
    $existing=get_option(self::OPT_TAX_REGISTRATION_SYNC_LOCK,array());
    if(!is_array($existing)||!hash_equals((string)($existing['token']??''),(string)$token)) return false;
    return delete_option(self::OPT_TAX_REGISTRATION_SYNC_LOCK);
  }

