    $summary+=array('digital_gross_sales_cents'=>$gross,'digital_refunded_sales_cents'=>$refund,'digital_net_sales_cents'=>$net,'digital_payment_intent_count'=>count($pi),'digital_invoice_count'=>count($inv),'digital_transaction_count'=>count($pi)+count($inv),'net_tax_collected_cents'=>$summary['digital_document_download']['tax_collected_cents']+$summary['digital_document_subscription']['tax_collected_cents'],'taxability_reasons'=>array_values($reasons),'reserve_rate_bps'=>$bps,'estimated_reserve_cents'=>(int)round(max(0,$net)*$bps/10000)); return $summary;
