      }

      $wpdb->last_error = '';
      $verified_rows = $wpdb->get_results("SELECT state_code, stripe_registration_id, stripe_registration_status, stripe_livemode, collection_active, last_stripe_sync_at FROM {$table}", ARRAY_A);
      if ($wpdb->last_error !== '') return $failure('stripe_registration_snapshot_verification_failed', $wpdb->last_error);
      $verified_by_state = array();
      foreach ((array) $verified_rows as $verified_row) {
        $verified_state = $this->mrm_normalize_state_code($verified_row['state_code'] ?? '');
        if ($verified_state !== '') $verified_by_state[$verified_state] = $verified_row;
      }

      foreach ($active as $state => $registration) {
        if (empty($verified_by_state[$state])) return $failure('stripe_registration_snapshot_state_missing', $state . ' was missing from the verification snapshot.');
        $verified_row = $verified_by_state[$state];
        $expected_livemode = !empty($registration['livemode']) ? 1 : 0;
        $mode_valid = !$this->mrm_tax_is_live_stripe_key() || $expected_livemode === 1;
        $expected_collection = sanitize_key($registration['status']) === 'active' && $mode_valid ? 1 : 0;
        if ((string) ($verified_row['stripe_registration_id'] ?? '') !== (string) $registration['id']
          || sanitize_key($verified_row['stripe_registration_status'] ?? '') !== sanitize_key($registration['status'])
          || (int) ($verified_row['stripe_livemode'] ?? 0) !== $expected_livemode
          || (int) ($verified_row['collection_active'] ?? 0) !== $expected_collection
          || sanitize_text_field($verified_row['last_stripe_sync_at'] ?? '') !== $now) {
          return $failure('stripe_registration_snapshot_mismatch', $state . ' did not match the Stripe registration snapshot after saving.');
        }
      }

      foreach ($verified_by_state as $state => $verified_row) {
        if (isset($active[$state])) continue;
        if ((string) ($verified_row['stripe_registration_id'] ?? '') !== ''
          || sanitize_key($verified_row['stripe_registration_status'] ?? '') !== 'none'
          || (int) ($verified_row['stripe_livemode'] ?? 0) !== 0
          || (int) ($verified_row['collection_active'] ?? 0) !== 0
          || sanitize_text_field($verified_row['last_stripe_sync_at'] ?? '') !== $now) {
          return $failure('stripe_registration_reset_verification_failed', $state . ' did not match the expected inactive Stripe snapshot.');
        }
      }

      $wpdb->last_error = '';
      if ($wpdb->query('COMMIT') === false || $wpdb->last_error !== '') return $failure('stripe_registration_commit_failed', $wpdb->last_error ?: 'The verified Stripe registration snapshot could not be committed.');
      $transaction_open = false;
      update_option(self::OPT_TAX_LAST_SUCCESSFUL_REGISTRATION_SYNC,$now,false);if(sanitize_text_field(get_option(self::OPT_TAX_LAST_SUCCESSFUL_REGISTRATION_SYNC,''))!==$now)return $failure('stripe_registration_global_timestamp_failed','The successful-sync timestamp could not be recorded.');
      $current_rows = $wpdb->get_results("SELECT * FROM {$table}", ARRAY_A);
      if ($wpdb->last_error !== '') {
        return $failure('stripe_registration_committed_snapshot_failed', $wpdb->last_error);
      }

      /* The verified Stripe snapshot is committed; errors below are noncritical. */
      $postprocessing_errors = array();
      $resolve_activation_warnings = function ($state) use (&$postprocessing_errors) {
        $result = $this->mrm_tax_resolve_state_workflow_alerts(
          $state,
          array('stripe_activation_notification_pending', 'stripe_activation_postprocessing_failed')
        );
        if (is_wp_error($result)) {
          $postprocessing_errors[] = array('state'=>$state, 'code'=>$result->get_error_code(), 'message'=>$result->get_error_message());
          error_log('MRM Stripe activation warning resolution failed for ' . $state . ': ' . $result->get_error_message());
          return false;
        }
        return true;
      };
      foreach ((array) $current_rows as $current) {
        $state = $this->mrm_normalize_state_code($current['state_code'] ?? '');
        if ($state === '') continue;
        $previous = $previous_by_state[$state] ?? array();
        $was_active = !empty($previous['collection_active']);
        $is_active = !empty($current['collection_active']);
        $missing_collection_start = $is_active && empty($current['stripe_collection_started_at']);
        $postprocessing_complete = $is_active
          && $this->mrm_tax_collection_activation_postprocessing_complete($current);
        /* Retry warning cleanup for every completed active state. */
        if ($postprocessing_complete) {
          $resolve_activation_warnings($state);
          continue;
        }
        $postprocessing_incomplete = $is_active;

        if ((!$was_active && $is_active) || $missing_collection_start || $postprocessing_incomplete) {
          $result = $this->mrm_tax_handle_verified_collection_activation($state, $previous, $current, $now);
          if (is_wp_error($result)) {
            $error_code = sanitize_key($result->get_error_code());
            $error_message = sanitize_textarea_field($result->get_error_message());
            $warning_type = $error_code === 'activation_email_pending'
              ? 'stripe_activation_notification_pending'
              : 'stripe_activation_postprocessing_failed';
            $collection_started_at = sanitize_text_field(
              $current['stripe_collection_started_at'] ?? $now
            );
            $warning_deduplication_key = sanitize_key(
              $state . '_' . str_replace(array('-', ':', ' '), '', $collection_started_at) . '_' . $error_code
            );
            $warning_alert = $this->mrm_tax_create_alert(
              $state,
              $warning_type,
              'stripe',
              0,
              array(
                'message' => 'The Stripe registration snapshot was successfully verified and committed, but activation post-processing remains pending.' .
                  "\n\nState: " . $state . "\nError code: " . $error_code . "\nDetails: " . $error_message,
                'state' => $state,
                'snapshot_committed' => true,
                'synced_at' => $now,
                'collection_started_at' => $collection_started_at,
                'postprocessing_error_code' => $error_code,
                'postprocessing_error_message' => $error_message,
              ),
              $warning_deduplication_key
            );
            if (is_wp_error($warning_alert)) {
              error_log('MRM Stripe activation warning alert failed for ' . $state . ': ' . $warning_alert->get_error_message());
            }
            $postprocessing_errors[] = array(
              'state' => $state,
              'code' => $error_code,
              'message' => $error_message,
            );
            continue;
          }

          $resolve_activation_warnings($state);
        }
      }

      $resolved_sync_alerts = $this->mrm_tax_resolve_alert_type('stripe_registration_sync_failed');
      if (is_wp_error($resolved_sync_alerts)) {
        return $failure('stripe_registration_sync_alert_resolution_failed', $resolved_sync_alerts->get_error_message());
      }

      return array(
        'snapshot_committed' => true,
        'synced_at' => $now,
        'active_states' => array_keys($active),
        'postprocessing_errors' => $postprocessing_errors,
      );
    } finally { $this->mrm_tax_release_registration_sync_lock($lock_token); }
  }
  private function mrm_tax_handle_verified_collection_activation($state, $previous_row, $current_row, $activation_time) {
    global $wpdb;
    $state=$this->mrm_normalize_state_code($state);
    if($state==='') return new WP_Error('activation_state_invalid','The activated state is invalid.');
    $table=$this->table_tax_state_status();
    $collection_started_at = sanitize_text_field($current_row['stripe_collection_started_at'] ?? '');
    if ($collection_started_at === '') $collection_started_at = $activation_time;
    $source_context = $this->mrm_tax_collection_activation_source_context($current_row, $collection_started_at);
    $activation_detection_source = sanitize_key($source_context['source'] ?? '');
    if ($activation_detection_source === '') {
      $previous_sync_at = sanitize_text_field($previous_row['last_stripe_sync_at'] ?? '');
      $previous_collection_started_at = sanitize_text_field($previous_row['stripe_collection_started_at'] ?? '');
      $first_local_verification = $previous_sync_at === ''
        || (!empty($previous_row['collection_active']) && $previous_collection_started_at === '');
      $activation_detection_source = $first_local_verification
        ? 'first_post_patch_verified_sync'
        : 'inactive_to_active_transition';
    }
    $first_post_patch_verification = $activation_detection_source === 'first_post_patch_verified_sync';
    $tracking_started_at=sanitize_text_field($current_row['pending_tax_tracking_started_at']??$current_row['physical_activity_started_at']??'');
    $tracking_ended_at=sanitize_text_field($current_row['pending_tax_tracking_ended_at']??'');
    $updates=array('stripe_collection_started_at'=>$collection_started_at,'updated_at'=>$activation_time);
    /* Persist the detection source before notification or reporting. */
    if (empty($source_context['recorded'])) {
      $updates['workflow_audit_json'] = $this->mrm_tax_append_workflow_audit(
        $current_row['workflow_audit_json'] ?? '',
        array(
          'event' => 'stripe_collection_start_source_recorded',
          'state' => $state,
          'collection_started_at' => $collection_started_at,
          'source' => $activation_detection_source,
          'stripe_registration_id' => sanitize_text_field($current_row['stripe_registration_id'] ?? ''),
          'administrator_id' => 0,
          'recorded_at' => current_time('mysql'),
        )
      );
    }
    if($tracking_started_at!=='') {
      $desired=$collection_started_at;
      try { if(new DateTimeImmutable($collection_started_at,wp_timezone()) < new DateTimeImmutable($tracking_started_at,wp_timezone())) $desired=$tracking_started_at; } catch(Throwable $error) { $desired=$tracking_started_at; }
      $replace=$tracking_ended_at==='';
      if(!$replace) { try { $replace=new DateTimeImmutable($tracking_ended_at,wp_timezone()) < new DateTimeImmutable($tracking_started_at,wp_timezone()); } catch(Throwable $error) { $replace=true; } }
      if($replace) $updates['pending_tax_tracking_ended_at']=$desired;
    }
    if(sanitize_key($current_row['authority_registration_status']??'not_started')==='approved') $updates['authority_registration_status']='active';
    $wpdb->last_error=''; $saved=$wpdb->update($table,$updates,array('state_code'=>$state));
    if($saved===false||$wpdb->last_error!=='') return new WP_Error('activation_state_save_failed',$wpdb->last_error?:'The collection-activation workflow could not be saved.');
    $row=$this->mrm_tax_get_state_row($state); if(is_wp_error($row)) return $row;
    $summary_end=sanitize_text_field($row['pending_tax_tracking_ended_at']??'') ?: $collection_started_at;
    $summary=$this->mrm_tax_summarize_pending_period_sales($state,$row,$summary_end); if(is_wp_error($summary)) return $summary;
    $frequency=sanitize_text_field($row['filing_frequency']??''); $due=sanitize_text_field($row['next_return_due_date']??'');
    $message = $first_post_patch_verification
      ? 'Stripe Tax collection was first verified locally after the state-workflow update. This timestamp may be later than the original historical Stripe activation.'
      : 'Stripe Tax collection became active.';
    $message .= "\n\nState: ".$state."\nStripe registration ID: ".sanitize_text_field($row['stripe_registration_id']??'')."\nCollection start: ".$collection_started_at."\nPending period start: ".sanitize_text_field($summary['period_start']??'')."\nPending period end: ".sanitize_text_field($summary['period_end']??'')."\nPending digital transactions: ".absint($summary['digital_transaction_count']??0)."\nPending digital gross sales: $".number_format(((int)($summary['digital_gross_sales_cents']??0))/100,2)."\nPending digital refunds: $".number_format(((int)($summary['digital_refunded_sales_cents']??0))/100,2)."\nPending digital net sales: $".number_format(((int)($summary['digital_net_sales_cents']??0))/100,2);
    if($state==='TX') $message.="\nEstimated internal reserve: $".number_format(((int)($summary['estimated_reserve_cents']??0))/100,2);
    $message.="\nFiling frequency: ".($frequency?:'MISSING')."\nNext return due date: ".($due?:'MISSING');
    if($frequency==='')$message.="\nWARNING: Filing frequency is missing."; if($due==='')$message.="\nWARNING: The next return due date is missing.";
    if(!in_array(sanitize_key($row['authority_registration_status']??''),array('approved','active','not_required_written_determination'),true)) $message.="\nWARNING: Stripe activation confirms collection only. The government permit status remains incomplete or requires review.";
    $dedup=$this->mrm_tax_collection_activation_deduplication_key($state,$collection_started_at);
    $alert=$this->mrm_tax_create_alert($state,'stripe_collection_activated','stripe',0,array('message'=>$message,'state'=>$state,'stripe_registration_id'=>$row['stripe_registration_id']??'','collection_started_at'=>$collection_started_at,'activation_detection_source'=>$activation_detection_source,'summary'=>$summary),$dedup); if(is_wp_error($alert)) return $alert;
    $activation_alert_id = absint($alert);
    if ($activation_alert_id <= 0) return new WP_Error('activation_alert_id_missing', 'The Stripe activation alert did not return a valid ID.');
    $wpdb->last_error = '';
    $activation_alert_row = $wpdb->get_row($wpdb->prepare("SELECT id, email_status, emailed_at, email_last_error FROM {$this->table_tax_alerts()} WHERE id = %d LIMIT 1", $activation_alert_id), ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('activation_alert_verification_failed', $wpdb->last_error);
    if (!is_array($activation_alert_row)) return new WP_Error('activation_alert_missing', 'The Stripe activation alert could not be reloaded.');
    $activation_email_status = sanitize_key($activation_alert_row['email_status'] ?? '');
    if ($activation_email_status === 'uncertain' || $activation_email_status === 'sending') {
      return new WP_Error('activation_email_state_uncertain', sanitize_text_field($activation_alert_row['email_last_error'] ?? 'The activation email may have been accepted, but its final sent state could not be confirmed. Automatic resend was suppressed to prevent a duplicate.'));
    }
    if ($activation_email_status === 'waived') {
      /* An administrator explicitly resolved the email uncertainty. */
    } elseif ($activation_email_status !== 'sent' || empty($activation_alert_row['emailed_at'])) {
      return new WP_Error('activation_email_pending', 'The Stripe activation notification has not been accepted by WordPress mail. Activation processing will retry or await administrator resolution.');
    }
    $resolved=$this->mrm_tax_resolve_state_workflow_alerts($state,array('tx_permit_status_day_7','tx_permit_processing_day_15','physical_nexus_registration_required','stripe_registration_action_required','subscription_not_collecting_review_required')); if(is_wp_error($resolved)) return $resolved;
    if(!$this->mrm_tax_collection_activation_postprocessing_complete($row)) {
      if ($first_post_patch_verification) {
        $audit = $this->mrm_tax_append_workflow_audit($row['workflow_audit_json'] ?? '', array('event'=>'first_post_patch_verified_sync','state'=>$state,'collection_started_at'=>$collection_started_at,'stripe_registration_id'=>sanitize_text_field($row['stripe_registration_id']??''),'administrator_id'=>0,'recorded_at'=>current_time('mysql')));
      } else {
        $audit = $row['workflow_audit_json'] ?? '';
      }
      $audit=$this->mrm_tax_append_workflow_audit($audit,array('event'=>'stripe_collection_activation_processed','state'=>$state,'collection_started_at'=>$collection_started_at,'stripe_registration_id'=>sanitize_text_field($row['stripe_registration_id']??''),'activation_detection_source'=>$activation_detection_source,'administrator_id'=>0,'recorded_at'=>current_time('mysql')));
      $wpdb->last_error=''; $audit_saved=$wpdb->update($table,array('workflow_audit_json'=>$audit,'updated_at'=>current_time('mysql')),array('state_code'=>$state));
      if($audit_saved===false||$wpdb->last_error!=='') return new WP_Error('activation_completion_marker_failed',$wpdb->last_error?:'The activation completion marker could not be saved.');
      $verified=$this->mrm_tax_get_state_row($state); if(is_wp_error($verified)||!$this->mrm_tax_collection_activation_postprocessing_complete($verified)) return new WP_Error('activation_completion_marker_unverified','The activation completion marker could not be verified.');
    }
    return array('state'=>$state,'summary'=>$summary);
  }

  public function handle_tax_sync_stripe_registrations() {
    if (!current_user_can('manage_options')) wp_die('You do not have permission.');
    check_admin_referer('mrm_tax_sync_stripe_registrations', 'mrm_tax_sync_nonce');
    $result = $this->mrm_tax_sync_stripe_registrations();
    $url = admin_url('admin.php?page=' . self::TAX_MONITOR_MENU_SLUG);
    if (is_wp_error($result)) {
      $url = add_query_arg('tax_error', rawurlencode($result->get_error_message()), $url);
    } elseif (!empty($result['postprocessing_errors'])) {
      $url = add_query_arg('stripe_sync_warning', count($result['postprocessing_errors']), $url);
    } else {
      $url = add_query_arg('stripe_sync', '1', $url);
    }
    wp_safe_redirect($url);
    exit;
  }

  public function cron_tax_sync_registrations() {
    $result=$this->mrm_tax_sync_stripe_registrations();
    if(is_wp_error($result))error_log('MRM Stripe Tax registration sync failed: '.$result->get_error_message());
    elseif(!empty($result['postprocessing_errors']))foreach($result['postprocessing_errors'] as $error)error_log('MRM Stripe Tax activation post-processing pending for '.sanitize_text_field($error['state']??'unknown state').': '.sanitize_textarea_field($error['message']??'Unknown post-processing error.'));
    $retry=$this->mrm_tax_retry_failed_alert_emails(25);
    if(is_wp_error($retry))error_log('MRM tax-alert email retry failed: '.$retry->get_error_message());
    elseif(!empty($retry['errors']))foreach($retry['errors'] as $error)error_log('MRM tax-alert email retry remains pending for alert #'.absint($error['alert_id']??0).': '.sanitize_textarea_field($error['message']??'Unknown email retry error.'));
    $this->mrm_tax_enforce_global_subscription_holds();
  }
  public function cron_tax_recompute_thresholds() { $result=$this->mrm_tax_recompute_all_thresholds(); if(is_wp_error($result)) error_log('MRM tax threshold recomputation failed: '.$result->get_error_message()); $this->mrm_tax_enforce_global_subscription_holds(); }

  public function register_external_physical_nexus_source($args) {
    global $wpdb;
    $args = wp_parse_args($args, array('state'=>'','country'=>'US','source_type'=>'manual_activity','source_id'=>'','source_label'=>'Business activity','details'=>''));
    $country = strtoupper(sanitize_text_field($args['country']));
    if ($country !== 'US') { return array('recorded'=>false,'reason'=>'non_us'); }
    $state = $this->mrm_normalize_state_code($args['state']);
    if ($state === '') return new WP_Error('invalid_physical_nexus_state','The physical-nexus state is missing or invalid.');
    $table = $this->table_tax_state_status();
    $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE state_code = %s LIMIT 1", $state), ARRAY_A);
    if (!is_array($row)) return new WP_Error('physical_nexus_state_missing','The state is missing from the tax registry.');
    $source_type = sanitize_key($args['source_type']);
    $source_id = sanitize_text_field((string)$args['source_id']);
    $source_label = sanitize_text_field($args['source_label']);
    $details = sanitize_text_field($args['details']);
    $reason = trim($source_label . ($source_id !== '' ? ' #' . $source_id : '') . ' reported activity or presence in ' . $state . ($details !== '' ? ': ' . $details : '') . '.');
    $reasons = preg_split('/\r\n|\r|\n/', (string)($row['physical_nexus_reason'] ?? ''));
    $reasons = array_values(array_filter(array_map('trim', (array)$reasons)));
    if (!in_array($reason, $reasons, true)) $reasons[] = $reason;
    $now = current_time('mysql');
    $updated = $wpdb->update($table, array('physical_nexus_flag'=>1,'physical_nexus_reason'=>implode("\n", $reasons),'first_flagged_at'=>!empty($row['first_flagged_at']) ? $row['first_flagged_at'] : $now,'updated_at'=>$now), array('state_code'=>$state));
    if ($updated === false) return new WP_Error('physical_nexus_save_failed', $wpdb->last_error ?: 'The physical-nexus record could not be saved.');
    $this->mrm_tax_create_alert($state, 'physical_nexus_source_added', $source_type, absint($source_id), array('message'=>$reason), sanitize_key(substr(md5($source_type . '|' . $source_id . '|' . $state), 0, 24)));
    return array('recorded'=>true,'state'=>$state,'first_flagged_at'=>!empty($row['first_flagged_at']) ? $row['first_flagged_at'] : $now,'physical_nexus_reason'=>implode("\n", $reasons),'source_type'=>$source_type,'source_id'=>$source_id);
  }


  private function mrm_tax_flag_instructor_state($profile_request_id, $payload) { return $this->register_external_physical_nexus_source(array('state'=>$payload['state'] ?? '', 'country'=>'US', 'source_type'=>'instructor_profile', 'source_id'=>absint($profile_request_id), 'source_label'=>'Instructor profile request', 'details'=>sanitize_text_field($payload['name'] ?? ''))); }


  private function mrm_tax_measure_state_window($state, $start, $end, $rules) {
    global $wpdb;
    $state = $this->mrm_normalize_state_code($state); if ($state === '') return new WP_Error('invalid_tax_state', 'The state threshold calculation received an invalid state.');
    $rules = is_array($rules) ? $rules : array(); $sales_basis = sanitize_key($rules['sales_basis'] ?? 'gross');
    $basis_columns = array('gross'=>'gross_sales_cents','retail'=>'retail_sales_cents','taxable'=>'taxable_sales_cents');
    if ($sales_basis === 'none' || !isset($basis_columns[$sales_basis])) return array('sales_cents'=>0,'transaction_count'=>0);
    $basis_column = $basis_columns[$sales_basis];
    $included_channels = isset($rules['included_channels']) && is_array($rules['included_channels']) ? array_values(array_filter(array_map('sanitize_key', $rules['included_channels']))) : array('direct');
    $included_categories = isset($rules['included_categories']) && is_array($rules['included_categories']) ? array_values(array_filter(array_map('sanitize_key', $rules['included_categories']))) : array('all');
    $subtract_refunds = !empty($rules['subtract_refunds']);
    $where = array('customer_state = %s','occurred_at >= %s','occurred_at <= %s'); $args = array($state,$start,$end);
    if (!empty($included_channels) && !in_array('all', $included_channels, true)) { $where[] = 'sales_channel IN (' . implode(',', array_fill(0, count($included_channels), '%s')) . ')'; foreach ($included_channels as $channel) $args[] = $channel; }
    if (!empty($included_categories) && !in_array('all', $included_categories, true)) { $where[] = 'threshold_category IN (' . implode(',', array_fill(0, count($included_categories), '%s')) . ')'; foreach ($included_categories as $category) $args[] = $category; }
    $sales_expression = $subtract_refunds ? "COALESCE(SUM(GREATEST(0, {$basis_column} - refunded_sales_cents)), 0)" : "COALESCE(SUM({$basis_column}), 0)";
    $sql = "SELECT {$sales_expression} AS sales_cents, COALESCE(SUM(transaction_count), 0) AS transaction_count FROM {$this->table_tax_sales_ledger()} WHERE " . implode(' AND ', $where);
    $wpdb->last_error = ''; $row = $wpdb->get_row($wpdb->prepare($sql, $args), ARRAY_A);
    if ($wpdb->last_error !== '') return new WP_Error('tax_threshold_query_failed', $wpdb->last_error);
    return array('sales_cents'=>(int)($row['sales_cents'] ?? 0),'transaction_count'=>(int)($row['transaction_count'] ?? 0));
  }

  private function mrm_tax_threshold_value_reached($actual, $threshold, $comparison) {
    $actual = (float)$actual; $threshold = (float)$threshold; if ($threshold <= 0) return false;
    return sanitize_key($comparison) === 'greater_than' ? $actual > $threshold : $actual >= $threshold;
  }

  private function mrm_tax_recompute_all_thresholds() {
    global $wpdb;
    $catalog_result = $this->mrm_tax_sync_rule_catalog(); if (is_wp_error($catalog_result)) { $message=$catalog_result->get_error_message(); update_option('mrm_tax_threshold_recompute_error',$message,false); $this->mrm_tax_create_alert('AZ','threshold_recompute_failed','tax_monitor',0,array('message'=>$message),sanitize_key(gmdate('Y-m-d-H'))); return $catalog_result; }
    $state_table = $this->table_tax_state_status(); $sales_table = $this->table_tax_sales_ledger();
    $wpdb->last_error = ''; $states = $wpdb->get_results("SELECT * FROM {$state_table} ORDER BY state_code ASC", ARRAY_A); if ($wpdb->last_error !== '' || !is_array($states)) { $message=$wpdb->last_error ?: 'The state tax registry could not be loaded.'; update_option('mrm_tax_threshold_recompute_error',$message,false); $this->mrm_tax_create_alert('AZ','threshold_recompute_failed','tax_monitor',0,array('message'=>$message),sanitize_key(gmdate('Y-m-d-H'))); return new WP_Error('tax_states_unavailable',$message); }
    $now = current_time('mysql'); $errors = array();
    foreach ($states as $row) {
      $state = $this->mrm_normalize_state_code($row['state_code'] ?? ''); if ($state === '') continue;
      $rules = json_decode((string)($row['rules_json'] ?? ''), true); if (!is_array($rules)) $rules = array();
      if (array_key_exists('economic_nexus_applicable', $rules) && empty($rules['economic_nexus_applicable'])) {
        $updated = $wpdb->update($state_table, array('estimated_sales_cents'=>0,'estimated_transaction_count'=>0,'estimated_threshold_percent'=>0,'estimated_threshold_status'=>'not_applicable','last_recomputed_at'=>$now,'updated_at'=>$now), array('state_code'=>$state));
        if ($updated === false) $errors[] = $state . ': ' . $wpdb->last_error; continue;
      }
      $threshold_operator = sanitize_key($row['threshold_operator'] ?? ''); $has_monitoring_rule = (array_key_exists('economic_nexus_applicable', $rules) || !empty($row['threshold_amount_cents']) || !empty($row['threshold_transaction_count']) || $threshold_operator === 'not_applicable');
      if (!$has_monitoring_rule) { $wpdb->last_error = ''; $unconfigured = $wpdb->get_row($wpdb->prepare("SELECT COALESCE(SUM(gross_sales_cents), 0) AS sales_cents, COALESCE(SUM(transaction_count), 0) AS transaction_count FROM {$sales_table} WHERE customer_state = %s", $state), ARRAY_A); if ($wpdb->last_error !== '') { $errors[] = $state . ': ' . $wpdb->last_error; continue; } $wpdb->last_error = ''; $updated = $wpdb->update($state_table, array('estimated_sales_cents'=>(int)($unconfigured['sales_cents'] ?? 0),'estimated_transaction_count'=>(int)($unconfigured['transaction_count'] ?? 0),'estimated_threshold_percent'=>0,'estimated_threshold_status'=>'not_evaluated','last_recomputed_at'=>$now,'updated_at'=>$now), array('state_code'=>$state)); if ($updated === false || $wpdb->last_error !== '') $errors[] = $state . ': ' . ($wpdb->last_error ?: 'The unconfigured threshold state could not be updated.'); continue; }
      $windows = $this->mrm_tax_window_bounds(sanitize_key($row['measurement_window'] ?? 'rolling_12_months')); if (empty($windows)) { $errors[] = $state . ': no measurement window was produced.'; continue; }
      $amount_threshold = (int)($row['threshold_amount_cents'] ?? 0); $count_threshold = (int)($row['threshold_transaction_count'] ?? 0); $operator = sanitize_key($row['threshold_operator'] ?? 'amount');
      $amount_comparison = sanitize_key($rules['amount_comparison'] ?? 'at_least'); $count_comparison = sanitize_key($rules['count_comparison'] ?? 'at_least');
      $best = array('sales'=>0,'transactions'=>0,'percent'=>0,'reached'=>false,'at_exact_unreached'=>false,'start'=>'','end'=>'');
      foreach ($windows as $window) {
        $start = sanitize_text_field($window[0] ?? ''); $end = sanitize_text_field($window[1] ?? ''); if ($start === '' || $end === '') continue;
        $measurement = $this->mrm_tax_measure_state_window($state, $start, $end, $rules); if (is_wp_error($measurement)) { $errors[] = $state . ': ' . $measurement->get_error_message(); continue; }
        $sales = (int)$measurement['sales_cents']; $transactions = (int)$measurement['transaction_count'];
        $amount_percent = $amount_threshold > 0 ? ($sales / $amount_threshold) * 100 : 0; $count_percent = $count_threshold > 0 ? ($transactions / $count_threshold) * 100 : 0;
        $amount_reached = $this->mrm_tax_threshold_value_reached($sales, $amount_threshold, $amount_comparison); $count_reached = $this->mrm_tax_threshold_value_reached($transactions, $count_threshold, $count_comparison);
        switch ($operator) { case 'count': $reached=$count_reached; $percent=$count_threshold>0?$count_percent:0; break; case 'amount_or_count': $reached=$amount_reached||$count_reached; $available=array(); if($amount_threshold>0)$available[]=$amount_percent; if($count_threshold>0)$available[]=$count_percent; $percent=!empty($available)?max($available):0; break; case 'amount_and_count': $reached=$amount_reached&&$count_reached; $percent=($amount_threshold>0&&$count_threshold>0)?min($amount_percent,$count_percent):0; break; case 'not_applicable': $reached=false; $percent=0; break; case 'amount': default: $reached=$amount_reached; $percent=$amount_threshold>0?$amount_percent:0; break; }
        $at_exact_unreached = !$reached && (($amount_comparison === 'greater_than' && $amount_threshold > 0 && $sales === $amount_threshold) || ($count_comparison === 'greater_than' && $count_threshold > 0 && $transactions === $count_threshold));
        if ($reached || $percent > $best['percent']) $best = array('sales'=>$sales,'transactions'=>$transactions,'percent'=>$percent,'reached'=>$reached,'at_exact_unreached'=>$at_exact_unreached,'start'=>$start,'end'=>$end);
        if ($reached) break;
      }
      $percent = round(max(0, $best['percent']), 2);
      if (!empty($row['collection_active'])) $status='registered'; elseif (!empty($row['physical_nexus_flag'])) $status='physical_nexus_review'; elseif (!empty($best['reached'])) $status='threshold_reached'; elseif (!empty($best['at_exact_unreached'])) $status='at_threshold_not_exceeded'; elseif ($percent >= 90) $status='approaching_90'; elseif ($percent >= 75) $status='approaching_75'; else $status='below_75';
      $update = array('estimated_sales_cents'=>(int)$best['sales'],'estimated_transaction_count'=>(int)$best['transactions'],'estimated_threshold_percent'=>$percent,'estimated_threshold_status'=>$status,'last_recomputed_at'=>$now,'updated_at'=>$now); if ($status === 'threshold_reached' && empty($row['threshold_hit_at'])) $update['threshold_hit_at']=$now;
      $updated = $wpdb->update($state_table, $update, array('state_code'=>$state)); if ($updated === false) { $errors[] = $state . ': ' . $wpdb->last_error; continue; }
      if (!empty($row['physical_nexus_flag']) && empty($row['collection_active'])) { if ($this->mrm_tax_state_pending_registration_window_is_valid($row)) { $this->mrm_tax_resolve_state_workflow_alerts($state,array('physical_nexus_registration_required')); } else { $this->mrm_tax_create_alert($state,'physical_nexus_registration_required','tax_state',0,array('message'=>$state.' has a physical-nexus indicator but collection is not active and no valid controlled registration window is recorded.'),sanitize_key('physical_nexus_'.($row['rules_version']??self::TAX_RULES_VERSION))); } }
      if ($status === 'threshold_reached' && empty($row['collection_active'])) $this->mrm_tax_create_alert($state, 'threshold_100', 'tax_state', 0, array('message'=>$state . ' economic-nexus threshold has been reached.','window_start'=>$best['start'],'window_end'=>$best['end']), $this->mrm_tax_threshold_period_key($row, $best['start'], $best['end']));
      elseif ($percent >= 75 && empty($row['collection_active'])) { $level = $percent >= 90 ? '90' : '75'; $this->mrm_tax_create_alert($state, 'threshold_' . $level, 'tax_state', 0, array('message'=>$state . ' threshold progress is ' . $percent . '%.','window_start'=>$best['start'],'window_end'=>$best['end']), $this->mrm_tax_threshold_period_key($row, $best['start'], $best['end'])); }
    }
    if (!empty($errors)) { $message=implode(' | ', array_values(array_unique($errors))); update_option('mrm_tax_threshold_recompute_error',$message,false); $this->mrm_tax_create_alert('AZ','threshold_recompute_failed','tax_monitor',0,array('message'=>$message),sanitize_key(gmdate('Y-m-d-H'))); return new WP_Error('tax_threshold_recompute_failed',$message); }
    delete_option('mrm_tax_threshold_recompute_error'); update_option('mrm_tax_last_threshold_recompute_at',$now,false); $this->mrm_tax_resolve_alert_type('threshold_recompute_failed'); return true;
  }

  private function mrm_tax_threshold_period_key($state_row, $start, $end) { return sanitize_key(implode('_', array($state_row['rules_version'] ?? self::TAX_RULES_VERSION, $state_row['measurement_window'] ?? 'unknown', substr((string)$start, 0, 10), substr((string)$end, 0, 10))));
  }

  public function handle_tax_recompute_thresholds() { if(!current_user_can('manage_options')) wp_die('You do not have permission.'); check_admin_referer('mrm_tax_recompute_thresholds','mrm_tax_recompute_nonce'); $result = $this->mrm_tax_recompute_all_thresholds(); $url = admin_url('admin.php?page=' . self::TAX_MONITOR_MENU_SLUG); $url = is_wp_error($result) ? add_query_arg('tax_error', rawurlencode($result->get_error_message()), $url) : add_query_arg('thresholds_recomputed', '1', $url); wp_safe_redirect($url); exit; }

  public function handle_tax_reconcile_payment_intent() { if(!current_user_can('manage_options')) wp_die('You do not have permission.'); check_admin_referer('mrm_tax_reconcile_payment_intent','mrm_tax_reconcile_nonce'); $payment_intent_id=sanitize_text_field(wp_unslash($_POST['payment_intent_id'] ?? '')); if(!preg_match('/^pi_[A-Za-z0-9_]+$/',$payment_intent_id)){ wp_safe_redirect(add_query_arg('tax_error',rawurlencode('The PaymentIntent ID was invalid.'),admin_url('admin.php?page=' . self::TAX_MONITOR_MENU_SLUG))); exit; } $result=$this->mrm_tax_resync_payment_intent_id($payment_intent_id); $url=admin_url('admin.php?page=' . self::TAX_MONITOR_MENU_SLUG); $url=is_wp_error($result)?add_query_arg('tax_error',rawurlencode($result->get_error_message()),$url):add_query_arg('tax_reconciled',rawurlencode($payment_intent_id),$url); wp_safe_redirect($url); exit; }




  public function handle_tax_reconcile_invoice() { if(!current_user_can('manage_options')) wp_die('You do not have permission.'); check_admin_referer('mrm_tax_reconcile_invoice','mrm_tax_reconcile_invoice_nonce'); $invoice_id=sanitize_text_field(wp_unslash($_POST['invoice_id'] ?? '')); $url=admin_url('admin.php?page='.self::TAX_MONITOR_MENU_SLUG); if(!preg_match('/^in_[A-Za-z0-9_]+$/',$invoice_id)){ wp_safe_redirect(add_query_arg('tax_error',rawurlencode('The Stripe Invoice ID was invalid.'),$url)); exit; } $invoice=$this->stripe_api_request('GET','/v1/invoices/'.rawurlencode($invoice_id)); if(is_wp_error($invoice)){ wp_safe_redirect(add_query_arg('tax_error',rawurlencode($invoice->get_error_message()),$url)); exit; } $status=sanitize_key($invoice['automatic_tax']['status'] ?? ''); if($status!=='complete'){ wp_safe_redirect(add_query_arg('tax_error',rawurlencode('Invoice '.$invoice_id.' cannot be reconciled because Stripe automatic tax is '.($status!==''?$status:'unknown').'.'),$url)); exit; } $result=$this->mrm_tax_sync_managed_subscription_invoice_lifecycle($invoice,0); if(is_wp_error($result)){ wp_safe_redirect(add_query_arg('tax_error',rawurlencode($result->get_error_message()),$url)); exit; } $this->mrm_tax_resolve_alerts_by_reference('invoice_id',$invoice_id,array('subscription_invoice_tax_failed','subscription_invoice_ledger_failed','subscription_credit_note_sync_failed')); wp_safe_redirect(add_query_arg('tax_reconciled',rawurlencode($invoice_id),$url)); exit; }
  private function mrm_tax_run_state_workflow_reminders() {
    global $wpdb;$row=$wpdb->get_row("SELECT * FROM {$this->table_tax_state_status()} WHERE state_code='TX' AND physical_activity_started_at IS NOT NULL LIMIT 1",ARRAY_A);if(!is_array($row))return true;$types=array('tx_permit_status_day_7','tx_permit_processing_day_15','tx_registration_checkpoint_day_30','tx_registered_agent_checkpoint_day_45','tx_form_304_target_day_60','tx_filing_status_check_day_70','tx_registration_critical_day_75','tx_registration_final_day_85','tx_registration_overdue_day_90');if($this->mrm_tax_row_has_written_clearance($row))return $this->mrm_tax_resolve_state_workflow_alerts('TX',$types);
    try{$start=new DateTimeImmutable($row['physical_activity_started_at'],wp_timezone());$today=new DateTimeImmutable('today',wp_timezone());}catch(Throwable $error){return new WP_Error('texas_workflow_date_invalid','The Texas business-activity date is invalid.');}$workflow=$start->format('Y-m-d');$authority=sanitize_key($row['authority_registration_status']??'');$foreign=sanitize_key($row['foreign_registration_status']??'');$collect=!empty($row['collection_active']);$submitted=in_array($foreign,array('submitted','active','not_required_written_determination'),true);$complete=in_array($foreign,array('active','not_required_written_determination'),true);
    $permit_is_approved=in_array($authority,array('approved','active'),true);$day_7_message=$permit_is_approved?'Texas Day 7: The permit is approved. Verify that Texas collection has been activated in Stripe Tax.':'Texas Day 7: Check the sales-tax permit application status.';$day_15_message=$permit_is_approved?'Texas Day 15: The permit is approved, but Stripe collection is still inactive. Complete and verify Stripe Tax activation.':'Texas Day 15: Review permit processing and any requested information.';
    $milestones=array(7=>array($types[0],$day_7_message,!$collect),15=>array($types[1],$day_15_message,!$collect),30=>array($types[2],'Texas Day 30: Confirm foreign-registration funding and preparation.',!$submitted),45=>array($types[3],'Texas Day 45: Confirm registered-agent and Form 304 preparation.',!$submitted),60=>array($types[4],'Texas Day 60: Internal Form 304 filing target.',!$submitted),70=>array($types[5],'Texas Day 70: Verify the foreign-registration filing status.',!$complete),75=>array($types[6],'Texas Day 75: Critical foreign-registration warning.',!$complete),85=>array($types[7],'Texas Day 85: Final warning before the tracked outside date.',!$complete),90=>array($types[8],'Texas Day 90: Foreign registration is overdue and requires immediate administrative review.',!$complete));
    foreach($milestones as $day=>$milestone){if(!$milestone[2])continue;$date=$start->modify('+'.absint($day).' days')->setTime(0,0);if($today<$date)continue;$result=$this->mrm_tax_create_alert('TX',$milestone[0],'state_workflow',0,array('message'=>$milestone[1],'workflow_start_date'=>$workflow,'milestone_day'=>$day,'milestone_date'=>$date->format('Y-m-d')),sanitize_key('tx_'.$workflow.'_day_'.$day));if(is_wp_error($result))return $result;}
    if ($today >= $start->modify('+90 days')->setTime(0, 0) && !$complete && $foreign !== 'overdue') {
      $audit = $this->mrm_tax_append_workflow_audit($row['workflow_audit_json'] ?? '', array(
        'event' => 'foreign_registration_marked_overdue',
        'old_value' => $foreign,
        'new_value' => 'overdue',
        'outside_due_date' => $row['foreign_registration_outside_due_date'] ?? '',
        'administrator_id' => 0,
        'recorded_at' => current_time('mysql'),
      ));
      $wpdb->last_error = '';
      $saved = $wpdb->update($this->table_tax_state_status(), array(
        'foreign_registration_status' => 'overdue',
        'workflow_audit_json' => $audit,
        'updated_at' => current_time('mysql'),
      ), array('state_code' => 'TX'));
      if ($saved === false || $wpdb->last_error !== '') return new WP_Error('texas_overdue_status_save_failed', $wpdb->last_error ?: 'The Texas overdue workflow status could not be saved.');
      $verified_status = $wpdb->get_var($wpdb->prepare("SELECT foreign_registration_status FROM {$this->table_tax_state_status()} WHERE state_code = %s LIMIT 1", 'TX'));
      if (sanitize_key($verified_status) !== 'overdue') return new WP_Error('texas_overdue_status_unverified', 'The Texas overdue workflow status could not be verified.');
    }
    return true;
  }

  public function cron_tax_filing_deadline_check() {
    global $wpdb;
    $rows = $wpdb->get_results("SELECT * FROM {$this->table_tax_state_status()} WHERE collection_active = 1 OR (stripe_registration_status = 'active' AND stripe_livemode = 1)", ARRAY_A);
    $today = new DateTimeImmutable('today', wp_timezone());
    foreach ((array)$rows as $row) {
      $state = $this->mrm_normalize_state_code($row['state_code'] ?? '');
      $due_date = sanitize_text_field($row['next_return_due_date'] ?? '');
      if ($due_date === '') { $this->mrm_tax_create_alert($state, 'filing_due_date_missing', 'tax_state', 0, array('message'=>$state . ' is active for collection but has no next return due date.'), sanitize_key('missing_' . gmdate('Y-m'))); continue; }
      try { $due = new DateTimeImmutable($due_date . ' 00:00:00', wp_timezone()); } catch (Throwable $error) { continue; }
      $days = (int)$today->diff($due)->format('%r%a');
      if ($days < 0) { $this->mrm_tax_create_alert($state, 'tax_return_overdue', 'tax_state', 0, array('message'=>$state . ' return was due on ' . $due_date . '.'), sanitize_key($due_date)); continue; }
      if ($days <= 10) $this->mrm_tax_create_alert($state, 'tax_return_due_soon', 'tax_state', 0, array('message'=>$state . ' return is due on ' . $due_date . '.'), sanitize_key($due_date));
    }
    $administrative_issues = $this->mrm_tax_administrative_compliance_issues();
    foreach ($administrative_issues as $issue) {
      if (array_key_exists('alertable', $issue) && empty($issue['alertable'])) continue;
      $state = $this->mrm_normalize_state_code($issue['state'] ?? 'AZ');
      if ($state === '') $state = 'AZ';
      $code = sanitize_key($issue['code'] ?? 'administrative_compliance');
      $this->mrm_tax_create_alert($state, $code, 'tax_administration', 0, array('message'=>sanitize_text_field($issue['message'] ?? '')), sanitize_key(gmdate('Y-m')));
    }
    $workflow_result = $this->mrm_tax_run_state_workflow_reminders();
    if (is_wp_error($workflow_result)) $this->mrm_tax_create_alert('TX','state_workflow_reminder_processing_failed','state_workflow',0,array('message'=>$workflow_result->get_error_message()),sanitize_key(gmdate('Y-m-d')));
    $this->mrm_tax_enforce_global_subscription_holds();
  }

  public function handle_tax_compliance_settings_save() {
    if (!current_user_can('manage_options')) wp_die('You do not have permission.');
    check_admin_referer('mrm_tax_compliance_settings_save', 'mrm_tax_compliance_nonce');
    $allowed_monitoring_modes = array('stripe_professional_review');
    $allowed_providers = array('stripe_automated_filing','taxjar','taxually','host','cpa_or_tax_firm','manual_internal');
    $monitoring_mode = sanitize_key(wp_unslash($_POST['national_monitoring_mode'] ?? ''));
    $filing_provider = sanitize_key(wp_unslash($_POST['filing_provider'] ?? ''));
    if (!in_array($monitoring_mode, $allowed_monitoring_modes, true)) $monitoring_mode = '';
    if (!in_array($filing_provider, $allowed_providers, true)) $filing_provider = '';
    update_option(self::OPT_TAX_COMPLIANCE_SETTINGS, array(
      'national_monitoring_mode'=>$monitoring_mode,
      'professional_reviewed_at'=>sanitize_text_field(wp_unslash($_POST['professional_reviewed_at'] ?? '')),
      'professional_reference'=>sanitize_textarea_field(wp_unslash($_POST['professional_reference'] ?? '')),
      'filing_provider'=>$filing_provider,
      'filing_provider_status'=>!empty($_POST['filing_provider_active']) ? 'active' : 'inactive',
      'filing_provider_effective_date'=>sanitize_text_field(wp_unslash($_POST['filing_provider_effective_date'] ?? '')),
      'filing_provider_reference'=>sanitize_textarea_field(wp_unslash($_POST['filing_provider_reference'] ?? '')),
    ), false);
    wp_safe_redirect(add_query_arg('compliance_settings_saved','1',admin_url('admin.php?page=' . self::TAX_MONITOR_MENU_SLUG)));
    exit;
  }

  public function handle_tax_alert_email_action() {
    if (!current_user_can('manage_options')) wp_die('You do not have permission to manage tax-alert emails.');
    global $wpdb;
    $id = absint($_POST['alert_id'] ?? 0);
    if ($id <= 0) wp_die('Invalid alert ID.');
    check_admin_referer('mrm_tax_alert_email_action_' . $id, 'mrm_tax_alert_email_nonce');
    $action = sanitize_key(wp_unslash($_POST['email_resolution_action'] ?? ''));
    $note = sanitize_textarea_field(wp_unslash($_POST['email_resolution_note'] ?? ''));
    $url = admin_url('admin.php?page=' . self::TAX_MONITOR_MENU_SLUG);
    if ($note === '') { wp_safe_redirect(add_query_arg('tax_error', rawurlencode('An administrator note is required for every email-recovery action.'), $url)); exit; }
    if (!in_array($action, array('retry','mark_sent','waive'), true)) wp_die('Invalid email-recovery action.');
    $table = $this->table_tax_alerts();
    $wpdb->last_error = '';
    $alert = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d LIMIT 1", $id), ARRAY_A);
    if ($wpdb->last_error !== '' || !is_array($alert)) { wp_safe_redirect(add_query_arg('tax_error', rawurlencode($wpdb->last_error ?: 'The tax alert could not be loaded.'), $url)); exit; }
    if (sanitize_key($alert['alert_status'] ?? '') !== 'open') { wp_safe_redirect(add_query_arg('tax_error', rawurlencode('This tax alert has already been resolved. The stale email-recovery form was not applied and no email was sent.'), $url)); exit; }
    $old = sanitize_key($alert['email_status'] ?? '');
    if ($old === 'sending') {
      $transition = $this->mrm_tax_transition_stale_alert_email_claim_to_uncertain($alert);
      if (is_wp_error($transition)) { wp_safe_redirect(add_query_arg('tax_error', rawurlencode($transition->get_error_message()), $url)); exit; }
      if ($transition !== true) { wp_safe_redirect(add_query_arg('tax_error', rawurlencode('This alert email is currently being sent. Recovery actions are unavailable until the sending claim expires or completes.'), $url)); exit; }
      $wpdb->last_error = '';
      $alert = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d LIMIT 1", $id), ARRAY_A);
      if ($wpdb->last_error !== '' || !is_array($alert)) { wp_safe_redirect(add_query_arg('tax_error', rawurlencode($wpdb->last_error ?: 'The expired email claim could not be reloaded.'), $url)); exit; }
      if (sanitize_key($alert['alert_status'] ?? '') !== 'open') { wp_safe_redirect(add_query_arg('tax_error', rawurlencode('The tax alert was resolved before the recovery action could be applied.'), $url)); exit; }
      $old = sanitize_key($alert['email_status'] ?? '');
    }
    if (!in_array($old, array('not_sent','failed','uncertain'), true)) { wp_safe_redirect(add_query_arg('tax_error', rawurlencode('This email state no longer permits an administrator recovery action.'), $url)); exit; }
    $expected_revision = max(1, absint($alert['alert_revision'] ?? 1));
    $now = current_time('mysql');
    $details = $this->mrm_tax_append_alert_email_recovery_history($alert['details_json'] ?? '', array('action'=>$action, 'old_email_status'=>$old, 'note'=>$note, 'administrator_id'=>get_current_user_id(), 'recorded_at'=>$now));
    $wpdb->last_error = '';
    if ($action === 'retry') {
      $saved = $wpdb->query($wpdb->prepare("UPDATE {$table} SET details_json = %s, email_status = 'failed', email_claim_token = NULL, email_claimed_at = NULL, email_last_error = %s, updated_at = %s, alert_revision = alert_revision + 1 WHERE id = %d AND alert_status = 'open' AND email_status = %s AND alert_revision = %d", $details, 'Administrator authorized a deliberate retry: ' . $note, $now, $id, $old, $expected_revision));
    } elseif ($action === 'mark_sent') {
      $emailed_at = !empty($alert['emailed_at']) ? $alert['emailed_at'] : $now;
      $saved = $wpdb->query($wpdb->prepare("UPDATE {$table} SET details_json = %s, email_status = 'sent', email_claim_token = NULL, email_claimed_at = NULL, email_last_error = NULL, emailed_at = %s, updated_at = %s, alert_revision = alert_revision + 1 WHERE id = %d AND alert_status = 'open' AND email_status = %s AND alert_revision = %d", $details, $emailed_at, $now, $id, $old, $expected_revision));
    } else {
      $saved = $wpdb->query($wpdb->prepare("UPDATE {$table} SET details_json = %s, email_status = 'waived', email_claim_token = NULL, email_claimed_at = NULL, email_last_error = %s, updated_at = %s, alert_revision = alert_revision + 1 WHERE id = %d AND alert_status = 'open' AND email_status = %s AND alert_revision = %d", $details, 'Administrator waived further automatic delivery: ' . $note, $now, $id, $old, $expected_revision));
    }
    if ($saved === false || $wpdb->last_error !== '') { wp_safe_redirect(add_query_arg('tax_error', rawurlencode($wpdb->last_error ?: 'The email-recovery action could not be saved.'), $url)); exit; }
    if ((int) $saved !== 1) { wp_safe_redirect(add_query_arg('tax_error', rawurlencode('The alert was resolved or changed by another process before the recovery action could be applied. Reload the page and review its current status.'), $url)); exit; }
    if ($action === 'retry') { $result = $this->mrm_tax_attempt_alert_email($id); if (is_wp_error($result)) { wp_safe_redirect(add_query_arg(array('tax_email_action'=>'retry_pending','tax_email_alert_id'=>$id), $url)); exit; } }
    $verified = $wpdb->get_var($wpdb->prepare("SELECT email_status FROM {$table} WHERE id = %d LIMIT 1", $id));
    $expected = $action === 'waive' ? 'waived' : 'sent';
    if (sanitize_key($verified) !== $expected) { wp_safe_redirect(add_query_arg('tax_error', rawurlencode('The email-recovery action could not be verified.'), $url)); exit; }
    wp_safe_redirect(add_query_arg(array('tax_email_action'=>$action,'tax_email_alert_id'=>$id), $url)); exit;
  }
  public function handle_tax_state_save() {
