    $now=new DateTimeImmutable('now',wp_timezone());foreach(array('authority_registration_submitted_at','physical_activity_started_at') as $key)if($dates[$key]&&new DateTimeImmutable($dates[$key],wp_timezone())>$now)$fail('Permit submission and activity dates cannot be in the future.');$application_ref=$text('authority_registration_application_reference');if(in_array($authority,array('application_submitted','additional_information_requested','approved','active'),true)&&(!$dates['authority_registration_submitted_at']||$application_ref===''))$fail('The selected permit status requires a submission timestamp and application reference.');$written_ref=$area('written_determination_reference');if($authority==='not_required_written_determination'&&(!$dates['written_determination_reviewed_at']||$written_ref===''))$fail('A written-determination date and reference are required.');$foreign_ref=$text('foreign_registration_reference');if(in_array($foreign,array('submitted','correction_required','active'),true)&&(!$dates['foreign_registration_submitted_at']||$foreign_ref===''))$fail('The selected foreign-registration status requires a submission timestamp and filing reference.');if($foreign==='active'&&!$dates['foreign_registration_accepted_at'])$fail('Active foreign registration requires an acceptance timestamp.');if($dates['foreign_registration_accepted_at']&&$dates['foreign_registration_submitted_at']&&$dates['foreign_registration_accepted_at']<$dates['foreign_registration_submitted_at'])$fail('Acceptance cannot precede submission.');$agent_ref=$text('registered_agent_reference');if(in_array($agent,array('engaged','active'),true)&&$agent_ref==='')$fail('The selected registered-agent status requires a reference.');if($dates['foreign_registration_internal_due_date']&&$dates['foreign_registration_outside_due_date']&&$dates['foreign_registration_internal_due_date']>$dates['foreign_registration_outside_due_date'])$fail('The internal due date cannot follow the outside due date.');$reserve_result=$state==='TX'?$this->mrm_tax_parse_admin_nonnegative_integer($_POST['pending_tax_reserve_rate_bps']??'','Pending-tax reserve rate',10000):null;$grace_result=$this->mrm_tax_parse_admin_nonnegative_integer($_POST['foreign_registration_grace_days']??'','Foreign-registration grace days',3650);if(is_wp_error($reserve_result))$fail($reserve_result->get_error_message());if(is_wp_error($grace_result))$fail($grace_result->get_error_message());$bps=$state==='TX'?($reserve_result===null?(($old['pending_tax_reserve_rate_bps']??'')===''?null:(int)$old['pending_tax_reserve_rate_bps']):$reserve_result):((($old['pending_tax_reserve_rate_bps']??'')==='')?null:(int)$old['pending_tax_reserve_rate_bps']);$grace=$grace_result===null?(($old['foreign_registration_grace_days']??'')===''?null:(int)$old['foreign_registration_grace_days']):$grace_result;
    $activity=$dates['physical_activity_started_at'];$old_activity=sanitize_text_field($old['physical_activity_started_at']??'');if($old_activity!==''&&$activity===null)$fail('The recorded business-activity start cannot be cleared. Enter a corrected date and a correction reason instead.');$audit=$old['workflow_audit_json']??'';$old_workflow='';if($old_activity!==''&&$activity!==$old_activity){$reason=$area('physical_activity_correction_reason');if($reason==='')$fail('An activity-date correction reason is required.');$old_workflow=substr($old_activity,0,10);$audit=$this->mrm_tax_append_workflow_audit($audit,array('event'=>'physical_activity_date_corrected','old_value'=>$old_activity,'new_value'=>$activity,'administrator_id'=>get_current_user_id(),'recorded_at'=>current_time('mysql'),'correction_reason'=>$reason));if($state==='TX'&&$activity){$base=new DateTimeImmutable($activity,wp_timezone());$dates['foreign_registration_internal_due_date']=$base->modify('+60 days')->format('Y-m-d');$dates['foreign_registration_outside_due_date']=$base->modify('+90 days')->format('Y-m-d');}}
    $pending_start=sanitize_text_field($old['pending_tax_tracking_started_at']??'');$pending_end=sanitize_text_field($old['pending_tax_tracking_ended_at']??'');
    if($activity!==$old_activity&&$activity!==null){$pending_start=$activity;if(!empty($old['collection_active'])){$pending_end=$activity;$stripe_start=sanitize_text_field($old['stripe_collection_started_at']??'');if($stripe_start!==''){try{if(new DateTimeImmutable($stripe_start,wp_timezone())>=new DateTimeImmutable($activity,wp_timezone()))$pending_end=$stripe_start;}catch(Throwable $error){$pending_end=$activity;}}}else{$pending_end=null;}}
    if($state==='TX'&&$activity!==null){$base=new DateTimeImmutable($activity,wp_timezone());$dates['foreign_registration_internal_due_date']=$base->modify('+60 days')->format('Y-m-d');$dates['foreign_registration_outside_due_date']=$base->modify('+90 days')->format('Y-m-d');if($grace===null)$grace=90;if($bps===null)$bps=825;}
    $data=array('authority_registration_status'=>$authority,'authority_registration_submitted_at'=>$dates['authority_registration_submitted_at'],'authority_registration_application_reference'=>$application_ref,'authority_registration_number'=>$text('authority_registration_number'),'authority_registration_effective_date'=>$dates['authority_registration_effective_date'],'written_determination_reviewed_at'=>$dates['written_determination_reviewed_at'],'written_determination_reference'=>$written_ref,'physical_activity_started_at'=>$activity,'pending_tax_tracking_started_at'=>$pending_start!==''?$pending_start:null,'pending_tax_tracking_ended_at'=>$pending_end!==''?$pending_end:null,'foreign_registration_status'=>$foreign,'foreign_registration_grace_days'=>$grace,'foreign_registration_internal_due_date'=>$dates['foreign_registration_internal_due_date'],'foreign_registration_outside_due_date'=>$dates['foreign_registration_outside_due_date'],'registered_agent_status'=>$agent,'registered_agent_reference'=>$agent_ref,'foreign_registration_submitted_at'=>$dates['foreign_registration_submitted_at'],'foreign_registration_accepted_at'=>$dates['foreign_registration_accepted_at'],'foreign_registration_reference'=>$foreign_ref,'pending_tax_reserve_rate_bps'=>$bps,'pending_tax_reconciled_at'=>$dates['pending_tax_reconciled_at'],'filing_status'=>$filing,'filing_frequency'=>$text('filing_frequency'),'next_return_due_date'=>$dates['next_return_due_date'],'last_return_filed_at'=>$dates['last_return_filed_at'],'last_return_confirmation'=>$area('last_return_confirmation'),'admin_notes'=>$area('admin_notes'),'workflow_audit_json'=>$audit,'updated_at'=>current_time('mysql'));
    $wpdb->last_error='';$saved=$wpdb->update($this->table_tax_state_status(),$data,array('state_code'=>$state));if($saved===false||$wpdb->last_error!=='')$fail($wpdb->last_error?:'The workflow could not be saved.');$verify=$this->mrm_tax_get_state_row($state);if(is_wp_error($verify))$fail($verify->get_error_message());foreach($data as $key=>$value)if($key!=='updated_at'&&(string)($verify[$key]??'')!==(string)($value??''))$fail('The saved workflow values could not be verified.');
    $permit_alerts = array('tx_permit_status_day_7', 'tx_permit_processing_day_15');
    $preparation_alerts = array('tx_registration_checkpoint_day_30', 'tx_registered_agent_checkpoint_day_45', 'tx_form_304_target_day_60');
    $remaining_alerts = array_merge($preparation_alerts, array('tx_filing_status_check_day_70', 'tx_registration_critical_day_75', 'tx_registration_final_day_85', 'tx_registration_overdue_day_90'));
    $resolve_workflow_alerts = function ($alert_types, $workflow_start = '') use ($state, $fail) {
      $result = $this->mrm_tax_resolve_state_workflow_alerts($state, $alert_types, $workflow_start);
      if (is_wp_error($result)) $fail($result->get_error_message());
    };
    if ($old_workflow !== '') $resolve_workflow_alerts(array_merge($permit_alerts, $remaining_alerts), $old_workflow);
    if (!empty($dates['foreign_registration_submitted_at'])) $resolve_workflow_alerts($preparation_alerts);
    if (in_array($foreign, array('active', 'not_required_written_determination'), true)) $resolve_workflow_alerts($remaining_alerts);
    if (!empty($verify['collection_active'])) $resolve_workflow_alerts($permit_alerts);
    if ($authority === 'not_required_written_determination') $resolve_workflow_alerts(array_merge($permit_alerts, $remaining_alerts));
    wp_safe_redirect(add_query_arg('state_saved',rawurlencode($state),$url));exit;
  }

  public function handle_tax_resolve_direct_invoice_refund() {
    if (!current_user_can('manage_options')) wp_die('You do not have permission.'); check_admin_referer('mrm_tax_resolve_direct_invoice_refund','mrm_tax_direct_refund_nonce');
    $url=admin_url('admin.php?page='.self::TAX_MONITOR_MENU_SLUG); $refund_id=sanitize_text_field(wp_unslash($_POST['refund_id'] ?? '')); $invoice_id=sanitize_text_field(wp_unslash($_POST['invoice_id'] ?? '')); $notes=sanitize_textarea_field(wp_unslash($_POST['resolution_notes'] ?? '')); $sales_cents=$this->mrm_money_to_cents(wp_unslash($_POST['refunded_sales'] ?? '0'),0); $tax_cents=$this->mrm_money_to_cents(wp_unslash($_POST['refunded_tax'] ?? '0'),0);
    $fail=function($message) use ($url){ wp_safe_redirect(add_query_arg('tax_error',rawurlencode($message),$url)); exit; };
    if (!preg_match('/^re_[A-Za-z0-9_]+$/',$refund_id) || !preg_match('/^in_[A-Za-z0-9_]+$/',$invoice_id)) $fail('The Refund or Invoice ID was invalid.'); if ($notes === '') $fail('Resolution notes are required.');
    $refund=$this->stripe_retrieve_refund($refund_id); if (is_wp_error($refund)) $fail($refund->get_error_message()); if (sanitize_key($refund['status'] ?? '') !== 'succeeded') $fail('Only a succeeded direct refund can be allocated to the subscription tax ledger.'); $refund_amount=absint($refund['amount'] ?? 0); if ($sales_cents < 0 || $tax_cents < 0 || ($sales_cents + $tax_cents) !== $refund_amount) $fail('The refunded pretax and tax amounts must add exactly to the Stripe Refund amount.');
    $invoice=$this->stripe_api_request('GET','/v1/invoices/'.rawurlencode($invoice_id)); if (is_wp_error($invoice)) $fail($invoice->get_error_message()); $invoice_charge_id=$this->mrm_stripe_invoice_charge_id($invoice); if (is_wp_error($invoice_charge_id)) $fail($invoice_charge_id->get_error_message()); $refund_charge_id=$this->mrm_stripe_expandable_id($refund['charge'] ?? ''); if ($refund_charge_id === '' || $refund_charge_id !== $invoice_charge_id) $fail('The Refund does not belong to the selected subscription Invoice.');
    global $wpdb; $external_id='invoice:'.$invoice_id.':sheet_music_subscription'; $ledger_row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table_tax_sales_ledger()} WHERE external_id = %s LIMIT 1",$external_id),ARRAY_A); if (!is_array($ledger_row)) $fail('The subscription Invoice ledger row does not exist.'); $metadata=json_decode((string)($ledger_row['metadata_json'] ?? ''),true); if (!is_array($metadata)) $metadata=array(); if (!is_array($metadata['manual_direct_refunds'] ?? null)) $metadata['manual_direct_refunds']=array(); $metadata['manual_direct_refunds'][$refund_id]=array('sales_cents'=>$sales_cents,'tax_cents'=>$tax_cents,'notes'=>$notes,'resolved_by_user_id'=>get_current_user_id(),'resolved_at'=>current_time('mysql'));
    $wpdb->last_error=''; $saved=$wpdb->update($this->table_tax_sales_ledger(),array('metadata_json'=>wp_json_encode($metadata),'updated_at'=>current_time('mysql')),array('external_id'=>$external_id)); if ($saved === false || $wpdb->last_error !== '') $fail($wpdb->last_error ?: 'The direct-refund allocation could not be saved.');
    $sync_result=$this->mrm_tax_sync_subscription_invoice_refunds($invoice_id,0); if (is_wp_error($sync_result)) $fail($sync_result->get_error_message()); $resolution_result=$this->mrm_tax_resolve_review_alert('subscription_direct_refund_review_required',$refund_id,array('resolution_notes'=>$notes,'sales_cents'=>$sales_cents,'tax_cents'=>$tax_cents,'resolved_by_user_id'=>get_current_user_id(),'resolved_at'=>current_time('mysql'))); if (is_wp_error($resolution_result)) $fail($resolution_result->get_error_message()); wp_safe_redirect(add_query_arg('tax_reconciled',rawurlencode($refund_id),$url)); exit;
  }

  public function handle_tax_resolve_refund_recovery() {
    if(!current_user_can('manage_options')) wp_die('You do not have permission.'); check_admin_referer('mrm_tax_resolve_refund_recovery','mrm_tax_refund_recovery_nonce');
    $url=admin_url('admin.php?page='.self::TAX_MONITOR_MENU_SLUG); $refund_id=sanitize_text_field(wp_unslash($_POST['refund_id'] ?? '')); $alert_type=sanitize_key(wp_unslash($_POST['alert_type'] ?? 'refund_failure_recovery_required')); $notes=sanitize_textarea_field(wp_unslash($_POST['resolution_notes'] ?? ''));
    $allowed_alert_types=array('refund_failure_recovery_required','partial_refund_business_review_required');
    $fail=function($message) use ($url){ wp_safe_redirect(add_query_arg('tax_error',rawurlencode($message),$url)); exit; };
    if(!in_array($alert_type,$allowed_alert_types,true)) $fail('The refund review type was invalid.');
    foreach(array('order_access_reviewed','payout_reviewed','accounting_reviewed','customer_resolution_reviewed') as $confirmation) if(empty($_POST[$confirmation])) $fail('Every refund review confirmation must be checked.');
    if(!preg_match('/^re_[A-Za-z0-9_]+$/',$refund_id) || $notes==='') $fail('A valid Refund ID and resolution notes are required.');
    $refund=$this->stripe_retrieve_refund($refund_id); if(is_wp_error($refund)) $fail($refund->get_error_message()); $refund_status=sanitize_key($refund['status'] ?? '');
    if($alert_type==='refund_failure_recovery_required' && !in_array($refund_status,array('failed','canceled'),true)) $fail('The Refund is not currently failed or canceled.');
    if($alert_type==='partial_refund_business_review_required' && $refund_status!=='succeeded') $fail('The partial Refund is not currently succeeded.');
    $payment_intent_id=$this->mrm_stripe_expandable_id($refund['payment_intent'] ?? ''); $charge_id=$this->mrm_stripe_expandable_id($refund['charge'] ?? ''); $invoice_id='';
    if($charge_id!==''){ $charge=$this->stripe_retrieve_charge($charge_id); if(is_wp_error($charge)) $fail($charge->get_error_message()); $invoice_id=$this->mrm_stripe_expandable_id($charge['invoice'] ?? ''); }
    $tax_result=$invoice_id!=='' ? $this->mrm_tax_sync_subscription_invoice_refunds($invoice_id,0) : $this->mrm_tax_sync_refund_reversal($payment_intent_id,$refund_id,0); if(is_wp_error($tax_result)) $fail('The tax ledger must be reconciled before the review can be resolved: '.$tax_result->get_error_message());
    $resolution_result=$this->mrm_tax_resolve_review_alert($alert_type,$refund_id,array('resolution_notes'=>$notes,'order_access_reviewed'=>true,'payout_reviewed'=>true,'accounting_reviewed'=>true,'customer_resolution_reviewed'=>true,'refund_status'=>$refund_status,'resolved_by_user_id'=>get_current_user_id(),'resolved_at'=>current_time('mysql'))); if(is_wp_error($resolution_result)) $fail($resolution_result->get_error_message());
    wp_safe_redirect(add_query_arg('tax_reconciled',rawurlencode($refund_id),$url)); exit;
  }



  public function render_sales_tax_nexus_page() {
    if(!current_user_can('manage_options')) wp_die('You do not have permission to access this page.'); global $wpdb; $this->maybe_install_or_upgrade_db(); $rows=$wpdb->get_results("SELECT * FROM {$this->table_tax_state_status()} ORDER BY state_name ASC",ARRAY_A); $live=$this->mrm_tax_is_live_stripe_key(); $readiness=$this->mrm_tax_live_checkout_readiness(); $administrative_issues=$this->mrm_tax_administrative_compliance_issues(); $reconciliation_result=$this->mrm_tax_ledger_reconciliation_rows(50); $reconciliation_error=is_wp_error($reconciliation_result)?$reconciliation_result:null; $reconciliation_rows=is_wp_error($reconciliation_result)?array():$reconciliation_result; $critical_alert_result=$this->mrm_tax_critical_open_alerts(50); $critical_alert_error=is_wp_error($critical_alert_result)?$critical_alert_result:null; $critical_alerts=is_wp_error($critical_alert_result)?array():$critical_alert_result; $email_attention_result=$this->mrm_tax_email_attention_alerts(100); $email_attention_error=is_wp_error($email_attention_result)?$email_attention_result:null; $email_attention_alerts=is_wp_error($email_attention_result)?array():$email_attention_result; ?>
    <div class="wrap"><h1>Sales Tax &amp; Nexus</h1>
      <?php if(isset($_GET['tax_error'])):?><div class="notice notice-error"><p><?php echo esc_html(wp_unslash($_GET['tax_error'])); ?></p></div><?php endif; ?>
      <?php if($reconciliation_error): ?><div class="notice notice-error"><p><strong>Tax-ledger reconciliation could not be loaded.</strong></p><p><?php echo esc_html($reconciliation_error->get_error_message()); ?></p></div><?php endif; ?>
      <?php if($critical_alert_error): ?><div class="notice notice-error"><p><strong>Critical tax alerts could not be loaded.</strong></p><p><?php echo esc_html($critical_alert_error->get_error_message()); ?></p></div><?php endif; ?>
      <?php if($email_attention_error): ?><div class="notice notice-error"><p>Tax-alert email attention records could not be loaded: <?php echo esc_html($email_attention_error->get_error_message()); ?></p></div><?php endif; ?>
      <?php if(isset($_GET['tax_email_action'])): $email_action=sanitize_key(wp_unslash($_GET['tax_email_action']));$email_alert_id=absint($_GET['tax_email_alert_id']??0); ?><div class="notice <?php echo $email_action==='retry_pending'?'notice-warning':'notice-success'; ?>"><p><?php if($email_action==='retry_pending'): ?>Alert email #<?php echo esc_html($email_alert_id); ?> remains pending after the deliberate retry.<?php elseif($email_action==='retry'): ?>Alert email #<?php echo esc_html($email_alert_id); ?> was retried successfully.<?php elseif($email_action==='mark_sent'): ?>Alert email #<?php echo esc_html($email_alert_id); ?> was marked sent after administrator verification.<?php elseif($email_action==='waive'): ?>Further automatic delivery was waived for alert #<?php echo esc_html($email_alert_id); ?>.<?php endif; ?></p></div><?php endif; ?>
      <?php if(isset($_GET['stripe_sync'])):?><div class="notice notice-success"><p>Stripe registrations synced.</p></div><?php endif; ?>
      <?php
      if (isset($_GET['stripe_sync_warning'])) :
        $warning_count = max(1, absint($_GET['stripe_sync_warning']));
      ?>
        <div class="notice notice-warning">
          <p>
            Stripe registrations were successfully retrieved, verified, and committed. However,
            <?php echo esc_html($warning_count); ?>
            activation notification or reporting
            <?php echo $warning_count === 1 ? 'task remains' : 'tasks remain'; ?>
            pending. Review the open noncritical tax alerts. Customer checkout and subscription
            processing are not blocked by this warning.
          </p>
        </div>
      <?php endif; ?>
      <?php if(isset($_GET['thresholds_recomputed'])):?><div class="notice notice-success"><p>State thresholds recomputed.</p></div><?php endif; ?>
      <?php if(isset($_GET['state_saved'])):?><div class="notice notice-success"><p>Saved <?php echo esc_html(wp_unslash($_GET['state_saved'])); ?>.</p></div><?php endif; ?><?php if(isset($_GET['tax_reconciled'])):?><div class="notice notice-success"><p>Tax reconciliation completed for <code><?php echo esc_html(wp_unslash($_GET['tax_reconciled'])); ?></code>.</p></div><?php endif; ?>
      <p><strong>Stripe mode:</strong> <?php echo $live ? '<span style="color:#008a20;font-weight:700;">LIVE</span>' : '<span style="color:#b32d2e;font-weight:700;">TEST</span>'; ?></p>
      <?php if(!$live): ?><div class="notice notice-warning"><p>The site is using a Stripe test key. Test-mode registrations do not satisfy the production approval gate.</p></div><?php endif; ?><?php if($live): ?><?php if(is_wp_error($readiness)): ?><div class="notice notice-error"><p><strong>Live checkout readiness: BLOCKED</strong></p><p><?php echo esc_html($readiness->get_error_message()); ?></p></div><?php else: ?><div class="notice notice-success"><p><strong>Live checkout readiness: READY</strong></p></div><?php endif; ?><?php endif; ?><?php if(!empty($administrative_issues)): ?><div class="notice notice-warning"><p><strong>Tax administration requires attention</strong></p><ul style="list-style:disc;padding-left:22px;"><?php foreach($administrative_issues as $issue): ?><li><?php echo esc_html($issue['message'] ?? ''); ?></li><?php endforeach; ?></ul></div><?php endif; ?>
      <div style="background:#fff;border:1px solid #dcdcde;padding:18px;margin:18px 0;max-width:1000px;"><h2>How this monitor works</h2><p>This page reads Stripe Tax settings and active registrations, then combines them with the Stripe Tax transactions and payment totals recorded by this site.</p><p><strong>This page includes administrator-only state workflow controls.</strong> Use the controls below to document permit applications, filing information, pending-period tracking, foreign registration, registered-agent progress, written determinations, and return deadlines. Stripe remains the source of truth for whether tax collection is active.</p><p>The site still flags instructor or presenter states as physical-presence signals because Stripe cannot infer every off-payment business activity.</p></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="display:inline-block;margin-right:8px;"><?php wp_nonce_field('mrm_tax_sync_stripe_registrations','mrm_tax_sync_nonce'); ?><input type="hidden" name="action" value="mrm_tax_sync_stripe_registrations"><button class="button button-primary">Sync Stripe Registrations</button></form>
      <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="display:inline-block;margin-right:8px;"><?php wp_nonce_field('mrm_tax_recompute_thresholds','mrm_tax_recompute_nonce'); ?><input type="hidden" name="action" value="mrm_tax_recompute_thresholds"><button class="button">Recompute Tracked Sales</button></form>
      <a class="button" href="https://dashboard.stripe.com/tax/locations?primary_tab=needs_attention" target="_blank" rel="noopener">Stripe Tax &gt; Needs attention</a> <a class="button" href="https://dashboard.stripe.com/tax/registrations" target="_blank" rel="noopener">Stripe Tax &gt; Registrations</a> <a class="button" href="https://dashboard.stripe.com/tax/transactions" target="_blank" rel="noopener">Stripe Tax &gt; Transactions</a>
      <?php if(!empty($reconciliation_rows)): ?><div style="background:#fff;border:1px solid #d63638;padding:18px;margin:18px 0;"><h2>Tax Transactions Requiring Reconciliation</h2><p>Live checkout remains blocked until these transactions or refund reversals are confirmed.</p><table class="widefat striped"><thead><tr><th>Ledger ID</th><th>Source</th><th>Stripe Reference</th><th>State</th><th>Status</th><th>Error</th><th>Occurred</th><th>Action</th></tr></thead><tbody><?php foreach($reconciliation_rows as $tax_row): ?><tr><td><?php echo esc_html($tax_row['id']); ?></td><td><?php echo esc_html($tax_row['source_type']); ?></td><td><code><?php echo esc_html($tax_row['payment_intent_id'] ?: ($tax_row['invoice_id'] ?: 'Unavailable')); ?></code></td><td><?php echo esc_html($tax_row['customer_state']); ?></td><td><?php echo esc_html($tax_row['tax_transaction_status']); ?></td><td><?php echo esc_html($tax_row['association_error'] ?: 'Missing or incomplete tax reconciliation record'); ?></td><td><?php echo esc_html($tax_row['occurred_at']); ?></td><td><?php if(!empty($tax_row['payment_intent_id'])): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('mrm_tax_reconcile_payment_intent','mrm_tax_reconcile_nonce'); ?><input type="hidden" name="action" value="mrm_tax_reconcile_payment_intent"><input type="hidden" name="payment_intent_id" value="<?php echo esc_attr($tax_row['payment_intent_id']); ?>"><button type="submit" class="button button-small">Reconcile Payment</button></form><?php elseif(!empty($tax_row['invoice_id'])): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('mrm_tax_reconcile_invoice','mrm_tax_reconcile_invoice_nonce'); ?><input type="hidden" name="action" value="mrm_tax_reconcile_invoice"><input type="hidden" name="invoice_id" value="<?php echo esc_attr($tax_row['invoice_id']); ?>"><button type="submit" class="button button-small">Reconcile Invoice</button></form><?php else: ?>Manual Stripe review required<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
      <?php if(!empty($critical_alerts)): ?><div style="background:#fff;border:1px solid #d63638;padding:18px;margin:18px 0;"><h2>Critical Tax Alerts</h2><p>These alerts must be reconciled before live checkout can report READY.</p><table class="widefat striped"><thead><tr><th>Alert</th><th>State</th><th>Message</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($critical_alerts as $alert): $details=json_decode((string)($alert['details_json'] ?? ''),true); if(!is_array($details)) $details=array(); $payment_intent_id=sanitize_text_field($details['payment_intent_id'] ?? ''); $invoice_id=sanitize_text_field($details['invoice_id'] ?? ''); $refund_id=sanitize_text_field($details['refund_id'] ?? ''); ?><tr><td><?php echo esc_html($alert['alert_type']); ?></td><td><?php echo esc_html($alert['state_code'] ?: '—'); ?></td><td><?php echo esc_html($details['message'] ?? 'Tax review required.'); ?></td><td><?php echo esc_html($alert['created_at']); ?></td><td><?php if(in_array($alert['alert_type'],array('refund_failure_recovery_required','partial_refund_business_review_required'),true) && $refund_id !== ''): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="min-width:300px;"><?php wp_nonce_field('mrm_tax_resolve_refund_recovery','mrm_tax_refund_recovery_nonce'); ?><input type="hidden" name="action" value="mrm_tax_resolve_refund_recovery"><input type="hidden" name="refund_id" value="<?php echo esc_attr($refund_id); ?>"><input type="hidden" name="alert_type" value="<?php echo esc_attr($alert['alert_type']); ?>"><label><input type="checkbox" name="order_access_reviewed" value="1"> Order and access reviewed</label><br><label><input type="checkbox" name="payout_reviewed" value="1"> Payout records reviewed</label><br><label><input type="checkbox" name="accounting_reviewed" value="1"> Accounting records reviewed</label><br><label><input type="checkbox" name="customer_resolution_reviewed" value="1"> Customer refund resolution reviewed</label><br><textarea name="resolution_notes" required rows="4" placeholder="Describe every correction and follow-up completed."></textarea><br><button class="button button-small" type="submit"><?php echo esc_html($alert['alert_type']==='partial_refund_business_review_required' ? 'Resolve Partial Refund Review' : 'Resolve Failed Refund'); ?></button></form><?php elseif($alert['alert_type']==='subscription_direct_refund_review_required' && $refund_id !== '' && $invoice_id !== ''): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="min-width:300px;"><?php wp_nonce_field('mrm_tax_resolve_direct_invoice_refund','mrm_tax_direct_refund_nonce'); ?><input type="hidden" name="action" value="mrm_tax_resolve_direct_invoice_refund"><input type="hidden" name="refund_id" value="<?php echo esc_attr($refund_id); ?>"><input type="hidden" name="invoice_id" value="<?php echo esc_attr($invoice_id); ?>"><label>Refunded pretax sales</label><br><input type="number" name="refunded_sales" min="0" step="0.01" required placeholder="0.00"><br><label>Refunded tax</label><br><input type="number" name="refunded_tax" min="0" step="0.01" required placeholder="0.00"><br><textarea name="resolution_notes" required rows="4" placeholder="Record the authoritative source used for the pretax and tax split."></textarea><br><button class="button button-small" type="submit">Apply Exact Refund Split</button></form><?php elseif($payment_intent_id !== ''): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('mrm_tax_reconcile_payment_intent','mrm_tax_reconcile_nonce'); ?><input type="hidden" name="action" value="mrm_tax_reconcile_payment_intent"><input type="hidden" name="payment_intent_id" value="<?php echo esc_attr($payment_intent_id); ?>"><button class="button button-small" type="submit">Reconcile Payment</button></form><?php elseif($invoice_id !== ''): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('mrm_tax_reconcile_invoice','mrm_tax_reconcile_invoice_nonce'); ?><input type="hidden" name="action" value="mrm_tax_reconcile_invoice"><input type="hidden" name="invoice_id" value="<?php echo esc_attr($invoice_id); ?>"><button class="button button-small" type="submit">Reconcile Invoice</button></form><?php else: ?>Manual review required<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
      <?php if(!empty($email_attention_alerts)): ?>
      <div style="background:#fff;border:1px solid #dba617;padding:18px;margin:18px 0;">
        <h2>Tax Alert Email Attention</h2><p>These records do not block checkout. They identify administrative notifications that failed, remain uncertain, are still being processed, or accompany pending Stripe activation reporting.</p>
        <table class="widefat striped"><thead><tr><th>Alert</th><th>State</th><th>Message</th><th>Email status</th><th>Last attempt</th><th>Email error</th><th>Recovery action</th></tr></thead><tbody>
        <?php foreach($email_attention_alerts as $alert): $details=json_decode((string)($alert['details_json']??''),true);if(!is_array($details))$details=array();$alert_id=absint($alert['id']??0);$email_status=sanitize_key($alert['email_status']??'');$can_recover=in_array($email_status,array('not_sent','failed','uncertain'),true); ?>
          <tr><td><strong><?php echo esc_html($alert['alert_type']??'unknown'); ?></strong><br>#<?php echo esc_html($alert_id); ?></td><td><?php echo esc_html($alert['state_code']?:'—'); ?></td><td><?php echo esc_html($details['message']??'Administrative review required.'); ?></td><td><?php echo esc_html($email_status?:'not_sent'); ?></td><td><?php echo esc_html($alert['email_last_attempt_at']??'—'); ?></td><td><?php echo esc_html($alert['email_last_error']??'—'); ?></td><td>
          <?php if($can_recover): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="min-width:280px;"><?php wp_nonce_field('mrm_tax_alert_email_action_'.$alert_id,'mrm_tax_alert_email_nonce'); ?><input type="hidden" name="action" value="mrm_tax_alert_email_action"><input type="hidden" name="alert_id" value="<?php echo esc_attr($alert_id); ?>"><select name="email_resolution_action" required><option value="">Select action</option><option value="retry">Retry email intentionally</option><option value="mark_sent">Mark sent after verification</option><option value="waive">Waive further delivery</option></select><br><textarea name="email_resolution_note" rows="3" required placeholder="Record what you verified and why this action is appropriate." style="width:100%;margin-top:6px;"></textarea><br><button class="button button-small" type="submit" style="margin-top:6px;">Apply email action</button></form>
          <?php elseif($email_status==='sending'): ?>An email process currently holds this alert. Recovery controls will become available only after the send completes or the 15-minute claim expires.<?php elseif(in_array(sanitize_key($alert['alert_type']??''),array('stripe_activation_notification_pending','stripe_activation_postprocessing_failed'),true)): ?>The underlying Stripe activation task will resolve this warning after its associated activation alert is recovered.<?php else: ?>No email recovery action is required.<?php endif; ?></td></tr>
        <?php endforeach; ?></tbody></table>
      </div><?php endif; ?>
      <h2 style="margin-top:24px;">State Monitoring</h2><p>Stripe remains the source of truth for collection status. The monitoring table is read-only, and the focused workflow panels below allow administrator-only permit, filing, pending-period, and foreign-registration tracking.</p><table class="widefat striped" style="margin-top:12px;"><thead><tr><th>State</th><th>Stripe Registration</th><th>Registration ID</th><th>Collection</th><th>Tracked sales</th><th>Tracked transactions</th><th>Monitored threshold</th><th>Threshold progress</th><th>Monitor status</th><th>Suggested action</th></tr></thead><tbody><?php foreach($rows as $r): $state=$this->mrm_normalize_state_code($r['state_code'] ?? ''); $collection_active=!empty($r['collection_active']); $no_general_tax=sanitize_key($r['general_sales_tax_status'] ?? '')==='no_general_state_sales_tax'; $physical_signal=!empty($r['physical_nexus_flag']); $threshold_reached=sanitize_key($r['estimated_threshold_status'] ?? '')==='threshold_reached'; $progress=max(0,(float)($r['estimated_threshold_percent'] ?? 0)); $color='#646970'; $signal='Monitoring'; $action='No action currently identified.'; if($collection_active){ $color='#008a20'; $signal='Collecting'; $action='Stripe Tax collection is active.'; } elseif($no_general_tax){ $color='#2271b1'; $signal='No general state sales tax'; $action='Monitor for product-specific or local obligations.'; } elseif($physical_signal || $threshold_reached){ $color='#b32d2e'; $signal=$physical_signal?'Physical-presence signal':'Threshold reached'; $action='Review this state in Stripe Tax and activate a registration when required.'; } elseif($progress >= 75){ $color=$progress >= 90 ? '#d63638' : '#996800'; $signal='Approaching threshold'; $action='Review Stripe Tax → Needs attention.'; } $threshold_parts=array(); if(!empty($r['threshold_amount_cents'])) $threshold_parts[]='$'.number_format(((int)$r['threshold_amount_cents'])/100,2); if(!empty($r['threshold_transaction_count'])) $threshold_parts[]=absint($r['threshold_transaction_count']).' transactions'; ?><tr style="border-left:5px solid <?php echo esc_attr($color); ?>"><td><strong><?php echo esc_html($state); ?></strong><br><?php echo esc_html($r['state_name'] ?? ''); ?></td><td><?php echo esc_html($r['stripe_registration_status'] ?: 'none'); ?><br><small>Last sync: <?php echo esc_html($r['last_stripe_sync_at'] ?: 'Never'); ?></small></td><td><?php if(!empty($r['stripe_registration_id'])): ?><code><?php echo esc_html($r['stripe_registration_id']); ?></code><?php else: ?>—<?php endif; ?></td><td><?php echo $collection_active ? 'Active' : 'Not active'; ?></td><td>$<?php echo esc_html(number_format(((int)($r['estimated_sales_cents'] ?? 0))/100,2)); ?></td><td><?php echo esc_html(absint($r['estimated_transaction_count'] ?? 0)); ?></td><td><?php echo esc_html(!empty($threshold_parts) ? implode(' or ', $threshold_parts) : 'Not applicable'); ?></td><td><?php echo esc_html(number_format($progress,1)); ?>%</td><td><strong><?php echo esc_html($signal); ?></strong><?php if($physical_signal && !empty($r['physical_nexus_reason'])): ?><br><small><?php echo esc_html($r['physical_nexus_reason']); ?></small><?php endif; ?></td><td><?php echo esc_html($action); ?></td></tr><?php endforeach; ?></tbody></table>
      <h2 style="margin-top:24px;">State Registration Workflows</h2>
      <?php foreach($rows as $row): $state=$this->mrm_normalize_state_code($row['state_code']??''); $show=!empty($row['physical_nexus_flag'])||!empty($row['physical_activity_started_at'])||sanitize_key($row['authority_registration_status']??'')!=='not_started'||sanitize_key($row['foreign_registration_status']??'')!=='not_started'||!empty($row['collection_active']); if(!$show)continue; $pending_summary=$this->mrm_tax_summarize_pending_period_sales($state,$row); ?>
      <div style="background:#fff;border:1px solid #dcdcde;padding:18px;margin:18px 0;"><h3><?php echo esc_html($state.' — '.($row['state_name']??'')); ?></h3><p><strong>Physical-nexus signal:</strong> <?php echo !empty($row['physical_nexus_flag'])?'Recorded':'Not recorded'; ?> | <strong>First signal:</strong> <?php echo esc_html($row['first_flagged_at']??'—'); ?></p><?php $physical_reason=trim((string)($row['physical_nexus_reason']??''));if($physical_reason!==''): ?><p><strong>Physical-nexus reason:</strong><br><?php echo nl2br(esc_html($physical_reason)); ?></p><?php endif; ?>
      <p><strong>Stripe registration:</strong> <?php echo esc_html($row['stripe_registration_status']??'none'); ?> | <strong>ID:</strong> <code><?php echo esc_html($row['stripe_registration_id']??'—'); ?></code> | <strong>Live:</strong> <?php echo !empty($row['stripe_livemode'])?'Yes':'No'; ?> | <strong>Collection:</strong> <?php echo !empty($row['collection_active'])?'Active':'Inactive'; ?> | <strong>Collection started:</strong> <?php echo esc_html($row['stripe_collection_started_at']??'—'); ?> | <strong>Last sync:</strong> <?php echo esc_html($row['last_stripe_sync_at']??'Never'); ?></p>
      <?php if(is_wp_error($pending_summary)): ?><p class="notice notice-error"><?php echo esc_html($pending_summary->get_error_message()); ?></p><?php else: ?><h4>Pending-period reporting</h4><p>Period: <?php echo esc_html(($pending_summary['period_start']??'—').' — '.($pending_summary['period_end']??'—')); ?> | Digital transactions: <?php echo esc_html($pending_summary['digital_transaction_count']??0); ?> (PaymentIntents: <?php echo esc_html($pending_summary['digital_payment_intent_count']??0); ?>; invoices: <?php echo esc_html($pending_summary['digital_invoice_count']??0); ?>) | Gross: $<?php echo esc_html(number_format(($pending_summary['digital_gross_sales_cents']??0)/100,2)); ?> | Refunds: $<?php echo esc_html(number_format(($pending_summary['digital_refunded_sales_cents']??0)/100,2)); ?> | Net: $<?php echo esc_html(number_format(($pending_summary['digital_net_sales_cents']??0)/100,2)); ?> | Net tax collected: $<?php echo esc_html(number_format(($pending_summary['net_tax_collected_cents']??0)/100,2)); ?></p><p><strong>Individual digital downloads:</strong> $<?php echo esc_html(number_format(($pending_summary['digital_document_download']['net_sales_cents']??0)/100,2)); ?> net from <?php echo esc_html($pending_summary['digital_document_download']['transaction_count']??0); ?> transactions.<br><strong>Digital subscriptions:</strong> $<?php echo esc_html(number_format(($pending_summary['digital_document_subscription']['net_sales_cents']??0)/100,2)); ?> net from <?php echo esc_html($pending_summary['digital_document_subscription']['transaction_count']??0); ?> invoices.</p><p>Lessons: $<?php echo esc_html(number_format(($pending_summary['lessons']['net_sales_cents']??0)/100,2)); ?> (<?php echo esc_html($pending_summary['lessons']['transaction_count']??0); ?>) | Masterclasses: $<?php echo esc_html(number_format(($pending_summary['masterclasses']['net_sales_cents']??0)/100,2)); ?> (<?php echo esc_html($pending_summary['masterclasses']['transaction_count']??0); ?>) | Taxability reasons: <?php echo esc_html(implode(', ',$pending_summary['taxability_reasons']??array())?:'None'); ?></p><?php if($state==='TX'): ?><p><strong>Estimated internal reserve — reporting only:</strong> $<?php echo esc_html(number_format(($pending_summary['estimated_reserve_cents']??0)/100,2)); ?> at <?php echo esc_html($pending_summary['reserve_rate_bps']??0); ?> basis points.</p><p>This reserve is not tax collected, is not added to customer prices, is not deducted from payouts, and is not a finalized tax liability.</p><?php endif; ?><?php endif; ?>
      <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('mrm_tax_state_save_'.$state,'mrm_tax_state_nonce'); ?><input type="hidden" name="action" value="mrm_tax_state_save"><input type="hidden" name="state_code" value="<?php echo esc_attr($state); ?>">
      <?php $selects=array('authority_registration_status'=>$this->mrm_tax_authority_registration_statuses(),'foreign_registration_status'=>$this->mrm_tax_foreign_registration_statuses(),'registered_agent_status'=>$this->mrm_tax_registered_agent_statuses(),'filing_status'=>$this->mrm_tax_filing_statuses()); foreach($selects as $field=>$options): ?><label style="display:inline-block;margin:6px 12px 6px 0;"><?php echo esc_html(ucwords(str_replace('_',' ',$field))); ?><br><select name="<?php echo esc_attr($field); ?>"><?php foreach($options as $option): ?><option value="<?php echo esc_attr($option); ?>" <?php selected($row[$field]??'',$option); ?>><?php echo esc_html($option); ?></option><?php endforeach; ?></select></label><?php endforeach; ?><br>
      <?php $fields=array('authority_registration_submitted_at','authority_registration_application_reference','authority_registration_number','authority_registration_effective_date','written_determination_reviewed_at','written_determination_reference','physical_activity_started_at','physical_activity_correction_reason','foreign_registration_grace_days','foreign_registration_internal_due_date','foreign_registration_outside_due_date','registered_agent_reference','foreign_registration_submitted_at','foreign_registration_accepted_at','foreign_registration_reference','pending_tax_reconciled_at','filing_frequency','next_return_due_date','last_return_filed_at','last_return_confirmation','admin_notes'); foreach($fields as $field): ?><label style="display:inline-block;vertical-align:top;margin:6px 12px 6px 0;"><?php echo esc_html(ucwords(str_replace('_',' ',$field))); ?><br><input name="<?php echo esc_attr($field); ?>" value="<?php echo esc_attr($row[$field]??''); ?>"></label><?php endforeach; ?><?php if($state==='TX'): ?><label style="display:inline-block;vertical-align:top;margin:6px 12px 6px 0;">Pending Tax Reserve Rate BPS<br><input type="number" min="0" max="10000" step="1" name="pending_tax_reserve_rate_bps" value="<?php echo esc_attr($row['pending_tax_reserve_rate_bps']??''); ?>"></label><?php endif; ?><p><button class="button button-primary" type="submit">Save workflow</button></p></form></div><?php endforeach; ?>
      </div><?php
  }

  public function render_profile_card_creation_page() {
    if (!current_user_can('manage_options')) wp_die('You do not have permission to access this page.');
    global $wpdb;
    $table = $this->table_profile_card_requests();
    $this->maybe_install_or_upgrade_db();
    $requests = $wpdb->get_results(
      "SELECT * FROM {$table}
       WHERE status IN ('sent', 'pending_review', 'changes_requested', 'tax_registration_required')
       ORDER BY updated_at DESC, id DESC
       LIMIT 100",
      ARRAY_A
    );

    $presenters_table = $wpdb->prefix . 'mrm_masterclass_presenters';
    $presenters = array();

    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $presenters_table)) === $presenters_table) {
      $presenter_approval_where = $this->mrm_profile_card_presenter_approval_where_sql('');

      $presenters = $wpdb->get_results(
        "SELECT id, name, email
         FROM {$presenters_table}
         WHERE {$presenter_approval_where}
         ORDER BY name ASC, email ASC",
        ARRAY_A
      );
    }

    $settings = $this->get_settings();

    $background_check_standard_docusign_url = esc_url((string)(
      $settings['background_check_standard_docusign_url']
      ?? $settings['background_check_docusign_url']
      ?? 'https://www.docusign.com/'
    ));

    $background_check_california_docusign_url = esc_url((string)(
      $settings['background_check_california_docusign_url']
      ?? 'https://www.docusign.com/'
    ));

    $instructor_agreement_w9_docusign_url = esc_url((string)(
      $settings['instructor_agreement_w9_docusign_url']
      ?? 'https://www.docusign.com/'
    ));

    $presenter_agreement_w9_docusign_url = esc_url((string)(
      $settings['presenter_agreement_w9_docusign_url']
      ?? 'https://www.docusign.com/'
    ));
    ?>
    <div class="wrap"><h1>Profile Card Creation</h1>
      <p class="description">Send private onboarding links to instructors and presenters. Submitted requests appear below for review before anything is created in Scheduler or Masterclass settings.</p>

      <?php
      $duplicate_email = isset($_GET['duplicate_email']) ? sanitize_email(wp_unslash($_GET['duplicate_email'])) : '';
      $duplicate_type  = isset($_GET['duplicate_type']) ? sanitize_key(wp_unslash($_GET['duplicate_type'])) : '';
      $duplicate_id    = isset($_GET['duplicate_id']) ? absint($_GET['duplicate_id']) : 0;
      $duplicate_note  = isset($_GET['duplicate_note']) ? sanitize_textarea_field(wp_unslash($_GET['duplicate_note'])) : '';
      $duplicate_days  = isset($_GET['duplicate_days']) ? absint($_GET['duplicate_days']) : 14;

      if ($duplicate_email && $duplicate_id && in_array($duplicate_type, array('instructor_profile', 'presenter_profile'), true)) :
        $duplicate_label = $duplicate_type === 'presenter_profile' ? 'presenter' : 'instructor';
      ?>
        <div class="notice notice-warning" style="padding:12px 14px;">
          <p><strong>This email is already in use.</strong> A <?php echo esc_html($duplicate_label); ?> profile already exists for <code><?php echo esc_html($duplicate_email); ?></code>.</p>
          <p>You can request an update to the existing profile card, or go back and choose a different email. Existing Stripe payout, hire date, operational calendar ID, and payout settings will be preserved during the update approval. Instructor update requests still require a Google Calendar link so the instructor can review and update recurring lesson availability.</p>
