  public function handle_profile_card_manual_update_instructor() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission.');
    }

    check_admin_referer('mrm_profile_card_manual_update_instructor', 'mrm_profile_card_manual_update_instructor_nonce');

    global $wpdb;

    $this->maybe_install_or_upgrade_db();

    $instructor_id = absint($_POST['instructor_id'] ?? 0);

    if ($instructor_id <= 0) {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode('Missing instructor ID.')));
      exit;
    }

    $table = $wpdb->prefix . 'mrm_instructors';

    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode('The instructors table could not be found.')));
      exit;
    }

    $first_name = sanitize_text_field(wp_unslash($_POST['first_name'] ?? ''));
    $last_name = sanitize_text_field(wp_unslash($_POST['last_name'] ?? ''));
    $name = trim($first_name . ' ' . $last_name);

    if ($name === '') {
      $name = sanitize_text_field(wp_unslash($_POST['name'] ?? ''));
    }

    $email = sanitize_email(wp_unslash($_POST['email'] ?? ''));

    if ($name === '' || !is_email($email)) {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode('Name and valid email are required.')));
      exit;
    }

    $payload = array(
      'first_name' => $first_name,
      'last_name' => $last_name,
      'name' => $name,
      'email' => $email,
      'city' => sanitize_text_field(wp_unslash($_POST['city'] ?? '')),
      'state' => strtoupper(substr(sanitize_text_field(wp_unslash($_POST['state'] ?? '')), 0, 2)),
      'address' => sanitize_text_field(wp_unslash($_POST['address'] ?? '')),
      'zip_code' => sanitize_text_field(wp_unslash($_POST['zip_code'] ?? '')),
      'offers_online' => !empty($_POST['offers_online']) ? 1 : 0,
      'offers_in_person' => !empty($_POST['offers_in_person']) ? 1 : 0,
      'instruments' => array_values(array_filter(array_map('sanitize_text_field', (array)($_POST['instruments'] ?? array())))),
      'instructor_title' => sanitize_text_field(wp_unslash($_POST['instructor_title'] ?? '')),
      'short_description' => sanitize_text_field(wp_unslash($_POST['short_description'] ?? '')),
      'long_description' => wp_kses_post(wp_unslash($_POST['long_description'] ?? '')),
      'profile_image_url' => esc_url_raw(wp_unslash($_POST['profile_image_url'] ?? '')),
      'website_url' => esc_url_raw(wp_unslash($_POST['website_url'] ?? '')),
      'instagram_url' => esc_url_raw(wp_unslash($_POST['instagram_url'] ?? '')),
      'facebook_url' => esc_url_raw(wp_unslash($_POST['facebook_url'] ?? '')),
      'youtube_url' => esc_url_raw(wp_unslash($_POST['youtube_url'] ?? '')),
      'linkedin_url' => esc_url_raw(wp_unslash($_POST['linkedin_url'] ?? '')),
    );

    $existing_instructor = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d LIMIT 1", $instructor_id), ARRAY_A);
    $existing_metadata = $this->mrm_profile_card_decode_metadata_from_row($existing_instructor);

    $data = array(
      'name' => $payload['name'],
      'email' => $payload['email'],
      'city' => $payload['city'],
      'state' => $payload['state'],
      'address' => $payload['address'],
      'zip_code' => $payload['zip_code'],
      'offers_in_person' => !empty($payload['offers_in_person']) ? 1 : 0,
      'offers_online' => !empty($payload['offers_online']) ? 1 : 0,
      'profile_image_url' => $payload['profile_image_url'],
      'short_description' => $payload['short_description'],
      'long_description' => $payload['long_description'],
      'instruments' => wp_json_encode($payload['instruments']),
    );

    /*
     * Save profile-card metadata and a complete current snapshot.
     * This preserves the latest manually edited profile-card values without touching
     * operational calendar, Stripe, timezone, or hire-date fields.
     */
    $this->mrm_profile_card_add_profile_metadata_to_record($table, $data, $payload, 'instructor_profile');

    if (!empty($existing_metadata['approved_profile_card_payload']) && is_array($existing_metadata['approved_profile_card_payload'])) {
      $manual_metadata = $this->mrm_profile_card_decode_metadata_from_row($data);
      $manual_metadata['approved_profile_card_payload'] = $existing_metadata['approved_profile_card_payload'];
      if (!empty($existing_metadata['approved_profile_card_uploaded_files']) && is_array($existing_metadata['approved_profile_card_uploaded_files'])) {
        $manual_metadata['approved_profile_card_uploaded_files'] = $existing_metadata['approved_profile_card_uploaded_files'];
      }
      $manual_metadata['approved_profile_card_saved_at'] = $existing_metadata['approved_profile_card_saved_at'] ?? ($manual_metadata['approved_profile_card_saved_at'] ?? '');

      if (array_key_exists('profile_metadata_json', $data)) {
        $data['profile_metadata_json'] = wp_json_encode($manual_metadata);
      } elseif (array_key_exists('metadata_json', $data)) {
        $data['metadata_json'] = wp_json_encode($manual_metadata);
      }
    }

    $updated = $wpdb->update($table, $data, array('id' => $instructor_id));

    if ($updated === false) {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode('Manual instructor update failed: ' . $wpdb->last_error)));
      exit;
    }

    wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&manual_updated=1'));
    exit;
  }

  public function handle_profile_card_request_existing_instructor_update() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission.');
    }

    check_admin_referer('mrm_profile_card_request_existing_instructor_update', 'mrm_profile_card_existing_instructor_nonce');

    global $wpdb;
    $this->maybe_install_or_upgrade_db();
    $instructor_id = absint($_POST['instructor_id'] ?? 0);
    $calendar_url = esc_url_raw(wp_unslash($_POST['instructor_calendar_url'] ?? ''));
    $note = sanitize_textarea_field(wp_unslash($_POST['change_request_note'] ?? ''));
    $days = max(1, min(60, absint($_POST['token_days'] ?? 14)));
    $field_comments = $this->mrm_profile_card_sanitize_field_comments_from_post($_POST['field_comments'] ?? array());

    if ($instructor_id <= 0 || $calendar_url === '') {
      $message = $instructor_id <= 0 ? 'Missing instructor ID.' : 'Please add the instructor Google Calendar link.';
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode($message)));
      exit;
    }

    $instructors_table = $wpdb->prefix . 'mrm_instructors';
    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $instructors_table)) !== $instructors_table) {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode('The instructors table could not be found.')));
      exit;
    }

    $instructor = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$instructors_table} WHERE id = %d LIMIT 1", $instructor_id), ARRAY_A);
    if (!is_array($instructor) || empty($instructor['id']) || empty($instructor['email']) || !is_email($instructor['email'])) {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode('The selected instructor is missing a valid email address.')));
      exit;
    }

    $recipient_email = sanitize_email((string)$instructor['email']);
    $recipient_name = sanitize_text_field((string)($instructor['name'] ?? $recipient_email));
    $token = $this->mrm_profile_card_new_token();
    $now = current_time('mysql');
    $admin_payload = array('admin_note' => $note, 'instructor_calendar_url' => $calendar_url, 'event_title' => '', 'masterclass_piece_sku' => '', 'masterclass_piece_title' => '', 'masterclass_piece_url' => '', 'event_start_time' => '', 'event_end_time' => '', 'event_timezone' => 'America/Phoenix', 'selected_presenter_id' => 0, 'presenter_payout_per_student_cents' => 0, 'event_price_cents' => 0, 'is_profile_update' => 1, 'existing_target_id' => $instructor_id);
    $submission_payload = $this->mrm_profile_card_existing_profile_submission_payload('instructor_profile', $instructor_id);
    $review_notes = array('change_request_note' => $note, 'field_comments' => $field_comments, 'changes_requested_at' => $now, 'changes_requested_by' => get_current_user_id(), 'source' => 'instructor_profiles_submenu');
    $requests_table = $this->table_profile_card_requests();

    $inserted = $wpdb->insert($requests_table, array('request_type' => 'instructor_profile', 'status' => 'changes_requested', 'recipient_name' => $recipient_name, 'recipient_email' => $recipient_email, 'token_hash' => $this->mrm_profile_card_hash_token($token), 'token_expires_at' => gmdate('Y-m-d H:i:s', time() + ($days * DAY_IN_SECONDS)), 'admin_payload' => $this->mrm_profile_card_encode_json($admin_payload), 'submission_payload' => $this->mrm_profile_card_encode_json($submission_payload), 'review_notes' => $this->mrm_profile_card_encode_json($review_notes), 'uploaded_files' => $this->mrm_profile_card_encode_json(array()), 'sent_at' => $now, 'created_at' => $now, 'updated_at' => $now));

    if (!$inserted) {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode('Could not create instructor update request: ' . $wpdb->last_error)));
      exit;
    }

    $form_url = add_query_arg(array('action' => 'mrm_profile_card_form', 'token' => $token), admin_url('admin-post.php'));
    $email_sent = $this->mrm_profile_card_send_changes_requested_email(
      array(
        'request_type' => 'instructor_profile',
        'recipient_email' => $recipient_email,
      ),
      $form_url,
      $note,
      $field_comments
    );

    if (!$email_sent) {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&error=' . rawurlencode('The update request was created, but the email could not be sent. Please verify email delivery before relying on this request.')));
      exit;
    }

    wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-instructor-profiles&update_sent=1'));
    exit;
  }

  public function handle_profile_card_create_invite() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission.');
    }

    check_admin_referer('mrm_profile_card_create_invite', 'mrm_profile_card_nonce');

    global $wpdb;

    $this->maybe_install_or_upgrade_db();

    $table = $this->table_profile_card_requests();

    $request_type = sanitize_key($_POST['request_type'] ?? 'instructor_profile');
    if (!in_array($request_type, array('instructor_profile', 'presenter_profile', 'presenter_event'), true)) {
      $request_type = 'instructor_profile';
    }

    $recipient_email = '';
    $recipient_name = '';
    $recipient_first_name = '';
    $recipient_last_name = '';
    $selected_presenter_id = 0;

    $force_profile_update = !empty($_POST['force_profile_update']);
    $existing_target_id   = absint($_POST['existing_target_id'] ?? 0);

    if ($request_type === 'presenter_event') {
      $selected_presenter_id = absint($_POST['presenter_id'] ?? 0);

      if ($selected_presenter_id <= 0) {
        wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-profile-card-creation&error=missing_presenter'));
        exit;
      }

      $presenters_table = $wpdb->prefix . 'mrm_masterclass_presenters';

      if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $presenters_table)) !== $presenters_table) {
        wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-profile-card-creation&error=invalid_presenter'));
        exit;
      }

      $presenter_approval_where = $this->mrm_profile_card_presenter_approval_where_sql('');

      $presenter = $wpdb->get_row(
        $wpdb->prepare(
          "SELECT id, name, email
           FROM {$presenters_table}
           WHERE id = %d
             AND {$presenter_approval_where}
           LIMIT 1",
          $selected_presenter_id
        ),
        ARRAY_A
      );

      if (!$presenter || empty($presenter['email']) || !is_email($presenter['email'])) {
        wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-profile-card-creation&error=unapproved_presenter'));
        exit;
      }

      $recipient_email = sanitize_email($presenter['email']);
      $recipient_name = sanitize_text_field($presenter['name'] ?? '');
    } else {
      $recipient_first_name = sanitize_text_field(wp_unslash($_POST['recipient_first_name'] ?? ''));
      $recipient_last_name  = sanitize_text_field(wp_unslash($_POST['recipient_last_name'] ?? ''));
      $recipient_email      = sanitize_email(wp_unslash($_POST['recipient_email'] ?? ''));

      if (
        !is_email($recipient_email) ||
        (
          !$force_profile_update &&
          (
            trim($recipient_first_name) === '' ||
            trim($recipient_last_name) === ''
          )
        )
      ) {
        wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-profile-card-creation&error=invalid_recipient'));
        exit;
      }

      $recipient_name = trim($recipient_first_name . ' ' . $recipient_last_name);

      if ($recipient_name === '') {
        $recipient_name = $recipient_email;
      }
    }

    $token = $this->mrm_profile_card_new_token();
    $days = max(1, min(60, absint($_POST['token_days'] ?? 14)));
    $admin_note = sanitize_textarea_field(wp_unslash($_POST['admin_note'] ?? ''));

    if (!$force_profile_update && $request_type === 'instructor_profile') {
      $existing = $this->mrm_profile_card_existing_instructor_by_email($recipient_email);

      if ($existing && !empty($existing['id'])) {
        wp_safe_redirect(add_query_arg(array('page' => 'mrm-pay-hub-profile-card-creation', 'duplicate_email' => rawurlencode($recipient_email), 'duplicate_type' => 'instructor_profile', 'duplicate_id' => absint($existing['id']), 'duplicate_days' => $days, 'duplicate_note' => rawurlencode($admin_note)), admin_url('admin.php')));
        exit;
      }
    }

    if (!$force_profile_update && $request_type === 'presenter_profile') {
      $existing = $this->mrm_profile_card_existing_presenter_by_email($recipient_email);

      if ($existing && !empty($existing['id'])) {
        wp_safe_redirect(add_query_arg(array('page' => 'mrm-pay-hub-profile-card-creation', 'duplicate_email' => rawurlencode($recipient_email), 'duplicate_type' => 'presenter_profile', 'duplicate_id' => absint($existing['id']), 'duplicate_days' => $days, 'duplicate_note' => rawurlencode($admin_note)), admin_url('admin.php')));
        exit;
      }
    }

    $instructor_calendar_url = esc_url_raw(wp_unslash($_POST['instructor_calendar_url'] ?? ''));

    if ($request_type === 'instructor_profile' && $instructor_calendar_url === '') {
      wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-profile-card-creation&error=missing_instructor_calendar'));
      exit;
    }

    $admin_payload = array(
      'admin_note' => $admin_note,
      'instructor_calendar_url' => $instructor_calendar_url,
      'event_title' => sanitize_text_field(wp_unslash($_POST['event_title'] ?? '')),
      'masterclass_piece_sku' => '',
      'masterclass_piece_title' => '',
      'masterclass_piece_url' => '',
      'event_start_time' => sanitize_text_field(wp_unslash($_POST['event_start_time'] ?? '')),
      'event_end_time' => sanitize_text_field(wp_unslash($_POST['event_end_time'] ?? '')),
      'event_timezone' => sanitize_text_field(wp_unslash($_POST['event_timezone'] ?? 'America/Phoenix')),
      'selected_presenter_id' => $selected_presenter_id,
      'presenter_payout_per_student_cents' => 0,
      'event_price_cents' => 0,
      'is_profile_update' => $force_profile_update ? 1 : 0,
      'existing_target_id' => $existing_target_id,
    );

    if ($request_type === 'presenter_event') {
      $admin_payload['presenter_payout_per_student_cents'] = $this->mrm_profile_card_money_to_cents($_POST['presenter_payout'] ?? '0');
      $admin_payload['event_price_cents'] = $this->mrm_profile_card_money_to_cents($_POST['event_price'] ?? '0');

      $selected_piece = $this->mrm_profile_card_piece_from_sku(wp_unslash($_POST['masterclass_piece_sku'] ?? ''));

      $admin_payload['masterclass_piece_sku'] = sanitize_text_field((string)($selected_piece['sku'] ?? ''));
      $admin_payload['masterclass_piece_title'] = sanitize_text_field((string)($selected_piece['title'] ?? ''));
      $admin_payload['masterclass_piece_url'] = esc_url_raw((string)($selected_piece['url'] ?? ''));

      if ($admin_payload['masterclass_piece_sku'] === '') {
        wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-profile-card-creation&error=missing_piece'));
        exit;
      }

      if (
        trim((string)$admin_payload['event_start_time']) === '' ||
        trim((string)$admin_payload['event_end_time']) === '' ||
        (int)$admin_payload['event_price_cents'] <= 0 ||
        (int)$admin_payload['presenter_payout_per_student_cents'] <= 0
      ) {
        wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-profile-card-creation&error=missing_event_details'));
        exit;
      }
    }

    $initial_submission_payload = array();

    if (
      $force_profile_update
      && $existing_target_id > 0
      && in_array($request_type, array('instructor_profile', 'presenter_profile'), true)
    ) {
      $initial_submission_payload = $this->mrm_profile_card_existing_profile_submission_payload(
        $request_type,
        $existing_target_id
      );
    } elseif (in_array($request_type, array('instructor_profile', 'presenter_profile'), true)) {
      $initial_submission_payload = array(
        'first_name' => $recipient_first_name,
        'last_name'  => $recipient_last_name,
        'name'       => $recipient_name,
        'email'      => $recipient_email,
      );
    }

    $now = current_time('mysql');

    $inserted = $wpdb->insert(
      $table,
      array(
        'request_type' => $request_type,
        'status' => 'sent',
        'recipient_name' => $recipient_name,
        'recipient_email' => $recipient_email,
        'token_hash' => $this->mrm_profile_card_hash_token($token),
        'token_expires_at' => gmdate('Y-m-d H:i:s', time() + ($days * DAY_IN_SECONDS)),
        'admin_payload' => $this->mrm_profile_card_encode_json($admin_payload),
        'submission_payload' => $this->mrm_profile_card_encode_json($initial_submission_payload),
        'review_notes' => $this->mrm_profile_card_encode_json(array()),
        'uploaded_files' => $this->mrm_profile_card_encode_json(array()),
        'sent_at' => $now,
        'created_at' => $now,
        'updated_at' => $now,
      )
    );

    if (!$inserted) {
      wp_safe_redirect(
        admin_url(
          'admin.php?page=mrm-pay-hub-profile-card-creation&error=' . rawurlencode('Request could not be saved before sending the email: ' . $wpdb->last_error)
        )
      );
      exit;
    }

    $url = add_query_arg(array('action' => 'mrm_profile_card_form', 'token' => $token), admin_url('admin-post.php'));

    $label = $this->mrm_profile_card_request_type_label($request_type);

    if ($force_profile_update) {
      $label .= ' Update';
    }

    $invite_parts = $this->mrm_profile_card_invite_email_parts(
      $request_type,
      $label,
      (string)$days . ' days',
      $admin_note,
      array(
        'sku' => $admin_payload['masterclass_piece_sku'] ?? '',
        'title' => $admin_payload['masterclass_piece_title'] ?? '',
        'url' => $admin_payload['masterclass_piece_url'] ?? '',
      )
    );

    $subject = (string)$invite_parts['subject'];

    if ($force_profile_update) {
      $subject .= ' Update';
    }

    $invite_buttons = is_array($invite_parts['buttons'] ?? null) ? $invite_parts['buttons'] : array();

    if (!empty($invite_buttons[0]) && is_array($invite_buttons[0])) {
      $invite_buttons[0]['url'] = $url;
    }

    $body = $this->mrm_email_wrap_html(
      (string)$invite_parts['title'],
      (string)$invite_parts['intro'],
      (string)$invite_parts['details'],
      $invite_buttons,
      ''
    );

    wp_mail($recipient_email, $subject, $body, array('Content-Type: text/html; charset=UTF-8'));

    wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-profile-card-creation&sent=1'));
    exit;
  }


  private function mrm_profile_card_uploads_from_payload($payload) {
    $payload = is_array($payload) ? $payload : array();

    $file_path = (string)($payload['fingerprint_card_file'] ?? '');
    $display_name = sanitize_file_name((string)(
      $payload['fingerprint_card_display_name']
      ?? $payload['fingerprint_card_name']
      ?? 'fingerprint-clearance'
    ));
    $stored_name = sanitize_file_name((string)(
      $payload['fingerprint_card_stored_name']
      ?? ($file_path !== '' ? basename($file_path) : '')
    ));
    $uploaded_at = sanitize_text_field((string)($payload['fingerprint_card_uploaded_at'] ?? ''));

    if ($file_path === '' && $stored_name !== '') {
      $candidate = trailingslashit($this->mrm_profile_card_private_upload_dir()) . $stored_name;

      if (file_exists($candidate)) {
        $file_path = $candidate;
      }
    }

    if ($file_path === '') {
      return array();
    }

    if ($display_name === '') {
      $display_name = $stored_name !== '' ? $stored_name : basename($file_path);
    }

    return array(
      array(
        'name' => $display_name,
        'display_name' => $display_name,
        'stored_name' => $stored_name !== '' ? $stored_name : basename($file_path),
        'file' => $file_path,
        'uploaded_at' => $uploaded_at,
        'source' => 'submission_payload',
      ),
    );
  }

  private function mrm_profile_card_merge_uploads_with_payload($uploads, $payload) {
    $uploads = is_array($uploads) ? $uploads : array();
    $payload_uploads = $this->mrm_profile_card_uploads_from_payload($payload);

    $merged = array();
    $seen = array();

    foreach (array_merge($uploads, $payload_uploads) as $file) {
      if (!is_array($file)) {
        continue;
      }

      $file_path = (string)($file['file'] ?? '');
      $file_url = (string)($file['url'] ?? '');
      $file_name = (string)($file['name'] ?? '');

      $key = $file_path !== '' ? $file_path : ($file_url !== '' ? $file_url : $file_name);

      if ($key === '' || isset($seen[$key])) {
        continue;
      }

      $seen[$key] = true;
      $merged[] = $file;
    }

    return $merged;
  }

  private function mrm_profile_card_normalize_private_upload_file($file) {
    $file = is_array($file) ? $file : array();

    $file_path = (string)($file['file'] ?? '');
    $file_url = esc_url_raw((string)($file['url'] ?? ''));

    $display_name = sanitize_file_name((string)(
      $file['display_name']
      ?? $file['name']
      ?? 'Uploaded file'
    ));

    $stored_name = sanitize_file_name((string)(
      $file['stored_name']
      ?? ($file_path !== '' ? basename($file_path) : '')
    ));

    if ($file_path === '' && $stored_name !== '') {
      $candidate = trailingslashit($this->mrm_profile_card_private_upload_dir()) . $stored_name;

      if (file_exists($candidate)) {
        $file_path = $candidate;
      }
    }

    if ($display_name === '') {
      $display_name = $stored_name !== '' ? $stored_name : 'Uploaded file';
    }

    return array(
      'name' => $display_name,
      'display_name' => $display_name,
      'stored_name' => $stored_name,
      'file' => $file_path,
      'url' => $file_url,
      'uploaded_at' => sanitize_text_field((string)($file['uploaded_at'] ?? '')),
      'source' => sanitize_text_field((string)($file['source'] ?? '')),
    );
  }

  private function mrm_profile_card_private_file_preview_html($file) {
    $file = $this->mrm_profile_card_normalize_private_upload_file($file);

    $file_name = sanitize_file_name((string)($file['name'] ?? 'Uploaded file'));
    $stored_name = sanitize_file_name((string)($file['stored_name'] ?? ''));
    $file_path = (string)($file['file'] ?? '');
    $file_url  = esc_url_raw((string)($file['url'] ?? ''));

    if ($file_name === '') {
      $file_name = 'Uploaded file';
    }

    $download_url = '';
    $mime = '';
    $file_exists = false;

    if ($file_path !== '') {
      $real_file = realpath($file_path);
      $private_root = realpath($this->mrm_profile_card_private_upload_dir());

      if ($real_file && $private_root && strpos($real_file, $private_root) === 0 && file_exists($real_file)) {
        $file_exists = true;

        $download_url = wp_nonce_url(
          admin_url(
            'admin-post.php?action=mrm_profile_card_download_private_file'
            . '&stored_name=' . rawurlencode(basename($real_file))
            . '&name=' . rawurlencode($file_name)
          ),
          'mrm_profile_card_download_private_file'
        );

        $mime = function_exists('mime_content_type') ? (string)mime_content_type($real_file) : '';

        if ($mime === '' || $mime === 'application/octet-stream') {
          $ext = strtolower(pathinfo($real_file, PATHINFO_EXTENSION));

          $mime_by_ext = array(
            'jpg' => 'image/jpeg',
            'jpeg' => 'image/jpeg',
            'png' => 'image/png',
            'webp' => 'image/webp',
            'pdf' => 'application/pdf',
          );

          $mime = $mime_by_ext[$ext] ?? $mime;
        }

        if ($stored_name === '') {
          $stored_name = basename($real_file);
        }
      }
    } elseif ($file_url !== '') {
      $download_url = $file_url;
    }

    $html = '<div class="mrm-profile-card-upload-preview" style="margin:12px 0 18px;padding:14px;border:1px solid #dcdcde;background:#fff;border-radius:12px;">';

    $html .= '<p style="margin:0 0 10px 0;">';
    $html .= '<strong>' . esc_html($file_name) . '</strong>';

    if ($stored_name !== '' && $stored_name !== $file_name) {
      $html .= '<br><span class="description">Stored private file: <code>' . esc_html($stored_name) . '</code></span>';
    }

    if (!$file_exists && $file_path !== '') {
      $html .= '<br><span style="color:#b32d2e;font-weight:700;">The saved private file path could not be found on disk.</span>';
      $html .= '<br><span class="description">Stored file expected: <code>' . esc_html($stored_name) . '</code></span>';
    }

    if ($download_url !== '') {
      $html .= '<br><a class="button button-small" href="' . esc_url($download_url) . '" target="_blank" rel="noopener noreferrer">Open Full File</a>';
    }

    $html .= '</p>';

    if ($download_url === '') {
      $html .= '<p class="description">Uploaded file reference is missing or incomplete.</p>';
    } elseif (strpos($mime, 'image/') === 0) {
      $html .= '<div style="margin-top:10px;">';
      $html .= '<img src="' . esc_url($download_url) . '" alt="' . esc_attr($file_name) . '" style="display:block;max-width:100%;width:auto;max-height:720px;height:auto;border:1px solid #dcdcde;border-radius:10px;background:#f6f7f7;">';
      $html .= '</div>';
    } elseif ($mime === 'application/pdf') {
      $html .= '<div style="margin-top:10px;">';
      $html .= '<iframe src="' . esc_url($download_url) . '" title="' . esc_attr($file_name) . '" style="width:100%;height:720px;border:1px solid #dcdcde;border-radius:10px;background:#f6f7f7;"></iframe>';
      $html .= '</div>';
    } else {
      $html .= '<p class="description" style="margin:10px 0 0 0;">Preview is not available for this file type. Use Open Full File to view or download it.</p>';
    }

    $html .= '</div>';

    return $html;
  }

  private function mrm_profile_card_render_uploaded_file_previews($uploads, $payload = array()) {
    $uploads = $this->mrm_profile_card_merge_uploads_with_payload($uploads, $payload);

    if (empty($uploads)) {
      return;
    }

    echo '<h3 style="margin-top:22px;">Uploaded Files</h3>';
    echo '<p class="description">Fingerprint clearance files are stored privately and previewed here through an admin-only secure file route.</p>';

    foreach ($uploads as $file) {
      echo $this->mrm_profile_card_private_file_preview_html($file);
    }
  }

  public function handle_profile_card_download_private_file() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission to access this file.');
    }

    check_admin_referer('mrm_profile_card_download_private_file');

    $file = isset($_GET['file']) ? sanitize_text_field(wp_unslash($_GET['file'])) : '';
    $stored_name = isset($_GET['stored_name']) ? sanitize_file_name(wp_unslash($_GET['stored_name'])) : '';
    $name = isset($_GET['name']) ? sanitize_file_name(wp_unslash($_GET['name'])) : 'fingerprint-proof';

    if ($stored_name !== '') {
      $file = trailingslashit($this->mrm_profile_card_private_upload_dir()) . $stored_name;
    }

    if ($file === '') {
      wp_die('Missing file.');
    }

    $real_file = realpath($file);
    $private_root = realpath($this->mrm_profile_card_private_upload_dir());

    if (!$real_file || !$private_root || strpos($real_file, $private_root) !== 0 || !file_exists($real_file)) {
      wp_die('File not found or not allowed.');
    }

    if ($name === '') {
      $name = basename($real_file);
    }

    nocache_headers();

    $mime = function_exists('mime_content_type') ? (string)mime_content_type($real_file) : '';

    if ($mime === '' || $mime === 'application/octet-stream') {
      $ext = strtolower(pathinfo($real_file, PATHINFO_EXTENSION));

      $mime_by_ext = array(
        'jpg' => 'image/jpeg',
        'jpeg' => 'image/jpeg',
        'png' => 'image/png',
        'webp' => 'image/webp',
        'pdf' => 'application/pdf',
      );

      $mime = $mime_by_ext[$ext] ?? 'application/octet-stream';
    }

    header('Content-Type: ' . $mime);
    header('Content-Disposition: inline; filename="' . rawurlencode($name) . '"');
    header('Content-Length: ' . filesize($real_file));
    header('X-Content-Type-Options: nosniff');

    readfile($real_file);
    exit;
  }

