                    Payout: <code><?php echo esc_html($row['stripe_payout_id'] ?: '—'); ?></code>
                  <?php else : ?>
                    —
                  <?php endif; ?>
                </td>
              </tr>
            <?php endforeach; ?>
          <?php endif; ?>
        </tbody>
      </table>

      <p>
        <button type="submit" class="button" onclick="return confirm('Run payout processing for selected instructor lesson rows?');">
          Pay Selected Instructor Lessons
        </button>
      </p>
    </form>
    <?php
    return ob_get_clean();
