  public function render_access_lists_page() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission to view this page.');
    }

    global $wpdb;

    $this->maybe_install_or_upgrade_db();

    $access_table = $this->table_sheet_music_access();
    $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $access_table));

    $products = $this->all_products();
    $sheet_music_products = array();

    foreach ((array)$products as $sku => $product) {
      if (!is_array($product)) {
        continue;
      }

      $sku = $this->sanitize_product_slug($sku);

      if ($sku === '' || $sku === 'all-sheet-music') {
        continue;
      }

      if ((string)($product['product_type'] ?? '') !== 'sheet_music') {
        continue;
      }

      $sheet_music_products[$sku] = $this->mrm_sheet_music_manual_access_label($sku, $product);
    }

    uksort($sheet_music_products, function($a, $b) use ($sheet_music_products) {
      $a_key = $this->mrm_sheet_music_manual_access_sort_key($a, $sheet_music_products[$a] ?? $a);
      $b_key = $this->mrm_sheet_music_manual_access_sort_key($b, $sheet_music_products[$b] ?? $b);

      return strnatcasecmp($a_key, $b_key);
    });

    $active_rows = array();

    if ($table_exists === $access_table) {
      $active_rows = $wpdb->get_results(
        "SELECT id, email_plain, sku, start_at, expires_at, granted_at, source, source_id
         FROM {$access_table}
         WHERE revoked_at IS NULL
         ORDER BY granted_at DESC, id DESC",
        ARRAY_A
      );
    }

    $blocked_emails = $this->mrm_sheet_music_blocked_emails();

    $subscription_rows = array();
    $subscriptions_table = $this->table_sheet_music_subscriptions();
    $subscriptions_table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $subscriptions_table));

    if ($subscriptions_table_exists === $subscriptions_table) {
      $subscription_rows = $wpdb->get_results(
        "SELECT id, email_plain, stripe_status, current_period_start, current_period_end, cancel_at_period_end, canceled_at, stripe_subscription_id, updated_at
         FROM {$subscriptions_table}
         WHERE email_plain <> ''
         ORDER BY updated_at DESC, id DESC",
        ARRAY_A
      );
    }

    echo '<div class="wrap">';
    echo '<h1>Sheet Music Access</h1>';
    settings_errors('mrm_pay_hub');

    if (isset($_GET['sheet_music_blocked'])) {
      echo '<div class="notice notice-success"><p>Email blocked from sheet music access.</p></div>';
    }

    if (isset($_GET['sheet_music_unblocked'])) {
      echo '<div class="notice notice-success"><p>Email removed from the blocked sheet music access list. Existing valid access rows will work again.</p></div>';
    }

    if (isset($_GET['sheet_music_block_error'])) {
      echo '<div class="notice notice-error"><p>Could not update the blocked email list. Please confirm the email address is valid.</p></div>';
    }

    echo '<p>Use this page to manually grant access, review purchase-based access, review subscription access, and temporarily block abusive emails from accessing sheet music. Blocking an email does not delete its original access row; it acts as a security override until the email is unblocked.</p>';

    if ($table_exists !== $access_table) {
      echo '<div class="notice notice-error"><p>The sheet music access table is missing. The plugin attempted to run the database installer, but the table was not found.</p></div>';
      echo '</div>';
      return;
    }

    echo '<form method="post" action="">';
    wp_nonce_field('mrm_pay_hub_save', 'mrm_pay_hub_nonce');

    echo '<h2>Add Manual Sheet Music Access</h2>';

    if (empty($sheet_music_products)) {
      echo '<div class="notice notice-warning inline"><p>No active sheet music products were found. Add sheet music products in Payment Hub → Products before granting manual access.</p></div>';
    }

    echo '<table class="widefat striped" style="max-width:1100px;">';
    echo '<thead><tr>';
    echo '<th>Piece/Product</th>';
    echo '<th>Email</th>';
    echo '<th>Purchase/Start Date</th>';
    echo '<th>Expires Date</th>';
    echo '</tr></thead>';
    echo '<tbody>';

    for ($i = 0; $i < 3; $i++) {
      echo '<tr>';
      echo '<td>';
      echo '<select name="mrm_access_add_slug[]" style="min-width:260px;">';
      echo '<option value="">Select a piece/product</option>';
      foreach ($sheet_music_products as $sku => $label) {
        echo '<option value="' . esc_attr($sku) . '">' . esc_html($label . ' (' . $sku . ')') . '</option>';
      }
      echo '</select>';
      echo '</td>';
      echo '<td><input type="email" name="mrm_access_add_email[]" class="regular-text" placeholder="student@example.com"></td>';
      echo '<td><input type="date" name="mrm_access_add_purchase[]"></td>';
      echo '<td><input type="date" name="mrm_access_add_expires[]"></td>';
      echo '</tr>';
    }

    echo '</tbody>';
    echo '</table>';
    echo '<h2 style="margin-top:28px;">Active Sheet Music Access — Manual Grants, Purchases, and All-Access Rows</h2>';
    echo '<p class="description">This list includes every active row in the sheet-music access ledger, including per-piece purchases, manual grants, instructor-wide access, and all-sheet-music access created by eligible add-ons or legacy subscription flows. Manual grants can be edited or revoked here. Purchase-created and system-created rows are shown for review and security blocking only. Use Block Email to temporarily prevent an email from accessing any sheet music without deleting the original access record.</p>';

    if (empty($active_rows)) {
      echo '<p>No active sheet-music access rows were found.</p>';
    } else {
      echo '<table class="widefat striped" style="max-width:1200px;">';
      echo '<thead><tr>';
      echo '<th>Revoke</th><th>Email</th><th>Piece/Product</th><th>Start Date</th><th>Expires Date</th><th>Granted</th><th>Source</th><th>Security</th>';
      echo '</tr></thead><tbody>';
      foreach ($active_rows as $row) {
        $row_id = absint($row['id'] ?? 0);
        $sku = (string)($row['sku'] ?? '');
        $label = $sheet_music_products[$sku] ?? $this->mrm_sheet_music_manual_access_label($sku, array());
        $row_source = strtolower(trim((string)($row['source'] ?? '')));
        $row_is_manual = in_array($row_source, array('manual_admin', 'manual'), true);
        $start_value = '';
        if (!empty($row['start_at'])) {
          $start_ts = strtotime((string)$row['start_at']);
          if ($start_ts) $start_value = date('Y-m-d', $start_ts);
        }
        $expires_value = '';
        if (!empty($row['expires_at'])) {
          $expires_ts = strtotime((string)$row['expires_at']);
          if ($expires_ts) $expires_value = date('Y-m-d', $expires_ts);
        }
        echo '<tr>';
        echo '<td>';
        echo '<input type="hidden" name="mrm_access_row_id[]" value="' . esc_attr($row_id) . '">';
        if ($row_is_manual) {
          echo '<label><input type="checkbox" name="mrm_access_row_delete[]" value="' . esc_attr($row_id) . '"> Revoke</label>';
        } else {
          echo '<span class="description">Purchase-managed</span>';
        }
        echo '</td>';
        $row_email = strtolower(trim(sanitize_email((string)($row['email_plain'] ?? ''))));
        $row_is_blocked = $row_email !== '' && in_array($row_email, $blocked_emails, true);

        echo '<td>';

        if ($row_is_manual) {
          echo '<input type="email" name="mrm_access_row_email[]" value="' . esc_attr($row_email) . '" class="regular-text">';
        } else {
          echo '<code>' . esc_html($row_email) . '</code>';
          echo '<input type="hidden" name="mrm_access_row_email[]" value="' . esc_attr($row_email) . '">';
        }

        if ($row_is_blocked) {
          echo '<br><span style="display:inline-block;margin-top:6px;padding:3px 8px;border-radius:999px;background:#b32d2e;color:#fff;font-weight:700;">Blocked</span>';
        }

        echo '</td>';

        echo '<td><strong>' . esc_html($label) . '</strong><br><code>' . esc_html($sku) . '</code></td>';

        echo '<td>';
        if ($row_is_manual) {
          echo '<input type="date" name="mrm_access_row_start[]" value="' . esc_attr($start_value) . '">';
        } else {
          echo esc_html($start_value ?: '—');
          echo '<input type="hidden" name="mrm_access_row_start[]" value="' . esc_attr($start_value) . '">';
        }
        echo '</td>';

        echo '<td>';
        if ($row_is_manual) {
          echo '<input type="date" name="mrm_access_row_expires[]" value="' . esc_attr($expires_value) . '">';
        } else {
          echo esc_html($expires_value ?: '—');
          echo '<input type="hidden" name="mrm_access_row_expires[]" value="' . esc_attr($expires_value) . '">';
        }
        echo '</td>';
        echo '<td>' . esc_html((string)($row['granted_at'] ?? '')) . '</td>';
        echo '<td>' . esc_html($this->mrm_sheet_music_access_source_label((string)($row['source'] ?? ''), $sku)) . '</td>';

        echo '<td>';
        if ($row_email && is_email($row_email)) {
          if ($row_is_blocked) {
            echo '<button type="submit" class="button button-small" name="mrm_sheet_music_unblock_email" value="' . esc_attr($row_email) . '">Unblock Email</button>';
          } else {
            echo '<button type="submit" class="button button-small button-link-delete" name="mrm_sheet_music_block_email" value="' . esc_attr($row_email) . '" onclick="return confirm(\'Block this email from accessing all sheet music?\');">Block Email</button>';
          }
        } else {
          echo '<span class="description">No email stored.</span>';
        }
        echo '</td>';
        echo '</tr>';
      }
      echo '</tbody></table>';
    }

    echo '<h2 style="margin-top:32px;">Subscription / All Sheet Music Access</h2>';
    echo '<p class="description">These rows come from the sheet music subscription ledger. Blocking an email here restricts access without canceling the Stripe subscription.</p>';

    if (empty($subscription_rows)) {
      echo '<p>No subscription access rows were found.</p>';
    } else {
      echo '<table class="widefat striped" style="max-width:1200px;">';
      echo '<thead><tr>';
      echo '<th>Email</th><th>Status</th><th>Period Start</th><th>Period End</th><th>Cancel at Period End</th><th>Stripe Subscription</th><th>Security</th>';
      echo '</tr></thead><tbody>';

      foreach ($subscription_rows as $sub_row) {
        $sub_email = strtolower(trim(sanitize_email((string)($sub_row['email_plain'] ?? ''))));
        $sub_is_blocked = $sub_email !== '' && in_array($sub_email, $blocked_emails, true);

        echo '<tr>';
        echo '<td>';
        echo esc_html($sub_email);
        if ($sub_is_blocked) {
          echo '<br><span style="display:inline-block;margin-top:6px;padding:3px 8px;border-radius:999px;background:#b32d2e;color:#fff;font-weight:700;">Blocked</span>';
        }
        echo '</td>';
        echo '<td>' . esc_html((string)($sub_row['stripe_status'] ?? '')) . '</td>';
        echo '<td>' . esc_html((string)($sub_row['current_period_start'] ?? '')) . '</td>';
        echo '<td>' . esc_html((string)($sub_row['current_period_end'] ?? '')) . '</td>';
        echo '<td>' . (!empty($sub_row['cancel_at_period_end']) ? 'Yes' : 'No') . '</td>';
        echo '<td><code>' . esc_html((string)($sub_row['stripe_subscription_id'] ?? '')) . '</code></td>';
        echo '<td>';
        if ($sub_email && is_email($sub_email)) {
          if ($sub_is_blocked) {
            echo '<button type="submit" class="button button-small" name="mrm_sheet_music_unblock_email" value="' . esc_attr($sub_email) . '">Unblock Email</button>';
          } else {
            echo '<button type="submit" class="button button-small button-link-delete" name="mrm_sheet_music_block_email" value="' . esc_attr($sub_email) . '" onclick="return confirm(\'Block this email from accessing all sheet music?\');">Block Email</button>';
          }
        } else {
          echo '<span class="description">No email stored.</span>';
        }
        echo '</td>';
        echo '</tr>';
      }

      echo '</tbody></table>';
    }

    echo '<h2 style="margin-top:32px;">Blocked Sheet Music Access Emails</h2>';
    echo '<p class="description">Emails on this list cannot access any sheet music, even if they have a valid manual grant, completed purchase, or subscription. Use Unblock Email to restore access if the underlying access row is still valid.</p>';

    if (empty($blocked_emails)) {
      echo '<p>No emails are currently blocked.</p>';
    } else {
      echo '<table class="widefat striped" style="max-width:900px;">';
      echo '<thead><tr><th>Email</th><th>Action</th></tr></thead><tbody>';

      foreach ($blocked_emails as $blocked_email) {
        echo '<tr>';
        echo '<td><code>' . esc_html($blocked_email) . '</code></td>';
        echo '<td><button type="submit" class="button button-small" name="mrm_sheet_music_unblock_email" value="' . esc_attr($blocked_email) . '">Unblock Email</button></td>';
        echo '</tr>';
      }

      echo '</tbody></table>';
    }

    echo '<p class="submit"><button type="submit" class="button button-primary">Save Sheet Music Access</button></p>';
    echo '</form></div>';
  }

  public function render_marketing_email_lists_page() {
    if (!current_user_can('manage_options')) {
      wp_die('You do not have permission to view this page.');
    }

    $defs = $this->mrm_marketing_default_lists();
    $manual_lists = $this->mrm_marketing_manual_lists();
    $mailing_address = (string)get_option('mrm_pay_hub_marketing_mailing_address', '');
    $unsubscribed = $this->mrm_marketing_unsubscribed_emails();
    $sent_log = $this->mrm_marketing_sent_log();
    $this->mrm_marketing_save_sent_log($sent_log);
    $sent_log = $this->mrm_marketing_sent_log();

    $state_options = $this->mrm_marketing_state_options();
    $school_outreach_types = $this->mrm_marketing_school_outreach_types();

    $selected_state = isset($_GET['mrm_state'])
      ? sanitize_key(wp_unslash($_GET['mrm_state']))
      : 'az';

    if (!isset($state_options[$selected_state])) {
      $selected_state = 'az';
    }

    echo '<div class="wrap">';
    echo '<h1>Marketing Email Lists</h1>';
    $log_deleted_status = isset($_GET['mrm_marketing_log_deleted'])
      ? sanitize_key(wp_unslash($_GET['mrm_marketing_log_deleted']))
      : '';

    if ($log_deleted_status === '1') {
      echo '<div class="notice notice-success is-dismissible"><p>The selected marketing email history entry was removed.</p></div>';
    } elseif ($log_deleted_status === '0') {
      echo '<div class="notice notice-error is-dismissible"><p>The selected marketing email history entry could not be found or removed.</p></div>';
    }
    if (!empty($_GET['mrm_marketing_saved'])) echo '<div class="notice notice-success"><p>Marketing email lists saved.</p></div>';
    if (!empty($_GET['mrm_marketing_sent']) || isset($_GET['mrm_marketing_failed'])) echo '<div class="notice notice-success"><p>Marketing email send complete. Sent: ' . esc_html((string)($_GET['mrm_marketing_sent'] ?? '0')) . '. Failed: ' . esc_html((string)($_GET['mrm_marketing_failed'] ?? '0')) . '.</p></div>';
    if (!empty($_GET['mrm_marketing_resubscribed'])) echo '<div class="notice notice-success"><p>Re-subscribed ' . esc_html((string)$_GET['mrm_marketing_resubscribed']) . ' email(s).</p></div>';
    if (!empty($_GET['mrm_marketing_error'])) echo '<div class="notice notice-error"><p>' . esc_html(rawurldecode((string)$_GET['mrm_marketing_error'])) . '</p></div>';

    echo '<p>Use this page to manage manual marketing lists, review dynamic list counts, preview marketing emails, and send selected marketing messages.</p>';
    echo '<div style="display:grid;grid-template-columns:minmax(320px, 1fr) minmax(360px, 1fr);gap:20px;align-items:start;">';
    echo '<div style="background:#fff;border:1px solid #ccd0d4;border-radius:12px;padding:18px;">';
    echo '<h2>Save Manual Lists</h2>';

    echo '<form method="get" action="' . esc_url(admin_url('admin.php')) . '" style="margin:0 0 20px;">';
    echo '<input type="hidden" name="page" value="mrm-pay-hub-marketing-email-lists">';
    echo '<label for="mrm-marketing-state-selector"><strong>State-specific lists</strong></label><br>';
    echo '<select id="mrm-marketing-state-selector" name="mrm_state" onchange="this.form.submit();" style="min-width:280px;margin-top:6px;">';

    foreach ($state_options as $state_key => $state_label) {
      echo '<option value="' . esc_attr($state_key) . '" ' . selected($selected_state, $state_key, false) . '>'
        . esc_html($state_label)
        . '</option>';
    }

    echo '</select>';
    echo '<p class="description">This selection controls every state-specific instructor, professor, director, and administrator list on this page.</p>';
    echo '<noscript><button type="submit" class="button">View State</button></noscript>';
    echo '</form>';

    echo '<form id="mrm-marketing-list-save-form" method="post" action="' . esc_url(admin_url('admin-post.php')) . '">';
    echo '<input type="hidden" name="action" value="mrm_marketing_email_save_lists">';
    echo '<input type="hidden" name="mrm_marketing_state" value="'
      . esc_attr($selected_state)
      . '">';

    wp_nonce_field(
      'mrm_marketing_email_save_lists',
      'mrm_marketing_email_lists_nonce'
    );
    foreach ($defs as $key => $def) {
      $type = (string)($def['type'] ?? '');
      $label = (string)($def['label'] ?? $key);
      $desc = (string)($def['desc'] ?? '');
      echo '<div style="border-top:1px solid #e5e5e5;padding-top:14px;margin-top:14px;"><h3 style="margin-bottom:4px;">' . esc_html($label) . '</h3>';
      if ($desc !== '') echo '<p class="description">' . esc_html($desc) . '</p>';
      if ($type === 'manual') {
        $emails = isset($manual_lists[$key]) ? (array)$manual_lists[$key] : array();
        echo $this->mrm_marketing_manual_list_example_html($def);
        echo '<textarea name="mrm_marketing_list_' . esc_attr($key) . '" rows="7" class="large-text code" placeholder="one@example.com&#10;two@example.com">' . esc_textarea(implode("\n", $emails)) . '</textarea>';
        echo '<p class="description">Current saved emails: ' . esc_html((string)count($emails)) . '</p>';
      } else {
        /*
         * Instructor correspondence does not use the marketing
         * unsubscribe suppression list. Its displayed count should
         * therefore match the recipients that will actually be sent
         * correspondence.
         */
        $apply_suppression =
          !$this->mrm_marketing_is_instructor_list($key);

        $recipients = $this->mrm_marketing_get_list_recipients(
          $key,
          $apply_suppression
        );

        if ($this->mrm_marketing_is_instructor_list($key)) {
          echo '<p><strong>Dynamic list:</strong> '
            . esc_html((string)count($recipients))
            . ' current instructor recipient(s).</p>';
        } else {
          echo '<p><strong>Dynamic list:</strong> '
            . esc_html((string)count($recipients))
            . ' active recipient(s) after unsubscribe suppression.</p>';
        }
      }
      echo '</div>';
    }
    echo '<div style="border-top:2px solid #ccd0d4;padding-top:18px;margin-top:22px;">';

    echo '<h2 style="margin-bottom:4px;">Instructor Lists by State</h2>';

    echo '<p class="description">These dynamic lists are generated from fully onboarded instructor profile records. They cannot be edited manually.</p>';

    $selected_instructor_list_key = $this->mrm_marketing_state_instructor_key(
      $selected_state
    );

    $selected_instructor_recipients = $this->mrm_marketing_get_list_recipients(
      $selected_instructor_list_key,
      false
    );

    echo '<div style="border-top:1px solid #e5e5e5;padding-top:14px;margin-top:14px;">';

    echo '<h3 style="margin-bottom:4px;">Instructors in '
      . esc_html($state_options[$selected_state])
      . '</h3>';

    echo '<p class="description">Fully onboarded instructor profiles whose saved state is '
      . esc_html($state_options[$selected_state])
      . '.</p>';

    echo '<p><strong>Dynamic list:</strong> '
      . esc_html((string)count($selected_instructor_recipients))
      . ' current instructor recipient(s).</p>';

    echo '</div>';
    echo '</div>';

    echo '<div style="border-top:2px solid #ccd0d4;padding-top:18px;margin-top:22px;">';

    echo '<h2 style="margin-bottom:4px;">College Professor Lists by State</h2>';

    echo '<p class="description">These are manually populated marketing outreach lists. All College Professors automatically combines every state list and removes duplicate emails.</p>';

    $selected_professor_list_key =
      $this->mrm_marketing_state_college_professor_key(
        $selected_state
      );

    $selected_professor_emails = isset(
      $manual_lists[$selected_professor_list_key]
    )
      ? (array)$manual_lists[$selected_professor_list_key]
      : array();

    echo '<div style="border-top:1px solid #e5e5e5;padding-top:14px;margin-top:14px;">';

    echo '<h3 style="margin-bottom:4px;">College Professors in '
      . esc_html(
          $state_options[$selected_state]
        )
      . '</h3>';

    echo '<p class="description">Add one professional college or university professor email per line. This list receives the normal marketing footer and unsubscribe option.</p>';

    echo '<textarea name="mrm_marketing_college_professor_emails" rows="8" class="large-text code" form="mrm-marketing-list-save-form" placeholder="professor@example.edu&#10;faculty@example.edu">'
      . esc_textarea(
          implode("\n", $selected_professor_emails)
        )
      . '</textarea>';

    echo '<p class="description">Current saved emails: '
      . esc_html(
          (string)count($selected_professor_emails)
        )
      . '</p>';

    echo '</div>';
    echo '</div>';

    echo '<div style="border-top:2px solid #ccd0d4;padding-top:18px;margin-top:22px;">';
    echo '<h2 style="margin-bottom:4px;">'
      . esc_html($state_options[$selected_state])
      . ' School Outreach Lists'
      . '</h2>';

    echo '<p class="description">The four lists below belong only to '
      . esc_html($state_options[$selected_state])
      . '. Use the state dropdown above to view and edit another state.</p>';

    foreach ($school_outreach_types as $type_key => $type_def) {
      $list_key = $this->mrm_marketing_school_outreach_key(
        $selected_state,
        $type_key
      );

      $emails = isset($manual_lists[$list_key])
        ? (array)$manual_lists[$list_key]
        : array();

      $label = (string)($type_def['label'] ?? $type_key);
      $desc = (string)($type_def['desc'] ?? '');
      $example = (string)($type_def['example'] ?? '');

      echo '<div style="border-top:1px solid #e5e5e5;padding-top:14px;margin-top:14px;">';
      echo '<h3 style="margin-bottom:4px;">' . esc_html($label) . '</h3>';

      if ($desc !== '') {
        echo '<p class="description">' . esc_html($desc) . '</p>';
      }

      if ($example !== '') {
        echo '<details style="margin:8px 0 10px;">';
        echo '<summary style="cursor:pointer;">Show formatting example</summary>';
        echo '<pre style="white-space:pre-wrap;background:#f6f7f7;padding:10px;border:1px solid #dcdcde;">'
          . esc_html($example)
          . '</pre>';
        echo '</details>';
      }

      echo '<textarea name="mrm_marketing_school_list_'
        . esc_attr($type_key)
        . '" rows="7" class="large-text code" placeholder="one@example.edu&#10;two@example.edu">'
        . esc_textarea(implode("\n", $emails))
        . '</textarea>';

      echo '<p class="description">Current saved emails: '
        . esc_html((string)count($emails))
        . '</p>';

      echo '</div>';
    }

    echo '</div>';

    echo '<h3 style="margin-top:20px;">Mailing Address / Footer Text</h3><p class="description">Shown in the footer of marketing emails.</p>';
    echo '<textarea name="mrm_marketing_mailing_address" rows="4" class="large-text">' . esc_textarea($mailing_address) . '</textarea>';
    echo '<p class="submit">';
    echo '<button type="submit" class="button button-primary">';
    echo 'Save All Marketing Lists';
    echo '</button>';
    echo '</p>';
    echo '</form>';
    echo '</div>';

    echo '<div style="background:#fff;border:1px solid #ccd0d4;border-radius:12px;padding:18px;"><h2>Preview and Send Email</h2>';
    echo '<p class="description">'
      . '<strong>Instructor correspondence:</strong> Emails sent exclusively to All Current Instructors or a state-specific instructor list are sent without the marketing footer or unsubscribe link. '
      . '<strong>All other recipient lists:</strong> The normal marketing footer, mailing address, unsubscribe link, and suppression rules remain active. '
      . 'Instructor lists cannot be combined with marketing or school outreach lists in one send.'
      . '</p>';
    echo '<div style="border:1px solid #dcdcde;border-radius:10px;background:#f6f7f7;padding:14px;margin-bottom:18px;"><h3 style="margin-top:0;">Live Preview</h3><div><strong id="mrm-marketing-preview-subject">Subject preview will appear here.</strong></div><iframe id="mrm-marketing-preview-frame" title="Marketing email preview" style="display:block;width:100%;height:520px;border:1px solid #dcdcde;border-radius:8px;background:#fff;margin-top:10px;"></iframe></div>';
    echo '<form id="mrm-marketing-email-send-form" method="post" enctype="multipart/form-data" action="' . esc_url(admin_url('admin-post.php')) . '"><input type="hidden" name="action" value="mrm_marketing_email_send">';
    wp_nonce_field('mrm_marketing_email_send', 'mrm_marketing_email_send_nonce');
    echo '<table class="form-table"><tr><th scope="row"><label for="mrm_marketing_subject">Subject</label></th><td><input type="text" id="mrm_marketing_subject" name="mrm_marketing_subject" class="large-text" required></td></tr>';
    echo '<tr><th scope="row"><label for="mrm_marketing_html">Email Body</label></th><td><textarea id="mrm_marketing_html" name="mrm_marketing_html" rows="12" class="large-text code" required></textarea><p class="description">Enter the complete custom HTML for this email. The subject line is used only as the email subject and is not inserted into the body. Instructor-only correspondence is sent without an automatic footer. All other recipient lists receive the configured marketing mailing address and unsubscribe footer.</p></td></tr>';
    echo '<tr><th scope="row">Send To Lists</th><td>';

    echo '<div style="margin-bottom:16px;">';
    echo '<strong>Standard Lists</strong>';

    foreach ($defs as $key => $def) {
      $label = (string)($def['label'] ?? $key);

      /*
       * Instructor correspondence ignores marketing unsubscribe
       * suppression, so instructor list counts must do the same.
       */
      $apply_count_suppression =
        !$this->mrm_marketing_is_instructor_list($key);

      $count = count(
        $this->mrm_marketing_get_list_recipients(
          $key,
          $apply_count_suppression
        )
      );

      echo '<label style="display:block;margin:6px 0;">';
      $list_mode = $this->mrm_marketing_is_instructor_list($key)
        ? 'instructor'
        : 'marketing';

      echo '<input type="checkbox" class="mrm-marketing-recipient-list" data-list-mode="'
        . esc_attr($list_mode)
        . '" name="mrm_marketing_lists[]" value="'
        . esc_attr($key)
        . '"> ';
      echo esc_html($label);

