  private function mrm_legal_ledger_filter_state() {
    $allowed = array(
      'all', 'processing_lessons', 'completed_lessons',
      'processing_sheet_music', 'completed_sheet_music', 'other',
    );
    $view = isset($_GET['ledger_view']) ? sanitize_key(wp_unslash($_GET['ledger_view'])) : 'all';
    return array(
      'view' => in_array($view, $allowed, true) ? $view : 'all',
      'unresolved_only' => !empty($_GET['unresolved_only']),
    );
  }

  private function mrm_legal_ledger_view_label($view) {
    $labels = array(
      'all' => 'All Order Records',
      'processing_lessons' => 'Processing / Unfinished Lessons',
      'completed_lessons' => 'Completed Lesson Orders',
      'processing_sheet_music' => 'Processing / Unfinished Sheet Music',
      'completed_sheet_music' => 'Completed Sheet Music Orders',
      'other' => 'Failed, Canceled, and Other Records',
    );
    return $labels[$view] ?? $labels['all'];
  }

  private function mrm_legal_ledger_where_sql($view, $unresolved_only = false) {
    $processing = "'created','processing'";
    $completed = "'paid','refund_pending','partially_refunded','refunded'";
    $where = '1=1';

    if ($view === 'processing_lessons') {
      $where = "o.product_type = 'lesson' AND o.status IN ({$processing})";
    } elseif ($view === 'completed_lessons') {
      $where = "o.product_type = 'lesson' AND o.status IN ({$completed})";
    } elseif ($view === 'processing_sheet_music') {
      $where = "o.product_type = 'sheet_music' AND o.status IN ({$processing})";
    } elseif ($view === 'completed_sheet_music') {
      $where = "o.product_type = 'sheet_music' AND o.status IN ({$completed})";
    } elseif ($view === 'other') {
      $where = "(o.product_type NOT IN ('lesson','sheet_music') OR o.status NOT IN ({$processing},{$completed}))";
    }

    if ($unresolved_only && in_array($view, array('processing_lessons', 'processing_sheet_music'), true)) {
      $orders = $this->table_orders();
      $where .= " AND NOT EXISTS (
        SELECT 1 FROM {$orders} later
        WHERE later.email_hash = o.email_hash
          AND later.product_type = o.product_type
          AND later.status IN ({$completed})
          AND (later.created_at > o.created_at OR (later.created_at = o.created_at AND later.id > o.id))
      )";
    }
    return $where;
  }

  public function render_legal_ledger_page() {
    if (!current_user_can('manage_options')) wp_die('You do not have permission to view this page.');
    global $wpdb;
    $orders = $this->table_orders();
    $state = $this->mrm_legal_ledger_filter_state();

    echo '<div class="wrap"><h1>Legal Dispute Ledger</h1>';
    if (isset($_GET['ledger_reset'])) echo '<div class="notice notice-success"><p>The pre-launch legal ledger was reset.</p></div>';
    echo '<p>Order attempts are retained as evidence. Use the views below to organize completed and unfinished activity without deleting it.</p>';
    if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $orders)) !== $orders) {
      echo '<div class="notice notice-error"><p>Orders table is missing.</p></div></div>'; return;
    }

    echo '<form method="get"><input type="hidden" name="page" value="mrm-pay-hub-legal-ledger">';
    echo '<label for="mrm-ledger-view"><strong>View:</strong></label> <select id="mrm-ledger-view" name="ledger_view">';
    foreach (array('all','processing_lessons','completed_lessons','processing_sheet_music','completed_sheet_music','other') as $view) {
      echo '<option value="' . esc_attr($view) . '"' . selected($state['view'], $view, false) . '>' . esc_html($this->mrm_legal_ledger_view_label($view)) . '</option>';
    }
    echo '</select> <label><input type="checkbox" name="unresolved_only" value="1"' . checked($state['unresolved_only'], true, false) . '> For processing views, hide attempts followed by a later completed order</label> ';
    echo '<button class="button">Apply</button></form>';

    $export_url = add_query_arg(array('action'=>'mrm_export_legal_ledger','ledger_view'=>$state['view'],'unresolved_only'=>$state['unresolved_only'] ? 1 : 0), admin_url('admin-post.php'));
    echo '<p><a class="button button-primary" href="' . esc_url(wp_nonce_url($export_url, 'mrm_export_legal_ledger')) . '">Export Current View CSV</a></p>';
    $where = $this->mrm_legal_ledger_where_sql($state['view'], $state['unresolved_only']);

    $matching_count = (int)$wpdb->get_var(
      "SELECT COUNT(*) FROM {$orders} o WHERE {$where}"
    );

    $rows = $wpdb->get_results(
      "SELECT
         o.id,
         o.created_at,
         o.customer_email,
         o.sku,
         o.product_type,
         o.amount_cents,
         o.currency,
         o.status,
         o.stripe_payment_intent_id
       FROM {$orders} o
       WHERE {$where}
       ORDER BY o.created_at DESC, o.id DESC
       LIMIT 500",
      ARRAY_A
    );

    echo '<h2>' . esc_html($this->mrm_legal_ledger_view_label($state['view'])) . '</h2>';

    echo '<p><strong>' .
      esc_html(number_format_i18n($matching_count)) .
      '</strong> matching records. The table shows the newest ' .
      esc_html(number_format_i18n(min(500, $matching_count))) .
      '; the CSV export includes every matching record.</p>';

    if (!$rows) {
      echo '<p>No order records found in this view.</p>';
    }
    else {
      echo '<table class="widefat striped"><thead><tr><th>Order ID</th><th>Created</th><th>Email</th><th>SKU</th><th>Type</th><th>Amount</th><th>Status</th><th>Stripe Payment Intent</th></tr></thead><tbody>';
      foreach ($rows as $row) {
        $amount = '$' . number_format(((int)$row['amount_cents']) / 100, 2) . ' ' . strtoupper((string)$row['currency']);
        echo '<tr><td>' . esc_html($row['id']) . '</td><td>' . esc_html($row['created_at']) . '</td><td>' . esc_html($row['customer_email']) . '</td><td>' . esc_html($row['sku']) . '</td><td>' . esc_html($row['product_type']) . '</td><td>' . esc_html($amount) . '</td><td>' . esc_html($row['status']) . '</td><td>' . esc_html($row['stripe_payment_intent_id']) . '</td></tr>';
      }
      echo '</tbody></table>';
    }

    echo '<hr><h2>One-Time Pre-Launch Reset</h2>';
    $reset_at = get_option(self::OPT_LEGAL_LEDGER_RESET_AT, '');
    if ($reset_at) echo '<p><strong>Reset permanently locked.</strong> Completed at ' . esc_html($reset_at) . '.</p>';
    else {
      echo '<p>Export the existing ledger first. This removes pre-launch order, payout, credit, promo-redemption, and Stripe-purchase entitlement records.</p>';
      echo '<form method="post" action="' . esc_url(admin_url('admin-post.php')) . '" onsubmit="return confirm(\'Permanently reset the pre-launch ledger?\');"><input type="hidden" name="action" value="mrm_reset_prelaunch_legal_ledger">';
      wp_nonce_field('mrm_reset_prelaunch_legal_ledger');
      echo '<label>Type <code>RESET PRELAUNCH LEDGER</code>: <input type="text" name="reset_confirmation" autocomplete="off"></label> <button class="button button-secondary">Reset Pre-Launch Ledger</button></form>';
    }
    echo '</div>';
  }

  public function handle_export_legal_ledger() {
    if (!is_admin()) wp_die('Invalid request.', 'Legal Ledger Export', array('response'=>400));
    if (!current_user_can('manage_options')) wp_die('You do not have permission to export this ledger.', 'Legal Ledger Export', array('response'=>403));
    check_admin_referer('mrm_export_legal_ledger');
    global $wpdb;
    $orders = $this->table_orders();
    if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $orders)) !== $orders) wp_die('Orders table is missing.', 'Legal Ledger Export', array('response'=>500));
    $state = $this->mrm_legal_ledger_filter_state();
    $where = $this->mrm_legal_ledger_where_sql($state['view'], $state['unresolved_only']);
    $rows = $wpdb->get_results("SELECT o.id,o.created_at,o.updated_at,o.customer_email,o.sku,o.product_type,o.amount_cents,o.currency,o.environment_mode,o.status,o.stripe_payment_intent_id,o.stripe_status,o.metadata_json FROM {$orders} o WHERE {$where} ORDER BY o.created_at DESC,o.id DESC", ARRAY_A);
    $export_rows = array();
    foreach ((array)$rows as $row) $export_rows[] = array($row['id'],$row['created_at'],$row['updated_at'],$row['customer_email'],$row['sku'],$row['product_type'],number_format(((int)$row['amount_cents'])/100,2,'.',''),$row['currency'],$row['environment_mode'],$row['status'],$row['stripe_payment_intent_id'],$row['stripe_status'],$row['metadata_json']);
    $this->mrm_csv_send('low-brass-lessons-legal-ledger-' . $state['view'] . '-' . gmdate('Y-m-d') . '.csv', array('Order ID','Created At','Updated At','Customer Email','SKU','Product Type','Amount','Currency','Environment','Status','Stripe Payment Intent','Stripe Status','Metadata JSON'), $export_rows);
  }

  public function handle_reset_prelaunch_legal_ledger() {
    if (!is_admin()) {
      wp_die(
        'Invalid request.',
        'Legal Ledger Reset',
        array('response' => 400)
      );
    }

    if (!current_user_can('manage_options')) {
      wp_die(
        'You do not have permission to reset this ledger.',
        'Legal Ledger Reset',
        array('response' => 403)
      );
    }

    check_admin_referer('mrm_reset_prelaunch_legal_ledger');

    if (get_option(self::OPT_LEGAL_LEDGER_RESET_AT, '')) {
      wp_die(
        'The one-time pre-launch reset has already been used.',
        'Legal Ledger Reset',
        array('response' => 409)
      );
    }

    $confirmation = isset($_POST['reset_confirmation'])
      ? sanitize_text_field(
          wp_unslash($_POST['reset_confirmation'])
        )
      : '';

    if ($confirmation !== 'RESET PRELAUNCH LEDGER') {
      wp_die(
        'The reset confirmation text did not match.',
        'Legal Ledger Reset',
        array('response' => 400)
      );
    }

    global $wpdb;

    $access_table = $this->table_sheet_music_access();
    $source_id_like = $wpdb->esc_like('pi_') . '%';
    $source_like = $wpdb->esc_like('stripe_pi') . '%';

    $wpdb->query('START TRANSACTION');

    $queries = array(
      $wpdb->prepare(
        "DELETE FROM {$access_table}
         WHERE source_id LIKE %s
            OR source LIKE %s",
        $source_id_like,
        $source_like
      ),

      "DELETE FROM {$this->table_links()}",

      "DELETE FROM {$this->table_payout_ledger()}",

      "DELETE FROM {$this->table_lesson_credits()}",

      "DELETE FROM {$this->table_promo_redemptions()}",

      "DELETE FROM {$this->table_orders()}",
    );

    foreach ($queries as $query) {
      if ($wpdb->query($query) === false) {
        $wpdb->query('ROLLBACK');

        wp_die(
          'The ledger reset failed; no database changes were committed.',
          'Legal Ledger Reset',
          array('response' => 500)
        );
      }
    }

    delete_option(self::OPT_ACCESS_LISTS);

    update_option(
      self::OPT_LEGAL_LEDGER_RESET_AT,
      current_time('mysql'),
      false
    );

    $wpdb->query('COMMIT');

    /*
     * DELETE empties the tables but normally leaves their next IDs
     * unchanged. Reset the counters after the deletion transaction.
     */
    $tables_to_reset = array(
      $this->table_links(),
      $this->table_payout_ledger(),
      $this->table_lesson_credits(),
      $this->table_promo_redemptions(),
      $this->table_orders(),
    );

    foreach ($tables_to_reset as $table) {
      $table_exists = $wpdb->get_var(
        $wpdb->prepare(
          'SHOW TABLES LIKE %s',
          $table
        )
      );

      if ($table_exists === $table) {
        $wpdb->query(
          "ALTER TABLE {$table} AUTO_INCREMENT = 1"
        );
      }
    }

    wp_safe_redirect(
      admin_url(
        'admin.php?page=mrm-pay-hub-legal-ledger&ledger_reset=1'
      )
    );

    exit;
  }

  public function handle_admin_post() {
    if (!is_admin()) return;
    if (!current_user_can('manage_options')) return;

    if (isset($_POST['mrm_pay_hub_test_aws_nonce']) && wp_verify_nonce($_POST['mrm_pay_hub_test_aws_nonce'], 'mrm_pay_hub_test_aws')) {
      $this->mrm_aws_debug_log('Stripe AWS test button pressed.');
      $result = $this->stripe_api_request('GET', '/v1/account');

      if (is_wp_error($result)) {
        $this->mrm_aws_debug_log('Stripe AWS test failed.', array(
          'error_code' => $result->get_error_code(),
          'error_message' => $result->get_error_message(),
        ));
        add_settings_error(
          'mrm_pay_hub',
          'aws_test_failed',
          'Stripe AWS test failed: ' . $result->get_error_message(),
          'error'
        );
      } else {
        $acct_id = isset($result['id']) ? (string)$result['id'] : '';
        $this->mrm_aws_debug_log('Stripe AWS test succeeded.', array(
          'account_id' => isset($result['id']) ? (string)$result['id'] : '',
        ));
        add_settings_error(
          'mrm_pay_hub',
          'aws_test_ok',
          'Stripe AWS test succeeded. Connected account response received' . ($acct_id !== '' ? ' (' . $acct_id . ')' : '') . '.',
          'updated'
        );
      }
    }

    // Repair default lesson SKUs if they were wiped to 0 by a prior update bug
    $this->ensure_default_products();

    if (isset($_POST['mrm_pay_hub_nonce']) && wp_verify_nonce($_POST['mrm_pay_hub_nonce'], 'mrm_pay_hub_save')) {
      $settings = $this->get_settings();
      if (isset($_POST['mrm_sheet_music_block_email'])) {
        $email_to_block = sanitize_email(wp_unslash($_POST['mrm_sheet_music_block_email']));

        if ($this->mrm_block_sheet_music_email($email_to_block)) {
          wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-access&sheet_music_blocked=1'));
          exit;
        }

        wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-access&sheet_music_block_error=1'));
        exit;
      }

      if (isset($_POST['mrm_sheet_music_unblock_email'])) {
        $email_to_unblock = sanitize_email(wp_unslash($_POST['mrm_sheet_music_unblock_email']));

        if ($this->mrm_unblock_sheet_music_email($email_to_unblock)) {
          wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-access&sheet_music_unblocked=1'));
          exit;
        }

        wp_safe_redirect(admin_url('admin.php?page=mrm-pay-hub-access&sheet_music_block_error=1'));
        exit;
      }

      // AWS / wp-config managed Stripe credentials are no longer stored in WordPress settings.

      if (isset($_POST['stripe_sheet_music_subscription_price_id'])) {
        $settings['stripe_sheet_music_subscription_price_id'] = sanitize_text_field((string)$_POST['stripe_sheet_music_subscription_price_id']);
        $settings['stripe_test_sheet_music_subscription_price_id'] = '';
      }

      if (isset($_POST['composer_connected_account_id'])) {
        $settings['composer_connected_account_id'] = sanitize_text_field((string)$_POST['composer_connected_account_id']);
      }

      if (isset($_POST['composer_payout_summary_email'])) {
        $settings['composer_payout_summary_email'] = sanitize_email(wp_unslash($_POST['composer_payout_summary_email']));
      }

      if (isset($_POST['background_check_standard_docusign_url'])) {
        $settings['background_check_standard_docusign_url'] = esc_url_raw(wp_unslash($_POST['background_check_standard_docusign_url']));

        /*
         * Keep the old setting populated as a fallback for older code paths.
         */
        $settings['background_check_docusign_url'] = $settings['background_check_standard_docusign_url'];
      }

      if (isset($_POST['background_check_california_docusign_url'])) {
        $settings['background_check_california_docusign_url'] = esc_url_raw(wp_unslash($_POST['background_check_california_docusign_url']));
      }

      if (isset($_POST['instructor_agreement_w9_docusign_url'])) {
        $settings['instructor_agreement_w9_docusign_url'] = esc_url_raw(wp_unslash($_POST['instructor_agreement_w9_docusign_url']));
      }

      if (isset($_POST['presenter_agreement_w9_docusign_url'])) {
        $settings['presenter_agreement_w9_docusign_url'] = esc_url_raw(wp_unslash($_POST['presenter_agreement_w9_docusign_url']));
      }

      if (isset($_POST['owner_payout_summary_email'])) {
        $settings['owner_payout_summary_email'] = sanitize_email(wp_unslash($_POST['owner_payout_summary_email']));
      }

      if (isset($_POST['one_time_sheet_music_composer_pct'])) {
        $settings['one_time_sheet_music_composer_pct'] = $this->mrm_sanitize_percent_setting($_POST['one_time_sheet_music_composer_pct'], 0);
      }

      if (isset($_POST['in_person_travel_amount'])) {
        $settings['in_person_travel_amount_cents'] = $this->mrm_money_to_cents($_POST['in_person_travel_amount'], 500);
      }

      foreach ($this->mrm_get_instructor_payout_chart_rows() as $row) {
        foreach (array_keys($this->mrm_get_instructor_payout_chart_columns()) as $year_bucket) {
          $setting_key = $this->mrm_get_instructor_payout_chart_setting_key(
            (int)$row['lesson_length'],
            (int)$row['is_online'],
            (int)$year_bucket
          );

          if ($setting_key === '') {
            continue;
          }

          $field_name = str_replace('_cents', '', $setting_key);

          if (isset($_POST[$field_name])) {
            $settings[$setting_key] = $this->mrm_money_to_cents(
              $_POST[$field_name],
              0
            );
          }
        }
      }

      if (isset($_POST['payout_anchor_date'])) {
        $settings['payout_anchor_date'] = sanitize_text_field((string)$_POST['payout_anchor_date']);
      }

      unset($settings['instructor_tier_rules']);
      unset($settings['instructor_payout_30_online_cents']);
      unset($settings['instructor_payout_30_inperson_cents']);
      unset($settings['instructor_payout_60_online_cents']);
      unset($settings['instructor_payout_60_inperson_cents']);

      $this->save_settings($settings);
      $this->mrm_schedule_daily_payout_check();

      // ✅ Manual access row inserts (row-based UI)
      if (
        isset($_POST['mrm_access_add_slug'], $_POST['mrm_access_add_email']) &&
        is_array($_POST['mrm_access_add_slug']) &&
        is_array($_POST['mrm_access_add_email'])
      ) {
        global $wpdb;
        $access_table = $this->table_sheet_music_access();

        // Ensure DB exists
        $this->maybe_install_or_upgrade_db();

        foreach ($_POST['mrm_access_add_slug'] as $i => $slug_raw) {
          $slug = $this->sanitize_product_slug($slug_raw);
          $email = sanitize_email((string)($_POST['mrm_access_add_email'][$i] ?? ''));

          if (!$slug) continue;
          if (!$email || !is_email($email)) continue;
          if ($slug === 'all-sheet-music') continue;

          $purchase_raw = (string)($_POST['mrm_access_add_purchase'][$i] ?? '');
          $expires_raw  = (string)($_POST['mrm_access_add_expires'][$i] ?? '');

          $purchase_dt = $purchase_raw ? date('Y-m-d 00:00:00', strtotime($purchase_raw)) : current_time('mysql');
          $expires_dt  = $expires_raw ? date('Y-m-d 00:00:00', strtotime($expires_raw)) : null;

          $email_hash = $this->email_hash($email);

          // Idempotent: skip if already active
          $existing = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$access_table} WHERE email_hash=%s AND sku=%s AND revoked_at IS NULL LIMIT 1",
            $email_hash, $slug
          ));
          if ($existing) continue;

          $wpdb->insert($access_table, array(
            'email_hash'  => $email_hash,
            'email_plain' => $email,
            'sku'         => $slug,
            'start_at'    => $purchase_dt,
            'expires_at'  => $expires_dt,
            'month_key'   => null,
            'granted_at'  => current_time('mysql'),
            'revoked_at'  => null,
            'source'      => 'manual_admin',
            'source_id'   => null,
          ), array('%s','%s','%s','%s','%s','%s','%s','%s','%s','%s'));
        }
      }

      // ✅ Edit / delete existing active access rows (row-based UI)
      if (isset($_POST['mrm_access_row_id']) && is_array($_POST['mrm_access_row_id'])) {
        global $wpdb;
        $access_table = $this->table_sheet_music_access();
        $this->maybe_install_or_upgrade_db();

        $delete_ids = array();
        if (isset($_POST['mrm_access_row_delete']) && is_array($_POST['mrm_access_row_delete'])) {
          foreach ($_POST['mrm_access_row_delete'] as $did) {
            $delete_ids[(int)$did] = true;
          }
        }

        foreach ($_POST['mrm_access_row_id'] as $i => $id_raw) {
          $row_id = (int)$id_raw;
          if ($row_id <= 0) continue;

          $row_record = $wpdb->get_row(
            $wpdb->prepare(
              "SELECT sku, source FROM {$access_table} WHERE id = %d LIMIT 1",
              $row_id
            ),
            ARRAY_A
          );

          $row_sku = (string)($row_record['sku'] ?? '');
          $row_source = strtolower(trim((string)($row_record['source'] ?? '')));
          $row_is_manual = in_array($row_source, array('manual_admin', 'manual'), true);

          if ($row_sku === 'all-sheet-music') {
            continue;
          }

          /*
           * Purchase/subscription-generated access rows are reviewable and blockable,
           * but should not be edited or revoked from this manual access editor.
           */
          if (!$row_is_manual) {
            continue;
          }

          // Delete (revoke) row
          if (isset($delete_ids[$row_id])) {
            $wpdb->update(
              $access_table,
              array('revoked_at' => current_time('mysql')),
              array('id' => $row_id),
              array('%s'),
              array('%d')
            );
            continue;
          }

          $email = sanitize_email((string)($_POST['mrm_access_row_email'][$i] ?? ''));
          if (!$email || !is_email($email)) {
            // skip invalid edits; preserve existing row
            continue;
          }

          $start_raw  = (string)($_POST['mrm_access_row_start'][$i] ?? '');
          $expire_raw = (string)($_POST['mrm_access_row_expires'][$i] ?? '');

          $start_dt  = $start_raw ? date('Y-m-d 00:00:00', strtotime($start_raw)) : null;
          $expire_dt = $expire_raw ? date('Y-m-d 00:00:00', strtotime($expire_raw)) : null;

          $wpdb->update(
            $access_table,
            array(
              'email_plain' => $email,
              'email_hash'  => $this->email_hash($email),
              'start_at'    => $start_dt,
              'expires_at'  => $expire_dt,
            ),
            array('id' => $row_id),
            array('%s','%s','%s','%s'),
            array('%d')
          );
        }
      }

      // Delete selected piece-product access rows
      if (!empty($_POST['mrm_piece_access_delete']) && is_array($_POST['mrm_piece_access_delete'])) {
        global $wpdb;
        $access_table = $this->table_sheet_music_access();

        $delete_ids = array_map('intval', (array)$_POST['mrm_piece_access_delete']);
        $delete_ids = array_filter($delete_ids);

        foreach ($delete_ids as $row_id) {
          if ($row_id <= 0) continue;

          $row_sku = (string)$wpdb->get_var($wpdb->prepare(
            "SELECT sku FROM {$access_table} WHERE id = %d LIMIT 1",
            $row_id
          ));

          // Never allow manual delete of the Stripe-managed subscription master row.
          if ($row_sku === 'all-sheet-music') {
            continue;
          }

          $wpdb->update(
            $access_table,
            array(
              'revoked_at' => current_time('mysql'),
            ),
            array('id' => $row_id),
            array('%s'),
            array('%d')
          );
        }
      }

      if (!empty($_POST['mrm_run_payout_batch'])) {
        $result = $this->mrm_run_payout_batch(true);
        $last = !empty($result['last_error']) ? (' Last error: ' . $result['last_error']) : '';
        $msg = 'Payout batch run. Transfers: ' . (int)($result['transfers_created'] ?? 0) . ', payouts: ' . (int)($result['payouts_created'] ?? 0) . ', errors: ' . (int)($result['errors'] ?? 0) . $last;
        add_settings_error('mrm_pay_hub', 'payout_batch_run', $msg, empty($result['errors']) ? 'updated' : 'error');
      }

      add_settings_error('mrm_pay_hub', 'saved', 'Settings saved.', 'updated');
    }

    if (isset($_POST['mrm_pay_hub_promo_codes_nonce']) && wp_verify_nonce($_POST['mrm_pay_hub_promo_codes_nonce'], 'mrm_pay_hub_save_promo_codes')) {
      $remove_ids = isset($_POST['promo_redemption_remove']) ? array_map('absint', (array)$_POST['promo_redemption_remove']) : array();
      $removed_redemptions = !empty($remove_ids) ? $this->mrm_delete_promo_redemption_rows($remove_ids) : 0;
      $existing_codes = $this->mrm_get_promo_codes();
      $codes = array();
      $seen_codes = array();
      $posted_codes = isset($_POST['promo_code']) ? (array)wp_unslash($_POST['promo_code']) : array();
      $labels = isset($_POST['promo_label']) ? (array)wp_unslash($_POST['promo_label']) : array();
      $discount_types = isset($_POST['promo_discount_type']) ? (array)wp_unslash($_POST['promo_discount_type']) : array();
      $percent_offs = isset($_POST['promo_percent_off']) ? (array)wp_unslash($_POST['promo_percent_off']) : array();
      $amount_offs = isset($_POST['promo_amount_off']) ? (array)wp_unslash($_POST['promo_amount_off']) : array();
      $targets = isset($_POST['promo_target']) ? (array)wp_unslash($_POST['promo_target']) : array();
      $rule_modes = isset($_POST['promo_rule_mode']) ? (array)wp_unslash($_POST['promo_rule_mode']) : array();
      $counts = isset($_POST['promo_occurrence_count']) ? (array)wp_unslash($_POST['promo_occurrence_count']) : array();
      $starts = isset($_POST['promo_starts_at']) ? (array)wp_unslash($_POST['promo_starts_at']) : array();
      $expires = isset($_POST['promo_expires_at']) ? (array)wp_unslash($_POST['promo_expires_at']) : array();
      $reusable = isset($_POST['promo_reusable_per_email']) ? (array)wp_unslash($_POST['promo_reusable_per_email']) : array();
      $deletes = isset($_POST['promo_delete']) ? (array)wp_unslash($_POST['promo_delete']) : array();

      foreach ($posted_codes as $i => $raw_code) {
        $code = $this->mrm_normalize_promo_code($raw_code);
        if ($code === '' || !empty($deletes[$i])) continue;
        if (isset($seen_codes[$code])) {
          add_settings_error('mrm_pay_hub', 'duplicate_promo_code_' . absint($i), 'Duplicate promotional code ignored: ' . $code, 'error');
          continue;
        }
        $seen_codes[$code] = true;
        $preserve = function () use (&$codes, $existing_codes, $code) { if (isset($existing_codes[$code]) && is_array($existing_codes[$code])) $codes[$code] = $existing_codes[$code]; };
        $discount_type = sanitize_key((string)($discount_types[$i] ?? 'percent'));
        if (!in_array($discount_type, array('percent', 'amount'), true)) $discount_type = 'percent';
        $percent = max(0, min(100, absint($percent_offs[$i] ?? 0)));
        $amount_cents = $this->mrm_money_to_cents($amount_offs[$i] ?? '0.00', 0);
        if ($discount_type === 'percent') {
          $amount_cents = 0;
          if ($percent <= 0) { $preserve(); add_settings_error('mrm_pay_hub','invalid_promo_percent_'.absint($i),$code.' requires a percentage greater than zero.','error'); continue; }
        } else {
          $percent = 0;
          if ($amount_cents <= 0) { $preserve(); add_settings_error('mrm_pay_hub','invalid_promo_amount_'.absint($i),$code.' requires a dollar amount greater than zero.','error'); continue; }
        }
        $target = $this->mrm_normalize_promo_target($targets[$i] ?? 'all');
        if ($target === '' || !$this->mrm_promo_target_is_known($target)) { $preserve(); add_settings_error('mrm_pay_hub','invalid_promo_target_'.absint($i),$code.' has an invalid or unavailable target.','error'); continue; }
        $scope_values = $this->mrm_promo_scope_values_for_target($target);
        if (empty($scope_values)) { $preserve(); add_settings_error('mrm_pay_hub','invalid_promo_scope_'.absint($i),$code.' could not resolve its purchase type.','error'); continue; }
        $scope = count($scope_values) === 3 ? 'all' : (count($scope_values) === 1 ? $scope_values[0] : implode(',', $scope_values));
        $rule_mode = sanitize_key((string)($rule_modes[$i] ?? 'all'));
        if (!in_array($rule_mode, array('all','first_n','first_n_months','after_n','date_window'), true)) $rule_mode = 'all';
        /* Occurrence-based rules are meaningful only for lesson-only targets. */
        $lesson_rule_target = strpos($target, 'lesson:') === 0;
        if (!$lesson_rule_target && in_array($rule_mode, array('first_n','first_n_months','after_n'), true)) $rule_mode = 'all';
        $count = max(0, absint($counts[$i] ?? 0));
        if (in_array($rule_mode, array('first_n','first_n_months','after_n'), true) && $count <= 0) { $preserve(); add_settings_error('mrm_pay_hub','invalid_promo_occurrence_'.absint($i),$code.' requires an occurrence or month count greater than zero.','error'); continue; }
        if (in_array($rule_mode, array('all','date_window'), true)) $count = 0;
        $starts_at = sanitize_text_field((string)($starts[$i] ?? ''));
        $expires_at = sanitize_text_field((string)($expires[$i] ?? ''));
        if ($starts_at !== '' && !preg_match('/^\d{4}-\d{2}-\d{2}$/', $starts_at)) { $preserve(); add_settings_error('mrm_pay_hub','invalid_promo_start_'.absint($i),$code.' has an invalid start date.','error'); continue; }
        if ($expires_at !== '' && !preg_match('/^\d{4}-\d{2}-\d{2}$/', $expires_at)) { $preserve(); add_settings_error('mrm_pay_hub','invalid_promo_end_'.absint($i),$code.' has an invalid end date.','error'); continue; }
        if ($starts_at !== '' && $expires_at !== '' && strtotime($starts_at) > strtotime($expires_at)) { $preserve(); add_settings_error('mrm_pay_hub','invalid_promo_date_range_'.absint($i),$code.' has an end date before its start date.','error'); continue; }
        $codes[$code] = array(
          'code'=>$code, 'label'=>sanitize_text_field((string)($labels[$i] ?? '')), 'discount_type'=>$discount_type,
          'percent_off'=>$percent, 'amount_off_cents'=>max(0,(int)$amount_cents), 'promo_target'=>$target,
          'scope'=>$scope, 'scopes'=>$scope_values, 'applies_to'=>'all_items', 'rule_mode'=>$rule_mode,
          'occurrence_count'=>$count, 'after_occurrence'=>0, 'starts_at'=>$starts_at, 'expires_at'=>$expires_at,
          'reusable_per_email'=>!empty($reusable[$i]) ? 1 : 0, 'active'=>1, 'updated_at'=>current_time('mysql'),
        );
      }
      $this->mrm_save_promo_codes($codes);
      $message = 'Promo codes saved.';
      if ($removed_redemptions > 0) $message .= ' Removed ' . (int)$removed_redemptions . ' completed redemption' . ($removed_redemptions === 1 ? '' : 's') . '.';
      add_settings_error('mrm_pay_hub', 'promo_codes_saved', $message, 'updated');
    }

    if (isset($_POST['mrm_pay_hub_products_nonce']) && wp_verify_nonce($_POST['mrm_pay_hub_products_nonce'], 'mrm_pay_hub_save_products')) {
      $existing = $this->all_products();
      $products = is_array($existing) ? $existing : array();

      $skus = isset($_POST['sku']) ? (array)$_POST['sku'] : array();
      $original_skus = isset($_POST['original_sku']) ? (array)$_POST['original_sku'] : array();
      $labels = isset($_POST['label']) ? (array)$_POST['label'] : array();
      $amounts = isset($_POST['amount_cents']) ? (array)$_POST['amount_cents'] : array();
      $currencies = isset($_POST['currency']) ? (array)$_POST['currency'] : array();
      $types = isset($_POST['product_type']) ? (array)$_POST['product_type'] : array();
      $categories = isset($_POST['category']) ? (array)$_POST['category'] : array();
      $deletes = isset($_POST['delete']) ? (array)$_POST['delete'] : array();
      $fundamentals_addon_enabled=(array)($_POST['fundamentals_addon_enabled']??array());
      $fundamentals_addon_skus=(array)($_POST['fundamentals_addon_sku']??array());
      $fundamentals_addon_amounts=(array)($_POST['fundamentals_addon_amount_cents']??array());

      $allowed_currencies = array('usd', 'eur');
      $allowed_types = array('lesson', 'sheet_music');
      $allowed_categories = array(
        'lesson' => array('60_online', '60_inperson', '30_online', '30_inperson'),
        'sheet_music' => array('fundamentals', 'trombone-euphonium', 'tuba', 'complete-package'),
      );
      $sku_renames = array();

      foreach ($skus as $index => $sku_raw) {
        $raw_sku_value = trim((string)$sku_raw);
        $raw_original_sku = trim((string)($original_skus[$index] ?? ''));
        $raw_label_value = trim((string)($labels[$index] ?? ''));
        $raw_amount_value = trim((string)($amounts[$index] ?? ''));
        $is_delete_request = !empty($deletes[$index]);

        $has_meaningful_input =
          ($raw_sku_value !== '') ||
          ($raw_original_sku !== '') ||
          ($raw_label_value !== '') ||
          ($raw_amount_value !== '') ||
          $is_delete_request;

        // Ignore the blank "new product" template row so it cannot overwrite real products.
        if (!$has_meaningful_input) {
          continue;
        }

        $label_raw = sanitize_text_field($raw_label_value);
        $type = sanitize_text_field((string)($types[$index] ?? 'sheet_music'));
        if (!in_array($type, $allowed_types, true)) $type = 'lesson';
        $category = sanitize_text_field((string)($categories[$index] ?? ''));
        if (!in_array($category, $allowed_categories[$type], true)) {
          $category = $allowed_categories[$type][0];
        }

        $original_sku = $this->sanitize_sku((string)($original_skus[$index] ?? ''));
        $current_sku = $original_sku ? $original_sku : $this->sanitize_sku($sku_raw);
        $existing_product=($current_sku && isset($products[$current_sku]) && is_array($products[$current_sku]))?$products[$current_sku]:array();
        if (!empty($deletes[$index])) {
          if ($current_sku) {
            unset($products[$current_sku]);
          }
          continue;
        }
        if ($type === 'sheet_music') {
          $sku = $this->generate_sheet_music_sku($label_raw, $category, $current_sku);
          if ($current_sku && $current_sku !== $sku) {
            $sku_renames[$current_sku] = $sku;
            unset($products[$current_sku]);
          }
        } else {
          $sku = 'lesson_' . $category;
          if ($current_sku && $current_sku !== $sku) {
            $sku_renames[$current_sku] = $sku;
            unset($products[$current_sku]);
          }
        }
        $sku = $this->sanitize_sku($sku);
        if (!$sku) continue;

        $label = $label_raw !== '' ? $label_raw : $sku;

        $amount_raw = trim((string)($amounts[$index] ?? ''));
        if ($amount_raw === '' && isset($existing_product['amount_cents'])) {
          // Preserve the existing price if the field was left blank.
          $final_amount_cents = max(0, (int)$existing_product['amount_cents']);
        } else {
          $final_amount_cents = max(0, (int)$amount_raw);
        }

        $currency = sanitize_text_field((string)($currencies[$index] ?? 'usd'));
        if (!in_array($currency, $allowed_currencies, true)) $currency = 'usd';

        $is_full_piece=$type==='sheet_music' && in_array($category,array('tuba','trombone-euphonium'),true);
        $posted_addon_amount = trim((string)($fundamentals_addon_amounts[$index] ?? ''));
        $existing_addon_amount = max(1, (int)($existing_product['fundamentals_addon_amount_cents'] ?? 500));
        if ($posted_addon_amount === '') {
          $addon_amount_cents = $existing_addon_amount;
        } else {
          $addon_amount_cents = max(1, (int)$posted_addon_amount);
        }
        $products[$sku] = array_merge($existing_product,array(
          'sku'=>$sku,'label'=>$label,'amount_cents'=>$final_amount_cents,'currency'=>$currency,
          'product_type'=>$type,'category'=>$category,'active'=>1,
          'fundamentals_addon_enabled'=>$is_full_piece && !empty($fundamentals_addon_enabled[$index])?1:0,
          'fundamentals_addon_sku'=>$is_full_piece?$this->sanitize_sku($fundamentals_addon_skus[$index]??''):'',
          'fundamentals_addon_amount_cents'=>$is_full_piece?$addon_amount_cents:500,
        ));
      }

      if (!empty($sku_renames)) {
        foreach ($products as $saved_sku => $saved_product) {
          if (!is_array($saved_product)) continue;
          $linked_addon_sku = $this->sanitize_sku((string)($saved_product['fundamentals_addon_sku'] ?? ''));
          if (!$linked_addon_sku || !isset($sku_renames[$linked_addon_sku])) continue;
          $products[$saved_sku]['fundamentals_addon_sku'] = $this->sanitize_sku($sku_renames[$linked_addon_sku]);
        }
      }

      $this->save_products($products);
      add_settings_error('mrm_pay_hub', 'products_saved', 'Products saved.', 'updated');
    }
  }

  private function render_products_ui() {
    $products = $this->all_products();
