                      <th>Payment Intent ID</th>
                      <th>Activation Status</th>
                      <th>Last Activation Error</th>
                      <th>Updated</th>
                    </tr>
                  </thead>
                  <tbody>
                  <?php if (empty($rows)) : ?>
                    <tr><td colspan="11">No sheet music subscriptions found.</td></tr>
                  <?php else : ?>
                    <?php foreach ($rows as $row) :
                      $is_active = $this->mrm_is_sheet_music_subscription_active_for_admin($row);
                      $end_date = $this->mrm_sheet_music_subscription_end_date_for_admin($row);
                    ?>
                      <tr>
                        <td><?php echo esc_html((string)$row['email_plain']); ?></td>
                        <td style="text-align:center;"><?php echo $is_active ? '✔' : ''; ?></td>
                        <td><?php echo esc_html($end_date); ?></td>
                        <td><?php echo esc_html((string)$row['stripe_status']); ?></td>
                        <td>
                          <?php
                          $tax_attention_status = sanitize_key($row['tax_attention_status'] ?? 'clear');
                          if (!empty($row['collection_paused_for_tax'])) {
                            echo '<strong style="color:#b32d2e;">Billing paused</strong>';
                            if (!empty($row['tax_attention_reason'])) {
                              echo '<br><small>' . esc_html($row['tax_attention_reason']) . '</small>';
                            }
                          } else {
                            echo esc_html($tax_attention_status ?: 'clear');
                          }
                          ?>
                        </td>
                        <td><?php echo esc_html((string)($row['order_id'] ?? '')); ?></td>
                        <td><?php echo esc_html((string)($row['payment_intent_id'] ?? '')); ?></td>
                        <td><?php echo esc_html((string)($row['activation_status'] ?? '')); ?></td>
                        <td><?php echo esc_html((string)($row['last_activation_error'] ?? '')); ?></td>
                        <td><?php echo esc_html((string)$row['updated_at']); ?></td>
                      </tr>
                    <?php endforeach; ?>
                  <?php endif; ?>
                  </tbody>
                </table>
              <?php endif; ?>
            <?php endif; ?>
            <p>
              <label>
                <input type="checkbox" name="delete[<?php echo esc_attr($current_index); ?>]" value="1" />
                Delete
              </label>
            </p>
          </div>
        <?php endforeach; ?>

        <?php $new_index = $index; ?>
        <div class="card" style="padding:16px;border:1px dashed #ccd0d4;">
          <h3 style="margin-top:0;">Add New Product</h3>
          <p>
            SKU will be generated automatically based on the label and type.
          </p>
          <p>
            <label>SKU<br />
              <input type="text" class="regular-text mrm-sku-display" value="" disabled />
              <input type="hidden" name="sku[<?php echo esc_attr($new_index); ?>]" value="" />
              <input type="hidden" name="original_sku[<?php echo esc_attr($new_index); ?>]" value="" />
            </label>
          </p>
          <p>
            <label>Label<br />
              <input type="text" name="label[<?php echo esc_attr($new_index); ?>]" value="" class="regular-text" />
            </label>
          </p>
          <p>
            <label>Amount (cents)<br />
              <input type="number" name="amount_cents[<?php echo esc_attr($new_index); ?>]" value="" class="small-text" />
            </label>
          </p>
          <p>
            <label>Currency<br />
              <select name="currency[<?php echo esc_attr($new_index); ?>]">
                <?php foreach ($currency_options as $value => $label) : ?>
                  <option value="<?php echo esc_attr($value); ?>"><?php echo esc_html($label); ?></option>
                <?php endforeach; ?>
              </select>
            </label>
          </p>
          <p>
            <label>Product Type<br />
              <select name="product_type[<?php echo esc_attr($new_index); ?>]" class="mrm-product-type">
                <?php foreach ($type_options as $value => $label) : ?>
                  <option value="<?php echo esc_attr($value); ?>"><?php echo esc_html($label); ?></option>
                <?php endforeach; ?>
              </select>
            </label>
          </p>
          <p>
            <label>Category<br />
              <select name="category[<?php echo esc_attr($new_index); ?>]" class="mrm-product-category">
                <?php foreach ($lesson_categories as $value => $label) : ?>
                  <option value="<?php echo esc_attr($value); ?>"><?php echo esc_html($label); ?></option>
                <?php endforeach; ?>
              </select>
            </label>
          </p>
          <div class="mrm-fundamentals-addon-settings" style="display:none;padding:14px;margin:14px 0;border:1px solid #dcdcde;border-radius:8px;background:#f6f7f7;">
            <p><strong>Fundamental Packet Add-On</strong></p><p><label><input type="checkbox" name="fundamentals_addon_enabled[<?php echo esc_attr($new_index); ?>]" value="1" /> Offer the matching Fundamental Packet with this Full Piece</label></p>
            <p><select name="fundamentals_addon_sku[<?php echo esc_attr($new_index); ?>]"><option value="">Select a Fundamental Packet</option><?php foreach($fundamentals_products as $fs=>$fl): ?><option value="<?php echo esc_attr($fs); ?>"><?php echo esc_html($fl.' — '.$fs); ?></option><?php endforeach; ?></select></p>
            <p><input type="number" min="1" name="fundamentals_addon_amount_cents[<?php echo esc_attr($new_index); ?>]" value="500" /></p>
          </div>
          <input type="hidden" name="delete[<?php echo esc_attr($new_index); ?>]" value="0" />
        </div>
      </div>
      <p class="submit">
        <button type="submit" class="button button-primary">Save Products</button>
      </p>
    </form>
    <script>
      (function() {
        var lessonCategories = <?php echo wp_json_encode($lesson_categories); ?>;
        var sheetCategories = <?php echo wp_json_encode($sheet_categories); ?>;
        function updateFundamentalsAddOnSettings(card) {
          if(!card) return; var type=card.querySelector('.mrm-product-type'), category=card.querySelector('.mrm-product-category'), settings=card.querySelector('.mrm-fundamentals-addon-settings');
          if(type&&category&&settings) settings.style.display=type.value==='sheet_music'&&(category.value==='tuba'||category.value==='trombone-euphonium')?'':'none';
        }
        function updateCategory(select) {
          var card = select.closest('.card');
          if (!card) return;
          var categorySelect = card.querySelector('.mrm-product-category');
          if (!categorySelect) return;
          var type = select.value;
          var options = type === 'sheet_music' ? sheetCategories : lessonCategories;
          var current = categorySelect.value;
          categorySelect.innerHTML = '';
          Object.keys(options).forEach(function(value) {
            var opt = document.createElement('option');
            opt.value = value;
            opt.textContent = options[value];
            if (value === current) opt.selected = true;
            categorySelect.appendChild(opt);
          });
          if (!categorySelect.value) {
            var keys = Object.keys(options);
            if (keys.length) categorySelect.value = keys[0];
          }
          updateFundamentalsAddOnSettings(card);
        }
        function slugify(s) {
          var text = String(s || '').trim().toLowerCase();
          text = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
          text = text.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
          return text || 'untitled';
        }
        function updateSku(card) {
          var labelInput = card.querySelector('input[name^="label"]');
          var typeSelect = card.querySelector('select[name^="product_type"]');
          var catSelect = card.querySelector('select[name^="category"]');
          var skuInput = card.querySelector('input[name^="sku"]');
          var skuDisplay = card.querySelector('.mrm-sku-display');
          if (!labelInput || !typeSelect || !catSelect || !skuInput) return;
          var labelSlug = slugify(labelInput.value);
          var type = typeSelect.value;
          var category = catSelect.value;
          var sku;
          if (type === 'sheet_music') {
            sku = 'piece-' + labelSlug + '-' + category;
          } else {
            sku = 'lesson_' + category;
          }
          skuInput.value = sku;
          if (skuDisplay) skuDisplay.value = sku;
          updateFundamentalsAddOnSettings(card);
        }
        document.querySelectorAll('.mrm-product-type').forEach(function(select) {
          select.addEventListener('change', function() {
            updateCategory(select);
            updateSku(select.closest('.card'));
          });
          updateCategory(select);
        });
        document.querySelectorAll('.mrm-products-grid .card').forEach(function(card) {
          ['input', 'change'].forEach(function(evt) {
            card.addEventListener(evt, function() {
              updateSku(card);
            });
          });
          updateSku(card);
        });
      })();
    </script>
    <?php
    return ob_get_clean();
  }


  public function create_instructor_performance_tax_location($instructor_id) {
    global $wpdb; $instructor_id = absint($instructor_id);
    if ($instructor_id <= 0) return new WP_Error('invalid_instructor', 'Invalid instructor ID.');
    $table = $wpdb->prefix . 'mrm_instructors';
    $instructor = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $instructor_id), ARRAY_A);
    if (!$instructor) return new WP_Error('instructor_not_found', 'Instructor not found.');
    if (empty($instructor['offers_in_person'])) return new WP_Error('in_person_not_enabled', 'This instructor does not offer in-person lessons.');
    foreach (array('address','city','state','zip_code') as $field) if (trim((string)($instructor[$field] ?? '')) === '') return new WP_Error('location_address_incomplete', 'The instructor address is incomplete.');
    $location = $this->stripe_api_request('POST', '/v1/tax/locations', array('type'=>'performance','address[line1]'=>(string)$instructor['address'],'address[city]'=>(string)$instructor['city'],'address[state]'=>(string)$instructor['state'],'address[postal_code]'=>(string)$instructor['zip_code'],'address[country]'=>'US','description'=>'Low Brass Lessons in-person lesson location for ' . sanitize_text_field($instructor['name'])), $this->mrm_stripe_tax_location_headers());
    if (is_wp_error($location)) return $location;
    $location_id = sanitize_text_field($location['id'] ?? '');
    if (strpos($location_id, 'taxloc_') !== 0) return new WP_Error('invalid_tax_location_response', 'Stripe did not return a valid Tax Location ID.');
    $updated = $wpdb->update($table, array('stripe_tax_location_id'=>$location_id), array('id'=>$instructor_id));
    if ($updated === false) return new WP_Error('tax_location_save_failed', $wpdb->last_error);
    return $location;
  }


  public function create_external_taxed_payment_intent($args) {
    $exemption_check = $this->mrm_tax_reject_unsupported_exemption_claim($args);
    if (is_wp_error($exemption_check)) return $exemption_check;
    $readiness = $this->mrm_tax_live_checkout_readiness();
    if (is_wp_error($readiness)) { $this->stripe_debug_log('External taxed checkout blocked.', array('code'=>$readiness->get_error_code(),'message'=>$readiness->get_error_message())); return new WP_Error('tax_configuration_not_ready', 'Payments are temporarily unavailable while our tax configuration is being updated.'); }
    $args = wp_parse_args($args, array('amount_cents'=>0,'currency'=>'usd','tax_code'=>'','reference'=>'','threshold_category'=>'other','address'=>array(),'metadata'=>array(),'description'=>'','receipt_email'=>''));
    $amount = absint($args['amount_cents']);
    $tax_code = sanitize_text_field($args['tax_code']);
    if ($amount <= 0 || $tax_code === '') return new WP_Error('external_tax_item_invalid','The checkout amount or tax code is invalid.');
    $tax = $this->mrm_tax_calculate_for_items($args['address'], array(array('amount_cents'=>$amount,'reference'=>sanitize_key($args['reference'] ?: 'external_item'),'tax_code'=>$tax_code,'threshold_category'=>sanitize_key($args['threshold_category']))), $args['currency']);
    if (is_wp_error($tax)) return $tax;
    $metadata = is_array($args['metadata']) ? $args['metadata'] : array();
    $metadata['mrm_subtotal_cents'] = (string)$tax['subtotal_cents'];
    $metadata['mrm_tax_cents'] = (string)$tax['tax_cents'];
    $metadata['mrm_total_cents'] = (string)$tax['amount_total_cents'];
    $metadata['mrm_tax_calculation_id'] = $tax['calculation_id'];
    $metadata['mrm_taxability_reason'] = $tax['taxability_reason'];
    $metadata['mrm_tax_code'] = $tax_code;
    $metadata['mrm_threshold_category'] = sanitize_key($args['threshold_category']);
    $metadata['mrm_customer_state'] = $this->mrm_normalize_state_code($args['address']['state'] ?? '');
    $metadata['mrm_customer_country'] = strtoupper(sanitize_text_field($args['address']['country'] ?? 'US'));
    $metadata['mrm_tax_lines_json'] = (string)($tax['metadata_line_items_json'] ?? '[]');
    $extra = array();
    if (is_email($args['receipt_email'])) $extra['receipt_email'] = sanitize_email($args['receipt_email']);
    $intent = $this->stripe_create_payment_intent($tax['amount_total_cents'], $args['currency'], $metadata, $args['description'], $extra, array('card'), $tax['calculation_id']);
    if (is_wp_error($intent)) return $intent;
    return array('payment_intent'=>$intent,'subtotal_cents'=>$tax['subtotal_cents'],'tax_cents'=>$tax['tax_cents'],'amount_total_cents'=>$tax['amount_total_cents'],'calculation_id'=>$tax['calculation_id'],'taxability_reason'=>$tax['taxability_reason']);
  }

}

global $mrm_pay_hub_singleton;
$mrm_pay_hub_singleton = new MRM_Payments_Hub_Single();

function mrm_pay_hub_singleton() {
  global $mrm_pay_hub_singleton;
  return $mrm_pay_hub_singleton instanceof MRM_Payments_Hub_Single ? $mrm_pay_hub_singleton : null;
}



function mrm_payments_hub_sync_tax_ledger_for_payment_intent($payment_intent_id) {
  $hub = mrm_pay_hub_singleton();
  if (!$hub || !method_exists($hub, 'sync_external_payment_intent_tax_ledger')) return new WP_Error('payments_hub_tax_sync_unavailable', 'The shared tax-ledger service is unavailable.');
  return $hub->sync_external_payment_intent_tax_ledger($payment_intent_id);
}

function mrm_payments_hub_flag_physical_nexus($args) { $hub = mrm_pay_hub_singleton(); if (!$hub || !method_exists($hub, 'register_external_physical_nexus_source')) return new WP_Error('physical_nexus_service_unavailable', 'The shared physical-nexus service is unavailable.'); return $hub->register_external_physical_nexus_source($args); }

function mrm_payments_hub_create_instructor_tax_location($instructor_id) {
  $hub = mrm_pay_hub_singleton();
  if (!$hub || !method_exists($hub, 'create_instructor_performance_tax_location')) return new WP_Error('tax_location_service_unavailable', 'The Stripe Tax Location service is unavailable.');
  return $hub->create_instructor_performance_tax_location($instructor_id);
}

function mrm_payments_hub_create_taxed_payment_intent($args) {
  $hub = mrm_pay_hub_singleton();
  if (!$hub || !method_exists($hub, 'create_external_taxed_payment_intent')) {
    return new WP_Error('payments_hub_tax_unavailable','The shared tax service is unavailable.');
  }
  return $hub->create_external_taxed_payment_intent($args);
}

